def _expand_cfg_path(v):
    """Config values may use  %VAR%  ~  {DWB} (this DeveloperWorkBench folder)  {DWB_HOME} (the DWB folder next to it)."""
    v = str(v or "").strip()
    if not v:
        return v
    v = v.replace("{DWB_HOME}", str(WORKFLOWS_ROOT.parent)).replace("{DWB}", str(WORKFLOWS_ROOT))
    return os.path.expanduser(os.path.expandvars(v))


def _bootstrap_environment():
    """Make the server independent of the shell that started it.

    Started from the desktop shortcut / Start Menu (not from a developer's Git Bash), the process only has Explorer's
    environment: GIT_HOME / REPO_PAYOR and variables changed since login are missing, so the Payor clone, its branches
    and its modules could not be found. Fill in what is missing, never overriding what is set:
      1. User + machine environment variables from the registry (also picks up changes made after login, e.g. by setbranch)
      2. GIT_HOME  <- Setup > Project Directory (setup_config.xlsx), else ~/hebb
      3. REPO_PAYOR default
    """
    if sys.platform != "win32":
        return
    try:
        import winreg
        merged = {}
        for hive, sub in ((winreg.HKEY_LOCAL_MACHINE, r"SYSTEM\CurrentControlSet\Control\Session Manager\Environment"),
                          (winreg.HKEY_CURRENT_USER, "Environment")):
            try:
                with winreg.OpenKey(hive, sub) as k:
                    i = 0
                    while True:
                        try:
                            name, val, typ = winreg.EnumValue(k, i)
                        except OSError:
                            break
                        i += 1
                        if isinstance(val, str):
                            merged[name.upper()] = (name, os.path.expandvars(val) if typ == winreg.REG_EXPAND_SZ else val)
            except OSError:
                pass
        # PATH: keep the current one, append registry entries that are missing (a shortcut-launched process can have a stale PATH)
        reg_path = merged.pop("PATH", (None, ""))[1]
        cur = os.environ.get("PATH", "")
        have = {p.strip().rstrip("\\").lower() for p in cur.split(";") if p.strip()}
        extra = [p for p in reg_path.split(";") if p.strip() and p.strip().rstrip("\\").lower() not in have]
        if extra:
            os.environ["PATH"] = cur.rstrip(";") + ";" + ";".join(extra)
        for key, (name, val) in merged.items():
            if key not in os.environ and val:
                os.environ[name] = val
    except Exception:
        pass

    try:
        if not os.environ.get("GIT_HOME", "").strip():
            gh = ""
            cfg = SETUP_ROOT / "setup_config.xlsx"
            if cfg.exists():
                import openpyxl as _xl_env
                wb = _xl_env.load_workbook(str(cfg), read_only=True, data_only=True)
                if "project_directory" in wb.sheetnames:
                    for row in wb["project_directory"].iter_rows(values_only=True):
                        if row and row[0] and len(row) > 1 and row[1]:
                            gh = str(row[1]).strip()
                            break
                wb.close()
            if not gh and (Path.home() / "hebb").is_dir():
                gh = str(Path.home() / "hebb")
            if gh:
                os.environ["GIT_HOME"] = gh
        os.environ.setdefault("REPO_PAYOR", "hrp.payer.core")
    except Exception:
        pass


