def _gp_app_slug(app_name):
    return app_name.lower().replace(" ", "_").replace("-", "_")

def _gp_params_path(app_name):
    return GP_ROOT / "gp_params" / f"{_gp_app_slug(app_name)}_gp_params.xlsx"

def _gp_job_url(app_name):
    import openpyxl as _xl, zipfile as _zf
    cfg_path = GP_ROOT / "gp_job_config.xlsx"
    if not cfg_path.exists():
        return ""
    try:
        cw = _xl.load_workbook(str(cfg_path))
    except (_zf.BadZipFile, Exception):
        return ""
    if "Settings" not in cw.sheetnames:
        return ""
    ws = cw["Settings"]
    hdrs = [str(c.value or "").strip().lower() for c in ws[1]]
    for row in ws.iter_rows(min_row=2, values_only=True):
        if any(v is not None for v in row):
            d = {k: str(v or "").strip() for k, v in zip(hdrs, row)}
            if d.get("application", "").lower() == app_name.lower():
                return d.get("url", "").rstrip("/")
    return ""

