import re as _re_team


_MVN_VERSION_TAIL = _re_team.compile(r"^\d[\w.\-]*$")
_MVN_RF_HINT      = _re_team.compile(r"-rf\s+:(\S+)")


def _mvn_artifact_id(raw):
    """Turn the text Maven prints after '[INFO] Building' into a usable `-rf :<artifactId>` value.

    Maven prints '<name> <version>' where <name> is the POM <name>, not the artifactId, e.g.
    'Connector MedicareHICN:: connector-medicarehicn-schema-bundle 27.1-SNAPSHOT'.
    The artifactId is the last token after the '::' separator; names without one are returned as-is.
    """
    s = (raw or "").strip()
    parts = s.split()
    if len(parts) > 1 and _MVN_VERSION_TAIL.match(parts[-1]):
        parts = parts[:-1]
    s = " ".join(parts)
    if "::" in s:
        s = s.rsplit("::", 1)[1].strip().split()[-1]
    return s

def _team_from_sprint_filename(filename):
    m = _re_team.match(r'^(.+?)_\d{4}-\d{2}-\d{2}_', filename)
    return m.group(1) if m else ""

def _sprint_team_path(filename):
    team = _team_from_sprint_filename(filename)
    if team:
        p = SPRINT_DATA / "Sprints" / team / filename
        if p.exists():
            return p
        p_prev = SPRINT_DATA / "PreviousSprints" / team / filename
        if p_prev.exists():
            return p_prev
        return p
    p = SPRINTS_DIR / filename
    if p.exists():
        return p
    p_prev = SPRINT_DATA / "PreviousSprints" / filename
    if p_prev.exists():
        return p_prev
    return p

def _sprint_sidecar_path(filename):
    stem = filename[:-5] if filename.endswith('.xlsx') else filename
    team = _team_from_sprint_filename(filename)
    if team:
        return SPRINT_DATA / "Sprints" / team / f"{stem}.json"
    return SPRINTS_DIR / f"{stem}.json"

def _find_project_path(jira_id, team=None):
    projects_root = SPRINT_DATA / "Projects"
    if team:
        return projects_root / team / f"{jira_id}.xlsx"
    for p in projects_root.glob(f"*/{jira_id}.xlsx"):
        return p
    return projects_root / f"{jira_id}.xlsx"

