def _list_payor_modules(srcdir, overrides=None):
    """Return {"ready": [{name, jar}], "needs_build": [{name}]} by scanning srcdir.

    overrides: optional dict {module_name: {"target_artifact_name": "specific.jar", ...}}
    When target_artifact_name is set for a module, only that exact file is checked
    in the module's target/ directory to determine build status.
    """
    import os as _os
    p = Path(srcdir)
    if not p.exists():
        return {"ready": [], "needs_build": [], "error": f"Not found: {srcdir}"}
    overrides = overrides or {}
    ready, needs_build = [], []
    for name in sorted(_os.listdir(str(p))):
        mod = p / name
        if not mod.is_dir() or not (mod / "pom.xml").exists():
            continue
        target = mod / "target"
        artifact = None
        specific = (overrides.get(name) or {}).get("target_artifact_name", "").strip()
        if specific:
            # Check for the exact configured artifact in target/
            if target.exists() and (target / specific).is_file():
                artifact = specific
        elif target.exists():
            try:
                # Check .war first (takes priority — WAR means it's a web app, always deployable)
                for f in target.iterdir():
                    if (f.suffix == ".war"
                            and (f.name.startswith(name + "-") or f.stem == name)):
                        artifact = f.name
                        break
                # Fall back to .jar if no .war found
                if not artifact:
                    for f in target.iterdir():
                        if (f.suffix == ".jar"
                                and "-sources" not in f.name and "-tests" not in f.name
                                and (f.name.startswith(name + "-") or f.stem == name)):
                            artifact = f.name
                            break
            except Exception:
                pass
        if artifact:
            ready.append({"name": name, "jar": artifact})
        else:
            needs_build.append({"name": name})
    return {"ready": ready, "needs_build": needs_build}


def _get_module_dependents(srcdir, module_name):
    """Return sorted list of modules that transitively depend on module_name."""
    import re as _re
    p = Path(srcdir)
    INTRA = _re.compile(r"com\.healthedge\.core|\$\{project\.groupId\}")
    reverse = {}  # module → set of modules that depend on it
    try:
        for entry in p.iterdir():
            if not entry.is_dir() or not (entry / "pom.xml").exists():
                continue
            name = entry.name
            reverse.setdefault(name, set())
            text = (entry / "pom.xml").read_text(errors="replace")
            for block in _re.findall(r"<dependency>(.*?)</dependency>", text, _re.DOTALL):
                groups    = _re.findall(r"<groupId>([^<]+)</groupId>", block)
                artifacts = _re.findall(r"<artifactId>([^<]+)</artifactId>", block)
                if any(INTRA.search(g) for g in groups) and artifacts:
                    dep = artifacts[0]
                    reverse.setdefault(dep, set())
                    reverse[dep].add(name)
    except Exception:
        pass
    visited, queue = {module_name}, [module_name]
    while queue:
        cur = queue.pop(0)
        for dep in reverse.get(cur, set()):
            if dep not in visited:
                visited.add(dep); queue.append(dep)
    visited.discard(module_name)
    return sorted(visited)


_PHASE2_FLAGS = {"-sdu"}   # flags that belong to the post-build phase


def _split_params_keys(flags):
    """Split flags into (phase1_key, phase2_key) for separate stats tracking."""
    p1 = [f for f in (flags or []) if f not in _PHASE2_FLAGS]
    p2 = [f for f in (flags or []) if f in _PHASE2_FLAGS]
    return _build_params_key(p1), _build_params_key(p2)


def _build_params_key(flags):
    """Canonical sorted string for a set of build flags."""
    return " ".join(sorted(str(f) for f in flags)) if flags else "(none)"


def _get_build_estimate(module, params_key):
    """Return median duration_ms of last ≤10 successful builds for (module, params_key), or None."""
    if not BUILD_STATS_FILE.exists():
        return None
    with _build_stats_lock:
        try:
            import openpyxl as _xl
            wb   = _xl.load_workbook(str(BUILD_STATS_FILE))
            ws   = wb.active
            hdrs = [str(ws.cell(1, c).value or "").strip().lower() for c in range(1, ws.max_column + 1)]
            durations = []
            for row in ws.iter_rows(min_row=2, values_only=True):
                d = {k: ("" if v is None else str(v)) for k, v in zip(hdrs, row)}
                if (d.get("module") == module and d.get("parameters") == params_key
                        and d.get("build_status") == "success"):
                    try:
                        durations.append(int(d["duration_ms"]))
                    except (ValueError, KeyError):
                        pass
            durations = durations[-10:]
            if not durations:
                return None
            s = sorted(durations)
            n = len(s)
            return s[n // 2] if n % 2 else (s[n // 2 - 1] + s[n // 2]) // 2
        except Exception:
            return None


def _save_build_stats(module, params_key, duration_ms, status):
    """Append one build-stat row; keep ≤10 entries per (module, params_key) combo."""
    from datetime import datetime as _dt
    with _build_stats_lock:
        try:
            import openpyxl as _xl
            from openpyxl.styles import Font, PatternFill
            BUILD_STATS_DIR.mkdir(parents=True, exist_ok=True)
            HDRS   = ["id", "timestamp", "module", "parameters", "duration_ms", "build_status"]
            WIDTHS = [8, 22, 30, 40, 14, 14]
            if not BUILD_STATS_FILE.exists():
                wb = _xl.Workbook()
                ws = wb.active
                ws.title = "Build Stats"
                hf = Font(bold=True, color="FFFFFF", name="Calibri")
                hb = PatternFill("solid", fgColor="1F3864")
                for i, (h, w) in enumerate(zip(HDRS, WIDTHS), 1):
                    c = ws.cell(1, i, h); c.font = hf; c.fill = hb
                    ws.column_dimensions[c.column_letter].width = w
            else:
                wb = _xl.load_workbook(str(BUILD_STATS_FILE))
                ws = wb.active
            hdrs    = [str(ws.cell(1, c).value or "").strip().lower() for c in range(1, ws.max_column + 1)]
            col     = {h: i for i, h in enumerate(hdrs, 1)}
            max_id  = max((int(ws.cell(r, 1).value or 0) for r in range(2, ws.max_row + 1)
                           if ws.cell(r, 1).value is not None), default=0)
            ws.append([max_id + 1, _dt.now().strftime("%Y-%m-%d %H:%M:%S"),
                       module, params_key, duration_ms, status])
            wb.save(str(BUILD_STATS_FILE))
            # Trim oldest entry per combo only after a successful build and only if count exceeds 10
            if status == "success":
                wb2 = _xl.load_workbook(str(BUILD_STATS_FILE))
                ws2 = wb2.active
                combo_rows = [r for r in range(2, ws2.max_row + 1)
                              if (str(ws2.cell(r, col.get("module", 3)).value or "") == module
                                  and str(ws2.cell(r, col.get("parameters", 4)).value or "") == params_key)]
                if len(combo_rows) > 10:
                    for r in sorted(combo_rows[:-10], reverse=True):
                        ws2.delete_rows(r)
                    wb2.save(str(BUILD_STATS_FILE))
        except Exception:
            pass


# ── Detached build jobs ──────────────────────────────────────────────────────────────────────────
# Builds / deploys run as detached processes writing to a log file, so restarting the Workbench never kills them.
# _DetachedProc looks like the Popen the build loops already use (stdout.readline / wait / returncode / pid / kill),
# but reads the log file; only the Abort endpoints kill the process tree.
_DET_DIR = Path(os.environ.get("DWB_RUN_STATE") or (Path(__file__).resolve().parent.parent / "run_logs"))
_DET_LAUNCHER = ("import subprocess,sys;"
                 "rc=subprocess.call(sys.argv[2:],stdin=subprocess.DEVNULL,stdout=sys.stdout,stderr=sys.stdout,creationflags=0x08000000);"
                 "open(sys.argv[1],'w').write(str(rc))")


def _pid_alive(pid):
    if not pid:
        return False
    try:
        if sys.platform == "win32":
            import ctypes as _ct               # direct API call: spawning tasklist per job made every start take over a minute
            from ctypes import wintypes as _wt
            k32 = _ct.windll.kernel32
            k32.OpenProcess.restype = _wt.HANDLE
            k32.OpenProcess.argtypes = [_wt.DWORD, _wt.BOOL, _wt.DWORD]
            k32.GetExitCodeProcess.argtypes = [_wt.HANDLE, _ct.POINTER(_wt.DWORD)]
            k32.CloseHandle.argtypes = [_wt.HANDLE]
            h = k32.OpenProcess(0x1000, False, int(pid))            # PROCESS_QUERY_LIMITED_INFORMATION
            if not h:
                return False
            code = _wt.DWORD()
            ok = k32.GetExitCodeProcess(h, _ct.byref(code))
            k32.CloseHandle(h)
            return bool(ok) and code.value == 259                    # STILL_ACTIVE
        os.kill(int(pid), 0)
        return True
    except Exception:
        return False


class _DetachedProc:
    def __init__(self, pid, log, code, offset=0):
        self.pid, self.log, self.code = pid, Path(log), Path(code)
        self._pos = offset
        self._buf = ""
        import collections as _co
        self._lines = _co.deque()
        self.returncode = None
        self.stdout = self

    def _rc(self):
        try:
            return int(self.code.read_text().strip())
        except Exception:
            return None

    def poll(self):
        rc = self._rc()
        if rc is None and not _pid_alive(self.pid):
            rc = self._rc()
            if rc is None:
                rc = -1                      # killed (abort) or died without recording an exit code
        if rc is not None:
            self.returncode = rc
        return self.returncode

    def _read_more(self):
        try:
            with open(self.log, "rb") as f:
                f.seek(self._pos)
                data = f.read()
            self._pos += len(data)
            if data:
                parts = (self._buf + data.decode("utf-8", errors="replace")).split("\n")   # split once; never re-split a big buffer per line
                self._buf = parts.pop()                                                      # the unfinished last line
                self._lines.extend(p.rstrip("\r") + "\n" for p in parts)
        except OSError:
            pass

    def readline(self):
        import time as _t
        while True:
            if self._lines:
                return self._lines.popleft()
            self._read_more()
            if self._lines:
                continue
            if self.poll() is not None:        # finished: drain what is left, then EOF
                self._read_more()
                if self._lines:
                    continue
                rest, self._buf = self._buf, ""
                return rest
            _t.sleep(0.3)

    def wait(self, timeout=None):
        import time as _t
        end = _t.time() + timeout if timeout else None
        while self.poll() is None:
            if end and _t.time() > end:
                raise subprocess.TimeoutExpired("detached", timeout)
            _t.sleep(0.3)
        return self.returncode

    def kill(self):
        try:
            subprocess.run(["taskkill", "/F", "/T", "/PID", str(self.pid)], capture_output=True, creationflags=0x08000000)
        except Exception:
            pass


def _detached_popen(kind, argv, cwd=None, env=None, meta=None):
    """Start argv detached; returns a _DetachedProc. Job info is saved so a restarted Workbench can re-attach (_adopt_detached_jobs)."""
    import json as _j, time as _t, uuid as _u
    _DET_DIR.mkdir(parents=True, exist_ok=True)
    jid = f"{kind}_{_t.strftime('%Y%m%d_%H%M%S')}_{_u.uuid4().hex[:4]}"
    log, code, info = _DET_DIR / f"{jid}.log", _DET_DIR / f"{jid}.code", _DET_DIR / f"{jid}.json"
    flags = 0
    if sys.platform == "win32":
        flags = 0x00000008 | 0x00000200            # DETACHED_PROCESS | CREATE_NEW_PROCESS_GROUP
    with open(log, "wb") as lf:
        p = subprocess.Popen([sys.executable, "-c", _DET_LAUNCHER, str(code)] + [str(a) for a in argv],
                             cwd=cwd, env=env, stdin=subprocess.DEVNULL, stdout=lf, stderr=subprocess.STDOUT, creationflags=flags)
    info.write_text(_j.dumps({"kind": kind, "pid": p.pid, "log": str(log), "code": str(code), "started": _t.time(), "meta": meta or {}}), encoding="utf-8")
    return _DetachedProc(p.pid, log, code)


def _prune_detached_logs(keep=30):
    try:
        files = sorted(_DET_DIR.glob("*.json"), key=lambda f: f.stat().st_mtime, reverse=True)
        for f in files[keep:]:
            for ext in (".json", ".log", ".code"):
                f.with_suffix(ext).unlink(missing_ok=True)
    except Exception:
        pass


def _tomcat_mgr_env(app_root):
    """Environment for deploy_jar.js with tomcat_manager_user/pass/port from the Deploy sheet of build_deploy_config.xlsx."""
    import os as _os
    env = dict(_os.environ)
    try:
        import openpyxl as _xl
        xlsx = Path(app_root) / "build_deploy_config.xlsx"
        if xlsx.exists():
            wb = _xl.load_workbook(str(xlsx), data_only=True)
            wsn = next((s for s in wb.sheetnames if s.lower() == "deploy"), None)
            if wsn:
                names = {"tomcat_manager_user": "DWB_TOMCAT_MGR_USER", "tomcat_manager_pass": "DWB_TOMCAT_MGR_PASS",
                         "tomcat_manager_port": "DWB_TOMCAT_MGR_PORT"}
                for row in wb[wsn].iter_rows(min_row=2, values_only=True):
                    if row and row[0] and str(row[0]).strip() in names and row[1] is not None and str(row[1]).strip():
                        env.setdefault(names[str(row[0]).strip()] + "_CFG", str(row[1]).strip())
                for k, v in list(env.items()):
                    if k.endswith("_CFG"):
                        env[k[:-4]] = v
                        del env[k]
    except Exception:
        pass
    return env


def _run_module_op(op, module, payor_root, extra_args):
    """Run build_module.js or deploy_jar.js, streaming output into _module_op."""
    import subprocess as _sub, time as _time
    script = "build_module.js" if op == "build" else "deploy_jar.js"
    args   = [module] + extra_args if op == "build" else [module]
    cmd    = ["node", f"scripts/{script}"] + args
    with _module_op_lock:
        _module_op["output"] += f"$ {' '.join(cmd)}\n\n"
    start_ms = int(_time.time() * 1000)
    params_key = _build_params_key(extra_args) if op == "build" else "(none)"
    final_status = "failed"
    try:
        proc = _detached_popen("module_op", cmd, cwd=str(payor_root), env=_tomcat_mgr_env(payor_root), meta={"op": op, "module": module})   # survives a Workbench restart
        with _module_op_lock:
            _module_op["proc"] = proc
        for line in iter(proc.stdout.readline, ""):
            with _module_op_lock:
                _module_op["output"] += line
        proc.wait()
        with _module_op_lock:
            _module_op["proc"] = None
            final_status = "aborted" if _module_op["status"] == "aborted" else ("success" if proc.returncode == 0 else "failed")
            _module_op["status"] = final_status
    except Exception as e:
        with _module_op_lock:
            _module_op["status"] = "failed"
            _module_op["output"] += f"\n[ERROR] {e}\n"
    if op == "build":
        _save_build_stats(module, params_key, int(_time.time() * 1000) - start_ms, final_status)


