def _get_jbaseline_jobs(app="Payor"):
    """Return enabled job names from JBaseline's baseline_job_config.xlsx for the given app."""
    import openpyxl as _xl_jbj
    cfg = JB_ROOT / "baseline_job_config.xlsx"
    if not cfg.exists():
        return []
    try:
        wb = _xl_jbj.load_workbook(str(cfg), read_only=True, data_only=True)
        sheet = next((s for s in wb.sheetnames if s.lower() == app.lower()), None)
        if not sheet:
            wb.close()
            return []
        ws = wb[sheet]
        hdrs = [str(ws.cell(1, c).value or "").strip().lower()
                for c in range(1, ws.max_column + 1)]
        jobs = []
        for row in ws.iter_rows(min_row=2, values_only=True):
            if not row[0]:
                continue
            d = {k: str(v or "").strip() for k, v in zip(hdrs, row)}
            if d.get("enabled", "1") not in ("0", "false", "no"):
                jobs.append(d.get("job_name", str(row[0]).strip()))
        wb.close()
        return jobs
    except Exception:
        return []


