def create_flask_app():
    try:
        from flask import Flask, jsonify, request, send_from_directory, send_file, redirect
    except ImportError:
        print(f"\n  ERROR: Flask is not installed.")
        print(f"  Run  {bold('setupcloneworkflowtool')}  to install all dependencies.\n")
        sys.exit(1)

    app = Flask(__name__, static_folder=None)

    @app.before_request
    def _options():
        from flask import request as req, make_response
        if req.method == "OPTIONS":
            r = make_response("", 204)
            r.headers["Access-Control-Allow-Origin"]  = "*"
            r.headers["Access-Control-Allow-Headers"] = "Content-Type"
            r.headers["Access-Control-Allow-Methods"] = "GET,POST,PATCH,DELETE,OPTIONS"
            return r

    @app.after_request
    def _cors(r):
        r.headers["Access-Control-Allow-Origin"]  = "*"
        r.headers["Access-Control-Allow-Headers"] = "Content-Type"
        r.headers["Access-Control-Allow-Methods"] = "GET,POST,PATCH,DELETE,OPTIONS"
        return r

    @app.route("/api/stages")
    def api_stages():
        return jsonify(ALL_STAGES)

    @app.route("/api/clone-workflow/poll-interval", methods=["GET"])
    def api_cw_poll_interval_get():
        return jsonify({"ok": True, "poll_interval_s": _cw_read_poll_interval()})

    @app.route("/api/clone-workflow/poll-interval", methods=["POST"])
    def api_cw_poll_interval_set():
        data       = request.get_json() or {}
        refresh_ms = int(data.get("refresh_ms") or 0)
        poll_s     = max(60, refresh_ms // 1000) if refresh_ms > 0 else 600
        _cw_write_poll_interval(poll_s)
        return jsonify({"ok": True, "poll_interval_s": poll_s})

    @app.route("/api/clone-workflow/jira-base-url", methods=["GET"])
    def api_cw_jira_base_url():
        jira_base = ""
        try:
            import openpyxl as _xl_jb
            _sb = WORKFLOWS_ROOT / "secrets.xlsx"
            if _sb.exists():
                _wb_jb = _xl_jb.load_workbook(str(_sb), read_only=True, data_only=True)
                for _sht in _wb_jb.sheetnames:
                    for _r in _wb_jb[_sht].iter_rows(min_row=2, values_only=True):
                        if _r[0] and str(_r[0]).strip() == "jira_base_url" and _r[1]:
                            jira_base = str(_r[1]).strip().rstrip("/")
                            break
                    if jira_base:
                        break
                _wb_jb.close()
        except Exception:
            pass
        return jsonify({"ok": True, "jira_base_url": jira_base})

    @app.route("/api/projects", methods=["GET"])
    def api_list():
        import json as _json_list
        rows = load_projects()
        for _r in rows:
            try:
                _ep = _json_list.loads(_r.get("extra_params") or "{}")
                _r["release_branch"] = str(_ep.get("release_branch", ""))
                _r["stage_outputs"]  = _ep.get("stage_outputs", {})
                if "remote_vm" not in _r:
                    _r["remote_vm"] = str(_ep.get("remote_vm", "") or _ep.get("vm_name", ""))
            except Exception:
                _r.setdefault("release_branch", "")
                _r.setdefault("remote_vm", "")
        return jsonify(rows)

    @app.route("/api/projects", methods=["POST"])
    def api_create():
        body          = request.get_json() or {}
        ticket        = body.get("ticket", "").strip()
        payor_version = body.get("payor_version", "").strip()
        bc_prefix     = body.get("bluecard_config_version_prefix", "").strip()
        du_prefix     = body.get("datauniverse_version_prefix", "").strip()
        extra_params      = body.get("extra_params") or {}
        stage_ids         = body.get("stage_ids") or []
        polling_interval  = int(body.get("polling_interval") or 600)
        if not ticket or not stage_ids:
            return jsonify({"error": "ticket and stage_ids required"}), 400
        import json as _json_proj
        extra_params_str = _json_proj.dumps(extra_params) if extra_params else ""
        pid = next_pid()
        create_project(pid, ticket, payor_version, stage_ids, bc_prefix, du_prefix,
                       extra_params_str, polling_interval)
        return jsonify({"pid": pid}), 201

    @app.route("/api/projects/<pid>", methods=["GET"])
    def api_detail(pid):
        import json as _json_det
        rows    = load_projects()
        project = next((r for r in rows if r.get("pid") == pid), None)
        if not project:
            return jsonify({"error": "not found"}), 404
        # Expose remote_vm, release_branch, melissa_ticket at top level so the UI can display/edit them
        try:
            _ep = _json_det.loads(project.get("extra_params") or "{}")
            project["remote_vm"]       = str(_ep.get("remote_vm", "") or _ep.get("vm_name", ""))
            project["release_branch"]  = str(_ep.get("release_branch", ""))
            project["melissa_ticket"]  = str(_ep.get("melissa_ticket", ""))
            project["stage_outputs"]   = _ep.get("stage_outputs", {})
            project["paused_at"]       = str(_ep.get("paused_at", ""))
        except Exception:
            project["remote_vm"]      = ""
            project["release_branch"] = ""
            project["melissa_ticket"] = ""
            project["stage_outputs"]  = {}
            project["paused_at"]      = ""
        return jsonify({"project": project, "stages": load_stages(pid)})

    @app.route("/api/projects/<pid>", methods=["PATCH"])
    def api_patch_project(pid):
        import json as _json_patch, openpyxl as _xl_patch
        body = request.get_json() or {}
        allowed = {"payor_version", "bluecard_config_version_prefix",
                   "datauniverse_version_prefix", "remote_vm", "release_branch",
                   "melissa_ticket"}
        patch = {k: v for k, v in body.items() if k in allowed}
        if not patch:
            return jsonify({"ok": False, "error": "No editable fields provided"}), 400
        if not PROJECTS.exists():
            return jsonify({"ok": False, "error": "Projects file not found"}), 404
        try:
            with _cw_projects_lock, _cw_projects_filelock():
                _wb_p = _xl_patch.load_workbook(str(PROJECTS))
                _ws_p = _wb_p.active
                _hdrs_p = [str(_ws_p.cell(1, c).value or "").strip().lower()
                           for c in range(1, _ws_p.max_column + 1)]
                _cmap_p = {h: i for i, h in enumerate(_hdrs_p, 1)}
                for _row_p in _ws_p.iter_rows(min_row=2):
                    if str(_row_p[0].value or "").strip() == str(pid).strip():
                        # Direct columns
                        for _fk in ("payor_version", "bluecard_config_version_prefix",
                                    "datauniverse_version_prefix"):
                            if _fk in patch and _fk in _cmap_p:
                                _row_p[_cmap_p[_fk] - 1].value = patch[_fk]
                        # remote_vm, release_branch, melissa_ticket live inside extra_params JSON
                        _ep_keys = {"remote_vm", "release_branch", "melissa_ticket"} & set(patch)
                        if _ep_keys and "extra_params" in _cmap_p:
                            _old_ep = str(_row_p[_cmap_p["extra_params"] - 1].value or "")
                            try:
                                _ep_d = _json_patch.loads(_old_ep) if _old_ep.strip() else {}
                                if not isinstance(_ep_d, dict):
                                    _ep_d = {}
                            except Exception:
                                _ep_d = {}
                            for _ek in _ep_keys:
                                _ep_d[_ek] = patch[_ek]
                            _row_p[_cmap_p["extra_params"] - 1].value = _json_patch.dumps(_ep_d)
                        break
                _save(_wb_p, PROJECTS)
            return jsonify({"ok": True})
        except Exception as _e_patch:
            return jsonify({"ok": False, "error": str(_e_patch)}), 500

    @app.route("/api/projects/<pid>", methods=["DELETE"])
    def api_delete(pid):
        # Signal the engine thread to stop before deleting files, so the
        # pid slot in _WF_THREADS is freed.  Without this, a new project
        # that reuses the same pid sees is_engine_running=True and the
        # Execute button is hidden.
        if pid in _WF_ABORT_EVENTS:
            _WF_ABORT_EVENTS[pid].set()
        if pid in _WF_THREADS:
            _WF_THREADS[pid].join(timeout=3)
            _WF_THREADS.pop(pid, None)
            _WF_ABORT_EVENTS.pop(pid, None)
        delete_project(pid)
        return "", 204

    @app.route("/api/projects/<pid>/execute", methods=["POST"])
    def api_execute_project(pid):
        rows = load_projects()
        proj = next((r for r in rows if r.get("pid") == pid), None)
        if not proj:
            return jsonify({"ok": False, "error": "Project not found"}), 404

        # Use global Auto Refresh interval from scheduler_config.xlsx
        polling_s = _cw_read_poll_interval()

        # Write polling_s back to project row so ProjectDetail.jsx can display it
        import openpyxl as _xl_pi
        if PROJECTS.exists():
            try:
                with _cw_projects_lock, _cw_projects_filelock():
                    _wb_pi = _xl_pi.load_workbook(str(PROJECTS))
                    _ws_pi = _wb_pi.active
                    _hdrs_pi = [str(_ws_pi.cell(1, c).value or "").strip().lower()
                                for c in range(1, _ws_pi.max_column + 1)]
                    _cmap_pi = {h: i for i, h in enumerate(_hdrs_pi, 1)}
                    for _row_pi in _ws_pi.iter_rows(min_row=2):
                        if str(_row_pi[0].value or "").strip() == str(pid).strip():
                            if "polling_interval" in _cmap_pi:
                                _row_pi[_cmap_pi["polling_interval"] - 1].value = polling_s
                            break
                    _save(_wb_pi, PROJECTS)
            except Exception:
                pass

        # Load dependency graph
        import openpyxl as _xl_ex
        _dep_path = CW_ROOT / "workflow_dependencies.xlsx"
        deps = {}
        if _dep_path.exists():
            try:
                _wb = _xl_ex.load_workbook(str(_dep_path), read_only=True, data_only=True)
                for _r in _wb.active.iter_rows(min_row=2, values_only=True):
                    _sid = str(_r[0] or "").strip(); _dep = str(_r[1] or "").strip()
                    if _sid and _dep:
                        deps.setdefault(_sid, [])
                        if _dep not in deps[_sid]:
                            deps[_sid].append(_dep)
                _wb.close()
            except Exception:
                pass

        # Build project params
        import json as _json_ex
        extra = {}
        try:
            _parsed = _json_ex.loads(proj.get("extra_params") or "{}")
            if isinstance(_parsed, dict):
                extra = _parsed
        except Exception:
            pass
        # Put **extra first so explicit project fields (payor_version, etc.) always
        # win over anything accidentally stored in extra_params.
        proj_params = {
            **extra,
            "payor_version":                  proj.get("payor_version", ""),
            "bluecard_config_version_prefix": proj.get("bluecard_config_version_prefix", ""),
            "datauniverse_version_prefix":    proj.get("datauniverse_version_prefix", ""),
            "app":                            extra.get("app", "Payor"),
        }

        # Build trigger/check closures via shared factory (also used by startup recovery)
        _wf_trigger_fn, _wf_check_fn = _build_wf_fns(pid, proj_params)

        # Start engine if not already running
        if pid not in _WF_THREADS or not _WF_THREADS[pid].is_alive():
            # Mark project as In Progress immediately so UI reflects it
            if PROJECTS.exists():
                try:
                    with _cw_projects_lock, _cw_projects_filelock():
                        _wb_ex = _xl_pi.load_workbook(str(PROJECTS))
                        _ws_ex = _wb_ex.active
                        _hdrs_ex = [str(_ws_ex.cell(1, c).value or "").strip().lower()
                                    for c in range(1, _ws_ex.max_column + 1)]
                        _cmap_ex = {h: i for i, h in enumerate(_hdrs_ex, 1)}
                        _ts_ex = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                        for _row_ex in _ws_ex.iter_rows(min_row=2):
                            if str(_row_ex[0].value or "").strip() == str(pid).strip():
                                if "status" in _cmap_ex:
                                    _row_ex[_cmap_ex["status"] - 1].value = "In Progress"
                                if "started_at" in _cmap_ex:
                                    _row_ex[_cmap_ex["started_at"] - 1].value = _ts_ex
                                break
                        _save(_wb_ex, PROJECTS)
                except Exception:
                    pass
            _abort_ev = _threading_wf.Event()
            _WF_ABORT_EVENTS[pid] = _abort_ev
            t = _threading_wf.Thread(
                target=_wf_run_engine,
                args=(pid, polling_s, deps, _wf_trigger_fn, _wf_check_fn,
                      {"baseline", "jreg", "jcj", "jcj_baseline", "remote_setup", "melissa_update", "clone_pr_gp",
                       "melissa_gp_payor", "melissa_gp_classic", "rpb", "puc_baseline", "puc"}, proj_params),
                daemon=True,
            )
            t.start()
            _WF_THREADS[pid] = t

        return jsonify({"ok": True, "is_running": True})

    @app.route("/api/preflight", methods=["GET"])
    def api_preflight():
        """Check Jenkins and GitHub reachability before starting a workflow."""
        import requests as _rq_pf
        from urllib.parse import urlparse as _urlparse_pf
        checks = []

        # ── Load secrets ──────────────────────────────────────────────────────
        _sec_pf = {}
        try:
            import openpyxl as _xl_pf
            if SECRETS_FILE.exists():
                _swb_pf = _xl_pf.load_workbook(str(SECRETS_FILE), read_only=True, data_only=True)
                for _sh_pf in _swb_pf.sheetnames:
                    for _r_pf in _swb_pf[_sh_pf].iter_rows(min_row=2, values_only=True):
                        if _r_pf[0] and _r_pf[1] is not None:
                            _sec_pf[str(_r_pf[0]).strip()] = str(_r_pf[1]).strip()
                _swb_pf.close()
        except Exception:
            pass

        # ── Jenkins check ─────────────────────────────────────────────────────
        _jk_user_pf = _sec_pf.get("jenkins_username", "").strip()
        _jk_pass_pf = (_sec_pf.get("jenkins_api_token", "") or _sec_pf.get("jenkins_password", "")).strip()

        # Derive Jenkins base URL from first available job config file
        _jk_base_pf = ""
        _cfg_candidates = [
            JR_ROOT  / "reg_job_config.xlsx",
            JB_ROOT  / "baseline_job_config.xlsx",
            JCJ_ROOT / "commit_job_config.xlsx",
            PUC_ROOT / "puc_config.xlsx",
        ]
        try:
            import openpyxl as _xl_pf2
            for _cp in _cfg_candidates:
                if not _cp.exists():
                    continue
                _cwb = _xl_pf2.load_workbook(str(_cp), read_only=True, data_only=True)
                for _csh in _cwb.sheetnames:
                    _cws = _cwb[_csh]
                    _ch = [str(_cws.cell(1, c).value or "").strip().lower()
                           for c in range(1, _cws.max_column + 1)]
                    if "job_url" in _ch:
                        _ci = _ch.index("job_url")
                        for _crow in _cws.iter_rows(min_row=2, values_only=True):
                            _cu = str(_crow[_ci] or "").strip() if _ci < len(_crow) else ""
                            if _cu.startswith("http"):
                                _p = _urlparse_pf(_cu)
                                _jk_base_pf = f"{_p.scheme}://{_p.netloc}"
                                break
                    if _jk_base_pf:
                        break
                _cwb.close()
                if _jk_base_pf:
                    break
        except Exception:
            pass

        if _jk_base_pf:
            try:
                _auth_pf = (_jk_user_pf, _jk_pass_pf) if _jk_user_pf and _jk_pass_pf else None
                _rj = _rq_pf.get(
                    _jk_base_pf.rstrip("/") + "/api/json",
                    auth=_auth_pf, timeout=5, verify=False
                )
                if _rj.status_code < 500:
                    checks.append({"name": "Jenkins", "reachable": True, "error": None})
                else:
                    checks.append({"name": "Jenkins", "reachable": False,
                                   "error": f"HTTP {_rj.status_code}"})
            except Exception as _ej:
                checks.append({"name": "Jenkins", "reachable": False,
                               "error": str(_ej)[:120]})
        else:
            checks.append({"name": "Jenkins", "reachable": None,
                           "error": "Job URL not configured"})

        # ── GitHub check ──────────────────────────────────────────────────────
        _gh_tok_pf = (_sec_pf.get("github_token") or _sec_pf.get("github_pat") or "").strip()
        try:
            _gh_hdrs_pf = ({"Authorization": f"token {_gh_tok_pf}"}
                           if _gh_tok_pf else {})
            _rg = _rq_pf.get("https://api.github.com", headers=_gh_hdrs_pf, timeout=5)
            if _rg.status_code < 500:
                checks.append({"name": "GitHub", "reachable": True, "error": None})
            else:
                checks.append({"name": "GitHub", "reachable": False,
                               "error": f"HTTP {_rg.status_code}"})
        except Exception as _eg:
            checks.append({"name": "GitHub", "reachable": False,
                           "error": str(_eg)[:120]})

        ok = all(c["reachable"] is not False for c in checks)
        return jsonify({"ok": ok, "checks": checks})

    @app.route("/api/health/environment", methods=["GET"])
    def api_health_environment():
        """Environment health panel: Jenkins queue depth, GitHub rate limit, VM reachability."""
        import concurrent.futures as _cf_he
        import socket as _sock_he
        from datetime import datetime as _dt_he
        from urllib.parse import urlparse as _urlparse_he

        # ── Load secrets once, shared by all checks ───────────────────────────
        _sec_he = {}
        try:
            import openpyxl as _xl_he
            if SECRETS_FILE.exists():
                _swb_he = _xl_he.load_workbook(str(SECRETS_FILE), read_only=True, data_only=True)
                for _sh_he in _swb_he.sheetnames:
                    for _r_he in _swb_he[_sh_he].iter_rows(min_row=2, values_only=True):
                        if _r_he[0] and _r_he[1] is not None:
                            _sec_he[str(_r_he[0]).strip()] = str(_r_he[1]).strip()
                _swb_he.close()
        except Exception:
            pass

        def _check_jenkins_queue():
            try:
                import requests as _rq_he2
                _jk_user = _sec_he.get("jenkins_username", "").strip()
                _jk_pass = (_sec_he.get("jenkins_api_token", "") or _sec_he.get("jenkins_password", "")).strip()
                _jk_base = ""
                _cfg_cands = [
                    JR_ROOT  / "reg_job_config.xlsx",
                    JB_ROOT  / "baseline_job_config.xlsx",
                    JCJ_ROOT / "commit_job_config.xlsx",
                    PUC_ROOT / "puc_config.xlsx",
                ]
                try:
                    import openpyxl as _xl_he3
                    for _cp in _cfg_cands:
                        if not _cp.exists():
                            continue
                        _cwb = _xl_he3.load_workbook(str(_cp), read_only=True, data_only=True)
                        for _csh in _cwb.sheetnames:
                            _cws = _cwb[_csh]
                            _ch = [str(_cws.cell(1, c).value or "").strip().lower()
                                   for c in range(1, _cws.max_column + 1)]
                            if "job_url" in _ch:
                                _ci = _ch.index("job_url")
                                for _crow in _cws.iter_rows(min_row=2, values_only=True):
                                    _cu = str(_crow[_ci] or "").strip() if _ci < len(_crow) else ""
                                    if _cu.startswith("http"):
                                        _p = _urlparse_he(_cu)
                                        _jk_base = f"{_p.scheme}://{_p.netloc}"
                                        break
                            if _jk_base:
                                break
                        _cwb.close()
                        if _jk_base:
                            break
                except Exception:
                    pass

                if not _jk_base:
                    return {"depth": None, "stuck": None, "status": "unknown",
                            "error": "Jenkins URL not configured", "url": ""}

                _auth = (_jk_user, _jk_pass) if _jk_user and _jk_pass else None
                _rq = _rq_he2.get(
                    _jk_base.rstrip("/") + "/queue/api/json?tree=items[stuck,blocked,why]",
                    auth=_auth, timeout=8, verify=False
                )
                items = _rq.json().get("items", []) if _rq.status_code == 200 else []
                depth = len(items)
                stuck = sum(1 for it in items if it.get("stuck") or it.get("blocked"))
                if stuck > 0:
                    status = "error"
                elif depth >= 15:
                    status = "error"
                elif depth >= 5:
                    status = "warn"
                else:
                    status = "ok"
                return {"depth": depth, "stuck": stuck, "status": status, "url": _jk_base}
            except Exception as _e_jq:
                return {"depth": None, "stuck": None, "status": "unknown",
                        "error": str(_e_jq)[:120], "url": ""}

        def _check_github_rate():
            try:
                import requests as _rq_gh, time as _time_gh
                _gh_tok = (_sec_he.get("github_token") or _sec_he.get("github_pat") or "").strip()
                _hdrs = {"Authorization": f"token {_gh_tok}"} if _gh_tok else {}
                _r = _rq_gh.get("https://api.github.com/rate_limit",
                                 headers=_hdrs, timeout=8, verify=False)
                core = _r.json().get("resources", {}).get("core", {})
                remaining = core.get("remaining", 0)
                limit     = core.get("limit", 5000)
                reset_ts  = core.get("reset", 0)
                secs = max(0, int(reset_ts - _time_gh.time()))
                resets_in = f"{secs // 60}m {secs % 60}s" if secs > 0 else "now"
                if remaining > 500:
                    status = "ok"
                elif remaining > 50:
                    status = "warn"
                else:
                    status = "error"
                return {"remaining": remaining, "limit": limit,
                        "resets_in": resets_in, "status": status}
            except Exception as _e_gh:
                return {"remaining": None, "limit": None, "status": "unknown",
                        "error": str(_e_gh)[:120]}

        def _check_vms():
            try:
                vms_list = _rows(VMS_FILE)
                checks = []
                for vm in vms_list:
                    ip   = str(vm.get("ip") or "").strip()
                    name = str(vm.get("name") or ip).strip()
                    if not ip:
                        continue
                    try:
                        _s = _sock_he.socket(_sock_he.AF_INET, _sock_he.SOCK_STREAM)
                        _s.settimeout(3)
                        reachable = _s.connect_ex((ip, 22)) == 0
                        _s.close()
                    except Exception:
                        reachable = False
                    checks.append({"name": name, "ip": ip, "reachable": reachable,
                                   "status": "ok" if reachable else "error"})
                return checks
            except Exception:
                return []

        result = {
            "ok": True,
            "checked_at": _dt_he.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
            "checks": {},
        }
        try:
            with _cf_he.ThreadPoolExecutor(max_workers=3) as _pool_he:
                _f_jq = _pool_he.submit(_check_jenkins_queue)
                _f_gh = _pool_he.submit(_check_github_rate)
                _f_vm = _pool_he.submit(_check_vms)
                result["checks"]["jenkins_queue"]     = _f_jq.result(timeout=15)
                result["checks"]["github_rate_limit"] = _f_gh.result(timeout=15)
                result["checks"]["vms"]               = _f_vm.result(timeout=15)
        except Exception as _e_he:
            result["ok"] = False
            result["error"] = str(_e_he)
        return jsonify(result)

    @app.route("/api/clone-workflow/validate-inputs", methods=["POST"])
    def api_validate_inputs():
        """Pre-flight validation of project inputs before executing the workflow."""
        import json as _json_vi, re as _re_vi, requests as _rq_vi
        from concurrent.futures import ThreadPoolExecutor as _TPE_vi, as_completed as _asc_vi

        body = request.get_json(force=True, silent=True) or {}
        pid_vi = str(body.get("pid", "")).strip()
        if not pid_vi:
            return jsonify({"ok": False, "error": "pid required"}), 400

        # ── Load project ───────────────────────────────────────────────────────
        _rows_vi = load_projects()
        _proj_vi = next((r for r in _rows_vi if str(r.get("pid", "")).strip() == pid_vi), None)
        if not _proj_vi:
            return jsonify({"ok": False, "error": "Project not found"}), 404

        try:
            _ep_vi = _json_vi.loads(_proj_vi.get("extra_params") or "{}")
        except Exception:
            _ep_vi = {}
        _so_vi   = _ep_vi.get("stage_outputs") or {}
        _rel_br  = str(_ep_vi.get("release_branch") or _proj_vi.get("payor_version") or "").strip()
        _clone_br = str((_so_vi.get("clone") or {}).get("clone_branch") or "").strip()
        _jcj_bl_ver = str((_so_vi.get("jcj_baseline") or {}).get("jcj_baseline_build_version") or "").strip()
        # Collect any pr_url values from stage outputs
        _pr_urls_vi = [
            str((_so_vi.get(sk) or {}).get("pr_url") or "").strip()
            for sk in ("melissa_gp_payor", "melissa_gp_classic", "clone_pr_gp")
        ]
        _pr_urls_vi = [u for u in _pr_urls_vi if u]

        # ── Load secrets & git config ─────────────────────────────────────────
        _gh_tok_vi = ""
        _jk_user_vi = ""
        _jk_pass_vi = ""
        try:
            import openpyxl as _xl_vi2
            if SECRETS_FILE.exists():
                _swb = _xl_vi2.load_workbook(str(SECRETS_FILE), read_only=True, data_only=True)
                for _sh in _swb.sheetnames:
                    for _r in _swb[_sh].iter_rows(min_row=2, values_only=True):
                        if not _r[0]:
                            continue
                        _k = str(_r[0]).strip().lower()
                        _v = str(_r[1] or "").strip() if len(_r) > 1 else ""
                        if _k in ("github_token", "github_pat") and not _gh_tok_vi:
                            _gh_tok_vi = _v
                        elif _k == "jenkins_username" and not _jk_user_vi:
                            _jk_user_vi = _v
                        elif _k in ("jenkins_api_token", "jenkins_password") and not _jk_pass_vi:
                            _jk_pass_vi = _v
                _swb.close()
        except Exception:
            pass

        _gh_hdrs_vi = ({"Authorization": f"token {_gh_tok_vi}",
                        "Accept": "application/vnd.github+json"}
                       if _gh_tok_vi else {"Accept": "application/vnd.github+json"})
        _jk_auth_vi = (_jk_user_vi, _jk_pass_vi) if _jk_user_vi and _jk_pass_vi else None

        # Derive repo owner/name from JR git_config (payor repo URL)
        _owner_vi = ""
        _repo_vi  = ""
        try:
            _repos_vi = _scm_read_git_config()
            _payor_url = next((r["repo_url"] for r in _repos_vi if r["app"] == "payor"), "")
            if _payor_url:
                _m_vi = _re_vi.search(r"github\.com[:/]([^/]+)/([^/.]+?)(?:\.git)?$", _payor_url)
                if _m_vi:
                    _owner_vi, _repo_vi = _m_vi.group(1), _m_vi.group(2)
        except Exception:
            pass

        # Derive JCJ job URL for enabled check
        _jcj_job_url_vi = ""
        try:
            import openpyxl as _xl_vi3
            _jcj_cfg = JCJ_ROOT / "commit_job_config.xlsx"
            if _jcj_cfg.exists():
                _wb_jv = _xl_vi3.load_workbook(str(_jcj_cfg), read_only=True, data_only=True)
                _app_vi = str(_ep_vi.get("app") or "Payor")
                _sn_vi = next((s for s in _wb_jv.sheetnames if s.lower() == _app_vi.lower()), None) or _wb_jv.sheetnames[0] if _wb_jv.sheetnames else None
                if _sn_vi:
                    _jws = _wb_jv[_sn_vi]
                    _jhdrs = [str(_jws.cell(1, c).value or "").strip().lower()
                              for c in range(1, _jws.max_column + 1)]
                    _ji = _jhdrs.index("job_url") if "job_url" in _jhdrs else -1
                    if _ji >= 0:
                        for _jr in _jws.iter_rows(min_row=2, values_only=True):
                            _u = str(_jr[_ji] or "").strip() if _ji < len(_jr) else ""
                            if _u.startswith("http"):
                                _jcj_job_url_vi = _u
                                break
                _wb_jv.close()
        except Exception:
            pass

        # ── Check functions ───────────────────────────────────────────────────
        def _chk_version_format():
            if not _rel_br:
                return {"key": "version_format", "status": "error",
                        "message": "Release branch version is not set"}
            if _re_vi.match(r"^\d+\.\d+\.\d+\.\d+(\.\d+)?$", _rel_br):
                return {"key": "version_format", "status": "ok",
                        "message": f"Version format valid: {_rel_br}"}
            return {"key": "version_format", "status": "error",
                    "message": f"Version '{_rel_br}' does not match expected pattern (e.g. 26.2.1.0.1)"}

        def _chk_github_release_branch():
            if not _rel_br or not _owner_vi or not _repo_vi:
                return {"key": "github_release_branch", "status": "skip",
                        "message": "GitHub repo not configured — skipped"}
            # Try both release/<version> and release-<version> naming
            _ver_short = _rel_br.rsplit(".", 1)[0] if _rel_br.count(".") >= 4 else _rel_br
            _candidates = [f"release-{_rel_br}", f"release/{_rel_br}",
                           f"release-{_ver_short}", f"release/{_ver_short}"]
            try:
                for _br in _candidates:
                    _url = f"https://api.github.com/repos/{_owner_vi}/{_repo_vi}/branches/{_br}"
                    _r = _rq_vi.get(_url, headers=_gh_hdrs_vi, timeout=8, verify=False)
                    if _r.status_code == 200:
                        return {"key": "github_release_branch", "status": "ok",
                                "message": f"Branch '{_br}' exists in GitHub"}
                return {"key": "github_release_branch", "status": "error",
                        "message": f"No release branch found for version {_rel_br} in GitHub"}
            except Exception as _e:
                return {"key": "github_release_branch", "status": "warning",
                        "message": f"Could not reach GitHub: {str(_e)[:80]}"}

        def _chk_github_clone_branch():
            if not _clone_br:
                return {"key": "github_clone_branch", "status": "skip",
                        "message": "Clone branch not configured — skipped"}
            if not _owner_vi or not _repo_vi:
                return {"key": "github_clone_branch", "status": "skip",
                        "message": "GitHub repo not configured — skipped"}
            try:
                _url = f"https://api.github.com/repos/{_owner_vi}/{_repo_vi}/branches/{_clone_br}"
                _r = _rq_vi.get(_url, headers=_gh_hdrs_vi, timeout=8, verify=False)
                if _r.status_code == 200:
                    return {"key": "github_clone_branch", "status": "ok",
                            "message": f"Clone branch '{_clone_br}' exists in GitHub"}
                elif _r.status_code == 404:
                    return {"key": "github_clone_branch", "status": "error",
                            "message": f"Clone branch '{_clone_br}' not found in GitHub"}
                return {"key": "github_clone_branch", "status": "warning",
                        "message": f"GitHub returned HTTP {_r.status_code} checking clone branch"}
            except Exception as _e:
                return {"key": "github_clone_branch", "status": "warning",
                        "message": f"Could not reach GitHub: {str(_e)[:80]}"}

        def _chk_jcj_build_version():
            if not _jcj_bl_ver:
                return {"key": "jcj_build_version_format", "status": "skip",
                        "message": "JCJ baseline build version not set — skipped"}
            # Pattern: 26.2.1.0.4-20261016HHMM-<sha7>
            if _re_vi.match(r"^\d+\.\d+\.\d+\.\d+\.\d+-\d+-[a-f0-9]{7,}$", _jcj_bl_ver):
                return {"key": "jcj_build_version_format", "status": "ok",
                        "message": f"JCJ build version format valid"}
            return {"key": "jcj_build_version_format", "status": "warning",
                    "message": f"JCJ build version '{_jcj_bl_ver}' may not match expected format"}

        def _chk_jenkins_jcj():
            if not _jcj_job_url_vi:
                return {"key": "jenkins_jcj_enabled", "status": "skip",
                        "message": "JCJ job URL not configured — skipped"}
            try:
                _r = _rq_vi.get(
                    _jcj_job_url_vi.rstrip("/") + "/api/json?tree=disabled,color",
                    auth=_jk_auth_vi, timeout=6, verify=False)
                if _r.status_code == 200:
                    _jdata = _r.json()
                    if _jdata.get("disabled"):
                        return {"key": "jenkins_jcj_enabled", "status": "warning",
                                "message": "JCJ Jenkins job is disabled — builds will not trigger"}
                    return {"key": "jenkins_jcj_enabled", "status": "ok",
                            "message": "JCJ Jenkins job is enabled"}
                return {"key": "jenkins_jcj_enabled", "status": "warning",
                        "message": f"Could not check JCJ job status (HTTP {_r.status_code})"}
            except Exception as _e:
                return {"key": "jenkins_jcj_enabled", "status": "warning",
                        "message": f"Could not reach Jenkins: {str(_e)[:80]}"}

        def _chk_pr_urls():
            if not _pr_urls_vi:
                return {"key": "pr_url_valid", "status": "skip",
                        "message": "No PR URLs configured — skipped"}
            _bad = []
            for _pu in _pr_urls_vi:
                _m = _re_vi.search(r"github\.com/([^/]+)/([^/]+)/pull/(\d+)", _pu)
                if not _m:
                    _bad.append(f"'{_pu}' is not a valid GitHub PR URL")
                    continue
                if not _owner_vi:
                    continue
                try:
                    _api = f"https://api.github.com/repos/{_m.group(1)}/{_m.group(2)}/pulls/{_m.group(3)}"
                    _r = _rq_vi.get(_api, headers=_gh_hdrs_vi, timeout=6, verify=False)
                    if _r.status_code == 404:
                        _bad.append(f"PR #{_m.group(3)} not found in GitHub")
                    elif _r.status_code != 200:
                        _bad.append(f"GitHub returned HTTP {_r.status_code} for PR URL")
                except Exception as _e:
                    _bad.append(f"Could not verify PR URL: {str(_e)[:60]}")
            if _bad:
                return {"key": "pr_url_valid", "status": "warning",
                        "message": "; ".join(_bad)}
            return {"key": "pr_url_valid", "status": "ok",
                    "message": f"{len(_pr_urls_vi)} PR URL(s) verified"}

        def _chk_puc_config():
            _cfg = PUC_ROOT / "puc_config.xlsx"
            if _cfg.exists():
                return {"key": "puc_config_exists", "status": "ok",
                        "message": "PUC config file found"}
            return {"key": "puc_config_exists", "status": "warning",
                    "message": "PUC config file not found — PUC stage will need configuration"}

        # ── Run all checks in parallel ────────────────────────────────────────
        _fns = [
            _chk_version_format,
            _chk_github_release_branch,
            _chk_github_clone_branch,
            _chk_jcj_build_version,
            _chk_jenkins_jcj,
            _chk_pr_urls,
            _chk_puc_config,
        ]
        _results_vi = [None] * len(_fns)
        with _TPE_vi(max_workers=6) as _ex_vi:
            _fut_map = {_ex_vi.submit(fn): i for i, fn in enumerate(_fns)}
            for _fut in _asc_vi(_fut_map):
                _i = _fut_map[_fut]
                try:
                    _results_vi[_i] = _fut.result()
                except Exception as _e:
                    _results_vi[_i] = {"key": f"check_{_i}", "status": "warning",
                                       "message": f"Check failed: {str(_e)[:80]}"}

        _checks_vi = [r for r in _results_vi if r is not None]
        _ok_vi = all(c["status"] in ("ok", "skip", "warning") for c in _checks_vi)
        return jsonify({"ok": _ok_vi, "checks": _checks_vi})

    @app.route("/api/projects/<pid>/abort", methods=["POST"])
    def api_abort_project(pid):
        import openpyxl as _xl_ab

        # 1. Signal engine to stop
        if pid in _WF_ABORT_EVENTS:
            _WF_ABORT_EVENTS[pid].set()

        stages = load_stages(pid)

        # 2. Abort running sub-workflows directly (no HTTP self-call to avoid deadlock)
        for _st in stages:
            _sk = str(_st.get("stage_key", "")).strip()
            _ss = str(_st.get("status", "")).strip()
            if _ss not in ("In Progress", "Waiting", "Pending"):
                continue

            if _sk == "baseline":
                _bl_proc_pid = None
                with _jbaseline_op_lock:
                    if _jbaseline_op.get("status") == "running":
                        _jbaseline_op["output"] += "\n--- Abort requested ---\n"
                        _jbaseline_op["status"] = "aborted"
                        _bl_proc_pid = _jbaseline_op.get("pid")
                _jbaseline_abort.set()
                if _bl_proc_pid:
                    import subprocess as _sp_ab
                    try: _sp_ab.run(["taskkill", "/F", "/T", "/PID", str(_bl_proc_pid)], capture_output=True)
                    except Exception: pass

            elif _sk == "jreg":
                _jr_proc_pid = None
                with _jreg_op_lock:
                    if _jreg_op.get("status") == "running":
                        _jreg_op["output"] += "\n--- Abort requested ---\n"
                        _jreg_op["status"] = "aborted"
                        _jr_proc_pid = _jreg_op.get("pid")
                _jreg_abort.set()
                if _jr_proc_pid:
                    import subprocess as _sp_ab
                    try: _sp_ab.run(["taskkill", "/F", "/T", "/PID", str(_jr_proc_pid)], capture_output=True)
                    except Exception: pass

            elif _sk == "remote_setup":
                _rs_pid = str(_st.get("tool_pid") or "").strip()
                if _rs_pid and RS_ROOT.exists():
                    _rs_path = RS_DATA / "projects.xlsx"
                    if _rs_path.exists():
                        try:
                            _wb_rs = _xl_ab.load_workbook(str(_rs_path))
                            _ws_rs = _wb_rs.active
                            _hdrs_rs = [str(_ws_rs.cell(1, c).value or "").strip().lower()
                                        for c in range(1, _ws_rs.max_column + 1)]
                            _cmap_rs = {h: i for i, h in enumerate(_hdrs_rs, 1)}
                            for _row_rs in _ws_rs.iter_rows(min_row=2):
                                if str(_row_rs[0].value or "").strip() == _rs_pid:
                                    if "status" in _cmap_rs:
                                        _row_rs[_cmap_rs["status"] - 1].value = "Aborted"
                                    break
                            _wb_rs.save(str(_rs_path))
                        except Exception:
                            pass

        # 3. Mark all non-terminal stages as Aborted
        for _st in stages:
            _ss = str(_st.get("status", "")).strip()
            if _ss not in ("Completed", "Skipped", "Failed", "Aborted"):
                update_stage(pid, _st["stage_id"], {"status": "Aborted"})

        # 4. Mark the project itself as Aborted
        if PROJECTS.exists():
            try:
                with _cw_projects_lock, _cw_projects_filelock():
                    _wb_p = _xl_ab.load_workbook(str(PROJECTS))
                    _ws_p = _wb_p.active
                    _hdrs_p = [str(_ws_p.cell(1, c).value or "").strip().lower()
                               for c in range(1, _ws_p.max_column + 1)]
                    _cmap_p = {h: i for i, h in enumerate(_hdrs_p, 1)}
                    for _row_p in _ws_p.iter_rows(min_row=2):
                        if str(_row_p[0].value or "").strip() == str(pid).strip():
                            if "status" in _cmap_p:
                                _row_p[_cmap_p["status"] - 1].value = "Aborted"
                            break
                    _save(_wb_p, PROJECTS)
            except Exception:
                pass

        return jsonify({"ok": True})

    @app.route("/api/projects/<pid>/pause", methods=["POST"])
    def api_pause_project(pid):
        import openpyxl as _xl_pause, json as _json_pause
        from datetime import datetime as _dt_pause
        if pid not in _WF_PAUSE_EVENTS:
            _WF_PAUSE_EVENTS[pid] = _threading_wf.Event()
        _WF_PAUSE_EVENTS[pid].set()
        _paused_at = _dt_pause.now().strftime("%Y-%m-%d %H:%M:%S")
        if PROJECTS.exists():
            try:
                with _cw_projects_lock, _cw_projects_filelock():
                    _wb_ps = _xl_pause.load_workbook(str(PROJECTS))
                    _ws_ps = _wb_ps.active
                    _hdrs_ps = [str(_ws_ps.cell(1, c).value or "").strip().lower()
                                for c in range(1, _ws_ps.max_column + 1)]
                    _cmap_ps = {h: i for i, h in enumerate(_hdrs_ps, 1)}
                    for _row_ps in _ws_ps.iter_rows(min_row=2):
                        if str(_row_ps[0].value or "").strip() == str(pid).strip():
                            if "status" in _cmap_ps:
                                _row_ps[_cmap_ps["status"] - 1].value = "Paused"
                            if "extra_params" in _cmap_ps:
                                _ep_cell_ps = _row_ps[_cmap_ps["extra_params"] - 1]
                                try:
                                    _ep_ps = _json_pause.loads(_ep_cell_ps.value or "{}")
                                    if not isinstance(_ep_ps, dict):
                                        _ep_ps = {}
                                except Exception:
                                    _ep_ps = {}
                                _ep_ps["paused_at"] = _paused_at
                                _ep_cell_ps.value = _json_pause.dumps(_ep_ps)
                            break
                    _save(_wb_ps, PROJECTS)
            except Exception:
                pass
        return jsonify({"ok": True, "paused_at": _paused_at})

    @app.route("/api/projects/<pid>/resume", methods=["POST"])
    def api_resume_project(pid):
        import openpyxl as _xl_res, json as _json_res
        import threading as _thr_res
        # Clear the pause gate
        if pid in _WF_PAUSE_EVENTS:
            _WF_PAUSE_EVENTS[pid].clear()
        # If engine is alive just wake it; otherwise restart it (e.g. after server restart)
        if pid in _WF_THREADS and _WF_THREADS[pid].is_alive():
            if pid not in _WF_WAKE_EVENTS:
                _WF_WAKE_EVENTS[pid] = _threading_wf.Event()
            _WF_WAKE_EVENTS[pid].set()
        else:
            _stages_res = load_stages(pid)
            _has_live = any(
                s.get("status", "Pending") not in ("Completed", "Skipped", "Failed", "Aborted")
                for s in _stages_res
            )
            if _has_live:
                _rows_res = load_projects()
                _proj_res = next((r for r in _rows_res if r.get("pid") == pid), None)
                if _proj_res:
                    _extra_res = {}
                    try:
                        _extra_res = _json_res.loads(_proj_res.get("extra_params") or "{}")
                    except Exception:
                        pass
                    _pp_res = {
                        **_extra_res,
                        "payor_version":                  _proj_res.get("payor_version", ""),
                        "bluecard_config_version_prefix": _proj_res.get("bluecard_config_version_prefix", ""),
                        "datauniverse_version_prefix":    _proj_res.get("datauniverse_version_prefix", ""),
                        "app":                            _extra_res.get("app", "Payor"),
                    }
                    _deps_res = {}
                    _dep_path_res = CW_ROOT / "workflow_dependencies.xlsx"
                    if _dep_path_res.exists():
                        try:
                            _wb_dep = _xl_res.load_workbook(str(_dep_path_res), read_only=True, data_only=True)
                            for _rd in _wb_dep.active.iter_rows(min_row=2, values_only=True):
                                _sd = str(_rd[0] or "").strip(); _dd = str(_rd[1] or "").strip()
                                if _sd and _dd:
                                    _deps_res.setdefault(_sd, [])
                                    if _dd not in _deps_res[_sd]:
                                        _deps_res[_sd].append(_dd)
                            _wb_dep.close()
                        except Exception:
                            pass
                    _tf_res, _cf_res = _build_wf_fns(pid, _pp_res)
                    _abort_ev_res = _thr_res.Event()
                    _WF_ABORT_EVENTS[pid] = _abort_ev_res
                    _t_res = _thr_res.Thread(
                        target=_wf_run_engine,
                        args=(pid, _cw_read_poll_interval(), _deps_res, _tf_res, _cf_res,
                              {"baseline", "jreg", "jcj", "jcj_baseline", "remote_setup", "melissa_update", "clone_pr_gp",
                               "melissa_gp_payor", "melissa_gp_classic", "rpb", "puc_baseline", "puc"}, _pp_res),
                        daemon=True,
                    )
                    _t_res.start()
                    _WF_THREADS[pid] = _t_res
        if PROJECTS.exists():
            try:
                with _cw_projects_lock, _cw_projects_filelock():
                    _wb_rs = _xl_res.load_workbook(str(PROJECTS))
                    _ws_rs = _wb_rs.active
                    _hdrs_rs = [str(_ws_rs.cell(1, c).value or "").strip().lower()
                                for c in range(1, _ws_rs.max_column + 1)]
                    _cmap_rs = {h: i for i, h in enumerate(_hdrs_rs, 1)}
                    for _row_rs in _ws_rs.iter_rows(min_row=2):
                        if str(_row_rs[0].value or "").strip() == str(pid).strip():
                            if "status" in _cmap_rs:
                                _row_rs[_cmap_rs["status"] - 1].value = "In Progress"
                            if "extra_params" in _cmap_rs:
                                _ep_cell_rs = _row_rs[_cmap_rs["extra_params"] - 1]
                                try:
                                    _ep_rs = _json_res.loads(_ep_cell_rs.value or "{}")
                                    if not isinstance(_ep_rs, dict):
                                        _ep_rs = {}
                                except Exception:
                                    _ep_rs = {}
                                _ep_rs.pop("paused_at", None)
                                _ep_cell_rs.value = _json_res.dumps(_ep_rs)
                            break
                    _save(_wb_rs, PROJECTS)
            except Exception:
                pass
        return jsonify({"ok": True})

    @app.route("/api/projects/<pid>/stage-outputs", methods=["POST"])
    def api_save_stage_outputs(pid):
        import openpyxl as _xl_so, json as _json_so
        body = request.get_json(force=True, silent=True) or {}
        stage_id = str(body.get("stage_id", "")).strip()
        outputs  = body.get("outputs", {})
        if not stage_id or not isinstance(outputs, dict):
            return jsonify({"ok": False, "error": "stage_id and outputs required"}), 400
        try:
            with _cw_projects_lock, _cw_projects_filelock():
                _wb_so = _xl_so.load_workbook(str(PROJECTS))
                _ws_so = _wb_so.active
                _hdr_so = [str(_ws_so.cell(1, c).value or "").strip() for c in range(1, _ws_so.max_column + 1)]
                _cmap_so = {h: i+1 for i, h in enumerate(_hdr_so)}
                for _row_so in _ws_so.iter_rows(min_row=2):
                    _pid_val = str(_row_so[_cmap_so.get("pid", 1) - 1].value or "").strip()
                    if _pid_val == str(pid):
                        _ep_cell = _row_so[_cmap_so.get("extra_params", 1) - 1]
                        try:
                            _ep_d = _json_so.loads(_ep_cell.value or "{}")
                        except Exception:
                            _ep_d = {}
                        _so = dict(_ep_d.get("stage_outputs", {}))
                        _so[stage_id] = dict(outputs)
                        _ep_d["stage_outputs"] = _so
                        _ep_cell.value = _json_so.dumps(_ep_d)
                        break
                _wb_so.save(str(PROJECTS))
            return jsonify({"ok": True})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)}), 500

    @app.route("/api/projects/<pid>/eta", methods=["GET"])
    def api_project_eta(pid):
        stages = load_stages(pid)

        # Load deps for critical-path ETA
        import openpyxl as _xl_eta
        _dp = CW_ROOT / "workflow_dependencies.xlsx"
        deps = {}
        if _dp.exists():
            try:
                _wb2 = _xl_eta.load_workbook(str(_dp), read_only=True, data_only=True)
                for _r2 in _wb2.active.iter_rows(min_row=2, values_only=True):
                    _s2 = str(_r2[0] or "").strip(); _d2 = str(_r2[1] or "").strip()
                    if _s2 and _d2:
                        deps.setdefault(_s2, [])
                        if _d2 not in deps[_s2]:
                            deps[_s2].append(_d2)
                _wb2.close()
            except Exception:
                pass

        stage_data = {}
        for st in stages:
            # Always key by stage_key ("baseline", "jreg" …) for consistency with dep graph
            sid     = str(st.get("stage_key", st["stage_id"])).strip()
            status  = st.get("status", "Pending")
            started = str(st.get("started_at") or "")
            avg     = _wf_get_eta(sid)

            if status == "Completed":
                stage_data[sid] = {"progress": 100, "remaining": 0, "avg_eta": avg}
            elif status == "In Progress" and started:
                try:
                    elapsed = (datetime.now() -
                               datetime.strptime(started, "%Y-%m-%d %H:%M:%S")).total_seconds()
                    progress  = min(99, int(elapsed / avg * 100)) if avg else 0
                    remaining = max(0.0, avg - elapsed) if avg else None
                    stage_data[sid] = {"progress": progress, "remaining": remaining,
                                       "avg_eta": avg, "elapsed": int(elapsed)}
                except Exception:
                    stage_data[sid] = {"progress": 0, "remaining": avg, "avg_eta": avg}
            elif status in ("Skipped",):
                stage_data[sid] = {"progress": 100, "remaining": 0, "avg_eta": avg}
            else:
                stage_data[sid] = {"progress": 0, "remaining": avg, "avg_eta": avg}

        # Workflow remaining via finish-time propagation through DAG
        sm_status = {str(s.get("stage_key", s["stage_id"])).strip(): s.get("status", "Pending") for s in stages}
        finish_memo = {}

        def _finish(sid, visiting=None):
            if sid in finish_memo:
                return finish_memo[sid]
            if visiting is None:
                visiting = set()
            if sid in visiting:
                return 0
            visiting.add(sid)
            if sm_status.get(sid) in ("Completed", "Skipped"):
                finish_memo[sid] = 0
                return 0
            own_rem = stage_data.get(sid, {}).get("remaining") or 0
            dep_finish = max((_finish(d, visiting.copy()) for d in deps.get(sid, [])), default=0)
            finish_memo[sid] = dep_finish + own_rem
            return finish_memo[sid]

        for _sid in (str(s.get("stage_key", s["stage_id"])).strip() for s in stages):
            _finish(_sid)

        workflow_remaining = max(finish_memo.values(), default=None)
        if workflow_remaining == 0:
            workflow_remaining = None

        return jsonify({
            "ok":                True,
            "stages":            stage_data,
            "workflow_remaining": workflow_remaining,
            "is_engine_running": pid in _WF_THREADS and _WF_THREADS[pid].is_alive(),
        })

    @app.route("/api/clone-workflow/stage-stats", methods=["GET"])
    def api_cw_stage_stats():
        """Return last 10 execution records per stage from WF_METRICS_FILE."""
        try:
            import openpyxl as _xl_ss
            with _wf_metrics_lock:
                if not WF_METRICS_FILE.exists():
                    return jsonify({"ok": True, "stages": {}})
                wb_ss = _xl_ss.load_workbook(str(WF_METRICS_FILE), read_only=True, data_only=True)
                ws_ss = wb_ss.active
                hdrs_ss = [str(ws_ss.cell(1, c).value or "").strip().lower()
                           for c in range(1, ws_ss.max_column + 1)]
                stages_out = {}
                for row_ss in ws_ss.iter_rows(min_row=2, values_only=True):
                    rd = {hdrs_ss[i]: (row_ss[i] if i < len(row_ss) else None)
                          for i in range(len(hdrs_ss))}
                    sid_ss = str(rd.get("stage_id") or "").strip()
                    if not sid_ss:
                        continue
                    stages_out.setdefault(sid_ss, [])
                    stages_out[sid_ss].append({
                        "duration_s":  round(float(rd["duration_seconds"]), 1) if rd.get("duration_seconds") is not None else None,
                        "recorded_at": str(rd.get("recorded_at") or ""),
                        "project_id":  str(rd.get("project_id") or ""),
                    })
                wb_ss.close()
            # Return only last 10 per stage (file already trimmed, but defensive)
            for sid_ss in stages_out:
                stages_out[sid_ss] = stages_out[sid_ss][-10:]
            summary = {}
            for sid_ss, entries in stages_out.items():
                durs = [e["duration_s"] for e in entries if e.get("duration_s") is not None]
                if durs:
                    summary[sid_ss] = {
                        "avg_s":  round(sum(durs) / len(durs), 1),
                        "min_s":  round(min(durs), 1),
                        "max_s":  round(max(durs), 1),
                        "count":  len(durs),
                    }
            return jsonify({"ok": True, "stages": stages_out, "summary": summary})
        except Exception as _e_ss:
            return jsonify({"ok": False, "error": str(_e_ss)}), 500

    @app.route("/api/clone-workflow/compare", methods=["GET"])
    def api_cw_compare():
        import json as _json_cmp
        try:
            _n_cmp = min(int(request.args.get("n", 10)), 20)
            _projs = load_projects()
            _projs = sorted(_projs, key=lambda p: int(str(p.get("pid") or 0) or 0), reverse=True)[:_n_cmp]
            _stage_order_cmp = [
                "jcj_baseline", "puc_baseline", "baseline", "remote_setup",
                "melissa_update", "melissa_gp_payor", "melissa_gp_classic",
                "clone", "clone_pr_gp", "jcj", "jreg", "rpb", "puc",
            ]
            _result_cmp = []
            for _proj in _projs:
                _pid_cmp = str(_proj.get("pid") or "").strip()
                try:
                    _ep_cmp = _json_cmp.loads(_proj.get("extra_params") or "{}")
                except Exception:
                    _ep_cmp = {}
                _rb_cmp = str(_ep_cmp.get("release_branch") or _proj.get("payor_version") or "").strip()
                _stages_list = load_stages(_pid_cmp)
                _stages_map  = {}
                for _s in _stages_list:
                    _sk = str(_s.get("stage_key") or _s.get("stage_id") or "").strip()
                    if _sk:
                        _stages_map[_sk] = {
                            "status": str(_s.get("status") or "").strip(),
                            "notes":  str(_s.get("notes")  or "").strip(),
                        }
                _result_cmp.append({
                    "pid":            _pid_cmp,
                    "ticket":         str(_proj.get("ticket") or "").strip(),
                    "release_branch": _rb_cmp,
                    "payor_version":  str(_proj.get("payor_version") or "").strip(),
                    "status":         str(_proj.get("status") or "").strip(),
                    "stages":         _stages_map,
                })
            return jsonify({"ok": True, "stages": _stage_order_cmp, "projects": _result_cmp})
        except Exception as _e_cmp:
            return jsonify({"ok": False, "error": str(_e_cmp)}), 500

    @app.route("/api/clone-workflow/runbook", methods=["GET"])
    def api_cw_runbook():
        try:
            import openpyxl as _xl_rb
            runbook_raw = {}
            _dp_rb = CW_ROOT / "workflow_dependencies.xlsx"
            if _dp_rb.exists():
                wb_rb = _xl_rb.load_workbook(str(_dp_rb), read_only=True, data_only=True)
                if "Runbook" in wb_rb.sheetnames:
                    ws_rb = wb_rb["Runbook"]
                    for row in ws_rb.iter_rows(min_row=2, values_only=True):
                        sid = str(row[0] or "").strip() if row else ""
                        sug = str(row[1] or "").strip() if len(row) > 1 else ""
                        if sid and sug:
                            runbook_raw.setdefault(sid, []).append(sug)
                wb_rb.close()
            failure_rates = {}
            try:
                _rb_projs = load_projects()
                _rb_projs = sorted(_rb_projs, key=lambda p: int(str(p.get("pid") or 0) or 0), reverse=True)[:10]
                for _rb_proj in _rb_projs:
                    _rb_pid = str(_rb_proj.get("pid") or "").strip()
                    _rb_stages = load_stages(_rb_pid)
                    for _rb_s in _rb_stages:
                        _rb_sk = str(_rb_s.get("stage_key") or _rb_s.get("stage_id") or "").strip()
                        _rb_st = str(_rb_s.get("status") or "").strip()
                        if not _rb_sk or _rb_st in ("Not Started", "Pending", "Skipped", ""):
                            continue
                        if _rb_sk not in failure_rates:
                            failure_rates[_rb_sk] = {"failed": 0, "reached": 0}
                        failure_rates[_rb_sk]["reached"] += 1
                        if _rb_st == "Failed":
                            failure_rates[_rb_sk]["failed"] += 1
            except Exception:
                pass
            _rb_stage_order = [
                "jcj_baseline", "puc_baseline", "baseline", "remote_setup",
                "melissa_update", "melissa_gp_payor", "melissa_gp_classic",
                "clone", "clone_pr_gp", "jcj", "jreg", "rpb", "puc",
            ]
            result_rb = {}
            all_rb_keys = set(list(runbook_raw.keys()) + list(failure_rates.keys()))
            for _rb_sk in _rb_stage_order:
                if _rb_sk in all_rb_keys:
                    result_rb[_rb_sk] = {
                        "suggestions":  runbook_raw.get(_rb_sk, []),
                        "failure_rate": failure_rates.get(_rb_sk),
                    }
            for _rb_sk in sorted(all_rb_keys - set(_rb_stage_order)):
                result_rb[_rb_sk] = {
                    "suggestions":  runbook_raw.get(_rb_sk, []),
                    "failure_rate": failure_rates.get(_rb_sk),
                }
            return jsonify({"ok": True, "runbook": result_rb})
        except Exception as _e_rb:
            return jsonify({"ok": False, "error": str(_e_rb)}), 500

    # ── Configuration Templates ───────────────────────────────────────────────
    _WF_TEMPLATES_COLS = ["template_name", "ticket", "release_branch",
                          "retry_count", "created_at", "extra_json"]

    @app.route("/api/clone-workflow/templates", methods=["GET"])
    def api_cw_templates_get():
        with _wf_templates_lock:
            try:
                import openpyxl as _xl_t
                _tp = CW_ROOT / "workflow_templates.xlsx"
                if not _tp.exists():
                    return jsonify({"ok": True, "templates": []})
                wb = _xl_t.load_workbook(str(_tp), read_only=True, data_only=True)
                ws = wb.active
                hdrs = [str(c.value or "").strip().lower()
                        for c in next(ws.iter_rows(min_row=1, max_row=1))]
                templates = []
                for row in ws.iter_rows(min_row=2, values_only=True):
                    if not any(row):
                        continue
                    r = {hdrs[i]: str(v or "") for i, v in enumerate(row) if i < len(hdrs)}
                    if r.get("template_name"):
                        templates.append(r)
                wb.close()
                return jsonify({"ok": True, "templates": templates})
            except Exception as _e_t:
                return jsonify({"ok": False, "error": str(_e_t)}), 500

    @app.route("/api/clone-workflow/templates", methods=["POST"])
    def api_cw_templates_save():
        data = request.get_json(force=True) or {}
        name = str(data.get("template_name") or "").strip()
        if not name:
            return jsonify({"ok": False, "error": "template_name required"}), 400
        with _wf_templates_lock:
            try:
                import openpyxl as _xl_t
                import json as _json_t
                from datetime import datetime as _dt_t
                _tp = CW_ROOT / "workflow_templates.xlsx"
                if not _tp.exists():
                    wb = _xl_t.Workbook(); ws = wb.active; ws.title = "Templates"
                    ws.append(_WF_TEMPLATES_COLS)
                    _save(wb, _tp)
                wb = _xl_t.load_workbook(str(_tp))
                ws = wb.active
                hdrs = [str(ws.cell(1, c).value or "").strip().lower()
                        for c in range(1, ws.max_column + 1)]
                col_idx = {h: i + 1 for i, h in enumerate(hdrs)}
                extra_json = _json_t.dumps(data.get("extra", {}))
                updated = False
                for row in ws.iter_rows(min_row=2):
                    if str(row[0].value or "").strip() == name:
                        if col_idx.get("ticket"):      row[col_idx["ticket"]       - 1].value = data.get("ticket", "")
                        if col_idx.get("release_branch"): row[col_idx["release_branch"] - 1].value = data.get("release_branch", "")
                        if col_idx.get("retry_count"): row[col_idx["retry_count"]   - 1].value = data.get("retry_count", "")
                        if col_idx.get("extra_json"):  row[col_idx["extra_json"]    - 1].value = extra_json
                        updated = True; break
                if not updated:
                    ws.append([
                        name,
                        data.get("ticket", ""),
                        data.get("release_branch", ""),
                        data.get("retry_count", ""),
                        _dt_t.now().strftime("%Y-%m-%d %H:%M:%S"),
                        extra_json,
                    ])
                _save(wb, _tp)
                return jsonify({"ok": True})
            except Exception as _e_t:
                return jsonify({"ok": False, "error": str(_e_t)}), 500

    @app.route("/api/clone-workflow/templates/<tpl_name>", methods=["DELETE"])
    def api_cw_templates_delete(tpl_name):
        with _wf_templates_lock:
            try:
                import openpyxl as _xl_t
                _tp = CW_ROOT / "workflow_templates.xlsx"
                if not _tp.exists():
                    return jsonify({"ok": True})
                wb = _xl_t.load_workbook(str(_tp))
                ws = wb.active
                header_row = list(ws.iter_rows(min_row=1, max_row=1, values_only=True))[0]
                rows_to_keep = [header_row]
                for row in ws.iter_rows(min_row=2, values_only=True):
                    if str(row[0] or "").strip() != tpl_name:
                        rows_to_keep.append(row)
                ws.delete_rows(1, ws.max_row)
                for r in rows_to_keep:
                    ws.append(list(r))
                _save(wb, _tp)
                return jsonify({"ok": True})
            except Exception as _e_t:
                return jsonify({"ok": False, "error": str(_e_t)}), 500

    @app.route("/api/projects/<int:pid>/release-notes", methods=["GET"])
    def api_project_release_notes(pid):
        """Fetch commits for the project's release branch and generate a formatted draft."""
        import re as _re_rn
        import requests as _rq_rn
        from datetime import datetime as _dt_rn

        # ── Load project row ──────────────────────────────────────────────────
        try:
            projs = load_projects()
            proj  = next((p for p in projs if str(p.get("pid") or "").strip() == str(pid)), None)
            if not proj:
                return jsonify({"ok": False, "error": f"Project {pid} not found"}), 404
        except Exception as _e_rn0:
            return jsonify({"ok": False, "error": str(_e_rn0)}), 500

        import json as _js_rn
        try:
            ep = _js_rn.loads(str(proj.get("extra_params") or "{}"))
        except Exception:
            ep = {}

        release_branch = (ep.get("release_branch") or proj.get("release_branch") or "").strip()
        if not release_branch:
            return jsonify({"ok": False, "error": "No release_branch configured for this project"}), 400

        # ── GitHub credentials + repo ─────────────────────────────────────────
        gh_token = _scm_github_token()
        gh_hdrs  = {"Authorization": f"token {gh_token}", "Accept": "application/vnd.github.v3+json"} if gh_token else {"Accept": "application/vnd.github.v3+json"}

        repos      = _scm_read_git_config()
        payor_url  = next((r["repo_url"] for r in repos if r["app"] == "payor"), "")
        if not payor_url:
            return jsonify({"ok": False, "error": "GitHub payor repo URL not configured in git_config.xlsx"}), 400

        _m_rn = _re_rn.search(r"github\.com[:/]([^/]+)/([^/.]+?)(?:\.git)?$", payor_url)
        if not _m_rn:
            return jsonify({"ok": False, "error": f"Cannot parse owner/repo from: {payor_url}"}), 400
        owner, repo = _m_rn.group(1), _m_rn.group(2)

        # ── Resolve branch name (try release-{ver} then release/{ver}) ────────
        ver_clean  = release_branch.lstrip("release-").lstrip("release/")
        candidates = [f"release-{ver_clean}", f"release/{ver_clean}", release_branch]
        branch_name = ""
        for _br_rn in candidates:
            try:
                _r_br = _rq_rn.get(f"https://api.github.com/repos/{owner}/{repo}/branches/{_br_rn}",
                                    headers=gh_hdrs, timeout=8, verify=False)
                if _r_br.status_code == 200:
                    branch_name = _br_rn
                    break
            except Exception:
                pass
        if not branch_name:
            return jsonify({"ok": False, "error": f"Branch not found on GitHub for release '{release_branch}' (tried: {', '.join(candidates)})"}), 404

        # ── Fetch commits ─────────────────────────────────────────────────────
        try:
            _r_cm = _rq_rn.get(
                f"https://api.github.com/repos/{owner}/{repo}/commits",
                headers=gh_hdrs,
                params={"sha": branch_name, "per_page": 50},
                timeout=15, verify=False
            )
            if _r_cm.status_code != 200:
                return jsonify({"ok": False, "error": f"GitHub API error {_r_cm.status_code}: {_r_cm.text[:200]}"}), 502
            raw_commits = _r_cm.json()
        except Exception as _e_rn1:
            return jsonify({"ok": False, "error": f"Failed to fetch commits: {_e_rn1}"}), 502

        # ── Parse + categorise ─────────────────────────────────────────────────
        _CC_CATEGORIES = {
            "feat":     "Features",
            "fix":      "Bug Fixes",
            "perf":     "Performance",
            "refactor": "Refactoring",
            "docs":     "Documentation",
            "test":     "Tests",
            "chore":    "Chores",
            "ci":       "CI / Build",
            "style":    "Style",
        }
        _CC_RE    = _re_rn.compile(r"^(feat|fix|perf|refactor|docs|test|chore|ci|style)(\([^)]+\))?(!)?:\s*(.+)", _re_rn.IGNORECASE)
        _JIRA_RE  = _re_rn.compile(r"^[A-Z]+-\d+:?\s*", _re_rn.IGNORECASE)
        _MERGE_RE = _re_rn.compile(r"^Merge ", _re_rn.IGNORECASE)

        categorised = {}  # {category_name: [{sha, subject, author}]}

        for _c in raw_commits:
            msg    = (_c.get("commit") or {}).get("message") or ""
            subj   = msg.split("\n")[0].strip()
            author = ((_c.get("commit") or {}).get("author") or {}).get("name") or ""
            sha    = (_c.get("sha") or "")[:7]

            if _MERGE_RE.match(subj):
                continue  # skip merge commits

            # strip leading JIRA ticket
            subj_clean = _JIRA_RE.sub("", subj).strip()

            _m_cc = _CC_RE.match(subj_clean) or _CC_RE.match(subj)
            if _m_cc:
                cat    = _CC_CATEGORIES.get(_m_cc.group(1).lower(), "Other Changes")
                subj_final = _m_cc.group(4).strip()
                subj_final = _JIRA_RE.sub("", subj_final).strip()
            else:
                cat        = "Other Changes"
                subj_final = subj_clean or subj

            entry = {"sha": sha, "subject": subj_final, "author": author}
            categorised.setdefault(cat, []).append(entry)

        # ── Format draft text ─────────────────────────────────────────────────
        _CAT_ORDER = ["Features", "Bug Fixes", "Performance", "Refactoring",
                      "Documentation", "Tests", "Chores", "CI / Build", "Style", "Other Changes"]

        total_count = sum(len(v) for v in categorised.values())
        lines = [
            f"Release Notes — {release_branch}",
            f"Generated: {_dt_rn.utcnow().strftime('%Y-%m-%d %H:%M UTC')}",
            f"Branch: {branch_name}",
            f"Commits: {total_count}",
            "",
        ]
        for cat in _CAT_ORDER:
            entries = categorised.get(cat)
            if not entries:
                continue
            lines.append(f"## {cat}")
            for e in entries:
                author_str = f" — {e['author']}" if e["author"] else ""
                lines.append(f"- {e['subject']} (#{e['sha']}){author_str}")
            lines.append("")

        lines += [
            "---",
            f"Source: https://github.com/{owner}/{repo}/commits/{branch_name}",
        ]

        draft = "\n".join(lines)

        return jsonify({
            "ok":            True,
            "release_branch": release_branch,
            "branch_name":   branch_name,
            "commit_count":  total_count,
            "draft":         draft,
            "categories":    categorised,
        })

    @app.route("/api/workflow/dependencies", methods=["GET"])
    def api_workflow_deps_get():
        import openpyxl as _xl
        path = CW_ROOT / "workflow_dependencies.xlsx"
        deps        = {}
        stage_params = {}
        if path.exists():
            try:
                wb = _xl.load_workbook(str(path), read_only=True, data_only=True)
                # Dependencies sheet
                ws = wb.active
                for row in ws.iter_rows(min_row=2, values_only=True):
                    sid = str(row[0] or "").strip()
                    dep = str(row[1] or "").strip()
                    if sid and dep:
                        deps.setdefault(sid, [])
                        if dep not in deps[sid]:
                            deps[sid].append(dep)
                # Stage Parameters sheet
                if "Stage Parameters" in wb.sheetnames:
                    ws_p = wb["Stage Parameters"]
                    for row in ws_p.iter_rows(min_row=2, values_only=True):
                        sid         = str(row[0] or "").strip()
                        param_name  = str(row[1] or "").strip()
                        label       = str(row[2] or "").strip()
                        required    = str(row[3] or "").strip().lower() in ("1", "true", "yes")
                        placeholder = str(row[4] or "").strip()
                        if sid and param_name:
                            stage_params.setdefault(sid, [])
                            stage_params[sid].append({
                                "param_name":  param_name,
                                "label":       label,
                                "required":    required,
                                "placeholder": placeholder,
                            })
                # Stage Config sheet (timeout_s, parallel_group per stage)
                stage_config = {}
                if "Stage Config" in wb.sheetnames:
                    ws_sc = wb["Stage Config"]
                    _sc_hdrs = [str(ws_sc.cell(1, c).value or "").strip().lower()
                                for c in range(1, ws_sc.max_column + 1)]
                    for row in ws_sc.iter_rows(min_row=2, values_only=True):
                        _sc_d = {_sc_hdrs[i]: row[i] for i in range(min(len(_sc_hdrs), len(row)))}
                        sid = str(_sc_d.get("stage_id") or "").strip()
                        ts  = _sc_d.get("timeout_s")
                        pg  = str(_sc_d.get("parallel_group") or "").strip() or None
                        if sid:
                            stage_config[sid] = {
                                "timeout_s":      float(ts) if ts is not None else None,
                                "parallel_group": pg,
                            }
                # Runbook sheet (stage_id, suggestion)
                runbook_out = {}
                if "Runbook" in wb.sheetnames:
                    ws_rk = wb["Runbook"]
                    for row in ws_rk.iter_rows(min_row=2, values_only=True):
                        sid = str(row[0] or "").strip() if row else ""
                        sug = str(row[1] or "").strip() if len(row) > 1 else ""
                        if sid and sug:
                            runbook_out.setdefault(sid, []).append(sug)
                wb.close()
            except Exception as _e:
                return jsonify({"ok": False, "error": str(_e)})
        else:
            stage_config = {}
            runbook_out  = {}
        return jsonify({"ok": True, "dependencies": deps, "stage_params": stage_params,
                        "stage_config": stage_config, "runbook": runbook_out})

    @app.route("/api/workflow/dependencies", methods=["POST"])
    def api_workflow_deps_post():
        import openpyxl as _xl
        data         = request.get_json() or {}
        deps         = data.get("dependencies") or {}
        stage_params = data.get("stage_params") or {}
        stage_config = data.get("stage_config") or {}
        CW_ROOT.mkdir(parents=True, exist_ok=True)
        path = CW_ROOT / "workflow_dependencies.xlsx"
        wb = _xl.Workbook()
        ws = wb.active
        ws.title = "Dependencies"
        ws.append(["stage_id", "depends_on"])
        for sid, dep_list in deps.items():
            for dep in (dep_list or []):
                ws.append([sid, dep])
        ws_p = wb.create_sheet("Stage Parameters")
        ws_p.append(["stage_id", "param_name", "label", "required", "placeholder"])
        for sid, params in stage_params.items():
            for p in (params or []):
                ws_p.append([sid, p.get("param_name", ""), p.get("label", ""),
                              "1" if p.get("required") else "0", p.get("placeholder", "")])
        ws_sc = wb.create_sheet("Stage Config")
        ws_sc.append(["stage_id", "timeout_s", "parallel_group"])
        for sid, cfg in stage_config.items():
            ts = cfg.get("timeout_s")
            pg = cfg.get("parallel_group") or None
            ws_sc.append([sid, float(ts) if ts is not None and ts != "" else None, pg])
        runbook_in = data.get("runbook") or {}
        ws_rk = wb.create_sheet("Runbook")
        ws_rk.append(["stage_id", "suggestion"])
        for sid, suggestions in runbook_in.items():
            for sug in (suggestions or []):
                sug = str(sug).strip()
                if sug:
                    ws_rk.append([sid, sug])
        wb.save(str(path))
        return jsonify({"ok": True})

    @app.route("/api/tools/jbaseline/jobs", methods=["GET"])
    def api_jbaseline_jobs():
        app_name = request.args.get("app", "Payor")
        jobs = _get_jbaseline_jobs(app_name)
        return jsonify({"ok": True, "jobs": jobs})

    @app.route("/api/clone-workflow/pom-version", methods=["GET"])
    def api_cw_pom_version():
        """Return the Payor Release Version by reading pom.xml from the release branch.

        Query param: branch  e.g. "26.2.1.0.1" or "release/26.2.1.0.1"
        Reads pom.xml from GitHub branch release-{branch}, strips -SNAPSHOT.
        Also returns BC/DU prefix hints so the caller can populate those fields in one call.
        """
        import re as _re_pv
        branch = request.args.get("branch", "").strip().lstrip("release/").lstrip("release-")
        if not branch:
            return jsonify({"ok": False, "error": "branch required"})
        hints = _fetch_pom_hints_for_tool(JB_ROOT, branch)
        pom_version = hints.get("pom_version", "")
        if not pom_version:
            return jsonify({"ok": False,
                            "error": "Could not read pom.xml — check GitHub config/token or branch name"})
        return jsonify({
            "ok":                   True,
            "payor_release_version": pom_version,
            "hints":                hints,
        })

    @app.route("/api/projects/<pid>/stages/<stage_id>", methods=["PATCH"])
    def api_patch_stage(pid, stage_id):
        _patch_ps = request.get_json() or {}
        _new_status_ps = str(_patch_ps.get("status") or "").strip()
        update_stage(pid, stage_id, _patch_ps)
        # Persist skip/unskip decision in extra_params.skipped_stages for cross-run durability
        if _new_status_ps in ("Skipped", "Pending"):
            try:
                import json as _json_ps, openpyxl as _xl_ps
                _all_stages_ps = load_stages(pid)
                _st_ps = next(
                    (s for s in _all_stages_ps if str(s.get("stage_id", "")) == str(stage_id)),
                    None)
                _sk_key_ps = str(
                    (_st_ps or {}).get("stage_key") or (_st_ps or {}).get("stage_id") or ""
                ).strip()
                if _sk_key_ps:
                    with _cw_projects_lock, _cw_projects_filelock():
                        _wb_ps = _xl_ps.load_workbook(str(PROJECTS))
                        _ws_ps = _wb_ps.active
                        _hdr_ps = [str(_ws_ps.cell(1, c).value or "").strip().lower()
                                   for c in range(1, _ws_ps.max_column + 1)]
                        _cm_ps = {h: i for i, h in enumerate(_hdr_ps)}
                        for _row_ps in _ws_ps.iter_rows(min_row=2):
                            if str(_row_ps[0].value or "").strip() == str(pid):
                                _ep_col = _cm_ps.get("extra_params", -1)
                                if _ep_col < 0:
                                    break
                                _ep_cell = _row_ps[_ep_col]
                                try:
                                    _ep_ps = _json_ps.loads(_ep_cell.value or "{}")
                                except Exception:
                                    _ep_ps = {}
                                _sl_ps = list(_ep_ps.get("skipped_stages") or [])
                                if _new_status_ps == "Skipped":
                                    if _sk_key_ps not in _sl_ps:
                                        _sl_ps.append(_sk_key_ps)
                                else:  # Pending = unskip
                                    _sl_ps = [x for x in _sl_ps if x != _sk_key_ps]
                                _ep_ps["skipped_stages"] = _sl_ps
                                _ep_cell.value = _json_ps.dumps(_ep_ps)
                                break
                        _save(_wb_ps, PROJECTS)
            except Exception:
                pass
        sync_project_progress(pid)
        # Wake the engine so it re-evaluates dependencies immediately
        import threading as _thr_ps
        if pid in _WF_THREADS and _WF_THREADS[pid].is_alive():
            if pid not in _WF_WAKE_EVENTS:
                _WF_WAKE_EVENTS[pid] = _thr_ps.Event()
            _WF_WAKE_EVENTS[pid].set()
        return jsonify({"ok": True})

    @app.route("/api/projects/<pid>/poke", methods=["POST"])
    def api_poke_project(pid):
        """Wake the engine for this project so it re-evaluates stage dependencies immediately."""
        import threading as _thr_poke
        if pid in _WF_THREADS and _WF_THREADS[pid].is_alive():
            if pid not in _WF_WAKE_EVENTS:
                _WF_WAKE_EVENTS[pid] = _thr_poke.Event()
            _WF_WAKE_EVENTS[pid].set()
            return jsonify({"ok": True, "woken": True})
        return jsonify({"ok": True, "woken": False, "message": "Engine not running for this project"})

    @app.route("/api/projects/<pid>/stages/<stage_id>/retrigger", methods=["POST"])
    def api_retrigger_stage(pid, stage_id):
        import requests as _req_rt, openpyxl as _xl_rt, json as _json_rt

        stages = load_stages(pid)
        stage  = next((s for s in stages if str(s.get("stage_id", "")) == str(stage_id)), None)
        if not stage:
            return jsonify({"ok": False, "error": "Stage not found"}), 404

        stage_key    = str(stage.get("stage_key", "")).strip()
        old_tool_pid = str(stage.get("tool_pid", "")).strip()

        # stage_key → tool name used by DELETE /api/tools/<tool>/projects/<pid>
        _SK_TOOL = {
            "baseline":           "jbaseline",
            "jreg":               "jreg",
            "remote_setup":       "remote-setup",
            "melissa_gp_payor":   "gp-run",
            "melissa_gp_classic": "gp-run",
            "clone_pr_gp":        "gp-run",
        }

        # ── Baseline / JReg: smart retry — ask the tool to retrigger its own failed jobs ──
        if stage_key in ("baseline", "jreg") and old_tool_pid:
            _proj_smr = next((r for r in load_projects() if r.get("pid") == pid), {})
            try:
                _ep_smr = _json_rt.loads(_proj_smr.get("extra_params") or "{}")
            except Exception:
                _ep_smr = {}
            _app_smr  = _ep_smr.get("app", "Payor")
            _port_smr = int(_IDP_CFG.get("server_port", 5556))
            _base_smr = f"http://127.0.0.1:{_port_smr}"
            _tool_smr = "jbaseline" if stage_key == "baseline" else "jreg"
            _rfj_ep   = f"{_base_smr}/api/tools/{_tool_smr}/projects/{old_tool_pid}/retrigger-failed-jobs"
            try:
                _rr = _req_rt.post(_rfj_ep, json={"app": _app_smr, "cw_pid": pid}, timeout=30).json()
                _retriggered = _rr.get("retriggered", [])
                _errs        = _rr.get("errors", [])
                if _rr.get("ok") and _retriggered:
                    _note = f"Retrying failed jobs: {', '.join(_retriggered)}"
                    if _errs:
                        _note += f" | Errors: {'; '.join(_errs)}"
                    update_stage(pid, stage_id, {
                        "status": "In Progress",
                        "notes":  _note,
                        "completed_at": "",
                    })
                    # Reset project to In Progress
                    if PROJECTS.exists():
                        try:
                            with _cw_projects_lock, _cw_projects_filelock():
                                _wb_smr = _xl_rt.load_workbook(str(PROJECTS))
                                _ws_smr = _wb_smr.active
                                _hd_smr = [str(_ws_smr.cell(1, c).value or "").strip().lower()
                                           for c in range(1, _ws_smr.max_column + 1)]
                                _cm_smr = {h: i for i, h in enumerate(_hd_smr, 1)}
                                for _row_smr in _ws_smr.iter_rows(min_row=2):
                                    if str(_row_smr[0].value or "").strip() == str(pid).strip():
                                        if "status" in _cm_smr:
                                            _row_smr[_cm_smr["status"] - 1].value = "In Progress"
                                        if "completed_at" in _cm_smr:
                                            _row_smr[_cm_smr["completed_at"] - 1].value = ""
                                        break
                                _save(_wb_smr, PROJECTS)
                        except Exception:
                            pass
                    # Re-attach engine so it resumes polling this stage
                    _proj_smr2 = next((r for r in load_projects() if r.get("pid") == pid), None)
                    if _proj_smr2:
                        _polling_smr = _cw_read_poll_interval()
                        try:
                            _ep2_smr = _json_rt.loads(_proj_smr2.get("extra_params") or "{}")
                        except Exception:
                            _ep2_smr = {}
                        _pp_smr = {
                            **_ep2_smr,
                            "payor_version":                  _proj_smr2.get("payor_version", ""),
                            "bluecard_config_version_prefix": _proj_smr2.get("bluecard_config_version_prefix", ""),
                            "datauniverse_version_prefix":    _proj_smr2.get("datauniverse_version_prefix", ""),
                            "app":                            _ep2_smr.get("app", "Payor"),
                        }
                        _dep_path_smr = CW_ROOT / "workflow_dependencies.xlsx"
                        _deps_smr = {}
                        if _dep_path_smr.exists():
                            try:
                                _wb_dep_smr = _xl_rt.load_workbook(str(_dep_path_smr), read_only=True, data_only=True)
                                for _r in _wb_dep_smr.active.iter_rows(min_row=2, values_only=True):
                                    _s2 = str(_r[0] or "").strip(); _d2 = str(_r[1] or "").strip()
                                    if _s2 and _d2:
                                        _deps_smr.setdefault(_s2, [])
                                        if _d2 not in _deps_smr[_s2]:
                                            _deps_smr[_s2].append(_d2)
                                _wb_dep_smr.close()
                            except Exception:
                                pass
                        _wf_tr_smr, _wf_ch_smr = _build_wf_fns(pid, _pp_smr)
                        if pid not in _WF_THREADS or not _WF_THREADS[pid].is_alive():
                            _abort_ev_smr = _threading_wf.Event()
                            _WF_ABORT_EVENTS[pid] = _abort_ev_smr
                            _t_smr = _threading_wf.Thread(
                                target=_wf_run_engine,
                                args=(pid, _polling_smr, _deps_smr, _wf_tr_smr, _wf_ch_smr,
                                      {"baseline", "jreg", "jcj", "jcj_baseline", "remote_setup", "melissa_update", "clone_pr_gp",
                                       "melissa_gp_payor", "melissa_gp_classic", "rpb", "puc_baseline", "puc"}, _pp_smr),
                                daemon=True,
                            )
                            _t_smr.start()
                            _WF_THREADS[pid] = _t_smr
                    return jsonify({"ok": True, "retriggered": _retriggered, "errors": _errs})
                # ok=True but no jobs retriggered (none failed) — still don't full-rerun
                return jsonify({"ok": True, "retriggered": [], "errors": _errs,
                                "message": _rr.get("message", "No failed jobs found")})
            except Exception as _smr_ex:
                # Smart retry call failed — return error; do NOT fall through to full re-run
                # which would delete the tool project and retrigger all jobs from scratch.
                return jsonify({"ok": False, "error": f"Smart retry failed: {_smr_ex}"}), 500

        # 1. Delete old tool project (best-effort)
        if old_tool_pid:
            _del_tool = _SK_TOOL.get(stage_key)
            if _del_tool:
                _port_rt = int(_IDP_CFG.get("server_port", 5556))
                _base_rt = f"http://127.0.0.1:{_port_rt}"
                _proj_rt = next((r for r in load_projects() if r.get("pid") == pid), {})
                try:
                    _ep_rt = _json_rt.loads(_proj_rt.get("extra_params") or "{}") if _proj_rt.get("extra_params") else {}
                except Exception:
                    _ep_rt = {}
                _app_rt = _ep_rt.get("app", "Payor")
                try:
                    _req_rt.delete(
                        f"{_base_rt}/api/tools/{_del_tool}/projects/{old_tool_pid}",
                        params={"app": _app_rt}, timeout=10)
                except Exception:
                    pass

        # 2. Reset the failed stage to Pending (clear tool_pid and timestamps)
        update_stage(pid, stage_id, {
            "tool_pid": "", "status": "Pending",
            "started_at": "", "completed_at": "", "notes": "",
        })

        # 3. Reset all Aborted stages to Pending (they cascaded from this failure)
        for _s in stages:
            if str(_s.get("stage_id", "")) != str(stage_id) and _s.get("status") == "Aborted":
                update_stage(pid, _s["stage_id"], {"status": "Pending", "notes": ""})

        # 4. Reset project status to In Progress
        if PROJECTS.exists():
            try:
                with _cw_projects_lock, _cw_projects_filelock():
                    _wb_rt = _xl_rt.load_workbook(str(PROJECTS))
                    _ws_rt = _wb_rt.active
                    _hd_rt = [str(_ws_rt.cell(1, c).value or "").strip().lower()
                              for c in range(1, _ws_rt.max_column + 1)]
                    _cm_rt = {h: i for i, h in enumerate(_hd_rt, 1)}
                    for _row_rt in _ws_rt.iter_rows(min_row=2):
                        if str(_row_rt[0].value or "").strip() == str(pid).strip():
                            if "status" in _cm_rt:
                                _row_rt[_cm_rt["status"] - 1].value = "In Progress"
                            if "completed_at" in _cm_rt:
                                _row_rt[_cm_rt["completed_at"] - 1].value = ""
                            break
                    _save(_wb_rt, PROJECTS)
            except Exception:
                pass

        # 5. Restart workflow engine
        proj_rt = next((r for r in load_projects() if r.get("pid") == pid), None)
        if proj_rt:
            polling_s_rt = _cw_read_poll_interval()
            try:
                _ep2_rt = _json_rt.loads(proj_rt.get("extra_params") or "{}") if proj_rt.get("extra_params") else {}
            except Exception:
                _ep2_rt = {}
            proj_params_rt = {
                **_ep2_rt,
                "payor_version":                  proj_rt.get("payor_version", ""),
                "bluecard_config_version_prefix": proj_rt.get("bluecard_config_version_prefix", ""),
                "datauniverse_version_prefix":    proj_rt.get("datauniverse_version_prefix", ""),
                "app":                            _ep2_rt.get("app", "Payor"),
            }
            _dep_path_rt = CW_ROOT / "workflow_dependencies.xlsx"
            deps_rt = {}
            if _dep_path_rt.exists():
                try:
                    _wb_dep = _xl_rt.load_workbook(str(_dep_path_rt), read_only=True, data_only=True)
                    for _r in _wb_dep.active.iter_rows(min_row=2, values_only=True):
                        _s2 = str(_r[0] or "").strip(); _d2 = str(_r[1] or "").strip()
                        if _s2 and _d2:
                            deps_rt.setdefault(_s2, [])
                            if _d2 not in deps_rt[_s2]:
                                deps_rt[_s2].append(_d2)
                    _wb_dep.close()
                except Exception:
                    pass
            _wf_tr, _wf_ch = _build_wf_fns(pid, proj_params_rt)
            if pid not in _WF_THREADS or not _WF_THREADS[pid].is_alive():
                _abort_ev = _threading_wf.Event()
                _WF_ABORT_EVENTS[pid] = _abort_ev
                t = _threading_wf.Thread(
                    target=_wf_run_engine,
                    args=(pid, polling_s_rt, deps_rt, _wf_tr, _wf_ch,
                          {"baseline", "jreg", "jcj", "jcj_baseline", "remote_setup", "melissa_update", "clone_pr_gp",
                           "melissa_gp_payor", "melissa_gp_classic", "rpb", "puc_baseline", "puc"}, proj_params_rt),
                    daemon=True,
                )
                t.start()
                _WF_THREADS[pid] = t

        return jsonify({"ok": True})

    # ── Docker API ────────────────────────────────────────────────────────────
    _DOCKER_CMDS = {"startdocker", "setupservers", "startservers",
                    "stopservers", "restartservers", "restartonly", "deleteservers"}

    @app.route("/api/docker/states", methods=["GET"])
    def api_docker_states():
        return jsonify(get_docker_states())

    @app.route("/api/docker/status", methods=["GET"])
    def api_docker_status():
        import subprocess as _sub
        try:
            r = _sub.run(
                ["docker", "info"],
                capture_output=True, text=True, timeout=5,
                creationflags=0x08000000,
            )
            return jsonify({"ok": True, "running": r.returncode == 0})
        except Exception:
            return jsonify({"ok": True, "running": False})

    def _docker_project_cmd(cmd, project):
        """Run a lifecycle command scoped to a single Docker Compose project."""
        import subprocess as _sub, json as _json
        from datetime import datetime as _dt
        _cflags = 0x08000000  # CREATE_NO_WINDOW on Windows

        def _ts(): return _dt.now().strftime('%Y-%m-%d %H:%M:%S')
        def _run(*args, timeout=120):
            r = _sub.run(list(args), capture_output=True, text=True, timeout=timeout,
                         encoding='utf-8', errors='replace', creationflags=_cflags)
            return r.returncode == 0, (r.stdout + r.stderr).strip()

        # List containers + discover compose file for this project
        try:
            r = _sub.run(
                ['docker', 'ps', '-a', '--filter', f'label=com.docker.compose.project={project}',
                 '--format', '{{json .}}'],
                capture_output=True, text=True, timeout=15, creationflags=_cflags)
            containers, compose_file = [], None
            for line in r.stdout.strip().splitlines():
                try:
                    obj = _json.loads(line.strip())
                    name = obj.get('Names', '')
                    labels = {}
                    for part in (obj.get('Labels') or '').split(','):
                        if '=' in part:
                            k, _, v = part.partition('=')
                            labels[k.strip()] = v.strip()
                    if name:
                        containers.append({'name': name, 'state': (obj.get('State') or '').lower()})
                    if not compose_file:
                        cf = labels.get('com.docker.compose.project.config_files', '')
                        if cf:
                            compose_file = cf.split(',')[0].strip()
                except Exception:
                    pass
        except Exception as e:
            return False, f"[{_ts()}] Failed to list containers for project '{project}': {e}"

        names   = [c['name'] for c in containers]
        running = [c['name'] for c in containers if c['state'] == 'running']
        stopped = [c['name'] for c in containers if c['state'] != 'running']
        lines   = [f"[{_ts()}] Project: {project}  |  containers: {len(names)}  running: {len(running)}  stopped: {len(stopped)}"]

        def _compose(*args):
            base = ['docker', 'compose', '-p', project]
            if compose_file:
                base += ['-f', compose_file]
            return _run(*base, *args)

        ok = True
        if cmd == 'startservers':
            if not names:
                ok, o = _compose('up', '-d')
            elif stopped:
                ok, o = _run('docker', 'start', *stopped)
                lines.append(f"Started: {', '.join(stopped)}")
            else:
                o = "All containers already running."
            lines.append(o)

        elif cmd == 'stopservers':
            if running:
                ok, o = _run('docker', 'stop', *running)
                lines.append(f"Stopped: {', '.join(running)}")
                lines.append(o)
            else:
                lines.append("No running containers to stop.")

        elif cmd == 'restartonly':
            if running:
                _, o1 = _run('docker', 'stop', *running); lines.append(o1)
                ok, o2 = _run('docker', 'start', *running); lines.append(o2)
            else:
                lines.append("No running containers to restart.")

        elif cmd == 'setupservers':
            ok, o = _compose('up', '-d')
            lines.append(o)

        elif cmd == 'restartservers':
            _, o1 = _compose('stop');  lines.append(o1)
            _, o2 = _compose('down');  lines.append(o2)
            ok, o3 = _compose('up', '-d'); lines.append(o3)

        elif cmd == 'deleteservers':
            if running:
                _, o1 = _run('docker', 'stop', *running); lines.append(o1)
            if names:
                ok, o2 = _compose('down'); lines.append(o2)
            else:
                lines.append(f"No containers found for project '{project}'.")

        else:
            return False, f"Command '{cmd}' not supported for project-scoped operations"

        return ok, '\n'.join(lines)

    @app.route("/api/docker/run", methods=["POST"])
    def api_docker_run():
        body    = request.get_json() or {}
        cmd     = body.get("cmd", "").strip()
        project = body.get("project", "").strip()
        if cmd not in _DOCKER_CMDS:
            return jsonify({"error": f"Unknown command: {cmd}"}), 400
        if project and cmd != 'startdocker':
            ok, out = _docker_project_cmd(cmd, project)
        else:
            ok, out = _run_ps1(cmd)
        return jsonify({"ok": ok, "output": out})

    @app.route("/api/docker/states", methods=["POST"])
    def api_docker_save():
        name = (request.get_json() or {}).get("name", "").strip()
        if not name:
            return jsonify({"error": "name required"}), 400
        ok, out = _run_ps1("save_docker_state", [name], timeout=300)
        return jsonify({"ok": ok, "output": out})

