    @app.route("/api/docker/states/<name>", methods=["DELETE"])
    def api_docker_remove(name):
        import subprocess as _sp
        state_path = LD_STATE_DIR / name
        if not state_path.exists() or not state_path.is_dir():
            return jsonify({"ok": False, "output": f"State '{name}' not found at:\n       {state_path}"})
        # Use PowerShell Remove-Item which handles read-only and locked files on Windows
        ps_cmd = f'Remove-Item -LiteralPath "{state_path}" -Recurse -Force -ErrorAction Stop'
        try:
            result = _sp.run(
                ['powershell', '-NoLogo', '-NonInteractive', '-Command', ps_cmd],
                capture_output=True, text=True, timeout=120
            )
            if result.returncode != 0:
                err = (result.stderr or result.stdout or "Unknown error").strip()
                return jsonify({"ok": False, "output": f"Failed to remove '{name}': {err}"})
            # Verify fully removed
            if state_path.exists():
                return jsonify({"ok": False, "output": f"Directory still exists after removal — files may be locked by Docker"})
            return jsonify({"ok": True, "output": f"Removed state '{name}'"})
        except Exception as e:
            return jsonify({"ok": False, "output": f"Failed to remove '{name}': {e}"})

    @app.route("/api/docker/containers", methods=["GET"])
    def api_docker_containers():
        import subprocess as _sub, json as _json
        try:
            r = _sub.run(
                ["docker", "ps", "-a", "--format", "{{json .}}"],
                capture_output=True, text=True, timeout=15,
                creationflags=0x08000000,
            )
            containers = []
            for line in r.stdout.strip().splitlines():
                line = line.strip()
                if not line:
                    continue
                try:
                    obj = _json.loads(line)
                    # Parse Labels string "k=v,k=v,..." into a dict
                    labels_str = obj.get("Labels", "") or ""
                    labels = {}
                    for part in labels_str.split(","):
                        if "=" in part:
                            k, _, v = part.partition("=")
                            labels[k.strip()] = v.strip()
                    containers.append({
                        "id":              obj.get("ID", ""),
                        "name":            obj.get("Names", ""),
                        "image":           obj.get("Image", ""),
                        "status":          obj.get("Status", ""),
                        "state":           (obj.get("State", "") or "").lower(),
                        "ports":           obj.get("Ports", ""),
                        "networks":        obj.get("Networks", ""),
                        "compose_project": labels.get("com.docker.compose.project", ""),
                        "compose_service": labels.get("com.docker.compose.service", ""),
                    })
                except Exception:
                    pass
            return jsonify({"ok": True, "containers": containers})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

