    @app.route("/api/docker/compose/download", methods=["POST"])
    def api_docker_compose_download():
        import urllib.request as _req
        body = request.get_json() or {}
        url = (body.get("url") or "").strip()
        local_path = (body.get("local_path") or "").strip()
        if not url:
            return jsonify({"ok": False, "error": "url is required"})
        if not local_path:
            return jsonify({"ok": False, "error": "local_path is required"})
        try:
            import pathlib as _pl
            dest = _pl.Path(local_path)
            dest.parent.mkdir(parents=True, exist_ok=True)
            with _req.urlopen(url, timeout=30) as resp:
                content = resp.read()
            dest.write_bytes(content)
            return jsonify({"ok": True, "bytes": len(content)})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    _COMPOSE_FILE = str(Path.home() / "dockerVM" / "dockerPOCArtifacts" / "dockerCompose" / "compose_with_tomcat.yaml")
    _COMPOSE_CONFIG_XLSX = LD_ROOT / "config.xlsx"
    _COMPOSE_DIR_KEY     = "compose_download_dir"
    _COMPOSE_DIR_DEFAULT = str(LD_ROOT / "dockercompose")

    def _read_compose_config() -> dict:
        import openpyxl as _xl
        cfg = {}
        try:
            wb = _xl.load_workbook(str(_COMPOSE_CONFIG_XLSX), data_only=True)
            ws = wb.active
            for row in ws.iter_rows(min_row=2, values_only=True):
                if row[0] and row[1] is not None:
                    cfg[str(row[0])] = str(row[1])
        except FileNotFoundError:
            pass
        except Exception as e:
            print(f"[compose-config] read error: {e}")
        return cfg

    def _write_compose_config(key: str, value: str):
        import openpyxl as _xl
        _COMPOSE_CONFIG_XLSX.parent.mkdir(parents=True, exist_ok=True)
        cfg = _read_compose_config()
        cfg[key] = value
        wb = _xl.Workbook()
        ws = wb.active
        ws.append(["key", "value"])
        for k, v in cfg.items():
            ws.append([k, v])
        wb.save(str(_COMPOSE_CONFIG_XLSX))

    @app.route("/api/docker/compose-config", methods=["GET"])
    def api_docker_compose_config_get():
        cfg = _read_compose_config()
        return jsonify({
            "ok": True,
            "compose_download_dir": cfg.get(_COMPOSE_DIR_KEY, _COMPOSE_DIR_DEFAULT),
        })

    @app.route("/api/docker/compose-config", methods=["POST"])
    def api_docker_compose_config_set():
        body = request.get_json() or {}
        new_dir = (body.get("compose_download_dir") or "").strip()
        if not new_dir:
            return jsonify({"ok": False, "error": "compose_download_dir is required"})
        try:
            _write_compose_config(_COMPOSE_DIR_KEY, new_dir)
            return jsonify({"ok": True})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/docker/compose-files", methods=["GET"])
    def api_docker_compose_files():
        import pathlib as _pl
        cfg = _read_compose_config()
        dir_path = _pl.Path(cfg.get(_COMPOSE_DIR_KEY, _COMPOSE_DIR_DEFAULT))
        try:
            if not dir_path.exists():
                return jsonify({"ok": True, "files": []})
            files = [
                {"name": f.name, "path": str(f), "size": f.stat().st_size}
                for f in sorted(dir_path.iterdir())
                if f.is_file() and f.suffix.lower() in (".yaml", ".yml", ".json")
            ]
            return jsonify({"ok": True, "files": files})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e), "files": []})

