    @app.route("/api/docker/compose", methods=["GET"])
    def api_docker_compose():
        import subprocess as _sub, json as _json
        file_path = (request.args.get("file") or "").strip() or _COMPOSE_FILE
        try:
            r = _sub.run(
                ["docker", "compose", "-f", file_path, "ps", "--format", "json"],
                capture_output=True, text=True, timeout=15,
                creationflags=0x08000000,
            )
            services = []
            # docker compose ps --format json outputs a JSON array or one object per line
            text = r.stdout.strip()
            if text.startswith("["):
                try:
                    items = _json.loads(text)
                    for obj in items:
                        services.append({
                            "name":    obj.get("Name", ""),
                            "service": obj.get("Service", ""),
                            "state":   (obj.get("State", "") or "").lower(),
                            "status":  obj.get("Status", ""),
                            "ports":   obj.get("Publishers", ""),
                        })
                except Exception:
                    pass
            else:
                for line in text.splitlines():
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        obj = _json.loads(line)
                        services.append({
                            "name":    obj.get("Name", ""),
                            "service": obj.get("Service", ""),
                            "state":   (obj.get("State", "") or "").lower(),
                            "status":  obj.get("Status", ""),
                            "ports":   obj.get("Publishers", ""),
                        })
                    except Exception:
                        pass
            return jsonify({"ok": True, "services": services})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

