    @app.route("/api/vms/developer-ping", methods=["GET"])
    def api_vms_developer_ping():
        """TCP port-22 reachability probe for all Developer VMs, runs in parallel."""
        import socket as _sock_ping
        import concurrent.futures as _cf_ping
        import openpyxl as _xl_ping
        if not VMS_FILE.exists():
            return jsonify({"results": []})
        wb_p = _xl_ping.load_workbook(str(VMS_FILE), read_only=True, data_only=True)
        ws_p = wb_p["Developer VMs"] if "Developer VMs" in wb_p.sheetnames else wb_p.active
        hdrs_p = [str(ws_p.cell(1, c).value or "").strip().lower()
                  for c in range(1, ws_p.max_column + 1)]
        vms_p = []
        for row in ws_p.iter_rows(min_row=2, values_only=True):
            if any(v is not None for v in row):
                d = {k: ("" if v is None else str(v).strip()) for k, v in zip(hdrs_p, row)}
                if d.get("name") and d.get("ip"):
                    vms_p.append(d)
        wb_p.close()

        def _probe(vm):
            try:
                s = _sock_ping.socket(_sock_ping.AF_INET, _sock_ping.SOCK_STREAM)
                s.settimeout(3)
                ok = s.connect_ex((vm["ip"], 22)) == 0
                s.close()
            except Exception:
                ok = False
            return {"name": vm["name"], "ip": vm["ip"], "reachable": ok}

        with _cf_ping.ThreadPoolExecutor(max_workers=8) as pool:
            results = list(pool.map(_probe, vms_p, timeout=15))
        return jsonify({"results": results})

