    @app.route("/api/vms/developer/<path:vm_name>/app-status", methods=["GET"])
    def api_vms_developer_app_status(vm_name):
        if not VMS_FILE.exists():
            return jsonify({"ok": False, "error": "vms.xlsx not found"}), 404
        import openpyxl as _xl
        wb  = _xl.load_workbook(str(VMS_FILE))
        vm  = None
        for sheet in wb.sheetnames:
            ws   = wb[sheet]
            hdrs = [str(ws.cell(1, c).value or "").strip().lower()
                    for c in range(1, ws.max_column + 1)]
            if "name" not in hdrs or "ip" not in hdrs:
                continue
            for row in ws.iter_rows(min_row=2, values_only=True):
                d = {k: ("" if v is None else str(v).strip())
                     for k, v in zip(hdrs, row)}
