    @app.route("/api/vms/developer/<path:vm_name>/app-action", methods=["POST"])
    def api_vms_developer_app_action(vm_name):
        body        = request.get_json() or {}
        app_name    = body.get("app",         "").strip()
        action      = body.get("action",      "").strip()
        extra_flags = body.get("extra_flags", [])   # list of raw flag strings e.g. ["-ncs", "-c"]
        if not app_name or action not in ("start", "stop", "restart", "build"):
            return jsonify({"ok": False, "error": "app and action (start|stop|restart|build) required"}), 400
        if not VMS_FILE.exists():
            return jsonify({"ok": False, "error": "vms.xlsx not found"}), 404
        import openpyxl as _xl
        wb  = _xl.load_workbook(str(VMS_FILE))
        vm  = None
        for sheet in wb.sheetnames:
            ws   = wb[sheet]
            hdrs = [str(ws.cell(1, c).value or "").strip().lower()
                    for c in range(1, ws.max_column + 1)]
            if "name" not in hdrs or "ip" not in hdrs:
                continue
            for row in ws.iter_rows(min_row=2, values_only=True):
                d = {k: ("" if v is None else str(v).strip())
                     for k, v in zip(hdrs, row)}
                if d.get("name", "").lower() == vm_name.lower():
                    vm = d; break
            if vm:
                break
        if not vm:
            return jsonify({"ok": False, "error": f"VM '{vm_name}' not found"}), 404
        ip       = vm.get("ip",       "")
        password = vm.get("password", "")
        if not ip:
            return jsonify({"ok": False, "error": "VM has no IP address"}), 400
        # Load app config
        APP_CONFIG = RS_ROOT / "app_config.xlsx"
        app_entry   = None
        build_param_defs = []
        if APP_CONFIG.exists():
            wb2 = _xl.load_workbook(str(APP_CONFIG))
            if "Apps" in wb2.sheetnames:
                ws2   = wb2["Apps"]
                hdrs2 = [str(ws2.cell(1, c).value or "").strip().lower() for c in range(1, ws2.max_column + 1)]
                for row in ws2.iter_rows(min_row=2, values_only=True):
                    if any(v is not None for v in row):
                        d = {k: ("" if v is None else str(v)) for k, v in zip(hdrs2, row)}
                        if d.get("app", "").lower() == app_name.lower():
                            app_entry = d; break
            if "BuildParams" in wb2.sheetnames:
                ws3   = wb2["BuildParams"]
                hdrs3 = [str(ws3.cell(1, c).value or "").strip().lower() for c in range(1, ws3.max_column + 1)]
                for row in ws3.iter_rows(min_row=2, values_only=True):
                    if any(v is not None for v in row):
                        d = {k: ("" if v is None else str(v)) for k, v in zip(hdrs3, row)}
                        if d.get("app", "").lower() == app_name.lower():
                            build_param_defs.append(d)
        if not app_entry:
            return jsonify({"ok": False, "error": f"App '{app_name}' not found in app_config.xlsx"}), 404
        # Build the command
        action_map = {"start": "start_cmd", "stop": "stop_cmd", "restart": "restart_cmd", "build": "build_cmd"}
        cmd = app_entry.get(action_map[action], "").strip()
        if not cmd:
            return jsonify({"ok": False, "error": f"No command configured for action '{action}' on app '{app_name}'"}), 400
        if action == "build" and extra_flags:
            for f in extra_flags:
                f = str(f).strip()
                if f:
                    cmd += f" {f}"
        # Wrap compound commands for SSH
        if " && " in cmd:
            ssh_cmd = f'bash -c "{cmd}"'
        else:
            ssh_cmd = cmd
        user = vm.get("description", "") or "weblogic"

        # Build action runs asynchronously so the UI can show progress + abort
        if action == "build":
            import time as _tbuild
            key = (vm_name.lower(), app_name.lower())
            _cmd_parts   = cmd.strip().split()
            _flags       = _cmd_parts[1:] if len(_cmd_parts) > 1 else []
            _params_key  = " ".join(sorted(_flags)) if _flags else "(none)"
            _start_ms    = int(_tbuild.time() * 1000)
            _est_ms      = _get_remote_build_estimate(app_name.lower(), _params_key)
            with _vm_builds_lock:
                current = _vm_builds.get(key)
                if current and current["status"] == "running":
                    return jsonify({"ok": False, "error": "A build is already running for this app"}), 409
                _vm_builds[key] = {
                    "status": "running", "output": "", "_channel": None, "_client": None,
                    "start_ms": _start_ms, "estimated_ms": _est_ms, "params_key": _params_key,
                }
            _threading.Thread(
                target=_run_build_async,
                args=(vm_name.lower(), app_name.lower(), ip, user, password, ssh_cmd,
                      app_entry.get("success_pattern", ""), _params_key),
                daemon=True,
            ).start()
            return jsonify({"ok": True, "async": True})

        # Start / stop / restart: also run asynchronously with live output streaming
        key = (vm_name.lower(), app_name.lower())
        with _vm_actions_lock:
            current = _vm_actions.get(key)
            if current and current["status"] == "running":
                return jsonify({"ok": False, "error": f"Action '{current.get('action')}' is already running for this app"}), 409
            _vm_actions[key] = {"action": action, "status": "running", "output": "", "_channel": None, "_client": None}
        _threading.Thread(
            target=_run_action_async,
            args=(vm_name.lower(), app_name.lower(), action, ip, user, password, ssh_cmd),
            daemon=True,
        ).start()
        return jsonify({"ok": True, "async": True})

    @app.route("/api/vms/developer/<path:vm_name>/app-build-status/<app_name>", methods=["GET"])
    def api_vms_developer_build_status(vm_name, app_name):
        import time as _tbs2
        key = (vm_name.lower(), app_name.lower())
        with _vm_builds_lock:
            b = _vm_builds.get(key)
        if not b:
            return jsonify({"ok": True, "status": None, "output": ""})
        status       = b["status"]
        start_ms     = b.get("start_ms")
        estimated_ms = b.get("estimated_ms")
        elapsed_ms   = (int(_tbs2.time() * 1000) - start_ms) if start_ms else 0
        if status == "running" and estimated_ms:
            progress = min(int(elapsed_ms / estimated_ms * 100), 95)
        elif status == "success":
            progress = 100
        else:
            progress = None
        return jsonify({
            "ok": True, "status": status, "output": b["output"],
            "elapsed_ms": elapsed_ms, "estimated_ms": estimated_ms, "progress": progress,
        })

    @app.route("/api/vms/developer/<path:vm_name>/app-abort-build/<app_name>", methods=["POST"])
    def api_vms_developer_abort_build(vm_name, app_name):
        key = (vm_name.lower(), app_name.lower())
        with _vm_builds_lock:
            b = _vm_builds.get(key)
            if not b or b["status"] != "running":
                return jsonify({"ok": False, "error": "No running build to abort"}), 400
            b["status"] = "aborted"
            chan   = b.get("_channel")
            client = b.get("_client")
            b["_channel"] = None
            b["_client"]  = None
        if chan:
            try: chan.send("\x03")   # Ctrl-C → SIGINT
            except: pass
            try: chan.close()
            except: pass
        if client:
            try: client.close()
            except: pass
        return jsonify({"ok": True})

    @app.route("/api/vms/developer/<path:vm_name>/app-action-status/<app_name>", methods=["GET"])
    def api_vms_developer_action_status(vm_name, app_name):
        key = (vm_name.lower(), app_name.lower())
        with _vm_actions_lock:
            a = _vm_actions.get(key)
        if not a:
            return jsonify({"ok": True, "status": None, "action": None, "output": ""})
        return jsonify({"ok": True, "status": a["status"], "action": a["action"], "output": a["output"]})

    @app.route("/api/vms/search", methods=["GET"])
    def api_vms_search():
        import threading as _threading
        import openpyxl as _xl
        prb = (request.args.get("prb") or "").strip()
        if not prb:
            return jsonify({"ok": False, "error": "prb parameter is required"}), 400
        if not VMS_FILE.exists():
            return jsonify({"ok": True, "results": [], "total_checked": 0})
        wb  = _xl.load_workbook(str(VMS_FILE))
        vms = []
        seen = set()
        for sheet in wb.sheetnames:
            ws   = wb[sheet]
            hdrs = [str(ws.cell(1, c).value or "").strip().lower()
                    for c in range(1, ws.max_column + 1)]
            if "name" not in hdrs or "ip" not in hdrs:
                continue
            for row in ws.iter_rows(min_row=2, values_only=True):
                if any(v is not None for v in row):
                    d    = {k: ("" if v is None else str(v).strip())
                            for k, v in zip(hdrs, row)}
                    name = d.get("name", "")
                    if name and name not in seen:
                        seen.add(name); vms.append(d)
        try:
            import paramiko as _pm
        except ImportError:
            return jsonify({"ok": False, "error": "paramiko not installed — run: pip install paramiko"}), 500
        results_arr = [None] * len(vms)
        def _worker(i, vm):
            ip       = vm.get("ip",       "")
            password = vm.get("password", "")
            if not ip:
                results_arr[i] = {"vm": vm, "parsed": None, "error": "no IP"}
                return
            client = _pm.SSHClient()
            client.set_missing_host_key_policy(_pm.AutoAddPolicy())
            try:
                client.connect(hostname=ip, port=22, username="weblogic",
                               password=password, timeout=30, banner_timeout=60, auth_timeout=30,
                               allow_agent=False, look_for_keys=False)
                _, stdout, _ = client.exec_command("branch", timeout=20)
                out = stdout.read().decode("utf-8", errors="replace").strip()
                client.close()
                parsed = {}
                for line in out.splitlines():
                    if ":" in line:
                        k, _, v = line.partition(":")
                        parsed[k.strip()] = v.strip()
                results_arr[i] = {"vm": vm, "parsed": parsed, "error": None}
            except Exception as e:
                results_arr[i] = {"vm": vm, "parsed": None, "error": str(e)}
        threads = [_threading.Thread(target=_worker, args=(i, vm)) for i, vm in enumerate(vms)]
        for t in threads: t.start()
        for t in threads: t.join()
        matched = []
        for r in results_arr:
            if r and r["parsed"]:
                if r["parsed"].get("Current branch", "").lower() == prb.lower():
                    matched.append({"name":   r["vm"].get("name", ""),
                                    "ip":     r["vm"].get("ip",   ""),
                                    "parsed": r["parsed"]})
        return jsonify({"ok": True, "results": matched, "total_checked": len(vms)})

