    @app.route("/api/secrets", methods=["POST"])
    def api_secrets_create():
        body     = request.get_json() or {}
        key      = body.get("key", "").strip()
        category = body.get("category", "").strip()
        if not key or not category:
            return jsonify({"error": "key and category required"}), 400
        import openpyxl
        if not SECRETS_FILE.exists():
            wb = openpyxl.Workbook()
            _make_sheet(wb, category, SECRET_HEADERS, SECRET_WIDTHS)
            _save(wb, SECRETS_FILE)
        wb = openpyxl.load_workbook(str(SECRETS_FILE))
        if category not in wb.sheetnames:
            _make_sheet(wb, category, SECRET_HEADERS, SECRET_WIDTHS)
        wb[category].append([key, body.get("value", "").strip(), body.get("notes", "").strip()])
        _save(wb, SECRETS_FILE)
        return jsonify({"key": key}), 201

    @app.route("/api/secrets/<category>/<path:secret_key>", methods=["PATCH"])
    def api_secrets_update(category, secret_key):
        if not SECRETS_FILE.exists():
            return jsonify({"ok": False}), 404
        import openpyxl
        wb = openpyxl.load_workbook(str(SECRETS_FILE))
        if category not in wb.sheetnames:
            return jsonify({"ok": False}), 404
        ws      = wb[category]
        hdrs    = [str(ws.cell(1, c).value or "").strip().lower()
                   for c in range(1, ws.max_column + 1)]
        col_map = {h: i for i, h in enumerate(hdrs, 1)}
        patch   = request.get_json() or {}
        for row in ws.iter_rows(min_row=2):
            if str(row[0].value or "").strip() == str(secret_key).strip():
                for k, v in patch.items():
                    if k in col_map:
                        row[col_map[k] - 1].value = v
                break
        _save(wb, SECRETS_FILE)
        return jsonify({"ok": True})

    @app.route("/api/secrets/<category>/<path:secret_key>", methods=["DELETE"])
    def api_secrets_delete(category, secret_key):
        if not SECRETS_FILE.exists():
            return "", 204
        import openpyxl
        wb = openpyxl.load_workbook(str(SECRETS_FILE))
        if category in wb.sheetnames:
            ws = wb[category]
            for row in ws.iter_rows(min_row=2):
                if str(row[0].value or "").strip() == str(secret_key).strip():
                    ws.delete_rows(row[0].row); break
            _save(wb, SECRETS_FILE)
        return "", 204

    @app.route("/api/vms/developer/<path:vm_name>/payor-version", methods=["GET"])
    def api_vms_developer_payor_version(vm_name):
        """Return the actual Payor branch checked out on the VM by SSHing and running 'branch'."""
        if not VMS_FILE.exists():
            return jsonify({"ok": False, "error": "vms.xlsx not found"}), 404
        import openpyxl as _xl, re as _re
        wb = _xl.load_workbook(str(VMS_FILE))
        vm = None
        for sheet in wb.sheetnames:
            ws   = wb[sheet]
            hdrs = [str(ws.cell(1, c).value or "").strip().lower()
                    for c in range(1, ws.max_column + 1)]
            if "name" not in hdrs or "ip" not in hdrs:
                continue
            for row in ws.iter_rows(min_row=2, values_only=True):
                d = {k: ("" if v is None else str(v).strip())
                     for k, v in zip(hdrs, row)}
                if d.get("name", "").lower() == vm_name.lower():
                    vm = d; break
            if vm:
                break
        if not vm:
            return jsonify({"ok": False, "error": f"VM '{vm_name}' not found"}), 404
        ip       = vm.get("ip", "")
        password = vm.get("password", "")
        if not ip:
            return jsonify({"ok": False, "error": "VM has no IP address"}), 400
        try:
            import paramiko as _pm
        except ImportError:
            return jsonify({"ok": False, "error": "paramiko not installed"}), 500
        try:
            client = _pm.SSHClient()
            client.set_missing_host_key_policy(_pm.AutoAddPolicy())
            client.connect(hostname=ip, port=22, username="weblogic",
                           password=password, timeout=30, banner_timeout=60, auth_timeout=30,
                           allow_agent=False, look_for_keys=False)
            # Try 'branch' command first; if no session, fall back to ~/.default-branch file
            fallback_cmd = (
                "OUTPUT=$(branch 2>&1); "
                "if echo \"$OUTPUT\" | grep -qi 'Current branch:'; then "
                "  echo \"$OUTPUT\"; "
                "else "
                "  DEF=$(cat ~/.default-branch 2>/dev/null | tr -d '\\n'); "
                "  [ -z \"$DEF\" ] && DEF=$(cat ~/.default-payor-branch 2>/dev/null | tr -d '\\n'); "
                "  if [ -n \"$DEF\" ]; then "
                "    echo \"Current branch: $DEF (from file)\"; "
                "  else "
                "    echo \"$OUTPUT\"; "
                "  fi; "
                "fi"
            )
            _, stdout, _ = client.exec_command(fallback_cmd, timeout=30)
            output = stdout.read().decode("utf-8", errors="replace")
            client.close()
        except Exception as e:
            return jsonify({"ok": False, "error": str(e), "branch_version": None}), 200
        # Output format: "Current branch:     26.1.1.1" or "Current branch: 26.1.1.1 (from file)"
        m = _re.search(r"^Current branch:\s+(\S+)", output, _re.IGNORECASE | _re.MULTILINE)
        if not m:
            return jsonify({"ok": False, "error": f"No branch version found. Output: {output[:200]!r}", "branch_version": None}), 200
        return jsonify({"ok": True, "branch_version": m.group(1).strip()})

    def _rpb_write_scheduler_setting(key, value):
        import openpyxl as _xl
        try:
            RPB_ROOT.mkdir(parents=True, exist_ok=True)
            _cfg = RPB_ROOT / "scheduler_config.xlsx"
            if _cfg.exists():
                _wb = _xl.load_workbook(str(_cfg))
                _ws = _wb.active
                for _r in _ws.iter_rows(min_row=2):
                    if _r[0].value and str(_r[0].value).strip().lower() == str(key).lower():
                        _r[1].value = value; break
                else:
                    _ws.append([key, value, ""])
                _wb.save(str(_cfg))
            else:
                _wb = _xl.Workbook(); _ws = _wb.active; _ws.title = "Config"
                _ws.append(["Key", "Value", "Notes"]); _ws.append([key, value, ""])
                _wb.save(str(_cfg))
        except Exception:
            pass

    @app.route("/api/tools/rpb/scheduler-settings", methods=["GET"])
    def api_rpb_get_scheduler_settings():
        import openpyxl as _xl
        settings = []
        _cfg = RPB_ROOT / "scheduler_config.xlsx"
        if _cfg.exists():
            try:
                _wb = _xl.load_workbook(str(_cfg), data_only=True)
                _ws = _wb.active
                _hdrs = [str(_ws.cell(1, c).value or "").strip().lower()
                         for c in range(1, _ws.max_column + 1)]
                _notes_col = _hdrs.index("notes") if "notes" in _hdrs else None
                for _r in _ws.iter_rows(min_row=2, values_only=True):
                    if not _r[0]:
                        continue
                    _k = str(_r[0]).strip()
                    _v = str(_r[1]).strip() if _r[1] is not None else ""
                    _n = str(_r[_notes_col]).strip() if (_notes_col is not None and _r[_notes_col]) else ""
                    settings.append({"key": _k, "value": _v, "notes": _n})
            except Exception:
                pass
        _DEFAULTS = [
            ("poll_interval_s",       "60",  "Auto refresh / engine poll interval in seconds"),
            ("max_poll_hours",        "48",  "Mark stale runs after this many hours"),
            ("stale_threshold_hours", "48",  "Startup recovery: ignore projects older than this"),
        ]
        _existing_keys = {s["key"].lower() for s in settings}
        for _dk, _dv, _dn in _DEFAULTS:
            if _dk.lower() not in _existing_keys:
                settings.append({"key": _dk, "value": _dv, "notes": _dn})
        return jsonify({"ok": True, "settings": settings})

    @app.route("/api/tools/rpb/scheduler-settings", methods=["POST"])
    def api_rpb_post_scheduler_settings():
        data = request.get_json() or {}
        updates = data.get("settings", {})
