    @app.route("/api/tools/rpb/projects", methods=["GET"])
    def api_rpb_projects():
        import openpyxl as _xl
        import json as _json
        path = RPB_DATA / "projects.xlsx"
        if not path.exists():
            return jsonify([])
        wb   = _xl.load_workbook(str(path))
        _rpb_app = request.args.get("app", "Payor")
        ws   = wb[_rpb_app] if _rpb_app in wb.sheetnames else wb.active
        hdrs = [str(ws.cell(1, c).value or "").strip().lower()
                for c in range(1, ws.max_column + 1)]
        rows = []
        for row in ws.iter_rows(min_row=2, values_only=True):
            if any(v is not None for v in row):
                d         = {k: ("" if v is None else str(v)) for k, v in zip(hdrs, row)}
                urls_obj  = _rpb_read_urls(d.get("pid", ""), _rpb_app)
                d["payor_urls"] = _json.dumps(urls_obj)
                vm_name   = urls_obj.get("vm_name", "")
                vm_ip, _  = _rpb_lookup_vm(vm_name)
                d["vm_name"] = vm_name
                d["vm_ip"]   = vm_ip
                with _rpb_threads_lock:
                    t = _rpb_threads.get(int(d.get("pid", 0)))
                    d["running"] = bool(t and t.is_alive())
                rpt, eml = _rpb_find_output_files(d.get("payor_version", ""), _rpb_app)
                d["has_report"] = rpt is not None
                d["has_email"]  = eml is not None
                rows.append(d)
        return jsonify(rows)

