    _CLONE_APP_ORDER = ["payor", "classic", "connector", "enrollment", "pik"]

    @app.route("/api/tools/clone/apps", methods=["GET"])
    def api_clone_list_apps():
        import re as _re_ca
        cfg_dir = LC_ROOT / "project_type_config"
        if not cfg_dir.exists():
            return jsonify({"apps": []})
        found = set()
        for f in cfg_dir.glob("*_config.xlsx"):
            found.add(_re_ca.sub(r"_config$", "", f.stem))
        ordered = [n for n in _CLONE_APP_ORDER if n in found]
        ordered += sorted(found - set(_CLONE_APP_ORDER))
        apps = [{"name": n} for n in ordered]
        return jsonify({"apps": apps})

    @app.route("/api/tools/clone/apps", methods=["POST"])
    def api_clone_create_app():
        import openpyxl as _xl_cca, re as _re_cca
        body     = request.get_json() or {}
        app_name = _re_cca.sub(r"[^a-z0-9_]", "_",
                               str(body.get("app_name") or "").strip().lower())
        if not app_name:
            return jsonify({"ok": False, "error": "app_name required"}), 400
        cfg_dir  = LC_ROOT / "project_type_config"
        proj_dir = LC_DATA / "projects"
        cfg_dir.mkdir(parents=True, exist_ok=True)
        proj_dir.mkdir(parents=True, exist_ok=True)
        cfg_path  = cfg_dir / f"{app_name}_config.xlsx"
        proj_path = proj_dir / f"{app_name}_projects.xlsx"
        if cfg_path.exists():
            return jsonify({"ok": False, "error": f"App '{app_name}' already exists"}), 409
        wb = _xl_cca.Workbook()
        ws = wb.active; ws.title = "Config"
        ws.append(["Key", "Value", "Notes"])
        for i, w in enumerate([30, 60, 80], 1):
            ws.column_dimensions[_xl_cca.utils.get_column_letter(i)].width = w
        wb.save(str(cfg_path))
        wb2 = _xl_cca.Workbook()
        ws2 = wb2.active; ws2.title = "Projects"
        ws2.append(_CLONE_PROJ_HEADERS)
        for i, w in enumerate(_CLONE_PROJ_WIDTHS, 1):
            ws2.column_dimensions[_xl_cca.utils.get_column_letter(i)].width = w
        ws_pr = wb2.create_sheet("PRs")
        ws_pr.append(_CLONE_PR_HEADERS)
        for i, w in enumerate(_CLONE_PR_WIDTHS, 1):
            ws_pr.column_dimensions[_xl_cca.utils.get_column_letter(i)].width = w
        wb2.save(str(proj_path))
        return jsonify({"ok": True, "app_name": app_name})

