    @app.route("/api/tools/clone/apps/<app_name>/projects", methods=["GET"])
    def api_clone_get_app_projects(app_name):
        import openpyxl as _xl_gp
        proj_path = LC_DATA / "projects" / f"{app_name}_projects.xlsx"
        if not proj_path.exists():
            return jsonify([])
        try:
            with _lc_projects_lock:
                with _lc_per_file_lock(proj_path):
                    wb = _xl_gp.load_workbook(str(proj_path), data_only=True)
            # ── Projects sheet ─────────────────────────────────────────────
            ws_proj = wb["Projects"] if "Projects" in wb.sheetnames else wb.active
            all_rows = list(ws_proj.iter_rows(values_only=True))
            if not all_rows:
                return jsonify([])
            hdrs = [str(c or "").strip().lower() for c in all_rows[0]]
            result = []
            for row in all_rows[1:]:
                if all(c is None for c in row):
                    continue
                result.append({
                    hdrs[i]: (str(row[i]) if row[i] is not None else "")
                    for i in range(len(hdrs))
                })
            # ── PRs sheet — join by project_id ─────────────────────────────
            if "PRs" in wb.sheetnames:
                ws_pr = wb["PRs"]
                pr_rows = list(ws_pr.iter_rows(values_only=True))
                if pr_rows:
                    pr_hdrs = [str(c or "").strip().lower() for c in pr_rows[0]]
                    pr_map = {}
                    for pr_row in pr_rows[1:]:
                        if all(c is None for c in pr_row):
                            continue
                        pr_dict = {pr_hdrs[i]: (str(pr_row[i]) if pr_row[i] is not None else "")
                                   for i in range(len(pr_hdrs))}
                        pid = pr_dict.get("project_id", "")
                        if pid:
                            pr_map[pid] = pr_dict
                    for rec in result:
                        pr_data = pr_map.get(rec.get("project_id", ""), {})
                        for k, v in pr_data.items():
                            if k != "project_id":
                                rec[k] = v
            return jsonify(result)
        except Exception:
            return jsonify([])

    @app.route("/api/tools/clone/apps/<app_name>/projects/<project_id>", methods=["DELETE"])
    def api_clone_delete_app_project(app_name, project_id):
        import openpyxl as _xl_dp
        proj_path = LC_DATA / "projects" / f"{app_name}_projects.xlsx"
        if not proj_path.exists():
            return jsonify({"ok": True})
        try:
            with _lc_projects_lock:
                with _lc_per_file_lock(proj_path):
                    wb = _xl_dp.load_workbook(str(proj_path))
                    pid_str = str(project_id)
                    # Delete from Projects sheet
                    ws_proj = wb["Projects"] if "Projects" in wb.sheetnames else wb.active
                    for row in ws_proj.iter_rows(min_row=2):
                        if str(row[0].value or "").strip() == pid_str:
                            ws_proj.delete_rows(row[0].row)
                            break
                    # Delete from PRs sheet
                    if "PRs" in wb.sheetnames:
                        ws_pr = wb["PRs"]
                        for row in ws_pr.iter_rows(min_row=2):
                            if str(row[0].value or "").strip() == pid_str:
                                ws_pr.delete_rows(row[0].row)
                                break
                    wb.save(str(proj_path))
            return jsonify({"ok": True})
        except Exception as _e:
            return jsonify({"ok": False, "error": str(_e)}), 500

