    def _rs_ensure_poller():
        """Start the RS poller thread if it is not already running."""
        with _rs_poller_state_lock:
            if not _rs_poller_state.get("running"):
                _rs_poller_state["running"] = True
                _threading.Thread(target=_rs_job_poller, daemon=True).start()

    def _rs_job_poller():
        """Background thread: poll Jenkins for active Remote VM Setup projects at the saved interval."""
        import sys as _sys, time as _t
        _rs_scr = str(RS_ROOT / "scripts")
        if _rs_scr not in _sys.path:
            _sys.path.insert(0, _rs_scr)
        try:
            import rvmsetupstatus as _rvm
        except ImportError:
            with _rs_poller_state_lock:
                _rs_poller_state["running"] = False
            return

        _ACTIVE = _rvm._ACTIVE_STATUSES

        while True:
            with _rs_poller_state_lock:
                interval = _rs_poller_state.get("poll_interval_s", 300)

            try:
                with _rs_projects_lock, _rs_projects_filelock():
                    projects = _rvm._load_projects()

                active = [p for p in projects
                          if str(p.get("status", "") or "").lower() in _ACTIVE]

                if active:
                    secrets     = _rvm._load_secrets()
                    updates_map = {}
                    eta_map     = {}

                    for _p in active:
                        _pid    = str(_p.get("pid", "") or "")
                        _jurl   = str(_p.get("jenkins_url", "") or "")
                        _qurl   = str(_p.get("queue_url",   "") or "")
                        _binfo  = _rvm._fetch_build_info(_jurl, _qurl, secrets)
                        if not _binfo:
                            continue
                        _building     = _binfo.get("building", False)
                        _result       = _binfo.get("result", "")
                        _start_ms     = _binfo.get("timestamp")
                        _est_ms       = _binfo.get("estimatedDuration")
                        _res_url      = _binfo.get("_build_url", "")
                        _res_from     = _binfo.get("_resolved_from", "")
                        _row_upd      = {}
                        if _res_from == "queue" and _res_url:
                            _row_upd["jenkins_url"] = _res_url
                        if _building:
                            _row_upd["status"] = "Running"
                            if _start_ms is not None:
                                eta_map[_pid] = {"start_ms": _start_ms, "est_ms": _est_ms}
                        else:
                            _row_upd["status"] = {
                                "SUCCESS": "Passed", "FAILURE": "Failed",
                                "ABORTED": "Cancelled", "UNSTABLE": "Unstable",
                            }.get(_result, _result or "Unknown")
                        if _row_upd:
                            updates_map[_pid] = _row_upd

                    if updates_map:
                        with _rs_projects_lock, _rs_projects_filelock():
                            _rvm._batch_update_projects(updates_map)
                    if eta_map:
                        _rvm._save_eta_cache(eta_map)

            except Exception:
                pass

            _t.sleep(interval)

    def _run_jbaseline_bg(cmd, wf_mode=False, wf_pid=None,
                          wf_stage_key="baseline", app_name="Payor"):
        """Run jbaseline CLI in background.

        wf_mode=True: triggered by Clone Workflow — skip _jbaseline_op so the
        Baseline page stays free for manual runs.  Completion is tracked via
        the run_id written to the Clone WF stage's tool_pid.
        """
        import subprocess as _sp
        _CREATE_NO_WINDOW = getattr(_sp, "CREATE_NO_WINDOW", 0x08000000)
        def _append(line):
            if not wf_mode:
                with _jbaseline_op_lock:
                    _jbaseline_op["output"] += line
        try:
            proc = _sp.Popen(cmd, stdout=_sp.PIPE, stderr=_sp.STDOUT, text=True,
                             encoding="utf-8", errors="replace",
                             creationflags=_CREATE_NO_WINDOW)
            if not wf_mode:
                with _jbaseline_op_lock:
                    _jbaseline_op["pid"] = proc.pid
            for line in iter(proc.stdout.readline, ""):
                if not wf_mode and _jbaseline_abort.is_set():
                    proc.kill()
                    _append("\n--- Aborted ---\n")
                    with _jbaseline_op_lock:
                        _jbaseline_op["status"] = "aborted"
                    return
                _append(line)
            proc.stdout.close()
            rc = proc.wait()
            _poll_app = None; _wf_pid_ref = None; _wf_sk_ref = None
            if wf_mode:
                # Always store tool_pid regardless of rc — the engine uses it
                # to read the actual status (success / failed / unstable) from
                # jbaseline projects.xlsx.  Without it the stage loops forever.
                _poll_app   = app_name or "Payor"
                _wf_pid_ref = wf_pid
                _wf_sk_ref  = wf_stage_key or "baseline"
            else:
                with _jbaseline_op_lock:
                    _jbaseline_op["pid"] = None  # process exited; clear stale PID
                    if _jbaseline_op["status"] == "running":
                        if rc == 0:
                            _poll_app   = _jbaseline_op.get("app", "Payor") or "Payor"
                            _wf_pid_ref = _jbaseline_op.get("_wf_pid")
                            _wf_sk_ref  = _jbaseline_op.get("_wf_stage_key", "baseline")
                        else:
                            _jbaseline_op["status"] = "failed"
            # Store baseline project (run_id) in the workflow stage's tool_pid
            if _poll_app and _wf_pid_ref:
                try:
                    import openpyxl as _xl_bg
                    _pd = JB_DATA / "projects" / _poll_app
                    if _pd.exists():
                        _fs = sorted(
                            _pd.glob("*.xlsx"),
                            key=lambda p: int(p.stem.split("_")[0]) if p.stem.split("_")[0].isdigit() else 0,
                            reverse=True)
                        if _fs:
                            _rid = int(_fs[0].stem.split("_")[0])
                            for _s in load_stages(_wf_pid_ref):
                                if str(_s.get("stage_key", "")).strip() == _wf_sk_ref:
                                    update_stage(_wf_pid_ref, _s["stage_id"],
                                                 {"tool_pid": str(_rid)})
                                    break
                except Exception:
                    pass
            # After CLI exits, ensure the new project row is in projects.xlsx.
            # The old (still-running) poller may have overwritten it via _update_run_status,
            # which reloads the file from a snapshot taken before append_run wrote the new row.
            if _poll_app:
                try:
                    import openpyxl as _xl_bg2, sys as _sys_bg
                    _pd2 = JB_DATA / "projects" / _poll_app
                    if _pd2.exists():
                        _fs2 = sorted(
                            _pd2.glob("*.xlsx"),
                            key=lambda p: int(p.stem.split("_")[0]) if p.stem.split("_")[0].isdigit() else 0,
                            reverse=True)
                        if _fs2:
                            _rid2 = int(_fs2[0].stem.split("_")[0])
                            _proj_xlsx2 = JB_DATA / "projects.xlsx"
                            if _proj_xlsx2.exists():
                                _row_found = True
                                with _jbaseline_projects_lock, _jb_projects_filelock():
                                    _wb_chk = _xl_bg2.load_workbook(str(_proj_xlsx2))
                                    _ws_chk = (_wb_chk[_poll_app]
                                               if _poll_app in _wb_chk.sheetnames
                                               else _wb_chk.active)
                                    _row_found = any(
                                        _ws_chk.cell(r, 1).value == _rid2
                                        for r in range(2, _ws_chk.max_row + 1)
                                    )
                                # Call append_run OUTSIDE the filelock — it acquires
                                # _projects_filelock() internally; calling it from within
                                # would deadlock (same lock file, same process).
                                if not _row_found:
                                    _jb_scr2 = str(JB_ROOT / "scripts")
                                    if _jb_scr2 not in _sys_bg.path:
                                        _sys_bg.path.insert(0, _jb_scr2)
                                    from jbaseline_tool import append_run as _ar2
                                    _ver2 = ""; _trig2 = ""
                                    with _jb_per_file_lock(_fs2[0]):
                                        _wb2_ = _xl_bg2.load_workbook(str(_fs2[0]))
                                    if "info" in _wb2_.sheetnames:
                                        for _ir2 in _wb2_["info"].iter_rows(
                                                min_row=2, values_only=True):
                                            _k2 = str(_ir2[0] or "").strip() if _ir2 else ""
                                            if _k2 == "release_version":
                                                _ver2 = str(_ir2[1] or "").strip()
                                            elif _k2 == "triggered_at":
                                                _trig2 = str(_ir2[1] or "").strip()
                                    from datetime import datetime as _dt_bg2
                                    if not _trig2:
                                        _trig2 = _dt_bg2.fromtimestamp(
                                            _fs2[0].stat().st_mtime
                                        ).strftime("%Y-%m-%d %H:%M:%S")
                                    _ar2(_rid2, _ver2, 1, "running", _trig2)
                except Exception:
                    pass
                _threading.Thread(
                    target=_jbaseline_job_poller, args=(_poll_app,), daemon=True
                ).start()
        except Exception as _e:
            _append(f"\nError: {_e}\n")
            if not wf_mode:
                with _jbaseline_op_lock:
                    if _jbaseline_op["status"] == "running":
                        _jbaseline_op["status"] = "failed"

    @app.route("/api/tools/jbaseline/trigger", methods=["POST"])
    def api_jbaseline_trigger():
        data = request.get_json() or {}
        if not data.get("payor_version", "").strip():
            return jsonify({"ok": False, "error": "payor_version is required"})
        _app_name = data.get("app", "Payor") or "Payor"
        _wf_pid_v = data.get("_wf_pid")
        _wf_sk_v  = data.get("_wf_stage_key")
        cmd  = ["cmd", "/c"] + _TOOL_CMD["jbaseline"](data)

        if _wf_pid_v:
            # Clone Workflow trigger: run jbaseline without claiming _jbaseline_op so
            # the Baseline page stays free for manual runs.  Completion is tracked via
            # the run_id written to the Clone WF stage's tool_pid field.
            _threading.Thread(
                target=_run_jbaseline_bg,
                kwargs={"cmd": cmd, "wf_mode": True, "wf_pid": _wf_pid_v,
                        "wf_stage_key": _wf_sk_v, "app_name": _app_name},
                daemon=True,
            ).start()
            return jsonify({"ok": True})

        # Manual trigger: claim _jbaseline_op so Baseline page shows the run.
        with _jbaseline_op_lock:
            if _jbaseline_op["status"] == "running":
                # Before blocking, verify the tracked CLI process is still alive.
                # If it died (e.g. crash, server restart, deadlocked poller), reset
                # so a fresh trigger is allowed rather than blocking forever.
                _existing_pid = _jbaseline_op.get("pid")
                _proc_alive = False
                if _existing_pid:
                    try:
                        import subprocess as _sp_chk
                        _out = _sp_chk.run(
                            ["tasklist", "/FI", f"PID eq {_existing_pid}", "/NH"],
                            capture_output=True, text=True, timeout=5
                        ).stdout
                        _proc_alive = str(_existing_pid) in _out
                    except Exception:
                        _proc_alive = False
                if _proc_alive:
                    return jsonify({"ok": False, "error": "A Baseline run is already in progress"})
                # Process is gone but status was never cleared — reset and continue
                _jbaseline_op["status"] = "failed"
            _start_msg = (f"Starting Baseline — {_app_name} "
                          f"(version: {data.get('payor_version','').strip()})\n"
                          f"Launching jbaseline CLI...\n")
            _jbaseline_op.update({"status": "running", "output": _start_msg, "pid": None,
                                   "app": _app_name,
                                   "_wf_pid": None, "_wf_stage_key": None})
        _jbaseline_abort.clear()
        _threading.Thread(target=_run_jbaseline_bg, args=(cmd,), daemon=True).start()
        return jsonify({"ok": True})

    @app.route("/api/tools/jbaseline/op-poll-interval", methods=["POST"])
    def api_jbaseline_poll_interval():
        import openpyxl as _xl
        data       = request.get_json() or {}
        refresh_ms = int(data.get("refresh_ms") or 0)
        if refresh_ms <= 0:
            return jsonify({"ok": True})  # auto-refresh Off — leave saved poll interval unchanged
        poll_s = max(30, refresh_ms // 1000)
        with _jbaseline_op_lock:
            _jbaseline_op["poll_interval_s"] = poll_s
        # Persist to scheduler_config.xlsx
        _cfg = JB_ROOT / "scheduler_config.xlsx"
        try:
            if _cfg.exists():
                _wb = _xl.load_workbook(str(_cfg))
                _ws = _wb.active
                for _row in _ws.iter_rows(min_row=2):
                    if _row[0].value and str(_row[0].value).strip().lower() == "poll_interval_s":
                        _row[1].value = poll_s
                        break
                else:
                    _ws.append(["poll_interval_s", poll_s])
                _wb.save(str(_cfg))
            else:
                _wb = _xl.Workbook()
                _ws = _wb.active
                _ws.title = "config"
                _ws.append(["key", "value"])
                _ws.append(["poll_interval_s", poll_s])
                _wb.save(str(_cfg))
        except Exception:
            pass
        return jsonify({"ok": True, "poll_interval_s": poll_s})

    @app.route("/api/tools/jbaseline/op-status", methods=["GET"])
    def api_jbaseline_op_status():
        with _jbaseline_op_lock:
            return jsonify({"ok": True, "status": _jbaseline_op["status"],
                            "output": _jbaseline_op["output"], "pid": _jbaseline_op["pid"],
                            "app": _jbaseline_op.get("app"),
                            "wf_pid": _jbaseline_op.get("_wf_pid")})

    @app.route("/api/tools/jbaseline/op-abort", methods=["POST"])
    def api_jbaseline_op_abort():
        with _jbaseline_op_lock:
            if _jbaseline_op["status"] != "running":
                return jsonify({"ok": False, "error": "No run in progress"})
            _jbaseline_op["output"] += "\n--- Abort requested ---\n"
            _jbaseline_op["status"] = "aborted"
            pid = _jbaseline_op.get("pid")
        _jbaseline_abort.set()
        if pid:
            import subprocess as _sp
            _CNW = getattr(_sp, "CREATE_NO_WINDOW", 0x08000000)
            try: _sp.run(["taskkill", "/F", "/T", "/PID", str(pid)],
                         capture_output=True, creationflags=_CNW)
            except Exception: pass
        return jsonify({"ok": True})

    @app.route("/api/tools/jbaseline/op-detach", methods=["POST"])
    def api_jbaseline_op_detach():
        """Detach from current baseline run: frees the Baseline page without stopping
        the Jenkins job poller.  Used when Clone Workflow owns the op and the user
        wants to start a manual run independently.  Does NOT signal _jbaseline_abort,
        so the poller keeps running and JB projects.xlsx stays up-to-date."""
        with _jbaseline_op_lock:
            if _jbaseline_op["status"] != "running":
                return jsonify({"ok": False, "error": "No run in progress"})
            pid = _jbaseline_op.get("pid")
            _jbaseline_op.update({
                "status": None, "output": "", "pid": None,
                "app": None, "_wf_pid": None, "_wf_stage_key": None,
            })
        if pid:
            import subprocess as _sp
            _CNW = getattr(_sp, "CREATE_NO_WINDOW", 0x08000000)
            try: _sp.run(["taskkill", "/F", "/T", "/PID", str(pid)],
                         capture_output=True, creationflags=_CNW)
            except Exception: pass
        return jsonify({"ok": True})

    @app.route("/api/tools/jbaseline/config", methods=["GET"])
    def api_jbaseline_config():
        import openpyxl as _xl
        cfg_path = JB_ROOT / "git_config.xlsx"
        payor_repo = ""
        if cfg_path.exists():
            try:
                wb = _xl.load_workbook(str(cfg_path))
                ws = wb.active
                for row in ws.iter_rows(min_row=2, values_only=True):
                    if row[0] and str(row[0]).strip().lower() == "payor" and row[1]:
                        payor_repo = str(row[1]).strip().rstrip("/")
                        break
            except Exception:
                pass
        max_poll_hours = 48
        stale_threshold_hours = 48
        sched_path = JB_ROOT / "scheduler_config.xlsx"
        if sched_path.exists():
            try:
                _wb_sc = _xl.load_workbook(str(sched_path), data_only=True)
                for _sr in _wb_sc.active.iter_rows(min_row=2, values_only=True):
                    if not _sr[0]:
                        continue
                    _k = str(_sr[0]).strip().lower()
                    if _k == "max_poll_hours" and _sr[1]:
                        max_poll_hours = int(_sr[1])
                    elif _k == "stale_threshold_hours" and _sr[1]:
                        stale_threshold_hours = int(_sr[1])
            except Exception:
                pass
        return jsonify({
            "payor_repo_url": payor_repo,
            "max_poll_hours": max_poll_hours,
            "stale_threshold_hours": stale_threshold_hours,
        })

    @app.route("/api/tools/jbaseline/scheduler-settings", methods=["GET"])
    def api_jbaseline_get_scheduler_settings():
        import openpyxl as _xl
        settings = []
        sched_path = JB_ROOT / "scheduler_config.xlsx"
        if sched_path.exists():
            try:
                _wb = _xl.load_workbook(str(sched_path), data_only=True)
                for _r in _wb.active.iter_rows(min_row=2, values_only=True):
                    if _r[0]:
                        settings.append({
                            "key":   str(_r[0]).strip(),
                            "value": str(_r[1]).strip() if _r[1] is not None else "",
                            "notes": str(_r[2]).strip() if len(_r) > 2 and _r[2] else "",
                        })
            except Exception:
                pass
        _DEFAULTS_JB = [
            ("poll_interval_s",      "60", "Jenkins job status poll interval in seconds"),
            ("max_poll_hours",        "48", "Mark non-final jobs as conn_err after this many hours"),
            ("stale_threshold_hours", "48", "Startup recovery: ignore runs older than this"),
        ]
        _existing_keys = {s["key"].lower() for s in settings}
        for _dk, _dv, _dn in _DEFAULTS_JB:
            if _dk.lower() not in _existing_keys:
                settings.append({"key": _dk, "value": _dv, "notes": _dn})
        return jsonify({"ok": True, "settings": settings})

    @app.route("/api/tools/jbaseline/scheduler-settings", methods=["POST"])
    def api_jbaseline_scheduler_settings():
        data = request.get_json() or {}
        # Generic {settings: {key: value}} map
        if "settings" in data and isinstance(data["settings"], dict):
            for k, v in data["settings"].items():
                _jb_write_scheduler_setting(str(k).strip(), str(v).strip())
            return jsonify({"ok": True})
        # Legacy named-field fallback
        errors = []
        if "max_poll_hours" in data:
            try:
                val = max(1, int(data["max_poll_hours"]))
                _jb_write_scheduler_setting("max_poll_hours", val)
            except Exception:
                errors.append("max_poll_hours must be an integer")
        if "stale_threshold_hours" in data:
            try:
                val = max(1, int(data["stale_threshold_hours"]))
                _jb_write_scheduler_setting("stale_threshold_hours", val)
            except Exception:
                errors.append("stale_threshold_hours must be an integer")
        if errors:
            return jsonify({"ok": False, "errors": errors}), 400
        return jsonify({"ok": True})

    @app.route("/api/tools/jbaseline/projects/<pid>/jobs", methods=["GET"])
    def api_jbaseline_project_jobs(pid):
        import openpyxl as _xl, requests as _req
        _jbaseline_app = request.args.get("app", "Payor")
        proj_dir = JB_DATA / "projects" / _jbaseline_app
        if not proj_dir.exists():
            return jsonify([])
        matches = list(proj_dir.glob(f"{pid}_*.xlsx"))
        if not matches:
            return jsonify([])
        try:
            with _jb_per_file_lock(matches[0]):
                wb = _xl.load_workbook(str(matches[0]))
            if "jobs" not in wb.sheetnames:
                return jsonify([])
            ws   = wb["jobs"]
            hdrs = [str(ws.cell(1, c).value or "").strip().lower()
                    for c in range(1, ws.max_column + 1)]
            rows = []
            for row in ws.iter_rows(min_row=2, values_only=True):
                if any(v is not None for v in row):
                    rows.append({k: ("" if v is None else str(v)) for k, v in zip(hdrs, row)})

            _run_info = {}
            _ws_info  = wb["info"] if "info" in wb.sheetnames else None
            if _ws_info:
                for _r in _ws_info.iter_rows(min_row=2, values_only=True):
                    if _r[0]:
                        _run_info[str(_r[0]).strip()] = str(_r[1] or "").strip()

            # Inject job_url from baseline config so job names are clickable
            _job_url_map = {}
            _cfg_path = JB_ROOT / "baseline_job_config.xlsx"
            if _cfg_path.exists():
                try:
                    _cwb = _xl.load_workbook(str(_cfg_path))
                    _cws = _cwb["payor"] if "payor" in _cwb.sheetnames else _cwb.active
                    for _cr in _cws.iter_rows(min_row=2, values_only=True):
                        if _cr[0] and _cr[1]:
                            _job_url_map[str(_cr[0]).strip()] = str(_cr[1]).strip()
                except Exception:
                    pass
            for row in rows:
                if not row.get("job_url"):
                    _jn = row.get("job_name", "")
                    if _jn in _job_url_map:
                        row["job_url"] = _job_url_map[_jn]

            # Load Jenkins secrets
            _sec = {}
            try:
                if SECRETS_FILE.exists():
                    _swb = _xl.load_workbook(str(SECRETS_FILE))
                    if "Jenkins" in _swb.sheetnames:
                        for _r in _swb["Jenkins"].iter_rows(min_row=2, values_only=True):
                            if _r[0] and _r[1] is not None:
                                _sec[str(_r[0]).strip()] = str(_r[1]).strip()
            except Exception:
                pass
            _auth = ((_sec.get("jenkins_username", ""),
                      _sec.get("jenkins_api_token", "") or _sec.get("jenkins_password", ""))
                     if _sec.get("jenkins_username") else None)

            # Resolve queue URLs → build URLs; poll running jobs for status
            if "jenkins_url" in hdrs:
                jurl_col      = hdrs.index("jenkins_url") + 1
                completed_col = (hdrs.index("completed") + 1) if "completed" in hdrs else None
                needs_save    = False

                # Step 1: resolve queue → build URL (parallel)
                import re as _re_jb
                import concurrent.futures as _cf_jb
                import time as _tj_b

                def _resolve_queue(args):
                    i, row = args
                    j_url = row.get("jenkins_url", "")
                    if j_url and "/queue/item/" not in j_url and _re_jb.search(r'/\d+/?$', j_url):
                        return i, None, False  # already a build URL
                    resolved     = None
                    still_queued = False
                    if j_url and "/queue/item/" in j_url:
                        try:
                            qr = _req.get(j_url.rstrip("/") + "/api/json",
                                          auth=_auth, timeout=5, verify=False)
                            if qr.status_code == 200:
                                try:
                                    exe = qr.json().get("executable")
                                    if exe and exe.get("url"):
                                        resolved = exe["url"].rstrip("/") + "/"
                                    else:
                                        still_queued = True
                                except Exception:
                                    pass
                        except Exception:
                            pass
                    if not resolved and not still_queued:
                        job_base         = row.get("job_url", "")
                        triggered_at_str = row.get("triggered_at", "")
                        if job_base:
                            try:
                                from datetime import datetime as _dt_jb
                                _triggered_ms = 0
                                if triggered_at_str:
                                    try:
                                        _triggered_ms = int(
                                            _dt_jb.fromisoformat(triggered_at_str).timestamp() * 1000
                                        ) - 300000  # 5-min buffer for clock skew between machines
                                    except Exception:
                                        pass
                                _pvp = _run_info.get("PAYOR_VERSION_PREFIX", "").strip()
                                for _sfx in ("staging:", "release:", "releases:"):
                                    if _pvp.lower().startswith(_sfx):
                                        _pvp = _pvp[len(_sfx):]
                                _pvp = _pvp.rstrip("-").strip()
                                if _triggered_ms or _pvp:
                                    _tree = ("builds[number,url,timestamp,"
                                             "actions[parameters[name,value]]]{0,10}")
                                    _jb = _req.get(
                                        job_base.rstrip("/") + f"/api/json?tree={_tree}",
                                        auth=_auth, timeout=8, verify=False)
                                    if _jb.status_code == 200:
                                        for _bld in (_jb.json().get("builds") or []):
                                            _bts  = _bld.get("timestamp", 0)
                                            _burl = (_bld.get("url") or "").rstrip("/") + "/"
                                            if not _burl or _burl == "/":
                                                continue
                                            if _triggered_ms and _bts < _triggered_ms:
                                                break  # builds in reverse-chrono order
                                            if _pvp:
                                                _bp = {}
                                                for _a in (_bld.get("actions") or []):
                                                    for _p in (_a.get("parameters") or []):
                                                        _bp[str(_p.get("name") or "")] = str(_p.get("value") or "")
                                                _bvp = _bp.get("PAYOR_VERSION_PREFIX", "")
                                                for _sfx in ("staging:", "release:", "releases:"):
                                                    if _bvp.lower().startswith(_sfx):
                                                        _bvp = _bvp[len(_sfx):]
                                                _bvp = _bvp.rstrip("-").strip()
                                                if _pvp not in _bvp:
                                                    continue
                                            resolved = _burl
                                            break
                                if not resolved and not _triggered_ms:
                                    lb = _req.get(job_base.rstrip("/") + "/lastBuild/api/json",
                                                  auth=_auth, timeout=5, verify=False)
                                    if lb.status_code == 200:
                                        lb_url = (lb.json().get("url") or "").rstrip("/") + "/"
                                        if lb_url and lb_url != "/":
                                            resolved = lb_url
                            except Exception:
                                pass
                    return i, resolved, still_queued

                with _cf_jb.ThreadPoolExecutor(max_workers=8) as _ex1:
                    _resolve_results = list(_ex1.map(_resolve_queue, enumerate(rows)))

                for i, resolved, _ in _resolve_results:
                    if resolved:
                        rows[i]["jenkins_url"] = resolved
                        ws.cell(i + 2, jurl_col, resolved)
                        rows[i]["completed"] = "Running"
                        if completed_col:
                            ws.cell(i + 2, completed_col, "Running")
                        needs_save = True

                # Step 2: poll build status for running/scheduled jobs (parallel)
                _now_ms_b = int(_tj_b.time() * 1000)

                def _poll_status(args):
                    i, row = args
                    j_url = row.get("jenkins_url", "")
                    comp  = (row.get("completed") or "").lower()
                    if not j_url or "/queue/item/" in j_url or comp not in ("scheduled", "running", "building"):
                        return i, None
                    try:
                        br = _req.get(j_url.rstrip("/") + "/api/json",
                                      auth=_auth, timeout=5, verify=False)
                        if br.status_code == 200:
                            bj       = br.json()
                            building = bj.get("building")
                            if building is False:
                                result   = (bj.get("result") or "").upper()
                                new_comp = {"SUCCESS": "Success", "FAILURE": "Failed",
                                            "ABORTED": "Aborted", "UNSTABLE": "Unstable"}.get(result, result or "Done")
                                return i, {"completed": new_comp, "eta_seconds": ""}
                            else:
                                est   = bj.get("estimatedDuration") or 0
                                start = bj.get("timestamp") or 0
                                eta   = str(max(0, int((start + est - _now_ms_b) / 1000))) if est and start else ""
                                return i, {"completed": "Running", "eta_seconds": eta}
                    except Exception:
                        pass
                    return i, None

                with _cf_jb.ThreadPoolExecutor(max_workers=8) as _ex2:
                    _poll_results = list(_ex2.map(_poll_status, enumerate(rows)))

                for i, update in _poll_results:
                    if update is not None:
                        rows[i]["completed"]   = update["completed"]
                        rows[i]["eta_seconds"] = update.get("eta_seconds", "")
                        if completed_col:
                            ws.cell(i + 2, completed_col, update["completed"])
                        needs_save = True

                if needs_save:
                    wb.save(str(matches[0]))

            return jsonify(rows)
        except Exception as e:
            return jsonify({"error": str(e)}), 500

    @app.route("/api/tools/jbaseline/projects/<pid>/retrigger-job", methods=["POST"])
    def api_jbaseline_retrigger_job(pid):
        import openpyxl as _xl, requests as _req
        from urllib.parse import urlparse as _up
        data     = request.get_json() or {}
        job_name = (data.get("job_name") or "").strip()
        app_name = (data.get("app") or "Payor").strip()
        if not job_name:
            return jsonify({"ok": False, "error": "job_name required"}), 400
        proj_dir = JB_DATA / "projects" / app_name
        matches  = list(proj_dir.glob(f"{pid}_*.xlsx")) if proj_dir.exists() else []
        if not matches:
            return jsonify({"ok": False, "error": "Project not found"}), 404
        try:
            with _jb_per_file_lock(matches[0]):
                wb      = _xl.load_workbook(str(matches[0]))
            ws_info = wb["info"] if "info" in wb.sheetnames else None
            ws_jobs = wb["jobs"] if "jobs" in wb.sheetnames else None
            if not ws_jobs:
                return jsonify({"ok": False, "error": "No jobs sheet"}), 404
            info = {}
            if ws_info:
                for _r in ws_info.iter_rows(min_row=2, values_only=True):
                    if _r[0]:
                        info[str(_r[0]).strip()] = str(_r[1] or "").strip()
            hdrs = [str(ws_jobs.cell(1, c).value or "").strip().lower()
                    for c in range(1, ws_jobs.max_column + 1)]
            job_row_idx   = None
            job_url       = ""
            prior_build_url = ""
            current_completed = ""
            for _idx in range(2, ws_jobs.max_row + 1):
                _jn = str(ws_jobs.cell(_idx, hdrs.index("job_name") + 1).value or "").strip()
                if _jn == job_name:
                    job_row_idx = _idx
                    if "job_url" in hdrs:
                        job_url = str(ws_jobs.cell(_idx, hdrs.index("job_url") + 1).value or "").strip()
                    if "build_url" in hdrs:
                        prior_build_url = str(ws_jobs.cell(_idx, hdrs.index("build_url") + 1).value or "").strip()
                    if "completed" in hdrs:
                        current_completed = str(ws_jobs.cell(_idx, hdrs.index("completed") + 1).value or "").strip()
                    break
            if not any(k in current_completed.lower() for k in ("failed", "failure", "error", "unstable")):
                return jsonify({"ok": False, "error": f"Job {job_name} is not in a failed or unstable state (current: {current_completed or 'unknown'})"}), 400
            if not job_url:
                cfg_path = JB_ROOT / "baseline_job_config.xlsx"
                if cfg_path.exists():
                    try:
                        _cwb = _xl.load_workbook(str(cfg_path))
                        _cws = _cwb["payor"] if "payor" in _cwb.sheetnames else _cwb.active
                        for _cr in _cws.iter_rows(min_row=2, values_only=True):
                            if _cr[0] and str(_cr[0]).strip() == job_name and _cr[1]:
                                job_url = str(_cr[1]).strip(); break
                    except Exception:
                        pass
            if not job_url and not prior_build_url:
                return jsonify({"ok": False, "error": f"No URL for job {job_name}"}), 404
            _sec = {}
            try:
                if SECRETS_FILE.exists():
                    _swb = _xl.load_workbook(str(SECRETS_FILE))
                    if "Jenkins" in _swb.sheetnames:
                        for _r in _swb["Jenkins"].iter_rows(min_row=2, values_only=True):
                            if _r[0] and _r[1] is not None:
                                _sec[str(_r[0]).strip()] = str(_r[1]).strip()
            except Exception:
                pass
            _auth = ((_sec.get("jenkins_username", ""),
                      _sec.get("jenkins_api_token", "") or _sec.get("jenkins_password", ""))
                     if _sec.get("jenkins_username") else None)
            _ref_url = prior_build_url or job_url
            parsed  = _up(_ref_url)
            base    = f"{parsed.scheme}://{parsed.netloc}"
            # Params: load from jenkins_params Excel, then override with project
            # info sheet version prefixes (same approach as jreg_tool.py trigger).
            params = {}
            for _pp in [JB_ROOT / "jenkins_params" / app_name / f"payor_{job_name}_jenkins_params.xlsx",
                        JB_ROOT / "jenkins_params" / f"payor_{job_name}_jenkins_params.xlsx"]:
                if _pp.exists():
                    try:
                        _pwb = _xl.load_workbook(str(_pp))
                        _pws = _pwb["BuildParameters"] if "BuildParameters" in _pwb.sheetnames else _pwb.active
                        for _pr in _pws.iter_rows(min_row=2, values_only=True):
                            if _pr[0] and _pr[1] is not None:
                                params[str(_pr[0]).strip()] = str(_pr[1]).strip()
                    except Exception:
                        pass
                    break
            for _pk in ["PAYOR_VERSION_PREFIX", "BLUECARD_CONFIG_VERSION_PREFIX",
                        "DATAUNIVERSE_VERSION_PREFIX", "BASE_IMAGE_NAME", "DB_IMAGE_NAME", "CES_SERVER_HOST"]:
                if info.get(_pk):
                    params[_pk] = info[_pk]

            _jb_username = _sec.get("jenkins_username", "")
            _jb_password = _sec.get("jenkins_password", "")
            _jb_queue_url = ""
            _jb_triggered = False

            # ── Playwright trigger — identical pattern to jreg_tool.trigger_job_playwright ──
            _jb_pw_error = ""
            _jb_pw_st = 0
            try:
                from playwright.sync_api import sync_playwright as _spwjb
                import json as _jjsonjb
                from urllib.parse import urlencode as _uejb
                import os as _os_jb
                _sys_browsers_jb = [
                    r"C:\Program Files\Google\Chrome\Application\chrome.exe",
                    r"C:\Program Files (x86)\Google\Chrome\Application\chrome.exe",
                    r"C:\Program Files\Microsoft\Edge\Application\msedge.exe",
                    r"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe",
                ]
                _sys_browser_jb = next((p for p in _sys_browsers_jb if _os_jb.path.exists(p)), None)
                _clean_jb = {k: v for k, v in params.items() if v is not None and str(v).strip()}
                # Resolve ChoiceParameterDefinition values (Nexus prefix mapping).
                try:
                    import requests as _rq_chjb
                    _ch_rjb = _rq_chjb.get(
                        job_url.rstrip("/") + "/api/json?tree=property[parameterDefinitions[name,type,choices]]",
                        auth=(_jb_username, _jb_password), verify=False, timeout=6)
                    if _ch_rjb.status_code == 200:
                        for _prop in _ch_rjb.json().get("property", []):
                            for _pd in _prop.get("parameterDefinitions", []):
                                if _pd.get("type") == "ChoiceParameterDefinition":
                                    _pname = _pd["name"]
                                    if _pname in _clean_jb:
                                        _choices = _pd.get("choices", [])
                                        _val = _clean_jb[_pname]
                                        if _val not in _choices:
                                            _match = next((c for c in _choices if c.endswith("/" + _val) or c.endswith(_val)), None)
                                            if _match:
                                                _clean_jb[_pname] = _match
                except Exception:
                    pass
                _qs_jb = _uejb(_clean_jb)
                _bwp_jb = (job_url.rstrip("/") + "/buildWithParameters?" + _qs_jb) if _qs_jb else (job_url.rstrip("/") + "/buildWithParameters")
                _jp_jb = {"parameter": [{"name": k, "value": str(v)} for k, v in _clean_jb.items()]}
                _body_jb = _uejb({"json": _jjsonjb.dumps(_jp_jb), "delay": "0sec"})
                with _spwjb() as _pwjb:
                    _launch_jb = {"headless": True}
                    if _sys_browser_jb:
                        _launch_jb["executable_path"] = _sys_browser_jb
                    _browser_jb = _pwjb.chromium.launch(**_launch_jb)
                    _ctx_jb = _browser_jb.new_context(ignore_https_errors=True)
                    _pg_jb  = _ctx_jb.new_page()
                    _pg_jb.goto(f"{base}/login", timeout=30000)
                    _pg_jb.fill("#j_username", _jb_username)
                    _pg_jb.fill("[name='j_password']", _jb_password)
                    _pg_jb.click("[name='Submit']")
                    _pg_jb.wait_for_load_state("networkidle", timeout=20000)
                    if "/login" in _pg_jb.url:
                        _jb_pw_error = "login-failed"
                    else:
                        _pg_jb.goto(_bwp_jb, timeout=20000)
                        _pg_jb.wait_for_load_state("domcontentloaded", timeout=15000)
                        _cijb = _pg_jb.evaluate("() => { const h = document.head; return { crumb: h.getAttribute('data-crumb-value') || '', field: h.getAttribute('data-crumb-header') || 'Jenkins-Crumb' }; }")
                        _cv_jb = _cijb.get("crumb", "")
                        _cf_jb = _cijb.get("field", "Jenkins-Crumb")
                        if not _cv_jb:
                            _jb_pw_error = "no-crumb-in-page"
                        else:
                            _rjb = _ctx_jb.request.post(
                                job_url.rstrip("/") + "/build",
                                headers={_cf_jb: _cv_jb, "Content-Type": "application/x-www-form-urlencoded"},
                                data=_body_jb,
                            )
                            _jb_pw_st = _rjb.status
                            if _rjb.status in (200, 201, 302, 303):
                                _ljb = _rjb.headers.get("location", "")
                                _fljb = (_ljb if _ljb.startswith("http") else f"{base}{_ljb}") if _ljb else ""
                                _jb_queue_url = (_fljb.rstrip("/") + "/") if "/queue/item/" in _fljb else ""
                                _jb_triggered = True
                            else:
                                _jb_pw_error = f"pw-post-{_rjb.status}"
                    _browser_jb.close()
            except Exception as _jb_pwe:
                _jb_pw_error = str(_jb_pwe)[:200]

            # ── REST API fallback ─────────────────────────────────────────────────────
            if not _jb_triggered:
                import json as _jjsonjb2
                from urllib.parse import urlencode as _uejb2
                _sess_jb = _req.Session()
                _sess_jb.auth = _auth
                _sess_jb.verify = False
                crumb_h = {}
                try:
                    _cr = _sess_jb.get(f"{base}/crumbIssuer/api/json", timeout=8)
                    if _cr.status_code == 200:
                        _cj = _cr.json()
                        crumb_h = {_cj["crumbRequestField"]: _cj["crumb"]}
                except Exception:
                    pass
                _clean_jb2 = {k: v for k, v in params.items() if v is not None and str(v).strip()}
                _jp_jb2 = {"parameter": [{"name": k, "value": str(v)} for k, v in _clean_jb2.items()]}
                _body_jb2 = _uejb2({"json": _jjsonjb2.dumps(_jp_jb2), "delay": "0sec"})
                _jb_errors = []
                def _try_api_jb(endpoint):
                    try:
                        r = _sess_jb.post(endpoint, headers={**crumb_h, "Content-Type": "application/x-www-form-urlencoded"},
                                          data=_body_jb2, timeout=10)
                        _jb_errors.append(f"{endpoint} → {r.status_code}")
                        return r
                    except Exception as _ae:
                        _jb_errors.append(f"{endpoint} → {_ae}")
                        return None
                _resp = None
                if prior_build_url:
                    _resp = _try_api_jb(prior_build_url.rstrip("/") + "/rebuild/parameterized")
                if not _resp or _resp.status_code not in (200, 201, 302, 303):
                    _resp = _try_api_jb(job_url.rstrip("/") + "/build")
                if _resp and _resp.status_code in (200, 201, 302, 303):
                    _ljb2 = _resp.headers.get("Location") or ""
                    _jb_queue_url = (_ljb2.rstrip("/") + "/") if "/queue/item/" in _ljb2 else ""
                    _jb_triggered = True
                else:
                    _jb_pw_part = f"[pw:{_jb_pw_error}] " if _jb_pw_error else ""
                    return jsonify({"ok": False, "error": _jb_pw_part + (" | ".join(_jb_errors) or "no response")})

            if job_row_idx is not None:
                if "jenkins_url" in hdrs:
                    ws_jobs.cell(job_row_idx, hdrs.index("jenkins_url") + 1, _jb_queue_url)
                if "build_url" in hdrs:
                    ws_jobs.cell(job_row_idx, hdrs.index("build_url") + 1, "")
                if "completed" in hdrs:
                    ws_jobs.cell(job_row_idx, hdrs.index("completed") + 1, "Scheduled")
                with _jb_per_file_lock(matches[0]):
                    wb.save(str(matches[0]))
            return jsonify({"ok": True, "queue_url": _jb_queue_url, "status": "Scheduled",
                            "_pw_st": _jb_pw_st, "_pw_err": _jb_pw_error})
        except Exception as _e:
            return jsonify({"ok": False, "error": str(_e)}), 500

    def _clear_cw_job_urls(cw_pid, stage_key, url_prefix, job_names):
        """Remove stale Jenkins URLs for retriggered jobs from CW projects.xlsx and stage detail xlsx."""
        import json as _js_cu, openpyxl as _xl_cu
        if not cw_pid or not job_names:
            return
        # 1. Clear from extra_params.stage_outputs.{stage_key} in projects.xlsx
        try:
            with _cw_projects_lock, _cw_projects_filelock():
                _wb_cu = _xl_cu.load_workbook(str(PROJECTS))
                _ws_cu = _wb_cu.active
                _hd_cu = [str(_ws_cu.cell(1, c).value or "").strip().lower()
                          for c in range(1, _ws_cu.max_column + 1)]
                _cm_cu = {h: i for i, h in enumerate(_hd_cu, 1)}
                for _row_cu in _ws_cu.iter_rows(min_row=2):
                    if str(_row_cu[0].value or "").strip() == str(cw_pid):
                        _ep_col = _cm_cu.get("extra_params", 0)
                        if _ep_col:
                            _ep_raw = str(_row_cu[_ep_col - 1].value or "{}")
                            _ep = _js_cu.loads(_ep_raw)
                            _so = _ep.get("stage_outputs", {})
                            _sk_so = _so.get(stage_key, {})
                            for _jn in job_names:
                                _sk_so.pop(f"{url_prefix}{_jn}", None)
                            _so[stage_key] = _sk_so
                            _ep["stage_outputs"] = _so
                            _row_cu[_ep_col - 1].value = _js_cu.dumps(_ep)
                        break
                _save(_wb_cu, PROJECTS)
        except Exception:
            pass
        # 2. Clear from output_params in stage detail xlsx
        try:
            _detail = STATUS_DIR / f"{cw_pid}_payor_clone_wf_stages_status.xlsx"
            if not _detail.exists():
                return
            with _cw_per_file_lock(_detail):
                _wb_d = _xl_cu.load_workbook(str(_detail))
            _ws_d = _wb_d.active
            _hd_d = [str(_ws_d.cell(1, c).value or "").strip().lower()
                     for c in range(1, _ws_d.max_column + 1)]
            _cm_d = {h: i for i, h in enumerate(_hd_d, 1)}
            for _row_d in _ws_d.iter_rows(min_row=2):
                _sk_val = str(_row_d[_cm_d.get("stage_key", 1) - 1].value or "").strip()
                if _sk_val != stage_key:
                    continue
                _op_col = _cm_d.get("output_params", 0)
                if not _op_col:
                    break
                _op_raw = str(_row_d[_op_col - 1].value or "{}")
                _op = _js_cu.loads(_op_raw)
                for _jn in job_names:
                    _op.pop(f"{url_prefix}{_jn}", None)
                _row_d[_op_col - 1].value = _js_cu.dumps(_op)
                break
            with _cw_per_file_lock(_detail):
                _wb_d.save(str(_detail))
        except Exception:
            pass

    @app.route("/api/tools/jbaseline/projects/<pid>/retrigger-failed-jobs", methods=["POST"])
    def api_jbaseline_retrigger_failed_jobs(pid):
        """Find all failed jobs in a jbaseline project and retrigger each via rebuild/parameterized.
        Clears stale Jenkins URLs from Clone Workflow stage data for retriggered jobs."""
        import requests as _req_rfj
        _body_rfj = request.get_json() or {}
        app_name  = _body_rfj.get("app", "Payor") or "Payor"
        cw_pid    = _body_rfj.get("cw_pid")
        _port_rfj = int(_IDP_CFG.get("server_port", 5556))
        _base_rfj = f"http://127.0.0.1:{_port_rfj}"
        try:
            jobs = _req_rfj.get(
                f"{_base_rfj}/api/tools/jbaseline/projects/{pid}/jobs",
                params={"app": app_name}, timeout=10,
            ).json()
        except Exception as _e:
            return jsonify({"ok": False, "error": f"Could not load jobs: {_e}"}), 500
        if not isinstance(jobs, list):
            return jsonify({"ok": False, "error": "Unexpected jobs response"}), 500
        failed_jobs = [
            j for j in jobs
            if any(k in (j.get("completed") or "").lower()
                   for k in ("failed", "failure", "error"))
        ]
        if not failed_jobs:
            return jsonify({"ok": True, "retriggered": [], "errors": [], "message": "No failed jobs found"})
        retriggered, errors = [], []
        for fj in failed_jobs:
            try:
                r = _req_rfj.post(
                    f"{_base_rfj}/api/tools/jbaseline/projects/{pid}/retrigger-job",
                    json={"job_name": fj["job_name"], "app": app_name},
                    timeout=15,
                ).json()
                if r.get("ok"):
                    retriggered.append(fj["job_name"])
                else:
                    errors.append(f"{fj['job_name']}: {r.get('error', '?')}")
            except Exception as _je:
                errors.append(f"{fj['job_name']}: {_je}")
        # Clear stale URLs for successfully retriggered jobs from CW stage data
        if retriggered and cw_pid:
            _clear_cw_job_urls(cw_pid, "baseline", "baseline_url_", retriggered)
        return jsonify({"ok": True, "retriggered": retriggered, "errors": errors})

    @app.route("/api/tools/jreg/trigger", methods=["POST"])
    def api_jreg_trigger():
        data = request.get_json() or {}
        if not data.get("payor_version", "").strip():
            return jsonify({"ok": False, "error": "payor_version is required"})
        _app_name = data.get("app", "Payor") or "Payor"
        _wf_pid_v = data.get("_wf_pid")
        _wf_sk_v  = data.get("_wf_stage_key")
        _pvp_v    = str(data.get("payor_version_prefix") or "").strip()
        with _jreg_op_lock:
            if _jreg_op["status"] == "running":
                return jsonify({"ok": False, "error": "A Jenkins Regression run is already in progress"})
            _jreg_op.update({"status": "running", "output": "", "pid": None, "app": _app_name,
                              "_wf_pid": _wf_pid_v, "_wf_stage_key": _wf_sk_v,
                              "_payor_version_prefix": _pvp_v})
        _jreg_abort.clear()
        cmd  = ["cmd", "/c"] + _TOOL_CMD["jreg"](data)
        _threading.Thread(target=_run_jreg_bg, args=(cmd,), daemon=True).start()
        return jsonify({"ok": True})

    @app.route("/api/tools/jreg/op-status", methods=["GET"])
    def api_jreg_op_status():
        with _jreg_op_lock:
            return jsonify({"ok": True, "status": _jreg_op["status"],
                            "output": _jreg_op["output"], "pid": _jreg_op["pid"],
                            "app": _jreg_op.get("app")})

    @app.route("/api/tools/jreg/op-abort", methods=["POST"])
    def api_jreg_op_abort():
        with _jreg_op_lock:
            if _jreg_op["status"] != "running":
                return jsonify({"ok": False, "error": "No run in progress"})
            _jreg_op["output"] += "\n--- Abort requested ---\n"
            _jreg_op["status"] = "aborted"
            pid = _jreg_op.get("pid")
        _jreg_abort.set()
        if pid:
            import subprocess as _sp
            try: _sp.run(["taskkill", "/F", "/T", "/PID", str(pid)], capture_output=True)
            except Exception: pass
        return jsonify({"ok": True})

