    @app.route("/api/tools/jreg/projects/<pid>/jobs", methods=["GET"])
    def api_jreg_project_jobs(pid):
        import openpyxl as _xl, requests as _req
        _jreg_app = request.args.get("app", "Payor")
        proj_dir = JR_DATA / "projects" / _jreg_app
        if not proj_dir.exists():
            return jsonify([])
        matches = list(proj_dir.glob(f"{pid}_*.xlsx"))
        if not matches:
            return jsonify([])
        try:
            with _jr_per_file_lock(matches[0]):
                wb = _xl.load_workbook(str(matches[0]))
            if "jobs" not in wb.sheetnames:
                return jsonify([])
            ws   = wb["jobs"]
            hdrs = [str(ws.cell(1, c).value or "").strip().lower()
                    for c in range(1, ws.max_column + 1)]
            rows = []
            for row in ws.iter_rows(min_row=2, values_only=True):
                if any(v is not None for v in row):
                    rows.append({k: ("" if v is None else str(v)) for k, v in zip(hdrs, row)})

            # Resolve queue URLs → build URLs; poll running jobs for status
            if "queue_url" in hdrs and "build_url" in hdrs:
                burl_col      = hdrs.index("build_url") + 1
                completed_col = (hdrs.index("completed") + 1) if "completed" in hdrs else None
                needs_save    = False
                _sec = {}
                try:
                    if SECRETS_FILE.exists():
                        _swb = _xl.load_workbook(str(SECRETS_FILE))
                        if "Jenkins" in _swb.sheetnames:
                            for _r in _swb["Jenkins"].iter_rows(min_row=2, values_only=True):
                                if _r[0] and _r[1] is not None:
                                    _sec[str(_r[0]).strip()] = str(_r[1]).strip()
                except Exception:
                    pass
                _auth = ((_sec.get("jenkins_username", ""),
                          _sec.get("jenkins_api_token", "") or _sec.get("jenkins_password", ""))
                         if _sec.get("jenkins_username") else None)

                # Read pvp from info sheet for build-search fallback
                _pvp_raw = ""
                if "info" in wb.sheetnames:
                    for _ir in wb["info"].iter_rows(min_row=2, values_only=True):
                        if _ir and str(_ir[0] or "").strip() == "PAYOR_VERSION_PREFIX":
                            _pvp_raw = str(_ir[1] or "").strip(); break
                if ":" in _pvp_raw:
                    _pvp_raw = _pvp_raw.split(":", 1)[1].rstrip("-")

                _jb_scripts = str(JB_ROOT / "scripts")
                import sys as _sys_jr
                if _jb_scripts not in _sys_jr.path:
                    _sys_jr.path.insert(0, _jb_scripts)
                try:
                    from jbaseline_client import _search_builds_after as _sba, _pvp_matches as _pvm
                except ImportError:
                    _sba = None; _pvm = None

                # Step 1: resolve queue → build URL
                for i, row in enumerate(rows):
                    b_url = row.get("build_url", "")
                    if b_url:
                        continue  # already resolved
                    q_url        = row.get("queue_url", "")
                    resolved     = None
                    still_queued = False  # True only when queue API confirms job is still pending
                    if q_url and "/queue/item/" in q_url:
                        try:
                            qr = _req.get(q_url.rstrip("/") + "/api/json",
                                          auth=_auth, timeout=8, verify=False)
                            if qr.status_code == 200:
                                try:
                                    exe = qr.json().get("executable")
                                    if exe and exe.get("url"):
                                        candidate = exe["url"].rstrip("/") + "/"
                                        # Verify PVP matches to avoid concurrent-trigger collision
                                        if _pvp_raw and _pvm and _auth:
                                            try:
                                                vr = _req.get(
                                                    candidate.rstrip("/") + "/api/json"
                                                    "?tree=actions[parameters[name,value]]",
                                                    auth=_auth, timeout=8, verify=False)
                                                if vr.status_code == 200:
                                                    _ok = False
                                                    for _a in vr.json().get("actions", []):
                                                        for _p in _a.get("parameters", []):
                                                            if str(_p.get("name", "")) == "PAYOR_VERSION_PREFIX":
                                                                _ok = _pvm(str(_p.get("value", "")), _pvp_raw)
                                                                break
                                                        if _ok:
                                                            break
                                                    resolved = candidate if _ok else None
                                                else:
                                                    resolved = candidate
                                            except Exception:
                                                resolved = candidate
                                        else:
                                            resolved = candidate
                                    else:
                                        still_queued = True
                                except Exception:
                                    pass
                        except Exception:
                            pass
                    # Fallback: search recent builds by PAYOR_VERSION_PREFIX — more reliable
                    # than lastBuild which always returns the most recent build regardless of
                    # which trigger it came from.
                    if not resolved and not still_queued:
                        j_url = row.get("job_url", "")
                        if j_url and _sba and _pvp_raw and _auth:
                            try:
                                found = _sba(j_url, _pvp_raw, _auth, 1)
                                if found:
                                    resolved = found[0]
                            except Exception:
                                pass
                    if resolved:
                        row["build_url"] = resolved
                        ws.cell(i + 2, burl_col, resolved)
                        row["completed"] = "RUNNING"
                        if completed_col:
                            ws.cell(i + 2, completed_col, "RUNNING")
                        needs_save = True

                # Step 2: poll build status for running/scheduled jobs
                import time as _tj_r
                _now_ms_r = int(_tj_r.time() * 1000)
                for i, row in enumerate(rows):
                    b_url = row.get("build_url", "")
                    comp  = (row.get("completed") or "").lower()
                    if not b_url or comp not in ("scheduled", "running", "building"):
                        continue
                    try:
                        br = _req.get(b_url.rstrip("/") + "/api/json",
                                      auth=_auth, timeout=8, verify=False)
                        if br.status_code == 200:
                            bj       = br.json()
                            building = bj.get("building")
                            if building is False:
                                result  = (bj.get("result") or "").upper()
                                new_comp = {"SUCCESS": "Success", "FAILURE": "Failed",
                                            "ABORTED": "Aborted", "UNSTABLE": "Unstable"}.get(result, result or "Done")
                                row["completed"]   = new_comp
                                row["eta_seconds"] = ""
                                if completed_col:
                                    ws.cell(i + 2, completed_col, new_comp)
                                needs_save = True
                            else:
                                row["completed"] = "RUNNING"
                                if completed_col:
                                    ws.cell(i + 2, completed_col, "RUNNING")
                                est   = bj.get("estimatedDuration") or 0
                                start = bj.get("timestamp") or 0
                                if est and start:
                                    row["eta_seconds"] = str(max(0, int((start + est - _now_ms_r) / 1000)))
                                needs_save = True
                    except Exception:
                        pass

                if needs_save:
                    with _jr_per_file_lock(matches[0]):
                        wb.save(str(matches[0]))

            return jsonify(rows)
        except Exception as e:
            return jsonify({"error": str(e)}), 500

    @app.route("/api/tools/jreg/projects/<pid>/retrigger-job", methods=["POST"])
    def api_jreg_retrigger_job(pid):
        import openpyxl as _xl, requests as _req
        from urllib.parse import urlparse as _up
        data     = request.get_json() or {}
        job_name = (data.get("job_name") or "").strip()
        app_name = (data.get("app") or "Payor").strip()
        if not job_name:
            return jsonify({"ok": False, "error": "job_name required"}), 400
        proj_dir = JR_DATA / "projects" / app_name
        matches  = list(proj_dir.glob(f"{pid}_*.xlsx")) if proj_dir.exists() else []
        if not matches:
            return jsonify({"ok": False, "error": "Project not found"}), 404
        try:
            wb      = _xl.load_workbook(str(matches[0]))
            ws_info = wb["info"] if "info" in wb.sheetnames else None
            ws_jobs = wb["jobs"] if "jobs" in wb.sheetnames else None
            if not ws_jobs:
                return jsonify({"ok": False, "error": "No jobs sheet"}), 404
            info = {}
            if ws_info:
                for _r in ws_info.iter_rows(min_row=2, values_only=True):
                    if _r[0]:
                        info[str(_r[0]).strip()] = str(_r[1] or "").strip()
            hdrs = [str(ws_jobs.cell(1, c).value or "").strip().lower()
                    for c in range(1, ws_jobs.max_column + 1)]
            job_row_idx     = None
            job_url         = ""
            prior_build_url = ""
            current_completed = ""
            for _idx in range(2, ws_jobs.max_row + 1):
                _jn = str(ws_jobs.cell(_idx, hdrs.index("job_name") + 1).value or "").strip()
                if _jn == job_name:
                    job_row_idx = _idx
                    if "job_url" in hdrs:
                        job_url = str(ws_jobs.cell(_idx, hdrs.index("job_url") + 1).value or "").strip()
                    if "build_url" in hdrs:
                        prior_build_url = str(ws_jobs.cell(_idx, hdrs.index("build_url") + 1).value or "").strip()
                    if "completed" in hdrs:
                        current_completed = str(ws_jobs.cell(_idx, hdrs.index("completed") + 1).value or "").strip()
                    break
            if not any(k in current_completed.lower() for k in ("failed", "failure", "error", "unstable")):
                return jsonify({"ok": False, "error": f"Job {job_name} is not in a failed or unstable state (current: {current_completed or 'unknown'})"}), 400
            if not job_url:
                cfg_path = JR_ROOT / "reg_job_config.xlsx"
                if cfg_path.exists():
                    try:
                        _cwb = _xl.load_workbook(str(cfg_path))
                        _cws = _cwb["payor"] if "payor" in _cwb.sheetnames else _cwb.active
                        for _cr in _cws.iter_rows(min_row=2, values_only=True):
                            if _cr[0] and str(_cr[0]).strip() == job_name and _cr[1]:
                                job_url = str(_cr[1]).strip(); break
                    except Exception:
                        pass
            if not job_url and not prior_build_url:
                return jsonify({"ok": False, "error": f"No URL for job {job_name}"}), 404
            _sec = {}
            try:
                if SECRETS_FILE.exists():
                    _swb = _xl.load_workbook(str(SECRETS_FILE))
                    if "Jenkins" in _swb.sheetnames:
                        for _r in _swb["Jenkins"].iter_rows(min_row=2, values_only=True):
                            if _r[0] and _r[1] is not None:
                                _sec[str(_r[0]).strip()] = str(_r[1]).strip()
            except Exception:
                pass
            _auth = ((_sec.get("jenkins_username", ""),
                      _sec.get("jenkins_api_token", "") or _sec.get("jenkins_password", ""))
                     if _sec.get("jenkins_username") else None)
            _ref_url = prior_build_url or job_url
            parsed  = _up(_ref_url)
            base    = f"{parsed.scheme}://{parsed.netloc}"
            # Params: load from jenkins_params Excel, then override with project
            # info sheet version prefixes (same approach as jreg_tool.py trigger).
            params = {}
            for _pp in [JR_ROOT / "jenkins_params" / app_name / f"payor_{job_name}_jenkins_params.xlsx",
                        JR_ROOT / "jenkins_params" / f"payor_{job_name}_jenkins_params.xlsx"]:
                if _pp.exists():
                    try:
                        _pwb = _xl.load_workbook(str(_pp))
                        _pws = _pwb["BuildParameters"] if "BuildParameters" in _pwb.sheetnames else _pwb.active
                        for _pr in _pws.iter_rows(min_row=2, values_only=True):
                            if _pr[0] and _pr[1] is not None:
                                params[str(_pr[0]).strip()] = str(_pr[1]).strip()
                    except Exception:
                        pass
                    break
            for _pk in ["PAYOR_VERSION_PREFIX", "BLUECARD_CONFIG_VERSION_PREFIX",
                        "DATAUNIVERSE_VERSION_PREFIX", "BASE_IMAGE_NAME", "DB_IMAGE_NAME", "CES_SERVER_HOST"]:
                if info.get(_pk):
                    params[_pk] = info[_pk]

            _jr_username = _sec.get("jenkins_username", "")
            _jr_password = _sec.get("jenkins_password", "")
            _jr_queue_url = ""
            _jr_triggered = False

            # ── Playwright trigger — identical pattern to jreg_tool.trigger_job_playwright ──
            _pw_error = ""
            _pw_st = 0
            try:
                from playwright.sync_api import sync_playwright as _spw
                import json as _jjson
                from urllib.parse import urlencode as _ue
                import os as _os_jr
                _sys_browsers = [
                    r"C:\Program Files\Google\Chrome\Application\chrome.exe",
                    r"C:\Program Files (x86)\Google\Chrome\Application\chrome.exe",
                    r"C:\Program Files\Microsoft\Edge\Application\msedge.exe",
                    r"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe",
                ]
                _sys_browser = next((p for p in _sys_browsers if _os_jr.path.exists(p)), None)
                _clean = {k: v for k, v in params.items() if v is not None and str(v).strip()}
                # Resolve ChoiceParameterDefinition values: stored values may omit the
                # Nexus registry prefix; match by suffix against the job's valid choices.
                try:
                    import requests as _rq_ch
                    _ch_resp = _rq_ch.get(
                        job_url.rstrip("/") + "/api/json?tree=property[parameterDefinitions[name,type,choices]]",
                        auth=(_jr_username, _jr_password), verify=False, timeout=6)
                    if _ch_resp.status_code == 200:
                        for _prop in _ch_resp.json().get("property", []):
                            for _pd in _prop.get("parameterDefinitions", []):
                                if _pd.get("type") == "ChoiceParameterDefinition":
                                    _pname = _pd["name"]
                                    if _pname in _clean:
                                        _choices = _pd.get("choices", [])
                                        _val = _clean[_pname]
                                        if _val not in _choices:
                                            _match = next((c for c in _choices if c.endswith("/" + _val) or c.endswith(_val)), None)
                                            if _match:
                                                _clean[_pname] = _match
                except Exception:
                    pass
                _qs = _ue(_clean)
                _bwp_url = (job_url.rstrip("/") + "/buildWithParameters?" + _qs) if _qs else (job_url.rstrip("/") + "/buildWithParameters")
                _json_params = {"parameter": [{"name": k, "value": str(v)} for k, v in _clean.items()]}
                _body_str = _ue({"json": _jjson.dumps(_json_params), "delay": "0sec"})
                with _spw() as _pw:
                    _launch_opts = {"headless": True}
                    if _sys_browser:
                        _launch_opts["executable_path"] = _sys_browser
                    _browser = _pw.chromium.launch(**_launch_opts)
                    _ctx = _browser.new_context(ignore_https_errors=True)
                    _pg  = _ctx.new_page()
                    _pg.goto(f"{base}/login", timeout=30000)
                    _pg.fill("#j_username", _jr_username)
                    _pg.fill("[name='j_password']", _jr_password)
                    _pg.click("[name='Submit']")
                    _pg.wait_for_load_state("networkidle", timeout=20000)
                    if "/login" in _pg.url:
                        _pw_error = "login-failed"
                    else:
                        _pg.goto(_bwp_url, timeout=20000)
                        _pg.wait_for_load_state("domcontentloaded", timeout=15000)
                        _ci = _pg.evaluate("() => { const h = document.head; return { crumb: h.getAttribute('data-crumb-value') || '', field: h.getAttribute('data-crumb-header') || 'Jenkins-Crumb' }; }")
                        _crumb_val = _ci.get("crumb", "")
                        _crumb_field = _ci.get("field", "Jenkins-Crumb")
                        if not _crumb_val:
                            _pw_error = "no-crumb-in-page"
                        else:
                            _pr2 = _ctx.request.post(
                                job_url.rstrip("/") + "/build",
                                headers={_crumb_field: _crumb_val, "Content-Type": "application/x-www-form-urlencoded"},
                                data=_body_str,
                            )
                            _st2 = _pr2.status
                            _pw_st = _st2
                            if _st2 in (200, 201, 302, 303):
                                _loc2 = _pr2.headers.get("location", "")
                                _full2 = (_loc2 if _loc2.startswith("http") else f"{base}{_loc2}") if _loc2 else ""
                                _jr_queue_url = (_full2.rstrip("/") + "/") if "/queue/item/" in _full2 else ""
                                _jr_triggered = True
                            else:
                                _pw_error = f"pw-post-{_st2}"
                    _browser.close()
            except Exception as _pwe:
                _pw_error = str(_pwe)[:200]

            # ── REST API fallback ─────────────────────────────────────────────────────
            if not _jr_triggered:
                import json as _jjson2
                from urllib.parse import urlencode as _ue2
                _sess_jr = _req.Session()
                _sess_jr.auth = _auth
                _sess_jr.verify = False
                crumb_h = {}
                try:
                    _cr = _sess_jr.get(f"{base}/crumbIssuer/api/json", timeout=8)
                    if _cr.status_code == 200:
                        _cj = _cr.json()
                        crumb_h = {_cj["crumbRequestField"]: _cj["crumb"]}
                except Exception:
                    pass
                _clean2 = {k: v for k, v in params.items() if v is not None and str(v).strip()}
                _jp2 = {"parameter": [{"name": k, "value": str(v)} for k, v in _clean2.items()]}
                _body2 = _ue2({"json": _jjson2.dumps(_jp2), "delay": "0sec"})
                _api_errors = []
                def _try_api(endpoint, **kw):
                    try:
                        r = _sess_jr.post(endpoint, headers={**crumb_h, "Content-Type": "application/x-www-form-urlencoded"},
                                          data=_body2, timeout=10)
                        _api_errors.append(f"{endpoint} → {r.status_code}")
                        return r
                    except Exception as _ae:
                        _api_errors.append(f"{endpoint} → {_ae}")
                        return None
                _resp = None
                if prior_build_url:
                    _resp = _try_api(prior_build_url.rstrip("/") + "/rebuild/parameterized")
                if not _resp or _resp.status_code not in (200, 201, 302, 303):
                    _resp = _try_api(job_url.rstrip("/") + "/build")
                if _resp and _resp.status_code in (200, 201, 302, 303):
                    _loc3 = _resp.headers.get("Location") or ""
                    _jr_queue_url = (_loc3.rstrip("/") + "/") if "/queue/item/" in _loc3 else ""
                    _jr_triggered = True
                else:
                    _pw_part = f"[pw:{_pw_error}] " if _pw_error else ""
                    return jsonify({"ok": False, "error": _pw_part + (" | ".join(_api_errors) or "no response")})

            if job_row_idx is not None:
                if "queue_url" in hdrs:
                    ws_jobs.cell(job_row_idx, hdrs.index("queue_url") + 1, _jr_queue_url)
                if "build_url" in hdrs:
                    ws_jobs.cell(job_row_idx, hdrs.index("build_url") + 1, "")
                if "completed" in hdrs:
                    ws_jobs.cell(job_row_idx, hdrs.index("completed") + 1, "Scheduled")
                wb.save(str(matches[0]))
            return jsonify({"ok": True, "queue_url": _jr_queue_url, "status": "Scheduled",
                            "_pw_st": _pw_st, "_pw_err": _pw_error})
        except Exception as _e:
            return jsonify({"ok": False, "error": str(_e)}), 500

    @app.route("/api/tools/jreg/projects/<pid>/retrigger-failed-jobs", methods=["POST"])
    def api_jreg_retrigger_failed_jobs(pid):
        """Find all failed jobs in a jreg project and retrigger each via rebuild/parameterized.
        Clears stale Jenkins URLs from Clone Workflow stage data for retriggered jobs."""
        import requests as _req_rfj2
        _body_rfj2 = request.get_json() or {}
        app_name   = _body_rfj2.get("app", "Payor") or "Payor"
        cw_pid     = _body_rfj2.get("cw_pid")
        _port_rfj2 = int(_IDP_CFG.get("server_port", 5556))
        _base_rfj2 = f"http://127.0.0.1:{_port_rfj2}"
        try:
            jobs = _req_rfj2.get(
                f"{_base_rfj2}/api/tools/jreg/projects/{pid}/jobs",
                params={"app": app_name}, timeout=10,
            ).json()
        except Exception as _e:
            return jsonify({"ok": False, "error": f"Could not load jobs: {_e}"}), 500
        if not isinstance(jobs, list):
            return jsonify({"ok": False, "error": "Unexpected jobs response"}), 500
        failed_jobs = [
            j for j in jobs
            if any(k in (j.get("completed") or "").lower()
                   for k in ("failed", "failure", "error"))
        ]
        if not failed_jobs:
            return jsonify({"ok": True, "retriggered": [], "errors": [], "message": "No failed jobs found"})
        retriggered, errors = [], []
        for fj in failed_jobs:
            try:
                r = _req_rfj2.post(
                    f"{_base_rfj2}/api/tools/jreg/projects/{pid}/retrigger-job",
                    json={"job_name": fj["job_name"], "app": app_name},
                    timeout=15,
                ).json()
                if r.get("ok"):
                    retriggered.append(fj["job_name"])
                else:
                    errors.append(f"{fj['job_name']}: {r.get('error', '?')}")
            except Exception as _je:
                errors.append(f"{fj['job_name']}: {_je}")
        # Clear stale URLs for successfully retriggered jobs from CW stage data
        if retriggered and cw_pid:
            _clear_cw_job_urls(cw_pid, "jreg", "jreg_url_", retriggered)
        # After retrigger: sync projects.xlsx to clear "failed" and restart the poller
        if retriggered:
            try:
                import openpyxl as _xl_rj2, sys as _sys_rj2
                _pid_int_rj2  = int(pid)
                _proj_dir_rj2 = JR_DATA / "projects" / app_name
                _files_rj2    = sorted(
                    _proj_dir_rj2.glob(f"{_pid_int_rj2}_*.xlsx"),
                    key=lambda p: int(p.stem.split("_")[0]) if p.stem.split("_")[0].isdigit() else 0,
                    reverse=True)
                if _files_rj2:
                    _wb_rj2  = _xl_rj2.load_workbook(str(_files_rj2[0]), data_only=True)
                    _sts_rj2 = []
                    if "jobs" in _wb_rj2.sheetnames:
                        _ws_rj2 = _wb_rj2["jobs"]
                        _hd_rj2 = [str(c.value or "").strip().lower() for c in _ws_rj2[1]]
                        if "completed" in _hd_rj2:
                            _cc_rj2 = _hd_rj2.index("completed")
                            for _rw_rj2 in _ws_rj2.iter_rows(min_row=2, values_only=True):
                                if any(v is not None for v in _rw_rj2):
                                    _sts_rj2.append(str(_rw_rj2[_cc_rj2] or "").strip().lower())
                    _wb_rj2.close()
                    if _sts_rj2:
                        _JS_ORD_RJ2 = ("failed", "trigger failed", "unstable", "aborted",
                                       "running", "scheduled", "success")
                        _cnts_rj2 = {}
                        for _s_rj2 in _sts_rj2:
                            _k_rj2 = _s_rj2
                            if _k_rj2 in ("success", "passed"):   _k_rj2 = "success"
                            elif _k_rj2 in ("failure", "failed"): _k_rj2 = "failed"
                            elif "trigger failed" in _k_rj2:      _k_rj2 = "trigger failed"
                            _cnts_rj2[_k_rj2] = _cnts_rj2.get(_k_rj2, 0) + 1
                        _total_rj2  = len(_sts_rj2)
                        _parts_rj2  = [f"{_cnts_rj2[k]} {k}" for k in _JS_ORD_RJ2 if _cnts_rj2.get(k)]
                        _parts_rj2 += [f"{v} {k}" for k, v in _cnts_rj2.items()
                                       if k not in _JS_ORD_RJ2 and v]
                        _status_rj2 = (f"{_total_rj2} jobs: {' '.join(_parts_rj2)}"
                                       if _parts_rj2 else f"{_total_rj2} jobs")
                        _jr_sc_rj2 = str(JR_ROOT / "scripts")
                        if _jr_sc_rj2 not in _sys_rj2.path:
                            _sys_rj2.path.insert(0, _jr_sc_rj2)
                        from jreg_tool import update_run_status as _urs_rj2
                        with _jreg_projects_lock, _jr_projects_filelock():
                            _urs_rj2(_pid_int_rj2, _status_rj2, app_name)
            except Exception:
                pass
            with _jreg_op_lock:
                _jreg_op["status"] = "running"
                _jreg_op["app"]    = app_name
            _threading.Thread(
                target=_jreg_job_poller, args=(app_name,), daemon=True
            ).start()
        return jsonify({"ok": True, "retriggered": retriggered, "errors": errors})

    @app.route("/api/tools/jreg/projects/<pid>/sync-from-jenkins", methods=["POST"])
    def api_jreg_sync_from_jenkins(pid):
        """For each job stuck at 'Scheduled' with no build_url, search Jenkins recent
        builds by PAYOR_VERSION_PREFIX and update build_url + status in the per-project
        xlsx, then sync projects.xlsx and restart the poller."""
        import openpyxl as _xl_sfj, sys as _sys_sfj, requests as _req_sfj
        _body_sfj = request.get_json() or {}
        app_name  = (_body_sfj.get("app") or "Payor").strip()
        try:
            _pid_sfj = int(pid)
        except (ValueError, TypeError):
            return jsonify({"ok": False, "error": "invalid pid"}), 400

        # Load per-project xlsx
        _proj_dir_sfj = JR_DATA / "projects" / app_name
        _files_sfj    = sorted(
            _proj_dir_sfj.glob(f"{_pid_sfj}_*.xlsx"),
            key=lambda p: int(p.stem.split("_")[0]) if p.stem.split("_")[0].isdigit() else 0,
            reverse=True) if _proj_dir_sfj.exists() else []
        if not _files_sfj:
            return jsonify({"ok": False, "error": f"No project found for pid {_pid_sfj}"}), 404

        _path_sfj = _files_sfj[0]
        try:
            _wb_sfj = _xl_sfj.load_workbook(str(_path_sfj))
        except Exception as _e_sfj:
            return jsonify({"ok": False, "error": str(_e_sfj)}), 500

        # Read PAYOR_VERSION_PREFIX from info sheet
        _pvp_sfj = ""
        if "info" in _wb_sfj.sheetnames:
            for _ir in _wb_sfj["info"].iter_rows(min_row=2, values_only=True):
                if _ir and str(_ir[0] or "").strip() == "PAYOR_VERSION_PREFIX":
                    _pvp_sfj = str(_ir[1] or "").strip(); break
        if ":" in _pvp_sfj:
            _pvp_sfj = _pvp_sfj.split(":", 1)[1].rstrip("-")
        if not _pvp_sfj:
            return jsonify({"ok": False, "error": "PAYOR_VERSION_PREFIX not found in project info"}), 400

        # Load Jenkins credentials
        _sec_sfj = {}
        try:
            if SECRETS_FILE.exists():
                _swb_sfj = _xl_sfj.load_workbook(str(SECRETS_FILE))
                if "Jenkins" in _swb_sfj.sheetnames:
                    for _r_sfj in _swb_sfj["Jenkins"].iter_rows(min_row=2, values_only=True):
                        if _r_sfj[0] and _r_sfj[1] is not None:
                            _sec_sfj[str(_r_sfj[0]).strip()] = str(_r_sfj[1]).strip()
        except Exception:
            pass
        _auth_sfj = ((_sec_sfj.get("jenkins_username", ""),
                      _sec_sfj.get("jenkins_api_token", "") or _sec_sfj.get("jenkins_password", ""))
                     if _sec_sfj.get("jenkins_username") else None)

        # Load jreg_client helpers
        _jr_sc_sfj = str(JR_ROOT / "scripts")
        if _jr_sc_sfj not in _sys_sfj.path:
            _sys_sfj.path.insert(0, _jr_sc_sfj)
        try:
            from jreg_client import _search_builds_after as _sba_sfj, _poll_build_status as _pbs_sfj
        except ImportError:
            return jsonify({"ok": False, "error": "jreg_client not available"}), 500

        # Load job URL map from reg_job_config.xlsx
        _jurl_sfj = {}
        try:
            _cfg_sfj = JR_ROOT / "reg_job_config.xlsx"
            if _cfg_sfj.exists():
                _cwb_sfj = _xl_sfj.load_workbook(str(_cfg_sfj))
                _csh_sfj = "payor" if "payor" in _cwb_sfj.sheetnames else _cwb_sfj.active.title
                for _cr_sfj in _cwb_sfj[_csh_sfj].iter_rows(min_row=2, values_only=True):
                    if _cr_sfj[0] and _cr_sfj[1]:
                        _jurl_sfj[str(_cr_sfj[0]).strip()] = str(_cr_sfj[1]).strip()
        except Exception:
            pass

        # Process jobs sheet
        if "jobs" not in _wb_sfj.sheetnames:
            return jsonify({"ok": False, "error": "No jobs sheet"}), 400
        _ws_sfj  = _wb_sfj["jobs"]
        _hd_sfj  = [str(c.value or "").strip().lower() for c in _ws_sfj[1]]
        _cm_sfj  = {h: i for i, h in enumerate(_hd_sfj)}
        _updated = []
        _skipped = []

        _JS_ORD_SFJ    = ("failed", "trigger failed", "unstable", "aborted",
                          "running", "scheduled", "success")
        _final_sts_sfj = []

        for _row_idx in range(2, _ws_sfj.max_row + 1):
            _rv = [_ws_sfj.cell(_row_idx, c + 1).value for c in range(len(_hd_sfj))]
            if not any(v is not None for v in _rv):
                continue
            _get   = lambda k: str(_rv[_cm_sfj[k]] or "").strip() if k in _cm_sfj else ""
            _jname = _get("job_name")
            _burl  = _get("build_url")
            _comp  = _get("completed")
            _jurl  = _get("job_url") or _jurl_sfj.get(_jname, "")

            # Only process jobs stuck as Scheduled with no build URL
            if _burl or _comp.lower() not in ("scheduled", ""):
                _final_sts_sfj.append(_comp)
                continue

            if not _jurl or not _auth_sfj:
                _skipped.append(_jname)
                _final_sts_sfj.append(_comp)
                continue

            # Search Jenkins by PVP
            try:
                _found_sfj = _sba_sfj(_jurl, _pvp_sfj, _auth_sfj, 1)
            except Exception:
                _found_sfj = []

            if _found_sfj:
                _new_burl = _found_sfj[0]
                try:
                    _new_st = _pbs_sfj(_new_burl, _auth_sfj) or "Running"
                except Exception:
                    _new_st = "Running"
                _norm = {"SUCCESS": "Success", "PASSED": "Success",
                         "FAILURE": "Failed",  "FAILED": "Failed",
                         "ABORTED": "Aborted", "UNSTABLE": "Unstable",
                         "RUNNING": "Running"}.get(_new_st.upper(), _new_st.capitalize())
                if "build_url" in _cm_sfj:
                    _ws_sfj.cell(_row_idx, _cm_sfj["build_url"] + 1, _new_burl)
                if "completed" in _cm_sfj:
                    _ws_sfj.cell(_row_idx, _cm_sfj["completed"] + 1, _norm)
                _updated.append({"job": _jname, "build_url": _new_burl, "status": _norm})
                _final_sts_sfj.append(_norm)
            else:
                _skipped.append(_jname)
                _final_sts_sfj.append(_comp)

        # Save per-project xlsx
        try:
            _wb_sfj.save(str(_path_sfj))
        except Exception as _e_sv:
            return jsonify({"ok": False, "error": f"Save failed: {_e_sv}"}), 500

        # Sync JR_ROOT/projects.xlsx with new statuses
        if _final_sts_sfj:
            try:
                _cnts_sfj = {}
                for _s_sfj in _final_sts_sfj:
                    _k_sfj = _s_sfj.strip().lower()
                    if _k_sfj in ("success", "passed"):   _k_sfj = "success"
                    elif _k_sfj in ("failure", "failed"): _k_sfj = "failed"
                    elif "trigger failed" in _k_sfj:      _k_sfj = "trigger failed"
                    _cnts_sfj[_k_sfj] = _cnts_sfj.get(_k_sfj, 0) + 1
                _total_sfj  = len(_final_sts_sfj)
                _parts_sfj  = [f"{_cnts_sfj[k]} {k}" for k in _JS_ORD_SFJ if _cnts_sfj.get(k)]
                _parts_sfj += [f"{v} {k}" for k, v in _cnts_sfj.items() if k not in _JS_ORD_SFJ and v]
                _status_sfj = (f"{_total_sfj} jobs: {' '.join(_parts_sfj)}"
                               if _parts_sfj else f"{_total_sfj} jobs")
                from jreg_tool import update_run_status as _urs_sfj
                with _jreg_projects_lock, _jr_projects_filelock():
                    _urs_sfj(_pid_sfj, _status_sfj, app_name)
            except Exception:
                pass

        # Restart poller if any jobs were found/updated
        if _updated:
            with _jreg_op_lock:
                _jreg_op["status"] = "running"
                _jreg_op["app"]    = app_name
            _threading.Thread(
                target=_jreg_job_poller, args=(app_name,), daemon=True
            ).start()

        return jsonify({"ok": True, "updated": _updated, "skipped": _skipped,
                        "pvp": _pvp_sfj})

    # ── Melissa Update — create project & execute ────────────────────────────

    _MDL_HDR       = ["pid", "timestamp", "ticket", "release_branch", "vm_name", "vm_ip", "status", "changes", "notes"]
    _MDL_WIDTHS    = [6, 22, 18, 16, 24, 18, 12, 8, 80]
    _MDL_HEADER_FILL = "1F3864"

    def _mdl_ensure():
        import openpyxl as _xl, zipfile as _zf
        from openpyxl.styles import Font as _F, PatternFill as _PF, Alignment as _Aln
        if MDL_ROOT.exists() and not (MDL_DATA / "projects.xlsx").exists():
            MDL_ROOT.mkdir(parents=True, exist_ok=True)
        path = MDL_DATA / "projects.xlsx"
        if path.exists():
            return path
        wb = _xl.Workbook(); ws = wb.active; ws.title = "Projects"
        for col, (title, width) in enumerate(zip(_MDL_HDR, _MDL_WIDTHS), start=1):
            c = ws.cell(1, col, title)
            c.font = _F(color="FFFFFF", bold=True, name="Calibri")
            c.fill = _PF("solid", fgColor=_MDL_HEADER_FILL)
            c.alignment = _Aln(horizontal="left")
            ws.column_dimensions[c.column_letter].width = width
        wb.save(str(path)); return path

    def _mdl_next_pid():
        path = MDL_DATA / "projects.xlsx"
        if not path.exists(): return 1
        import openpyxl as _xl
        try:
            wb = _xl.load_workbook(str(path), read_only=True, data_only=True)
            ws = wb.active
            return max((ws.cell(r, 1).value or 0 for r in range(2, ws.max_row + 1)), default=0) + 1
        except Exception: return 1

    @app.route("/api/tools/melissa/projects", methods=["POST"])
    def api_melissa_create_project():
        import openpyxl as _xl
        from openpyxl.styles import Font as _F, PatternFill as _PF, Alignment as _Aln
        from datetime import datetime as _dt_ml
        data          = request.get_json() or {}
        ticket        = str(data.get("ticket", "") or "").strip()
        release_branch= str(data.get("release_branch", "") or "").strip()
        vm_name       = str(data.get("vm_name", "") or "").strip()
        if not vm_name:
            return jsonify({"ok": False, "error": "vm_name is required"}), 400
        # Look up VM IP from vms.xlsx
        vm_ip = ""
        try:
            vms_data = _rows(VMS_FILE)
            hit = next((v for v in vms_data if str(v.get("name", "")).strip() == vm_name), None)
            if hit:
                vm_ip = str(hit.get("ip", "") or "").strip()
        except Exception: pass
        path = _mdl_ensure()
        ts   = _dt_ml.now().strftime("%Y-%m-%d %H:%M:%S")
        pid  = None
        try:
            with _mdl_projects_lock, _mdl_projects_filelock():
                pid = _mdl_next_pid()
                wb = _xl.load_workbook(str(path))
                ws = wb.active
                hdrs = [str(ws.cell(1, c).value or "").strip().lower() for c in range(1, ws.max_column + 1)]
                # Add missing columns
                for col_name, width in (("ticket", 18), ("release_branch", 16)):
                    if col_name not in hdrs:
                        col_idx = ws.max_column + 1
                        c = ws.cell(1, col_idx, col_name)
                        c.font = _F(color="FFFFFF", bold=True, name="Calibri")
                        c.fill = _PF("solid", fgColor=_MDL_HEADER_FILL)
                        c.alignment = _Aln(horizontal="left")
                        ws.column_dimensions[c.column_letter].width = width
                hdrs = [str(ws.cell(1, c).value or "").strip().lower() for c in range(1, ws.max_column + 1)]
                row_map = {"pid": pid, "timestamp": ts, "ticket": ticket,
                           "release_branch": release_branch, "vm_name": vm_name,
                           "vm_ip": vm_ip, "status": "Pending", "changes": "", "notes": ""}
                ws.append([row_map.get(h, "") for h in hdrs])
                wb.save(str(path))
        except Exception as _e:
            return jsonify({"ok": False, "error": str(_e)}), 500
        return jsonify({"ok": True, "pid": pid})

    @app.route("/api/tools/melissa/projects/<int:pid>/execute", methods=["POST"])
    def api_melissa_execute_project(pid):
        import openpyxl as _xl, subprocess as _sp, threading as _thr, os as _os_ml, uuid as _uuid_ml
        path = MDL_DATA / "projects.xlsx"
        if not path.exists():
            return jsonify({"ok": False, "error": "projects.xlsx not found"}), 404
        # Read the project row
        try:
            with _mdl_projects_lock, _mdl_projects_filelock():
                wb = _xl.load_workbook(str(path), data_only=True)
            ws = wb.active
            hdrs = [str(ws.cell(1, c).value or "").strip().lower() for c in range(1, ws.max_column + 1)]
            row_data = None
            for row in ws.iter_rows(min_row=2, values_only=True):
                if str(row[0] or "").strip() == str(pid):
                    row_data = {k: (str(v).strip() if v is not None else "") for k, v in zip(hdrs, row)}
                    break
        except Exception as _e:
            return jsonify({"ok": False, "error": str(_e)}), 500
        if not row_data:
            return jsonify({"ok": False, "error": f"Project #{pid} not found"}), 404
        vm_name        = row_data.get("vm_name", "")
        ticket         = row_data.get("ticket", "")
        release_branch = row_data.get("release_branch", "")
        if not vm_name:
            return jsonify({"ok": False, "error": "No VM name stored in project row"}), 400
        # Update status to Running
        try:
            with _mdl_projects_lock, _mdl_projects_filelock():
                wb2 = _xl.load_workbook(str(path))
                ws2 = wb2.active
                hdrs2 = [str(ws2.cell(1, c).value or "").strip().lower() for c in range(1, ws2.max_column + 1)]
                for row2 in ws2.iter_rows(min_row=2):
                    if str(row2[0].value or "").strip() == str(pid):
                        if "status" in hdrs2:
                            row2[hdrs2.index("status")].value = "Running"
                        break
                wb2.save(str(path))
        except Exception: pass
        # Build command
        run_id = _uuid_ml.uuid4().hex[:10]
        cmd = ["cmd", "/c", "updatemdl",
               "--vm", vm_name, "--pid", str(pid)]
        if ticket:         cmd += ["--ticket",         ticket]
        if release_branch: cmd += ["--release-branch", release_branch]
        _env = {**_os_ml.environ, "PYTHONUNBUFFERED": "1",
                "PYTHONIOENCODING": "utf-8", "PYTHONUTF8": "1"}
        try:
            proc = _sp.Popen(
                cmd,
                stdout=_sp.PIPE, stderr=_sp.STDOUT,
                creationflags=0x08000000,
                text=True, encoding="utf-8", errors="replace",
                bufsize=1,
                env=_env,
            )
        except Exception as _e:
            return jsonify({"ok": False, "error": str(_e)}), 500
        _mdl_state = {"proc": proc, "lines": [], "status": "running", "returncode": None}
        with _mdl_run_lock:
            _mdl_run_procs[run_id] = _mdl_state
        def _mdl_read():
            try:
                for line in proc.stdout:
                    with _mdl_run_lock:
                        _mdl_state["lines"].append(line.rstrip("\n"))
                proc.wait()
                with _mdl_run_lock:
                    _mdl_state["returncode"] = proc.returncode
                    if _mdl_state["status"] == "running":
                        _mdl_state["status"] = "done" if proc.returncode == 0 else "failed"
            except Exception as exc:
                with _mdl_run_lock:
                    _mdl_state["lines"].append(f"[reader error: {exc}]")
                    _mdl_state["status"] = "failed"
        _thr.Thread(target=_mdl_read, daemon=True).start()
        return jsonify({"ok": True, "pid": pid, "run_id": run_id})

    @app.route("/api/tools/melissa/output/<run_id>", methods=["GET"])
    def api_melissa_output(run_id):
        with _mdl_run_lock:
            state = _mdl_run_procs.get(run_id)
        if not state:
            return jsonify({"ok": False, "error": "Unknown run_id"}), 404
        with _mdl_run_lock:
            return jsonify({
                "ok":         True,
                "output":     "\n".join(state["lines"]),
                "status":     state["status"],
                "returncode": state["returncode"],
            })

    # ── Melissa scheduler config ─────────────────────────────────────────────

    _MDL_SCHED_CFG = MDL_ROOT / "scheduler_config.xlsx"
    _MDL_DEFAULT_INTERVAL = 1   # minutes

    def _mdl_read_interval():
        if not _MDL_SCHED_CFG.exists():
            return _MDL_DEFAULT_INTERVAL
        import openpyxl as _xl_ms
        try:
            wb = _xl_ms.load_workbook(str(_MDL_SCHED_CFG), data_only=True)
            for row in wb.active.iter_rows(min_row=2, values_only=True):
                if str(row[0] or "").strip().lower() == "auto_refresh_interval":
                    return int(row[1] or _MDL_DEFAULT_INTERVAL)
        except Exception:
            pass
        return _MDL_DEFAULT_INTERVAL

    def _mdl_write_interval(mins):
        import openpyxl as _xl_ms2
        from openpyxl.styles import Font as _Fms, PatternFill as _PFms, Alignment as _Alms
        MDL_ROOT.mkdir(parents=True, exist_ok=True)
        if not _MDL_SCHED_CFG.exists():
            wb = _xl_ms2.Workbook(); ws = wb.active; ws.title = "Config"
            for col, val in enumerate(["Key", "Value", "Notes"], 1):
                c = ws.cell(1, col, val)
                c.font = _Fms(color="FFFFFF", bold=True)
                c.fill = _PFms("solid", fgColor="1F3864")
            ws.append(["auto_refresh_interval", mins, "Auto refresh interval in minutes (0 = off)"])
            wb.save(str(_MDL_SCHED_CFG)); return
        wb = _xl_ms2.load_workbook(str(_MDL_SCHED_CFG)); ws = wb.active
        updated = False
        for row in ws.iter_rows(min_row=2):
            if str(row[0].value or "").strip().lower() == "auto_refresh_interval":
                row[1].value = mins; updated = True; break
        if not updated:
            ws.append(["auto_refresh_interval", mins, "Auto refresh interval in minutes (0 = off)"])
        wb.save(str(_MDL_SCHED_CFG))

    @app.route("/api/tools/melissa/scheduler-config", methods=["GET"])
    def api_melissa_get_scheduler_config():
        return jsonify({"ok": True, "interval_minutes": _mdl_read_interval()})

    @app.route("/api/tools/melissa/scheduler-config", methods=["PUT"])
    def api_melissa_put_scheduler_config():
        body = request.get_json() or {}
        try:
            mins = int(body.get("interval_minutes", _MDL_DEFAULT_INTERVAL))
        except (ValueError, TypeError):
            mins = _MDL_DEFAULT_INTERVAL
        try:
            _mdl_write_interval(mins)
            # Update live scheduler interval
            with _mdl_sched_lock:
                _mdl_sched_state["interval_s"] = mins * 60
        except Exception as _e:
            return jsonify({"ok": False, "error": str(_e)}), 500
        return jsonify({"ok": True, "interval_minutes": mins})

    def _mdl_write_scheduler_setting(key, value):
        import openpyxl as _xl
        try:
            MDL_ROOT.mkdir(parents=True, exist_ok=True)
            if _MDL_SCHED_CFG.exists():
                _wb = _xl.load_workbook(str(_MDL_SCHED_CFG))
                _ws = _wb.active
                for _r in _ws.iter_rows(min_row=2):
                    if _r[0].value and str(_r[0].value).strip().lower() == str(key).lower():
                        _r[1].value = value; break
                else:
                    _ws.append([key, value])
                _wb.save(str(_MDL_SCHED_CFG))
            else:
                _wb = _xl.Workbook(); _ws = _wb.active; _ws.title = "Config"
                _ws.append(["key", "value", "notes"]); _ws.append([key, value, ""])
                _wb.save(str(_MDL_SCHED_CFG))
        except Exception:
            pass

    @app.route("/api/tools/melissa/scheduler-settings", methods=["GET"])
    def api_melissa_get_scheduler_settings():
        import openpyxl as _xl
        settings = []
        if _MDL_SCHED_CFG.exists():
            try:
                _wb = _xl.load_workbook(str(_MDL_SCHED_CFG), data_only=True)
                _ws = _wb.active
                _hdrs = [str(_ws.cell(1, c).value or "").strip().lower()
                         for c in range(1, _ws.max_column + 1)]
                _notes_col = _hdrs.index("notes") if "notes" in _hdrs else None
                for _r in _ws.iter_rows(min_row=2, values_only=True):
                    if not _r[0]:
                        continue
                    _k = str(_r[0]).strip()
                    _v = str(_r[1]).strip() if _r[1] is not None else ""
                    _n = str(_r[_notes_col]).strip() if (_notes_col is not None and _r[_notes_col]) else ""
                    settings.append({"key": _k, "value": _v, "notes": _n})
            except Exception:
                pass
        _DEFAULTS = [
            ("auto_refresh_interval", "1",  "Auto refresh interval in minutes (0 = off)"),
            ("max_poll_hours",        "48", "Mark stale runs after this many hours"),
            ("stale_threshold_hours", "48", "Startup recovery: ignore projects older than this"),
        ]
        _existing_keys = {s["key"].lower() for s in settings}
        for _dk, _dv, _dn in _DEFAULTS:
            if _dk.lower() not in _existing_keys:
                settings.append({"key": _dk, "value": _dv, "notes": _dn})
        return jsonify({"ok": True, "settings": settings})

    @app.route("/api/tools/melissa/scheduler-settings", methods=["POST"])
    def api_melissa_post_scheduler_settings():
        data = request.get_json() or {}
        updates = data.get("settings", {})
        if not isinstance(updates, dict):
            return jsonify({"ok": False, "error": "settings must be a key:value object"}), 400
        for _k, _v in updates.items():
            _mdl_write_scheduler_setting(str(_k).strip(), str(_v).strip())
            if str(_k).strip().lower() == "auto_refresh_interval":
                try:
                    with _mdl_sched_lock:
                        _mdl_sched_state["interval_s"] = int(_v) * 60
                except Exception:
                    pass
        return jsonify({"ok": True})

