    @app.route("/api/tools/melissa/stats/<int:pid>", methods=["GET"])
    def api_melissa_stats(pid):
        import openpyxl as _xl_st
        path = MDL_ROOT / "stats" / "stats.xlsx"
        if not path.exists():
            return jsonify({"ok": True, "stages": [], "total": len(_MDL_ALL_STAGES),
                            "done": 0, "running_stage": None})
        try:
            wb = _xl_st.load_workbook(str(path), read_only=True, data_only=True)
            ws = wb.active
            hdrs = [str(ws.cell(1, c).value or "").strip().lower()
                    for c in range(1, ws.max_column + 1)]
            stages = []
            for row in ws.iter_rows(min_row=2, values_only=True):
                d = {k: (str(v).strip() if v is not None else "") for k, v in zip(hdrs, row)}
                if str(d.get("pid", "")).strip() == str(pid):
                    stages.append(d)
            wb.close()
            done_count    = sum(1 for s in stages if s.get("status") == "done")
            running_stage = next((s.get("stage") for s in stages if s.get("status") == "running"), None)
            total_elapsed = sum(float(s.get("elapsed_s") or 0) for s in stages)
            return jsonify({
                "ok": True, "stages": stages,
                "total": len(_MDL_ALL_STAGES),
                "done": done_count,
                "running_stage": running_stage,
                "total_elapsed_s": round(total_elapsed, 1),
            })
        except Exception as _e:
            return jsonify({"ok": False, "error": str(_e)}), 500

    @app.route("/api/tools/melissa/images", methods=["GET"])
    def api_melissa_images():
        img_dir = MDL_DATA / "remote_images"
