    _RS_PROJ_WIDTHS  = [6, 22, 14, 20, 160]

    @app.route("/api/tools/gp-run/projects", methods=["GET"])
    def api_gp_run_projects():
        try:
            import openpyxl as _xl, zipfile as _zf
            app_name = request.args.get("app", "Payor")
            path = GP_DATA / "projects.xlsx"
            if not path.exists():
                return jsonify({"rows": [], "meta": {}})
            # Read projects
            try:
                wb = _xl.load_workbook(str(path))
            except _zf.BadZipFile:
                return jsonify({"rows": [], "meta": {}, "warning": f"projects.xlsx is not a valid xlsx file (may be old .xls format or corrupt): {path}"})
            if app_name in wb.sheetnames:
                ws = wb[app_name]
            elif app_name == "Payor":
                ws = (wb["Projects"] if "Projects" in wb.sheetnames else wb.active)
            else:
                return jsonify({"rows": [], "meta": {}})
            hdrs = [str(ws.cell(1, c).value or "").strip().lower() for c in range(1, ws.max_column + 1)]
            rows = []
            for row in ws.iter_rows(min_row=2, values_only=True):
                if any(v is not None for v in row):
                    d = {k: ("" if v is None else str(v)) for k, v in zip(hdrs, row)}
                    if d.get("project_id", "").strip():
                        rows.append(d)
            # Read Jenkins job URL from config.xlsx to construct build URLs
            job_base = _gp_job_url(app_name)
            for row in rows:
                jid = row.get("job_id", "").strip().lstrip("#")
                row["jenkins_url"] = f"{job_base}/{jid}" if job_base and jid and jid not in ("", "None") else ""
            # Merge eta_cache
            import json as _json_gp, time as _time_gp
            eta_path   = GP_ROOT / "eta_cache.json"
            eta_cache  = {}
            if eta_path.exists():
                try: eta_cache = _json_gp.loads(eta_path.read_text(encoding="utf-8"))
                except Exception: pass
            sonar_path  = GP_ROOT / "sonar_cache.json"
            sonar_cache = {}
            if sonar_path.exists():
                try: sonar_cache = _json_gp.loads(sonar_path.read_text(encoding="utf-8"))
                except Exception: pass
            _GP_ELIGIBLE = {"running", "scheduled", "created", "unstable"}
            for row in rows:
                pid    = str(row.get("project_id", ""))
                status = str(row.get("status", "") or "").lower()
                timing = eta_cache.get(pid, {})
                s_ms   = timing.get("start_ms")
                e_ms   = timing.get("est_ms")
                if status in _GP_ELIGIBLE and s_ms is not None:
                    if e_ms:
                        row["eta_seconds"] = max(0, int((int(s_ms) + int(e_ms)) / 1000 - _time_gp.time()))
                    else:
                        row["eta_seconds"] = -int(_time_gp.time() - int(s_ms) / 1000)
                else:
                    row["eta_seconds"] = None
                _sc = sonar_cache.get(pid)
                row["sonar_url"] = _sc.get("url", "") if isinstance(_sc, dict) else (_sc or "")
                row["sonar_qg"]  = _sc.get("qg",  "") if isinstance(_sc, dict) else ""
            # Read jira_base_url from secrets for ticket links
            jira_base = ""
            secrets_path = WORKFLOWS_ROOT / "secrets.xlsx"
            if secrets_path.exists():
                try: sw = _xl.load_workbook(str(secrets_path))
                except _zf.BadZipFile: sw = None
                for sht in (sw.sheetnames if sw else []):
                    for r in sw[sht].iter_rows(min_row=2, values_only=True):
                        if r[0] and str(r[0]).strip() == "jira_base_url" and r[1] is not None:
                            jira_base = str(r[1]).strip().rstrip("/")
                            break
                    if jira_base:
                        break
            return jsonify({"rows": rows, "meta": {"jira_base_url": jira_base}})
        except Exception as _e:
            import traceback as _tb
            return jsonify({"ok": False, "error": str(_e), "trace": _tb.format_exc()})

    @app.route("/api/tools/gp-run/projects/<pid>/status", methods=["GET"])
    def api_gp_run_project_status(pid):
        import sys as _sys, time as _time, json as _json
        _gp_scripts = str(GP_ROOT / "scripts")
        if _gp_scripts not in _sys.path:
            _sys.path.insert(0, _gp_scripts)
        import gpstatus_tool as _gp

        app_name = request.args.get("app", "Payor")

        # Load the project row using gpstatus_tool's own loader
        rows = _gp.load_projects(app_name)
        row  = next((r for r in rows if str(r.get("project_id", "")).strip() == str(pid).strip()), None)
        if row is None:
            return jsonify({"ok": False, "error": "project not found"}), 404

        # Construct jenkins_url from config
        settings    = _gp.load_settings(app_name)
        job_base    = settings.get("url", "").rstrip("/")
        job_id      = str(row.get("job_id", "") or "").strip().lstrip("#")
        jenkins_url = f"{job_base}/{job_id}" if job_base and job_id and job_id not in ("", "None") else ""

        # Skip refresh_single for terminal rows — status can't change, and concurrent
        # writes from background Sonar fetches would corrupt the xlsx file.
        row_status = str(row.get("status") or "").lower()
        if row_status in _gp.TERMINAL:
            updated = row
        else:
            try:
                updated = _gp.refresh_single(row, app_name)
            except Exception as _e:
                print(f"[gp-run] refresh_single failed for pid {pid}: {_e}", file=_sys.stderr)
                updated = row
        status  = str(updated.get("status") or row.get("status") or "")

        # ETA from the updated row (refresh_single populates start_ms/est_ms)
        eta_seconds = None
        s_ms = updated.get("start_ms")
        e_ms = updated.get("est_ms")
        if s_ms is not None:
            eta_seconds = (max(0, int((int(s_ms) + int(e_ms)) / 1000 - _time.time()))
                           if e_ms else -int(_time.time() - int(s_ms) / 1000))
        else:
            cache  = _gp._load_eta_cache()
            timing = cache.get(str(pid), {})
            s_ms2  = timing.get("start_ms")
            e_ms2  = timing.get("est_ms")
            if s_ms2:
                eta_seconds = (max(0, int((int(s_ms2) + int(e_ms2)) / 1000 - _time.time()))
                               if e_ms2 else -int(_time.time() - int(s_ms2) / 1000))

        # Fetch sonar URL from Jenkins for terminal projects (cached in sonar_cache.json)
        sonar_url        = ""
        sonar_qg         = ""
        sonar_debug      = {"jenkins_url": jenkins_url, "status": status, "source": "none"}
        sonar_cache_path = GP_ROOT / "sonar_cache.json"
        sonar_cache      = {}
        if sonar_cache_path.exists():
            try: sonar_cache = _json.loads(sonar_cache_path.read_text(encoding="utf-8"))
            except Exception: pass
        _sc = sonar_cache.get(str(pid))
        if _sc:
            if isinstance(_sc, dict):
                sonar_url = _sc.get("url", "")
                sonar_qg  = _sc.get("qg",  "")
            else:
                sonar_url = str(_sc)
            sonar_debug["source"] = "cache"
        elif status.lower() in _gp.TERMINAL:
            try:
                import re as _re, requests as _requests, urllib3 as _urllib3, openpyxl as _xl
                _urllib3.disable_warnings()
                settings2 = _gp.load_settings(app_name)
                # Same default component the Sonar Report Generator uses; override via a sonar_project_key column in gp_job_config.xlsx
                sonar_project_key = (settings2.get("sonar_project_key", "") or "com.healthedge.core:core-parent").strip()
                pr_url = str(row.get("pr_url", "") or "").strip()
                pr_m   = _re.search(r'/pull/(\d+)', pr_url)
                pr_num = pr_m.group(1) if pr_m else ""
                sonar_debug["sonar_project_key"] = sonar_project_key
                sonar_debug["pr_num"] = pr_num
                feature_branch = str(row.get("feature_branch", "") or "").strip()
                if sonar_project_key and (pr_num or feature_branch):
                    # Read Sonar credentials directly from secrets.xlsx Sonar sheet
                    _wb = _xl.load_workbook(str(_gp.SECRETS_PATH), read_only=True, data_only=True)
                    _sonar_creds = {}
                    if "Sonar" in _wb.sheetnames:
                        for _r in _wb["Sonar"].iter_rows(values_only=True):
                            if _r and str(_r[0] or "").strip().lower() == "key":      # header row: key | value | notes
                                continue
                            if _r and _r[0] and _r[1] is not None:
                                _sonar_creds[str(_r[0]).strip().lower()] = str(_r[1]).strip()
                    _wb.close()
                    sonar_base = _sonar_creds.get("base url", "").rstrip("/")
                    sonar_user = _sonar_creds.get("login", "")
                    sonar_pass = _sonar_creds.get("password", "")
                    sonar_debug["sonar_base"] = sonar_base
                    if sonar_base and sonar_user:
                        # Verify the PR analysis exists in Sonar
                        _s = _requests.Session()
                        _s.verify = False
                        from urllib.parse import quote
                        _resp = None
                        if pr_num:
                            # Direct lookup of the PR analysis: far faster than listing every PR of the (huge) project,
                            # which regularly exceeded the old 15s timeout and left the link missing.
                            try:
                                _mr = _s.get(f"{sonar_base}/api/measures/component", auth=(sonar_user, sonar_pass), timeout=20, verify=False,
                                             params={"component": sonar_project_key, "pullRequest": pr_num, "metricKeys": "alert_status"})
                            except _requests.exceptions.RequestException as _te:
                                # Sonar is slow / unreachable: the PR number is known, so still offer the link (not cached).
                                _mr = None
                                sonar_debug["unverified"] = str(_te)[:120]
                                sonar_url = f"{sonar_base}/dashboard?id={quote(sonar_project_key, safe='')}&pullRequest={pr_num}"
                            if _mr is not None:
                                sonar_debug["sonar_http"] = _mr.status_code
                            if _mr is not None and _mr.status_code == 200:
                                _ms = (_mr.json().get("component") or {}).get("measures") or []
                                sonar_qg  = next((m.get("value", "") for m in _ms if m.get("metric") == "alert_status"), "")
                                sonar_url = f"{sonar_base}/dashboard?id={quote(sonar_project_key, safe='')}&pullRequest={pr_num}"
                        if not sonar_url:
                            _resp = _s.get(
                                f"{sonar_base}/api/project_pull_requests/list",
                                auth=(sonar_user, sonar_pass), timeout=90, verify=False,
                                params={"project": sonar_project_key},
                            )
                            sonar_debug["sonar_http"] = _resp.status_code
                        if _resp is not None and _resp.status_code == 200:
                            _prs = _resp.json().get("pullRequests", [])
                            sonar_debug["pr_keys_sample"] = [p.get("key") for p in _prs][:5]
                            for _pr in _prs:
                                # Failed jobs often have no PR URL yet: fall back to the Sonar PR analysis of the same branch
                                if (pr_num and _pr.get("key") == pr_num) or                                    (not pr_num and feature_branch and _pr.get("branch") == feature_branch):
                                    from urllib.parse import quote
                                    sonar_url = f"{sonar_base}/dashboard?id={quote(sonar_project_key, safe='')}&pullRequest={_pr.get('key')}"
                                    sonar_qg  = (_pr.get("status") or {}).get("qualityGateStatus", "")
                                    break
                sonar_debug["source"] = "sonar_api"
                sonar_debug["found"]  = sonar_url
                if sonar_url and not sonar_debug.get("unverified"):
                    sonar_cache[str(pid)] = {"url": sonar_url, "qg": sonar_qg}
                    sonar_cache_path.write_text(_json.dumps(sonar_cache, indent=2), encoding="utf-8")
            except Exception as _e:
                sonar_debug["error"] = str(_e)
        else:
            sonar_debug["skip_reason"] = "not terminal"

        return jsonify({
            "ok":          True,
            "pid":         pid,
            "status":      status,
            "eta_seconds": eta_seconds,
            "jenkins_url": jenkins_url,
            "sonar_url":   sonar_url,
            "sonar_qg":    sonar_qg,
            "sonar_debug": sonar_debug,
        })

    @app.route("/api/tools/remote-setup/projects", methods=["GET"])
    def api_remote_setup_projects():
        import sys as _sys, time as _time
        _rs_scripts = str(RS_ROOT / "scripts")
        if _rs_scripts not in _sys.path:
            _sys.path.insert(0, _rs_scripts)
        import rvmsetupstatus as _rvm

        path = RS_DATA / "projects.xlsx"
        if not path.exists():
            return jsonify([])
        import openpyxl as _xl
        with _rs_projects_lock, _rs_projects_filelock():
            wb = _xl.load_workbook(str(path))
        ws   = wb.active
        hdrs = [str(ws.cell(1, c).value or "").strip().lower()
                for c in range(1, ws.max_column + 1)]
        rows = []
        for row in ws.iter_rows(min_row=2, values_only=True):
            if any(v is not None for v in row):
                rows.append({k: ("" if v is None else str(v)) for k, v in zip(hdrs, row)})

        # Merge eta_cache into each row
        cache = _rvm._load_eta_cache()
        active = _rvm._ACTIVE_STATUSES
        now_s = _time.time()
        for row in rows:
            pid    = str(row.get("pid", ""))
            status = str(row.get("status", "") or "").lower()
            timing = cache.get(pid, {})
            s_ms   = timing.get("start_ms")
            e_ms   = timing.get("est_ms")
            if status in active and s_ms is not None:
                if e_ms:
                    row["eta_seconds"] = max(0, int((int(s_ms) + int(e_ms)) / 1000 - now_s))
                else:
                    row["eta_seconds"] = -int(now_s - int(s_ms) / 1000)
            else:
                row["eta_seconds"] = None
        return jsonify(rows)

