    @app.route("/api/tools/remote-setup/projects", methods=["POST"])
    def api_remote_setup_create():
        from datetime import datetime as _dt
        import openpyxl as _xl, json as _json
        data    = request.get_json() or {}
        vm_name = str(data.get("vm_name", "")).strip()
        if not vm_name:
            return jsonify({"ok": False, "error": "vm_name is required"}), 400

        # Look up VM IP
        vm_ip = ""
        if VMS_FILE.exists():
            wb_v = _xl.load_workbook(str(VMS_FILE))
            ws_v = wb_v[wb_v.sheetnames[0]]
            hdrs_v = [str(ws_v.cell(1, c).value or "").strip().lower() for c in range(1, ws_v.max_column + 1)]
            for row in ws_v.iter_rows(min_row=2, values_only=True):
                d = {k: ("" if v is None else str(v).strip()) for k, v in zip(hdrs_v, row)}
                if d.get("name", "").lower() == vm_name.lower():
                    vm_ip = d.get("ip", ""); break

        # Build default params from katalon_params.xlsx
        params = {}
        params_file = RS_ROOT / "katalon_params.xlsx"
        if params_file.exists():
            wb_p = _xl.load_workbook(str(params_file))
            ws_p = wb_p.active
            hdrs_p = [str(ws_p.cell(1, c).value or "").strip().lower() for c in range(1, ws_p.max_column + 1)]
            for row in ws_p.iter_rows(min_row=2, values_only=True):
                if any(v is not None for v in row):
                    d = {k: ("" if v is None else str(v)) for k, v in zip(hdrs_p, row)}
                    params[d.get("key", "")] = d.get("default", "")
        if vm_ip:
            params["VM_IP"] = vm_ip
        # Apply caller-supplied overrides (e.g. from Clone Workflow) on top of defaults
        _overrides = data.get("param_overrides", {})
        if isinstance(_overrides, dict):
            params.update({str(k): str(v) for k, v in _overrides.items() if k})

        path = RS_DATA / "projects.xlsx"
        now  = _dt.now().strftime("%Y-%m-%d %H:%M")

        if not path.exists():
            wb = _xl.Workbook()
            ws = wb.active
            ws.title = "Projects"
            init_hdrs = ["pid", "timestamp", "vm_name", "vm_ip", "status", "jenkins_url", "queue_url", "config_file", "params_json"]
            ws.append(init_hdrs)
            for i, w in enumerate([6, 20, 22, 16, 14, 60, 60, 30, 160], 1):
                ws.column_dimensions[_xl.utils.get_column_letter(i)].width = w
            next_pid = 1
            hdrs = init_hdrs
        else:
            wb   = _xl.load_workbook(str(path))
            ws   = wb.active
            hdrs = [str(ws.cell(1, c).value or "").strip().lower() for c in range(1, ws.max_column + 1)]
            pids = [int(r[0].value) for r in ws.iter_rows(min_row=2)
                    if r[0].value is not None and str(r[0].value).isdigit()]
            next_pid = (max(pids) + 1) if pids else 1
            # Add params_json column if not present
            if "params_json" not in hdrs:
                nc = ws.max_column + 1
                ws.cell(1, nc).value = "params_json"
                ws.column_dimensions[_xl.utils.get_column_letter(nc)].width = 160
                hdrs.append("params_json")

        cmap     = {h: i for i, h in enumerate(hdrs, 1)}
        num_cols = max(cmap.values())
        new_row  = [None] * num_cols
        for field, val in {
            "pid": next_pid, "timestamp": now, "vm_name": vm_name,
            "vm_ip": vm_ip, "status": "pending",
            "jenkins_url": "", "queue_url": "", "config_file": "",
            "params_json": _json.dumps(params),
        }.items():
            if field in cmap:
                new_row[cmap[field] - 1] = val
        ws.append(new_row)
        wb.save(str(path))
        return jsonify({"ok": True, "pid": next_pid}), 201

    @app.route("/api/tools/remote-setup/projects/<pid>", methods=["PATCH"])
    def api_remote_setup_patch(pid):
        import openpyxl as _xl, json as _json
        path = RS_DATA / "projects.xlsx"
        if not path.exists():
            return jsonify({"ok": False}), 404
        wb   = _xl.load_workbook(str(path))
        ws   = wb.active
        hdrs = [str(ws.cell(1, c).value or "").strip().lower() for c in range(1, ws.max_column + 1)]
        cmap = {h: i for i, h in enumerate(hdrs, 1)}
        pid_col = cmap.get("pid", 1)
        data = request.get_json() or {}
        for row in ws.iter_rows(min_row=2):
            if str(row[pid_col - 1].value or "").strip() == str(pid).strip():
                if "params" in data and "params_json" in cmap:
                    row[cmap["params_json"] - 1].value = _json.dumps(data["params"])
                if "status" in data and "status" in cmap:
                    row[cmap["status"] - 1].value = data["status"]
                break
        wb.save(str(path))
        return jsonify({"ok": True})

    @app.route("/api/tools/remote-setup/projects/<pid>/server-logs", methods=["GET"])
    def api_remote_setup_server_logs(pid):
        import openpyxl as _xl
        path = RS_DATA / "projects.xlsx"
        if not path.exists():
            return jsonify({"error": "project not found"}), 404
        wb   = _xl.load_workbook(str(path))
        ws   = wb.active
        hdrs = [str(ws.cell(1, c).value or "").strip().lower() for c in range(1, ws.max_column + 1)]
        cmap = {h: i for i, h in enumerate(hdrs, 1)}
        config_file = None
        for row in ws.iter_rows(min_row=2, values_only=True):
            if str(row[cmap.get("pid", 1) - 1] or "").strip() == str(pid).strip():
                config_file = str(row[cmap["config_file"] - 1] or "").strip() if "config_file" in cmap else ""
                break
        if not config_file:
            return jsonify({"ok": False, "error": "No config file linked to this project"}), 404
        file_path = RS_DATA / "configured_servers" / config_file
        if not file_path.exists():
            return jsonify({"ok": False, "error": f"{config_file} not found"}), 404
        wb2  = _xl.load_workbook(str(file_path))
        if "Setups" not in wb2.sheetnames:
            return jsonify({"ok": True, "logs": [], "columns": []})
        ws2  = wb2["Setups"]
        raw_hdrs = [ws2.cell(1, c).value for c in range(1, ws2.max_column + 1)]
        hdrs2    = [str(h or "").strip() for h in raw_hdrs]
        STD      = {"pid", "timestamp", "vm_name", "vm_ip", "status", "queue_url"}
        param_cols = [h for h in hdrs2 if h and h.lower() not in STD]
        logs = []
        for row in ws2.iter_rows(min_row=2, values_only=True):
            if not any(v is not None for v in row):
                continue
            d = {h: ("" if v is None else str(v)) for h, v in zip(hdrs2, row)}
            logs.append(d)
        logs.reverse()  # newest first
        return jsonify({"ok": True, "logs": logs, "param_cols": param_cols})

    @app.route("/api/tools/remote-setup/projects/<pid>/trigger", methods=["POST"])
    def api_remote_setup_trigger(pid):
        import openpyxl as _xl, subprocess as _sp, json as _json
        path = RS_DATA / "projects.xlsx"
        if not path.exists():
            return jsonify({"ok": False, "error": "project not found"}), 404
        with _rs_projects_lock, _rs_projects_filelock():
            wb   = _xl.load_workbook(str(path))
            ws   = wb.active
            hdrs = [str(ws.cell(1, c).value or "").strip().lower() for c in range(1, ws.max_column + 1)]
            cmap = {h: i for i, h in enumerate(hdrs, 1)}
            pid_col = cmap.get("pid", 1)
            vm_name     = None
            params_json = {}
            for row in ws.iter_rows(min_row=2):
                if str(row[pid_col - 1].value or "").strip() == str(pid).strip():
                    vm_name = str(row[cmap.get("vm_name", 3) - 1].value or "").strip()
                    if "params_json" in cmap:
                        raw = row[cmap["params_json"] - 1].value
                        if raw:
                            try: params_json = _json.loads(str(raw))
                            except Exception: pass
                    if "status" in cmap:
                        row[cmap["status"] - 1].value = "triggered"
                    break
            if not vm_name:
                return jsonify({"ok": False, "error": "project not found"}), 404
            wb.save(str(path))
        import sys as _sys
        flags = 0x08000000  # CREATE_NO_WINDOW — applied directly to python.exe so no console pops up
        if hasattr(_sp, "DETACHED_PROCESS"):
            flags |= _sp.DETACHED_PROCESS | _sp.CREATE_NEW_PROCESS_GROUP
        script = str(RS_ROOT / "scripts" / "remote_setup.py")
        cmd = [_sys.executable, script, "-vm", vm_name, "-defaults", "-idp-pid", str(pid)]
        for k, v in params_json.items():
            cmd += ["-param", str(k), str(v)]
        try:
            _log_path = RS_ROOT / f"rs_trigger_{pid}.log"
            with open(str(_log_path), "w") as _log_fh:
                proc = _sp.Popen(
                    cmd,
                    stdout=_log_fh, stderr=_log_fh,
                    creationflags=flags,
                )
            _rs_ensure_poller()
            return jsonify({"ok": True, "process_pid": proc.pid})
        except Exception as e:
            try:
                with _rs_projects_lock, _rs_projects_filelock():
                    wb2 = _xl.load_workbook(str(path))
                    ws2 = wb2.active
                    for row in ws2.iter_rows(min_row=2):
                        if str(row[0].value or "").strip() == str(pid).strip():
                            if "status" in cmap:
                                row[cmap["status"] - 1].value = "pending"
                            break
                    wb2.save(str(path))
            except Exception:
                pass
            return jsonify({"ok": False, "error": str(e)}), 500

    @app.route("/api/tools/remote-setup/projects/<pid>/status", methods=["GET"])
    def api_remote_setup_project_status(pid):
        import sys as _sys, time as _time
        # Reuse all Jenkins + ETA logic from rvmsetupstatus
        _rs_scripts = str(RS_ROOT / "scripts")
        if _rs_scripts not in _sys.path:
            _sys.path.insert(0, _rs_scripts)
        import rvmsetupstatus as _rvm

        project = _rvm._find_project(pid)
        if not project:
            return jsonify({"ok": False, "error": "project not found"}), 404

        status      = str(project.get("status",      "") or "")
        jenkins_url = str(project.get("jenkins_url", "") or "")
        queue_url   = str(project.get("queue_url",   "") or "")
        eta_seconds = None

        if status.lower() in _rvm._ACTIVE_STATUSES:
            secrets    = _rvm._load_secrets()
            build_info = _rvm._fetch_build_info(jenkins_url, queue_url, secrets)

            if build_info:
                building      = build_info.get("building", False)
                result        = build_info.get("result", "")
                start_ms      = build_info.get("timestamp")
                est_ms        = build_info.get("estimatedDuration")
                resolved_url  = build_info.get("_build_url", "")
                resolved_from = build_info.get("_resolved_from", "")

                updates = {}
                if resolved_from == "queue" and resolved_url:
                    updates["jenkins_url"] = resolved_url
                    jenkins_url = resolved_url

                if building:
                    updates["status"] = "Running"
                    status = "Running"
                    if start_ms is not None:
                        _rvm._save_eta_cache({str(pid): {"start_ms": start_ms, "est_ms": est_ms or 0}})
                        if est_ms:
                            eta_seconds = max(0, int((int(start_ms) + int(est_ms)) / 1000 - _time.time()))
                        else:
                            # No Jenkins estimation — return elapsed as negative so UI shows "+Xm Ys"
                            elapsed = int(_time.time() - int(start_ms) / 1000)
                            eta_seconds = -elapsed
                else:
                    new_status = {
                        "SUCCESS":  "Passed",
                        "FAILURE":  "Failed",
                        "ABORTED":  "Cancelled",
                        "UNSTABLE": "Unstable",
                    }.get(result, result or status)
                    if new_status != status:
                        updates["status"] = new_status
                        status = new_status

                if updates:
                    with _rs_projects_lock, _rs_projects_filelock():
                        _rvm._update_project_fields(pid, **updates)

            else:
                # Jenkins unreachable — serve ETA from cache if available
                cache  = _rvm._load_eta_cache()
                timing = cache.get(str(pid), {})
                s_ms   = timing.get("start_ms")
                e_ms   = timing.get("est_ms")
                if s_ms:
                    if e_ms:
                        eta_seconds = max(0, int((int(s_ms) + int(e_ms)) / 1000 - _time.time()))
                    else:
                        elapsed = int(_time.time() - int(s_ms) / 1000)
                        eta_seconds = -elapsed

        return jsonify({
            "ok":          True,
            "pid":         pid,
            "status":      status,
            "jenkins_url": jenkins_url,
            "queue_url":   queue_url,
            "eta_seconds": eta_seconds,
        })

    @app.route("/api/tools/remote-setup/poll-interval", methods=["POST"])
    def api_rs_poll_interval():
        data       = request.get_json() or {}
        refresh_ms = int(data.get("refresh_ms") or 0)
        if refresh_ms <= 0:
            return jsonify({"ok": True})  # Off — leave saved interval unchanged
        poll_s = max(30, refresh_ms // 1000)
        with _rs_poller_state_lock:
            _rs_poller_state["poll_interval_s"] = poll_s
        _rs_write_poll_interval(poll_s)
        _rs_ensure_poller()
        return jsonify({"ok": True, "poll_interval_s": poll_s})

