    # GP runs are launched detached with output in a log file + exit-code file, so restarting the
    # Workbench does not kill them; only the abort endpoint does.
    _GP_RUNS_DIR = GP_ROOT / "run_logs"
    # Tiny launcher: runs the real command and records its exit code for the Workbench to pick up later.
    _GP_LAUNCHER = ("import subprocess,sys;"
                    "rc=subprocess.call(sys.argv[2:]);"
                    "open(sys.argv[1],'w').write(str(rc))")

    def _gp_run_paths(run_id):
        return (_GP_RUNS_DIR / f"{run_id}.json", _GP_RUNS_DIR / f"{run_id}.log", _GP_RUNS_DIR / f"{run_id}.code")

    def _gp_run_load(run_id):
        import json as _j
        try:
            return _j.loads(_gp_run_paths(run_id)[0].read_text(encoding="utf-8"))
        except Exception:
            return None

    def _gp_run_save(meta):
        import json as _j
        with _gp_run_lock:
            _gp_run_paths(meta["run_id"])[0].write_text(_j.dumps(meta), encoding="utf-8")

    def _gp_pid_alive(pid):
        import subprocess as _sp
        for _ in range(2):
            try:
                r = _sp.run(["tasklist", "/FI", f"PID eq {pid}", "/NH", "/FO", "CSV"], capture_output=True, text=True,
                            timeout=15, creationflags=0x08000000)
                if r.returncode == 0:
                    return f'"{pid}"' in r.stdout
            except Exception:
                pass
        return True   # could not tell: assume still running rather than reporting a false failure

    def _gp_run_refresh(run_id):
        """Resolve a finished run's status from its exit-code file (works across Workbench restarts)."""
        meta = _gp_run_load(run_id)
        if not meta:
            return meta
        _, _, codef = _gp_run_paths(run_id)
        # a run wrongly marked "failed" (exit code unknown) is corrected as soon as its exit-code file exists
        healing = meta.get("status") == "failed" and meta.get("returncode") is None and codef.exists()
        if meta.get("status") != "running" and not healing:
            return meta
        if not codef.exists() and not _gp_pid_alive(meta.get("pid")):
            import time as _tm
            _tm.sleep(3)   # the exit-code file is written just before the launcher exits; re-check, and re-check the pid, before giving up
        if codef.exists():
            try:
                rc = int(codef.read_text(encoding="utf-8-sig", errors="replace").strip() or "0")
            except ValueError:
                rc = 1
            meta["returncode"] = rc
            meta["status"] = "done" if rc == 0 else "failed"
        elif not _gp_pid_alive(meta.get("pid")) and not _gp_pid_alive(meta.get("pid")):
            if codef.exists():       # written while we were checking the pid
                return _gp_run_refresh(run_id)
            meta["status"] = "failed"
            meta["returncode"] = None
        else:
            return meta
        _gp_run_save(meta)
        return meta

    @app.route("/api/tools/gp-run/trigger", methods=["POST"])
    def api_gp_run_trigger():
        import subprocess as _sp, uuid as _uuid, os as _os2, sys as _sys, time as _tm
        data = request.get_json() or {}
        _gp_args = _TOOL_CMD["gp-run"](data)  # ["gprun", "--app", ...]
        # Invoke the Python script directly to avoid cmd.exe /c quirks with .cmd
        # batch files where trailing tokens can be re-executed as standalone commands.
        run_id = _uuid.uuid4().hex[:10]
        _GP_RUNS_DIR.mkdir(parents=True, exist_ok=True)
        _, logf, codef = _gp_run_paths(run_id)
        cmd = [_sys.executable, "-c", _GP_LAUNCHER, str(codef),
               _sys.executable, str(GP_ROOT / "scripts" / "gprun_tool.py")] + _gp_args[1:]
        _env = {**_os2.environ, "PYTHONUNBUFFERED": "1"}
        try:
            with open(logf, "wb") as lh:
                proc = _sp.Popen(
                    cmd, stdout=lh, stderr=_sp.STDOUT, stdin=_sp.DEVNULL, env=_env,
                    creationflags=0x08000000 | 0x00000200,   # CREATE_NO_WINDOW | CREATE_NEW_PROCESS_GROUP
                )
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)}), 500
        _gp_run_save({"run_id": run_id, "pid": proc.pid, "app": data.get("app", "Payor"),
                      "status": "running", "returncode": None, "created": _tm.time()})
        return jsonify({"ok": True, "run_id": run_id, "pid": proc.pid})

    @app.route("/api/tools/gp-run/output/<run_id>", methods=["GET"])
    def api_gp_run_output(run_id):
        meta = _gp_run_refresh(run_id)
        if not meta:
            return jsonify({"ok": False, "error": "Unknown run_id"}), 404
        try:
            output = _gp_run_paths(run_id)[1].read_bytes()[-400000:].decode("utf-8", errors="replace")
        except Exception:
            output = ""
        return jsonify({"ok": True, "output": output, "status": meta["status"], "returncode": meta.get("returncode")})

    @app.route("/api/tools/gp-run/abort/<run_id>", methods=["POST"])
    def api_gp_run_abort(run_id):
        import subprocess as _sp2
        meta = _gp_run_load(run_id)
        if not meta:
            return jsonify({"ok": False, "error": "Unknown run_id"}), 404
        if meta.get("status") == "running":
            meta["status"] = "aborted"
            _gp_run_save(meta)
            try:
                _sp2.run(["taskkill", "/F", "/T", "/PID", str(meta.get("pid"))], capture_output=True, creationflags=0x08000000)
            except Exception:
                pass
        return jsonify({"ok": True})

    @app.route("/api/tools/gp-run/active", methods=["GET"])
    def api_gp_run_active():
        """Most recent still-running (or just-finished) GP run for an app, so the UI can re-attach after a restart."""
        app_name = request.args.get("app", "Payor")
        best = None
        if _GP_RUNS_DIR.exists():
            for jf in _GP_RUNS_DIR.glob("*.json"):
                m = _gp_run_load(jf.stem)
                if m and m.get("app") == app_name and m.get("status") == "running":
                    if best is None or m.get("created", 0) > best.get("created", 0):
                        best = m
        if best:
            best = _gp_run_refresh(best["run_id"])
        return jsonify({"ok": True, "run_id": best["run_id"] if best and best["status"] == "running" else None})

