    @app.route("/api/tools/gp-run/apps/<app_name>", methods=["DELETE"])
    def api_gp_run_apps_delete(app_name):
        import openpyxl as _xl, shutil as _sh
        if not app_name:
            return jsonify({"ok": False, "error": "App name required"})
        try:
            # projects.xlsx — remove sheet
            proj_path = GP_DATA / "projects.xlsx"
            if proj_path.exists():
                wb = _xl.load_workbook(str(proj_path))
                if app_name in wb.sheetnames:
                    del wb[app_name]
                    wb.save(str(proj_path))

            # projects/{AppName}/ — delete folder
            proj_dir = GP_DATA / "projects" / app_name
            if proj_dir.exists():
                _sh.rmtree(str(proj_dir))

            # config.xlsx — remove row
            cfg_path = GP_ROOT / "gp_job_config.xlsx"
            if cfg_path.exists():
                wbc = _xl.load_workbook(str(cfg_path))
                wss = wbc["Settings"] if "Settings" in wbc.sheetnames else wbc.active
                rows_to_del = [r for r in range(2, wss.max_row + 1)
                               if str(wss.cell(r, 1).value or "").strip() == app_name]
                for r in sorted(rows_to_del, reverse=True):
                    wss.delete_rows(r)
                wbc.save(str(cfg_path))

            # gp_params file — delete if exists
            gp_params_path = _gp_params_path(app_name)
            if gp_params_path.exists():
                gp_params_path.unlink()

            apps_list = []
            if proj_path.exists():
                wb2 = _xl.load_workbook(str(proj_path), read_only=True)
                apps_list = list(wb2.sheetnames)
                wb2.close()
            return jsonify({"ok": True, "apps": apps_list})
        except Exception as _e:
            return jsonify({"ok": False, "error": str(_e)})

