    @app.route("/api/tools/gp-run/gp-params/<app_name>", methods=["POST"])
    def api_gp_run_gp_params_post(app_name):
        import openpyxl as _xl, os as _os
        data      = request.get_json() or {}
        params_in = data.get("parameters", [])
        path = _gp_params_path(app_name)
        if not path.exists():
            from openpyxl.styles import Font as _Fnt2, PatternFill as _Fill3, Alignment as _Aln2
            _os.makedirs(str(path.parent), exist_ok=True)
            wb2 = _xl.Workbook(); wb2.remove(wb2.active)
            ws2 = wb2.create_sheet("BuildParameters")
            _hf2 = _Fill3("solid", fgColor="4472C4"); _ff2 = _Fnt2(color="FFFFFF", bold=True)
            for col2, t2 in enumerate(("parameter", "value", "type", "default", "description"), start=1):
                cell2 = ws2.cell(1, col2, t2); cell2.font = _ff2; cell2.fill = _hf2
            wb2.save(str(path))
        try:
            wb = _xl.load_workbook(str(path))
            if "BuildParameters" not in wb.sheetnames:
                return jsonify({"ok": False, "error": "BuildParameters sheet not found"})
            ws = wb["BuildParameters"]
            hdrs = [str(ws.cell(1, c).value or "").strip().lower()
                    for c in range(1, ws.max_column + 1)]
            val_col = (hdrs.index("value") + 1) if "value" in hdrs else None
            if val_col is None:
                return jsonify({"ok": False, "error": "No 'value' column in BuildParameters"})
            updates = {p.get("parameter", "").strip(): p.get("value", "") for p in params_in if p.get("parameter")}
            for row in ws.iter_rows(min_row=2):
                name = str(row[0].value or "").strip()
                if name in updates:
                    row[val_col - 1].value = updates[name]
            wb.save(str(path))
            return jsonify({"ok": True})
        except Exception as _e:
            return jsonify({"ok": False, "error": str(_e)})

    @app.route("/api/tools/gp-run/fetch-params/<app_name>", methods=["POST"])
    def api_gp_run_fetch_params(app_name):
        import subprocess as _sp, sys as _sys
        job_url = _gp_job_url(app_name)
        if not job_url:
            return jsonify({"ok": False, "error": f"No URL configured for '{app_name}'. Add it via Configure first."})
        script_dir          = GP_ROOT / "scripts"
        fetch_params_script = script_dir / "fetch_build_params.py"
        fetch_groups_script = script_dir / "fetch_test_groups.py"
        python = _sys.executable
        _cflags = 0x08000000 if _sys.platform == "win32" else 0  # CREATE_NO_WINDOW
        lines = []
        for label, script in [("build params", fetch_params_script), ("test groups", fetch_groups_script)]:
            try:
                result = _sp.run(
                    [python, str(script), "--app", app_name],
                    capture_output=True, text=True, timeout=120,
                    cwd=str(script_dir),
                    creationflags=_cflags,
                )
                lines.append(f"--- Fetching {label} ---")
                if result.stdout:
                    lines.extend(result.stdout.splitlines())
                if result.stderr:
                    lines.extend(result.stderr.splitlines())
                if result.returncode != 0:
                    lines.append(f"ERROR: {label} fetch failed (exit code {result.returncode})")
                    return jsonify({"ok": False, "output": "\n".join(lines)})
            except _sp.TimeoutExpired:
                lines.append(f"ERROR: {label} fetch timed out after 120s")
                return jsonify({"ok": False, "output": "\n".join(lines)})
            except Exception as _e:
                lines.append(f"ERROR: {_e}")
                return jsonify({"ok": False, "output": "\n".join(lines)})
        return jsonify({"ok": True, "output": "\n".join(lines)})

