    # -------------------------------------------------------------------------
    # Jenkins Commit Job endpoints (mirror of jreg, using JCJ_ROOT)
    # -------------------------------------------------------------------------

    def _jcj_load_secrets():
        import openpyxl as _xl
        if not SECRETS_FILE.exists():
            return {}
        try:
            wb = _xl.load_workbook(str(SECRETS_FILE))
            if "Jenkins" not in wb.sheetnames:
                return {}
            out = {}
            for row in wb["Jenkins"].iter_rows(min_row=2, values_only=True):
                if row[0] and row[1] is not None:
                    out[str(row[0]).strip()] = str(row[1]).strip()
            return out
        except Exception:
            return {}

    def _run_jcj_bg(data):
        import openpyxl as _xl, re as _re, requests as _req
        import datetime as _dt
        from openpyxl.styles import Font as _JFn, PatternFill as _JPf, Alignment as _JAl

        app_name      = data.get("app", "Payor") or "Payor"
        url_params    = data.get("url_params") or {}
        selected_jobs = data.get("selected_jobs") or []
        runs          = max(1, int(data.get("runs") or 1))

        def _append(line):
            with _jcj_op_lock:
                _jcj_op["output"] += line

        try:
            _append(f"Jenkins Commit Job — {app_name}\n{'='*40}\n\n")

            # --- credentials ---
            secrets  = _jcj_load_secrets()
            username = secrets.get("jenkins_username", "")
            token    = secrets.get("jenkins_api_token", "") or secrets.get("jenkins_password", "")
            auth     = (username, token) if username and token else None
            if not auth:
                _append("ERROR: Jenkins credentials not found in secrets.xlsx (Jenkins sheet).\n")
                with _jcj_op_lock:
                    _jcj_op["status"] = "failed"
                return

            # --- read configured jobs ---
            cfg_path = JCJ_ROOT / "commit_job_config.xlsx"
            all_jobs = []
            if cfg_path.exists():
                wb_c = _xl.load_workbook(str(cfg_path))
                sheet = next((s for s in wb_c.sheetnames if s.lower() == app_name.lower()), None)
                if sheet:
                    _cfg_ws   = wb_c[sheet]
                    _cfg_hdrs = [str(_cfg_ws.cell(1, c).value or "").strip().lower()
                                 for c in range(1, _cfg_ws.max_column + 1)]
                    for row in _cfg_ws.iter_rows(min_row=2, values_only=True):
                        if row[0]:
                            _rd = {k: str(v or "").strip() for k, v in zip(_cfg_hdrs, row)}
                            if _rd.get("enabled", "1") in ("0", "false", "no"):
                                continue
                            all_jobs.append({
                                "job_name":        _rd.get("job_name", str(row[0]).strip()),
                                "job_url":         _rd.get("job_url", str(row[1] if len(row) > 1 else "") or ""),
                                "artifactory_url": _rd.get("artifactory_url", ""),
                            })

            if selected_jobs:
                job_map    = {j["job_name"]: j for j in all_jobs}
                jobs_to_run = [job_map[n] for n in selected_jobs if n in job_map]
            else:
                jobs_to_run = all_jobs

            if not jobs_to_run:
                _append("ERROR: No jobs configured for this application.\n")
                with _jcj_op_lock:
                    _jcj_op["status"] = "failed"
                return

            _append(f"Jobs to run ({len(jobs_to_run)}): {', '.join(j['job_name'] for j in jobs_to_run)}\n")
            _append(f"Runs per job: {runs}\n\n")

            # --- allocate project ID ---
            JCJ_ROOT.mkdir(parents=True, exist_ok=True)
            proj_path  = JCJ_DATA / "projects.xlsx"
            wb_p       = _xl.load_workbook(str(proj_path)) if proj_path.exists() else _xl.Workbook()
            sheet_p    = app_name
            if sheet_p not in wb_p.sheetnames:
                ws_p = wb_p.create_sheet(title=sheet_p)
                _hf = _JPf("solid", fgColor="1F3864"); _ff = _JFn(bold=True, color="FFFFFF", name="Calibri")
                _al = _JAl(horizontal="left", vertical="center")
                for ci, col in enumerate(["project_id", "payor_release_version", "runs", "status", "triggered_at"], 1):
                    c = ws_p.cell(1, ci, col); c.font = _ff; c.fill = _hf; c.alignment = _al
                if "Sheet" in wb_p.sheetnames and sheet_p != "Sheet":
                    wb_p.remove(wb_p["Sheet"])
            else:
                ws_p = wb_p[sheet_p]
            existing_ids = [ws_p.cell(r, 1).value for r in range(2, ws_p.max_row + 1) if ws_p.cell(r, 1).value]
            pid = str(max((int(str(x)) for x in existing_ids if str(x).isdigit()), default=0) + 1)
            version_label = ", ".join(v for v in url_params.values() if v) if url_params else ""
            triggered_at  = _dt.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            ws_p.append([pid, version_label, str(runs), f"{len(jobs_to_run)} jobs: triggering…", triggered_at])
            wb_p.save(str(proj_path))

            # Store JCJ project_id in Clone Workflow stage tool_pid so _check("jcj") can track it
            _jcj_wf_pid = str(data.get("_wf_pid") or "").strip()
            _jcj_wf_sk  = str(data.get("_wf_stage_key") or "jcj").strip()
            if _jcj_wf_pid:
                try:
                    for _s_wf in load_stages(_jcj_wf_pid):
                        if str(_s_wf.get("stage_key", "")).strip() == _jcj_wf_sk:
                            update_stage(_jcj_wf_pid, _s_wf["stage_id"], {"tool_pid": str(pid)})
                            break
                except Exception:
                    pass

            # --- trigger each job ---
            overall_ok  = True
            job_results = []

            # one session per run — keeps cookies so crumb stays valid
            sess = _req.Session()
            sess.auth = auth

            # obtain crumb once for all jobs
            crumb_hdr = {}
            try:
                base_url = None
                for job in jobs_to_run:
                    raw = _re.sub(r'\{([^}]+)\}', lambda m: url_params.get(m.group(1), m.group(0)), job["job_url"])
                    if "/job/" in raw:
                        base_url = raw.split("/job/")[0]
                        break
                if base_url:
                    cr = sess.get(f"{base_url}/crumbIssuer/api/json", timeout=10)
                    if cr.status_code == 200:
                        cj = cr.json()
                        crumb_hdr = {cj["crumbRequestField"]: cj["crumb"]}
                        _append(f"CSRF crumb obtained.\n\n")
                    else:
                        _append(f"CSRF crumb not available (HTTP {cr.status_code}) — proceeding without it.\n\n")
            except Exception as _ce:
                _append(f"CSRF crumb error: {_ce} — proceeding without it.\n\n")

            for job in jobs_to_run:
                if _jcj_abort.is_set():
                    _append("\n--- Aborted ---\n")
                    with _jcj_op_lock:
                        _jcj_op["status"] = "aborted"
                    _jcj_update_project_status(app_name, pid, "Aborted")
                    return

                jname = job["job_name"]
                resolved_url = _re.sub(r'\{([^}]+)\}', lambda m: url_params.get(m.group(1), m.group(0)), job["job_url"])

                # append /build if URL doesn't already end with a build trigger path
                turl = resolved_url.rstrip("/")
                if not (turl.endswith("/build") or turl.endswith("/buildWithParameters")):
                    turl += "/build"

                _append(f"▶ {jname}\n   {turl}\n")

                job_status = "trigger failed"; queue_url = ""; build_url = ""
                for run_i in range(runs):
                    if runs > 1:
                        _append(f"   Run {run_i + 1}/{runs}: ")
                    try:
                        resp = sess.post(turl, headers=crumb_hdr, timeout=30)
                        if resp.status_code in (200, 201, 302):
                            queue_url  = resp.headers.get("Location", "")
                            job_status = "triggered"
                            _append(f"{'   ' if runs == 1 else ''}✓ queued  {queue_url or 'N/A'}\n")
                        else:
                            _append(f"{'   ' if runs == 1 else ''}✗ HTTP {resp.status_code}\n")
                            overall_ok = False
                    except Exception as ex:
                        _append(f"{'   ' if runs == 1 else ''}✗ {ex}\n")
                        overall_ok = False

                # store original URL (without /build) for display
                job_results.append({"job_name": jname, "job_url": resolved_url,
                                    "completed": job_status, "runs": str(runs),
                                    "triggered_at": triggered_at, "build_url": build_url,
                                    "queue_url": queue_url, "artifactory_url": job.get("artifactory_url", "")})
                _append("\n")

            # --- resolve queue items → build URLs ---
            import time as _time
            _append("Resolving queue items to build URLs…\n")
            for attempt in range(8):
                if _jcj_abort.is_set():
                    break
                all_resolved = True
                for jr in job_results:
                    if jr.get("queue_url") and not jr.get("build_url"):
                        all_resolved = False
                        try:
                            qr = sess.get(jr["queue_url"].rstrip("/") + "/api/json", timeout=10)
                            if qr.status_code == 200:
                                exe = qr.json().get("executable")
                                if exe and exe.get("url"):
                                    jr["build_url"] = exe["url"].rstrip("/") + "/"
                                    jr["completed"]  = "Running"
                                    _append(f"  {jr['job_name']}: {jr['build_url']}\n")
                        except Exception:
                            pass
                if all_resolved:
                    break
                _time.sleep(3)

            # --- write job detail file helper ---
            _jcj_job_cols = ["job_name", "job_url", "completed", "runs", "triggered_at", "build_url",
                             "queue_url", "build_version", "artifact_url", "artifactory_url", "eta_seconds"]

            def _save_jcj_detail():
                try:
                    _pdir = JCJ_DATA / "projects" / app_name
                    _pdir.mkdir(parents=True, exist_ok=True)
                    _wb_j = _xl.Workbook()
                    _ws_j = _wb_j.active; _ws_j.title = "jobs"
                    _hf2 = _JPf("solid", fgColor="1F3864")
                    _ff2 = _JFn(bold=True, color="FFFFFF", name="Calibri")
                    for _ci, _col in enumerate(_jcj_job_cols, 1):
                        _c = _ws_j.cell(1, _ci, _col); _c.font = _ff2; _c.fill = _hf2
                    for _jr in job_results:
                        _ws_j.append([_jr.get(k, "") for k in _jcj_job_cols])
                    _wb_j.save(str(_pdir / f"{pid}_run.xlsx"))
                except Exception as _ex_j:
                    _append(f"Warning: could not save job detail file: {_ex_j}\n")

            # write initial state (build URLs known) so UI can display progress
            _save_jcj_detail()
            _jcj_update_project_status(app_name, pid, _jcj_compute_project_status(job_results))

            # --- poll builds to completion and extract build_version ---
            _append("\nPolling builds for completion…\n")
            _ver_pat_jcj = _re.compile(r'\d+\.\d+[\d.]*-\d+-[0-9a-f]+')
            for _poll_i in range(120):   # max 120 × 10 s ≈ 20 min
                if _jcj_abort.is_set():
                    _append("\n--- Aborted ---\n")
                    with _jcj_op_lock:
                        _jcj_op["status"] = "aborted"
                    _jcj_update_project_status(app_name, pid, "Aborted")
                    return
                _any_active   = False
                _poll_updated = False
                _TERM_STATES  = ("success", "failed", "failure", "aborted", "done", "unstable")
                for _jr in job_results:
                    _burl = _jr.get("build_url", "")
                    _cmp  = (_jr.get("completed") or "").lower()
                    if not _burl:
                        if _jr.get("queue_url"):
                            _any_active = True
                            try:
                                _qr = sess.get(_jr["queue_url"].rstrip("/") + "/api/json", timeout=10)
                                if _qr.status_code == 200:
                                    _exe = _qr.json().get("executable")
                                    if _exe and _exe.get("url"):
                                        _jr["build_url"] = _exe["url"].rstrip("/") + "/"
                                        _jr["completed"]  = "Running"
                                        _append(f"  {_jr['job_name']}: resolved → {_jr['build_url']}\n")
                                        _poll_updated = True
                            except Exception:
                                pass
                        continue
                    if any(k in _cmp for k in _TERM_STATES):
                        continue   # already in terminal state
                    _any_active = True
                    try:
                        import time as _time_jcj_eta
                        _now_ms_jcj = int(_time_jcj_eta.time() * 1000)
                        _br = sess.get(
                            _burl.rstrip("/") + "/api/json"
                            "?tree=building,result,estimatedDuration,timestamp"
                            ",artifacts[fileName,relativePath],description,displayName",
                            timeout=15)
                        if _br.status_code == 200:
                            _bj = _br.json()
                            if _bj.get("building") is False:
                                _result = (_bj.get("result") or "").upper()
                                _jr["completed"] = {"SUCCESS": "Success", "FAILURE": "Failed",
                                                    "ABORTED": "Aborted", "UNSTABLE": "Unstable"
                                                    }.get(_result, _result or "Done")
                                _jr["eta_seconds"] = ""
                                if _result == "SUCCESS":
                                    # 1) artifact filename
                                    for _art in _bj.get("artifacts", []):
                                        _m = _ver_pat_jcj.search(_art.get("fileName", ""))
                                        if _m:
                                            _jr["build_version"] = _m.group(0)
                                            break
                                    # 2) fallback: description / displayName
                                    if not _jr.get("build_version"):
                                        for _txt in [_bj.get("description") or "",
                                                     _bj.get("displayName") or ""]:
                                            _m = _ver_pat_jcj.search(_txt)
                                            if _m:
                                                _jr["build_version"] = _m.group(0)
                                                break
                                    # 3) construct artifact_url
                                    if _jr.get("build_version"):
                                        _art_cfg = _jr.get("artifactory_url", "").strip()
                                        if _art_cfg:
                                            _jr["artifact_url"] = _re.sub(
                                                r'\{[^}]+\}', _jr["build_version"], _art_cfg)
                                        elif _bj.get("artifacts"):
                                            for _a in _bj["artifacts"]:
                                                if _a.get("relativePath"):
                                                    _jr["artifact_url"] = (
                                                        _burl.rstrip("/") + "/artifact/" + _a["relativePath"])
                                                    break
                                    _append(f"  ✓ {_jr['job_name']}: {_jr['completed']}"
                                            f"{' — ' + _jr['build_version'] if _jr.get('build_version') else ''}\n")
                                else:
                                    _append(f"  ✗ {_jr['job_name']}: {_jr['completed']}\n")
                                    overall_ok = False
                                _poll_updated = True
                            else:
                                _est   = _bj.get("estimatedDuration") or 0
                                _start = _bj.get("timestamp") or 0
                                if _est and _start:
                                    _jr["eta_seconds"] = str(max(0, int((_start + _est - _now_ms_jcj) / 1000)))
                    except Exception:
                        pass
                if _poll_updated:
                    _save_jcj_detail()
                    _jcj_update_project_status(app_name, pid, _jcj_compute_project_status(job_results))
                if not _any_active:
                    break
                _time.sleep(10)

            # --- save extracted build_version to projects.xlsx ---
            _first_build_ver = next(
                (_jr.get("build_version", "") for _jr in job_results if _jr.get("build_version")), "")
            if _first_build_ver:
                _jcj_update_project_payor_version(app_name, pid, _first_build_ver)

            # --- write final job detail file ---
            _save_jcj_detail()

            # --- update final project status ---
            final_status = _jcj_compute_project_status(job_results)
            _jcj_update_project_status(app_name, pid, final_status)
            _append(f"\n{'✓ All jobs completed.' if overall_ok else '✗ Some jobs failed or timed out.'}\n")

            with _jcj_op_lock:
                if _jcj_op["status"] == "running":
                    _jcj_op["status"] = "success" if overall_ok else "failed"

        except Exception as _e:
            _append(f"\nFatal error: {_e}\n")
            with _jcj_op_lock:
                if _jcj_op["status"] == "running":
                    _jcj_op["status"] = "failed"

    def _jcj_compute_project_status(job_results):
        total    = len(job_results)
        success  = sum(1 for j in job_results if any(k in (j.get("completed") or "").lower() for k in ("success", "passed", "completed", "done")))
        failed   = sum(1 for j in job_results if any(k in (j.get("completed") or "").lower() for k in ("failed", "failure", "error")))
        running  = sum(1 for j in job_results if any(k in (j.get("completed") or "").lower() for k in ("running", "building")))
        queued   = sum(1 for j in job_results if any(k in (j.get("completed") or "").lower() for k in ("queued", "triggered", "scheduled")))
        unstable = sum(1 for j in job_results if "unstable" in (j.get("completed") or "").lower())
        parts    = []
        if failed:   parts.append(f"{failed} failed")
        if running:  parts.append(f"{running} running")
        if queued:   parts.append(f"{queued} queued")
        if unstable: parts.append(f"{unstable} unstable")
        if success:  parts.append(f"{success} success")
        return f"{total} jobs: " + (", ".join(parts) if parts else "pending")

    def _jcj_update_project_status(app_name, pid, status):
        import openpyxl as _xl
        proj_path = JCJ_DATA / "projects.xlsx"
        if not proj_path.exists():
            return
        try:
            wb = _xl.load_workbook(str(proj_path))
            sheet = next((s for s in wb.sheetnames if s.lower() == app_name.lower()), None)
            if not sheet:
                return
            ws = wb[sheet]
            hdrs = [str(ws.cell(1, c).value or "").strip().lower() for c in range(1, ws.max_column + 1)]
            pid_col    = hdrs.index("project_id") + 1 if "project_id" in hdrs else 1
            status_col = hdrs.index("status") + 1 if "status" in hdrs else 4
            for r in range(2, ws.max_row + 1):
                if str(ws.cell(r, pid_col).value or "").strip() == str(pid):
                    ws.cell(r, status_col, status)
                    break
            wb.save(str(proj_path))
        except Exception:
            pass

    def _jcj_update_project_payor_version(app_name, pid, version):
        """Write extracted build_version into payor_release_version column of projects.xlsx."""
        import openpyxl as _xl
        proj_path = JCJ_DATA / "projects.xlsx"
        if not proj_path.exists():
            return
        try:
            wb = _xl.load_workbook(str(proj_path))
            sheet = next((s for s in wb.sheetnames if s.lower() == app_name.lower()), None)
            if not sheet:
                return
            ws = wb[sheet]
            hdrs = [str(ws.cell(1, c).value or "").strip().lower() for c in range(1, ws.max_column + 1)]
            pid_col = hdrs.index("project_id") + 1 if "project_id" in hdrs else 1
            ver_col = hdrs.index("payor_release_version") + 1 if "payor_release_version" in hdrs else 2
            for r in range(2, ws.max_row + 1):
                if str(ws.cell(r, pid_col).value or "").strip() == str(pid):
                    ws.cell(r, ver_col, version)
                    break
            wb.save(str(proj_path))
        except Exception:
            pass

    @app.route("/api/tools/jcj/trigger", methods=["POST"])
    def api_jcj_trigger():
        data      = request.get_json() or {}
        _app_name = data.get("app", "Payor") or "Payor"
        with _jcj_op_lock:
            if _jcj_op["status"] == "running":
                return jsonify({"ok": False, "error": "A Jenkins Commit Job run is already in progress"})
            _jcj_op.update({"status": "running", "output": "", "pid": None, "app": _app_name})
        _jcj_abort.clear()
        _threading.Thread(target=_run_jcj_bg, args=(data,), daemon=True).start()
        return jsonify({"ok": True})

    @app.route("/api/tools/jcj/op-status", methods=["GET"])
    def api_jcj_op_status():
        with _jcj_op_lock:
            return jsonify({"ok": True, "status": _jcj_op["status"],
                            "output": _jcj_op["output"], "pid": _jcj_op["pid"],
                            "app": _jcj_op.get("app")})

    @app.route("/api/tools/jcj/op-abort", methods=["POST"])
    def api_jcj_op_abort():
        with _jcj_op_lock:
            if _jcj_op["status"] != "running":
                return jsonify({"ok": False, "error": "No run in progress"})
            _jcj_op["output"] += "\n--- Abort requested ---\n"
            pid = _jcj_op.get("pid")
        _jcj_abort.set()
        if pid:
            import subprocess as _sp
            try: _sp.run(["taskkill", "/F", "/T", "/PID", str(pid)], capture_output=True)
            except Exception: pass
        return jsonify({"ok": True})

    @app.route("/api/tools/jcj/config", methods=["GET"])
    def api_jcj_config():
        import openpyxl as _xl
        cfg_path = JCJ_ROOT / "git_config.xlsx"
        payor_repo = ""
        if cfg_path.exists():
            try:
                wb = _xl.load_workbook(str(cfg_path))
                ws = wb.active
                for row in ws.iter_rows(min_row=2, values_only=True):
                    if row[0] and str(row[0]).strip().lower() == "payor" and row[1]:
                        payor_repo = str(row[1]).strip().rstrip("/")
                        break
            except Exception:
                pass
        return jsonify({"payor_repo_url": payor_repo})

    @app.route("/api/tools/jcj/scheduler-settings", methods=["GET"])
    def api_jcj_get_scheduler_settings():
        import openpyxl as _xl
        settings = []
        _cfg = JCJ_ROOT / "scheduler_config.xlsx"
        if _cfg.exists():
            try:
                _wb = _xl.load_workbook(str(_cfg), data_only=True)
                _ws = _wb.active
                _hdrs = [str(_ws.cell(1, c).value or "").strip().lower()
                         for c in range(1, _ws.max_column + 1)]
                _notes_col = _hdrs.index("notes") if "notes" in _hdrs else None
                for _r in _ws.iter_rows(min_row=2, values_only=True):
                    if not _r[0]:
                        continue
                    _k = str(_r[0]).strip()
                    _v = str(_r[1]).strip() if _r[1] is not None else ""
                    _n = str(_r[_notes_col]).strip() if (_notes_col is not None and _r[_notes_col]) else ""
                    settings.append({"key": _k, "value": _v, "notes": _n})
            except Exception:
                pass
        _DEFAULTS_JCJ = [
            ("poll_interval_s",      "60",  "Jenkins status poll interval in seconds"),
            ("max_poll_hours",        "48",  "Mark stale jobs as conn_err after this many hours"),
            ("stale_threshold_hours", "48",  "Startup recovery: ignore projects older than this"),
        ]
        _existing_keys_jcj = {s["key"].lower() for s in settings}
        for _dk, _dv, _dn in _DEFAULTS_JCJ:
            if _dk.lower() not in _existing_keys_jcj:
                settings.append({"key": _dk, "value": _dv, "notes": _dn})
        return jsonify({"ok": True, "settings": settings})

    @app.route("/api/tools/jcj/scheduler-settings", methods=["POST"])
    def api_jcj_post_scheduler_settings():
        data = request.get_json() or {}
        updates = data.get("settings", {})
        if not isinstance(updates, dict):
            return jsonify({"ok": False, "error": "settings must be a key:value object"}), 400
        for _k, _v in updates.items():
            _jcj_write_scheduler_setting(str(_k).strip(), str(_v).strip())
        return jsonify({"ok": True})

    @app.route("/api/tools/jcj/projects/<pid>/jobs", methods=["GET"])
    def api_jcj_project_jobs(pid):
        import openpyxl as _xl, time as _tj
        _jcj_app = request.args.get("app", "Payor")
        proj_dir = JCJ_DATA / "projects" / _jcj_app
        if not proj_dir.exists():
            return jsonify([])
        matches = list(proj_dir.glob(f"{pid}_*.xlsx"))
        if not matches:
            return jsonify([])
        detail_path = matches[0]
        job_cols = ["job_name", "job_url", "completed", "runs", "triggered_at", "build_url", "queue_url", "build_version", "artifact_url", "artifactory_url", "eta_seconds"]
        try:
            wb   = _xl.load_workbook(str(detail_path))
            if "jobs" not in wb.sheetnames:
                return jsonify([])
            ws   = wb["jobs"]
            hdrs = [str(ws.cell(1, c).value or "").strip().lower()
                    for c in range(1, ws.max_column + 1)]
            rows = []
            for row in ws.iter_rows(min_row=2, values_only=True):
                if any(v is not None for v in row):
                    rows.append({k: ("" if v is None else str(v)) for k, v in zip(hdrs, row)})

            # migrate xlsx if headers are missing any job_cols (e.g. eta_seconds added later)
            if hdrs != job_cols:
                try:
                    for ci, col in enumerate(job_cols, 1):
                        ws.cell(1, ci, col)
                    if ws.max_row > 1:
                        ws.delete_rows(2, ws.max_row - 1)
                    for r in rows:
                        ws.append([r.get(k, "") for k in job_cols])
                    wb.save(str(detail_path))
                except Exception:
                    pass

            # backfill artifactory_url from current config for rows missing it (old runs pre-dating the column)
            try:
                _cfg_path = JCJ_ROOT / "commit_job_config.xlsx"
                if _cfg_path.exists():
                    _cwb = _xl.load_workbook(str(_cfg_path))
                    _sheet = next((s for s in _cwb.sheetnames if s.lower() == _jcj_app.lower()), None)
                    if _sheet:
                        _cws  = _cwb[_sheet]
                        _chdrs = [str(_cws.cell(1, c).value or "").strip().lower()
                                  for c in range(1, _cws.max_column + 1)]
                        _cfg_map = {}
                        for _crow in _cws.iter_rows(min_row=2, values_only=True):
                            if _crow[0]:
                                _cd = {k: str(v or "").strip() for k, v in zip(_chdrs, _crow)}
                                _cfg_map[_cd.get("job_name", str(_crow[0])).strip().lower()] = _cd
                        for r in rows:
                            if not r.get("artifactory_url"):
                                _cd = _cfg_map.get((r.get("job_name") or "").lower())
                                if _cd:
                                    r["artifactory_url"] = _cd.get("artifactory_url", "")
            except Exception:
                pass

            # fast-path: if artifactory_url + build_version are already known, recompute artifact_url in-memory now
            import re as _re_art
            _fast_updated = False
            for r in rows:
                art_cfg = r.get("artifactory_url", "").strip()
                bv      = r.get("build_version", "").strip()
                if art_cfg and bv:
                    expected = _re_art.sub(r'\{[^}]+\}', bv, art_cfg)
                    if r.get("artifact_url") != expected:
                        r["artifact_url"] = expected
                        _fast_updated = True

            pending_q = [r for r in rows if r.get("queue_url") and not r.get("build_url")]
            running_j = [r for r in rows if r.get("build_url") and
                         any(k in (r.get("completed") or "").lower() for k in ("running", "building", "queued", "triggered"))]

            def _needs_artifact_fetch(r):
                if not r.get("build_url"):
                    return False
                if not any(k in (r.get("completed") or "").lower() for k in ("success", "passed", "done", "completed")):
                    return False
                if not r.get("artifact_url"):
                    return True
                # re-fetch if artifactory_url is configured but artifact_url still points to Jenkins
                art_cfg = r.get("artifactory_url", "").strip()
                if art_cfg and not r.get("artifact_url", "").startswith(art_cfg.split("{")[0]):
                    return True
                return False

            if _fast_updated and not (pending_q or running_j or any(_needs_artifact_fetch(r) for r in rows)):
                # no Jenkins poll needed but artifact_url was fixed — persist now
                try:
                    for ci, col in enumerate(job_cols, 1):
                        ws.cell(1, ci, col)
                    if ws.max_row > 1:
                        ws.delete_rows(2, ws.max_row - 1)
                    for r in rows:
                        ws.append([r.get(k, "") for k in job_cols])
                    wb.save(str(detail_path))
                except Exception:
                    pass

            if pending_q or running_j or any(_needs_artifact_fetch(r) for r in rows):
                try:
                    import requests as _req_j, re as _re_ver
                    _sec  = _jcj_load_secrets()
                    _u    = _sec.get("jenkins_username", "")
                    _t    = _sec.get("jenkins_api_token", "") or _sec.get("jenkins_password", "")
                    _auth = (_u, _t) if _u and _t else None
                    now_ms = int(_tj.time() * 1000)
                    updated = False

                    # resolve queue → build for queued jobs
                    for r in pending_q:
                        try:
                            qr = _req_j.get(r["queue_url"].rstrip("/") + "/api/json", auth=_auth, timeout=8)
                            if qr.status_code == 200:
                                exe = qr.json().get("executable")
                                if exe and exe.get("url"):
                                    r["build_url"] = exe["url"].rstrip("/") + "/"
                                    r["completed"]  = "Running"
                                    updated = True
                        except Exception:
                            pass

                    # poll build status + ETA for running jobs
                    for r in (running_j + [r for r in pending_q if r.get("build_url")]):
                        if not r.get("build_url"):
                            continue
                        try:
                            br = _req_j.get(r["build_url"].rstrip("/") + "/api/json", auth=_auth, timeout=8)
                            if br.status_code == 200:
                                bj       = br.json()
                                building = bj.get("building")
                                if building is False:
                                    result = (bj.get("result") or "").upper()
                                    r["completed"]  = {"SUCCESS": "Success", "FAILURE": "Failed",
                                                       "ABORTED": "Aborted", "UNSTABLE": "Unstable"}.get(result, result or "Done")
                                    r["eta_seconds"] = ""
                                    updated = True
                                else:
                                    r["completed"]   = "Running"
                                    est  = bj.get("estimatedDuration") or 0
                                    start= bj.get("timestamp") or 0
                                    if est and start:
                                        r["eta_seconds"] = str(max(0, int((start + est - now_ms) / 1000)))
                                        updated = True
                        except Exception:
                            pass

                    # fetch artifact info for succeeded jobs that don't yet have artifact_url
                    _ver_pat = _re_ver.compile(r'\d+\.\d+[\d.]*-\d+-[0-9a-f]+')
                    for r in rows:
                        if _needs_artifact_fetch(r):
                            r["artifact_url"] = ""  # clear stale value before re-fetch
                            try:
                                ar = _req_j.get(
                                    r["build_url"].rstrip("/") + "/api/json?tree=artifacts[fileName,relativePath],description,displayName",
                                    auth=_auth, timeout=8)
                                if ar.status_code == 200:
                                    bdata = ar.json()
                                    # 1) try archived artifacts
                                    for art in bdata.get("artifacts", []):
                                        fname = art.get("fileName", "")
                                        rel   = art.get("relativePath", "")
                                        m = _ver_pat.search(fname)
                                        if m:
                                            r["build_version"] = m.group(0)
                                            updated = True
                                            break
                                    # 2) fallback: description or displayName
                                    if not r.get("build_version"):
                                        for text in [bdata.get("description") or "", bdata.get("displayName") or ""]:
                                            m = _ver_pat.search(text)
                                            if m:
                                                r["build_version"] = m.group(0)
                                                updated = True
                                                break
                                    # 3) construct artifact_url: prefer configured artifactory_url, else Jenkins artifact
                                    if r.get("build_version"):
                                        art_cfg = r.get("artifactory_url", "").strip()
                                        if art_cfg:
                                            import re as _re_art2
                                            r["artifact_url"] = _re_art2.sub(r'\{[^}]+\}', r["build_version"], art_cfg)
                                            updated = True
                                        elif bdata.get("artifacts"):
                                            for art in bdata["artifacts"]:
                                                rel = art.get("relativePath", "")
                                                if rel:
                                                    r["artifact_url"] = r["build_url"].rstrip("/") + "/artifact/" + rel
                                                    updated = True
                                                    break
                                        else:
                                            r["artifact_url"] = r["build_url"].rstrip("/") + "/"
                                            updated = True
                            except Exception:
                                pass

                    if updated or _fast_updated:
                        # Ensure header row has all columns before rewriting data
                        for ci, col in enumerate(job_cols, 1):
                            ws.cell(1, ci, col)
                        if ws.max_row > 1:
                            ws.delete_rows(2, ws.max_row - 1)
                        for r in rows:
                            ws.append([r.get(k, "") for k in job_cols])
                        wb.save(str(detail_path))
                        _jcj_update_project_status(_jcj_app, pid, _jcj_compute_project_status(rows))
                except Exception:
                    pass

            return jsonify(rows)
        except Exception as e:
            return jsonify({"error": str(e)}), 500

    @app.route("/api/tools/jcj/projects/<pid>/retrigger-job", methods=["POST"])
    def api_jcj_retrigger_job(pid):
        import openpyxl as _xl, requests as _req
        from urllib.parse import urlparse as _up
        data     = request.get_json() or {}
        job_name = (data.get("job_name") or "").strip()
        app_name = (data.get("app") or "Payor").strip()
        if not job_name:
            return jsonify({"ok": False, "error": "job_name required"}), 400
        proj_dir  = JCJ_DATA / "projects" / app_name
        proj_path = proj_dir / f"{pid}_run.xlsx"
        if not proj_path.exists():
            matches   = list(proj_dir.glob(f"{pid}_*.xlsx")) if proj_dir.exists() else []
            proj_path = matches[0] if matches else None
        if not proj_path:
            return jsonify({"ok": False, "error": "Project not found"}), 404
        try:
            wb      = _xl.load_workbook(str(proj_path))
            ws_jobs = wb["jobs"] if "jobs" in wb.sheetnames else wb.active
            hdrs = [str(ws_jobs.cell(1, c).value or "").strip().lower()
                    for c in range(1, ws_jobs.max_column + 1)]
            job_row_idx = None
            job_url     = ""
            for _idx in range(2, ws_jobs.max_row + 1):
                _jn = str(ws_jobs.cell(_idx, hdrs.index("job_name") + 1).value or "").strip()
                if _jn == job_name:
                    job_row_idx = _idx
                    if "job_url" in hdrs:
                        job_url = str(ws_jobs.cell(_idx, hdrs.index("job_url") + 1).value or "").strip()
                    break
            if not job_url:
                return jsonify({"ok": False, "error": f"No URL for job {job_name}"}), 404
            _sec = {}
            try:
                if SECRETS_FILE.exists():
                    _swb = _xl.load_workbook(str(SECRETS_FILE))
                    if "Jenkins" in _swb.sheetnames:
                        for _r in _swb["Jenkins"].iter_rows(min_row=2, values_only=True):
                            if _r[0] and _r[1] is not None:
                                _sec[str(_r[0]).strip()] = str(_r[1]).strip()
            except Exception:
                pass
            _auth = ((_sec.get("jenkins_username", ""),
                      _sec.get("jenkins_api_token", "") or _sec.get("jenkins_password", ""))
                     if _sec.get("jenkins_username") else None)
            params = {}
            for _pp in [JCJ_ROOT / "jenkins_params" / app_name / f"payor_{job_name}_jenkins_params.xlsx",
                        JCJ_ROOT / "jenkins_params" / f"payor_{job_name}_jenkins_params.xlsx"]:
                if _pp.exists():
                    try:
                        _pwb = _xl.load_workbook(str(_pp))
                        _pws = _pwb["BuildParameters"] if "BuildParameters" in _pwb.sheetnames else _pwb.active
                        for _pr in _pws.iter_rows(min_row=2, values_only=True):
                            if _pr[0] and _pr[1] is not None:
                                params[str(_pr[0]).strip()] = str(_pr[1]).strip()
                    except Exception:
                        pass
                    break
            parsed  = _up(job_url)
            base    = f"{parsed.scheme}://{parsed.netloc}"
            crumb_h = {}
            try:
                _cr = _req.get(f"{base}/crumbIssuer/api/json", auth=_auth, verify=False, timeout=8)
                if _cr.status_code == 200:
                    _cj = _cr.json()
                    crumb_h = {_cj["crumbRequestField"]: _cj["crumb"]}
            except Exception:
                pass
            _endpoint = job_url.rstrip("/") + ("/buildWithParameters" if params else "/build")
            _resp = _req.post(_endpoint, params=params if params else None,
                              headers=crumb_h, auth=_auth, verify=False, timeout=10)
            if _resp.status_code in (200, 201):
                queue_url = (_resp.headers.get("Location") or "").rstrip("/") + "/"
                if job_row_idx is not None:
                    if "queue_url" in hdrs:
                        ws_jobs.cell(job_row_idx, hdrs.index("queue_url") + 1, queue_url)
                    if "build_url" in hdrs:
                        ws_jobs.cell(job_row_idx, hdrs.index("build_url") + 1, "")
                    if "completed" in hdrs:
                        ws_jobs.cell(job_row_idx, hdrs.index("completed") + 1, "Scheduled")
                    wb.save(str(proj_path))
                return jsonify({"ok": True, "queue_url": queue_url, "status": "Scheduled"})
            else:
                return jsonify({"ok": False, "error": f"Jenkins HTTP {_resp.status_code}"})
        except Exception as _e:
            return jsonify({"ok": False, "error": str(_e)}), 500

    @app.route("/api/tools/jcj/artifact-download", methods=["GET"])
    def api_jcj_artifact_download():
        import requests as _rdl
        from flask import Response, stream_with_context as _swc
        url = request.args.get("url", "").strip()
        if not url:
            return jsonify({"error": "url required"}), 400
        try:
            no_jenkins_auth = request.args.get("no_jenkins_auth", "")
            if no_jenkins_auth:
                _auth = None
            else:
                _sec  = _jcj_load_secrets()
                _u    = _sec.get("jenkins_username", "")
                _t    = _sec.get("jenkins_api_token", "") or _sec.get("jenkins_password", "")
                _auth = (_u, _t) if _u and _t else None
            import urllib3 as _ul3
            _ul3.disable_warnings(_ul3.exceptions.InsecureRequestWarning)
            resp  = _rdl.get(url, auth=_auth, stream=True, timeout=60, verify=False)
            if resp.status_code != 200:
                return jsonify({"error": f"Download returned {resp.status_code}"}), resp.status_code
            fname = url.rstrip("/").split("/")[-1] or "artifact"
            return Response(
                _swc(resp.iter_content(chunk_size=65536)),
                content_type=resp.headers.get("Content-Type", "application/octet-stream"),
                headers={"Content-Disposition": f'attachment; filename="{fname}"'}
            )
        except Exception as _e:
            return jsonify({"error": str(_e)}), 500

