    @app.route("/api/tools/jcj/apps", methods=["POST"])
    def api_jcj_apps_post():
        import openpyxl as _xl
        from openpyxl.styles import Font as _Fn, PatternFill as _Pf, Alignment as _Al
        data     = request.get_json() or {}
        app_name = str(data.get("name", "") or "").strip()
        if not app_name:
            return jsonify({"ok": False, "error": "App name required"})
        if any(c in set('/\\:*?"<>|') for c in app_name):
            return jsonify({"ok": False, "error": "App name contains invalid characters"})
        try:
            _hf = _Pf("solid", fgColor="1F3864")
            _ff = _Fn(bold=True, color="FFFFFF", name="Calibri")
            _al = _Al(horizontal="left", vertical="center")
            _PROJ_COLS   = ["project_id", "payor_release_version", "runs", "status", "triggered_at"]
            _PROJ_WIDTHS = [12, 22, 8, 14, 22]

            proj_path = JCJ_DATA / "projects.xlsx"
            JCJ_ROOT.mkdir(parents=True, exist_ok=True)
            wb = _xl.load_workbook(str(proj_path)) if proj_path.exists() else _xl.Workbook()
            if app_name not in wb.sheetnames:
                ws = wb.create_sheet(title=app_name)
                ws.append(_PROJ_COLS)
                for i, (col, w) in enumerate(zip(_PROJ_COLS, _PROJ_WIDTHS), 1):
                    c = ws.cell(1, i); c.font = _ff; c.fill = _hf; c.alignment = _al
                    ws.column_dimensions[ws.cell(1, i).column_letter].width = w
                if "Sheet" in wb.sheetnames and app_name != "Sheet":
                    wb.remove(wb["Sheet"])
                wb.save(str(proj_path))

            (JCJ_DATA / "projects" / app_name).mkdir(parents=True, exist_ok=True)
            (JCJ_ROOT / "jenkins_params" / app_name).mkdir(parents=True, exist_ok=True)

            cfg_path = JCJ_ROOT / "commit_job_config.xlsx"
            wbc = _xl.load_workbook(str(cfg_path)) if cfg_path.exists() else _xl.Workbook()
            cfg_sheet = app_name.lower()
            if cfg_sheet not in [s.lower() for s in wbc.sheetnames]:
                wsc = wbc.create_sheet(title=cfg_sheet)
                for ci, col in enumerate(("job_name", "job_url"), 1):
                    c = wsc.cell(1, ci, col); c.font = _ff; c.fill = _hf
                if "Sheet" in wbc.sheetnames and cfg_sheet != "Sheet":
                    wbc.remove(wbc["Sheet"])
                wbc.save(str(cfg_path))

            wb2 = _xl.load_workbook(str(proj_path), read_only=True)
            apps_list = list(wb2.sheetnames)
            wb2.close()
            return jsonify({"ok": True, "apps": apps_list})
        except Exception as _e:
            return jsonify({"ok": False, "error": str(_e)})

    @app.route("/api/tools/jcj/apps/<app_name>", methods=["DELETE"])
    def api_jcj_apps_delete(app_name):
        import openpyxl as _xl, shutil as _sh
        if not app_name:
            return jsonify({"ok": False, "error": "App name required"})
        try:
            proj_path = JCJ_DATA / "projects.xlsx"
            if proj_path.exists():
                wb = _xl.load_workbook(str(proj_path))
                if app_name in wb.sheetnames:
                    del wb[app_name]
                    wb.save(str(proj_path))

            for sub in ("projects", "jenkins_params"):
                d = JCJ_ROOT / sub / app_name
                if d.exists():
                    _sh.rmtree(str(d))

            cfg_path = JCJ_ROOT / "commit_job_config.xlsx"
            if cfg_path.exists():
                wbc = _xl.load_workbook(str(cfg_path))
                for sn in list(wbc.sheetnames):
                    if sn.lower() == app_name.lower():
                        del wbc[sn]; break
                wbc.save(str(cfg_path))

            apps_list = []
            if proj_path.exists():
                wb2 = _xl.load_workbook(str(proj_path), read_only=True)
                apps_list = list(wb2.sheetnames)
                wb2.close()
            return jsonify({"ok": True, "apps": apps_list})
        except Exception as _e:
            return jsonify({"ok": False, "error": str(_e)})

    @app.route("/api/tools/jcj/job-config/<app_name>", methods=["GET"])
    def api_jcj_job_config_get(app_name):
        import openpyxl as _xl
        path = JCJ_ROOT / "commit_job_config.xlsx"
        jobs = []
        if path.exists():
            try:
                wb = _xl.load_workbook(str(path), read_only=True, data_only=True)
                sheet_name = app_name.lower()
                if sheet_name not in wb.sheetnames and app_name in wb.sheetnames:
                    sheet_name = app_name
                if sheet_name in wb.sheetnames:
                    ws = wb[sheet_name]
                    hdrs = [str(ws.cell(1, c).value or "").strip().lower() for c in range(1, ws.max_column + 1)]
                    for row in ws.iter_rows(min_row=2, values_only=True):
                        if any(v is not None for v in row):
                            d = {k: str(v or "").strip() for k, v in zip(hdrs, row)}
                            if d.get("job_name"):
                                raw_en = d.get("enabled", "1")
                                d["enabled"] = raw_en not in ("0", "false", "no")
                                jobs.append(d)
                wb.close()
            except Exception as _e:
                return jsonify({"ok": False, "error": str(_e)})
        repo_url = ""
        git_cfg = JCJ_ROOT / "git_config.xlsx"
        if git_cfg.exists():
            try:
                wbg = _xl.load_workbook(str(git_cfg), read_only=True)
                wsg = wbg["repos"] if "repos" in wbg.sheetnames else None
                if wsg:
                    key = app_name.lower()
                    for row in wsg.iter_rows(min_row=2, values_only=True):
                        if row[0] and str(row[0]).strip().lower() == key and row[1]:
                            repo_url = str(row[1]).strip(); break
                wbg.close()
            except Exception:
                pass
        resp = jsonify({"ok": True, "jobs": jobs, "repo_url": repo_url})
        resp.headers["Cache-Control"] = "no-store"
        return resp

    @app.route("/api/tools/jcj/job-config/<app_name>", methods=["POST"])
    def api_jcj_job_config_post(app_name):
        import openpyxl as _xl
        data    = request.get_json() or {}
        jobs_in = data.get("jobs", [])
        path    = JCJ_ROOT / "commit_job_config.xlsx"
        JCJ_ROOT.mkdir(parents=True, exist_ok=True)
        try:
            wb = _xl.load_workbook(str(path)) if path.exists() else _xl.Workbook()
            sheet_name = app_name.lower()
            if sheet_name not in wb.sheetnames:
                if app_name in wb.sheetnames:
                    sheet_name = app_name
                else:
                    from openpyxl.styles import Font as _Fn3, PatternFill as _Pf3
                    _hf3 = _Pf3("solid", fgColor="1F3864"); _ff3 = _Fn3(bold=True, color="FFFFFF", name="Calibri")
                    ws = wb.create_sheet(title=sheet_name)
                    for ci, col in enumerate(("job_name", "job_url", "artifactory_url", "enabled"), 1):
                        c = ws.cell(1, ci, col); c.font = _ff3; c.fill = _hf3
                    if "Sheet" in wb.sheetnames and sheet_name != "Sheet":
                        wb.remove(wb["Sheet"])
                    wb.save(str(path))
                    wb = _xl.load_workbook(str(path))
            ws = wb[sheet_name]
            hdrs = [str(ws.cell(1, c).value or "").strip().lower() for c in range(1, ws.max_column + 1)]
            if not hdrs or hdrs[0] != "job_name":        ws.cell(1, 1, "job_name")
            if len(hdrs) < 2 or hdrs[1] != "job_url":   ws.cell(1, 2, "job_url")
            if len(hdrs) < 3 or hdrs[2] != "artifactory_url": ws.cell(1, 3, "artifactory_url")
            if len(hdrs) < 4 or hdrs[3] != "enabled":   ws.cell(1, 4, "enabled")
            if ws.max_row > 1:
                ws.delete_rows(2, ws.max_row - 1)
            for j in jobs_in:
                name    = str(j.get("job_name",        "") or "").strip()
                url     = str(j.get("job_url",         "") or "").strip()
                art     = str(j.get("artifactory_url", "") or "").strip()
                enabled = "0" if j.get("enabled") is False else "1"
                if name or url:
                    ws.append([name, url, art, enabled])
            wb.save(str(path))
            repo_url = str(data.get("repo_url", "") or "").strip()
            if repo_url is not None:
                git_cfg = JCJ_ROOT / "git_config.xlsx"
                try:
                    from openpyxl.styles import Font as _GFn2, PatternFill as _GPf2
                    if git_cfg.exists():
                        wbg = _xl.load_workbook(str(git_cfg))
                    else:
                        wbg = _xl.Workbook()
                    if "repos" not in wbg.sheetnames:
                        wsg = wbg.active; wsg.title = "repos"
                        _hfg = _GPf2("solid", fgColor="1F3864"); _ffg = _GFn2(bold=True, color="FFFFFF", name="Calibri")
                        for ci, col in enumerate(("name", "repo_url"), 1):
                            c = wsg.cell(1, ci, col); c.font = _ffg; c.fill = _hfg
                        wsg.column_dimensions["A"].width = 20; wsg.column_dimensions["B"].width = 80
                    else:
                        wsg = wbg["repos"]
                    key = app_name.lower(); updated = False
                    for r in range(2, wsg.max_row + 1):
                        if str(wsg.cell(r, 1).value or "").strip().lower() == key:
                            wsg.cell(r, 2, repo_url); updated = True; break
                    if not updated:
                        wsg.append([key, repo_url])
                    wbg.save(str(git_cfg))
                except Exception:
                    pass
            return jsonify({"ok": True})
        except Exception as _e:
            return jsonify({"ok": False, "error": str(_e)})

    @app.route("/api/tools/jcj/params/<app_name>", methods=["GET"])
    def api_jcj_params_get(app_name):
        import openpyxl as _xl
        params_dir = JCJ_ROOT / "jenkins_params" / app_name
        if not params_dir.exists():
            return jsonify({"ok": True, "jobs": []})
        app_lower = app_name.lower()
        prefix = f"{app_lower}_"; suffix = "_jenkins_params"
        jobs_out = []
        for f in sorted(params_dir.glob(f"{prefix}*_jenkins_params.xlsx")):
            after_prefix = f.stem[len(prefix):]
            job_name = after_prefix[:-len(suffix)] if after_prefix.endswith(suffix) else after_prefix
            try:
                wb = _xl.load_workbook(str(f), read_only=True, data_only=True)
                params = []; choices = {}
                if "BuildParameters" in wb.sheetnames:
                    ws = wb["BuildParameters"]
                    hdrs = [str(ws.cell(1, c).value or "").strip().lower() for c in range(1, ws.max_column + 1)]
                    for row in ws.iter_rows(min_row=2, values_only=True):
                        if any(v is not None for v in row):
                            d = {k: str(v or "").strip() for k, v in zip(hdrs, row)}
                            if d.get("param_name"):
                                params.append(d)
                for sn in wb.sheetnames:
                    if sn != "BuildParameters":
                        cws = wb[sn]
                        c_list = [str(r[0] or "") for r in cws.iter_rows(min_row=2, values_only=True) if r[0] is not None]
                        if c_list:
                            choices[sn] = c_list
                wb.close()
                jobs_out.append({"job_name": job_name, "params": params, "choices": choices})
            except Exception as _e:
                jobs_out.append({"job_name": job_name, "params": [], "choices": {}, "error": str(_e)})
        return jsonify({"ok": True, "jobs": jobs_out})

    @app.route("/api/tools/jcj/params/<app_name>", methods=["POST"])
    def api_jcj_params_post(app_name):
        import openpyxl as _xl
        data = request.get_json() or {}
        job_name  = data.get("job_name", "").strip()
        params_in = data.get("params", [])
        if not job_name:
            return jsonify({"ok": False, "error": "job_name required"})
        path = JCJ_ROOT / "jenkins_params" / app_name / f"{app_name.lower()}_{job_name}_jenkins_params.xlsx"
        if not path.exists():
            return jsonify({"ok": False, "error": f"File not found: {path.name}"})
        try:
            wb = _xl.load_workbook(str(path))
            if "BuildParameters" not in wb.sheetnames:
                return jsonify({"ok": False, "error": "BuildParameters sheet not found"})
            ws = wb["BuildParameters"]
            hdrs = [str(ws.cell(1, c).value or "").strip().lower() for c in range(1, ws.max_column + 1)]
            val_col = (hdrs.index("param_value") + 1) if "param_value" in hdrs else None
            if val_col is None:
                return jsonify({"ok": False, "error": "No 'param_value' column in BuildParameters"})
            updates = {p.get("param_name", "").strip(): p.get("param_value", "") for p in params_in if p.get("param_name")}
            for row in ws.iter_rows(min_row=2):
                name = str(row[0].value or "").strip()
                if name in updates:
                    row[val_col - 1].value = updates[name]
            wb.save(str(path))
            return jsonify({"ok": True})
        except Exception as _e:
            return jsonify({"ok": False, "error": str(_e)})

    @app.route("/api/tools/jcj/fetch-params/<app_name>", methods=["POST"])
    def api_jcj_fetch_params(app_name):
        import subprocess as _sp, sys as _sys
        script = JCJ_ROOT / "scripts" / "fetch_job_params.py"
        if not script.exists():
            return jsonify({"ok": False, "error": "fetch_job_params.py not found"})
        python = _sys.executable
        _cflags = 0x08000000 if _sys.platform == "win32" else 0
        try:
            result = _sp.run(
                [python, str(script), "--app", app_name],
                capture_output=True, text=True, timeout=120,
                cwd=str(JCJ_ROOT / "scripts"),
                creationflags=_cflags,
            )
            lines = []
            if result.stdout: lines.extend(result.stdout.splitlines())
            if result.stderr:  lines.extend(result.stderr.splitlines())
            if result.returncode != 0:
                lines.append(f"ERROR: fetch failed (exit code {result.returncode})")
                return jsonify({"ok": False, "output": "\n".join(lines)})
            return jsonify({"ok": True, "output": "\n".join(lines)})
        except _sp.TimeoutExpired:
            return jsonify({"ok": False, "output": "ERROR: Timed out after 120s"})
        except Exception as _e:
            return jsonify({"ok": False, "output": str(_e)})

    @app.route("/api/tools/workflow-stats", methods=["GET"])
    def api_workflow_stats():
        import os as _os
        import openpyxl as _oxl
        from datetime import datetime as _dt

        ACTIVE_KWS = ('running', 'scheduled', 'triggered', 'building', 'created', 'in_progress', 'in progress', 'open')
        PASSED_KWS = ('passed', 'completed', 'success', 'done')
        FAILED_KWS = ('failed', 'error', 'unstable')
        CANCEL_KWS = ('cancelled', 'aborted', 'canceled')

        def classify(val, null_is_running=True):
            if val is True:  return 'passed'
            if val is False or val is None:
                return 'running' if null_is_running else 'other'
            s = str(val).lower().strip()
            if s in ('', 'none', 'false', '0'):
                return 'running' if null_is_running else 'other'
            if s in ('true', '1'):              return 'passed'
            if any(k in s for k in ACTIVE_KWS): return 'running'
            if any(k in s for k in PASSED_KWS): return 'passed'
            if any(k in s for k in FAILED_KWS): return 'failed'
            if any(k in s for k in CANCEL_KWS): return 'cancelled'
            return 'other'

        def read_counts(path, sheet_name, col_name, extra_cols=None, null_is_running=True):
            empty = {'total': 0, 'running': 0, 'passed': 0, 'failed': 0, 'cancelled': 0, 'other': 0}
            if not _os.path.exists(str(path)):
                return empty, []
            try:
                wb = _oxl.load_workbook(str(path), read_only=True, data_only=True)
                if sheet_name not in wb.sheetnames:
                    wb.close()
                    return empty, []
                ws = wb[sheet_name]
                hdrs = [str(ws.cell(1, c).value or '').strip().lower() for c in range(1, ws.max_column + 1)]
                if col_name.lower() not in hdrs:
                    wb.close()
                    return empty, []
                si = hdrs.index(col_name.lower())
                extra_idx = {}
                if extra_cols:
                    for ec in extra_cols:
                        if ec.lower() in hdrs:
                            extra_idx[ec] = hdrs.index(ec.lower())
                counts = dict(empty)
                rows_extra = []
                for row in ws.iter_rows(min_row=2, values_only=True):
                    if any(v is not None for v in row):
                        counts['total'] += 1
                        cat = classify(row[si], null_is_running)
                        counts[cat] += 1
                        if extra_cols:
                            er = {ec: (row[idx] if idx < len(row) else None) for ec, idx in extra_idx.items()}
                            er['_status'] = cat
                            rows_extra.append(er)
                wb.close()
                return counts, rows_extra
            except Exception:
                return empty, []

        def write_stats(stats_dir, counts):
            try:
                _os.makedirs(str(stats_dir), exist_ok=True)
                p = _os.path.join(str(stats_dir), 'stats.xlsx')
                headers = ['timestamp', 'total', 'running', 'passed', 'failed', 'cancelled', 'other']
                ts = _dt.now().strftime('%Y-%m-%d %H:%M:%S')
                new_vals = [counts.get(h, 0) for h in headers[1:]]
                if _os.path.exists(p):
                    wb = _oxl.load_workbook(p)
                    ws = wb.active
                    last = None
                    for row in ws.iter_rows(min_row=2, values_only=True):
                        last = row
                    if last and list(last[1:]) == new_vals:
                        wb.close()
                        return
                else:
                    wb = _oxl.Workbook()
                    ws = wb.active
                    ws.append(headers)
                ws.append([ts] + new_vals)
                wb.save(p)
            except Exception:
                pass

        def compute_eta(rows_extra):
            now_ms = _dt.now().timestamp() * 1000
            best_remaining = None
            for r in rows_extra:
                if r['_status'] != 'running':
                    continue
                est = r.get('est_ms')
                triggered = r.get('triggered_at')
                if not est or not triggered:
                    continue
                try:
                    est_ms = float(est)
                    if hasattr(triggered, 'timestamp'):
                        start_ms = triggered.timestamp() * 1000
                    else:
                        from datetime import datetime as _dt2
                        start_ms = _dt2.fromisoformat(str(triggered)).timestamp() * 1000
                    remaining = est_ms - (now_ms - start_ms)
                    if remaining > 0 and (best_remaining is None or remaining < best_remaining):
                        best_remaining = remaining
                except Exception:
                    pass
            return int(best_remaining) if best_remaining is not None else None

        tool_defs = [
            {'key': 'puc',          'path': PUC_ROOT / 'projects.xlsx', 'sheet': 'Projects', 'col': 'status',    'root': PUC_ROOT, 'eta_cols': None, 'null_is_running': False},
            # baseline, jreg, jcj handled separately below (multi-app sum)
            {'key': 'remote-setup', 'path': RS_ROOT  / 'projects.xlsx', 'sheet': 'Projects', 'col': 'status',    'root': RS_ROOT,  'eta_cols': None, 'null_is_running': False},
            {'key': 'melissa',      'path': MDL_ROOT / 'projects.xlsx', 'sheet': 'Projects', 'col': 'status',    'root': MDL_ROOT, 'eta_cols': None, 'null_is_running': False},
            {'key': 'rpb',          'path': RPB_ROOT / 'projects.xlsx', 'sheet': 'Payor',    'col': 'status',    'root': RPB_ROOT, 'eta_cols': None, 'null_is_running': False},
        ]

        result = {}
        for td in tool_defs:
            counts, rows_extra = read_counts(td['path'], td['sheet'], td['col'], td.get('eta_cols'), td.get('null_is_running', True))
            write_stats(td['root'] / 'stats', counts)
            entry = dict(counts)
            if td.get('eta_cols'):
                eta = compute_eta(rows_extra)
                if eta is not None:
                    entry['eta_ms'] = eta
            result[td['key']] = entry

        # GP Run: sum counts across ALL app sheets
        try:
            _wb_gp = _oxl.load_workbook(str(GP_ROOT / 'projects.xlsx'), read_only=True)
            _gp_all_apps = list(_wb_gp.sheetnames)
            _wb_gp.close()
        except Exception:
            _gp_all_apps = []
        _gp_totals = {'total': 0, 'running': 0, 'passed': 0, 'failed': 0, 'cancelled': 0, 'other': 0}
        for _app in _gp_all_apps:
            _c, _ = read_counts(GP_ROOT / 'projects.xlsx', _app, 'status', None, False)
            for _k in _gp_totals:
                _gp_totals[_k] += _c.get(_k, 0)
        result['gp-run'] = _gp_totals

        # jreg: sum counts across all app sheets (dynamic from projects.xlsx)
        try:
            _wb_apps = _oxl.load_workbook(str(JR_ROOT / 'projects.xlsx'), read_only=True)
            _jreg_all_apps = list(_wb_apps.sheetnames)
            _wb_apps.close()
        except Exception:
            _jreg_all_apps = []
        _jreg_totals = {'total': 0, 'running': 0, 'passed': 0, 'failed': 0, 'cancelled': 0, 'other': 0}
        for _app in _jreg_all_apps:
            _c, _ = read_counts(JR_ROOT / 'projects.xlsx', _app, 'status', None, False)
            for _k in _jreg_totals:
                _jreg_totals[_k] += _c.get(_k, 0)
        write_stats(JR_ROOT / 'stats', _jreg_totals)
        result['jreg'] = _jreg_totals

        # Baseline: sum counts across all app sheets (sheets named by app, e.g. "Payor")
        try:
            _wb_jb = _oxl.load_workbook(str(JB_ROOT / 'projects.xlsx'), read_only=True)
            _jb_all_apps = list(_wb_jb.sheetnames)
            _wb_jb.close()
        except Exception:
            _jb_all_apps = []
        _jb_totals = {'total': 0, 'running': 0, 'passed': 0, 'failed': 0, 'cancelled': 0, 'other': 0}
        for _app in _jb_all_apps:
            _c, _ = read_counts(JB_ROOT / 'projects.xlsx', _app, 'status', None, False)
            for _k in _jb_totals:
                _jb_totals[_k] += _c.get(_k, 0)
        write_stats(JB_ROOT / 'stats', _jb_totals)
        result['baseline'] = _jb_totals

        # JCJ: sum counts across all app sheets (same structure as baseline)
        try:
            _wb_jcj = _oxl.load_workbook(str(JCJ_ROOT / 'projects.xlsx'), read_only=True)
            _jcj_all_apps = list(_wb_jcj.sheetnames)
            _wb_jcj.close()
        except Exception:
            _jcj_all_apps = []
        _jcj_totals = {'total': 0, 'running': 0, 'passed': 0, 'failed': 0, 'cancelled': 0, 'other': 0}
        for _app in _jcj_all_apps:
            _c, _ = read_counts(JCJ_ROOT / 'projects.xlsx', _app, 'status', None, False)
            for _k in _jcj_totals:
                _jcj_totals[_k] += _c.get(_k, 0)
        result['jcj'] = _jcj_totals

        # Clone Workflow: "Payor" sheet with "status" column
        _cw_counts, _ = read_counts(PROJECTS, 'Payor', 'status', None, False)
        result['clone-workflow'] = _cw_counts

        return jsonify({'ok': True, 'stats': result})

    @app.route("/api/tools/<tool>/trigger", methods=["POST"])
    def api_tool_trigger(tool):
        if tool not in _TOOL_CMD:
            return jsonify({"ok": False, "error": "trigger not supported for this tool"}), 400
        data = request.get_json() or {}
        cmd  = ["cmd", "/c"] + _TOOL_CMD[tool](data)
        import subprocess
        try:
            if tool == "jreg":
                # Open a visible console so the user sees live progress and ETA
                flags = getattr(subprocess, "CREATE_NEW_CONSOLE", 0x00000010)
                proc  = subprocess.Popen(cmd, creationflags=flags)
            else:
                flags = 0
                if hasattr(subprocess, "DETACHED_PROCESS"):
                    flags = subprocess.DETACHED_PROCESS | subprocess.CREATE_NEW_PROCESS_GROUP
                proc = subprocess.Popen(
                    cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                    creationflags=flags,
                )
            return jsonify({"ok": True, "pid": proc.pid})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)}), 500

    @app.route("/api/tools/puc/config", methods=["GET"])
    def api_puc_get_config():
        import openpyxl as _xl
        cfg_path = PUC_ROOT / "puc_config.xlsx"
        config_row  = {}
        status_config = []
