    @app.route("/api/tools/puc/config", methods=["POST"])
    def api_puc_save_config():
        import openpyxl as _xl
        body = request.get_json() or {}
        cfg  = body.get("config", {})
        sc   = body.get("status_config", [])
        cfg_path = PUC_ROOT / "puc_config.xlsx"
        try:
            if cfg_path.exists():
                wb = _xl.load_workbook(str(cfg_path))
            else:
                wb = _xl.Workbook()
                if wb.active:
                    wb.active.title = "config"
            # Write config sheet (row 1 = headers, row 2 = values)
            if "config" not in wb.sheetnames:
                wb.create_sheet("config")
            ws = wb["config"]
            ws.delete_rows(1, ws.max_row)
            keys = list(cfg.keys())
            ws.append(keys)
            ws.append([cfg.get(k, "") for k in keys])
            # Write status_config sheet
            if "status_config" not in wb.sheetnames:
                wb.create_sheet("status_config")
            sc_ws = wb["status_config"]
            sc_ws.delete_rows(1, sc_ws.max_row)
            if sc:
                sc_keys = list(sc[0].keys())
                sc_ws.append(sc_keys)
                for row in sc:
                    sc_ws.append([row.get(k, "") for k in sc_keys])
            else:
                sc_ws.append(["status", "color"])
            wb.save(str(cfg_path))
            return jsonify({"ok": True})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    def _run_puc_bg(cmd):
        import subprocess as _sp
        _CREATE_NO_WINDOW = getattr(_sp, "CREATE_NO_WINDOW", 0x08000000)
        def _append(line):
            with _puc_op_lock:
                _puc_op["output"] += line
        try:
            proc = _sp.Popen(cmd, stdout=_sp.PIPE, stderr=_sp.STDOUT, text=True,
                             creationflags=_CREATE_NO_WINDOW)
            with _puc_op_lock:
                _puc_op["pid"] = proc.pid
            for line in iter(proc.stdout.readline, ""):
                if _puc_abort.is_set():
                    proc.kill()
                    _append("\n--- Aborted ---\n")
                    with _puc_op_lock:
                        _puc_op["status"] = "aborted"
                    return
                _append(line)
            proc.stdout.close()
            rc = proc.wait()
            with _puc_op_lock:
                if _puc_op["status"] == "running":
                    _puc_op["status"] = "success" if rc == 0 else "failed"
        except Exception as _e:
            _append(f"\nError: {_e}\n")
            with _puc_op_lock:
                if _puc_op["status"] == "running":
                    _puc_op["status"] = "failed"

    @app.route("/api/tools/puc/trigger", methods=["POST"])
    def api_puc_trigger():
        import openpyxl as _xl
        data = request.get_json() or {}
        version = (data.get("payor_version") or "").strip()
        if not version:
            return jsonify({"ok": False, "error": "payor_version is required"})
        with _puc_op_lock:
            if _puc_op["status"] == "running":
                return jsonify({"ok": False, "error": "A PUC run is already in progress"})
            _puc_op.update({"status": "running", "output": "", "pid": None})
        _puc_abort.clear()
        # Auto-derive Jenkins job URL from config
        baseline_url = (data.get("baseline_url") or "").strip()
        if not baseline_url:
            cfg_path = PUC_ROOT / "puc_config.xlsx"
            if cfg_path.exists():
                try:
                    cw = _xl.load_workbook(str(cfg_path))
                    if "config" in cw.sheetnames:
                        hdrs = [str(c.value or "").strip().lower()
                                for c in next(cw["config"].iter_rows(min_row=1, max_row=1))]
                        for r in cw["config"].iter_rows(min_row=2, values_only=True):
                            if r[0]:
                                rd = {k: (str(v).strip() if v is not None else "") for k, v in zip(hdrs, r)}
                                for _fld in ("jenkins_job_url", "jenkins_url", "puc_url", "job_url", "baseline_url_template"):
                                    if rd.get(_fld):
                                        baseline_url = rd[_fld].replace("{version}", version).rstrip("/")
                                        break
                                break
                except Exception:
                    pass
        cmd_data = {"payor_version": version}
        if baseline_url:
            cmd_data["baseline_url"] = baseline_url
        _puc_mode = (data.get("mode") or "").strip()
        if _puc_mode:
            cmd_data["mode"] = _puc_mode
        cmd = ["cmd", "/c"] + _TOOL_CMD["puc"](cmd_data)
        _threading.Thread(target=_run_puc_bg, args=(cmd,), daemon=True).start()
        return jsonify({"ok": True, "derived_url": baseline_url})

    @app.route("/api/tools/puc/op-status", methods=["GET"])
    def api_puc_op_status():
        with _puc_op_lock:
            return jsonify({"ok": True, "status": _puc_op["status"],
                            "output": _puc_op["output"], "pid": _puc_op["pid"]})

    @app.route("/api/tools/puc/op-abort", methods=["POST"])
    def api_puc_op_abort():
        with _puc_op_lock:
            if _puc_op["status"] != "running":
                return jsonify({"ok": False, "error": "No PUC run in progress"})
            _puc_op["output"] += "\n--- Abort requested ---\n"
            pid = _puc_op.get("pid")
        _puc_abort.set()
        if pid:
            import subprocess as _sp
            try: _sp.run(["taskkill", "/F", "/T", "/PID", str(pid)], capture_output=True)
            except Exception: pass
        return jsonify({"ok": True})

    def _puc_write_scheduler_setting(key, value):
        import openpyxl as _xl
        try:
            PUC_ROOT.mkdir(parents=True, exist_ok=True)
            _cfg = PUC_ROOT / "scheduler_config.xlsx"
            if _cfg.exists():
                _wb = _xl.load_workbook(str(_cfg))
                _ws = _wb.active
                for _r in _ws.iter_rows(min_row=2):
                    if _r[0].value and str(_r[0].value).strip().lower() == str(key).lower():
                        _r[1].value = value; break
                else:
                    _ws.append([key, value, ""])
                _wb.save(str(_cfg))
            else:
                _wb = _xl.Workbook(); _ws = _wb.active; _ws.title = "Config"
                _ws.append(["Key", "Value", "Notes"]); _ws.append([key, value, ""])
                _wb.save(str(_cfg))
        except Exception:
            pass

    @app.route("/api/tools/puc/scheduler-settings", methods=["GET"])
    def api_puc_get_scheduler_settings():
        import openpyxl as _xl
        settings = []
        _cfg = PUC_ROOT / "scheduler_config.xlsx"
        if _cfg.exists():
            try:
                _wb = _xl.load_workbook(str(_cfg), data_only=True)
                _ws = _wb.active
                _hdrs = [str(_ws.cell(1, c).value or "").strip().lower()
                         for c in range(1, _ws.max_column + 1)]
                _notes_col = _hdrs.index("notes") if "notes" in _hdrs else None
                for _r in _ws.iter_rows(min_row=2, values_only=True):
                    if not _r[0]:
                        continue
                    _k = str(_r[0]).strip()
                    _v = str(_r[1]).strip() if _r[1] is not None else ""
                    _n = str(_r[_notes_col]).strip() if (_notes_col is not None and _r[_notes_col]) else ""
                    settings.append({"key": _k, "value": _v, "notes": _n})
            except Exception:
                pass
        _DEFAULTS = [
            ("auto_refresh_interval", "0",  "Auto refresh interval in minutes (0 = off)"),
            ("max_poll_hours",        "48", "Mark stale runs after this many hours"),
            ("stale_threshold_hours", "48", "Startup recovery: ignore projects older than this"),
        ]
        _existing_keys = {s["key"].lower() for s in settings}
        for _dk, _dv, _dn in _DEFAULTS:
            if _dk.lower() not in _existing_keys:
                settings.append({"key": _dk, "value": _dv, "notes": _dn})
        return jsonify({"ok": True, "settings": settings})

    @app.route("/api/tools/puc/scheduler-settings", methods=["POST"])
    def api_puc_post_scheduler_settings():
        data = request.get_json() or {}
        updates = data.get("settings", {})
        if not isinstance(updates, dict):
            return jsonify({"ok": False, "error": "settings must be a key:value object"}), 400
        for _k, _v in updates.items():
            _puc_write_scheduler_setting(str(_k).strip(), str(_v).strip())
        return jsonify({"ok": True})

    @app.route("/api/tools/puc/projects", methods=["GET"])
    def api_puc_projects():
        import openpyxl as _xl
        path = PUC_DATA / "projects.xlsx"
        if not path.exists():
            return jsonify({"rows": [], "meta": {}})
        with _puc_projects_lock, _puc_projects_filelock():
            wb = _xl.load_workbook(str(path))
        ws   = wb.active
        hdrs = [str(ws.cell(1, c).value or "").strip().lower() for c in range(1, ws.max_column + 1)]
        rows = []
        for row in ws.iter_rows(min_row=2, values_only=True):
            if any(v is not None for v in row):
                d = {k: ("" if v is None else str(v)) for k, v in zip(hdrs, row)}
                if d.get("pid", "").strip():
                    rows.append(d)
        # Read config and status_config from puc_config.xlsx
        github_repo_url   = ""
        release_prefix    = ""
        jenkins_job_url   = ""
        status_config     = []
        cfg_path = PUC_ROOT / "puc_config.xlsx"
        if cfg_path.exists():
            cw = _xl.load_workbook(str(cfg_path))
            if "config" in cw.sheetnames:
                hdrs_cfg = [str(c.value or "").strip().lower()
                            for c in next(cw["config"].iter_rows(min_row=1, max_row=1))]
                for r in cw["config"].iter_rows(min_row=2, values_only=True):
                    if r[0]:
                        rd = {k: (str(v).strip() if v is not None else "") for k, v in zip(hdrs_cfg, r)}
                        github_repo_url = rd.get("github_repo_url", "").rstrip("/")
                        release_prefix  = rd.get("release_prefix", "")
                        # Accept any of these common field names for the Jenkins job URL template
                        for _fld in ("jenkins_job_url", "jenkins_url", "puc_url", "job_url", "baseline_url_template"):
                            if rd.get(_fld):
                                jenkins_job_url = rd[_fld].rstrip("/")
                                break
                        break
            if "status_config" in cw.sheetnames:
                sc_hdrs = [str(c.value or "").strip().lower()
                           for c in next(cw["status_config"].iter_rows(min_row=1, max_row=1))]
                for r in cw["status_config"].iter_rows(min_row=2, values_only=True):
                    if r[0] is not None:
                        rd = {k: (str(v).strip() if v is not None else "") for k, v in zip(sc_hdrs, r)}
                        if rd.get("status"):
                            status_config.append(rd)
        # Merge eta_cache
        import json  as _json_puc
        import time  as _time_puc
        eta_path = PUC_ROOT / "eta_cache.json"
        eta_cache = {}
        if eta_path.exists():
            try: eta_cache = _json_puc.loads(eta_path.read_text(encoding="utf-8"))
            except Exception: pass
        now_s = _time_puc.time()
        for row in rows:
            pid_key = str(row.get("pid", ""))
            timing  = eta_cache.get(pid_key, {})
            s_ms    = timing.get("start_ms")
            e_ms    = timing.get("est_ms")
            if s_ms and e_ms:
                end_s = (int(s_ms) + int(e_ms)) / 1000
                row["eta_seconds"] = int(end_s - now_s) if end_s > now_s else -int(now_s - end_s)
            else:
                row["eta_seconds"] = None

        return jsonify({"rows": rows, "meta": {
            "github_repo_url":  github_repo_url,
            "release_prefix":   release_prefix,
            "status_config":    status_config,
            "jenkins_job_url":  jenkins_job_url,
        }})

    @app.route("/api/tools/puc/projects/<pid>/baseline", methods=["PATCH"])
    def api_puc_update_baseline(pid):
        import openpyxl as _xl
        body = request.get_json() or {}
        baseline_url = (body.get("baseline_url") or "").strip()
        path = PUC_DATA / "projects.xlsx"
        if not path.exists():
            return jsonify({"ok": False, "error": "projects.xlsx not found"})
        try:
            with _puc_projects_lock, _puc_projects_filelock():
                wb = _xl.load_workbook(str(path))
                ws = wb.active
                hdrs = [str(ws.cell(1, c).value or "").strip().lower() for c in range(1, ws.max_column + 1)]
                pid_col       = hdrs.index("pid")          + 1 if "pid"          in hdrs else None
                baseline_col  = hdrs.index("baseline_url") + 1 if "baseline_url" in hdrs else None
                if pid_col is None:
                    return jsonify({"ok": False, "error": "pid column not found"})
                if baseline_col is None:
                    baseline_col = len(hdrs) + 1
                    ws.cell(1, baseline_col).value = "baseline_url"
                updated = False
                for row in ws.iter_rows(min_row=2):
                    if str(row[pid_col - 1].value or "").strip() == str(pid).strip():
                        row[baseline_col - 1].value = baseline_url
                        updated = True
                        break
                if not updated:
                    return jsonify({"ok": False, "error": f"Project {pid} not found"})
                wb.save(str(path))
            return jsonify({"ok": True, "baseline_url": baseline_url})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/tools/puc/projects/<pid>/status", methods=["GET"])
    def api_puc_project_status(pid):
        import sys as _sys
        _puc_scripts = str(PUC_ROOT / "scripts")
        if _puc_scripts not in _sys.path:
            _sys.path.insert(0, _puc_scripts)
        import puc_status as _puc

        rows = _puc._load_projects()
        row  = next((r for r in rows if r.get("pid", "") == str(pid)), None)
        if row is None:
            return jsonify({"ok": False, "error": "project not found"}), 404

        secrets   = _puc.load_secrets()
        username  = secrets.get("jenkins_username", "")
        password  = secrets.get("jenkins_password", "") or secrets.get("jenkins_api_token", "")
        auth      = (username, password) if username and password else None

        status    = row.get("status", "")
        build_url = row.get("build_url", "")
        queue_url = row.get("queue_url", "")

        if not build_url and queue_url and auth:
            resolved = _puc._resolve_queue_item(queue_url, auth)
            if resolved:
                build_url = resolved

        import time as _time_puc2
        eta_seconds = None
        if build_url and auth:
            info = _puc._poll_build_info(build_url, auth)
            if info.get("status"):
                status = info["status"]
                _puc._update_project(pid, status, build_url)
            s_ms = info.get("start_ms")
            e_ms = info.get("est_ms")
            if s_ms:
                cache = _puc._load_eta_cache()
                cache[str(pid)] = {"start_ms": s_ms, "est_ms": e_ms or 0}
                _puc._save_eta_cache(cache)
                if e_ms:
                    end_s = (int(s_ms) + int(e_ms)) / 1000
                    now_s = _time_puc2.time()
                    eta_seconds = int(end_s - now_s) if end_s > now_s else -int(now_s - end_s)
            elif not info:
                # build_url query failed — try eta from cache
                cache  = _puc._load_eta_cache()
                timing = cache.get(str(pid), {})
                s_ms2  = timing.get("start_ms")
                e_ms2  = timing.get("est_ms")
                if s_ms2 and e_ms2:
                    end_s = (int(s_ms2) + int(e_ms2)) / 1000
                    now_s = _time_puc2.time()
                    eta_seconds = int(end_s - now_s) if end_s > now_s else -int(now_s - end_s)

        return jsonify({"ok": True, "pid": pid, "status": status, "build_url": build_url, "eta_seconds": eta_seconds})

