    # ── Help: Wishlist (features) & Bugs, backed by Help/features_and_bugs.xlsx ──
    _HELP_KINDS = {
        "features": {"sheet": "features", "statuses": ("requested", "implemented")},
        "bugs":     {"sheet": "bugs",     "statuses": ("filed", "fixed")},
    }
    _HELP_COLS = ["id", "title", "description", "status", "created", "updated", "pushed"]
    _help_lock = _threading.Lock()

    def _help_load():
        import openpyxl as _xl
        path = HELP_ROOT / "features_and_bugs.xlsx"
        if path.exists():
            wb = _xl.load_workbook(str(path))
        else:
            wb = _xl.Workbook()
            wb.remove(wb.active)
        for k in _HELP_KINDS.values():
            if k["sheet"] not in wb.sheetnames:
                wb.create_sheet(k["sheet"]).append(_HELP_COLS)
            elif wb[k["sheet"]].cell(1, 7).value != "pushed":
                wb[k["sheet"]].cell(1, 7).value = "pushed"
        return wb, path

    def _help_rows(ws):
        out = []
        for r in ws.iter_rows(min_row=2, values_only=True):
            if r and r[0]:
                out.append({c: ("" if v is None else str(v)) for c, v in zip(_HELP_COLS, r)})
        return out

    def _help_save(wb, path):
        HELP_ROOT.mkdir(parents=True, exist_ok=True)
        wb.save(str(path))

    @app.route("/api/help/<kind>", methods=["GET", "POST"])
    def api_help_items(kind):
        import uuid as _uuid_h, datetime as _dt_h
        cfg = _HELP_KINDS.get(kind)
        if not cfg:
            return jsonify({"ok": False, "error": "Unknown kind"}), 404
        if request.method == "GET":
            _help_sweep_jobs()     # finalise AI runs that finished meanwhile so their item shows Implemented / Fixed right away
        with _help_lock:
            wb, path = _help_load()
            ws = wb[cfg["sheet"]]
            if request.method == "GET":
                # One-time: sheets from before "newest first" are oldest-first; reorder them once by created (desc)
                cws = _help_cfg_sheet(wb)
                flag = "order_newest_first_" + kind
                if _help_cfg_get(cws, flag) != "1":
                    rows_ = [[c.value for c in r] for r in ws.iter_rows(min_row=2, max_col=len(_HELP_COLS)) if r[0].value]
                    rows_.sort(key=lambda v: str(v[4] or ""), reverse=True)
                    for ri_, vals_ in enumerate(rows_, start=2):
                        for ci_, v_ in enumerate(vals_, start=1):
                            ws.cell(row=ri_, column=ci_).value = v_
                    _help_cfg_set(cws, flag, "1")
                    try: _help_save(wb, path)
                    except PermissionError: pass
                return jsonify({"ok": True, "items": _help_rows(ws)})
            body  = request.get_json(silent=True) or {}
            title = str(body.get("title", "")).strip()
            if not title:
                return jsonify({"ok": False, "error": "Title is required"}), 400
            now  = _dt_h.datetime.now().strftime("%Y-%m-%d %H:%M")
            item = {"id": _uuid_h.uuid4().hex[:8], "title": title,
                    "description": str(body.get("description", "")).strip(),
                    "status": cfg["statuses"][0], "created": now, "updated": now, "pushed": ""}
            ws.insert_rows(2)      # newest first; manual up/down moves still reorder rows
            for ci_, c_ in enumerate(_HELP_COLS, start=1):
                ws.cell(row=2, column=ci_).value = item.get(c_, "")
            try:
                _help_save(wb, path)
            except PermissionError:
                return jsonify({"ok": False, "error": "features_and_bugs.xlsx is open — close it and retry"}), 500
            return jsonify({"ok": True, "item": item})

    @app.route("/api/help/<kind>/<item_id>", methods=["PUT", "DELETE"])
    def api_help_item(kind, item_id):
        import datetime as _dt_h
        cfg = _HELP_KINDS.get(kind)
        if not cfg:
            return jsonify({"ok": False, "error": "Unknown kind"}), 404
        with _help_lock:
            wb, path = _help_load()
            ws = wb[cfg["sheet"]]
            row = next((r for r in ws.iter_rows(min_row=2) if str(r[0].value or "") == item_id), None)
            if row is None:
                return jsonify({"ok": False, "error": "Not found"}), 404
            if request.method == "DELETE":
                ws.delete_rows(row[0].row)
                item = None
            else:
                body = request.get_json(silent=True) or {}
                if "title" in body:
                    t = str(body["title"]).strip()
                    if not t:
                        return jsonify({"ok": False, "error": "Title is required"}), 400
                    row[1].value = t
                if "description" in body:
                    row[2].value = str(body["description"]).strip()
                if "status" in body:
                    if body["status"] not in cfg["statuses"]:
                        return jsonify({"ok": False, "error": "Invalid status"}), 400
                    row[3].value = body["status"]
                row[5].value = _dt_h.datetime.now().strftime("%Y-%m-%d %H:%M")
                item = {c: ("" if cell.value is None else str(cell.value)) for c, cell in zip(_HELP_COLS, row)}
            try:
                _help_save(wb, path)
            except PermissionError:
                return jsonify({"ok": False, "error": "features_and_bugs.xlsx is open — close it and retry"}), 500
            return jsonify({"ok": True, "item": item})

