    @app.route("/api/tools/rpb/projects/<int:pid>", methods=["PATCH"])
    def api_rpb_patch(pid):
        import openpyxl as _xl
        data = request.get_json() or {}
        if "payor_urls" in data:
            # Look up payor_version from projects.xlsx for the filename
            path = RPB_DATA / "projects.xlsx"
            _patch_app = str(data.get("app", "Payor") or "Payor").strip()
            version = str(pid)
            if path.exists():
                with _rpb_projects_lock, _rpb_projects_filelock():
                    wb  = _xl.load_workbook(str(path))
                    ws  = wb[_patch_app] if _patch_app in wb.sheetnames else wb.active
                    hdrs = [str(ws.cell(1, c).value or "").strip().lower()
                            for c in range(1, ws.max_column + 1)]
                    ver_col = hdrs.index("payor_version") + 1 if "payor_version" in hdrs else None
                    for row in ws.iter_rows(min_row=2, values_only=True):
                        if str(row[0] or "").strip() == str(pid):
                            if ver_col:
                                version = str(row[ver_col - 1] or "").strip()
                            break
            _rpb_write_urls(pid, version, data["payor_urls"], _patch_app)
        return jsonify({"ok": True})

