    @app.route("/api/local-app/payor/current-branch", methods=["GET"])
    def api_local_app_payor_current_branch():
        force = request.args.get("force", "").lower() in ("1", "true", "yes")
        if not force:
            cached = _lb_cache_get("payor")
            if cached is not None:
                return jsonify(cached)
        script = PAYOR_SCRIPTS / "get_current_payor_branch.py"
        if not script.exists():
            return jsonify({"ok": False, "error": "get_current_payor_branch.py not found"})
        try:
            _cflags = 0x08000000 if sys.platform == "win32" else 0  # CREATE_NO_WINDOW
            r = subprocess.run(
                [sys.executable, str(script), "--json"],
                capture_output=True, text=True, timeout=15,
                creationflags=_cflags,
            )
            if r.returncode != 0:
                return jsonify({"ok": False, "error": r.stderr.strip() or "Script error"})
            import json as _json
            data = _json.loads(r.stdout.strip())
            data["ok"] = True
            _lb_cache_set("payor", data)
            return jsonify(data)
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

