    def _payor_srcdir():
        """Return (branch, srcdir) derived from ~/.default-branch."""
        import os as _os
        default_branch_file = Path.home() / ".default-branch"
        branch = default_branch_file.read_text(errors="replace").strip() if default_branch_file.exists() else ""
        git_home   = _os.environ.get("GIT_HOME", "").strip()
        repo_payor = _os.environ.get("REPO_PAYOR", "hrp.payer.core").strip()
        srcdir = str(Path(git_home) / f"{repo_payor}-{branch}") if branch and git_home else ""
        return branch, srcdir

    def _read_local_tool(key):
        """Read a tool path from Local_Build_And_Deployment/Applications/Payor/app_config.xlsx 'Local Tools' sheet."""
        cfg = PAYOR_ROOT / "app_config.xlsx"
        if not cfg.exists():
            return ""
        try:
            import openpyxl as _xl
            wb = _xl.load_workbook(str(cfg))
            if "Local Tools" not in wb.sheetnames:
                return ""
            ws = wb["Local Tools"]
            for row in ws.iter_rows(min_row=2, values_only=True):
                if row[0] and str(row[0]).strip() == key and row[1]:
                    return str(row[1]).strip()
        except Exception:
            pass
        return ""

    @app.route("/api/local-app/payor/open-ide", methods=["POST"])
    def api_local_app_payor_open_ide():
        import glob as _glob, shutil as _shutil
        _, srcdir = _payor_srcdir()
        if not srcdir or not Path(srcdir).exists():
            return jsonify({"ok": False, "error": f"Clone directory not found: {srcdir}"})
        # 1. Check app_config.xlsx Local Tools sheet
        idea_exe = _read_local_tool("intellij_exe")
        # 2. PATH
        if not idea_exe or not Path(idea_exe).exists():
            idea_exe = _shutil.which("idea64") or _shutil.which("idea") or ""
        # 3. Program Files (x86) then Program Files
        if not idea_exe or not Path(idea_exe).exists():
            for pf in [r"C:\Program Files (x86)\JetBrains", r"C:\Program Files\JetBrains"]:
                matches = sorted(_glob.glob(pf + r"\IntelliJ IDEA*\bin\idea64.exe"))
                if matches:
                    idea_exe = matches[-1]
                    break
        if not idea_exe or not Path(idea_exe).exists():
            return jsonify({"ok": False, "error": "IntelliJ IDEA not found. Add intellij_exe to Local_Build_And_Deployment/Applications/Payor/app_config.xlsx 'Local Tools' sheet."})
        try:
            subprocess.Popen([idea_exe, srcdir], creationflags=0x08000000)
            return jsonify({"ok": True})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/local-app/payor/open-terminal", methods=["POST"])
    def api_local_app_payor_open_terminal():
        branch, srcdir = _payor_srcdir()
        if not srcdir or not Path(srcdir).exists():
            return jsonify({"ok": False, "error": f"Clone directory not found: {srcdir}"})
        try:
            # Open a new PowerShell window in the clone directory
            subprocess.Popen(
                ["cmd.exe", "/c", "start", "powershell.exe", "-NoExit",
                 "-Command", f"Set-Location '{srcdir}'"],
                creationflags=0x08000000,
            )
            return jsonify({"ok": True})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/local-app/payor/build", methods=["POST"])
    def api_local_app_payor_build():
        import time as _time
        body        = request.get_json() or {}
        flags       = [f for f in (body.get("flags") or []) if str(f).startswith("-")]
        resume_from = (body.get("resume_from") or "").strip()
        max_retries = max(0, int(body.get("max_retries") or 5))
        p1_key, p2_key = _split_params_keys(flags)
        _, srcdir   = _payor_srcdir()
        if not srcdir or not Path(srcdir).exists():
            return jsonify({"ok": False, "error": f"Clone directory not found: {srcdir}"})

        p1_estimate  = _get_build_estimate("full_build", p1_key)
        p2_estimate  = _get_build_estimate("full_deploy", p2_key)
        total_est    = (p1_estimate or 0) + (p2_estimate or 0) or None

        mod_result  = _list_payor_modules(srcdir)
        known_names = set(
            m["name"] for m in (mod_result.get("ready") or []) +
                                (mod_result.get("needs_build") or [])
        )

        # Determine initial phase based on flags
        if "-os" in flags:
            initial_phase = "bootstrapping"
        elif "-nbld" in flags:
            initial_phase = "deploying"
        else:
            initial_phase = "building"

        with _payor_build_lock:
            if _payor_build["status"] == "running":
                return jsonify({"ok": False, "error": "A build is already running"}), 409
            resume_offset = 0
            if resume_from and _payor_build.get("failed_at_module_num"):
                resume_offset = max(0, (_payor_build["failed_at_module_num"] or 1) - 1)
            _payor_build.update({
                "status":               "running",
                "output":               "",
                "proc":                 None,
                "start_ms":             int(_time.time() * 1000),
                "estimated_ms":         total_est,
                "phase":                initial_phase,
                "phase1_end_ms":        None,
                "phase1_estimate_ms":   p1_estimate,
                "phase2_estimate_ms":   p2_estimate,
                "current_module":       None,
                "module_num":           resume_offset if resume_offset else None,
                "total_modules":        len(known_names) if known_names else None,
                "failed_module":        None,
                "failed_at_module_num": None,
                "known_modules":        known_names,
                "retry_count":          0,
                "max_retries":          max_retries,
            })
        _kill_payor_java_processes(srcdir)
        cmd_flags = []
        for f in flags:
            cmd_flags.append(f)
            if f == "-rf" and resume_from:
                cmd_flags.append(f":{resume_from}")
        cmd_parts = ["refresh-payor"] + cmd_flags
        _threading.Thread(
            target=_run_payor_build_local_guarded,
            args=(srcdir, cmd_parts, p1_key, p2_key),
            kwargs={"base_flags": flags, "max_retries": max_retries},
            daemon=True,
        ).start()
        return jsonify({"ok": True, "estimated_ms": total_est})

    @app.route("/api/local-app/payor/build-status", methods=["GET"])
    def api_local_app_payor_build_status():
        import time as _time
        with _payor_build_lock:
            status         = _payor_build["status"]
            output         = _payor_build["output"]
            start_ms       = _payor_build["start_ms"]
            estimated_ms   = _payor_build["estimated_ms"]
            current_module = _payor_build.get("current_module")
            module_num     = _payor_build.get("module_num")
            total_modules  = _payor_build.get("total_modules")
            failed_module  = _payor_build.get("failed_module")
            phase          = _payor_build.get("phase")
            retry_count    = _payor_build.get("retry_count", 0)
            max_retries    = _payor_build.get("max_retries", 5)
        elapsed_ms = (int(_time.time() * 1000) - start_ms) if start_ms else 0
        if status == "running" and estimated_ms:
            progress = min(int(elapsed_ms / estimated_ms * 100), 95)
        elif status == "success":
            progress = 100
        else:
            progress = None
        return jsonify({
            "status":         status,
            "output":         output,
            "elapsed_ms":     elapsed_ms,
            "estimated_ms":   estimated_ms,
            "progress":       progress,
            "current_module": current_module,
            "module_num":     module_num,
            "total_modules":  total_modules,
            "failed_module":  failed_module,
            "phase":          phase,
            "retry_count":    retry_count,
            "max_retries":    max_retries,
        })

    @app.route("/api/local-app/payor/abort-build", methods=["POST"])
    def api_local_app_payor_abort_build():
        _, srcdir = _payor_srcdir()
        with _payor_build_lock:
            if _payor_build["status"] != "running":
                return jsonify({"ok": False, "error": "No build running"}), 400
            _payor_build["status"] = "aborted"
            proc = _payor_build.get("proc")
        if proc:
            try:
                subprocess.run(["taskkill", "/F", "/T", "/PID", str(proc.pid)],
                               capture_output=True, creationflags=0x08000000)
            except Exception:
                try: proc.kill()
                except Exception: pass
        # Kill any orphaned JVMs that taskkill may have missed — they hold file locks
        _kill_payor_java_processes(srcdir)
        _restore_cfgviewer_pom(srcdir)
        return jsonify({"ok": True})

