    @app.route("/api/local-app/payor/artemis/queues", methods=["GET"])
    def api_local_app_payor_artemis_queues():
        # Artemis binds its web console to localhost inside the container, so
        # direct host→container HTTP is blocked. Run curl inside the container instead.
        import json as _json, re as _re2
        container = _get_payor_container()
        if not container:
            return jsonify({"ok": False, "error": "Payor container not running"})
        JOLOKIA = "http://localhost:8161/console/jolokia"
        AUTH    = "admin:admin"
        ORIGIN  = "http://localhost:8161"
        try:
            # Step 1: search for queue MBeans
            r1 = subprocess.run(
                ["docker", "exec", container, "curl", "-s",
                 "-u", AUTH, "-H", f"Origin: {ORIGIN}",
                 f"{JOLOKIA}/search/org.apache.activemq.artemis:*,subcomponent=queues"],
                capture_output=True, text=True, timeout=10,
                creationflags=0x08000000,
            )
            mbeans = _json.loads(r1.stdout).get("value") or []
            if not mbeans:
                return jsonify({"ok": True, "queues": []})

            # Step 2: bulk POST to read MessageCount, MessagesAdded, ConsumerCount
            bulk = [
                {"type": "read", "mbean": mb,
                 "attribute": ["MessageCount", "MessagesAdded", "ConsumerCount"]}
                for mb in mbeans
            ]
            r2 = subprocess.run(
                ["docker", "exec", container, "curl", "-s",
                 "-u", AUTH, "-H", f"Origin: {ORIGIN}",
                 "-H", "Content-Type: application/json",
                 "-X", "POST", "-d", _json.dumps(bulk), JOLOKIA],
                capture_output=True, text=True, timeout=20,
                creationflags=0x08000000,
            )
            results = _json.loads(r2.stdout)

            queues = []
            for entry in (results if isinstance(results, list) else [results]):
                if entry.get("status") != 200:
                    continue
                mb  = entry.get("request", {}).get("mbean", "")
                val = entry.get("value") or {}
                m   = _re2.search(r'queue="([^"]+)"', mb)
                name = m.group(1) if m else mb
                queues.append({
                    "name":          name,
                    "messageCount":  val.get("MessageCount", 0),
                    "messagesAdded": val.get("MessagesAdded", 0),
                    "consumerCount": val.get("ConsumerCount", 0),
                })
            queues.sort(key=lambda q: q["name"].lower())
            return jsonify({"ok": True, "queues": queues})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

