    def _ldap_rows_from_text(txt):
        """Connection rows for the providers listed in AUTHENTICATION_PROVIDERS of a properties text."""
        import re as _r
        glob, secs = _ldap_parse_props(txt)
        sl = {k.lower(): k for k in secs}
        rows = []
        for sec in [x.strip() for x in glob.get("AUTHENTICATION_PROVIDERS", "").split(",") if x.strip()]:
            if sec.lower() not in sl: continue
            sec = sl[sec.lower()]; kv = secs[sec]
            ad = "activedirectory" in kv.get("AuthenticatorProviderType", "").lower() or sec.lower().endswith("-ad") or kv.get("UserObjectClass", "").lower() == "user"
            dn = kv.get("UserBaseDn") or kv.get("GroupBaseDn") or ""
            dcs = _r.findall(r"(?i)dc=[^,]+", dn)
            rows.append({"name": kv.get("Name") or sec, "enabled": True, "provider": "activedirectory" if ad else "openldap", "host": kv.get("Host", "localhost"), "port": kv.get("Port", "389"),
                         "username": kv.get("Principal", ""), "secret": kv.get("Credential", ""), "scope": ",".join(dcs) if dcs else dn,
                         "options": ("ssl=true;" if kv.get("SSLEnabled", "").lower() == "true" else "") + "section=" + sec,
                         "settings": "\n".join("%s=%s" % (k, v) for k, v in kv.items() if k != "Credential")})
        return rows

    def _ldap_parse_props(text):
        """Parse the authentication provider properties ([section]Key=Value or [section]_Key=Value) into {section: {key: value}}."""
        import re as _r
        glob, secs = {}, {}
        for ln in text.splitlines():
            ln = ln.strip()
            if not ln or ln.startswith("#"): continue
            m = _r.match(r"\[([^\]]+)\]_?([A-Za-z0-9_.]+)\s*=\s*(.*)$", ln)
            if m: secs.setdefault(m.group(1), {})[m.group(2)] = m.group(3).strip(); continue
            m = _r.match(r"([A-Za-z0-9_.]+)\s*=\s*(.*)$", ln)
            if m: glob[m.group(1)] = m.group(2).strip()
        return glob, secs

    @app.route("/api/local-app/<app_name>/svc/ldap/import", methods=["POST"])
    def api_ldap_import(app_name):
        """Read the AD / OpenLDAP authentication providers from the properties file inside the container and save them to ldap_config.xlsx."""
        import re as _r
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS: return jsonify({"ok": False, "error": "Unknown app"}), 404
        c = _appmap_container_name(app_name)
        jb = request.get_json(silent=True) or {}
        if not c and not str(jb.get("text", "")).strip(): return jsonify({"ok": False, "error": "Container is not configured / running"})
        path = str(jb.get("path", "")).strip()
        pasted = str(jb.get("text", "")).strip()
        if path and not _r.fullmatch(r"/[A-Za-z0-9_./-]+", path): return jsonify({"ok": False, "error": "Invalid file path"})
        if not path and not pasted:
            ok, o = _appmap_dk(["exec", "-u", "root", c, "sh", "-c",
                                "for d in /home/weblogic/domains /home/weblogic; do find $d -maxdepth 5 -type f \\( -name '*.properties' -o -name '*.cfg' -o -name '*.conf' \\) 2>/dev/null "
                                "| xargs grep -l 'AUTHENTICATION_PROVIDERS' 2>/dev/null | head -5; done"], timeout=90)
            found = [x for x in (o.splitlines() if ok else []) if x.startswith("/")]
            if not found: return jsonify({"ok": False, "error": "No file containing AUTHENTICATION_PROVIDERS was found in the container - enter its path"})
            path = found[0]
        if pasted:
            txt, path = pasted, "(pasted text)"
        else:
            ok, txt = _appmap_dk(["exec", "-u", "root", c, "cat", path], timeout=30)
            if not ok: return jsonify({"ok": False, "error": txt})
        glob, secs = _ldap_parse_props(txt)
        wanted = [x.strip() for x in glob.get("AUTHENTICATION_PROVIDERS", "").split(",") if x.strip()]
        rows = _svc_load(app_name, "ldap")
        byname = {r["name"]: r for r in rows}
        imported = []
        for row in _ldap_rows_from_text(txt):
            if row["name"] in byname: rows[rows.index(byname[row["name"]])] = row
            else: rows.append(row)
            imported.append(row["name"])
        if not imported: return jsonify({"ok": False, "error": "%s has no [section] entries for: %s" % (path, ", ".join(wanted) or "(no providers listed)")})
        _svc_save(app_name, "ldap", rows)
        return jsonify({"ok": True, "file": path, "imported": imported})

    def _ldap_do(sk, f, mid, op, resp_tag):
        sk.sendall(_tlv(0x30, _b_int(mid) + op))
        while True:
            _, body = _ber_read(f)
            for t, v in _ber_items(body):
                if t == resp_tag:
                    it = _ber_items(v)
                    return int.from_bytes(it[0][1], "big"), (it[2][1].decode("utf-8", "replace") if len(it) > 2 else "")

    def _ldap_attr(name, vals):
        vals = vals if isinstance(vals, list) else [vals]
        return _tlv(0x30, _b_str(name) + _tlv(0x31, b"".join(_b_str(v) for v in vals)))

    def _ldap_manage(sk, f, c, act, b):
        ssl = "ssl=true" in c["options"].lower().replace(" ", "")
        ad = c["provider"].lower() == "activedirectory"
        base = c["scope"].strip().lower()
        dn = str(b.get("dn", "")).strip()
        if not dn: return {"ok": False, "error": "A DN is required"}
        if base and not dn.lower().endswith(base): return {"ok": False, "error": "DN must be inside the configured base DN (%s)" % c["scope"]}
        def chk(code, msg):
            if code != 0:
                hint = {50: " (insufficient access - the bind account needs write permission)", 68: " (entry already exists)", 32: " (no such object)", 53: " (server unwilling - AD needs LDAPS to set passwords)",
                        19: " (constraint violation)", 65: " (object class violation - a required attribute is missing)", 66: " (not allowed on non-leaf)"}.get(code, "")
                raise IOError("LDAP error %d%s: %s" % (code, hint, msg))
        def modify(changes):
            ops = b"".join(_tlv(0x30, _tlv(0x0a, bytes([{"add": 0, "delete": 1, "replace": 2}[ch["op"]]])) + _ldap_attr(ch["attr"], ch.get("values", []))) for ch in changes)
            chk(*_ldap_do(sk, f, 20, _tlv(0x66, _b_str(dn) + _tlv(0x30, ops)), 0x67))
        if act == "add":
            attrs = {k: v for k, v in (b.get("attrs") or {}).items() if v not in ("", [], None)}
            chk(*_ldap_do(sk, f, 21, _tlv(0x68, _b_str(dn) + _tlv(0x30, b"".join(_ldap_attr(k, v if isinstance(v, list) else [str(v)]) for k, v in attrs.items()))), 0x69))
            return {"ok": True, "message": "Created " + dn}
        if act == "modify":
            ch = [{"op": x.get("op", "replace"), "attr": x["attr"], "values": [str(v) for v in (x.get("values") or [])]} for x in (b.get("changes") or [])]
            if not ch: return {"ok": False, "error": "Nothing to change"}
            modify(ch)
            return {"ok": True, "message": "Updated " + dn}
        if act == "delete":
            chk(*_ldap_do(sk, f, 22, _tlv(0x4a, dn.encode("utf-8")), 0x6b))
            return {"ok": True, "message": "Deleted " + dn}
        if act == "password":
            pw = str(b.get("password", ""))
            if not pw: return {"ok": False, "error": "Password is empty"}
            if ad:
                if not ssl: return {"ok": False, "error": "Active Directory only accepts password changes over LDAPS - set Options to ssl=true and the port to 636"}
                modify([{"op": "replace", "attr": "unicodePwd", "values": [('"%s"' % pw).encode("utf-16-le")]}])
            else:
                modify([{"op": "replace", "attr": "userPassword", "values": [pw]}])
            return {"ok": True, "message": "Password changed for " + dn}
        if act in ("enable", "disable"):
            if not ad: return {"ok": False, "error": "Enable/disable applies to Active Directory accounts"}
            modify([{"op": "replace", "attr": "userAccountControl", "values": ["512" if act == "enable" else "514"]}])
            return {"ok": True, "message": ("Enabled " if act == "enable" else "Disabled ") + dn}
        return {"ok": False, "error": "Unsupported action"}

    @app.route("/api/local-app/<app_name>/svc/<kind>/action", methods=["POST"])
    def api_svc_action(app_name, kind):
        import time as _t, json as _js, re as _r
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS or kind not in _SVC: return jsonify({"ok": False, "error": "Unknown"}), 404
        b = request.get_json(silent=True) or {}
        c = next((x for x in _svc_load(app_name, kind) if x["name"] == b.get("name")), None)
        if not c: return jsonify({"ok": False, "error": "Unknown connection"})
        act = b.get("action", "test")
        c["_container"] = _appmap_container_name(app_name)
        t0 = _t.time()
        try:
            if kind == "cache":
                prov = c["provider"].lower()
                if prov == "he-blob":
                    return _heblob_action(c, act, b, t0)
                if prov == "redis":
                    sk = _redis_open(c)
                    try:
                        if act == "test":
                            _resp_cmd(sk, "PING")
                            ver = _r.search(r"redis_version:(\S+)", _resp_cmd(sk, "INFO", "server") or "")
                            return jsonify({"ok": True, "message": "Connected - Redis %s, %d keys, %d ms" % (ver.group(1) if ver else "?", _resp_cmd(sk, "DBSIZE"), (_t.time() - t0) * 1000)})
                        if act == "info":
                            return jsonify({"ok": True, "text": (_resp_cmd(sk, "INFO") or "")[:20000]})
                        if act == "keys":
                            cur, keys, pat = "0", [], str(b.get("pattern") or "*")
                            for _ in range(200):
                                r = _resp_cmd(sk, "SCAN", cur, "MATCH", pat, "COUNT", 500)
                                cur = str(r[0]); keys += r[1]
                                if cur == "0" or len(keys) >= 300: break
                            keys = keys[:300]
                            rows = [{"key": k, "type": _resp_cmd(sk, "TYPE", k), "ttl": _resp_cmd(sk, "TTL", k)} for k in keys]
                            return jsonify({"ok": True, "rows": rows})
                        if act == "get":
                            k = str(b.get("key", "")); ty = _resp_cmd(sk, "TYPE", k)
                            v = {"string": lambda: _resp_cmd(sk, "GET", k), "hash": lambda: _resp_cmd(sk, "HGETALL", k), "list": lambda: _resp_cmd(sk, "LRANGE", k, 0, 99),
                                 "set": lambda: _resp_cmd(sk, "SMEMBERS", k), "zset": lambda: _resp_cmd(sk, "ZRANGE", k, 0, 99, "WITHSCORES")}.get(ty, lambda: None)()
                            return jsonify({"ok": True, "type": ty, "value": v if isinstance(v, str) else _js.dumps(v, indent=1)[:50000]})
                    finally:
                        sk.close()
                elif prov == "memcached":
                    sk = _svc_sock(c); sk.sendall(b"stats\r\n"); buf = b""
                    while not buf.endswith(b"END\r\n"):
                        d = sk.recv(4096)
                        if not d: break
                        buf += d
                    sk.close()
                    txt = buf.decode("utf-8", "replace")
                    if act == "info": return jsonify({"ok": True, "text": txt})
                    if act == "test": return jsonify({"ok": True, "message": "Connected - memcached, %d ms" % ((_t.time() - t0) * 1000)})
                    return jsonify({"ok": False, "error": "memcached cannot list keys"})
                else:
                    sk = _svc_sock(c); sk.close()
                    if act == "test": return jsonify({"ok": True, "message": "TCP port is open (%d ms). Only a connection check is available for provider '%s'." % ((_t.time() - t0) * 1000, prov)})
                    return jsonify({"ok": False, "error": "Browsing is not available for provider '%s'" % prov})
            if kind == "ldap":
                sk, f = _ldap_open(c)
                try:
                    if act == "test":
                        ents, code = _ldap_search(sk, f, c["scope"], "(objectClass=*)", 0, 1)
                        return jsonify({"ok": True, "message": "Bind OK as %s, base %s %s (%d ms)" % (c["username"] or "anonymous", c["scope"], "readable" if code == 0 else "result code %d" % code, (_t.time() - t0) * 1000)})
                    if act in ("add", "modify", "delete", "password", "enable", "disable"):
                        return jsonify(_ldap_manage(sk, f, c, act, b))
                    base = str(b.get("base") or c["scope"])
                    ents, code = _ldap_search(sk, f, base, str(b.get("filter") or "(objectClass=*)"), {"base": 0, "one": 1, "sub": 2}.get(b.get("scope"), 2), 200)
                    return jsonify({"ok": True, "entries": ents[:200], "code": code})
                finally:
                    sk.close()
            if kind == "vault":
                import requests as _rq
                opt = dict(x.split("=", 1) for x in c["options"].replace(" ", "").split(";") if "=" in x)
                scheme = "https" if (opt.get("https") == "true" or c["port"] == "443") else "http"
                url = "%s://%s:%s" % (scheme, c["host"], c["port"])
                hd = {"X-Vault-Token": c["secret"]}
                if opt.get("namespace"): hd["X-Vault-Namespace"] = opt["namespace"]
                kv2 = opt.get("kv", "2") != "1"
                mount, path = c["scope"].strip("/"), str(b.get("path", "")).strip("/")
                if act == "test":
                    r = _rq.get(url + "/v1/sys/health?standbyok=true&sealedcode=200&uninitcode=200", headers=hd, timeout=6, verify=False).json()
                    ta = _rq.get(url + "/v1/auth/token/lookup-self", headers=hd, timeout=6, verify=False)
                    return jsonify({"ok": True, "message": "Vault %s - %s, %s (%d ms)" % (r.get("version", "?"), "SEALED" if r.get("sealed") else "unsealed",
                                    "token valid" if ta.status_code == 200 else "token rejected (HTTP %d)" % ta.status_code, (_t.time() - t0) * 1000)})
                if act == "list":
                    u = "%s/v1/%s/%s/%s" % (url, mount, "metadata" if kv2 else "", path) if kv2 else "%s/v1/%s/%s" % (url, mount, path)
                    r = _rq.request("LIST", u.rstrip("/"), headers=hd, timeout=8, verify=False)
                    if r.status_code == 404: return jsonify({"ok": True, "keys": []})
                    if r.status_code != 200: return jsonify({"ok": False, "error": "HTTP %d: %s" % (r.status_code, r.text[:300])})
                    return jsonify({"ok": True, "keys": r.json().get("data", {}).get("keys", [])})
                if act == "read":
                    u = "%s/v1/%s/%s/%s" % (url, mount, "data", path) if kv2 else "%s/v1/%s/%s" % (url, mount, path)
                    r = _rq.get(u, headers=hd, timeout=8, verify=False)
                    if r.status_code != 200: return jsonify({"ok": False, "error": "HTTP %d: %s" % (r.status_code, r.text[:300])})
                    d = r.json().get("data", {})
                    return jsonify({"ok": True, "data": d.get("data", d) if kv2 else d, "meta": d.get("metadata") if kv2 else None})
            return jsonify({"ok": False, "error": "Unsupported action"})
        except Exception as e:
            return jsonify({"ok": False, "error": "%s: %s" % (type(e).__name__, e)})

    @app.route("/api/local-app/<app_name>/appmap/settings", methods=["GET", "POST"])
    def api_appmap_settings(app_name):
        import json as _js_as
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": "Unknown app"}), 404
        if request.method == "POST":
            _obs_record(app_name, "config_change", "AppMap settings changed")
        d = _appmap_settings(app_name)
        if request.method == "POST":
            b = request.get_json(silent=True) or {}
            for k in d:
                if k in b: d[k] = bool(b[k])
            h = _appmap_cfgdir(app_name)
            (h / "settings.json").write_text(_js_as.dumps(d), encoding="utf-8")
        return jsonify({"ok": True, **d})

    @app.route("/api/local-app/<app_name>/appmap/config", methods=["GET", "POST"])
    def api_appmap_config(app_name):
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": "Unknown app"}), 404
        p = _appmap_yml_path(app_name)
        if request.method == "POST":
            txt = (request.get_json(silent=True) or {}).get("content")
            if not isinstance(txt, str) or not txt.strip():
                return jsonify({"ok": False, "error": "appmap.yml cannot be empty"})
            p.write_text(txt.replace("\r\n", "\n"), encoding="utf-8")
        return jsonify({"ok": True, "path": str(p), "content": p.read_text(encoding="utf-8", errors="replace"),
                        "output": str(_appmap_home(app_name) / "tmp" / "appmap"), "lib": str(_appmap_lib())})

    def _appmap_dirs(srcdir, app_name=None):
        root = Path(srcdir)
        _own = (_appmap_home(app_name) / "tmp" / "appmap") if app_name else None
        ds = [root / "tmp" / "appmap", root / "target" / "appmap", root / "build" / "appmap"]
        for pat in ("*/tmp/appmap", "*/target/appmap"):
            ds += list(root.glob(pat))
        if _own: ds.insert(0, _own)
        return [d for d in ds if d.is_dir()]

    @app.route("/api/local-app/<app_name>/appmap", methods=["GET"])
    def api_appmap_status(app_name):
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": "Unknown app"}), 404
        srcdir = _appmap_srcdir(app_name)
        pom = Path(srcdir) / "pom.xml" if srcdir else None
        if not pom or not pom.exists():
            return jsonify({"ok": True, "available": False, "enabled": False, "srcdir": srcdir or "",
                            "error": "pom.xml not found in the app source directory"})
        text = pom.read_text(encoding="utf-8", errors="replace")
        maps = sum(len(list(d.rglob("*.appmap.json"))) for d in _appmap_dirs(srcdir, app_name))
        return jsonify({"ok": True, "available": True, "enabled": _appmap_enabled(text), "srcdir": str(srcdir), "maps": maps})

    def _appmap_parse(path, srcdir):
        import json as _json, re as _re
        data = _json.loads(Path(path).read_text(encoding="utf-8", errors="replace"))
        events = data.get("events") or []
        by_id = {e.get("id"): e for e in events if e.get("event") == "call"}
        stack, calls, http_s, http_c, sqls, spans = {}, [], [], [], [], []
        span_by_id = {}
        for e in events:
            tid = e.get("thread_id", 0)
            st = stack.setdefault(tid, [])
            if e.get("event") == "call":
                if e.get("http_server_request"):
                    _r = e["http_server_request"]; _k, _lb = "http", "%s %s" % (_r.get("request_method", ""), _r.get("normalized_path_info") or _r.get("path_info") or "")
                elif e.get("http_client_request"):
                    _r = e["http_client_request"]; _k, _lb = "httpc", "%s %s" % (_r.get("request_method", ""), _r.get("url") or "")
                elif e.get("sql_query"):
                    _k, _lb = "sql", _re.sub(r"\s+", " ", e["sql_query"].get("sql") or "")[:120]
                else:
                    _k, _lb = "call", "%s.%s" % ((e.get("defined_class") or "").split(".")[-1], e.get("method_id") or "")
                spans.append({"id": e.get("id"), "parent": st[-1] if st else None, "kind": _k, "label": _lb, "ms": 0.0})
                span_by_id[e.get("id")] = spans[-1]
                cls = e.get("defined_class") or ""
                rec = {"id": e.get("id"), "cls": cls, "method": e.get("method_id") or "", "path": e.get("path") or "",
                       "line": e.get("lineno"), "depth": len(st), "parent": st[-1] if st else None, "ms": None,
                       "params": ["%s=%s" % (_pp.get("name") or "arg", str(_pp.get("value"))[:300]) for _pp in (e.get("parameters") or [])][:12],
                       "ret": None}
                if e.get("http_server_request"):
                    r = e["http_server_request"]; http_s.append({"id": e["id"], "method": r.get("request_method"), "path": r.get("normalized_path_info") or r.get("path_info"), "status": None, "ms": None})
                elif e.get("http_client_request"):
                    r = e["http_client_request"]; http_c.append({"id": e["id"], "method": r.get("request_method"), "url": r.get("url"), "status": None, "ms": None})
                elif e.get("sql_query"):
                    q = e["sql_query"]; sqls.append({"id": e["id"], "sql": q.get("sql") or "", "db": q.get("database_type") or "", "ms": None,
                                                     "params": ["%s=%s" % (_pp.get("name") or "arg", str(_pp.get("value"))[:300]) for _pp in (e.get("parameters") or [])]})
                else:
                    calls.append(rec)
                st.append(e.get("id"))
            elif e.get("event") == "return":
                cid = e.get("parent_id")
                if st and cid in st:
                    while st and st[-1] != cid:
                        st.pop()
                    if st:
                        st.pop()
                ms = round((e.get("elapsed") or 0) * 1000, 3)
                _sp = span_by_id.get(cid)
                if _sp is not None:
                    _sp["ms"] = ms
                for coll in (calls, http_s, http_c, sqls):
                    for r in coll:
                        if r["id"] == cid:
                            r["ms"] = ms
                            if "ret" in r and isinstance(e.get("return_value"), dict):
                                _rv = e["return_value"]; r["ret"] = "%s: %s" % ((_rv.get("class") or "").split(".")[-1], str(_rv.get("value"))[:500])
                            if "status" in r and e.get("http_server_response"):
                                r["status"] = e["http_server_response"].get("status_code", e["http_server_response"].get("status"))
                            if "status" in r and e.get("http_client_response"):
                                r["status"] = e["http_client_response"].get("status_code", e["http_client_response"].get("status"))
                            break
        # edges caller class -> callee class
        cls_of = {c["id"]: c["cls"] for c in calls}
        edges = {}
        for c in calls:
            p = cls_of.get(c["parent"])
            if p and c["cls"] and p != c["cls"]:
                k = (p, c["cls"], c["method"]); edges[k] = edges.get(k, 0) + 1
        seq = []
        for c in calls:
            p = cls_of.get(c["parent"])
            if p and c["cls"] and p != c["cls"]:
                seq.append({"from": p, "to": c["cls"], "method": c["method"], "ms": c["ms"]})
        # classMap -> functions with locations
        funcs = []
        def walk(nodes, pkg):
            for n in nodes or []:
                t = n.get("type"); nm = n.get("name", "")
                if t == "function":
                    funcs.append({"cls": pkg, "name": nm, "location": n.get("location", ""), "static": bool(n.get("static"))})
                else:
                    walk(n.get("children"), (pkg + "." + nm) if pkg else nm)
        walk(data.get("classMap"), "")
        used = {}
        for c in calls:
            k = (c["cls"], c["method"]); used[k] = used.get(k, 0) + 1
        for f in funcs:
            f["calls"] = used.get((f["cls"], f["name"]), 0)
        # SQL grouped
        grp = {}
        for q in sqls:
            k = _re.sub(r"\s+", " ", _re.sub(r"'[^']*'|\b\d+\b", "?", q["sql"]).strip())[:300]
            g = grp.setdefault(k, {"sql": k, "db": q["db"], "count": 0, "total_ms": 0.0, "max_ms": 0.0})
            g["count"] += 1; g["total_ms"] = round(g["total_ms"] + (q["ms"] or 0), 3); g["max_ms"] = max(g["max_ms"], q["ms"] or 0)
        sql_runs = [{"id": q["id"], "sql": q["sql"], "db": q["db"], "ms": q["ms"], "params": q.get("params") or []} for q in sqls[:500]]
        # trace layout: AppMap events carry no timestamps, so children are laid out one after another inside their parent
        nxt, root_off = {}, 0.0
        for s in spans:
            p = span_by_id.get(s["parent"])
            if p is None:
                s["depth"], s["start"] = 0, root_off
                root_off += s["ms"]
            else:
                s["depth"] = p["depth"] + 1
                s["start"] = nxt.get(p["id"], p["start"])
            nxt[s["id"]] = s["start"]
            if p is not None:
                nxt[p["id"]] = s["start"] + s["ms"]
        for s in spans:
            s["start"] = round(s["start"], 3)
        meta = data.get("metadata") or {}
        return {
            "spans": spans[:2500],
            "name": meta.get("name") or Path(path).stem,
            "recorder": (meta.get("recorder") or {}).get("name", ""),
            "totals": {"events": len(events), "calls": len(calls), "http_server": len(http_s), "http_client": len(http_c), "sql": len(sqls)},
            "calls": calls[:800],
            "edges": [{"from": a, "to": b, "method": m, "count": n} for (a, b, m), n in sorted(edges.items(), key=lambda x: -x[1])[:200]],
            "sequence": seq[:120],
            "functions": sorted(funcs, key=lambda f: -f["calls"])[:1500],
            "sql": sorted(grp.values(), key=lambda g: -g["total_ms"])[:300],
            "sql_runs": sql_runs,
            "http_server": http_s[:300], "http_client": http_c[:300],
        }

    @app.route("/api/local-app/<app_name>/appmap/maps", methods=["GET"])
    def api_appmap_maps(app_name):
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": "Unknown app"}), 404
        srcdir = _appmap_srcdir(app_name)
        if not srcdir or not Path(srcdir).exists():
            return jsonify({"ok": False, "error": "App source directory not found"})
        files = []
        _home = _appmap_home(app_name)
        _appmap_pull(app_name)
        def _rel(f):
            try: return "dwb:" + str(f.relative_to(_home)).replace("\\", "/")
            except ValueError: return str(f.relative_to(srcdir)).replace("\\", "/")
        for d in _appmap_dirs(srcdir, app_name):
            for f in d.rglob("*.appmap.json"):
                files.append((f.stat().st_mtime, f))
        files.sort(key=lambda x: -x[0])
        import time as _t
        return jsonify({"ok": True, "srcdir": str(srcdir), "maps": [
            {"file": _rel(f), "name": f.name.replace(".appmap.json", ""), "size": f.stat().st_size,
             "modified": _t.strftime("%Y-%m-%d %H:%M", _t.localtime(m))} for m, f in files[:300]]})

    @app.route("/api/local-app/<app_name>/appmap/delete", methods=["POST"])
    def api_appmap_delete(app_name):
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": "Unknown app"}), 404
        srcdir = _appmap_srcdir(app_name)
        if not srcdir:
            return jsonify({"ok": False, "error": "App source directory not found"})
        body = request.get_json(silent=True) or {}
        _home = _appmap_home(app_name)
        targets = []
        if body.get("all"):
            for d in _appmap_dirs(srcdir, app_name):
                targets += list(d.rglob("*.appmap.json"))
        else:
            rel = str(body.get("file") or "")
            if not rel.endswith(".appmap.json"):
                return jsonify({"ok": False, "error": "Invalid file"}), 400
            base = Path(srcdir)
            if rel.startswith("dwb:"):
                base = _home; rel = rel[4:]
            full = (base / rel).resolve()
            if base.resolve() not in full.parents or not full.is_file():
                return jsonify({"ok": False, "error": "File not found"}), 404
            targets = [full]
        n = 0
        _srv = _home / "tmp" / "appmap" / "server"
        for f in targets:
            try:
                f.unlink(); n += 1
                try: _appmap_container_rm(app_name, f.relative_to(_srv).as_posix())   # also drop it inside the container, or the next pull restores it
                except ValueError: pass
            except Exception: pass
        if body.get("all"): _appmap_container_rm(app_name, "")
        return jsonify({"ok": True, "deleted": n})

    @app.route("/api/local-app/<app_name>/appmap/map", methods=["GET"])
    def api_appmap_map(app_name):
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": "Unknown app"}), 404
        srcdir = _appmap_srcdir(app_name)
        rel = request.args.get("file", "")
        if not srcdir or not rel.endswith(".appmap.json"):
            return jsonify({"ok": False, "error": "Invalid file"}), 400
        _base = Path(srcdir)
        if rel.startswith("dwb:"):
            _base = _appmap_home(app_name); rel = rel[4:]
        full = (_base / rel).resolve()
        if _base.resolve() not in full.parents or not full.is_file():
            return jsonify({"ok": False, "error": "File not found"}), 404
        _mb = full.stat().st_size / 1048576
        if _mb > 250:
            return jsonify({"ok": False, "error": "This recording is %d MB, too large to visualise. Narrow 'packages:' / add 'exclude:' entries in appmap.yml (AppMap tab), delete this file and re-run the test." % _mb})
        try:
            return jsonify({"ok": True, **_appmap_parse(full, srcdir)})
        except Exception as e:
            return jsonify({"ok": False, "error": "Could not read the AppMap file: %s" % e})

    # ── Deployed info ─────────────────────────────────────────────────────────
    _DEPLOYED_INFO_FILE = PAYOR_ROOT / "deployed_info.json"

    @app.route("/api/local-app/payor/deployed-info", methods=["GET"])
    def api_payor_deployed_info_get():
        import json as _json
        if _DEPLOYED_INFO_FILE.exists():
            try:
                data = _json.loads(_DEPLOYED_INFO_FILE.read_text(encoding="utf-8"))
                return jsonify({"ok": True, **data})
            except Exception:
                pass
        return jsonify({"ok": True, "branch": None, "release_ver": None, "deployed_at": None})

    @app.route("/api/local-app/payor/deployed-info", methods=["POST"])
    def api_payor_deployed_info_post():
        import json as _json, datetime as _dt
        body = request.get_json() or {}
        info = {
            "branch":      body.get("branch"),
            "release_ver": body.get("release_ver"),
            "deployed_at": _dt.datetime.utcnow().strftime("%Y-%m-%d %H:%M UTC"),
        }
        _DEPLOYED_INFO_FILE.parent.mkdir(parents=True, exist_ok=True)
        _DEPLOYED_INFO_FILE.write_text(_json.dumps(info), encoding="utf-8")
        return jsonify({"ok": True, **info})

    # ── Payor DB service status / start / stop ───────────────────────────────

    @app.route("/api/local-app/payor/db/service-status", methods=["GET"])
    def api_db_service_status():
        import subprocess as _sub

        # Derive Windows service name from the same Oracle SID used for DB connections
        with _payor_db_config_lock:
            oracle_sid = _payor_db_config.get("service", "DB19C")
        win_svc = f"OracleService{oracle_sid}"
        found_service = win_svc

        def _sc_query(svc):
            r = _sub.run(["sc", "query", svc],
                         capture_output=True, text=True, timeout=10, creationflags=0x08000000)
            t = r.stdout.upper()
            if "RUNNING" in t:       return "running"
            if "START_PENDING" in t: return "starting"
            if "STOPPED" in t or "STOP_PENDING" in t: return "stopped"
            return None

        state = "unknown"
        try:
            parsed = _sc_query(win_svc)
            if parsed:
                state = parsed
            else:
                # Fall back: use PowerShell to find any OracleService* that is running/stopped
                r2 = _sub.run(
                    ["powershell", "-NoProfile", "-Command",
                     "Get-Service -Name 'OracleService*' | Select-Object -Property Name,Status | Format-List"],
                    capture_output=True, text=True, timeout=15, creationflags=0x08000000,
                )
                out2 = r2.stdout
                # Parse: find the service whose Name contains the SID
                import re as _re
                blocks = _re.split(r'\r?\n\r?\n', out2.strip())
                for block in blocks:
                    name_m = _re.search(r'Name\s*:\s*(\S+)', block, _re.IGNORECASE)
                    status_m = _re.search(r'Status\s*:\s*(\S+)', block, _re.IGNORECASE)
                    if name_m and status_m:
                        svc_name = name_m.group(1).strip()
                        svc_status = status_m.group(1).strip().lower()
                        if oracle_sid.lower() in svc_name.lower():
                            found_service = svc_name
                            if svc_status == "running":   state = "running"
                            elif svc_status == "stopped": state = "stopped"
                            elif svc_status == "startpending": state = "starting"
                            break
        except Exception:
            pass
        # Also try a lightweight DB ping
        db_up = False
        try:
            conn = _get_db_connection()
            conn.ping()
            conn.close()
            db_up = True
        except Exception:
            pass
        return jsonify({"ok": True, "service": state, "db_up": db_up, "service_name": found_service})

    @app.route("/api/local-app/payor/db/start", methods=["POST"])
    def api_db_start():
        import subprocess as _sub
        with _payor_db_config_lock:
            oracle_sid = _payor_db_config.get("service", "DB19C")
        win_svc = f"OracleService{oracle_sid}"
        try:
            r = _sub.run(
                ["net", "start", win_svc],
                capture_output=True, text=True, timeout=60, creationflags=0x08000000,
            )
            if r.returncode == 0 or "already been started" in (r.stdout + r.stderr).lower():
                return jsonify({"ok": True})
            return jsonify({"ok": False, "error": (r.stderr or r.stdout).strip()})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/local-app/payor/db/stop", methods=["POST"])
    def api_db_stop():
        import subprocess as _sub
        with _payor_db_config_lock:
            oracle_sid = _payor_db_config.get("service", "DB19C")
        win_svc = f"OracleService{oracle_sid}"
        try:
            r = _sub.run(
                ["net", "stop", win_svc],
                capture_output=True, text=True, timeout=60, creationflags=0x08000000,
            )
            if r.returncode == 0 or "is not started" in (r.stdout + r.stderr).lower():
                return jsonify({"ok": True})
            return jsonify({"ok": False, "error": (r.stderr or r.stdout).strip()})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/local-app/payor/db/commit-edits", methods=["POST"])
    def api_db_commit_edits():
        body    = request.get_json() or {}
        table   = (body.get("table") or "").strip()
        columns = body.get("columns", [])
        changes = body.get("changes", [])
        inserts = body.get("inserts", [])
        if not table:
            return jsonify({"ok": False, "error": "No table name found in query. Make sure the query has FROM <tablename>."})
        if not changes and not inserts:
            return jsonify({"ok": True, "committed": 0})
        # Oracle stores unquoted names in UPPERCASE
        table_ident = table.upper().strip('"').strip("'")
        col_idents  = [c.upper() for c in columns]
        try:
            conn = _get_db_connection()
            cur  = conn.cursor()
            # Fetch insertable columns once for both UPDATE and INSERT filtering
            _owner, _tbl = table_ident.split('.', 1) if '.' in table_ident else (None, table_ident)
            if _owner:
                cur.execute(
                    "SELECT COLUMN_NAME FROM ALL_TAB_COLUMNS WHERE OWNER=:o AND TABLE_NAME=:t ORDER BY COLUMN_ID",
                    {"o": _owner, "t": _tbl}
                )
            else:
                cur.execute(
                    "SELECT COLUMN_NAME FROM ALL_TAB_COLUMNS WHERE TABLE_NAME=:t ORDER BY COLUMN_ID",
                    {"t": _tbl}
                )
            real_cols = {row[0] for row in cur.fetchall()}
            # Only filter by real_cols when the lookup actually returned results.
            # If empty (table not found / wrong schema), fall back to using all columns
            # so updates aren't silently skipped.
            use_filter = bool(real_cols)
            committed = 0
            for ch in changes:
                original  = ch.get("original", [])
                updated   = ch.get("updated",  [])
                key_index = ch.get("keyIndex", 0)
                set_parts, set_vals = [], []
                for i, (o, u) in enumerate(zip(original, updated)):
                    # Skip columns not in the real table only when we have reliable column info
                    if use_filter and col_idents[i] not in real_cols:
                        continue
                    if str(o if o is not None else '') != str(u if u is not None else ''):
                        set_parts.append(f'{col_idents[i]} = :sv{i}')
                        set_vals.append((f"sv{i}", u if u != '' else None))
                if not set_parts:
                    continue
                key_val = original[key_index] if key_index < len(original) else original[0]
                if key_val is None:
                    where_clause = f'{col_idents[key_index]} IS NULL'
                    where_params = {}
                else:
                    where_clause = f'{col_idents[key_index]} = :wk'
                    where_params = {"wk": str(key_val)}  # stringify to avoid type mismatch
                sql    = f'UPDATE {table_ident} SET {", ".join(set_parts)} WHERE {where_clause}'
                params = dict(set_vals, **where_params)
                cur.execute(sql, params)
                if cur.rowcount == 0:
                    conn.rollback()
                    cur.close(); conn.close()
                    return jsonify({"ok": False, "error": f"UPDATE matched 0 rows. Key column '{col_idents[key_index]}' = '{key_val}' not found in {table_ident}. Check the Key column selection."})
                committed += cur.rowcount
            if inserts:
                # Map result columns → real table columns (reuse real_cols fetched above)
                valid = [(i, c) for i, c in enumerate(col_idents) if c in real_cols]
                if not valid:
                    raise Exception(
                        f"No insertable columns found in table {table_ident}. "
                        f"Result columns: {col_idents}. "
                        f"Check the table name extracted from FROM clause or use a simpler SELECT."
                    )
                ins_cols = [c for _, c in valid]
                ins_ph   = [f':iv{i}' for i, _ in valid]
                ins_sql  = f'INSERT INTO {table_ident} ({", ".join(ins_cols)}) VALUES ({", ".join(ins_ph)})'
                for ins in inserts:
                    values = ins.get("values", [])
                    params = {f'iv{idx}': (values[idx] if idx < len(values) and values[idx] != '' else None) for idx, _ in valid}
                    cur.execute(ins_sql, params)
                    committed += 1
            conn.commit()
            cur.close(); conn.close()
            return jsonify({"ok": True, "committed": committed})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    # ── relations inferred from column names: tables that share a key column (USER_ACCOUNT / USER_ACCOUNT_PASSWORD share USER_ACCT_ID) without a foreign key between them ──
    _infer_cache = {}
    _INFER_IGNORE = {"VER_ID", "TENANT_ID", "ENDOR_EFF_DT", "ENDOR_EXPIRE_DT", "VER_EFF_DT", "VER_EXPIRE_DT"}
    _INFER_MAXTABLES = 40                     # a column found in more tables than this is generic (audit columns ...), not a link

    def _infer_meta(cur, owner):
        import time as _t
        hit = _infer_cache.get(owner)
        if hit and _t.time() - hit[0] < 300: return hit[1]
        by_col, by_tab = {}, {}
        cur.execute("SELECT table_name, column_name FROM all_tab_columns WHERE owner = :o", {"o": owner})
        for tn, cn in cur.fetchall():
            by_col.setdefault(cn, []).append(tn); by_tab.setdefault(tn, []).append(cn)
        pk = {}
        cur.execute("""SELECT k.table_name, cc.column_name FROM all_constraints k JOIN all_cons_columns cc ON cc.constraint_name = k.constraint_name AND cc.owner = k.owner
                       WHERE k.owner = :o AND k.constraint_type = 'P'""", {"o": owner})
        for tn, cn in cur.fetchall(): pk.setdefault(tn, set()).add(cn)
        fkp = set()
        cur.execute("""SELECT c.table_name, rc.table_name FROM all_constraints c JOIN all_constraints rc ON rc.constraint_name = c.r_constraint_name AND rc.owner = c.r_owner
                       WHERE c.owner = :o AND c.constraint_type = 'R' AND rc.owner = :o""", {"o": owner})
        for a, b in cur.fetchall(): fkp.add(frozenset((a, b)))
        meta = {"by_col": by_col, "by_tab": by_tab, "pk": pk, "fk": fkp}
        _infer_cache[owner] = (_t.time(), meta)
        return meta

    def _infer_pair(meta, c, a, b):
        """(child, parent) of a pair of tables that share column c, or None when neither side has c as a key."""
        pk = meta["pk"]; ap, bp = c in pk.get(a, ()), c in pk.get(b, ())
        if ap and not bp: return (b, a)
        if bp and not ap: return (a, b)
        if ap and bp:
            if b.startswith(a): return (b, a)
            if a.startswith(b): return (a, b)
            return (b, a) if a < b else (a, b)
        return None

    def _hid(v):
        """Tables the user hid in the relation view: a comma separated string or a list -> set of table names."""
        if isinstance(v, str): v = v.split(",")
        return {str(x).strip().upper() for x in (v or []) if str(x).strip()}

    def _capval(v):
        v = str(v if v is not None else "").strip().lower()
        if v == "all": return 0
        try: return max(10, int(v))
        except Exception: return 250

    def _infmax(v):
        """The 'ignore columns found in more than N tables' choice: a number, or 'all' (0) = nothing is ignored."""
        v = str(v if v is not None else "").strip().lower()
        if v == "all": return 0
        try: return max(2, int(v))
        except Exception: return _INFER_MAXTABLES

    def _infer_neighbours(meta, t, limit=40, maxt=40):
        """[(other table, shared column, 'parent' | 'child' = what the other one is for t)]"""
        out = []
        if not maxt: limit = max(limit, 100)
        for c in meta["by_tab"].get(t, []):
            tabs = meta["by_col"].get(c, [])
            if len(tabs) < 2 or (maxt and (c in _INFER_IGNORE or len(tabs) > maxt)): continue
            for o in tabs:
                if o == t or frozenset((t, o)) in meta["fk"]: continue
                pr = _infer_pair(meta, c, t, o)
                if pr: out.append((o, c, "parent" if pr[1] == o else "child"))
        return out[:limit]

    def _db_relations_walk(conn, schema, table, values, depth=2, per_fk=15, node_cap=150, refby=False, inferred=False, inferred_max=40, hidden=None):
        """Starting from one result row, follows foreign keys up (parents) and down (children) and returns the related rows as a graph."""
        hid = _hid(hidden)
        empty_n = [0]                                              # the empty referencing tables ("Show referenced-by tables") are counted apart, so they never use up the room of the real related rows
        real_n = lambda: len(nodes) - empty_n[0]
        cur = conn.cursor()
        if not schema:
            cur.execute("SELECT USER FROM dual")
            schema = cur.fetchone()[0]
        schema, table = schema.upper(), table.upper()
        fk_cache = {}

        def sval(v):
            if v is None: return None
            if hasattr(v, "read"):
                try: v = v.read()
                except Exception: return "[LOB]"
            if isinstance(v, (bytes, bytearray)): return "[%d bytes]" % len(v)
            if isinstance(v, (int, float)): return v
            v = str(v)
            return v if len(v) <= 160 else v[:157] + "..."

        def fks(owner, tbl):
            k = (owner, tbl)
            if k in fk_cache: return fk_cache[k]
            out, inc = {}, {}
            cur.execute("""
                SELECT c.constraint_name, cc.column_name, rc.owner, rc.table_name, rcc.column_name
                FROM all_constraints c
                JOIN all_cons_columns cc  ON cc.constraint_name = c.constraint_name AND cc.owner = c.owner
                JOIN all_constraints rc   ON rc.constraint_name = c.r_constraint_name AND rc.owner = c.r_owner
                JOIN all_cons_columns rcc ON rcc.constraint_name = rc.constraint_name AND rcc.owner = rc.owner AND rcc.position = cc.position
                WHERE c.owner = :o AND c.table_name = :t AND c.constraint_type = 'R'
                ORDER BY c.constraint_name, cc.position""", {"o": owner, "t": tbl})
            for cn, col, ro, rt, rcol in cur.fetchall():
                d = out.setdefault(cn, {"name": cn, "cols": [], "o": ro, "t": rt, "rcols": []})
                d["cols"].append(col); d["rcols"].append(rcol)
            cur.execute("""
                SELECT c.constraint_name, c.owner, c.table_name, cc.column_name, rcc.column_name
                FROM all_constraints rc
                JOIN all_constraints c    ON c.r_constraint_name = rc.constraint_name AND c.r_owner = rc.owner AND c.constraint_type = 'R'
                JOIN all_cons_columns cc  ON cc.constraint_name = c.constraint_name AND cc.owner = c.owner
                JOIN all_cons_columns rcc ON rcc.constraint_name = rc.constraint_name AND rcc.owner = rc.owner AND rcc.position = cc.position
                WHERE rc.owner = :o AND rc.table_name = :t AND rc.constraint_type IN ('P', 'U')
                ORDER BY c.constraint_name, cc.position""", {"o": owner, "t": tbl})
            for cn, co, ct, col, rcol in cur.fetchall():
                d = inc.setdefault(cn, {"name": cn, "o": co, "t": ct, "cols": [], "rcols": []})
                d["cols"].append(col); d["rcols"].append(rcol)
            fk_cache[k] = (list(out.values()), list(inc.values()))
            return fk_cache[k]

        def fetch(owner, tbl, conds, limit):
            """conds: [(col, value)]; returns [(rowid, {col: value})]"""
            where = " AND ".join('t."%s" = :v%d' % (c, i) for i, (c, _) in enumerate(conds))
            binds = {"v%d" % i: v for i, (_, v) in enumerate(conds)}
            cur.execute('SELECT * FROM (SELECT t.ROWID AS "__RID", t.* FROM "%s"."%s" t WHERE %s) WHERE ROWNUM <= %d' % (owner, tbl, where, limit + 1), binds)
            names = [d[0] for d in cur.description]
            rows = cur.fetchall()
            return [(str(r[0]), {names[i]: sval(r[i]) for i in range(1, len(names))}) for r in rows[:limit]], len(rows) > limit

        # the clicked row: identify it by its primary key when the result has it, else by all its simple values
        cur.execute("""SELECT cc.column_name FROM all_constraints c JOIN all_cons_columns cc ON cc.constraint_name = c.constraint_name AND cc.owner = c.owner
                       WHERE c.owner = :o AND c.table_name = :t AND c.constraint_type = 'P' ORDER BY cc.position""", {"o": schema, "t": table})
        pk = [r[0] for r in cur.fetchall()]
        vals = {str(k).upper(): v for k, v in (values or {}).items()}
        if pk and all(vals.get(c) not in (None, "") for c in pk): conds = [(c, vals[c]) for c in pk]
        else:
            cur.execute("SELECT column_name, data_type FROM all_tab_columns WHERE owner = :o AND table_name = :t", {"o": schema, "t": table})
            ok = {c for c, dt in cur.fetchall() if dt in ("NUMBER", "VARCHAR2", "CHAR", "NVARCHAR2", "FLOAT", "INTEGER")}
            conds = [(c, v) for c, v in vals.items() if c in ok and v not in (None, "") and len(str(v)) <= 200]
        if not conds: raise ValueError("The row has no values that can identify it in %s.%s" % (schema, table))
        root, _ = fetch(schema, table, conds, 1)
        if not root: raise ValueError("The row was not found in %s.%s (the Table field must name the table the row came from)" % (schema, table))

        nodes, edges, seen, truncated = {}, [], set(), False
        pk_cache = {}
        def pkcols(owner, tbl):
            if (owner, tbl) not in pk_cache:
                cur.execute("""SELECT cc.column_name FROM all_constraints c JOIN all_cons_columns cc ON cc.constraint_name = c.constraint_name AND cc.owner = c.owner
                               WHERE c.owner = :o AND c.table_name = :t AND c.constraint_type = 'P' ORDER BY cc.position""", {"o": owner, "t": tbl})
                pk_cache[(owner, tbl)] = [r[0] for r in cur.fetchall()]
            return pk_cache[(owner, tbl)]

        def add(owner, tbl, rid, row, level):
            nid = "%s.%s/%s" % (owner, tbl, rid)
            if nid not in nodes:
                pk = pkcols(owner, tbl)
                ordered = {k: row[k] for k in pk if k in row}              # primary key columns first
                ordered.update({k: v for k, v in row.items() if k not in ordered})
                nodes[nid] = {"id": nid, "schema": owner, "table": tbl, "level": level, "row": ordered, "pk": pk, "cols": list(ordered.keys())}   # "cols": the order to show (JSON objects get sorted by Flask)
            return nid
        rid0, row0 = root[0]
        rootid = add(schema, table, rid0, row0, 0)
        frontier = [(rootid, schema, table, row0, 0)]
        for _ in range(max(1, min(depth, 10))):
            nxt = []
            for nid, o, t, row, lvl in frontier:
                if real_n() >= node_cap: truncated = True; break
                out, inc = fks(o, t)
                for fk in out:                                         # parents
                    if fk["t"] in hid: continue
                    cv = [(rc, row.get(c)) for c, rc in zip(fk["cols"], fk["rcols"])]
                    if any(v is None for _, v in cv): continue
                    found, more = fetch(fk["o"], fk["t"], cv, per_fk)
                    for rid, prow in found:
                        pid = add(fk["o"], fk["t"], rid, prow, lvl - 1)
                        key = (nid, pid, fk["name"])
                        if key not in seen:
                            seen.add(key); edges.append({"from": nid, "to": pid, "label": ", ".join(fk["cols"]) + " → " + ", ".join(fk["rcols"]), "kind": "parent"})
                            nxt.append((pid, fk["o"], fk["t"], prow, lvl - 1))
                for fk in inc:                                         # children
                    if fk["t"] in hid: continue
                    cv = [(c, row.get(rc)) for c, rc in zip(fk["cols"], fk["rcols"])]
                    if any(v is None for _, v in cv): continue
                    found, more = fetch(fk["o"], fk["t"], cv, per_fk)
                    truncated = truncated or more
                    if refby and not found and empty_n[0] < 300:     # "Show referenced-by tables": a table with a foreign key to this one is shown even when no row of it points at this row
                        cid = "%s.%s/(none:%s:%s)" % (fk["o"], fk["t"], fk["name"], nid)
                        if cid not in nodes:
                            empty_n[0] += 1
                            pk2 = pkcols(fk["o"], fk["t"])
                            cur.execute("SELECT column_name FROM all_tab_columns WHERE owner = :o AND table_name = :t ORDER BY column_id", {"o": fk["o"], "t": fk["t"]})
                            names = [r[0] for r in cur.fetchall()]
                            names = [c for c in pk2 if c in names] + [c for c in names if c not in pk2]
                            nodes[cid] = {"id": cid, "schema": fk["o"], "table": fk["t"], "level": lvl + 1, "row": {}, "pk": pk2, "cols": names, "empty": True}
                        key = (cid, nid, fk["name"])
                        if key not in seen:
                            seen.add(key); edges.append({"from": cid, "to": nid, "label": ", ".join(fk["cols"]) + " → " + ", ".join(fk["rcols"]), "kind": "child"})
                    for rid, crow in found:
                        cid = add(fk["o"], fk["t"], rid, crow, lvl + 1)
                        key = (cid, nid, fk["name"])
                        if key not in seen:
                            seen.add(key); edges.append({"from": cid, "to": nid, "label": ", ".join(fk["cols"]) + " → " + ", ".join(fk["rcols"]), "kind": "child"})
                            nxt.append((cid, fk["o"], fk["t"], crow, lvl + 1))
                if inferred:                                           # tables sharing a key column with this one: the rows with the same value
                    meta = _infer_meta(cur, o)
                    for other, c, role in _infer_neighbours(meta, t, maxt=inferred_max):
                        if other in hid: continue
                        v = row.get(c)
                        if v is None or real_n() >= node_cap: continue
                        found, more = fetch(o, other, [(c, v)], per_fk)
                        truncated = truncated or more
                        for rid, orow in found:
                            oid = add(o, other, rid, orow, lvl - 1 if role == "parent" else lvl + 1)
                            a2, b2 = (nid, oid) if role == "parent" else (oid, nid)
                            key = (a2, b2, "inf:" + c)
                            if key not in seen:
                                seen.add(key); edges.append({"from": a2, "to": b2, "label": c + " → " + c, "kind": "inferred"})
                                nxt.append((oid, o, other, orow, lvl - 1 if role == "parent" else lvl + 1))
            frontier = nxt
        cur.close()
        return {"root": rootid, "nodes": list(nodes.values()), "edges": edges, "truncated": truncated}

    @app.route("/api/local-app/payor/db/relations", methods=["POST"])
    def api_local_payor_db_relations():
        b = request.get_json(silent=True) or {}
        try:
            conn = _get_db_connection()
            try:
                return jsonify(dict(ok=True, **_db_relations_walk(conn, b.get("schema", ""), b.get("table", ""), b.get("values"), int(b.get("depth") or 2), refby=bool(b.get("refby")), inferred=bool(b.get("inferred")), inferred_max=_infmax(b.get("inferred_max")), hidden=b.get("hidden"))))
            finally:
                conn.close()
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    def _db_table_relations(conn, schema, table, depth=1, node_cap=150, inferred=False, inferred_max=40, hidden=None):
        hid = _hid(hidden)
        """Tables related to one table through foreign keys (parents it points to, children that point at it) as a graph."""
        cur = conn.cursor()
        if not schema:
            cur.execute("SELECT USER FROM dual"); schema = cur.fetchone()[0]
        schema, table = schema.upper(), table.upper()
        cache = {}

        def cols(o, t):
            if (o, t) in cache: return cache[(o, t)]
            cur.execute("SELECT column_name, data_type FROM all_tab_columns WHERE owner = :o AND table_name = :t ORDER BY column_id", {"o": o, "t": t})
            c = cur.fetchall()
            cur.execute("""SELECT cc.column_name FROM all_constraints k JOIN all_cons_columns cc ON cc.constraint_name = k.constraint_name AND cc.owner = k.owner
                           WHERE k.owner = :o AND k.table_name = :t AND k.constraint_type = 'P'""", {"o": o, "t": t})
            pk = {r[0] for r in cur.fetchall()}
            cur.execute("""SELECT DISTINCT cc.column_name FROM all_constraints k JOIN all_cons_columns cc ON cc.constraint_name = k.constraint_name AND cc.owner = k.owner
                           WHERE k.owner = :o AND k.table_name = :t AND k.constraint_type = 'R'""", {"o": o, "t": t})
            fk = {r[0] for r in cur.fetchall()}
            c.sort(key=lambda x: (x[0] not in pk, x[0] not in fk))
            cache[(o, t)] = {n: dt + (" PK" if n in pk else "") + (" FK" if n in fk else "") for n, dt in c}
            return cache[(o, t)]

        def links(o, t):
            cur.execute("""SELECT c.constraint_name, rc.owner, rc.table_name, cc.column_name, rcc.column_name
                FROM all_constraints c
                JOIN all_cons_columns cc  ON cc.constraint_name = c.constraint_name AND cc.owner = c.owner
                JOIN all_constraints rc   ON rc.constraint_name = c.r_constraint_name AND rc.owner = c.r_owner
                JOIN all_cons_columns rcc ON rcc.constraint_name = rc.constraint_name AND rcc.owner = rc.owner AND rcc.position = cc.position
                WHERE c.owner = :o AND c.table_name = :t AND c.constraint_type = 'R' ORDER BY c.constraint_name, cc.position""", {"o": o, "t": t})
            par = {}
            for cn, ro, rt, c1, c2 in cur.fetchall():
                d = par.setdefault(cn, [ro, rt, [], []]); d[2].append(c1); d[3].append(c2)
            cur.execute("""SELECT c.constraint_name, c.owner, c.table_name, cc.column_name, rcc.column_name
                FROM all_constraints rc
                JOIN all_constraints c    ON c.r_constraint_name = rc.constraint_name AND c.r_owner = rc.owner AND c.constraint_type = 'R'
                JOIN all_cons_columns cc  ON cc.constraint_name = c.constraint_name AND cc.owner = c.owner
                JOIN all_cons_columns rcc ON rcc.constraint_name = rc.constraint_name AND rcc.owner = rc.owner AND rcc.position = cc.position
                WHERE rc.owner = :o AND rc.table_name = :t AND rc.constraint_type IN ('P', 'U') ORDER BY c.constraint_name, cc.position""", {"o": o, "t": t})
            chi = {}
            for cn, co, ct, c1, c2 in cur.fetchall():
                d = chi.setdefault(cn, [co, ct, [], []]); d[2].append(c1); d[3].append(c2)
            return par, chi

        nodes, edges, seen = {}, [], set()
        def add(o, t, lvl):
            nid = "%s.%s" % (o, t)
            if nid not in nodes: nodes[nid] = {"id": nid, "schema": o, "table": t, "level": lvl, "row": cols(o, t), "cols": list(cols(o, t).keys())}
            return nid
        root = add(schema, table, 0)
        frontier = [(schema, table, 0)]
        for _ in range(max(1, min(depth, 10))):
            nxt = []
            for o, t, lvl in frontier:
                if len(nodes) >= node_cap: break
                par, chi = links(o, t)
                me = "%s.%s" % (o, t)
                for cn, (ro, rt, c1, c2) in par.items():
                    if rt in hid: continue
                    new = "%s.%s" % (ro, rt) not in nodes
                    pid = add(ro, rt, lvl - 1)
                    if (me, pid, cn) not in seen:
                        seen.add((me, pid, cn)); edges.append({"from": me, "to": pid, "label": ", ".join(c1) + " → " + ", ".join(c2), "kind": "parent"})
                        if new: nxt.append((ro, rt, lvl - 1))
                for cn, (co, ct, c1, c2) in chi.items():
                    if ct in hid: continue
                    new = "%s.%s" % (co, ct) not in nodes
                    cid = add(co, ct, lvl + 1)
                    if (cid, me, cn) not in seen:
                        seen.add((cid, me, cn)); edges.append({"from": cid, "to": me, "label": ", ".join(c1) + " → " + ", ".join(c2), "kind": "child"})
                        if new: nxt.append((co, ct, lvl + 1))
                if inferred:                                           # tables sharing a key column with this one, without a foreign key
                    meta = _infer_meta(cur, o)
                    for other, c, role in _infer_neighbours(meta, t, maxt=inferred_max):
                        if len(nodes) >= node_cap or other in hid: continue
                        new = "%s.%s" % (o, other) not in nodes
                        oid = add(o, other, lvl - 1 if role == "parent" else lvl + 1)
                        a2, b2 = (me, oid) if role == "parent" else (oid, me)
                        key = (a2, b2, "inf:" + c)
                        if key not in seen:
                            seen.add(key); edges.append({"from": a2, "to": b2, "label": c + " → " + c, "kind": "inferred"})
                            if new: nxt.append((o, other, lvl - 1 if role == "parent" else lvl + 1))
            frontier = nxt
        cur.close()
        return {"root": root, "nodes": list(nodes.values()), "edges": edges, "truncated": len(nodes) >= node_cap}

    @app.route("/api/local-app/payor/db/table-relations", methods=["GET"])
    def api_local_payor_db_table_relations():
        try:
            conn = _get_db_connection()
            try:
                return jsonify(dict(ok=True, **_db_table_relations(conn, request.args.get("schema", ""), request.args.get("table", ""), int(request.args.get("depth") or 1), inferred=request.args.get("inferred") == "1", inferred_max=_infmax(request.args.get("inferred_max")), hidden=request.args.get("hidden", ""))))
            finally:
                conn.close()
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    def _db_schema_relations(conn, schema, cap=250, isolated=False, focus="", refby=False, inferred=False, inferred_max=40, hidden=None):
        hid = _hid(hidden)
        cap = cap if cap else 10 ** 9                            # 0 = all tables
        """Every foreign key between tables of one schema: the connected tables as nodes, one edge per constraint (child -> parent)."""
        cur = conn.cursor()
        schema = (schema or "").upper()
        cur.execute("SELECT COUNT(*) FROM all_tables WHERE owner = :o", {"o": schema})
        total = cur.fetchone()[0]
        cur.execute("""SELECT c.constraint_name, c.table_name, rc.owner, rc.table_name, cc.column_name, rcc.column_name
            FROM all_constraints c
            JOIN all_cons_columns cc  ON cc.constraint_name = c.constraint_name AND cc.owner = c.owner
            JOIN all_constraints rc   ON rc.constraint_name = c.r_constraint_name AND rc.owner = c.r_owner
            JOIN all_cons_columns rcc ON rcc.constraint_name = rc.constraint_name AND rcc.owner = rc.owner AND rcc.position = cc.position
            WHERE c.owner = :o AND c.constraint_type = 'R' ORDER BY c.constraint_name, cc.position""", {"o": schema})
        cons = {}
        for cn, ct, ro, rt, c1, c2 in cur.fetchall():
            if ct in hid or rt in hid: continue
            d = cons.setdefault(cn, [ct, ro, rt, [], []]); d[3].append(c1); d[4].append(c2)
        deg, referrers = {}, {}
        for ct, ro, rt, _, _ in cons.values():
            a, b = "%s.%s" % (schema, ct), "%s.%s" % (ro, rt)
            if a == b: continue
            deg.setdefault(a, set()).add(b); deg.setdefault(b, set()).add(a)
            referrers.setdefault(b, set()).add(a)                      # b is referenced by a
        inf_edges = []
        if inferred:                                           # same-named key columns between tables without a foreign key
            meta = _infer_meta(cur, schema)
            for c, tabs in meta["by_col"].items():
                if len(tabs) < 2 or (inferred_max and (c in _INFER_IGNORE or len(tabs) > inferred_max)): continue
                if len(inf_edges) > 30000: break                          # with 'all' a very common column would make millions of pairs
                for i in range(len(tabs)):
                    if len(inf_edges) > 30000: break
                    if tabs[i] in hid: continue
                    for j in range(i + 1, len(tabs)):
                        if tabs[j] in hid: continue
                        if frozenset((tabs[i], tabs[j])) in meta["fk"]: continue
                        pr = _infer_pair(meta, c, tabs[i], tabs[j])
                        if not pr: continue
                        a, b = "%s.%s" % (schema, pr[0]), "%s.%s" % (schema, pr[1])
                        inf_edges.append((a, b, c))
                        deg.setdefault(a, set()).add(b); deg.setdefault(b, set()).add(a); referrers.setdefault(b, set()).add(a)
        keep = set(sorted(deg, key=lambda k: -len(deg[k]))[:cap])
        if refby:                                                      # "Show referenced-by tables": every table that references a shown table is shown too (beyond the usual limit)
            for t in list(keep): keep |= referrers.get(t, set())
            if inferred:                                               # ... and the tables that share a key column name with a shown table, so that both options together lose nothing
                for a, b, c in inf_edges:
                    if a in keep or b in keep: keep.add(a); keep.add(b)
        focus_id = ""
        if focus:                                              # a table asked for by name is brought in with its neighbours even if it is not among the most connected
            q = focus.strip().upper().replace("%", "")
            cur.execute("SELECT table_name FROM (SELECT table_name FROM all_tables WHERE owner = :o AND table_name LIKE :q ORDER BY CASE WHEN table_name = :e THEN 0 ELSE 1 END, table_name) WHERE ROWNUM = 1",
                        {"o": schema, "q": "%" + q + "%", "e": q})
            r = cur.fetchone()
            if r:
                focus_id = "%s.%s" % (schema, r[0])
                keep.add(focus_id); keep |= deg.get(focus_id, set())
        edges, ids = [], set()
        for ct, ro, rt, c1, c2 in cons.values():
            a, b = "%s.%s" % (schema, ct), "%s.%s" % (ro, rt)
            if a in keep and b in keep and a != b:
                edges.append({"from": a, "to": b, "label": ", ".join(c1) + " → " + ", ".join(c2)}); ids.add(a); ids.add(b)
        seen_inf = set()
        for a, b, c in inf_edges:
            if a in keep and b in keep and (a, b, c) not in seen_inf:
                seen_inf.add((a, b, c)); edges.append({"from": a, "to": b, "label": c + " → " + c, "kind": "inferred"}); ids.add(a); ids.add(b)
        if isolated:                                           # tables that take part in no foreign key
            cur.execute("SELECT table_name FROM all_tables WHERE owner = :o AND table_name NOT LIKE 'BIN$%' ORDER BY table_name", {"o": schema})
            for (tn,) in cur.fetchall():
                if tn in hid: continue
                ids.add("%s.%s" % (schema, tn)) if "%s.%s" % (schema, tn) not in deg else None
        if focus_id: ids.add(focus_id)
        nodes = [{"id": i, "schema": i.split(".")[0], "table": i.split(".", 1)[1], "level": 0, "row": {}} for i in sorted(ids)]
        cur.close()
        return {"nodes": nodes, "edges": edges, "total": total, "connected": len(deg), "truncated": len(deg) > cap, "root": "", "focus": focus_id}

    def _db_search_tables(conn, schema, q, limit=60):
        cur = conn.cursor()
        q = (q or "").strip().upper().replace("%", "")
        cur.execute("SELECT table_name FROM (SELECT table_name FROM all_tables WHERE owner = :o AND table_name LIKE :q ORDER BY CASE WHEN table_name = :e THEN 0 WHEN table_name LIKE :p THEN 1 ELSE 2 END, table_name) WHERE ROWNUM <= %d" % limit,
                    {"o": (schema or "").upper(), "q": "%" + q + "%", "e": q, "p": q + "%"})
        names = [r[0] for r in cur.fetchall()]
        cur.close()
        return names

    def _db_tables_columns(conn, tables):
        """Columns (with type and PK/FK marks) for a list of {schema, table}."""
        cur = conn.cursor()
        out = {}
        by_owner = {}
        for t in tables:
            by_owner.setdefault(str(t.get("schema", "")).upper(), []).append(str(t.get("table", "")).upper())
        for o, names in by_owner.items():
            ph = ",".join(":t%d" % i for i in range(len(names)))
            b = dict({"t%d" % i: n for i, n in enumerate(names)}, o=o)
            cur.execute("SELECT table_name, column_name, data_type FROM all_tab_columns WHERE owner = :o AND table_name IN (%s) ORDER BY table_name, column_id" % ph, b)
            cols = {}
            for tn, cn, dt in cur.fetchall(): cols.setdefault(tn, []).append((cn, dt))
            cur.execute("""SELECT k.table_name, k.constraint_type, cc.column_name FROM all_constraints k JOIN all_cons_columns cc ON cc.constraint_name = k.constraint_name AND cc.owner = k.owner
                           WHERE k.owner = :o AND k.table_name IN (%s) AND k.constraint_type IN ('P', 'R')""" % ph, b)
            pk, fk = set(), set()
            for tn, ty, cn in cur.fetchall(): (pk if ty == "P" else fk).add((tn, cn))
            for tn, lst in cols.items():
                lst.sort(key=lambda x: ((tn, x[0]) not in pk, (tn, x[0]) not in fk))
                out["%s.%s" % (o, tn)] = {cn: dt + (" PK" if (tn, cn) in pk else "") + (" FK" if (tn, cn) in fk else "") for cn, dt in lst}
        cur.close()
        return out

