    @app.route("/api/local-app/payor/db/export", methods=["POST"])
    def api_db_export():
        import io as _io
        from flask import send_file as _sf, Response as _Resp
        body    = request.get_json() or {}
        columns = body.get("columns", [])
        rows    = body.get("rows",    [])
        fmt     = body.get("format",  "xlsx").lower()

        if fmt == "xls":
            try:
                import xlwt as _xlwt
            except ImportError:
                return _Resp('{"ok":false,"error":"xlwt not installed — run: pip install xlwt"}',
                             status=500, mimetype="application/json")
            wb = _xlwt.Workbook(encoding="utf-8")
            ws = wb.add_sheet("Results")
            bold = _xlwt.easyxf("font: bold true")
            for ci, col in enumerate(columns):
                ws.write(0, ci, str(col), bold)
            for ri, row in enumerate(rows, 1):
                for ci, val in enumerate(row):
                    ws.write(ri, ci, "" if val is None else (val if isinstance(val, (int, float)) else str(val)))
            buf = _io.BytesIO()
            wb.save(buf)
            buf.seek(0)
            return _sf(buf, mimetype="application/vnd.ms-excel", as_attachment=True, download_name="query_result.xls")
        else:
            try:
                import openpyxl as _xl
                from openpyxl.styles import Font as _Font
            except ImportError:
                return _Resp('{"ok":false,"error":"openpyxl not installed — run: pip install openpyxl"}',
                             status=500, mimetype="application/json")
            wb = _xl.Workbook()
            ws = wb.active
            ws.append(columns)
            for cell in ws[1]:
                cell.font = _Font(bold=True)
            for row in rows:
                ws.append([None if v is None else (v if isinstance(v, (int, float)) else str(v)) for v in row])
            buf = _io.BytesIO()
            wb.save(buf)
            buf.seek(0)
            mime = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
            return _sf(buf, mimetype=mime, as_attachment=True, download_name="query_result.xlsx")

