    @app.route("/api/local-app/payor/db/connect", methods=["POST"])
    def api_local_app_payor_db_connect():
        body = request.get_json() or {}
        # If caller provides credentials, update config; else auto-detect from container
        if body.get("user"):
            with _payor_db_config_lock:
                for k in ("host", "port", "service", "user", "password"):
                    if k in body:
                        _payor_db_config[k] = int(body[k]) if k == "port" else body[k]
        else:
            container = _resolve_payor_container(_read_payor_docker_key("containerName") or "payer-tc-261")
            detected = _db_read_container_config(container)
            if detected:
                with _payor_db_config_lock:
                    _payor_db_config.update(detected)
        try:
            conn = _get_db_connection()
            cur = conn.cursor()
            cur.execute("SELECT USER FROM dual")
            schema_user = cur.fetchone()[0]
            conn.close()
            with _payor_db_config_lock:
                cfg_safe = {k: v for k, v in _payor_db_config.items() if k != "password"}
            return jsonify({"ok": True, "schema_user": schema_user, "config": cfg_safe})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/local-app/payor/db/schemas", methods=["GET"])
    def api_local_app_payor_db_schemas():
        try:
            conn = _get_db_connection()
            cur = conn.cursor()
            cur.execute("SELECT USER FROM dual")
            current = cur.fetchone()[0]
            schemas = [current]
            try:
                cur.execute("SELECT COUNT(*) FROM all_tables WHERE owner = 'PAYOR_DW'")
                if (cur.fetchone() or [0])[0] > 0 and current != "PAYOR_DW":
                    schemas.append("PAYOR_DW")
            except Exception:
                pass
            conn.close()
            return jsonify({"ok": True, "schemas": schemas})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

