    @app.route("/api/local-app/payor/db/table-structure", methods=["GET"])
    def api_local_app_payor_db_table_structure():
        schema = (request.args.get("schema") or "").upper().strip()
        table  = (request.args.get("table")  or "").upper().strip()
        if not schema or not table:
            return jsonify({"ok": False, "error": "schema and table required"})
        try:
            conn = _get_db_connection()
            cur  = conn.cursor()
            # Columns with precision/scale/default
            cur.execute("""
                SELECT column_name, data_type, data_length, data_precision, data_scale,
                       nullable, data_default
                FROM all_tab_columns
                WHERE owner = :o AND table_name = :t
                ORDER BY column_id
            """, {"o": schema, "t": table})
            columns = [{"name": r[0], "type": r[1], "length": r[2],
                        "precision": r[3], "scale": r[4],
                        "nullable": r[5], "default_val": (r[6] or "").strip() if r[6] else None}
                       for r in cur.fetchall()]
            # Primary key columns
            cur.execute("""
                SELECT cc.column_name
                FROM all_constraints c
                JOIN all_cons_columns cc ON c.constraint_name = cc.constraint_name AND c.owner = cc.owner
                WHERE c.owner = :o AND c.table_name = :t AND c.constraint_type = 'P'
                ORDER BY cc.position
            """, {"o": schema, "t": table})
            pk_cols = [r[0] for r in cur.fetchall()]
            # Foreign keys: column → referenced owner.table.column
            cur.execute("""
                SELECT cc.column_name, rc.owner, rc.table_name, rcc.column_name
                FROM all_constraints c
                JOIN all_cons_columns cc  ON c.constraint_name  = cc.constraint_name  AND c.owner = cc.owner
                JOIN all_constraints rc   ON c.r_constraint_name = rc.constraint_name AND c.r_owner = rc.owner
                JOIN all_cons_columns rcc ON rc.constraint_name  = rcc.constraint_name AND rc.owner = rcc.owner
                                         AND cc.position = rcc.position
                WHERE c.owner = :o AND c.table_name = :t AND c.constraint_type = 'R'
            """, {"o": schema, "t": table})
            fk_map = {r[0]: {"ref_schema": r[1], "ref_table": r[2], "ref_col": r[3]} for r in cur.fetchall()}
            # Referenced by: columns of other tables whose foreign key points at this table
            cur.execute("""
                SELECT c.owner, c.table_name, cc.column_name, rcc.column_name
                FROM all_constraints rc
                JOIN all_constraints c    ON c.r_constraint_name = rc.constraint_name AND c.r_owner = rc.owner AND c.constraint_type = 'R'
                JOIN all_cons_columns cc  ON cc.constraint_name = c.constraint_name AND cc.owner = c.owner
                JOIN all_cons_columns rcc ON rcc.constraint_name = rc.constraint_name AND rcc.owner = rc.owner AND rcc.position = cc.position
                WHERE rc.owner = :o AND rc.table_name = :t AND rc.constraint_type IN ('P', 'U')
                ORDER BY c.owner, c.table_name, cc.column_name
            """, {"o": schema, "t": table})
            referenced_by = [{"schema": r[0], "table": r[1], "column": r[2], "ref_col": r[3]} for r in cur.fetchall()]
            # Indexes
            cur.execute("""
                SELECT i.index_name, i.uniqueness, ic.column_name
                FROM all_indexes i
                JOIN all_ind_columns ic ON i.index_name = ic.index_name AND i.owner = ic.index_owner
                WHERE i.owner = :o AND i.table_name = :t
                ORDER BY i.index_name, ic.column_position
            """, {"o": schema, "t": table})
            idx_map = {}
            for r in cur.fetchall():
                if r[0] not in idx_map:
                    idx_map[r[0]] = {"name": r[0], "uniqueness": r[1], "columns": []}
                idx_map[r[0]]["columns"].append(r[2])
            conn.close()
            return jsonify({"ok": True, "columns": columns, "pk_cols": pk_cols,
                            "fk_map": fk_map, "referenced_by": referenced_by, "indexes": list(idx_map.values())})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/local-app/payor/db/execute", methods=["POST"])
    def api_local_app_payor_db_execute():
        body = request.get_json() or {}
        sql  = (body.get("sql") or "").strip().rstrip(";").strip()
        if not sql:
            return jsonify({"ok": False, "error": "sql required"})
        try:
            conn = _get_db_connection()
            cur  = conn.cursor()
            cur.execute(sql)
            if cur.description:
                columns = [d[0] for d in cur.description]
                raw_rows = cur.fetchmany(1000)
                rows = []
                for row in raw_rows:
                    rows.append([_db_cell(v) for v in row])
                conn.close()
                return jsonify({"ok": True, "columns": columns, "rows": rows,
                                "row_count": len(rows), "is_dml": False})
            else:
                conn.commit()
                rowcount = cur.rowcount
                conn.close()
                return jsonify({"ok": True, "columns": [], "rows": [],
                                "row_count": rowcount, "is_dml": True})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    def _query_names_path(folder):
        folder.mkdir(parents=True, exist_ok=True)
        return folder / "tab_names.json"

    def _query_names_get(folder):
        import json as _jn
        pth = _query_names_path(folder)
        try:
            return _jn.loads(pth.read_text(encoding="utf-8")) if pth.exists() else {}
        except Exception:
            return {}

    def _query_names_set(folder, tab_num, title):
        import json as _jn
        names = _query_names_get(folder)
        title = str(title or "").strip()[:60]
        if title:
            names[str(tab_num)] = title
        else:
            names.pop(str(tab_num), None)
        _query_names_path(folder).write_text(_jn.dumps(names, indent=2), encoding="utf-8")
        return names

