    @app.route("/api/local-app/payor/module-build", methods=["POST"])
    def api_local_app_payor_module_build():
        body       = request.get_json() or {}
        module     = str(body.get("module", "")).strip()
        skip_tests = bool(body.get("skip_tests", False))
        with_dist  = bool(body.get("with_dist",  False))
        if not module:
            return jsonify({"ok": False, "error": "module is required"}), 400
        with _module_op_lock:
            if _module_op["status"] == "running":
                return jsonify({"ok": False, "error": "An operation is already running"}), 409
            _module_op.update({"status": "running", "output": "", "op": "build", "module": module})
        extra = []
        if skip_tests: extra.append("-st")
        if with_dist:  extra.append("-dist")
        _threading.Thread(target=_run_module_op, args=("build", module, PAYOR_ROOT, extra), daemon=True).start()
        return jsonify({"ok": True})

