    def api_local_app_payor_module_op_abort():
        with _module_op_lock:
            if _module_op["status"] != "running":
                return jsonify({"ok": False, "error": "Nothing is running"}), 400
            _module_op["status"] = "aborted"
            proc = _module_op.get("proc")
