    @app.route("/api/local-app/payor/module-deploy-cfg", methods=["GET", "POST"])
    def api_local_app_payor_module_deploy_cfg():
        if request.method == "POST":
            body   = request.get_json() or {}
            module = str(body.get("module", "")).strip()
            if not module:
                return jsonify({"ok": False, "error": "module is required"}), 400
            overrides = _read_module_overrides(PAYOR_ROOT)
            entry = overrides.get(module, {})
            for field in ("suppress_warning", "disable_needs_build"):
                if field in body:
                    entry[field] = bool(body[field])
            if "target_artifact_name" in body:
                v = str(body["target_artifact_name"] or "").strip()
                if v: entry["target_artifact_name"] = v
                else: entry.pop("target_artifact_name", None)
            if "targets" in body:
                cleaned = [
                    {"deploy_dir": str(t.get("deploy_dir") or "").strip(),
                     "deployment_artifact_name": str(t.get("deployment_artifact_name") or "").strip()}
                    for t in (body["targets"] or [])
                    if str(t.get("deploy_dir") or "").strip() or str(t.get("deployment_artifact_name") or "").strip()
                ]
                entry["targets"] = cleaned
                entry.pop("jar_name", None)
                # Keep backward-compat keys = first target values (for deploy_jar.js)
                if cleaned:
                    entry["deploy_dir"] = cleaned[0]["deploy_dir"]
                    entry["deployment_artifact_name"] = cleaned[0]["deployment_artifact_name"]
                else:
                    entry.pop("deploy_dir", None)
                    entry.pop("deployment_artifact_name", None)
            else:
                # Legacy single-field update
                for field in ("deploy_dir", "deployment_artifact_name"):
                    val = body.get(field) if field in body else body.get("jar_name") if field == "deployment_artifact_name" else None
                    if val is not None:
                        v = str(val or "").strip()
                        entry.pop("jar_name", None)
                        if v:
                            entry[field] = v
                            targets = entry.get("targets", [])
                            if targets:
                                targets[0][field] = v
                            else:
                                entry["targets"] = [{"deploy_dir": entry.get("deploy_dir", ""), "deployment_artifact_name": entry.get("deployment_artifact_name", "")}]
                        else:
                            entry.pop(field, None)
            overrides[module] = entry
            _write_module_overrides(PAYOR_ROOT, overrides)
            return jsonify({"ok": True})
        config_xlsx = PAYOR_ROOT / "app_config.xlsx"
        module_overrides = _read_module_overrides(PAYOR_ROOT)
        if not config_xlsx.exists():
            return jsonify({"ok": True, "configured": False, "reason": "app_config.xlsx not found",
                            "module_overrides": module_overrides})
        try:
            import openpyxl as _xl
            wb = _xl.load_workbook(str(config_xlsx), data_only=True)
            docker_ws = next((s for s in wb.sheetnames if s.lower() == "docker_vm"), None)
            if not docker_ws:
                return jsonify({"ok": True, "configured": False, "reason": "Docker_VM sheet not found in app_config.xlsx",
                                "module_overrides": module_overrides})
            deploy_dir = ""
            container  = ""
            for row in wb[docker_ws].iter_rows(min_row=2, values_only=True):
                if not row or not row[0]:
                    continue
                k  = str(row[0]).strip()
                v  = str(row[1]).strip() if row[1] is not None else ""
                ov = str(row[2]).strip() if len(row) > 2 and row[2] is not None else ""
                val = ov if ov else v
                if k == "deployDir":
                    deploy_dir = val
                elif k == "containerName":
                    container = val
            configured = bool(deploy_dir)
            return jsonify({"ok": True, "configured": configured, "deploy_dir": deploy_dir,
                            "container": _resolve_payor_container(container) if container else container, "module_overrides": module_overrides})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/local-app/payor/fix-dependency", methods=["POST"])
    def api_local_app_payor_fix_dependency():
        import re as _re2
        body     = request.get_json() or {}
        artifact = (body.get("artifact") or "").strip()

        # Auto-detect from last build output when not provided
        if not artifact:
            with _payor_build_lock:
                last_output = _payor_build.get("output", "")
            m = _re2.search(
                r"Could not transfer artifact\s+(\S+:\S+:\S+:\S+)\s+from/to",
                last_output, _re2.I,
            )
            if m:
                artifact = m.group(1)
        if not artifact:
            return jsonify({"ok": False, "error": "Could not determine failing artifact from build output"})
        if len(artifact.split(":")) != 4:
            return jsonify({"ok": False, "error": f"Unexpected artifact format: {artifact}"})

        _, srcdir = _payor_srcdir()
        if not srcdir or not Path(srcdir).exists():
            return jsonify({"ok": False, "error": "Clone directory not found"})

        ok, log = _mvn_install_artifact(artifact, srcdir)
        if not ok:
            return jsonify({"ok": False, "error": "Dependency install failed — see output", "output": log})
        return jsonify({"ok": True, "artifact": artifact, "output": log})

