    # ── Local App Payor – UI Apps (Manager, Designer, Admin) ──────────────────

    _INSTALLED_BASE_DEFAULT = str(HE_UI_INSTALLED_BASE / "Local")
    _INSTALLERS_BASE_DEFAULT = str(HE_UI_INSTALLERS_BASE / "Local")

    def _ensure_ui_apps_config():
        import openpyxl as _xl
        _defaults = {
            "base_url":        "https://heeng-sugarloaf.healthedge.net",
            "version":         "release-26.1.1.1",
            "installers_base": _INSTALLERS_BASE_DEFAULT,
            "installed_base":  _INSTALLED_BASE_DEFAULT,
        }
        if not UI_APPS_CONFIG.exists():
            wb = _xl.Workbook()
            ws_cfg = wb.active
            ws_cfg.title = "Config"
            ws_cfg.append(["Setting", "Value"])
            for k, v in _defaults.items():
                ws_cfg.append([k, v])
            ws_apps = wb.create_sheet("Apps")
            ws_apps.append(["app_id", "display_name", "folder", "app_file"])
            ws_apps.append(["manager",  "Manager",  "Manager",  "HealthEdge.Manager.application"])
            ws_apps.append(["admin",    "Admin",    "UASAdmin", "UASAdmin.application"])
            ws_apps.append(["designer", "Designer", "Designer", "HealthEdge.Designer.application"])
            wb.save(str(UI_APPS_CONFIG))
            return
        # Back-fill any keys missing from an existing config file
        wb = _xl.load_workbook(str(UI_APPS_CONFIG))
        ws_cfg = wb["Config"] if "Config" in wb.sheetnames else wb.active
        existing_keys = set()
        for row in ws_cfg.iter_rows(min_row=2, values_only=True):
            if row[0]:
                existing_keys.add(str(row[0]).strip())
        changed = False
        for k, v in _defaults.items():
            if k not in existing_keys:
                ws_cfg.append([k, v])
                changed = True
        if changed:
            wb.save(str(UI_APPS_CONFIG))

    def _read_ui_apps_config():
        import openpyxl as _xl
        _ensure_ui_apps_config()
        wb = _xl.load_workbook(str(UI_APPS_CONFIG))
        ws_cfg = wb["Config"]
        config = {}
        for row in ws_cfg.iter_rows(min_row=2, values_only=True):
            if row[0]:
                config[str(row[0]).strip()] = str(row[1] or "").strip()
        ws_apps = wb["Apps"]
        headers = [c.value for c in next(ws_apps.iter_rows(min_row=1, max_row=1))]
        apps = []
        for row in ws_apps.iter_rows(min_row=2, values_only=True):
            if row[0]:
                apps.append({h: (str(v).strip() if v is not None else "")
                              for h, v in zip(headers, row)})
        return config, apps

    def _write_ui_apps_config(config_updates):
        import openpyxl as _xl
        _ensure_ui_apps_config()
        wb = _xl.load_workbook(str(UI_APPS_CONFIG))
        ws_cfg = wb["Config"]
        existing = {}
        for i, row in enumerate(ws_cfg.iter_rows(min_row=2), start=2):
            if row[0].value:
                existing[str(row[0].value).strip()] = i
        for k, v in config_updates.items():
            if k in existing:
                ws_cfg.cell(row=existing[k], column=2, value=v)
            else:
                ws_cfg.append([k, v])
        wb.save(str(UI_APPS_CONFIG))

    def _clean_version(ver):
        import re as _re
        m = _re.search(r'\d+\.\d+\.\d+\.\d+', ver)
        return m.group(0) if m else ver.replace("release-", "").strip("-")

    def _sync_he_ui_client(rows):
        import openpyxl as _xl
        path = HE_UI_CLIENT_XLSX
        cols = ["Application", "Version", "Installers", "InstalledAt"]
        if not path.exists():
            wb = _xl.Workbook(); ws = wb.active; ws.title = "Tracking"
            ws.append(cols)
        else:
            wb = _xl.load_workbook(str(path))
            ws = wb["Tracking"] if "Tracking" in wb.sheetnames else wb.create_sheet("Tracking")
            if ws.max_row < 1 or ws.cell(1, 1).value != "Application":
                ws.insert_rows(1); ws.append(cols)  # safety: shouldn't happen
        existing = {}
        for i, row in enumerate(ws.iter_rows(min_row=2), start=2):
            if row[0].value:
                existing[str(row[0].value)] = i
        for rd in rows:
            if rd["Application"] in existing:
                for j, col in enumerate(cols, 1):
                    ws.cell(row=existing[rd["Application"]], column=j, value=rd[col])
            else:
                ws.append([rd[c] for c in cols])
        wb.save(str(path))

    _clickonce_versions_cache = {"versions": None, "ts": 0.0}

    def _fetch_clickonce_versions(base_url):
        import time as _time2, re as _re4
        import urllib.request as _urlreq2
        now = _time2.time()
        if (_clickonce_versions_cache["versions"] is not None
                and now - _clickonce_versions_cache["ts"] < 300):
            return _clickonce_versions_cache["versions"]
        try:
            url = base_url.rstrip("/") + "/"
            req = _urlreq2.Request(url, headers={"User-Agent": "IDP/1.0"})
            with _urlreq2.urlopen(req, timeout=5) as resp:
                html = resp.read().decode("utf-8", errors="replace")
            # Match href values that look like release-X.Y.Z or master (with optional trailing /)
            raw = _re4.findall(
                r'href=["\']([^"\'#?]*(?:release-[\d.]+|master)/?)["\']', html, _re4.I)
            versions = []
            seen = set()
            for v in raw:
                v = v.rstrip("/").split("/")[-1]
                if v and v not in seen:
                    seen.add(v)
                    versions.append(v)
            _clickonce_versions_cache["versions"] = versions
            _clickonce_versions_cache["ts"] = now
            return versions
        except Exception:
            return _clickonce_versions_cache["versions"] or []

    def _parse_release_tuple(ver):
        import re as _re5
        # Accept X.Y.Z (3-part) or X.Y (2-part, padded to (X, Y, 0)) so that
        # "27.1" and "release-27.1.0.0" both produce comparable tuples.
        m = _re5.search(r'(\d+)\.(\d+)(?:\.(\d+))?', ver)
        if not m:
            return None
        return (int(m.group(1)), int(m.group(2)), int(m.group(3) or 0))

    def _find_best_ui_version(deployed_ver, available_versions):
        if not available_versions:
            return deployed_ver
        if "master" in deployed_ver.lower():
            return "master" if "master" in available_versions else deployed_ver
        deployed_tuple = _parse_release_tuple(deployed_ver)
        if deployed_tuple is None:
            return deployed_ver
        candidates = []
        for v in available_versions:
            t = _parse_release_tuple(v)
            if t and t <= deployed_tuple:
                candidates.append((t, v))
        if not candidates:
            return deployed_ver
        candidates.sort(key=lambda x: x[0])
        return candidates[-1][1]

    def _get_ui_apps_with_status():
        import json as _json2
        config, app_defs = _read_ui_apps_config()
        base            = config.get("base_url", "").rstrip("/")
        # Auto-detect deployed version from deployed_info.json; fall back to Excel config
        ver = config.get("version", "")
        _detected_release_ver = ""
        try:
            if _DEPLOYED_INFO_FILE.exists():
                _di = _json2.loads(_DEPLOYED_INFO_FILE.read_text(encoding="utf-8"))
                _branch      = (_di.get("branch")      or "").strip()
                _release_ver = (_di.get("release_ver") or "").strip()
                _detected_release_ver = _release_ver
                if _branch.lower() == "master":
                    ver = "master"
                elif _release_ver:
                    ver = f"release-{_release_ver}"
                elif _branch:
                    ver = _branch
        except Exception:
            pass
        # Resolve the best available UI version from the ClickOnce server
        available = _fetch_clickonce_versions(base) if base else []
        ui_ver    = _find_best_ui_version(ver, available) if available else ver
        ui_clean  = _clean_version(ui_ver)
        # For master builds with a known release version, use the release version dir
        # for install checks (master IS that release); download URL still uses "master".
        _install_clean = (
            _clean_version(f"release-{_detected_release_ver}")
            if ver == "master" and _detected_release_ver
            else ui_clean
        )
        config["version"]    = ver       # reflect auto-detected deployed version
        config["ui_version"] = ui_ver
        inst_base_str    = _expand_cfg_path(config.get("installers_base", ""))
        inst_base        = Path(inst_base_str) if inst_base_str else HE_UI_INSTALLERS_BASE
        instd_base_str   = _expand_cfg_path(config.get("installed_base", ""))
        instd_base       = Path(instd_base_str) if instd_base_str else HE_UI_INSTALLED_BASE
        result, he_rows = [], []
        for app in app_defs:
            name         = app.get("display_name", "")
            url          = f"{base}/{ui_ver}/{app.get('folder','')}/{app.get('app_file','')}"
            installers   = inst_base / name / _install_clean
            installed_at = instd_base / name / _install_clean
            ver_for_dir  = _install_clean
            # Redirect only for "master" builds: master_version.txt records which
            # numeric version was actually downloaded (e.g. "26.1") so the install
            # directory can be found.  Skipped for explicit release versions to
            # avoid a stale master_version.txt hiding a new version.
            if ver_for_dir == "master":
                import re as _re_vd
                _marker = inst_base / name / "master_version.txt"
                if _marker.exists():
                    try:
                        _mv_str = _marker.read_text(encoding="utf-8").strip()
                        if _re_vd.match(r'\d+\.\d+', _mv_str):
                            _redir_inst = inst_base / name / _mv_str
                            if _redir_inst.resolve() != installers.resolve():
                                ver_for_dir  = _mv_str
                                installers   = _redir_inst
                                installed_at = instd_base / name / ver_for_dir
                    except Exception:
                        pass
            downloaded   = False
            if installers.exists():
                if (installers / ".download_complete").exists():
                    downloaded = True
                else:
                    for _ext in (".exe", ".msi"):
                        if list(installers.glob(f"*{_ext}")):
                            downloaded = True; break
            # Prefer xlsx-tracked install info over directory existence check
            try:
                install_info = _get_ui_installation(name, ver_for_dir)
            except Exception:
                install_info = None
            if install_info:
                install_path = install_info.get("InstallPath", "")
                main_exe     = install_info.get("MainExe", "")
                installed    = bool(install_path and Path(install_path).exists())
            else:
                install_path = str(installed_at)
                main_exe     = ""
                installed    = installed_at.exists()
            result.append({**app, "url": url, "version": ver_for_dir,
                           "installers": str(installers), "installed_at": install_path,
                           "installed": installed, "downloaded": downloaded, "main_exe": main_exe})
        return config, result

    # ── Stats helpers (HE_UI_Client.xlsx "Stats" sheet) ───────────────────────

    def _get_ui_stats(app_name, stat_type):
        import openpyxl as _xl
        if not HE_UI_CLIENT_XLSX.exists():
            return []
        wb = _xl.load_workbook(str(HE_UI_CLIENT_XLSX))
        if "Stats" not in wb.sheetnames:
            return []
        rows = []
        for row in wb["Stats"].iter_rows(min_row=2, values_only=True):
            if row[0] == app_name and row[1] == stat_type:
                rows.append({"duration": float(row[3] or 0), "file_size": int(row[4] or 0),
                             "timestamp": str(row[2] or "")})
        rows.sort(key=lambda r: r["timestamp"])
        return rows[-10:]

    def _record_ui_stat(app_name, stat_type, duration, file_size):
        import openpyxl as _xl
        from datetime import datetime as _dt
        path = HE_UI_CLIENT_XLSX
        wb = _xl.load_workbook(str(path)) if path.exists() else _xl.Workbook()
        if "Tracking" not in wb.sheetnames:
            ws_t = wb.active; ws_t.title = "Tracking"
            ws_t.append(["Application", "Version", "Installers", "InstalledAt"])
        if "Stats" not in wb.sheetnames:
            ws = wb.create_sheet("Stats")
            ws.append(["Application", "Type", "Timestamp", "DurationSeconds", "FileSizeBytes"])
        else:
            ws = wb["Stats"]
        ws.append([app_name, stat_type, _dt.now().isoformat(), round(duration, 2), int(file_size)])
        # Keep only last 10 per (app_name, stat_type) — delete oldest
        matching = [r[0].row for r in ws.iter_rows(min_row=2)
                    if r[0].value == app_name and r[1].value == stat_type]
        for row_num in reversed(matching[:-10]):
            ws.delete_rows(row_num, 1)
        wb.save(str(path))

    def _estimate_duration(app_name, stat_type, total_bytes=None):
        stats = _get_ui_stats(app_name, stat_type)
        if not stats:
            return None
        if stat_type == "download" and total_bytes and total_bytes > 0:
            speeds = [s["file_size"] / s["duration"]
                      for s in stats if s["duration"] > 0 and s["file_size"] > 0]
            if speeds:
                return total_bytes / (sum(speeds) / len(speeds))
        else:
            durations = [s["duration"] for s in stats if s["duration"] > 0]
            if durations:
                return sum(durations) / len(durations)
        return None

    # ── Background threads ────────────────────────────────────────────────────

    def _do_download(app_id, url, dest_path, app_name):
        """Download .application manifest then prefetch all app files into the
        installer cache so that Run Installer works fully offline."""
        import urllib.request as _urlreq, ssl as _ssl, time as _time, os as _os
        import xml.etree.ElementTree as _ET2, urllib.parse as _uparse2
        _ctx = _ssl.create_default_context()
        _ctx.check_hostname = False; _ctx.verify_mode = _ssl.CERT_NONE
        start = _time.time()

        def _upd(**kw):
            with _ui_downloads_lock:
                if app_id in _ui_downloads:
                    _ui_downloads[app_id].update(kw)

        def _encode_path2(raw):
            segments = raw.replace("\\", "/").split("/")
            return "/".join(_uparse2.quote(s, safe="") for s in segments)

        def _fetch_raw(src_url):
            req = _urlreq.Request(src_url, headers={"User-Agent": "Mozilla/5.0"})
            with _urlreq.urlopen(req, context=_ctx, timeout=120) as r:
                return r.read()

        try:
            dest_path.parent.mkdir(parents=True, exist_ok=True)
            _upd(status="downloading", phase_label="Downloading manifest…",
                 percent=0, downloaded=0, elapsed=0, speed=0)

            # ── Step 1: download .application ───────────────────────────────
            app_data = _fetch_raw(url)
            with open(str(dest_path), "wb") as f:
                f.write(app_data)

            # ── Step 2: parse .application → .exe.manifest URL ──────────────
            base_url = url.rsplit("/", 1)[0]
            try:
                root2 = _ET2.fromstring(app_data)
            except Exception:
                # Manifest not parseable — just save the .application and finish
                _upd(status="done", percent=100, elapsed=_time.time()-start,
                     downloaded=len(app_data), remaining=0, filename=dest_path.name)
                return

            # Extract real release version from assemblyIdentity and redirect dirs
            import re as _re_v2
            for _ev in root2.iter():
                _tv = _ev.tag.split("}")[-1] if "}" in _ev.tag else _ev.tag
                if _tv == "assemblyIdentity":
                    _av = _ev.get("version", "")
                    if _av and _av != "0.0.0.0":
                        _mv = _re_v2.search(r'(\d+)\.(\d+)\.\d+\.\d+', _av)
                        if _mv:
                            _ver_clean = f"{_mv.group(1)}.{_mv.group(2)}"
                            # Write marker so status can map branch→version
                            (dest_path.parent.parent / "master_version.txt").write_text(
                                _ver_clean, encoding="utf-8")
                            # Redirect dest_path to versioned directory only if not already there
                            _new_dir = dest_path.parent.parent / _ver_clean
                            if _new_dir.resolve() != dest_path.parent.resolve():
                                _new_dir.mkdir(parents=True, exist_ok=True)
                                import shutil as _shu_v
                                _shu_v.copy2(str(dest_path), str(_new_dir / dest_path.name))
                                import os as _os_v
                                try:
                                    _os_v.remove(str(dest_path))
                                except Exception:
                                    pass
                                dest_path = _new_dir / dest_path.name
                    break

            exe_manifest_rel = None
            for elem in root2.iter():
                cb = elem.get("codebase", "")
                if cb.endswith(".manifest") and ".exe.manifest" in cb:
                    exe_manifest_rel = cb; break
                if not exe_manifest_rel and cb.endswith(".manifest"):
                    exe_manifest_rel = cb

            if not exe_manifest_rel:
                _upd(status="done", percent=100, elapsed=_time.time()-start,
                     downloaded=len(app_data), remaining=0, filename=dest_path.name)
                return

            # ── Step 3: download .exe.manifest ───────────────────────────────
            _upd(phase_label="Fetching file list…", percent=3)
            exe_manifest_url = f"{base_url}/{_encode_path2(exe_manifest_rel)}"
            exe_manifest_data = _fetch_raw(exe_manifest_url)
            # Save .exe.manifest alongside .application for offline install
            rel_parts = exe_manifest_rel.replace("\\", "/").split("/")
            exe_manifest_local = dest_path.parent.joinpath(*rel_parts)
            exe_manifest_local.parent.mkdir(parents=True, exist_ok=True)
            exe_manifest_local.write_bytes(exe_manifest_data)

            # ── Step 4: parse .exe.manifest → file list ──────────────────────
            try:
                exe_root2 = _ET2.fromstring(exe_manifest_data)
            except Exception:
                _upd(status="done", percent=100, elapsed=_time.time()-start,
                     downloaded=len(app_data), remaining=0, filename=dest_path.name)
                return

            files2 = []
            for elem in exe_root2.iter():
                tag2 = elem.tag.split("}")[-1] if "}" in elem.tag else elem.tag
                if tag2 == "file":
                    fname2 = elem.get("name", "")
                    size2  = int(elem.get("size", 0))
                    if fname2:
                        files2.append({"name": fname2, "size": size2})
                elif tag2 == "dependentAssembly" and elem.get("dependencyType") == "install":
                    codebase2 = elem.get("codebase", "")
                    size2     = int(elem.get("size", 0))
                    if codebase2 and not codebase2.endswith(".manifest"):
                        files2.append({"name": codebase2, "size": size2})

            if not files2:
                _upd(status="done", percent=100, elapsed=_time.time()-start,
                     downloaded=len(app_data), remaining=0, filename=dest_path.name)
                return

            # Prepend the main exe (not listed in <file> elements — derived from manifest name)
            _mf_name2 = Path(exe_manifest_rel.replace("\\", "/")).name
            if _mf_name2.endswith(".manifest"):
                _main_exe_base2 = _mf_name2[:-len(".manifest")]
                if not any(f["name"].lower() == _main_exe_base2.lower() for f in files2):
                    files2.insert(0, {"name": _main_exe_base2, "size": 0})

            # ── Step 5: download all .deploy files into installer cache ───────
            app_files_base = exe_manifest_url.rsplit("/", 1)[0]
            total_bytes = sum(f["size"] for f in files2)
            _upd(total=total_bytes, downloaded=0, file_count=len(files2),
                 phase_label=f"Downloading {len(files2)} files…", percent=5)

            downloaded_bytes = 0
            for idx, finfo in enumerate(files2, 1):
                # Honour abort request
                with _ui_downloads_lock:
                    if _ui_downloads.get(app_id, {}).get("abort"):
                        _upd(status="aborted", error="Download aborted by user.")
                        return

                fname2   = finfo["name"]
                # Store with .deploy extension so install can distinguish cache from installed
                rel_parts2   = fname2.replace("\\", "/").split("/")
                cached_path  = dest_path.parent.joinpath(*rel_parts2)
                cached_deploy = Path(str(cached_path) + ".deploy")

                if not cached_deploy.exists():
                    file_url = f"{app_files_base}/{_encode_path2(fname2)}.deploy"
                    _upd(phase_label=f"[{idx}/{len(files2)}] {fname2}", current_file=fname2)
                    raw = _fetch_raw(file_url)
                    cached_deploy.parent.mkdir(parents=True, exist_ok=True)
                    cached_deploy.write_bytes(raw)
                    downloaded_bytes += len(raw)
                else:
                    downloaded_bytes += cached_deploy.stat().st_size

                elapsed = _time.time() - start
                pct = 5 + int(downloaded_bytes / total_bytes * 94) if total_bytes > 0 else 5
                speed = downloaded_bytes / elapsed if elapsed > 0 else 0
                remaining = ((total_bytes - downloaded_bytes) / speed) if speed > 0 else None
                _upd(downloaded=downloaded_bytes, percent=pct, elapsed=elapsed,
                     speed=speed, remaining=remaining)

            elapsed = _time.time() - start
            # Write completion marker so status check knows ALL files downloaded successfully
            try:
                (dest_path.parent / ".download_complete").write_text("ok", encoding="utf-8")
            except Exception:
                pass
            _upd(status="done", percent=100, elapsed=elapsed, downloaded=downloaded_bytes,
                 remaining=0, filename=dest_path.name)
            try:
                _record_ui_stat(app_name, "download", elapsed, downloaded_bytes)
            except Exception:
                pass
        except Exception as e:
            _upd(status="error", error=f"{e} — URL: {url}")

    # ── HE_UI_Client.xlsx install tracking ───────────────────────────────────

    _TRACK_COLS = ["Application", "Version", "Source", "InstallPath", "MainExe", "ServerIP", "InstalledAt"]

    def _record_ui_installation(app_name, version, source, install_path, main_exe, server_ip=""):
        import openpyxl as _xl
        from datetime import datetime as _dt
        path = HE_UI_CLIENT_XLSX
        if path.exists():
            wb = _xl.load_workbook(str(path))
        else:
            wb = _xl.Workbook()
        ws_name = "Tracking"
        if ws_name not in wb.sheetnames:
            ws = wb.create_sheet(ws_name)
            ws.append(_TRACK_COLS)
        else:
            ws = wb[ws_name]
            # Ensure header matches current schema (handles old ["Application","Version","Installers","InstalledAt"] schema)
            cur_header = [ws.cell(1, j).value for j in range(1, len(_TRACK_COLS) + 1)]
            if cur_header != _TRACK_COLS:
                if ws.max_row < 1 or ws.cell(1, 1).value is None:
                    # Empty sheet — write header at row 1
                    for j, c in enumerate(_TRACK_COLS, 1):
                        ws.cell(1, j).value = c
                else:
                    # Header row exists but uses old column names — update in place
                    # Data column positions are unchanged: Application=1, Version=2,
                    # old"Installers"/new"Source"=3, old"InstalledAt"/new"InstallPath"=4
                    for j, c in enumerate(_TRACK_COLS, 1):
                        ws.cell(1, j).value = c
        found_row = None
        for i, row in enumerate(ws.iter_rows(min_row=2), start=2):
            if str(row[0].value or "") == app_name and str(row[1].value or "") == version:
                found_row = i; break
        vals = [app_name, version, source, install_path, main_exe, server_ip, _dt.now().isoformat()]
        if found_row:
            for j, v in enumerate(vals, 1):
                ws.cell(found_row, j).value = v
        else:
            ws.append(vals)
        wb.save(str(path))

    def _get_ui_installation(app_name, version):
        import openpyxl as _xl
        if not HE_UI_CLIENT_XLSX.exists():
            return None
        wb = _xl.load_workbook(str(HE_UI_CLIENT_XLSX))
        ws_name = "Tracking"
        if ws_name not in wb.sheetnames:
            return None
        ws = wb[ws_name]
        headers = [ws.cell(1, j).value for j in range(1, ws.max_column + 1)]
        for row in ws.iter_rows(min_row=2, values_only=True):
            if str(row[0] or "") == app_name and str(row[1] or "") == version:
                info = {h: (row[j] or "") for j, h in enumerate(headers) if h}
                # Compatibility: old schema used "InstalledAt" for the install path
                if not info.get("InstallPath") and info.get("InstalledAt"):
                    info["InstallPath"] = info["InstalledAt"]
                return info
        return None

    def _remove_ui_installation(app_name, version):
        import openpyxl as _xl
        if not HE_UI_CLIENT_XLSX.exists():
            return
        wb = _xl.load_workbook(str(HE_UI_CLIENT_XLSX))
        if "Tracking" not in wb.sheetnames:
            return
        ws = wb["Tracking"]
        for i, row in enumerate(ws.iter_rows(min_row=2), start=2):
            if str(row[0].value or "") == app_name and str(row[1].value or "") == version:
                ws.delete_rows(i, 1); break
        wb.save(str(HE_UI_CLIENT_XLSX))

    # ── Direct ClickOnce installation (no popup / no security dialog) ─────────

    def _do_install_direct(app_id, installer_path, app_url, install_dir, app_name, version, weblogic_url=None):
        """Parse the .application manifest and download all app files directly."""
        import xml.etree.ElementTree as _ET
        import urllib.request as _urlreq
        import ssl as _ssl, time as _time, urllib.parse as _uparse

        _ctx = _ssl.create_default_context()
        _ctx.check_hostname = False
        _ctx.verify_mode = _ssl.CERT_NONE
        start = _time.time()

        def _upd(**kw):
            with _ui_install_ops_lock:
                if app_id in _ui_install_ops:
                    _ui_install_ops[app_id].update(kw)

        def _fetch_bytes(url):
            req = _urlreq.Request(url, headers={"User-Agent": "Mozilla/5.0"})
            with _urlreq.urlopen(req, context=_ctx, timeout=120) as r:
                return r.read()

        try:
            # Determine source and server IP from app_url
            parsed = _uparse.urlparse(app_url)
            server_ip = parsed.hostname or ""
            source = "Local" if server_ip in ("localhost", "127.0.0.1") else "Remote"
            base_url = app_url.rsplit("/", 1)[0]

            _upd(status="installing", phase_label="Parsing manifest…", percent=0)

            # 1. Parse the local .application manifest to get the .exe.manifest path
            tree = _ET.parse(str(installer_path))
            root = tree.getroot()
            exe_manifest_rel = None
            for elem in root.iter():
                cb = elem.get("codebase", "")
                if cb.endswith(".manifest") and ".exe.manifest" in cb:
                    exe_manifest_rel = cb; break
                # Fallback: any .manifest codebase
                if not exe_manifest_rel and cb.endswith(".manifest"):
                    exe_manifest_rel = cb

            if not exe_manifest_rel:
                raise RuntimeError("Cannot find .exe.manifest reference in .application")

            def _encode_path(raw):
                """Normalize backslashes and percent-encode each path segment."""
                segments = raw.replace("\\", "/").split("/")
                return "/".join(_uparse.quote(s, safe="") for s in segments)

            exe_manifest_url = f"{base_url}/{_encode_path(exe_manifest_rel)}"
            _upd(phase_label="Loading manifest…", percent=2)

            # 2. Load .exe.manifest — prefer locally-cached copy (from prefetch download)
            rel_parts_m = exe_manifest_rel.replace("\\", "/").split("/")
            local_manifest = installer_path.parent.joinpath(*rel_parts_m)
            if local_manifest.exists():
                exe_manifest_content = local_manifest.read_bytes()
            else:
                _upd(phase_label="Downloading manifest…", percent=2)
                exe_manifest_content = _fetch_bytes(exe_manifest_url)

            exe_root = _ET.fromstring(exe_manifest_content)

            files = []
            for elem in exe_root.iter():
                tag = elem.tag.split("}")[-1] if "}" in elem.tag else elem.tag
                if tag == "file":
                    fname = elem.get("name", "")
                    size  = int(elem.get("size", 0))
                    if fname:
                        files.append({"name": fname, "size": size})
                elif tag == "dependentAssembly" and elem.get("dependencyType") == "install":
                    codebase = elem.get("codebase", "")
                    size     = int(elem.get("size", 0))
                    # Skip nested .manifest references (sub-manifests, not direct files)
                    if codebase and not codebase.endswith(".manifest"):
                        files.append({"name": codebase, "size": size})

            if not files:
                raise RuntimeError("No files found in .exe.manifest")

            # The main exe is not listed in <file> elements — it IS the assembly.
            # Derive its name from the .exe.manifest filename and prepend it.
            _mf_name = Path(exe_manifest_rel.replace("\\", "/")).name
            if _mf_name.endswith(".manifest"):
                _main_exe_base = _mf_name[:-len(".manifest")]
                if not any(f["name"].lower() == _main_exe_base.lower() for f in files):
                    files.insert(0, {"name": _main_exe_base, "size": 0})

            app_files_base = exe_manifest_url.rsplit("/", 1)[0]
            total_bytes = sum(f["size"] for f in files)
            _upd(total=total_bytes, downloaded=0, file_count=len(files),
                 phase_label=f"Installing {len(files)} files…", percent=5)

            # 3. Copy/download all files — use local .deploy cache when available
            install_dir.mkdir(parents=True, exist_ok=True)
            downloaded_bytes = 0
            exe_candidates = []   # (path_str, name_matches_app)
            skipped_files  = []
            # Utility exes bundled by ClickOnce that should never be the launch target
            _TOOL_EXES = {"7za.exe", "7z.exe", "7zfm.exe", "7zg.exe",
                          "setup.exe", "uninstall.exe", "updater.exe",
                          "crashreporter.exe", "squirrel.exe"}

            for idx, finfo in enumerate(files, 1):
                # Honour abort request
                with _ui_install_ops_lock:
                    if _ui_install_ops.get(app_id, {}).get("abort"):
                        _upd(status="aborted", error="Installation aborted by user.")
                        return

                fname = finfo["name"]
                local_path = install_dir / fname
                local_path.parent.mkdir(parents=True, exist_ok=True)

                _upd(current_file=fname, current_num=idx,
                     phase_label=f"[{idx}/{len(files)}] {fname}")

                # Check local .deploy cache from prefetch download
                rel_parts_f = fname.replace("\\", "/").split("/")
                cached_deploy = Path(str(installer_path.parent.joinpath(*rel_parts_f)) + ".deploy")

                try:
                    if cached_deploy.exists():
                        import shutil as _shutil2
                        _shutil2.copy2(str(cached_deploy), str(local_path))
                        downloaded_bytes += cached_deploy.stat().st_size
                    else:
                        file_url = f"{app_files_base}/{_encode_path(fname)}.deploy"
                        req = _urlreq.Request(file_url, headers={"User-Agent": "Mozilla/5.0"})
                        with _urlreq.urlopen(req, context=_ctx, timeout=30) as resp:
                            with open(str(local_path), "wb") as out:
                                while True:
                                    chunk = resp.read(65536)
                                    if not chunk: break
                                    out.write(chunk)
                                    downloaded_bytes += len(chunk)
                except OSError as _fe:
                    if getattr(_fe, "winerror", None) == 32 and local_path.exists():
                        # File locked by running process — already present, skip safely
                        downloaded_bytes += local_path.stat().st_size
                    else:
                        skipped_files.append(fname)
                        _upd(phase_label=f"[{idx}/{len(files)}] SKIPPED: {Path(fname).name} ({_fe})")
                    continue
                except Exception as _fe:
                    skipped_files.append(fname)
                    _upd(phase_label=f"[{idx}/{len(files)}] SKIPPED: {Path(fname).name} (server unreachable)")
                    continue

                pct = 5 + int((downloaded_bytes / total_bytes * 94)) if total_bytes > 0 else 5
                _upd(downloaded=downloaded_bytes, percent=pct, elapsed=_time.time() - start)

                if fname.lower().endswith(".exe"):
                    basename = Path(fname).name.lower()
                    if basename not in _TOOL_EXES and not basename.startswith("uninstall"):
                        name_match = app_name.lower() in basename
                        exe_candidates.append((str(local_path), name_match))

            # Pick best exe: prefer name-matching, then first non-tool candidate
            preferred_exes = [p for p, m in exe_candidates if m]
            main_exe = preferred_exes[0] if preferred_exes else (exe_candidates[0][0] if exe_candidates else None)

            elapsed = _time.time() - start
            try:
                _record_ui_installation(app_name, version, source,
                                        str(install_dir), main_exe or "", server_ip)
            except Exception:
                pass
            try:
                _record_ui_stat(app_name, "install", elapsed, total_bytes)
            except Exception:
                pass
            # Post-install: patch server config to point at correct server URL
            _cfg_names = {
                "manager":  "healthedge.manager.config",
                "designer": "healthedge.designer.config",
            }
            _app_name_lower = app_name.lower().replace("remote_payor_", "")
            if _app_name_lower in ("manager", "admin", "designer"):
                try:
                    import re as _re_cfg, subprocess as _sp_cfg, getpass as _gp
                    _svc_url = weblogic_url if weblogic_url else "http://localhost:7001/web-services/"

                    # Resolve display name: VM name from vms.xlsx (remote) or git username (local)
                    if weblogic_url:
                        _vm_ip_for_name = _uparse.urlparse(weblogic_url).hostname or ""
                        _display_name = ""
                        if _vm_ip_for_name and VMS_FILE.exists():
                            try:
                                import openpyxl as _xl_cfg
                                _wb_cfg = _xl_cfg.load_workbook(str(VMS_FILE))
                                _ws_cfg = _wb_cfg[_wb_cfg.sheetnames[0]]
                                _hdrs_cfg = [str(_ws_cfg.cell(1, c).value or "").strip().lower()
                                             for c in range(1, _ws_cfg.max_column + 1)]
                                for _row_cfg in _ws_cfg.iter_rows(min_row=2, values_only=True):
                                    _d_cfg = {k: ("" if v is None else str(v).strip())
                                               for k, v in zip(_hdrs_cfg, _row_cfg)}
                                    if _d_cfg.get("ip", "") == _vm_ip_for_name:
                                        _display_name = _d_cfg.get("name", "")
                                        break
                            except Exception:
                                pass
                        if not _display_name:
                            _display_name = _vm_ip_for_name or "Remote"
                    else:
                        try:
                            _si = _sp_cfg.STARTUPINFO()
                            _si.dwFlags |= _sp_cfg.STARTF_USESHOWWINDOW
                            _git_name = _sp_cfg.check_output(
                                ["git", "config", "user.name"],
                                stderr=_sp_cfg.DEVNULL, timeout=5,
                                startupinfo=_si,
                                creationflags=_sp_cfg.CREATE_NO_WINDOW,
                            ).decode(errors="replace").strip()
                            _display_name = _git_name.split()[0] if _git_name else ""
                        except Exception:
                            _display_name = ""
                        if not _display_name:
                            _display_name = _gp.getuser()

                    # Use explicit filename if known; for Admin scan for the right file
                    _known = _cfg_names.get(_app_name_lower)
                    if _known:
                        _cfg_candidates = [install_dir / _known]
                    else:
                        _cfg_candidates = [p for p in install_dir.glob("*.config")
                                           if not p.name.lower().endswith(".exe.config")]
                    for _cfg_path in _cfg_candidates:
                        if not _cfg_path.exists():
                            continue
                        _cfg_text = _cfg_path.read_text(encoding="utf-8", errors="replace")
                        if "<URL>" not in _cfg_text or "<Servers>" not in _cfg_text:
                            continue
                        _cfg_text = _re_cfg.sub(
                            r'<URL>.*?</URL>',
                            f'<URL>{_svc_url}</URL>',
                            _cfg_text)
                        _nvi = f'<NameValueItem name="{_display_name}" value="{_svc_url}" />'
                        _cfg_text = _re_cfg.sub(
                            r'<Servers>.*?</Servers>',
                            f'<Servers>\n        {_nvi}\n    </Servers>',
                            _cfg_text, flags=_re_cfg.DOTALL)
                        _cfg_path.write_text(_cfg_text, encoding="utf-8")
                        break
                except Exception:
                    pass

            _warn = f" ({len(skipped_files)} file(s) skipped — re-download for full install)" if skipped_files else ""
            _upd(status="done", percent=100, elapsed=elapsed, main_exe=main_exe or "", warning=_warn)

        except Exception as e:
            _upd(status="error", error=str(e))

