    @app.route("/api/local-app/payor/ui-apps/<app_id>/run-installer", methods=["POST"])
    def api_ui_apps_run_installer(app_id):
        try:
            import threading as _thr
            _, apps = _get_ui_apps_with_status()
            app_obj = next((a for a in apps if a["app_id"] == app_id), None)
            if not app_obj:
                return jsonify({"ok": False, "error": f"Unknown app: {app_id}"})
            inst_dir = Path(app_obj["installers"])
            target = None
            if inst_dir.exists():
                for ext in (".application", ".exe", ".msi"):
                    hits = list(inst_dir.glob(f"*{ext}"))
                    if hits:
                        target = hits[0]; break
            if not target:
                return jsonify({"ok": False, "error": f"No installer found in {inst_dir}"})
            config_inner, _ = _read_ui_apps_config()
            instd_str = _expand_cfg_path(config_inner.get("installed_base", ""))
            instd_root = Path(instd_str) if instd_str else HE_UI_INSTALLED_BASE
            install_dir = instd_root / app_obj["display_name"] / app_obj["version"]
            with _ui_install_ops_lock:
                _ui_install_ops[app_id] = {"status": "installing", "percent": 0, "elapsed": 0,
                                           "phase_label": "Starting…", "error": None}
            _thr.Thread(
                target=_do_install_direct,
                args=(app_id, target, app_obj["url"], install_dir,
                      app_obj["display_name"], app_obj["version"]),
                daemon=True,
            ).start()
            return jsonify({"ok": True})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

