    @app.route("/api/local-app/payor/ui-apps/<app_id>/open", methods=["POST"])
    def api_ui_apps_open(app_id):
        try:
            import subprocess as _subp, time as _t
            _, apps = _get_ui_apps_with_status()
            app_obj = next((a for a in apps if a["app_id"] == app_id), None)
            if not app_obj:
                return jsonify({"ok": False, "error": f"Unknown app: {app_id}"})

            def _launch(exe_path):
                exe = Path(exe_path)
                si = _subp.STARTUPINFO()
                si.dwFlags  = _subp.STARTF_USESHOWWINDOW
                si.wShowWindow = 1  # SW_SHOWNORMAL
                proc = _subp.Popen(
                    [str(exe)],
                    cwd=str(exe.parent),
                    startupinfo=si,
                    creationflags=_subp.DETACHED_PROCESS | _subp.CREATE_NEW_PROCESS_GROUP,
                )
                # Give the process a moment to start; if it exits immediately it crashed
                _t.sleep(1.5)
                if proc.poll() is not None:
                    raise RuntimeError(
                        f"Process exited immediately (code {proc.returncode}). "
                        f"Exe: {exe}"
                    )
                return str(exe)

            _SKIP_TOOLS = {"7za.exe", "7z.exe", "7zfm.exe", "7zg.exe",
                           "setup.exe", "uninstall.exe", "updater.exe",
                           "crashreporter.exe", "squirrel.exe"}

            def _is_tool_exe(p):
                n = Path(p).name.lower()
                return n in _SKIP_TOOLS or n.startswith("uninstall")

            main_exe = app_obj.get("main_exe", "")
            if main_exe and Path(main_exe).exists() and not _is_tool_exe(main_exe):
                launched = _launch(main_exe)
                return jsonify({"ok": True, "message": f"Opened: {launched}"})
            # Fallback: find main exe in install directory (prefer app-named, skip tools)
            install_dir = Path(app_obj.get("installed_at", ""))
            if not install_dir.exists():
                return jsonify({"ok": False, "error": "Application is not installed. Please download and install first."})
            all_exes = [e for e in install_dir.rglob("*.exe")
                        if not _is_tool_exe(e)]
            app_name_lower = app_obj.get("display_name", "").lower()
            preferred = [e for e in all_exes if app_name_lower in e.name.lower()]
            hit = preferred[0] if preferred else (all_exes[0] if all_exes else None)
            if hit:
                launched = _launch(hit)
                return jsonify({"ok": True, "message": f"Opened: {launched}"})
            return jsonify({"ok": False, "error": f"No launchable executable found in {install_dir}. Try re-installing."})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

