    def _version_env_type(release_ver):
        """WebLogic before 26.1, Tomcat from 26.1 onwards; empty if version unknown."""
        try:
            parts = str(release_ver or "").split(".")
            major = int(parts[0])
            minor = int(parts[1]) if len(parts) > 1 else 0
            if major > 26 or (major == 26 and minor >= 1):
                return "Tomcat"
            return "WebLogic"
        except (ValueError, IndexError):
            return ""

