    def _select_by_version(entries, version_num):
        """Select value from [{value, condition}] list.
        = has highest precedence; unconditional row is fallback."""
        import re as _rvc
        def _parse_ver(s):
            parts = str(s or "").split(".")
            try:
                return int(parts[0]) * 1000 + (int(parts[1]) if len(parts) > 1 else 0)
            except (ValueError, IndexError):
                return 0
        def _eval(cond, v):
            if not cond:
                return True, False
            cond = cond.strip()
            and_parts = _rvc.split(r'\s+and\s+', cond, flags=_rvc.IGNORECASE)
            if len(and_parts) > 1:
                results = [_eval(p.strip(), v) for p in and_parts]
                return all(r[0] for r in results), all(r[1] for r in results)
            or_parts = _rvc.split(r'\s+or\s+', cond, flags=_rvc.IGNORECASE)
            if len(or_parts) > 1:
                results = [_eval(p.strip(), v) for p in or_parts]
                return any(r[0] for r in results), any(r[1] for r in results)
            m = _rvc.match(r"^([<>]=?|=)([\d.]+)$", cond)
            if not m or v is None:
                return False, False
            cv, op = _parse_ver(m.group(2)), m.group(1)
            ok = (v < cv if op == "<" else v > cv if op == ">" else
                  v == cv if op == "=" else v <= cv if op == "<=" else
                  v >= cv if op == ">=" else False)
            return ok, op == "="
        # exact match first
        for e in entries:
            ok, exact = _eval(e["condition"], version_num)
            if ok and exact:
                return e["value"]
        # range conditions
        for e in entries:
            if not e["condition"]:
                continue
            ok, _ = _eval(e["condition"], version_num)
            if ok:
                return e["value"]
        # unconditional fallback
        for e in entries:
            if not e["condition"]:
                return e["value"]
        return None

    def _get_app_version_num(app_name):
        """Return major*1000+minor: branch file first, pom.xml fallback (for master branch)."""
        import re as _rvn
        try:
            bf_raw = _LOCAL_APP_DEFAULTS.get(app_name, {}).get("branch_file", "")
            if not bf_raw:
                deps   = _read_local_deps(app_name)
                bf_raw = deps.get("default_branch_file", "").strip()
            if bf_raw:
                bf = Path(bf_raw.replace("~", str(Path.home())))
                if bf.exists():
                    branch = bf.read_text(errors="replace").strip()
                    m = _rvn.search(r"(\d+)\.(\d+)", branch)
                    if m:
                        return int(m.group(1)) * 1000 + int(m.group(2))
            # Branch is "master" or unversioned — fall back to pom.xml
            srcdir = _get_generic_srcdir(app_name)
            if srcdir:
                pom = Path(srcdir) / "pom.xml"
                if pom.exists():
                    text = pom.read_text(errors="replace")
                    m = _rvn.search(r"<version>(\d+)\.(\d+)", text)
                    if m:
                        return int(m.group(1)) * 1000 + int(m.group(2))
        except Exception:
            pass
        return None

    def _read_generic_app_config(app_name):
        """Return app config from hardcoded defaults + build_deploy_config.xlsx overrides."""
        result = dict(_LOCAL_APP_DEFAULTS.get(app_name, {}))
        try:
            import openpyxl as _xl
            xlsx = _generic_app_root(app_name) / "build_deploy_config.xlsx"
            if xlsx.exists():
                wb  = _xl.load_workbook(str(xlsx), data_only=True)
                wsn = next((s for s in wb.sheetnames if s.lower() == "deploy"), None)
                if wsn:
                    version_num = _get_app_version_num(app_name)
                    groups = {}
                    for row in wb[wsn].iter_rows(min_row=2, values_only=True):
                        if not (row and row[0]):
                            continue
                        k    = str(row[0]).strip()
                        val  = str(row[1]).strip() if row[1] is not None else ""
                        cond = str(row[2]).strip() if len(row) > 2 and row[2] is not None else ""
                        groups.setdefault(k, []).append({"value": val, "condition": cond})
                    for k, entries in groups.items():
                        selected = _select_by_version(entries, version_num)
                        if selected is None:
                            continue
                        if k == "deployment_container" and selected:
                            result["container"] = selected
                        elif k in ("tomcat_manager_user", "tomcat_manager_pass", "tomcat_manager_port",
                                   "karaf_home", "karaf_user", "karaf_password") and selected:
                            result[k] = selected      # karaf_home differs per version (4.4.3 for <27, 4.4.11 for >=27)
        except Exception:
            pass
        return result

    def _write_generic_app_config(app_name, cfg):
        """Persist container override to build_deploy_config.xlsx Deploy sheet."""
        container = (cfg.get("container") or "").strip()
        if not container:
            return
        try:
            import openpyxl as _xl
            xlsx = _generic_app_root(app_name) / "build_deploy_config.xlsx"
            if not xlsx.exists():
                return
            wb  = _xl.load_workbook(str(xlsx))
            wsn = next((s for s in wb.sheetnames if s.lower() == "deploy"), None)
            if not wsn:
                return
            ws = wb[wsn]
            for row in ws.iter_rows(min_row=2):
                if row[0].value and str(row[0].value).strip() == "deployment_container":
                    row[1].value = container
                    wb.save(str(xlsx))
                    return
        except Exception:
            pass

    _LSERVER_SCRIPTS = {
        "classic":    LBD_APPS_ROOT / "Classic"    / "lclassicserver.py",
        "connector":  LBD_APPS_ROOT / "Connector"  / "lconnectorserver.py",
        "enrollment": LBD_APPS_ROOT / "Enrollment" / "lenrollmentserver.py",
        "pik":        LBD_APPS_ROOT / "PIK"        / "lpikserver.py",
    }

    def _lappserver(app_name, *args):
        """Run the l<app>server.py with given args plus --json. Returns parsed dict."""
        import json as _json, subprocess as _sub
        script = _LSERVER_SCRIPTS.get(app_name)
        if not script or not script.exists():
            return {"ok": False, "error": f"l{app_name}server.py not found at {script}"}
        cmd = [sys.executable, str(script), "--json"] + list(args)
        r = _sub.run(cmd, capture_output=True, text=True, encoding="utf-8",
                     errors="replace", creationflags=0x08000000 if sys.platform == "win32" else 0, timeout=30,
                     env=_rp_env(script.parent))
        out = (r.stdout or "").strip()
        if not out:
            return {"ok": False, "error": r.stderr.strip() or f"l{app_name}server produced no output"}
        try:
            return _json.loads(out)
        except Exception:
            return {"ok": False, "error": out}

    def _generic_app_props_file(app_name):
        return _generic_app_root(app_name) / "runtime_properties.json"

    def _read_generic_app_props(app_name):
        """Read props: try live container via l<app>server, fall back to JSON file."""
        cfg = _read_generic_app_config(app_name)
        container = cfg.get("container", "")
        if container and _docker_container_running(container):
            d = _lappserver(app_name, "list")
            if d.get("ok"):
                return d.get("properties", {})
        import json as _json
        pf = _generic_app_props_file(app_name)
        if pf.exists():
            try:
                return _json.loads(pf.read_text(encoding="utf-8"))
            except Exception:
                pass
        return {}

    def _write_generic_app_props(app_name, props):
        """Write props: update via l<app>server if container running, always persist to JSON file."""
        import json as _json
        pf = _generic_app_props_file(app_name)
        pf.parent.mkdir(parents=True, exist_ok=True)
        pf.write_text(_json.dumps(props, indent=2, sort_keys=True), encoding="utf-8")

    def _generic_app_deployed_file(app_name):
        return _generic_app_root(app_name) / "deployed_info.json"

    def _docker_container_running(container_name):
        if not container_name:
            return False
        try:
            import subprocess as _sub
            r = _sub.run(
                ["docker", "inspect", "--format", "{{.State.Running}}", container_name],
                capture_output=True, text=True, timeout=10,
                creationflags=0x08000000 if sys.platform == "win32" else 0,
            )
            return r.stdout.strip().lower() == "true"
        except Exception:
            return False

