    @app.route("/api/local-app/<app_name>/current-branch", methods=["GET"])
    def api_generic_current_branch(app_name):
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        force = request.args.get("force", "").lower() in ("1", "true", "yes")
        if not force:
            cached = _lb_cache_get(app_name)
            if cached is not None:
                return jsonify(cached)
        import re as _re, subprocess as _sub
        # Read set branch from branch file — use hardcoded defaults (fast); cached deps xlsx as fallback
        branch_file = _LOCAL_APP_DEFAULTS.get(app_name, {}).get("branch_file", "")
        if not branch_file:
            deps        = _read_local_deps(app_name)
            branch_file = deps.get("default_branch_file", "").strip()
        set_branch  = ""
        if branch_file:
            bf_path = Path(branch_file.replace("~", str(Path.home())))
            if bf_path.exists():
                set_branch = bf_path.read_text(errors="replace").strip()
        srcdir = _get_generic_srcdir(app_name)
        if not srcdir or not Path(srcdir).exists():
            if set_branch:
                return jsonify({"ok": False, "error": f"Branch set to '{set_branch}' but clone not found. Clone that version or run the env tool for an existing clone."})
            return jsonify({"ok": False, "error": "No branch set. Run the env tool (e.g. setc3branch master) first."})
        # Determine env_type from app defaults
        env_type = ""
        try:
            _acfg    = _read_generic_app_config(app_name)
            env_type = _acfg.get("env_type", "")
        except Exception:
            pass
        try:
            _cf = 0x08000000 if sys.platform == "win32" else 0
            r = _sub.run(["git", "-C", srcdir, "rev-parse", "--abbrev-ref", "HEAD"],
                         capture_output=True, text=True, timeout=10, creationflags=_cf)
            branch = r.stdout.strip() or set_branch
            # Read authoritative version from release.txt (branch name != Maven version)
            release_ver = None
            _rtxt = Path(srcdir) / "metadata" / "release.txt"
            if _rtxt.exists():
                for _rl in _rtxt.read_text(errors="replace").splitlines():
                    _rl = _rl.strip()
                    if "=" in _rl and not _rl.startswith("#"):
                        _rk, _, _rv = _rl.partition("=")
                        if _rk.strip().lower() == "release_ver":
                            release_ver = _rv.strip() or None
                            break
            # Fall back to pom.xml version
            if not release_ver:
                pom_path = Path(srcdir) / "pom.xml"
                if pom_path.exists():
                    pom_text = pom_path.read_text(errors="replace")
                    pv = _re.search(r"<version>(\d+\.\d+[^<]*)</version>", pom_text)
                    if pv:
                        raw = pv.group(1).split("-")[0].strip()
                        if _re.match(r"^\d+\.\d+", raw):
                            release_ver = raw
            # Last resort: extract from branch name
            if not release_ver:
                m = _re.search(r"(\d+\.\d+(?:\.\d+)*)", branch)
                release_ver = m.group(1) if m else None
            if env_type == "version-based":
                env_type = _version_env_type(release_ver)
            result = {"ok": True, "branch": branch, "release_ver": release_ver,
                      "env_type": env_type or None, "srcdir": srcdir, "set_branch": set_branch}
            _lb_cache_set(app_name, result)
            return jsonify(result)
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    _local_deps_cache: dict = {}

    # Branch info cache — avoids spawning git/python subprocess on every page open
    _local_branch_cache: dict = {}

    def _lb_cache_get(key):
        import time as _t
        entry = _local_branch_cache.get(key)
        if entry and _t.time() - entry["ts"] < int(_IDP_CFG.get("local_branch_cache_ttl_s", 60)):
            return entry["data"]
        return None

    def _lb_cache_set(key, data):
        import time as _t
        _local_branch_cache[key] = {"ts": _t.time(), "data": data}

    def _read_local_deps(app_name):
        if app_name in _local_deps_cache:
            return _local_deps_cache[app_name]
        xlsx_path = (PAYOR_ROOT if app_name == "payor" else _generic_app_root(app_name)) / "devtool_config.xlsx"
        if not xlsx_path.exists():
            _local_deps_cache[app_name] = {}
            return {}
        try:
            import openpyxl as _xl
            wb = _xl.load_workbook(str(xlsx_path), data_only=True)
            ws = wb.active
            result = {}
            for row in ws.iter_rows(min_row=2, values_only=True):
                if not row or row[1] is None: continue
                key = str(row[1]).strip()
                cmd = str(row[3]).strip() if row[3] is not None else ''
                if key and cmd:
                    result[key] = cmd
            _local_deps_cache[app_name] = result
            return result
        except Exception:
            _local_deps_cache[app_name] = {}
            return {}

    def _get_generic_srcdir(app_name):
        """Resolve srcdir from default_branch_file + git_pattern + GIT_HOME.
        Returns empty string if the exact clone does not exist (use _find_repo_dir for any-clone fallback)."""
        import os as _os
        # Use branch_file from hardcoded defaults (fast); fall back to local_deps xlsx (cached)
        branch_file = _LOCAL_APP_DEFAULTS.get(app_name, {}).get("branch_file", "")
        deps        = _read_local_deps(app_name)
        if not branch_file:
            branch_file = deps.get("default_branch_file", "").strip()
        git_pattern = deps.get("git_pattern", "").strip()
        git_home    = _os.environ.get("GIT_HOME", "").strip()
        if not (branch_file and git_pattern and git_home):
            return ""
        bf_path = Path(branch_file.replace("~", str(Path.home())))
        if not bf_path.exists():
            return ""
        branch = bf_path.read_text(errors="replace").strip()
        if not branch:
            return ""
        candidate = Path(git_home) / f"{git_pattern.split('*')[0]}{branch}"
        if not candidate.exists() and branch == "master":
            bare = Path(git_home) / git_pattern.split('*')[0].rstrip('-').rstrip('.')
            if bare.exists():
                return str(bare)
        return str(candidate)

    def _find_repo_dir(app_name):
        """Return path to any valid local repo for app_name.
        Tries the currently-active srcdir first, then searches GIT_HOME via git_pattern."""
        import os as _os
        # Try currently-active srcdir
        if app_name == "payor":
            _, srcdir = _payor_srcdir()
        else:
            srcdir = _get_generic_srcdir(app_name)
        if srcdir and Path(srcdir).exists() and (Path(srcdir) / ".git").exists():
            return srcdir
        # Search GIT_HOME for any matching clone
        deps = _read_local_deps(app_name)
        git_pattern = deps.get("git_pattern", "").strip()
        git_home    = _os.environ.get("GIT_HOME", "").strip()
        if git_home and git_pattern:
            candidates = sorted(Path(git_home).glob(git_pattern), reverse=True)
            for c in candidates:
                if (c / ".git").exists():
                    return str(c)
        return ""

    def _list_release_branches(clone_dir):
        """Run git branch -a on clone_dir and return sorted release-* version strings."""
        import subprocess as _sub, re as _re
        _cf = 0x08000000 if sys.platform == "win32" else 0
        r = _sub.run(["git", "-C", clone_dir, "branch", "-a"],
                     capture_output=True, text=True, timeout=15, creationflags=_cf)
        pattern = _re.compile(r"remotes/[^/]+/release-(.+)")
        seen, versions = set(), []
        for line in r.stdout.splitlines():
            m = pattern.search(line.strip())
            if m:
                v = m.group(1)
                if v not in seen:
                    seen.add(v)
                    versions.append(v)
        def _branch_sort_key(v):
            # New-style (e.g. 26.1, 21.8) sorts before old-style (e.g. r21.6, r20.x).
            # With reverse=True, higher primary comes first; give new-style 1, old-style 0.
            is_old = bool(_re.match(r"^r\d", v))
            primary = 0 if is_old else 1
            parts = [
                (0, int(x)) if x.isdigit() else (1, x)
                for x in _re.split(r"[.\-]", v)
            ]
            return (primary, parts)
        versions.sort(key=_branch_sort_key, reverse=True)
        return versions

    @app.route("/api/local-app/<app_name>/branches", methods=["GET"])
    def api_generic_branches(app_name):
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        clone_dir = _find_repo_dir(app_name)
        if not clone_dir:
            return jsonify({"ok": True, "branches": ["master"]})
        try:
            return jsonify({"ok": True, "branches": ["master"] + _list_release_branches(clone_dir)})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

