    def api_generic_abort_set_branch(app_name):
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        lock, state = _get_set_branch_state(app_name)
        with lock:
            proc = state.get("proc")
            if proc:
                try: proc.terminate()
                except Exception: pass
            state["status"] = "failed"
            state["output"] += "\n[ABORTED]\n"
            state["proc"] = None
        return jsonify({"ok": True})

