    def api_generic_server_status(app_name):
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        cfg = _read_generic_app_config(app_name)
        container  = cfg.get("container", "")
        env_type   = cfg.get("env_type", "")
        karaf_home = cfg.get("karaf_home", "")
        if not container:
            return jsonify({"ok": True, "running": False, "container": container})
        if env_type == "Karaf" and karaf_home and _docker_container_running(container):
            try:
                import subprocess as _sub
                r = _sub.run(
                    ["docker", "exec", container, "bash", "-c",
                     "ps -ef | grep karaf.main.Main | grep -v grep | wc -l"],
                    capture_output=True, text=True, timeout=10,
                    creationflags=0x08000000 if sys.platform == "win32" else 0,
                )
                running = r.stdout.strip() not in ("", "0")
            except Exception:
                running = False
        else:
            running = _docker_container_running(container)
        return jsonify({"ok": True, "running": running, "container": container,
                        "debug": bool(running and _local_debug_mode(container))})

    @app.route("/api/local-app/<app_name>/server-op", methods=["POST"])
    def api_generic_server_op(app_name):
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        body = request.get_json() or {}
        operation = body.get("operation", "start")
        cfg = _read_generic_app_config(app_name)
        container = cfg.get("container", "")
        if not container:
            return jsonify({"ok": False, "error": "Container name not configured. Set it in App Config."})
        with _generic_app_server_ops_lock:
            if _generic_app_server_ops.get(app_name, {}).get("status") == "running":
                return jsonify({"ok": False, "error": "An operation is already running"}), 409
            _generic_app_server_ops[app_name] = {"status": "running", "output": "", "operation": operation, "success": None}
        env_type   = cfg.get("env_type", "")
        karaf_home = cfg.get("karaf_home", "")
        is_karaf   = env_type == "Karaf" and bool(karaf_home)

        def _run_op():
            import subprocess as _sub
            _cf = 0x08000000 if sys.platform == "win32" else 0

            def _docker_exec(bash_cmd, timeout=60):
                r = _sub.run(
                    ["docker", "exec", container, "bash", "-c", bash_cmd],
                    capture_output=True, text=True, timeout=timeout, creationflags=_cf,
                )
                return r.returncode == 0, (r.stdout + "\n" + r.stderr).strip()

            def _docker_run(docker_cmd, timeout=60):
                r = _sub.run(docker_cmd, capture_output=True, text=True, timeout=timeout, creationflags=_cf)
                return r.returncode == 0, (r.stdout + "\n" + r.stderr).strip()

            def _finish(success, out):
                with _generic_app_server_ops_lock:
                    _generic_app_server_ops[app_name] = {
                        "status": "success" if success else "failed",
                        "output": out, "success": success,
                        "operation": operation,
                        "error": "" if success else out,
                    }

            try:
                if env_type == "Tomcat" and operation in ("stop", "restart"):
                    ok, out = _local_tomcat_stop(container)
                    if operation == "restart" and ok:
                        ok, out2 = _local_tomcat_start(container, app_name)
                        out = out + "\n" + out2
                    _finish(ok, out)
                    return
                if operation == "start_debug" or (operation == "start" and env_type == "Tomcat"):
                    _docker_run(["docker", "start", container], timeout=30)
                    ok, out = _local_tomcat_start(container, app_name, debug=(operation == "start_debug"))
                    _finish(ok, out)
                    return
                if is_karaf:
                    stop_cmd  = f"sh '{karaf_home}/bin/stop' 2>/dev/null || true; sleep 3; PID=$(ps -ef | grep karaf.main.Main | grep -v grep | awk '{{print $2}}'); [ -n \"$PID\" ] && kill -9 $PID 2>/dev/null; rm -f '{karaf_home}/lock' 2>/dev/null; echo stopped"
                    start_cmd = f"'{karaf_home}/bin/start'"
                    lines = []
                    if operation == "start":
                        _docker_run(["docker", "start", container], timeout=30)
                        ok, out = _docker_exec(start_cmd, timeout=30)
                        lines.append(out)
                        _finish(ok, "\n".join(lines).strip())
                    elif operation == "stop":
                        ok, out = _docker_exec(stop_cmd, timeout=60)
                        lines.append(out)
                        _finish(True, "\n".join(lines).strip())
                    elif operation == "restart":
                        _, out1 = _docker_exec(stop_cmd, timeout=60)
                        lines.append(out1)
                        ok, out2 = _docker_exec(start_cmd, timeout=30)
                        lines.append(out2)
                        _finish(ok, "\n".join(lines).strip())
                    else:
                        _finish(False, f"Unknown operation: {operation}")
                else:
                    cmd_map = {"start": ["docker", "start", container], "stop": ["docker", "stop", container],
                               "restart": ["docker", "restart", container]}
                    cmd = cmd_map.get(operation)
                    if not cmd:
                        _finish(False, f"Unknown: {operation}")
                        return
                    ok, out = _docker_run(cmd, timeout=120)
                    _finish(ok, out)
            except Exception as e:
                with _generic_app_server_ops_lock:
                    _generic_app_server_ops[app_name] = {"status": "failed", "output": "", "error": str(e),
                                                          "operation": operation, "success": False}
        _threading.Thread(target=_run_op, daemon=True).start()
        return jsonify({"ok": True})

