    @app.route("/api/local-app/<app_name>/karaf/log/set-level", methods=["POST"])
    def api_generic_karaf_log_set_level(app_name):
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        import re as _re_ls
        body   = request.get_json(force=True) or {}
        logger = (body.get("logger") or "ROOT").strip()
