    def _karaf_cfg_ctx(app_name):
        """Return (container, etc_path) for config file operations."""
        import subprocess as _sp_cc
        defaults = _LOCAL_APP_DEFAULTS.get(app_name, {})
        cfg = _read_generic_app_config(app_name)
        container  = cfg.get("container")  or defaults.get("container", "")
        karaf_home = cfg.get("karaf_home") or defaults.get("karaf_home", "")
        if not container or not karaf_home:
            raise ValueError("karaf_home or container not configured")
        return container, f"{karaf_home}/etc"

    @app.route("/api/local-app/<app_name>/karaf/configs", methods=["GET"])
    def api_generic_karaf_config_list(app_name):
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        import subprocess as _sp_cl
        try:
            container, etc = _karaf_cfg_ctx(app_name)
            r = _sp_cl.run(
                ["docker", "exec", container, "sh", "-c", f"ls {etc}/*.cfg 2>/dev/null"],
                capture_output=True, text=True, timeout=10,
                creationflags=0x08000000 if sys.platform == "win32" else 0,
            )
            pids = []
            for line in r.stdout.splitlines():
                line = line.strip()
                if line.endswith(".cfg"):
                    import os as _os
                    pids.append(_os.path.basename(line)[:-4])
            return jsonify({"ok": True, "pids": sorted(pids)})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/local-app/<app_name>/karaf/config/<pid>", methods=["GET"])
    def api_generic_karaf_config_get(app_name, pid):
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        import subprocess as _sp_cg, re as _re_cg
        if not _re_cg.match(r'^[\w.\-]+$', pid):
            return jsonify({"ok": False, "error": "Invalid PID"}), 400
        try:
            container, etc = _karaf_cfg_ctx(app_name)
            r = _sp_cg.run(
                ["docker", "exec", container, "cat", f"{etc}/{pid}.cfg"],
                capture_output=True, text=True, timeout=10,
                creationflags=0x08000000 if sys.platform == "win32" else 0,
            )
            if r.returncode != 0:
                return jsonify({"ok": False, "error": f"{pid}.cfg not found"})
            properties = {}
            raw_lines = []
            for line in r.stdout.splitlines():
                raw_lines.append(line)
                stripped = line.strip()
                if stripped.startswith('#') or not stripped:
                    continue
                if '=' in stripped:
                    k, _, v = stripped.partition('=')
                    properties[k.strip()] = v.strip()
            return jsonify({"ok": True, "pid": pid, "properties": properties, "raw": r.stdout})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/local-app/<app_name>/karaf/config/<pid>", methods=["POST"])
    def api_generic_karaf_config_update(app_name, pid):
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        import subprocess as _sp_cu, re as _re_cu
        if not _re_cu.match(r'^[\w.\-]+$', pid):
            return jsonify({"ok": False, "error": "Invalid PID"}), 400
        body = request.get_json(force=True) or {}
        new_props = body.get("properties", {})
        try:
            container, etc = _karaf_cfg_ctx(app_name)
            # Read existing file to preserve comments and ordering
            r = _sp_cu.run(
                ["docker", "exec", container, "cat", f"{etc}/{pid}.cfg"],
                capture_output=True, text=True, timeout=10,
                creationflags=0x08000000 if sys.platform == "win32" else 0,
            )
            existing_lines = r.stdout.splitlines() if r.returncode == 0 else []
            # Build updated lines: update existing keys in-place, append new ones
            updated_keys = set()
            out_lines = []
            for line in existing_lines:
                stripped = line.strip()
                if not stripped.startswith('#') and '=' in stripped:
                    k = stripped.split('=', 1)[0].strip()
                    if k in new_props:
                        out_lines.append(f"{k}={new_props[k]}")
                        updated_keys.add(k)
                        continue
                    elif k not in new_props:
                        # key was deleted — skip
                        continue
                out_lines.append(line)
            # Append brand-new keys
            for k, v in new_props.items():
                if k not in updated_keys:
                    out_lines.append(f"{k}={v}")
            new_content = "\n".join(out_lines) + "\n"
            # Write back via docker exec stdin
            write_cmd = ["docker", "exec", "-i", container, "sh", "-c", f"cat > {etc}/{pid}.cfg"]
            wr = _sp_cu.run(
                write_cmd, input=new_content, capture_output=True, text=True, timeout=15,
                creationflags=0x08000000 if sys.platform == "win32" else 0,
            )
            if wr.returncode != 0:
                return jsonify({"ok": False, "error": wr.stderr or "Write failed"})
            return jsonify({"ok": True})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    # ── Remote Karaf endpoints ────────────────────────────────────────────────────

    _KARAF_REMOTE_APPS = {"connector", "enrollment"}

    def _resolve_karaf_home(karaf_home, app_name, vm_ip):
        """Substitute {branch_version} in karaf_home. Uses branch-info rcache first, SSH fallback."""
        if not karaf_home or "{branch_version}" not in karaf_home:
            return karaf_home
        # Fast path: rcache already has release_ver from page-init
        cached = _rcache_get(vm_ip, f"branch_info_{app_name}")
        ver = (cached or {}).get("release_ver", "")
        if not ver:
            # Fallback: read branch file from VM via SSH
            deps = _read_vm_cmd_deps(app_name)
            branch_file = deps.get("default_branch_file", "~/.default-branch")
            ok, out, _ = _ssh_run(vm_ip, f"cat {branch_file} 2>/dev/null | tr -d '\\n'", timeout=10)
            ver = out.strip() if ok and out.strip() else ""
        return karaf_home.replace("{branch_version}", ver) if ver else karaf_home

    def _karaf_exec_remote(app_name, vm_ip, karaf_command, timeout=20):
        import re as _re_kr
        local_def = _LOCAL_APP_DEFAULTS.get(app_name, {})
        cfg       = _read_generic_app_config(app_name)
        vm_deps   = _read_vm_cmd_deps(app_name)
        # karaf_home from vm_dependencies.xlsx wins, then generic config, then local defaults
        karaf_home = vm_deps.get("karaf_home") or cfg.get("karaf_home") or local_def.get("karaf_home", "")
        karaf_home = _resolve_karaf_home(karaf_home, app_name, vm_ip)
        karaf_user = vm_deps.get("karaf_user") or cfg.get("karaf_user") or local_def.get("karaf_user", "karaf")
        karaf_pass = vm_deps.get("karaf_password") or cfg.get("karaf_password") or local_def.get("karaf_password", "karaf")
        if not karaf_home:
            raise ValueError(f"karaf_home not configured for remote {app_name}")
        safe_cmd   = karaf_command.replace("'", "").replace('"', '')
        client_bin = f"{karaf_home}/bin/client"
        # Karaf runs directly on the VM (not in Docker); run client binary via SSH
        ssh_cmd = f"{client_bin} -u {karaf_user} -p {karaf_pass} '{safe_cmd}' 2>&1"
        ok, out, err = _ssh_run(vm_ip, ssh_cmd, timeout=timeout + 15)
        if not ok:
            raise RuntimeError(f"SSH failed: {err}")
        combined = (out or "") + ("\n" + err if err else "")
        raw = _re_kr.sub(r'\x1b\[[0-9;]*[mGKHF]', '', combined)
        return raw, 0

    @app.route("/api/remote-app/<app_name>/karaf/debug-exec", methods=["GET"])
    def api_remote_karaf_debug_exec(app_name):
        if app_name not in _KARAF_REMOTE_APPS:
            return jsonify({"ok": False, "error": f"Not a Karaf app: {app_name}"}), 404
        vm_ip = request.args.get("vm_ip", "")
        cmd = request.args.get("cmd", "info")
        try:
            raw, _ = _karaf_exec_remote(app_name, vm_ip, cmd, timeout=20)
            return jsonify({"ok": True, "raw": raw, "lines": raw.splitlines()})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

