    def _karaf_cfg_ctx_remote(app_name, vm_ip=""):
        local_def = _LOCAL_APP_DEFAULTS.get(app_name, {})
        cfg       = _read_generic_app_config(app_name)
        vm_deps   = _read_vm_cmd_deps(app_name)
