    @app.route("/api/remote-app/<app_name>/karaf/features", methods=["GET"])
    def api_remote_karaf_features(app_name):
        if app_name not in _KARAF_REMOTE_APPS:
            return jsonify({"ok": False, "error": f"Not a Karaf app: {app_name}"}), 404
        vm_ip = request.args.get("vm_ip", "")
        import re as _re_k
        try:
            raw, _ = _karaf_exec_remote(app_name, vm_ip, "feature:list", timeout=20)
            _SEP_F = '│' if '│' in raw else '|'
            features = []; in_table = False
            for line in raw.splitlines():
                stripped = line.strip()
                if not in_table:
                    if _SEP_F in stripped and 'Name' in stripped and 'State' in stripped:
                        in_table = True
                    continue
                if _re_k.match(r'^[-─-┿│| ]+$', stripped): continue
                if _SEP_F not in stripped: continue
                cols = [c.strip() for c in stripped.split(_SEP_F)]
                if len(cols) < 4: continue
                name = cols[0]; version = cols[1]; required = cols[2] == 'x'; state = cols[3]
                repo = cols[4] if len(cols) > 4 else ""; desc = cols[5] if len(cols) > 5 else ""
                if name: features.append({"name": name, "version": version, "required": required,
                                           "state": state, "repository": repo, "description": desc})
            return jsonify({"ok": True, "features": features})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/remote-app/<app_name>/karaf/repos", methods=["GET"])
    def api_remote_karaf_repos(app_name):
        if app_name not in _KARAF_REMOTE_APPS:
            return jsonify({"ok": False, "error": f"Not a Karaf app: {app_name}"}), 404
        vm_ip = request.args.get("vm_ip", "")
        import re as _re_kr
        try:
            raw, _ = _karaf_exec_remote(app_name, vm_ip, "feature:repo-list", timeout=20)
            _SEP_R = '│' if '│' in raw else '|'
            repos = []
            for line in raw.splitlines():
                stripped = line.strip()
                if _SEP_R not in stripped: continue
                cols = [c.strip() for c in stripped.split(_SEP_R, 1)]
                if len(cols) < 2: continue
                name = cols[0]; url = cols[1]
                if not name or name.lower() in ('name', '---', ''): continue
                if _re_kr.match(r'^[-─-┿│| ]+$', name): continue
                repos.append({"name": name, "url": url})
            return jsonify({"ok": True, "repos": repos})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/remote-app/<app_name>/karaf/repo-op", methods=["POST"])
    def api_remote_karaf_repo_op(app_name):
        if app_name not in _KARAF_REMOTE_APPS:
            return jsonify({"ok": False, "error": f"Not a Karaf app: {app_name}"}), 404
        vm_ip = request.args.get("vm_ip", "")
        import re as _re_ro
        body = request.get_json() or {}
        op = (body.get("op") or "").strip(); name = (body.get("name") or "").strip()
        if op not in ("add", "remove"): return jsonify({"ok": False, "error": "op must be 'add' or 'remove'"})
        if not name: return jsonify({"ok": False, "error": "name is required"})
        if not _re_ro.match(r'^[\w./:@!-]+$', name): return jsonify({"ok": False, "error": "invalid characters"})
        try:
            raw, _ = _karaf_exec_remote(app_name, vm_ip, f"feature:repo-{'add' if op == 'add' else 'remove'} {name}", timeout=30)
            err = next((l.strip() for l in raw.splitlines() if 'Error' in l or 'error' in l), None)
            return jsonify({"ok": False, "error": err}) if err else jsonify({"ok": True, "output": raw.strip()})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/remote-app/<app_name>/karaf/feature-op", methods=["POST"])
    def api_remote_karaf_feature_op(app_name):
        if app_name not in _KARAF_REMOTE_APPS:
            return jsonify({"ok": False, "error": f"Not a Karaf app: {app_name}"}), 404
        vm_ip = request.args.get("vm_ip", "")
        import re as _re_fo
        body = request.get_json() or {}
        op = (body.get("op") or "").strip(); name = (body.get("name") or "").strip()
        if op not in ("install", "uninstall"): return jsonify({"ok": False, "error": "op must be 'install' or 'uninstall'"})
        if not name: return jsonify({"ok": False, "error": "name is required"})
        if not _re_fo.match(r'^[\w.\-]+$', name): return jsonify({"ok": False, "error": "invalid characters"})
