    @app.route("/api/remote-app/<app_name>/karaf/config/<pid>", methods=["GET"])
    def api_remote_karaf_config_get(app_name, pid):
        if app_name not in _KARAF_REMOTE_APPS:
            return jsonify({"ok": False, "error": f"Not a Karaf app: {app_name}"}), 404
        import re as _re_cg
        if not _re_cg.match(r'^[\w.\-]+$', pid): return jsonify({"ok": False, "error": "Invalid PID"}), 400
        vm_ip = request.args.get("vm_ip", "")
        try:
            _, etc = _karaf_cfg_ctx_remote(app_name, vm_ip)
            ok, out, err = _ssh_run(vm_ip, f"cat {etc}/{pid}.cfg 2>/dev/null", timeout=15)
            if not ok: return jsonify({"ok": False, "error": err or f"{pid}.cfg not found"})
            properties = {}
            for line in out.splitlines():
                stripped = line.strip()
                if stripped.startswith('#') or not stripped or '=' not in stripped: continue
                k, _, v = stripped.partition('=')
                properties[k.strip()] = v.strip()
            return jsonify({"ok": True, "pid": pid, "properties": properties, "raw": out})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/remote-app/<app_name>/karaf/config/<pid>", methods=["POST"])
    def api_remote_karaf_config_update(app_name, pid):
        if app_name not in _KARAF_REMOTE_APPS:
            return jsonify({"ok": False, "error": f"Not a Karaf app: {app_name}"}), 404
        import re as _re_cu
        if not _re_cu.match(r'^[\w.\-]+$', pid): return jsonify({"ok": False, "error": "Invalid PID"}), 400
        vm_ip = request.args.get("vm_ip", "")
        body = request.get_json(force=True) or {}
        new_props = body.get("properties", {})
        try:
            _, etc = _karaf_cfg_ctx_remote(app_name, vm_ip)
            ok, out, _ = _ssh_run(vm_ip, f"cat {etc}/{pid}.cfg 2>/dev/null", timeout=15)
            existing_lines = out.splitlines() if ok else []
            updated_keys = set(); out_lines = []
            for line in existing_lines:
                stripped = line.strip()
                if not stripped.startswith('#') and '=' in stripped:
                    k = stripped.split('=', 1)[0].strip()
                    if k in new_props:
                        out_lines.append(f"{k}={new_props[k]}"); updated_keys.add(k); continue
                    elif k not in new_props:
                        continue
                out_lines.append(line)
            for k, v in new_props.items():
                if k not in updated_keys:
                    out_lines.append(f"{k}={v}")
            new_content = "\n".join(out_lines) + "\n"
            import base64 as _b64
            encoded = _b64.b64encode(new_content.encode()).decode()
            write_cmd = f"echo {encoded} | base64 -d > {etc}/{pid}.cfg"
            ok2, _, err2 = _ssh_run(vm_ip, write_cmd, timeout=20)
            if not ok2: return jsonify({"ok": False, "error": err2 or "Write failed"})
            return jsonify({"ok": True})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    # ── Remote Tomcat management endpoints ───────────────────────────────────────

    _TOMCAT_REMOTE_APPS = {"pik"}

    def _tomcat_exec(vm_ip, container, script, timeout=20):
        escaped = script.replace("'", "'\\''")
        return _ssh_run(vm_ip, f"docker exec {container} sh -c '{escaped}'", timeout=timeout)

    @app.route("/api/remote-app/<app_name>/tomcat/system", methods=["GET"])
    def api_remote_tomcat_system(app_name):
        import re as _re_tc
        vm_ip = request.args.get("vm_ip", "")
        cfg = _read_remote_app_config(app_name)
        container = cfg.get("container", app_name)
        script = (
            "TPID=$(jcmd 2>/dev/null | grep -E 'catalina.startup.Bootstrap|org.apache.catalina' | awk '{print $1}' | head -1); "
            "[ -z \"$TPID\" ] && TPID=$(pgrep -f catalina.startup.Bootstrap 2>/dev/null | tail -1); "
            "[ -z \"$TPID\" ] && { echo ERR_NO_PID; exit 0; }; "
            "echo PID:$TPID; "
            "grep -E '^(Threads|VmRSS|VmSize):' /proc/$TPID/status 2>/dev/null || true; "
            "java -version 2>&1 | head -1 | sed 's/^/JAVA_VER:/'; "
            "echo HEAP_START; "
            "timeout 10 jcmd $TPID GC.heap_info 2>&1 || true; "
            "echo HEAP_END; "
            "echo PROPS_START; "
            "timeout 5 jcmd $TPID VM.system_properties 2>&1 | grep -E '^(catalina\\.(home|base)|java\\.version|java\\.vendor|user\\.name)=' || true; "
            "echo PROPS_END; "
            "echo JSTAT_START; "
            "timeout 5 jstat -gcutil $TPID 2>&1 | tail -1 || true; "
            "echo JSTAT_END"
        )
        ok, out, err = _tomcat_exec(vm_ip, container, script, timeout=25)
        if not ok:
            return jsonify({"ok": False, "error": err or "SSH failed"})
        if "ERR_NO_PID" in out:
            return jsonify({"ok": False, "error": "No Tomcat process found in container"})
        result = {"pid": None, "threads": None, "vmrss": None, "vmsize": None,
                  "java_version": None, "heap": {}, "props": {}, "jstat_raw": ""}
        heap_lines, props_lines, jstat_lines = [], [], []
        section = None
        for line in out.splitlines():
            if line.startswith("PID:"):
                result["pid"] = line[4:].strip()
            elif line.startswith("Threads:"):
                result["threads"] = line.split(":", 1)[1].strip()
            elif line.startswith("VmRSS:"):
                result["vmrss"] = line.split(":", 1)[1].strip()
            elif line.startswith("VmSize:"):
                result["vmsize"] = line.split(":", 1)[1].strip()
            elif line.startswith("JAVA_VER:"):
                result["java_version"] = line[9:].strip()
            elif line == "HEAP_START":
                section = "heap"
            elif line == "HEAP_END":
                section = None
            elif line == "PROPS_START":
                section = "props"
            elif line == "PROPS_END":
                section = None
            elif line == "JSTAT_START":
                section = "jstat"
            elif line == "JSTAT_END":
                section = None
            elif section == "heap":
                heap_lines.append(line)
            elif section == "props":
                props_lines.append(line)
            elif section == "jstat":
                jstat_lines.append(line)
        heap_raw = "\n".join(heap_lines)
        m = _re_tc.search(r"total\s+([\d.]+)([KMG]?)", heap_raw, _re_tc.I)
        if m: result["heap"]["total"] = m.group(1) + m.group(2)
        m = _re_tc.search(r",\s*used\s+([\d.]+)([KMG]?)", heap_raw, _re_tc.I)
        if m: result["heap"]["used"] = m.group(1) + m.group(2)
        m = _re_tc.search(r"Metaspace\s+used\s+([\d.]+)([KMG]?)", heap_raw, _re_tc.I)
        if m: result["heap"]["metaspace_used"] = m.group(1) + m.group(2)
        m = _re_tc.search(r"Metaspace.*committed\s+([\d.]+)([KMG]?)", heap_raw, _re_tc.I)
        if m: result["heap"]["metaspace_committed"] = m.group(1) + m.group(2)
        result["heap"]["raw"] = heap_raw.strip()
        for line in props_lines:
            if "=" in line:
                k, _, v = line.partition("=")
                result["props"][k.strip()] = v.strip()
        result["jstat_raw"] = " ".join(jstat_lines).strip()
        return jsonify({"ok": True, **result})

    @app.route("/api/remote-app/<app_name>/tomcat/gc", methods=["POST"])
    def api_remote_tomcat_gc(app_name):
        vm_ip = request.args.get("vm_ip", "")
        cfg = _read_remote_app_config(app_name)
        container = cfg.get("container", app_name)
        script = (
            "TPID=$(jcmd 2>/dev/null | grep -E 'catalina.startup.Bootstrap|org.apache.catalina' | awk '{print $1}' | head -1); "
            "[ -z \"$TPID\" ] && TPID=$(pgrep -f catalina.startup.Bootstrap 2>/dev/null | tail -1); "
            "[ -z \"$TPID\" ] && { echo ERR_NO_PID; exit 0; }; "
            "timeout 25 jcmd $TPID GC.run 2>&1"
        )
        ok, out, err = _tomcat_exec(vm_ip, container, script, timeout=30)
        if not ok:
            return jsonify({"ok": False, "error": err or "SSH failed"})
        if "ERR_NO_PID" in out:
            return jsonify({"ok": False, "error": "No Tomcat process found in container"})
        return jsonify({"ok": True, "output": out.strip()})

    @app.route("/api/remote-app/<app_name>/tomcat/apps", methods=["GET"])
    def api_remote_tomcat_apps(app_name):
        vm_ip = request.args.get("vm_ip", "")
        cfg = _read_remote_app_config(app_name)
        container = cfg.get("container", app_name)
        mgr_user  = cfg.get("tomcat_manager_user", "admin")
        mgr_pass  = cfg.get("tomcat_manager_pass", "admin")
        mgr_port  = cfg.get("tomcat_manager_port") or cfg.get("port", 8080)
        mgr_script = (
            f"curl -s -u {mgr_user}:{mgr_pass} "
            f"http://localhost:{mgr_port}/manager/text/list 2>&1"
        )
        ok, out, _ = _tomcat_exec(vm_ip, container, mgr_script, timeout=15)
        if ok and out.startswith("OK -"):
            apps = []
            for line in out.splitlines()[1:]:
                parts = line.strip().split(":")
                if len(parts) >= 2 and parts[0]:
                    apps.append({
                        "path": parts[0],
                        "state": parts[1] if len(parts) > 1 else "unknown",
                        "sessions": parts[2] if len(parts) > 2 else "0",
                    })
            return jsonify({"ok": True, "apps": apps, "manager": True})
        fallback_script = (
            "TPID=$(jcmd 2>/dev/null | grep -E 'catalina.startup.Bootstrap|org.apache.catalina' | awk '{print $1}' | head -1); "
            "[ -z \"$TPID\" ] && TPID=$(pgrep -f catalina.startup.Bootstrap 2>/dev/null | tail -1); "
            "CHOME=$(timeout 5 jcmd $TPID VM.system_properties 2>&1 | grep ^catalina.home= | head -1 | cut -d= -f2); "
            "[ -z \"$CHOME\" ] && CHOME=$(find /opt /home -maxdepth 5 -name catalina.sh 2>/dev/null | head -1 | sed 's|/bin/catalina.sh||'); "
            "echo CHOME:$CHOME; "
            "[ -d \"$CHOME/webapps\" ] && ls -1 \"$CHOME/webapps/\" 2>&1 | sed 's/^/WEBAPP:/' || echo ERR_NO_WEBAPPS"
        )
        ok, out, err = _tomcat_exec(vm_ip, container, fallback_script, timeout=20)
        if not ok:
            return jsonify({"ok": False, "error": err or "SSH failed"})
        if "ERR_NO_WEBAPPS" in out:
            return jsonify({"ok": False, "error": "Cannot find webapps directory. Tomcat Manager not available."})
        apps = []
        catalina_home = ""
        for line in out.splitlines():
            if line.startswith("CHOME:"):
                catalina_home = line[6:].strip()
            elif line.startswith("WEBAPP:"):
                name = line[7:].strip()
                if name:
                    apps.append({"path": f"/{name}", "state": "unknown", "sessions": "—"})
        return jsonify({"ok": True, "apps": apps, "manager": False, "catalina_home": catalina_home})

    @app.route("/api/remote-app/<app_name>/tomcat/app-action", methods=["POST"])
    def api_remote_tomcat_app_action(app_name):
        body = request.get_json() or {}
        vm_ip  = body.get("vm_ip", "")
        action = body.get("action", "")
        path   = body.get("path", "")
        if action not in ("start", "stop", "reload", "undeploy"):
            return jsonify({"ok": False, "error": f"Unknown action: {action}"})
        if not path:
            return jsonify({"ok": False, "error": "App path is required"})
        cfg = _read_remote_app_config(app_name)
        container = cfg.get("container", app_name)
        mgr_user  = cfg.get("tomcat_manager_user", "admin")
        mgr_pass  = cfg.get("tomcat_manager_pass", "admin")
        mgr_port  = cfg.get("tomcat_manager_port") or cfg.get("port", 8080)
        script = (
            f"curl -s -u {mgr_user}:{mgr_pass} "
            f"\"http://localhost:{mgr_port}/manager/text/{action}?path={path}\" 2>&1"
        )
        ok, out, err = _tomcat_exec(vm_ip, container, script, timeout=30)
        if not ok:
            return jsonify({"ok": False, "error": err or "SSH failed"})
        if out.startswith("OK"):
            return jsonify({"ok": True, "output": out.strip()})
        if "401" in out or "Unauthorized" in out.lower():
            return jsonify({"ok": False, "error": "Tomcat Manager authentication failed — configure tomcat_manager_user/pass in app screen_config"})
        return jsonify({"ok": False, "error": out.strip() or "Action failed"})

    @app.route("/api/remote-app/<app_name>/tomcat/deploy", methods=["POST"])
    def api_remote_tomcat_deploy(app_name):
        if request.files.get("war"):
            # Same as Tomcat Manager's "WAR file to deploy": the context path comes from the file name (ROOT.war -> /)
            up = request.files["war"]
            vm_ip = request.form.get("vm_ip", "")
            fname = Path(up.filename or "").name
            if not fname.lower().endswith(".war"):
                return jsonify({"ok": False, "error": "Choose a .war file"})
            stem = fname[:-4]
            cfg = _read_remote_app_config(app_name)
            container = cfg.get("container", app_name)
            mgr_user = cfg.get("tomcat_manager_user", "admin")
            mgr_pass = cfg.get("tomcat_manager_pass", "admin")
            mgr_port = cfg.get("tomcat_manager_port") or cfg.get("port", 8080)
            cpath = "" if stem == "ROOT" else "/" + stem
            tmp_vm = f"/tmp/dwb_{stem}.war"
            try:
                sftp = _pooled_client(vm_ip).open_sftp()
                try:
                    with sftp.open(tmp_vm, "wb") as rf:
                        rf.set_pipelined(True)
                        while True:
                            chunk = up.stream.read(1024 * 1024)
                            if not chunk:
                                break
                            rf.write(chunk)
                finally:
                    sftp.close()
            except Exception as e:
                return jsonify({"ok": False, "error": f"Could not upload WAR to VM: {e}"})
            ok, out, err = _ssh_run(vm_ip, f"docker cp {tmp_vm} {container}:/tmp/{stem}.war; rm -f {tmp_vm}", timeout=120)
            if not ok:
                return jsonify({"ok": False, "error": f"Could not copy WAR to container: {err}"})
            ok, out, err = _tomcat_exec(vm_ip, container,
                f"curl -s -u {mgr_user}:{mgr_pass} \"http://localhost:{mgr_port}/manager/text/deploy?path={cpath}&update=true\" "
                f"--upload-file /tmp/{stem}.war 2>&1; rm -f /tmp/{stem}.war", timeout=300)
            if out.startswith("OK"):
                return jsonify({"ok": True, "output": out.strip()})
            if "401" in out or "Unauthorized" in out.lower():
                return jsonify({"ok": False, "error": "Tomcat Manager auth failed — configure tomcat_manager_user/pass"})
            return jsonify({"ok": False, "error": out.strip() or err or "Deploy failed"})
        body = request.get_json() or {}
        vm_ip    = body.get("vm_ip", "")
        path     = body.get("path", "").strip()
        war_path = body.get("war_path", "").strip()
        if not path:
            return jsonify({"ok": False, "error": "context path is required (e.g. /myapp)"})
        if not war_path:
            return jsonify({"ok": False, "error": "war_path is required (path to WAR on the VM)"})
        cfg = _read_remote_app_config(app_name)
        container = cfg.get("container", app_name)
        mgr_user  = cfg.get("tomcat_manager_user", "admin")
        mgr_pass  = cfg.get("tomcat_manager_pass", "admin")
        mgr_port  = cfg.get("tomcat_manager_port") or cfg.get("port", 8080)
        ctx_name  = path.lstrip("/") or "app"
        copy_cmd  = f"docker cp {war_path} {container}:/tmp/{ctx_name}.war"
        ok, out, err = _ssh_run(vm_ip, copy_cmd, timeout=30)
        if not ok:
            return jsonify({"ok": False, "error": f"Could not copy WAR to container: {err}"})
        deploy_script = (
            f"curl -s -u {mgr_user}:{mgr_pass} "
            f"\"http://localhost:{mgr_port}/manager/text/deploy?path={path}&update=true\" "
            f"--upload-file /tmp/{ctx_name}.war 2>&1; "
            f"rm -f /tmp/{ctx_name}.war"
        )
        ok, out, err = _tomcat_exec(vm_ip, container, deploy_script, timeout=60)
        if not ok:
            return jsonify({"ok": False, "error": err or "SSH failed"})
        if out.startswith("OK"):
            return jsonify({"ok": True, "output": out.strip()})
        if "401" in out or "Unauthorized" in out.lower():
            return jsonify({"ok": False, "error": "Tomcat Manager auth failed — configure tomcat_manager_user/pass"})
        return jsonify({"ok": False, "error": out.strip() or "Deploy failed"})

    # ── Local Tomcat management endpoints ─────────────────────────────────────

    _LOCAL_TOMCAT_APPS = {"payor"}
    _LOCAL_TOMCAT_PORTS = {"payor": 7001}

    def _local_tomcat_exec(container, script, timeout=20):
        import subprocess as _sp_ltc
        cmd = ["docker", "exec", container, "sh", "-c", script]
        r = _sp_ltc.run(cmd, capture_output=True, text=True, timeout=timeout + 5,
                        creationflags=0x08000000 if sys.platform == "win32" else 0)
        ok = r.returncode == 0 or r.stdout.strip()
        return bool(ok), r.stdout, r.stderr

    def _get_local_tomcat_container(app_name):
        if app_name == "payor":
            return _get_payor_container() or "payer-tc"
        defaults = _LOCAL_APP_DEFAULTS.get(app_name, {})
        cfg = _read_generic_app_config(app_name)
        return cfg.get("container") or defaults.get("container", app_name)

    def _manager_deploy_war(container, cfg, up, stem):
        """Deploy an uploaded WAR through Tomcat Manager (text API deploy with the WAR as the PUT body: what the
        Manager page's 'WAR file to deploy' does). Returns (ok, message)."""
        import subprocess as _sp, tempfile as _tf, os as _os
        cf = 0x08000000 if sys.platform == "win32" else 0
        mgr_user = cfg.get("tomcat_manager_user", "admin")
        mgr_pass = cfg.get("tomcat_manager_pass", "admin")
        mgr_port = cfg.get("tomcat_manager_port") or cfg.get("port", 8080)
        cpath = "" if stem == "ROOT" else "/" + stem
        tmpd = _tf.mkdtemp(prefix="dwb_war_")
        try:
            local = _os.path.join(tmpd, stem + ".war")
            up.save(local)
            r = _sp.run(["docker", "cp", local, f"{container}:/tmp/{stem}.war"], capture_output=True, text=True, creationflags=cf)
            if r.returncode != 0:
                return False, f"Could not copy WAR to container: {r.stderr.strip()}"
        finally:
            import shutil as _sh
            _sh.rmtree(tmpd, ignore_errors=True)
        ok, out, err = _local_tomcat_exec(container,
            f"curl -s -u {mgr_user}:{mgr_pass} \"http://localhost:{mgr_port}/manager/text/deploy?path={cpath}&update=true\" "
            f"--upload-file /tmp/{stem}.war 2>&1; rm -f /tmp/{stem}.war", timeout=300)
        if out.startswith("OK"):
            # confirm with the Manager's own list that the context is really running
            ok2, lst, _e = _local_tomcat_exec(container,
                f"curl -s -u {mgr_user}:{mgr_pass} \"http://localhost:{mgr_port}/manager/text/list\" 2>&1", timeout=30)
            line = next((l for l in lst.splitlines() if l.startswith((cpath or "/") + ":")), "")
            if not line.split(":")[1:2] == ["running"]:
                return False, f"Manager reported OK but the application is not running: {line or 'not listed'}\n{out.strip()}"
            return True, out.strip() + f"\n{line}"
        if "401" in out or "unauthorized" in out.lower():
            return False, "Tomcat Manager auth failed — configure tomcat_manager_user/pass in Deploy Configuration"
        return False, out.strip() or err.strip() or "Deploy failed"

    def _get_local_tomcat_cfg(app_name):
        defaults = _LOCAL_APP_DEFAULTS.get(app_name, {})
        cfg = _read_generic_app_config(app_name)
        merged = {**defaults, **cfg}
        if "port" not in merged and app_name in _LOCAL_TOMCAT_PORTS:
            merged["port"] = _LOCAL_TOMCAT_PORTS[app_name]
        return merged

    @app.route("/api/local-app/<app_name>/tomcat/system", methods=["GET"])
    def api_local_tomcat_system(app_name):
        import re as _re_ltc
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        container = _get_local_tomcat_container(app_name)
        cfg = _get_local_tomcat_cfg(app_name)
        script = (
            "TPID=$(jcmd 2>/dev/null | grep -E 'catalina.startup.Bootstrap|org.apache.catalina' | awk '{print $1}' | head -1); "
            "[ -z \"$TPID\" ] && TPID=$(pgrep -f catalina.startup.Bootstrap 2>/dev/null | tail -1); "
            "[ -z \"$TPID\" ] && { echo ERR_NO_PID; exit 0; }; "
            "echo PID:$TPID; "
            "grep -E '^(Threads|VmRSS|VmSize):' /proc/$TPID/status 2>/dev/null || true; "
            "java -version 2>&1 | head -1 | sed 's/^/JAVA_VER:/'; "
            "echo HEAP_START; "
            "timeout 10 jcmd $TPID GC.heap_info 2>&1 || true; "
            "echo HEAP_END; "
            "echo PROPS_START; "
            "timeout 5 jcmd $TPID VM.system_properties 2>&1 | grep -E '^(catalina\\.(home|base)|java\\.version|java\\.vendor|user\\.name)=' || true; "
            "echo PROPS_END; "
            "echo JSTAT_START; "
            "timeout 5 jstat -gcutil $TPID 2>&1 | tail -1 || true; "
            "echo JSTAT_END"
        )
        ok, out, err = _local_tomcat_exec(container, script, timeout=25)
        if not ok and not out:
            return jsonify({"ok": False, "error": err or "Docker exec failed"})
        if "ERR_NO_PID" in out:
            return jsonify({"ok": False, "error": "No Tomcat process found in container"})
        result = {"pid": None, "threads": None, "vmrss": None, "vmsize": None,
                  "java_version": None, "heap": {}, "props": {}, "jstat_raw": ""}
        heap_lines, props_lines, jstat_lines = [], [], []
        section = None
        for line in out.splitlines():
            if line.startswith("PID:"):         result["pid"] = line[4:].strip()
            elif line.startswith("Threads:"):   result["threads"] = line.split(":", 1)[1].strip()
            elif line.startswith("VmRSS:"):     result["vmrss"] = line.split(":", 1)[1].strip()
            elif line.startswith("VmSize:"):    result["vmsize"] = line.split(":", 1)[1].strip()
            elif line.startswith("JAVA_VER:"):  result["java_version"] = line[9:].strip()
            elif line == "HEAP_START":  section = "heap"
            elif line == "HEAP_END":    section = None
            elif line == "PROPS_START": section = "props"
            elif line == "PROPS_END":   section = None
            elif line == "JSTAT_START": section = "jstat"
            elif line == "JSTAT_END":   section = None
            elif section == "heap":  heap_lines.append(line)
            elif section == "props": props_lines.append(line)
            elif section == "jstat": jstat_lines.append(line)
        heap_raw = "\n".join(heap_lines)
        m = _re_ltc.search(r"total\s+([\d.]+)([KMG]?)", heap_raw, _re_ltc.I)
        if m: result["heap"]["total"] = m.group(1) + m.group(2)
        m = _re_ltc.search(r",\s*used\s+([\d.]+)([KMG]?)", heap_raw, _re_ltc.I)
        if m: result["heap"]["used"] = m.group(1) + m.group(2)
        m = _re_ltc.search(r"Metaspace\s+used\s+([\d.]+)([KMG]?)", heap_raw, _re_ltc.I)
        if m: result["heap"]["metaspace_used"] = m.group(1) + m.group(2)
        m = _re_ltc.search(r"Metaspace.*committed\s+([\d.]+)([KMG]?)", heap_raw, _re_ltc.I)
        if m: result["heap"]["metaspace_committed"] = m.group(1) + m.group(2)
        result["heap"]["raw"] = heap_raw.strip()
        for line in props_lines:
            if "=" in line:
                k, _, v = line.partition("=")
                result["props"][k.strip()] = v.strip()
        result["jstat_raw"] = " ".join(jstat_lines).strip()
        return jsonify({"ok": True, **result})

    @app.route("/api/local-app/<app_name>/tomcat/gc", methods=["POST"])
    def api_local_tomcat_gc(app_name):
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        container = _get_local_tomcat_container(app_name)
        cfg = _get_local_tomcat_cfg(app_name)
        script = (
            "TPID=$(jcmd 2>/dev/null | grep -E 'catalina.startup.Bootstrap|org.apache.catalina' | awk '{print $1}' | head -1); "
            "[ -z \"$TPID\" ] && TPID=$(pgrep -f catalina.startup.Bootstrap 2>/dev/null | tail -1); "
            "[ -z \"$TPID\" ] && { echo ERR_NO_PID; exit 0; }; "
            "timeout 25 jcmd $TPID GC.run 2>&1"
        )
        ok, out, err = _local_tomcat_exec(container, script, timeout=30)
        if "ERR_NO_PID" in out:
            return jsonify({"ok": False, "error": "No Tomcat process found in container"})
        return jsonify({"ok": True, "output": out.strip()})

    # Tail of the Tomcat log inside the container: catalina.out, else the newest catalina*.log
    _TOMCAT_LOG_SCRIPT = (
        # exactly what startServer / startServer -d printed (written by the Start buttons)
        "F=/tmp/@APP@_start.log; if [ -s \"$F\" ]; then tail -n @N@ \"$F\"; exit 0; fi; "
        "CH=$(find /opt /home /usr/local -maxdepth 5 -name catalina.sh 2>/dev/null | head -1 | sed 's|/bin/catalina.sh||'); "
        "B=\"${CATALINA_BASE:-$CH}\"; "
        # fallback when the server was started some other way: newest catalina / claimserver log
        "F=$(ls -t \"$B\"/logs/catalina.out \"$B\"/logs/catalina*.log "
        "/home/*/domains/*/claimserver/logs/*.log /home/*/domains/*/logs/*.log 2>/dev/null | head -1); "
        "if [ -n \"$F\" ] && [ -f \"$F\" ]; then tail -n @N@ \"$F\"; else echo 'No Tomcat log file found'; fi"
    )

    @app.route("/api/local-app/<app_name>/tomcat/server-log", methods=["GET"])
    def api_local_tomcat_server_log(app_name):
        import subprocess as _sp_tl
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        n = max(50, min(int(request.args.get("n", 400) or 400), 2000))
        container = _get_local_tomcat_container(app_name)
        try:
            ok_f, out_f, _ = _local_tomcat_exec(container, _TOMCAT_LOG_SCRIPT.replace('@APP@', app_name).replace('@N@', str(n)), timeout=15)
            if ok_f and out_f.strip() and "No Tomcat log file found" not in out_f:
                return jsonify({"ok": True, "output": out_f})
            # container stdout/stderr is catalina.out for a Docker-run Tomcat
            r = _sp_tl.run(["docker", "logs", "--tail", str(n), container], capture_output=True, text=True,
                           timeout=15, creationflags=0x08000000 if sys.platform == "win32" else 0)
            out = (r.stdout + r.stderr).strip()
            if r.returncode != 0 and not out:
                return jsonify({"ok": False, "error": "docker logs failed"})
            return jsonify({"ok": True, "output": out})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/remote-app/<app_name>/tomcat/server-log", methods=["GET"])
    def api_remote_tomcat_server_log(app_name):
        vm_ip = request.args.get("vm_ip", "")
        n = max(50, min(int(request.args.get("n", 400) or 400), 2000))
        container = _read_remote_app_config(app_name).get("container", app_name)
        # startServer runs on the VM itself, so its log lives on the VM, not inside the container
        okh, outh, _ = _ssh_run(vm_ip, f"[ -s /tmp/{app_name}_start.log ] && tail -n {n} /tmp/{app_name}_start.log", timeout=15)
        if okh and outh.strip():
            return jsonify({"ok": True, "output": outh})
        ok, out, err = _tomcat_exec(vm_ip, container, _TOMCAT_LOG_SCRIPT.replace('@APP@', app_name).replace('@N@', str(n)), timeout=15)
        if not ok:
            return jsonify({"ok": False, "error": err or "SSH failed"})
        return jsonify({"ok": True, "output": out})

    @app.route("/api/local-app/<app_name>/tomcat/apps", methods=["GET"])
    def api_local_tomcat_apps(app_name):
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        container = _get_local_tomcat_container(app_name)
        cfg = _get_local_tomcat_cfg(app_name)
        mgr_user = cfg.get("tomcat_manager_user", "admin")
        mgr_pass = cfg.get("tomcat_manager_pass", "admin")
        mgr_port = cfg.get("tomcat_manager_port") or cfg.get("port", 8080)
        mgr_script = f"curl -s -u {mgr_user}:{mgr_pass} http://localhost:{mgr_port}/manager/text/list 2>&1"
        ok, out, _ = _local_tomcat_exec(container, mgr_script, timeout=15)
        if ok and out.startswith("OK -"):
            apps = []
            for line in out.splitlines()[1:]:
                parts = line.strip().split(":")
                if len(parts) >= 2 and parts[0]:
                    apps.append({"path": parts[0], "state": parts[1] if len(parts) > 1 else "unknown",
                                 "sessions": parts[2] if len(parts) > 2 else "0"})
            return jsonify({"ok": True, "apps": apps, "manager": True})
        fallback_script = (
            "TPID=$(jcmd 2>/dev/null | grep -E 'catalina.startup.Bootstrap|org.apache.catalina' | awk '{print $1}' | head -1); "
            "[ -z \"$TPID\" ] && TPID=$(pgrep -f catalina.startup.Bootstrap 2>/dev/null | tail -1); "
            "CHOME=$(timeout 5 jcmd $TPID VM.system_properties 2>&1 | grep ^catalina.home= | head -1 | cut -d= -f2); "
            "[ -z \"$CHOME\" ] && CHOME=$(find /opt /home -maxdepth 5 -name catalina.sh 2>/dev/null | head -1 | sed 's|/bin/catalina.sh||'); "
            "echo CHOME:$CHOME; "
            "[ -d \"$CHOME/webapps\" ] && ls -1 \"$CHOME/webapps/\" 2>&1 | sed 's/^/WEBAPP:/' || echo ERR_NO_WEBAPPS"
        )
        ok, out, err = _local_tomcat_exec(container, fallback_script, timeout=20)
        if "ERR_NO_WEBAPPS" in out:
            return jsonify({"ok": False, "error": "Cannot find webapps directory. Tomcat Manager not available."})
        apps, catalina_home = [], ""
        for line in out.splitlines():
            if line.startswith("CHOME:"):
                catalina_home = line[6:].strip()
            elif line.startswith("WEBAPP:"):
                name = line[7:].strip()
                if name:
                    apps.append({"path": f"/{name}", "state": "unknown", "sessions": "—"})
        return jsonify({"ok": True, "apps": apps, "manager": False, "catalina_home": catalina_home})

    @app.route("/api/local-app/<app_name>/tomcat/app-action", methods=["POST"])
    def api_local_tomcat_app_action(app_name):
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        body = request.get_json() or {}
        action = body.get("action", "")
        path   = body.get("path", "")
        if action not in ("start", "stop", "reload", "undeploy"):
            return jsonify({"ok": False, "error": f"Unknown action: {action}"})
        if not path:
            return jsonify({"ok": False, "error": "App path is required"})
        container = _get_local_tomcat_container(app_name)
        cfg = _get_local_tomcat_cfg(app_name)
        mgr_user = cfg.get("tomcat_manager_user", "admin")
        mgr_pass = cfg.get("tomcat_manager_pass", "admin")
        mgr_port = cfg.get("tomcat_manager_port") or cfg.get("port", 8080)
        script = (f"curl -s -u {mgr_user}:{mgr_pass} "
                  f"\"http://localhost:{mgr_port}/manager/text/{action}?path={path}\" 2>&1")
        ok, out, err = _local_tomcat_exec(container, script, timeout=30)
        if out.startswith("OK"):
            return jsonify({"ok": True, "output": out.strip()})
        if "401" in out or "Unauthorized" in out.lower():
            return jsonify({"ok": False, "error": "Tomcat Manager auth failed — configure tomcat_manager_user/pass in app screen_config"})
        return jsonify({"ok": False, "error": out.strip() or "Action failed"})

    @app.route("/api/local-app/<app_name>/tomcat/deploy", methods=["POST"])
    def api_local_tomcat_deploy(app_name):
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        if request.files.get("war"):
            # Same as Tomcat Manager's "WAR file to deploy": upload + deploy, context path from the file name (ROOT.war -> /)
            up = request.files["war"]
            fname = Path(up.filename or "").name
            if not fname.lower().endswith(".war"):
                return jsonify({"ok": False, "error": "Choose a .war file"})
            stem = fname[:-4]
            container = _get_local_tomcat_container(app_name)
            cfg = _get_local_tomcat_cfg(app_name)
            ok, msg = _manager_deploy_war(container, cfg, up, stem)
            return jsonify({"ok": ok, ("output" if ok else "error"): msg})
        body = request.get_json() or {}
        path     = body.get("path", "").strip()
        war_path = body.get("war_path", "").strip()
        if not path:
            return jsonify({"ok": False, "error": "context path is required (e.g. /myapp)"})
        if not war_path:
            return jsonify({"ok": False, "error": "war_path is required (local path to WAR file)"})
        container = _get_local_tomcat_container(app_name)
        cfg = _get_local_tomcat_cfg(app_name)
        mgr_user = cfg.get("tomcat_manager_user", "admin")
        mgr_pass = cfg.get("tomcat_manager_pass", "admin")
        mgr_port = cfg.get("tomcat_manager_port") or cfg.get("port", 8080)
        ctx_name = path.lstrip("/") or "app"
        import subprocess as _sp_ltd
        r = _sp_ltd.run(["docker", "cp", war_path, f"{container}:/tmp/{ctx_name}.war"],
                        capture_output=True, text=True,
                        creationflags=0x08000000 if sys.platform == "win32" else 0)
        if r.returncode != 0:
            return jsonify({"ok": False, "error": f"Could not copy WAR to container: {r.stderr.strip()}"})
        deploy_script = (
            f"curl -s -u {mgr_user}:{mgr_pass} "
            f"\"http://localhost:{mgr_port}/manager/text/deploy?path={path}&update=true\" "
            f"--upload-file /tmp/{ctx_name}.war 2>&1; "
            f"rm -f /tmp/{ctx_name}.war"
        )
        ok, out, err = _local_tomcat_exec(container, deploy_script, timeout=60)
        if out.startswith("OK"):
            return jsonify({"ok": True, "output": out.strip()})
        if "401" in out or "Unauthorized" in out.lower():
            return jsonify({"ok": False, "error": "Tomcat Manager auth failed — configure tomcat_manager_user/pass"})
        return jsonify({"ok": False, "error": out.strip() or "Deploy failed"})

    @app.route("/api/remote-app/<app_name>/web-services", methods=["GET"])
    def api_remote_generic_web_services(app_name):
        import urllib.request as _urlreq_ws, ssl as _ssl_ws, re as _re_ws
        vm_ip = request.args.get("vm_ip", "")
        force = request.args.get("force", "").lower() in ("1", "true", "yes")
        if app_name not in _ALL_REMOTE_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        ws_cache_key = f"web_services_{app_name}"
        if not force:
            cached = _rcache_get(vm_ip, ws_cache_key)
            if cached is not None:
                return jsonify({**cached, "cached": True})
        # Resolve services_url + karaf_services_url: vm_dependencies.xlsx → screen_config settings → default
        vm_deps = _read_vm_cmd_deps(app_name)
        services_url  = vm_deps.get("services_url", "")
        karaf_svc_url = vm_deps.get("karaf_services_url", "")
        if not services_url or not karaf_svc_url:
            try:
                import openpyxl as _xl_ws
                _scfg = _remote_app_root(app_name) / "screen_config.xlsx"
                if _scfg.exists():
                    _wb_ws = _xl_ws.load_workbook(str(_scfg), data_only=True)
                    for _r_ws in _wb_ws.active.iter_rows(min_row=2, values_only=True):
                        if _r_ws and str(_r_ws[0]).strip().lower() == "settings":
                            _k_ws = str(_r_ws[1]).strip().lower() if _r_ws[1] else ""
                            if _k_ws == "services_url" and not services_url:
                                services_url = str(_r_ws[2]).strip() if _r_ws[2] else ""
                            elif _k_ws == "karaf_services_url" and not karaf_svc_url:
                                karaf_svc_url = str(_r_ws[2]).strip() if _r_ws[2] else ""
            except Exception:
                pass
        if not services_url:
            remote_def = _REMOTE_APP_DEFAULTS.get(app_name, {})
            port = remote_def.get("port", 7001)
            services_url = f"http://{{vm_ip}}:{port}/web-services"
        if not karaf_svc_url:
            karaf_svc_url = _REMOTE_APP_DEFAULTS.get(app_name, {}).get("karaf_services_url", "")
        # Substitute {vm_ip} placeholder
        services_url  = services_url.replace("{vm_ip}", vm_ip)
        karaf_svc_url = karaf_svc_url.replace("{vm_ip}", vm_ip) if karaf_svc_url else ""
        ctx = _ssl_ws.create_default_context()
        ctx.check_hostname = False; ctx.verify_mode = _ssl_ws.CERT_NONE

        def _parse_ws(section_html):
            rows = _re_ws.findall(r'<tr>(.*?)</tr>', section_html, _re_ws.S)
            svcs = []
            for row in rows:
                name_m = _re_ws.search(r'class="porttypename">([^<]+)<', row)
                if not name_m: continue
                ops    = _re_ws.findall(r'<li>([^<]+)</li>', row)
                ep_m   = _re_ws.search(r'Endpoint address.*?class="value">([^<]+)<', row, _re_ws.S)
                wsdl_m = _re_ws.search(r'href="([^"]+\?wsdl)"', row)
                ns_m   = _re_ws.search(r'Target namespace.*?class="value">([^<]+)<', row, _re_ws.S)
                svcs.append({"name": name_m.group(1).strip(), "ops": ops,
                             "endpoint": ep_m.group(1).strip() if ep_m else "",
                             "wsdl": wsdl_m.group(1).strip() if wsdl_m else "",
                             "namespace": ns_m.group(1).strip() if ns_m else ""})
            return svcs

        def _parse_karaf_cxf_ws(khtml):
            """Parse Apache CXF /services listing page for REST services.
            Handles the CXF format: <span class="value">ENDPOINT</span> + <a href="?_wadl">."""
            rest_idx = khtml.lower().find("available restful")
            soap_idx = khtml.lower().find("available soap", (rest_idx + 1) if rest_idx >= 0 else 0)
            if rest_idx < 0:
                rest_sec = khtml
            elif soap_idx > rest_idx:
                rest_sec = khtml[rest_idx:soap_idx]
            else:
                rest_sec = khtml[rest_idx:]
            svcs, seen = [], set()
            # Primary: parse <tr> blocks, endpoint in class="value" span
            for row in _re_ws.findall(r'<tr>(.*?)</tr>', rest_sec, _re_ws.S | _re_ws.I):
                ep_m = _re_ws.search(r'class=["\']value["\']>([^<]+)<', row, _re_ws.I)
                if not ep_m:
                    continue
                ep = ep_m.group(1).strip()
                if not ep or ep in seen:
                    continue
                seen.add(ep)
                wadl_m = _re_ws.search(r'href=["\']([^"\']+\?_wadl[^"\']*)["\']', row, _re_ws.I)
                wadl = wadl_m.group(1).strip() if wadl_m else ""
                name = ep.rstrip('/').split('/')[-1] or ep
                svcs.append({"name": name, "ops": [], "endpoint": ep, "wsdl": wadl, "namespace": ""})
            # Fallback: href-based links (older CXF versions)
            if not svcs:
                for m in _re_ws.finditer(r'<a\b[^>]+href=[\'"]([^\'"]+)[\'"][^>]*>([^<]*)</a>', rest_sec, _re_ws.I):
                    href, text = m.group(1).strip(), m.group(2).strip()
                    if not href or href.startswith('#'):
                        continue
                    ep = href.split("?")[0] if "?" in href else href
                    if not (ep.startswith("http") or ep.startswith("/")):
                        continue
                    if ep in seen:
                        continue
                    seen.add(ep)
                    name = text if (text and not text.startswith("http")) else (ep.rstrip('/').split('/')[-1] or ep)
                    svcs.append({"name": name, "ops": [], "endpoint": ep,
                                 "wsdl": href if "?" in href else "", "namespace": ""})
            return svcs

        soap, rest, main_err, main_html = [], [], None, None
        try:
            req = _urlreq_ws.Request(services_url, headers={"User-Agent": "IDP/1.0"})
            with _urlreq_ws.urlopen(req, timeout=10, context=ctx) as r:
                main_html = r.read().decode("utf-8", errors="replace")
            soap_start = main_html.find("Available SOAP")
            rest_start = main_html.find("Available RESTful")
            soap_html = main_html[soap_start:rest_start] if rest_start > soap_start > 0 else main_html[soap_start:]
            rest_html = main_html[rest_start:] if rest_start > 0 else ""
            soap = _parse_ws(soap_html)
            rest = _parse_ws(rest_html)
        except Exception as e:
            main_err = str(e)

        if karaf_svc_url:
            # Reuse already-fetched HTML if the URLs are the same
            if karaf_svc_url == services_url and main_html is not None:
                karaf_html = main_html
            else:
                karaf_html = None
                try:
                    req2 = _urlreq_ws.Request(karaf_svc_url, headers={"User-Agent": "IDP/1.0"})
                    with _urlreq_ws.urlopen(req2, timeout=10, context=ctx) as r2:
                        karaf_html = r2.read().decode("utf-8", errors="replace")
                except Exception:
                    pass
            if karaf_html is not None:
                karaf_rest = _parse_karaf_cxf_ws(karaf_html)
                existing_eps = {s["endpoint"] for s in rest}
                for s in karaf_rest:
                    if s["endpoint"] not in existing_eps:
                        rest.append(s)
                        existing_eps.add(s["endpoint"])

        if main_err and not soap and not rest:
            return jsonify({"ok": False, "error": main_err})
        result = {"ok": True, "soap": soap, "rest": rest, "url": services_url}
        _rcache_set(vm_ip, ws_cache_key, result)
        return jsonify(result)

    # ── Remote App Development endpoints (SSH-based via VM) ─────────────────────

    _REMOTE_DEV_DEFAULT_VM = "10.192.251.19"
    _ALL_REMOTE_APPS = {"payor", "classic", "connector", "enrollment", "pik"}

    _REMOTE_APP_DEFAULTS = {
        "payor":      {"container": "payor-tc",      "port": 7001, "props_path": "/home/weblogic/domains/healthedge/runtime.properties", "git_pattern": "hrp.payer.core-*"},
        "classic":    {"container": "classic-tc",    "port": 7002, "props_path": "/home/weblogic/domains/healthedge/runtime.properties", "git_pattern": "classic-*"},
        "connector":  {"container": "connector",     "port": 8080, "props_path": "/home/connector/config/connector.properties",         "git_pattern": "connector-*", "karaf_services_url": "http://{vm_ip}:8181/connector/services"},
        "enrollment": {"container": "enrollment-tc", "port": 7003, "props_path": "/home/weblogic/domains/healthedge/runtime.properties", "git_pattern": "enrollment-*", "karaf_services_url": "http://{vm_ip}:8181/connector/services"},
        "pik":        {"container": "pik-tc",        "port": 7004, "props_path": "/home/weblogic/domains/healthedge/runtime.properties", "git_pattern": "pik-*"},
    }

    def _read_remote_app_config(app_name):
        import json as _json
        defaults = dict(_REMOTE_APP_DEFAULTS.get(app_name, {}))
        # Read global remote config for VM
        global_cfg_file = WORKFLOWS_ROOT / "Remote_Build_And_Deployment" / "config.json"
        if global_cfg_file.exists():
            try:
                gcfg = _json.loads(global_cfg_file.read_text(encoding="utf-8"))
                defaults["default_vm_ip"] = gcfg.get("default_vm_ip", _REMOTE_DEV_DEFAULT_VM)
                defaults["ssh_user"]      = gcfg.get("ssh_user", "ec2-user")
            except Exception:
                pass
        # vm_dependencies takes precedence for git_pattern and src_dir
        deps = _read_vm_cmd_deps(app_name)
        for key in ("git_pattern", "src_dir", "check_server"):
            val = deps.get(key, "").strip()
            if val:
                defaults[key] = val
        return defaults

    def _lookup_vm_credentials(vm_ip):
        """Look up username + password for a VM IP from vms.xlsx.
        Returns (username, password, key_path) — any field may be empty string."""
        username = "weblogic"
        password = ""
        key_path = ""
        # Check Remote_Build_And_Deployment/config.json for ssh_key_path / ssh_user
        try:
            import json as _j
            rbd_cfg_file = WORKFLOWS_ROOT / "Remote_Build_And_Deployment" / "config.json"
            if rbd_cfg_file.exists():
                rbd_cfg = _j.loads(rbd_cfg_file.read_text(encoding="utf-8"))
                if rbd_cfg.get("ssh_user"):
                    username = rbd_cfg["ssh_user"]
                if rbd_cfg.get("ssh_key_path"):
                    key_path = rbd_cfg["ssh_key_path"]
        except Exception:
            pass
        # Look up VM by IP in vms.xlsx to get password
        if VMS_FILE.exists():
            try:
                import openpyxl as _xl
                wb   = _xl.load_workbook(str(VMS_FILE))
                for sheet in wb.sheetnames:
                    ws   = wb[sheet]
                    hdrs = [str(ws.cell(1, c).value or "").strip().lower()
                            for c in range(1, ws.max_column + 1)]
                    if "ip" not in hdrs:
                        continue
                    for row in ws.iter_rows(min_row=2, values_only=True):
                        d = {k: ("" if v is None else str(v).strip())
                             for k, v in zip(hdrs, row)}
                        if d.get("ip", "") == vm_ip:
                            if d.get("password"):
                                password = d["password"]
                            # 'description' field can hold the username for dev VMs
                            if d.get("description", "").strip().replace(" ", "") in ("ec2-user", "weblogic", "ubuntu", "centos"):
                                username = d["description"].strip()
                            break
                    else:
                        continue
                    break
            except Exception:
                pass
        return username, password, key_path

    def _get_ssh_semaphore(vm_ip):
        with _ssh_vm_sem_lock:
            if vm_ip not in _ssh_vm_semaphores:
                _ssh_vm_semaphores[vm_ip] = _threading.Semaphore(_SSH_MAX_CONCURRENT_PER_VM)
            return _ssh_vm_semaphores[vm_ip]

    def _make_ssh_client(vm_ip, username=None, timeout=30):
        """Create and return a connected paramiko SSHClient. Caller must close it."""
        import paramiko as _pm
        vm_user, vm_pass, vm_key = _lookup_vm_credentials(vm_ip)
        effective_user = username or vm_user
        client = _pm.SSHClient()
        client.set_missing_host_key_policy(_pm.AutoAddPolicy())
        ckw = dict(
            hostname=vm_ip, port=22, username=effective_user,
            timeout=timeout, banner_timeout=timeout + 10, auth_timeout=timeout,
            allow_agent=False, look_for_keys=False,
        )
        if vm_key and Path(vm_key).exists():
            ckw["key_filename"] = vm_key
            # explicit key file — don't scan ~/.ssh/
        else:
            # No specific key file: always scan ~/.ssh/ (ec2-user and similar use key auth)
            ckw["look_for_keys"] = True
            if vm_pass:
                ckw["password"] = vm_pass   # also try password as a fallback
        client.connect(**ckw)
        return client

    def _pooled_client(vm_ip, username=None, timeout=None):
        """Return a live pooled SSHClient for vm_ip, connecting/reconnecting as needed.
        Caller must NOT close the client — it stays in the pool for reuse."""
        import time as _time
        if timeout is None:
            timeout = int(_IDP_CFG.get("ssh_connect_timeout_s", 30))
        with _ssh_pool_lock:
            client = _ssh_pool.get(vm_ip)
            if client is not None:
                transport = client.get_transport()
                if transport and transport.is_active():
                    return client
                # Dead connection — evict and reconnect below
                try: client.close()
                except Exception: pass
                del _ssh_pool[vm_ip]
            client = _make_ssh_client(vm_ip, username, timeout)
            # Enable keepalive so idle connections survive server-side SSH timeouts
            try:
                if _SSH_KEEPALIVE_S > 0:
                    client.get_transport().set_keepalive(_SSH_KEEPALIVE_S)
            except Exception: pass
            _ssh_pool[vm_ip] = client
            return client

    def _evict_pooled_client(vm_ip):
        """Remove a VM's pooled connection (called on error so next use reconnects)."""
        with _ssh_pool_lock:
            client = _ssh_pool.pop(vm_ip, None)
            if client:
                try: client.close()
                except Exception: pass

    def _ssh_run(vm_ip, cmd, username=None, timeout=None):
        import time as _time
        try:
            import paramiko as _pm  # noqa
        except ImportError:
            return False, "", "paramiko not installed. Run: pip install paramiko"
        if timeout is None:
            timeout = int(_IDP_CFG.get("ssh_connect_timeout_s", 30))
        sem = _get_ssh_semaphore(vm_ip)
        _q_timeout = int(_IDP_CFG.get("ssh_queue_timeout_s", 120))
        acquired = sem.acquire(blocking=True, timeout=_q_timeout)
        if not acquired:
            return False, "", "SSH queue timeout: too many concurrent connections to this VM"
        try:
            last_err = ""
            for attempt in range(3):
                if attempt:
                    _time.sleep(2 * attempt)
                try:
                    client = _pooled_client(vm_ip, username, timeout)
                    _, stdout, stderr = client.exec_command(cmd, timeout=timeout)
                    out = stdout.read().decode(errors="replace").strip()
                    err = stderr.read().decode(errors="replace").strip()
                    return True, out, err
                except Exception as e:
                    last_err = str(e)
                    _evict_pooled_client(vm_ip)  # force reconnect on next attempt
                    _retryable = ("banner" in last_err.lower() or "eof" in last_err.lower()
                                  or "no existing session" in last_err.lower()
                                  or "timed out" in last_err.lower())
                    if not _retryable:
                        break
            return False, "", last_err
        finally:
            sem.release()

    def _ssh_stream(vm_ip, cmd, on_line, abort_event=None, username=None, timeout=None):
        """Run cmd via SSH and call on_line(line) for each stdout line as it arrives.
        Returns True if the command exited 0, False otherwise.
        If abort_event is set mid-run the channel is closed immediately."""
        if timeout is None:
            timeout = int(_IDP_CFG.get("ssh_connect_timeout_s", 30))
        sem = _get_ssh_semaphore(vm_ip)
        _q_timeout = int(_IDP_CFG.get("ssh_queue_timeout_s", 120))
        acquired = sem.acquire(blocking=True, timeout=_q_timeout)
        if not acquired:
            on_line("SSH queue timeout: too many concurrent connections to this VM\n")
            return False
        try:
            client = _pooled_client(vm_ip, username, timeout)
            _, stdout, _ = client.exec_command(cmd, timeout=timeout)
            for raw in iter(stdout.readline, ""):
                if abort_event and abort_event.is_set():
                    try: stdout.channel.close()
                    except Exception: pass
                    return False
                on_line(raw)
            return stdout.channel.recv_exit_status() == 0
        except Exception as e:
            on_line(f"\nError: {e}\n")
            _evict_pooled_client(vm_ip)
            return False
        finally:
            sem.release()

    def _ssh_run_multi(vm_ip, cmds, username=None, timeout=None):
        """Open ONE SSH connection and run all commands simultaneously via parallel channels.
        Returns list of (ok, out, err) in the same order as cmds."""
        if not cmds:
            return []
        if timeout is None:
            timeout = int(_IDP_CFG.get("ssh_connect_timeout_s", 30))
        sem = _get_ssh_semaphore(vm_ip)
        _q_timeout = int(_IDP_CFG.get("ssh_queue_timeout_s", 120))
        acquired = sem.acquire(blocking=True, timeout=_q_timeout)
        if not acquired:
            return [(False, "", "SSH queue timeout")] * len(cmds)
        try:
            client = _pooled_client(vm_ip, username, timeout)
            # Launch all commands simultaneously — each exec_command opens an independent channel
            channels = []
            for cmd in cmds:
                _, stdout, stderr = client.exec_command(cmd, timeout=timeout)
                channels.append((stdout, stderr))
            # Collect results (channels run in parallel on the VM)
            results = []
            for stdout, stderr in channels:
                out = stdout.read().decode(errors="replace").strip()
                err = stderr.read().decode(errors="replace").strip()
                results.append((True, out, err))
            return results
        except Exception as e:
            _evict_pooled_client(vm_ip)  # force reconnect on next call
            return [(False, "", str(e))] * len(cmds)
        finally:
            sem.release()

    # ── SSH pool settings endpoint ────────────────────────────────────────────
    @app.route("/api/ssh-pool/settings", methods=["GET", "POST"])
    def api_ssh_pool_settings():
        global _SSH_KEEPALIVE_S
        if request.method == "GET":
            with _ssh_pool_lock:
                connected_vms = list(_ssh_pool.keys())
            return jsonify({"ok": True, "keepalive_s": _SSH_KEEPALIVE_S, "connected_vms": connected_vms})
        body = request.get_json() or {}
        if "keepalive_s" in body:
            _SSH_KEEPALIVE_S = int(body["keepalive_s"])
        # Evict all pooled connections so they reconnect with the new keepalive setting
        with _ssh_pool_lock:
            for client in list(_ssh_pool.values()):
                try: client.close()
                except Exception: pass
            _ssh_pool.clear()
        return jsonify({"ok": True, "keepalive_s": _SSH_KEEPALIVE_S})

    # ── Remote data cache helpers ──────────────────────────────────────────────

    def _rcache_ttl():
        import json as _json
        try:
            if REMOTE_CACHE_CONFIG_FILE.exists():
                cfg = _json.loads(REMOTE_CACHE_CONFIG_FILE.read_text(encoding="utf-8"))
                return int(cfg.get("ttl_seconds", _REMOTE_CACHE_TTL_DEFAULT))
        except Exception:
            pass
        return _REMOTE_CACHE_TTL_DEFAULT

    def _rcache_get(vm_ip, cache_type, ttl=None):
        import time as _t
        key = (vm_ip, cache_type)
        with _remote_cache_lock:
            entry = _remote_cache.get(key)
        effective_ttl = ttl if ttl is not None else _rcache_ttl()
        if entry and (_t.time() - entry["ts"]) < effective_ttl:
            return entry["data"]
        return None

    def _rcache_set(vm_ip, cache_type, data):
        import time as _t
        key = (vm_ip, cache_type)
        with _remote_cache_lock:
            _remote_cache[key] = {"data": data, "ts": _t.time()}

    def _rcache_invalidate(vm_ip, cache_type):
        key = (vm_ip, cache_type)
        with _remote_cache_lock:
            _remote_cache.pop(key, None)

    def _rcache_invalidate_vm(vm_ip):
        with _remote_cache_lock:
            for k in [k for k in _remote_cache if k[0] == vm_ip]:
                del _remote_cache[k]

    @app.route("/api/remote-app/cache/config", methods=["GET"])
    def api_remote_cache_config_get():
        import json as _json
        cfg = {"ttl_seconds": _rcache_ttl()}
        try:
            if REMOTE_CACHE_CONFIG_FILE.exists():
                cfg.update(_json.loads(REMOTE_CACHE_CONFIG_FILE.read_text(encoding="utf-8")))
                cfg.setdefault("ttl_seconds", _REMOTE_CACHE_TTL_DEFAULT)
        except Exception:
            pass
        with _remote_cache_lock:
            entries = [
                {"vm_ip": k[0], "type": k[1],
                 "age_seconds": round(__import__("time").time() - v["ts"])}
                for k, v in _remote_cache.items()
            ]
        return jsonify({"ok": True, "config": cfg, "cached_entries": entries,
                        "default_ttl_seconds": _REMOTE_CACHE_TTL_DEFAULT})

    @app.route("/api/remote-app/cache/config", methods=["POST"])
    def api_remote_cache_config_set():
        import json as _json
        body = request.get_json() or {}
        ttl = body.get("ttl_seconds")
        if ttl is not None:
            try:
                ttl = int(ttl)
                if ttl < 0:
                    return jsonify({"ok": False, "error": "ttl_seconds must be >= 0"}), 400
            except (TypeError, ValueError):
                return jsonify({"ok": False, "error": "ttl_seconds must be an integer"}), 400
        try:
            existing = {}
            if REMOTE_CACHE_CONFIG_FILE.exists():
                existing = _json.loads(REMOTE_CACHE_CONFIG_FILE.read_text(encoding="utf-8"))
            if ttl is not None:
                existing["ttl_seconds"] = ttl
            REMOTE_CACHE_CONFIG_FILE.parent.mkdir(parents=True, exist_ok=True)
            REMOTE_CACHE_CONFIG_FILE.write_text(_json.dumps(existing, indent=2), encoding="utf-8")
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})
        return jsonify({"ok": True, "config": {"ttl_seconds": _rcache_ttl()}})

    @app.route("/api/remote-app/cache/clear", methods=["POST"])
    def api_remote_cache_clear():
        body  = request.get_json() or {}
        vm_ip = body.get("vm_ip")
        ctype = body.get("type")
        with _remote_cache_lock:
            if vm_ip and ctype:
                _remote_cache.pop((vm_ip, ctype), None)
            elif vm_ip:
                for k in [k for k in _remote_cache if k[0] == vm_ip]:
                    del _remote_cache[k]
            else:
                _remote_cache.clear()
        return jsonify({"ok": True})

    # ── Remote build analytics ────────────────────────────────────────────────
    def _remote_analytics_file(app_name):
        return _remote_app_root(app_name) / "stats" / "buildstats.xlsx"

    def _get_remote_build_estimate(app_name, params_key):
        """Median duration_ms of last ≤10 successful builds with same params, or None."""
        f = _remote_analytics_file(app_name)
        if not f.exists():
            return None
        try:
            import openpyxl as _xl2
            wb = _xl2.load_workbook(str(f), data_only=True)
            ws = wb.active
            hdrs = [str(ws.cell(1, c).value or "").strip().lower() for c in range(1, ws.max_column + 1)]
            durations = []
            for row in ws.iter_rows(min_row=2, values_only=True):
                d = {k: ("" if v is None else str(v)) for k, v in zip(hdrs, row)}
                if d.get("parameters") == params_key and d.get("build_status") == "success":
                    try:
                        durations.append(int(float(d.get("duration_ms", 0))))
                    except (ValueError, TypeError):
                        pass
            durations = durations[-10:]
            if not durations:
                return None
            s = sorted(durations)
            n = len(s)
            return s[n // 2] if n % 2 else (s[n // 2 - 1] + s[n // 2]) // 2
        except Exception:
            return None

    def _save_remote_build_stats(app_name, params_key, duration_ms, status):
        """Append to stats/buildstats.xlsx; trim per-params rows to ≤10."""
        from datetime import datetime as _dt2
        try:
            import openpyxl as _xl2
            from openpyxl.styles import Font as _Fnt2, PatternFill as _PFill2
            f = _remote_analytics_file(app_name)
            f.parent.mkdir(parents=True, exist_ok=True)
            HDRS   = ["id", "timestamp", "module", "parameters", "duration_ms", "build_status"]
            WIDTHS = [8, 22, 30, 40, 14, 14]
            if not f.exists():
                wb = _xl2.Workbook()
                ws = wb.active
                ws.title = "Build Stats"
                hf = _Fnt2(bold=True, color="FFFFFF", name="Calibri")
                hb = _PFill2("solid", fgColor="4472C4")
                for i, (h, w) in enumerate(zip(HDRS, WIDTHS), 1):
                    c = ws.cell(1, i, h); c.font = hf; c.fill = hb
                    ws.column_dimensions[c.column_letter].width = w
            else:
                wb = _xl2.load_workbook(str(f))
                ws = wb.active
            hdrs2 = [str(ws.cell(1, c).value or "").strip().lower() for c in range(1, ws.max_column + 1)]
            p_col = (hdrs2.index("parameters") + 1) if "parameters" in hdrs2 else 4
            max_id = max((int(ws.cell(r, 1).value or 0) for r in range(2, ws.max_row + 1)
                          if ws.cell(r, 1).value is not None), default=0)
            ws.append([max_id + 1, _dt2.now().strftime("%Y-%m-%d %H:%M:%S"),
                       "full", params_key, duration_ms, status])
            wb.save(str(f))
            wb2 = _xl2.load_workbook(str(f))
            ws2 = wb2.active
            combo_rows = [r for r in range(2, ws2.max_row + 1)
                          if str(ws2.cell(r, p_col).value or "") == params_key]
            if len(combo_rows) > 10:
                for r in sorted(combo_rows[:-10], reverse=True):
                    ws2.delete_rows(r)
                wb2.save(str(f))
        except Exception:
            pass

