    @app.route("/api/remote-app/<app_name>/deploy-config", methods=["GET"])
    def api_remote_deploy_config_get(app_name):
        if app_name not in _ALL_REMOTE_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        try:
            import openpyxl as _xl
            xlsx = _remote_app_root(app_name) / "build_deploy_config.xlsx"
            if not xlsx.exists():
                return jsonify({"ok": True, "deploy": []})
            wb = _xl.load_workbook(str(xlsx), data_only=True)
            wsn = next((s for s in wb.sheetnames if s.lower() == "deploy"), None)
            if not wsn:
                return jsonify({"ok": True, "deploy": []})
            rows = []
            for row in wb[wsn].iter_rows(min_row=2, values_only=True):
                if not (row and row[0]):
                    continue
                rows.append({
                    "key":         str(row[0]).strip() if row[0] is not None else "",
                    "value":       str(row[1]).strip() if len(row) > 1 and row[1] is not None else "",
                    "condition":   str(row[2]).strip() if len(row) > 2 and row[2] is not None else "",
                    "description": str(row[3]).strip() if len(row) > 3 and row[3] is not None else "",
                })
            return jsonify({"ok": True, "deploy": rows})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)}), 500

    @app.route("/api/remote-app/<app_name>/deploy-config", methods=["POST"])
    def api_remote_deploy_config_save(app_name):
        if app_name not in _ALL_REMOTE_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        deploy_rows = (request.get_json() or {}).get("deploy", [])
        try:
            import openpyxl as _xl
            from openpyxl.styles import Font as _RFnt, PatternFill as _RFill
            xlsx = _remote_app_root(app_name) / "build_deploy_config.xlsx"
            wb = _xl.load_workbook(str(xlsx)) if xlsx.exists() else _xl.Workbook()
            wsn = next((s for s in wb.sheetnames if s.lower() == "deploy"), None)
            if wsn:
                del wb[wsn]
            ws = wb.create_sheet("Deploy")
            f  = _RFnt(bold=True, color="FFFFFF", name="Calibri")
            bg = _RFill("solid", fgColor="4472C4")
            for i, (h, w) in enumerate(zip(["Key", "Value", "Condition", "Description"], [25, 35, 15, 50]), 1):
                c = ws.cell(1, i, h); c.font = f; c.fill = bg
                ws.column_dimensions[c.column_letter].width = w
            for r in deploy_rows:
                ws.append([r.get("key",""), r.get("value",""), r.get("condition",""), r.get("description","")])
            if "Sheet" in wb.sheetnames and wb["Sheet"].max_row <= 1:
                del wb["Sheet"]
            xlsx.parent.mkdir(parents=True, exist_ok=True)
            wb.save(str(xlsx))
            return jsonify({"ok": True})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)}), 500

    # ── Remote command runner ──────────────────────────────────────────────────
    _remote_cmd_state = {}   # cmd_id → {status, output, started_at}
    _REMOTE_BUILD_SUCCESS_PATTERNS = {
        "connector":  "has status of Running",
        "enrollment": "Successfully Added",
    }

    @app.route("/api/remote-app/<app_name>/run-command", methods=["POST"])
    def api_remote_run_command(app_name):
        if app_name not in _ALL_REMOTE_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        body = request.get_json() or {}
        vm_ip   = body.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
        command = (body.get("command") or "").strip()
        if not command:
            return jsonify({"ok": False, "error": "command is required"}), 400
        cfg         = _read_remote_app_config(app_name)
        git_pattern = cfg.get("git_pattern", f"{app_name}-*")
        git_prefix  = git_pattern.split('*')[0]   # e.g. "hrp.payer.core-"
        deps_rc     = _read_vm_cmd_deps(app_name)
        dflt_branch_file_rc = deps_rc.get("default_branch_file", "~/.default-branch")
        full_cmd = (
            f'[ -f $HOME/.bash_profile ] && . $HOME/.bash_profile 2>/dev/null; '
            f'[ -f $HOME/.bashrc ] && . $HOME/.bashrc 2>/dev/null; '
            f'_DEF=$(cat {dflt_branch_file_rc} 2>/dev/null | tr -d "\\n"); '
            f'REPO=""; '
            f'for _BASE in "${{GIT_HOME:-}}" "$HOME" /home/weblogic /opt; do '
            f'  [ -z "$_BASE" ] && continue; '
            f'  if [ -n "$_DEF" ]; then '
            f'    _F=$(ls -d "$_BASE"/{git_prefix}${{_DEF}} 2>/dev/null | head -1); '
            f'    [ -n "$_F" ] && REPO="$_F" && break; '
            f'  fi; '
            f'  _F=$(ls -d "$_BASE"/{git_pattern} 2>/dev/null | head -1); '
            f'  [ -n "$_F" ] && REPO="$_F" && break; '
            f'done; '
            f'[ -z "$REPO" ] && echo "ERROR: repo matching {git_pattern} not found" && exit 1; '
            f'cd "$REPO" && {command} 2>&1'
        )
        import uuid as _uuid, time as _time, threading as _thr
        cmd_id = _uuid.uuid4().hex[:8]
        _remote_cmd_state[cmd_id] = {"status": "running", "output": f"Running on {vm_ip}…\n", "started_at": _time.time(), "command": command, "vm_ip": vm_ip, "app_name": app_name}

        def _run_bg():
            import re as _re2, time as _tm2
            _mod_pat    = _re2.compile(r'Building\s+(.+?)\s+\[(\d+)/(\d+)\]')
            _ansi_pat   = _re2.compile(r'\x1b\[[0-9;?]*[A-Za-z]')
            _ph_rank    = {"building": 0, "deploying": 1, "stopping": 2, "creating_schema": 3, "starting": 4, "bootstrapping": 5}
            _deploy_pat = _re2.compile(r'\bdeploy\b|copying.*\.(war|jar)\b|stopping\s+tomcat', _re2.I)
            _schema_pat = _re2.compile(r'creat.*schema|running.*ddl|create\s+table', _re2.I)
            _boot_pat   = _re2.compile(r'bootstrap', _re2.I)
            _start_pat  = _re2.compile(r'starting.*(tomcat|server|weblogic|artemis)|start.*(tomcat|weblogic)', _re2.I)
            _cmd_parts  = command.strip().split()
            _flags      = _cmd_parts[1:] if len(_cmd_parts) > 1 else []
            _params_key = " ".join(sorted(_flags)) if _flags else "(none)"
            _start_ms   = int(_tm2.time() * 1000)
            _est_ms     = _get_remote_build_estimate(app_name, _params_key)
            _remote_cmd_state[cmd_id].update({
                "start_ms": _start_ms, "estimated_ms": _est_ms,
                "elapsed_ms": 0, "progress": None,
                "current_module": None, "module_num": None, "total_modules": None,
                "phase": "building",
            })
            _build_phase_done = [False]
            try:
                import paramiko as _pm
                vm_user, vm_pass, vm_key = _lookup_vm_credentials(vm_ip)
                client = _pm.SSHClient()
                client.set_missing_host_key_policy(_pm.AutoAddPolicy())
                kw = dict(hostname=vm_ip, port=22, username=vm_user, timeout=15)
                if vm_key and Path(vm_key).exists():
                    kw.update(key_filename=vm_key, look_for_keys=False, allow_agent=False)
                elif vm_pass:
                    kw.update(password=vm_pass, look_for_keys=False, allow_agent=False)
                client.connect(**kw)
                _, stdout, stderr = client.exec_command(full_cmd, timeout=7200, get_pty=True)   # pty: line-buffered, progress never stalls
                buf = f"Running on {vm_ip}…\n"
                for raw in stdout:
                    line    = raw if isinstance(raw, str) else raw.decode(errors="replace")
                    line    = _ansi_pat.sub("", line).replace("\r", "")
                    buf    += line
                    now_ms  = int(_tm2.time() * 1000)
                    elapsed = now_ms - _start_ms
                    st      = _remote_cmd_state[cmd_id]
                    m = _mod_pat.search(line)
                    if m and not _build_phase_done[0]:
                        st["current_module"] = _mvn_artifact_id(m.group(1))
                        st["module_num"]     = int(m.group(2))
                        st["total_modules"]  = int(m.group(3))
                    if not _build_phase_done[0]:
                        if "BUILD SUCCESS" in line or "BUILD FAILURE" in line:
                            _build_phase_done[0] = True
                            st["current_module"] = None
                            if "BUILD SUCCESS" in line:
                                st["phase"] = "deploying"
                    else:
                        _np = "creating_schema" if _schema_pat.search(line) else ("bootstrapping" if _boot_pat.search(line) else ("starting" if _start_pat.search(line) else None))
                        if _np and _ph_rank.get(_np, 0) >= _ph_rank.get(st.get("phase"), 0):
                            st["phase"] = _np
                    if _est_ms and _est_ms > 0:
                        st["progress"] = min(int(elapsed / _est_ms * 100), 95)
                    elif st.get("total_modules") and st.get("module_num"):
                        st["progress"] = min(int(st["module_num"] / st["total_modules"] * 80), 80)
                    st["output"]     = buf
                    st["elapsed_ms"] = elapsed
                err_out = stderr.read().decode(errors="replace").strip()
                if err_out:
                    buf += "\n" + err_out
                exit_code     = stdout.channel.recv_exit_status()
                client.close()
                final_elapsed = int(_tm2.time() * 1000) - _start_ms
                _spat = _REMOTE_BUILD_SUCCESS_PATTERNS.get(app_name.lower(), "")
                final_status  = "success" if exit_code == 0 or (_spat and _spat in buf) else "failed"
                _remote_cmd_state[cmd_id].update({
                    "output":         buf.strip(),
                    "status":         final_status,
                    "elapsed_ms":     final_elapsed,
                    "progress":       100 if final_status == "success" else _remote_cmd_state[cmd_id].get("progress"),
                    "phase":          None,
                    "current_module": None,
                })
                _save_remote_build_stats(app_name, _params_key, final_elapsed, final_status)
            except Exception as exc:
                _remote_cmd_state[cmd_id]["output"] = _remote_cmd_state[cmd_id].get("output", "") + f"\nError: {exc}"
                _remote_cmd_state[cmd_id]["status"] = "failed"

        _thr.Thread(target=_run_bg, daemon=True).start()
        return jsonify({"ok": True, "cmd_id": cmd_id})

    @app.route("/api/remote-app/<app_name>/command-status", methods=["GET"])
    def api_remote_command_status(app_name):
        import time as _t2
        cmd_id = request.args.get("cmd_id", "")
        state  = _remote_cmd_state.get(cmd_id)
        if not state:
            return jsonify({"ok": False, "error": "Unknown cmd_id"})
        resp = dict(state)
        if state.get("status") == "running" and state.get("start_ms"):
            resp["elapsed_ms"] = int(_t2.time() * 1000) - state["start_ms"]
        return jsonify({"ok": True, **resp})

