    @app.route("/api/remote-app/<app_name>/open-terminal", methods=["POST"])
    def api_remote_app_open_terminal(app_name):
        """Open an SSH terminal for any app (same as payor but with app-specific source alias)."""
        if app_name not in _ALL_REMOTE_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        body     = request.get_json() or {}
        vm_ip    = body.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
        vm_user, vm_pass, vm_key = _lookup_vm_credentials(vm_ip)
        deps         = _read_vm_cmd_deps(app_name)
        nav_cmd      = deps.get("terminal_init", "tosrc")
        init_cmd     = f"source ~/.bash_profile 2>/dev/null; source ~/.bashrc 2>/dev/null; {nav_cmd}"

        script = (
            "import sys, time, threading, pathlib\n"
            "import paramiko\n"
            f"_vm_ip   = {repr(vm_ip)}\n"
            f"_user    = {repr(vm_user)}\n"
            f"_pass    = {repr(vm_pass)}\n"
            f"_key     = {repr(vm_key)}\n"
            f"_init    = {repr(init_cmd)}\n"
            "print(f'Connecting to {_user}@{_vm_ip} ...')\n"
            "sys.stdout.flush()\n"
            "c = paramiko.SSHClient()\n"
            "c.set_missing_host_key_policy(paramiko.AutoAddPolicy())\n"
            "kw = dict(hostname=_vm_ip, port=22, username=_user, timeout=15)\n"
            "if _key and pathlib.Path(_key).exists():\n"
            "    kw.update(key_filename=_key, look_for_keys=False, allow_agent=False)\n"
            "elif _pass:\n"
            "    kw.update(password=_pass, look_for_keys=False, allow_agent=False)\n"
            "try:\n"
            "    c.connect(**kw)\n"
            "except Exception as e:\n"
            "    print(f'Connection failed: {e}'); input('Press Enter to close...'); sys.exit(1)\n"
            "print('Connected.')\n"
            "sys.stdout.flush()\n"
            "import shutil as _sh\n"
            "cols, rows = _sh.get_terminal_size((200, 50))\n"
            "ch = c.invoke_shell(term='xterm-256color', width=cols, height=rows)\n"
            "time.sleep(0.8)\n"
            "while ch.recv_ready(): sys.stdout.buffer.write(ch.recv(4096))\n"
            "sys.stdout.buffer.flush()\n"
            "ch.send(_init + '\\n')\n"
            "import msvcrt\n"
            "_done = threading.Event()\n"
            "def _rx():\n"
            "    while not _done.is_set():\n"
            "        if ch.recv_ready():\n"
            "            data = ch.recv(4096)\n"
            "            if not data: _done.set(); break\n"
            "            sys.stdout.buffer.write(data); sys.stdout.buffer.flush()\n"
            "        elif ch.closed: _done.set(); break\n"
            "        else: time.sleep(0.01)\n"
            "threading.Thread(target=_rx, daemon=True).start()\n"
            "_SPECIAL = {'K':'\\x1b[D','M':'\\x1b[C','H':'\\x1b[A','P':'\\x1b[B',"
            "            'S':'\\x1b[3~','G':'\\x1b[H','O':'\\x1b[F'}\n"
            "try:\n"
            "    while not _done.is_set():\n"
            "        if msvcrt.kbhit():\n"
            "            k = msvcrt.getwch()\n"
            "            if k in ('\\x00','\\xe0'):\n"
            "                k2 = msvcrt.getwch()\n"
            "                seq = _SPECIAL.get(k2)\n"
            "                if seq: ch.send(seq.encode())\n"
            "            else:\n"
            "                ch.send(k if isinstance(k,bytes) else k.encode('utf-8','replace'))\n"
            "        else: time.sleep(0.01)\n"
            "except (KeyboardInterrupt, EOFError):\n"
            "    try: ch.send(b'\\x03')\n"
            "    except Exception: pass\n"
            "c.close()\n"
            "print('\\n[SSH session closed]')\n"
            "input('Press Enter to close...')\n"
        )

        import tempfile, base64 as _b64
        tmp = tempfile.NamedTemporaryFile(
            mode="w", suffix=f"_idp_{app_name}_term.py", delete=False, encoding="utf-8"
        )
        tmp.write(script); tmp.flush(); tmp.close()

        ps_cmd = f'python "{tmp.name}"'
        try:
            encoded = _b64.b64encode(ps_cmd.encode("utf-16-le")).decode("ascii")
            subprocess.Popen(
                ["powershell.exe", "-EncodedCommand", encoded],
                creationflags=0x00000010,
            )
            return jsonify({"ok": True})
        except Exception as exc:
            return jsonify({"ok": False, "error": str(exc)})

    @app.route("/api/remote-app/<app_name>/modules", methods=["GET"])
    def api_remote_app_modules(app_name):
        """List modules (lpm --json) for any app."""
        if app_name not in _ALL_REMOTE_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        vm_ip = request.args.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
        force = request.args.get("force", "").lower() in ("1", "true", "yes")
        if not force:
            cached = _rcache_get(vm_ip, f"modules_{app_name}")
            if cached is not None:
                return jsonify({**cached, "cached": True})
        find = _remote_app_find_repo_cmd(app_name)
        # Build a shell lookup string for modules that have a specific target_artifact_name configured.
        # Format: "modA=specific.jar modB=specific.war ..."
        deploy_cfg   = _read_module_deploy_dirs(app_name)
        specific_arts = " ".join(
            f"{m}={cfg['target_artifact_name']}"
            for m, cfg in deploy_cfg.items()
            if cfg.get("target_artifact_name")
        )
        # Pure-shell module scan: no lpm dependency required.
        # For each subdirectory with pom.xml, check target artifact to determine ready vs needs_build.
        # If a specific target_artifact_name is configured for the module, check that exact file;
        # otherwise fall back to wildcard *.jar / *.war detection.
        cmd = (
            find +
            f"SPECIFIC_ARTS='{specific_arts}' && "
            "cd \"$SRCDIR\" && "
            "READY_JSON='' NEEDS_JSON='' RS='' NS=''; "
            "for d in */; do "
            "  [ -f \"${d}pom.xml\" ] || continue; "
            "  mod=\"${d%/}\"; "
            "  spec_art=''; "
            "  for pair in $SPECIFIC_ARTS; do "
            "    key=\"${pair%%=*}\"; val=\"${pair##*=}\"; "
            "    [ \"$key\" = \"$mod\" ] && spec_art=\"$val\" && break; "
            "  done; "
            "  if [ -n \"$spec_art\" ]; then "
            "    if [ -f \"${d}target/${spec_art}\" ]; then "
            "      READY_JSON=\"${READY_JSON}${RS}{\\\"name\\\":\\\"${mod}\\\",\\\"jar\\\":\\\"${spec_art}\\\"}\" ; RS=','; "
            "    else "
            "      NEEDS_JSON=\"${NEEDS_JSON}${NS}{\\\"name\\\":\\\"${mod}\\\"}\" ; NS=','; "
            "    fi; "
            "  else "
            "    jar=$(ls \"${d}target/\"*.war 2>/dev/null | head -1); "
            "    [ -z \"$jar\" ] && jar=$(ls \"${d}target/\"*.jar 2>/dev/null | grep -v '\\-sources\\.jar' | grep -v '\\-tests\\.jar' | head -1); "
            "    if [ -n \"$jar\" ]; then "
            "      jname=$(basename \"$jar\"); "
            "      READY_JSON=\"${READY_JSON}${RS}{\\\"name\\\":\\\"${mod}\\\",\\\"jar\\\":\\\"${jname}\\\"}\" ; RS=','; "
            "    else "
            "      NEEDS_JSON=\"${NEEDS_JSON}${NS}{\\\"name\\\":\\\"${mod}\\\"}\" ; NS=','; "
            "    fi; "
            "  fi; "
            "done; "
            "printf '{\"ready\":[%s],\"needs_build\":[%s]}' \"$READY_JSON\" \"$NEEDS_JSON\""
        )
        ok, out, err = _ssh_run(vm_ip, cmd)
        if not ok:
            return jsonify({"ok": False, "error": err or out or "SSH failed"})
        try:
            import json as _json
            data   = _json.loads(out.strip())
            result = {"ok": True, "ready": data.get("ready", []), "needs_build": data.get("needs_build", [])}
            _rcache_set(vm_ip, f"modules_{app_name}", result)
            return jsonify(result)
        except Exception:
            return jsonify({"ok": False, "error": out.strip() or "Module scan returned unexpected output"})

    @app.route("/api/remote-app/<app_name>/modules/<path:module>/dependents", methods=["GET"])
    def api_remote_app_module_dependents(app_name, module):
        """Return modules that depend on the given module by grepping all pom.xml files."""
        if app_name not in _ALL_REMOTE_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        vm_ip = request.args.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
        find  = _remote_app_find_repo_cmd(app_name)
        safe  = module.replace("'", "").replace('"', "").replace("`", "")
        # Single grep across all pom.xml files, then extract directory names
        cmd   = (
            find +
            f"grep -rl \"<artifactId>{safe}</artifactId>\" \"$SRCDIR\"/*/pom.xml 2>/dev/null | "
            f"while read f; do mod=$(basename \"$(dirname \"$f\")\"); "
            f"[ \"$mod\" != \"{safe}\" ] && echo \"$mod\"; done | sort -u"
        )
        ok, out, err = _ssh_run(vm_ip, cmd, timeout=60)
        if not ok:
            return jsonify({"ok": False, "error": err or out or "SSH failed"})
        dependents = [ln.strip() for ln in out.splitlines() if ln.strip()]
        return jsonify({"ok": True, "dependents": sorted(dependents)})

    @app.route("/api/remote-app/<app_name>/vm-deps", methods=["GET"])
    def api_remote_app_vm_deps(app_name):
        """Return vm_dependencies.xlsx main sheet as a flat JSON object."""
        if app_name not in _ALL_REMOTE_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        return jsonify({"ok": True, **_read_vm_cmd_deps(app_name)})

    def _read_module_deploy_dirs(app_name):
        """Read module_deploy sheet → {module: {targets, target_artifact_name, suppress_warning, disable_needs_build}}.
        Multiple rows with the same module name each contribute one entry to targets[]."""
        xlsx_path = _remote_app_root(app_name) / "vm_dependencies.xlsx"
        if not xlsx_path.exists():
            return {}
        try:
            import openpyxl as _xl
            wb = _xl.load_workbook(str(xlsx_path), data_only=True)
            if "module_deploy" not in wb.sheetnames:
                return {}
            ws  = wb["module_deploy"]
            out = {}
            for row in ws.iter_rows(min_row=2, values_only=True):
                if not row or row[0] is None:
                    continue
                module        = str(row[0]).strip()
                artifact_name = str(row[1]).strip() if len(row) > 1 and row[1] is not None else ""
                dep_dir       = str(row[2]).strip() if len(row) > 2 and row[2] is not None else ""
                if not module:
                    continue
                if module not in out:
                    raw_sw = row[3] if len(row) > 3 else None
                    suppress = raw_sw if isinstance(raw_sw, bool) else \
                               str(raw_sw or "").strip().upper() in ("TRUE", "1", "YES")
                    raw_dnb = row[4] if len(row) > 4 else None
                    disable_needs_build = raw_dnb if isinstance(raw_dnb, bool) else \
                                          str(raw_dnb or "").strip().upper() in ("TRUE", "1", "YES")
                    target_art = str(row[5]).strip() if len(row) > 5 and row[5] is not None else ""
                    catalina_dir = str(row[6]).strip() if len(row) > 6 and row[6] is not None else ""
                    out[module] = {
                        "targets": [],
                        "target_artifact_name": target_art,
                        "catalina_dir": catalina_dir,
                        "suppress_warning": suppress,
                        "disable_needs_build": disable_needs_build,
                    }
                if artifact_name or dep_dir:
                    out[module]["targets"].append({
                        "deployment_artifact_name": artifact_name,
                        "deployment_dir": dep_dir,
                    })
            return out
        except Exception:
            return {}

    @app.route("/api/remote-app/<app_name>/module-deploy-dirs", methods=["GET"])
    def api_remote_app_module_deploy_dirs(app_name):
        """Return per-module deploy config from vm_dependencies.xlsx module_deploy sheet."""
        if app_name not in _ALL_REMOTE_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        return jsonify({"ok": True, "dirs": _read_module_deploy_dirs(app_name)})

    @app.route("/api/remote-app/<app_name>/module-deploy-dirs/<module>", methods=["POST"])
    def api_remote_app_module_deploy_dirs_update(app_name, module):
        """Create or update module rows in vm_dependencies.xlsx module_deploy sheet.
        Accepts a targets[] array; writes one row per target (first row has module-level fields)."""
        if app_name not in _ALL_REMOTE_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        body = request.get_json() or {}
        xlsx_path = _remote_app_root(app_name) / "vm_dependencies.xlsx"
        try:
            import openpyxl as _xl
            if xlsx_path.exists():
                wb = _xl.load_workbook(str(xlsx_path))
            else:
                wb = _xl.Workbook()
                wb.active.title = "Main"
            _MDEPLOY_HEADERS = ["module", "deployment_artifact_name", "deployment_dir",
                                "suppress_warning", "disable_needs_build", "target_artifact_name",
                                "catalina_dir"]
            if "module_deploy" not in wb.sheetnames:
                ws = wb.create_sheet("module_deploy")
                ws.append(_MDEPLOY_HEADERS)
            else:
                ws = wb["module_deploy"]
            if ws.max_row < 1 or ws.cell(1, 1).value != "module":
                ws.insert_rows(1)
                for col, h in enumerate(_MDEPLOY_HEADERS, 1):
                    ws.cell(1, col).value = h
            else:
                if ws.cell(1, 2).value == "jar_name":
                    ws.cell(1, 2).value = "deployment_artifact_name"
                if ws.max_column < 6:
                    ws.cell(1, 6).value = "target_artifact_name"
                if ws.max_column < 7:
                    ws.cell(1, 7).value = "catalina_dir"
            suppress     = bool(body.get("suppress_warning", False))
            disable_nb   = bool(body.get("disable_needs_build", False))
            target_art   = str(body.get("target_artifact_name") or "").strip()
            catalina_dir = str(body.get("catalina_dir") or "").strip()
            targets    = [t for t in (body.get("targets") or [])
                          if str(t.get("deployment_artifact_name") or "").strip()
                          or str(t.get("deployment_dir") or "").strip()]
            # Delete all existing rows for this module
            rows_to_delete = [
                row[0].row for row in ws.iter_rows(min_row=2)
                if row[0].value and str(row[0].value).strip() == module
            ]
            for row_num in reversed(rows_to_delete):
                ws.delete_rows(row_num)
            # Write one row per target (or one row with empty artifact/dir if no targets)
            if targets:
                for i, t in enumerate(targets):
                    art = str(t.get("deployment_artifact_name") or "").strip()
                    d   = str(t.get("deployment_dir") or "").strip()
                    if i == 0:
                        ws.append([module, art, d, suppress, disable_nb, target_art, catalina_dir])
                    else:
                        ws.append([module, art, d, "", "", "", ""])
            else:
                ws.append([module, "", "", suppress, disable_nb, target_art, catalina_dir])
            wb.save(str(xlsx_path))
            return jsonify({"ok": True, "dirs": _read_module_deploy_dirs(app_name)})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    # ── env-setup (repo initialisation via env tool e.g. setbranch / setc3branch) ─

    def _read_vm_cmd_deps(app_name):
        xlsx_path = _remote_app_root(app_name) / "vm_dependencies.xlsx"
        if not xlsx_path.exists():
            return {}
        try:
            import openpyxl as _xl
            wb = _xl.load_workbook(str(xlsx_path), data_only=True)
            ws = wb.active
            result = {}
            for row in ws.iter_rows(min_row=2, values_only=True):
                if not row or row[1] is None: continue
                key = str(row[1]).strip()
                cmd = str(row[3]).strip() if row[3] is not None else ''
                if key and cmd:
                    result[key] = cmd
            return result
        except Exception:
            return {}

    _env_setup_tracker: dict = {}  # key: "{vm_ip}:{app_name}" -> {setup_id, pid, log_path, status, branch, started_at}

    @app.route("/api/remote-app/<app_name>/env-setup", methods=["POST"])
    def api_remote_app_env_setup(app_name):
        if app_name not in _ALL_REMOTE_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        body   = request.get_json() or {}
        vm_ip  = body.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
        branch = (body.get("branch") or "master").strip()
        deps     = _read_vm_cmd_deps(app_name)
        env_tool = deps.get("env_tool", "setbranch")
        log_path = f"/tmp/{app_name}_env_setup_{vm_ip.replace('.', '_')}.log"
        import uuid as _uuid, time as _time
        setup_id = _uuid.uuid4().hex[:10]
        cmd = (
            f"[ -f $HOME/.bash_profile ] && . $HOME/.bash_profile 2>/dev/null; "
            f"[ -f $HOME/.bashrc ] && . $HOME/.bashrc 2>/dev/null; "
            f"> {log_path}; "
            f"nohup bash -c '. $HOME/.bash_profile 2>/dev/null; . $HOME/.bashrc 2>/dev/null; "
            f"{env_tool} {branch}' > {log_path} 2>&1 & echo $!"
        )
        ok, out, err = _ssh_run(vm_ip, cmd, timeout=15)
        if not ok:
            return jsonify({"ok": False, "error": err or out or "SSH failed"})
        pid = out.strip()
        _env_setup_tracker[f"{vm_ip}:{app_name}"] = {
            "setup_id": setup_id, "pid": pid, "log_path": log_path,
            "status": "running", "started_at": _time.time(), "branch": branch,
        }
        return jsonify({"ok": True, "setup_id": setup_id, "pid": pid})

    @app.route("/api/remote-app/<app_name>/env-setup/status", methods=["GET"])
    def api_remote_app_env_setup_status(app_name):
        if app_name not in _ALL_REMOTE_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        vm_ip = request.args.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
        state = _env_setup_tracker.get(f"{vm_ip}:{app_name}")
        if not state:
            return jsonify({"ok": True, "active": False})
        pid = state.get("pid", "")
        if pid and state["status"] == "running":
            ok2, out2, _ = _ssh_run(vm_ip, f"kill -0 {pid} 2>/dev/null && echo running || echo done", timeout=8)
            if ok2 and "done" in (out2 or ""):
                state["status"] = "done"
        return jsonify({"ok": True, "active": True,
                        "setup_id": state["setup_id"], "pid": state["pid"],
                        "status": state["status"], "branch": state["branch"]})

    @app.route("/api/remote-app/<app_name>/env-setup/log", methods=["GET"])
    def api_remote_app_env_setup_log(app_name):
        if app_name not in _ALL_REMOTE_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        vm_ip = request.args.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
        state = _env_setup_tracker.get(f"{vm_ip}:{app_name}")
        if not state:
            return jsonify({"ok": True, "log": "", "status": "idle", "active": False})
        ok, out, _ = _ssh_run(vm_ip, f"cat {state['log_path']} 2>/dev/null", timeout=10)
        log_text = out or ""
        pid = state.get("pid", "")
        status = state["status"]
        if pid and status == "running":
            ok2, out2, _ = _ssh_run(vm_ip, f"kill -0 {pid} 2>/dev/null && echo running || echo done", timeout=8)
            if ok2 and "done" in (out2 or ""):
                state["status"] = "done"
                status = "done"
        return jsonify({"ok": True, "log": log_text, "status": status, "active": status == "running"})

    @app.route("/api/remote-app/<app_name>/env-setup/abort", methods=["POST"])
    def api_remote_app_env_setup_abort(app_name):
        if app_name not in _ALL_REMOTE_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        body  = request.get_json() or {}
        vm_ip = body.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
        state = _env_setup_tracker.get(f"{vm_ip}:{app_name}")
        if not state:
            return jsonify({"ok": False, "error": "No active setup found"})
        pid = state.get("pid", "")
        if pid:
            kill_cmd = (
                f"PGID=$(ps -o pgid= -p {pid} 2>/dev/null | tr -d ' '); "
                f"[ -n \"$PGID\" ] && kill -TERM -$PGID 2>/dev/null; "
                f"kill -TERM {pid} 2>/dev/null; sleep 1; kill -KILL {pid} 2>/dev/null; echo aborted"
            )
            _ssh_run(vm_ip, kill_cmd, timeout=12)
        state["status"] = "aborted"
        return jsonify({"ok": True})

    def _fetch_vm_payor_deployed_info(vm_ip):
        """SSH to the VM once to get branch, release_ver, and server_running for the payor banner."""
        cfg     = _read_remote_app_config("payor")
        pattern = cfg.get("git_pattern", "hrp.payer.core-*")
        prefix  = pattern.split("*")[0]
        port    = cfg.get("port", 7001)
        cmd = (
            "[ -f $HOME/.bash_profile ] && . $HOME/.bash_profile >/dev/null 2>&1; "
            "[ -f $HOME/.bashrc ] && . $HOME/.bashrc >/dev/null 2>&1; "
            "DEF=$(cat $HOME/.default-branch 2>/dev/null | tr -d '\\n\\r'); "
            "SRCDIR=''; "
            "for _BASE in \"${{GIT_HOME:-}}\" \"$HOME\" /home/weblogic /opt; do "
            "  [ -z \"$_BASE\" ] && continue; "
            "  if [ -n \"$DEF\" ]; then "
            "    _F=$(ls -d \"$_BASE\"/{prefix}${{DEF}} 2>/dev/null | head -1); "
            "    [ -n \"$_F\" ] && SRCDIR=\"$_F\" && break; "
            "  fi; "
            "  _F=$(ls -d \"$_BASE\"/{pattern} 2>/dev/null | head -1); "
            "  [ -n \"$_F\" ] && SRCDIR=\"$_F\" && break; "
            "done; "
            "RV=$(grep -m1 '^release_ver=' \"$SRCDIR/metadata/release.txt\" 2>/dev/null | cut -d= -f2 | tr -d '\\n'); "
            "HTTP=$(curl -s -o /dev/null -w '%{{http_code}}' http://localhost:{port}/ --connect-timeout 3 2>/dev/null); "
            "printf '%s|%s|%s' \"$DEF\" \"$RV\" \"$HTTP\""
        ).format(pattern=pattern, prefix=prefix, port=port)
        ok, out, _ = _ssh_run(vm_ip, cmd, timeout=25)
        if not ok or not out.strip():
            return {"branch": None, "release_ver": None, "server_running": False}
        parts  = out.strip().split("|")
        branch = parts[0].strip() if len(parts) > 0 else ""
        rv     = parts[1].strip() if len(parts) > 1 else ""
        http   = parts[2].strip() if len(parts) > 2 else "000"
        return {
            "branch":        branch or None,
            "release_ver":   rv or None,
            "server_running": http not in ("", "000"),
        }

    def _fetch_vm_app_deployed_info(app_name, vm_ip):
        """Generic SSH lookup: returns branch and release_ver for any remote app."""
        cfg     = _read_remote_app_config(app_name)
        deps    = _read_vm_cmd_deps(app_name)
        pattern = cfg.get("git_pattern", f"{app_name}-*")
        prefix  = pattern.split("*")[0]
        dflt_f  = deps.get("default_branch_file", "~/.default-branch")
        cmd = (
            "[ -f $HOME/.bash_profile ] && . $HOME/.bash_profile >/dev/null 2>&1; "
            "[ -f $HOME/.bashrc ] && . $HOME/.bashrc >/dev/null 2>&1; "
            "DEF=$(cat {dflt_f} 2>/dev/null | tr -d '\\n\\r'); "
            "SRCDIR=''; "
            "for _BASE in \"${{GIT_HOME:-}}\" \"$HOME\" /home/weblogic /opt; do "
            "  [ -z \"$_BASE\" ] && continue; "
            "  if [ -n \"$DEF\" ]; then "
            "    _F=$(ls -d \"$_BASE\"/{prefix}${{DEF}} 2>/dev/null | head -1); "
            "    [ -n \"$_F\" ] && SRCDIR=\"$_F\" && break; "
            "  fi; "
            "  _F=$(ls -d \"$_BASE\"/{pattern} 2>/dev/null | head -1); "
            "  [ -n \"$_F\" ] && SRCDIR=\"$_F\" && break; "
            "done; "
            "RV=$(grep -m1 '^release_ver=' \"$SRCDIR/metadata/release.txt\" 2>/dev/null | cut -d= -f2 | tr -d '\\n'); "
            "[ -z \"$RV\" ] && RV=$(grep -m1 '<version>' \"$SRCDIR/pom.xml\" 2>/dev/null | sed 's|.*<version>||;s|</version>.*||' | cut -d- -f1 | tr -d '[:space:]'); "
            "printf '%s|%s' \"$DEF\" \"$RV\""
        ).format(pattern=pattern, prefix=prefix, dflt_f=dflt_f)
        ok, out, _ = _ssh_run(vm_ip, cmd, timeout=25)
        if not ok or not out.strip():
            return {"branch": None, "release_ver": None}
        parts = out.strip().split("|")
        branch = parts[0].strip() if len(parts) > 0 else ""
        rv     = parts[1].strip() if len(parts) > 1 else ""
        return {"branch": branch or None, "release_ver": rv or None}

    @app.route("/api/remote-app/<app_name>/deployed-info", methods=["GET"])
    def api_remote_app_deployed_info_get(app_name):
        import json as _json, time as _t
        if app_name not in _ALL_REMOTE_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        vm_ip = request.args.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
        force = request.args.get("force", "").lower() in ("1", "true", "yes")

        if app_name == "payor":
            # ── Payor: local-file cache with 10-min TTL, SSH fallback ──────────
            safe = vm_ip.replace(".", "_").replace(":", "_")
            cf   = _REMOTE_DEPLOYED_INFO_DIR / f"{safe}.json"
            _REMOTE_DEPLOYED_INFO_DIR.mkdir(parents=True, exist_ok=True)
            cached = None
            if not force and cf.exists():
                try:
                    cached = _json.loads(cf.read_text(encoding="utf-8"))
                    if (_t.time() - cached.get("ts", 0)) < _REMOTE_DEPLOYED_INFO_TTL:
                        return jsonify({"ok": True, **{k: v for k, v in cached.items() if k != "ts"}})
                except Exception:
                    cached = None
            # Cache miss or stale — SSH to VM
            info = _fetch_vm_payor_deployed_info(vm_ip)
            # Preserve deployed_at from a previous explicit deployment if still in cache
            prev_at = (cached or {}).get("deployed_at")
            save = {**info, "deployed_at": info.get("deployed_at") or prev_at, "ts": _t.time()}
            try:
                cf.write_text(_json.dumps(save), encoding="utf-8")
            except Exception:
                pass
            return jsonify({"ok": True, **{k: v for k, v in save.items() if k != "ts"}})

        # ── Other apps: try explicit deployment file first, then live SSH ──────
        deployed_file = f"~/deployed_info_{app_name}.json"
        ok, out, _ = _ssh_run(vm_ip, f"cat {deployed_file} 2>/dev/null")
        if ok and out.strip():
            try:
                data = _json.loads(out.strip())
                if data.get("branch"):
                    return jsonify({"ok": True, **data})
            except Exception:
                pass
        # File missing or empty — live lookup from the repo on the VM
        info = _fetch_vm_app_deployed_info(app_name, vm_ip)
        return jsonify({"ok": True, **info})

    @app.route("/api/remote-app/<app_name>/deployed-info", methods=["POST"])
    def api_remote_app_deployed_info_post(app_name):
        """Record a fresh deployment for non-Payor apps by writing deployed_info to the VM."""
        import json as _json, datetime as _dt
        if app_name not in _ALL_REMOTE_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        body  = request.get_json(force=True) or {}
        vm_ip = body.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
        # SSH lookup so we always capture the actual repo state after deploy
        info = _fetch_vm_app_deployed_info(app_name, vm_ip)
        deployed_at = _dt.datetime.utcnow().strftime("%Y-%m-%d %H:%M UTC")
        payload = {**info, "deployed_at": deployed_at}
        safe_json = _json.dumps(payload).replace("'", "'\\''")
        _ssh_run(vm_ip, f"echo '{safe_json}' > ~/deployed_info_{app_name}.json", timeout=10)
        _rcache_invalidate(vm_ip, f"branch_info_{app_name}")
        return jsonify({"ok": True, **payload})

    @app.route("/api/remote-app/payor/deployed-info", methods=["POST"])
    def api_remote_payor_deployed_info_post():
        """Called after a successful remote deployment to update the local banner cache."""
        import json as _json, time as _t, datetime as _dt
        body  = request.get_json() or {}
        vm_ip = body.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
        safe  = vm_ip.replace(".", "_").replace(":", "_")
        cf    = _REMOTE_DEPLOYED_INFO_DIR / f"{safe}.json"
        _REMOTE_DEPLOYED_INFO_DIR.mkdir(parents=True, exist_ok=True)
        # SSH to VM to get current state right after deployment
        info = _fetch_vm_payor_deployed_info(vm_ip)
        deployed_at = _dt.datetime.utcnow().strftime("%Y-%m-%d %H:%M UTC")
        save = {**info, "deployed_at": deployed_at, "ts": _t.time()}
        try:
            cf.write_text(_json.dumps(save), encoding="utf-8")
        except Exception:
            pass
        # Invalidate related caches so next page load gets fresh domain/branch data
        _rcache_invalidate(vm_ip, f"branch_info_payor")
        _rcache_invalidate(vm_ip, "domain_status")
        return jsonify({"ok": True, **{k: v for k, v in save.items() if k != "ts"}})

