    # ── Generic local-app build + modules ──────────────────────────────────────

    _generic_builds: dict = {}
    _generic_build_locks: dict = {}
    _generic_module_ops: dict = {}
    _generic_module_op_locks: dict = {}
    _generic_set_branch_ops: dict = {}
    _generic_set_branch_locks: dict = {}

    import re as _re
    _generic_build_mod_pat = _re.compile(r'\[INFO\] Building (.+)\[(\d+)/(\d+)\]')

    def _get_generic_build_state(app_name):
        if app_name not in _generic_builds:
            _generic_builds[app_name] = {
                "status": "idle", "output": "", "proc": None, "start_ms": None,
                "phase": None, "current_module": None, "module_num": None,
                "total_modules": None, "failed_module": None,
                "params_key": None, "estimate_ms": None,
            }
            _generic_build_locks[app_name] = _threading.Lock()
        return _generic_build_locks[app_name], _generic_builds[app_name]

    def _save_generic_build_stats(app_name, params_key, duration_ms, status):
        """Append to stats/buildstats.xlsx; trim per-params rows to ≤10."""
        from datetime import datetime as _dt3
        try:
            import openpyxl as _xl3
            from openpyxl.styles import Font as _Fnt3, PatternFill as _PFill3
            stats_dir  = _generic_app_root(app_name) / "stats"
            stats_file = stats_dir / "buildstats.xlsx"
            stats_dir.mkdir(parents=True, exist_ok=True)
            HDRS   = ["id", "timestamp", "module", "parameters", "duration_ms", "build_status"]
            WIDTHS = [8, 22, 30, 40, 14, 14]
            if not stats_file.exists():
                wb3 = _xl3.Workbook(); ws3 = wb3.active; ws3.title = "Build Stats"
                hf3 = _Fnt3(bold=True, color="FFFFFF", name="Calibri")
                hb3 = _PFill3("solid", fgColor="4472C4")
                for i, (h, w) in enumerate(zip(HDRS, WIDTHS), 1):
                    c = ws3.cell(1, i, h); c.font = hf3; c.fill = hb3
                    ws3.column_dimensions[c.column_letter].width = w
            else:
                wb3 = _xl3.load_workbook(str(stats_file)); ws3 = wb3.active
            max_id = max((int(ws3.cell(r, 1).value or 0) for r in range(2, ws3.max_row + 1)
                          if ws3.cell(r, 1).value is not None), default=0)
            ws3.append([max_id + 1, _dt3.now().strftime("%Y-%m-%d %H:%M:%S"),
                        "full", params_key, duration_ms, status])
            wb3.save(str(stats_file))
            if status == "success":
                wb4 = _xl3.load_workbook(str(stats_file)); ws4 = wb4.active
                hdrs4 = [str(ws4.cell(1, c).value or "").strip().lower() for c in range(1, ws4.max_column + 1)]
                p_col = (hdrs4.index("parameters") + 1) if "parameters" in hdrs4 else 4
                combo_rows = [r for r in range(2, ws4.max_row + 1)
                              if str(ws4.cell(r, p_col).value or "") == params_key]
                if len(combo_rows) > 10:
                    for r in sorted(combo_rows[:-10], reverse=True):
                        ws4.delete_rows(r)
                    wb4.save(str(stats_file))
        except Exception:
            pass

    def _get_generic_build_estimate(app_name, params_key):
        """Median duration_ms of last ≤10 successful builds with same params, or None."""
        stats_file = _generic_app_root(app_name) / "stats" / "buildstats.xlsx"
        if not stats_file.exists():
            return None
        try:
            import openpyxl as _xl3
            wb  = _xl3.load_workbook(str(stats_file), data_only=True)
            ws  = wb.active
            hdrs = [str(ws.cell(1, c).value or "").strip().lower() for c in range(1, ws.max_column + 1)]
            durations = []
            for row in ws.iter_rows(min_row=2, values_only=True):
                d = {k: ("" if v is None else str(v)) for k, v in zip(hdrs, row)}
                if d.get("parameters") == params_key and d.get("build_status") == "success":
                    try:
                        durations.append(int(float(d.get("duration_ms", 0))))
                    except (ValueError, TypeError):
                        pass
            durations = durations[-10:]
            if not durations:
                return None
            s = sorted(durations)
            n = len(s)
            return s[n // 2] if n % 2 else (s[n // 2 - 1] + s[n // 2]) // 2
        except Exception:
            return None

    def _get_generic_module_op_state(app_name):
        if app_name not in _generic_module_ops:
            _generic_module_ops[app_name] = {"status": "idle", "output": "", "op": None, "module": None}
            _generic_module_op_locks[app_name] = _threading.Lock()
        return _generic_module_op_locks[app_name], _generic_module_ops[app_name]

    def _get_set_branch_state(app_name):
        if app_name not in _generic_set_branch_ops:
            _generic_set_branch_ops[app_name] = {"status": "idle", "output": "", "proc": None, "version": ""}
            _generic_set_branch_locks[app_name] = _threading.Lock()
        return _generic_set_branch_locks[app_name], _generic_set_branch_ops[app_name]

    def _run_set_branch_op(app_name, env_tool, version):
        lock, state = _get_set_branch_state(app_name)
        cf = 0x08000000 if sys.platform == "win32" else 0
        # Override Read-Host so interactive y/n prompts are auto-answered;
        # [System.Console]::Out.WriteLine writes directly to stdout so the prompt appears in the log.
        ps_override = (
            "function Read-Host { "
            "param($Prompt) "
            "[System.Console]::Out.WriteLine($Prompt + ': y'); "
            "'y' }; "
        )
        try:
            proc = subprocess.Popen(
                ["powershell.exe", "-Command", f"{ps_override}{env_tool} {version}"],
                stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                text=True, encoding="utf-8", errors="replace",
                creationflags=cf,
            )
            with lock:
                state["proc"] = proc
            for line in iter(proc.stdout.readline, ""):
                with lock:
                    state["output"] += line
            proc.wait()
            with lock:
                state["status"] = "success" if proc.returncode == 0 else "failed"
                state["proc"] = None
        except Exception as e:
            with lock:
                state["status"] = "failed"
                state["output"] += f"\n[ERROR] {e}\n"
                state["proc"] = None

    def _run_generic_build(app_name, srcdir, cmd_parts):
        import subprocess as _sub, time as _gtime, re as _grv, os as _gos
        lock, build = _get_generic_build_state(app_name)
        cf = 0x08000000 if sys.platform == "win32" else 0
        cmd_str    = " ".join(cmd_parts)
        params_key = " ".join(cmd_parts[1:]).strip() or "default"
        _stop_started   = _re.compile(r'Stop Artemis|Stop Tomcat|Stop WebLogic', _re.I)
        _deploy_started = _re.compile(r'Install inside container|docker cp.*staging|staging.*docker', _re.I)
        _start_started  = _re.compile(r'Start Artemis|Start Tomcat|Start WebLogic', _re.I)
        final_status = "failed"
        # Resolve release version from pom.xml and pass to the JS script via env var.
        # The JS script reads APP_RELEASE_VERSION for condition-based container selection,
        # reusing the same version resolution used by the current-branch display.
        _env = dict(_gos.environ)
        try:
            pom = Path(srcdir) / "pom.xml"
            if pom.exists():
                pom_text = _grv.sub(r"<parent>[\s\S]*?</parent>", "", pom.read_text(errors="replace"), flags=_grv.DOTALL)
                m = _grv.search(r"<version>(\d+\.\d+[^<\-]*)", pom_text)
                if m:
                    _env["APP_RELEASE_VERSION"] = m.group(1).split("-")[0].strip()
        except Exception:
            pass
        try:
            proc = _detached_popen("gbuild", ["cmd.exe", "/c", cmd_str], cwd=srcdir, env=_env, meta={"app": app_name})   # survives a Workbench restart
            with lock:
                build["proc"] = proc
                build["phase"] = "building"
            for line in iter(proc.stdout.readline, ""):
                with lock:
                    build["output"] += line
                    # Track Maven module progress (same pattern as Payor)
                    _rf = _MVN_RF_HINT.search(line)
                    if _rf and "resume the build" in line:
                        build["failed_hint"] = _rf.group(1)
                    m = _generic_build_mod_pat.search(line)
                    if m:
                        build["current_module"] = _mvn_artifact_id(m.group(1))
                        build["module_num"]     = int(m.group(2))
                        build["total_modules"]  = int(m.group(3))
                    # Detect phase transitions: building → stopping → deploying → starting
                    elif build["phase"] == "building" and _stop_started.search(line):
                        build["phase"]          = "stopping"
                        build["current_module"] = None
                    elif build["phase"] in ("building", "stopping") and _deploy_started.search(line):
                        build["phase"]          = "deploying"
                        build["current_module"] = None
                    elif build["phase"] == "deploying" and _start_started.search(line):
                        build["phase"]          = "starting"
                        build["current_module"] = None
            proc.wait()
            with lock:
                final_status = "success" if proc.returncode == 0 else "failed"
                build["status"] = final_status
                if final_status == "failed":
                    build["failed_module"] = build.get("failed_hint") or build.get("current_module")
                build["phase"]          = None
                build["current_module"] = None
                build["proc"] = None
            duration_ms = int(_gtime.time() * 1000) - (build.get("start_ms") or int(_gtime.time() * 1000))
            _save_generic_build_stats(app_name, params_key, duration_ms, final_status)
        except Exception as e:
            with lock:
                build["status"] = "failed"
                build["output"] += f"\n[ERROR] {e}\n"
                build["phase"]          = None
                build["current_module"] = None
                build["proc"] = None
            _save_generic_build_stats(app_name, params_key, 0, "failed")

    def _adopt_detached_jobs():
        """After a Workbench restart: re-attach to builds / deploys still running (and pick up the result of ones that finished meanwhile)."""
        import json as _j, time as _t
        _adopted = set()
        # newest first: only the latest job of each kind / app is shown, so older logs are never read
        for info in sorted(_DET_DIR.glob("*.json"), key=lambda f: f.stat().st_mtime, reverse=True) if _DET_DIR.is_dir() else []:
            try:
                d = _j.loads(info.read_text(encoding="utf-8"))
                kind, meta = d.get("kind"), d.get("meta") or {}
                proc = _DetachedProc(d["pid"], d["log"], d["code"])
                alive = proc.poll() is None
                if kind == "payor_build":
                    lock, st = _payor_build_lock, _payor_build
                elif kind == "module_op":
                    lock, st = _module_op_lock, _module_op
                elif kind == "gmodule_op":
                    lock, st = _get_generic_module_op_state(meta.get("app", ""))
                elif kind == "gbuild":
                    lock, st = _get_generic_build_state(meta.get("app", ""))
                else:
                    continue
                if id(st) in _adopted:
                    continue                                     # newer job of this kind / app already adopted
                with lock:
                    if st.get("status") == "running":
                        continue                                 # a newer job is already tracked
                    if not alive and st.get("status") not in (None, "idle"):
                        continue                                 # result already known
                    st.update({"status": "running", "output": "", "proc": proc if alive else None})
                    if kind in ("module_op", "gmodule_op"):
                        st.update({"op": meta.get("op"), "module": meta.get("module")})
                    else:
                        st.update({"phase": "building", "current_module": None, "module_num": None, "start_ms": int(d.get("started", _t.time()) * 1000)})
                    if kind == "payor_build":
                        st["total_modules"] = None
                _adopted.add(id(st))
                _th_a = _threading.Thread(target=_follow_adopted, args=(kind, proc, lock, st), daemon=True)
                _th_a.start()
            except Exception:
                continue

    def _follow_adopted(kind, proc, lock, st):
        import re as _r
        mod_pat = _r.compile(r'\[INFO\] Building (.+)\[(\d+)/(\d+)\]')
        schema  = _r.compile(r'creat.*schema|schema.*creat|running.*ddl|create\s+table|schema.*script', _r.I)
        boot    = _r.compile(r'starting.*tomcat|starting.*server|bootstrap|starting.*application|jvm.*start|server.*start', _r.I)
        # what is already in the log goes in as one block (replaying a multi-MB log line by line starved the whole server for a minute)
        proc._read_more()
        _pre = list(proc._lines)
        proc._lines.clear()
        if _pre:
            with lock:
                st["output"] += "".join(_pre)
                if kind in ("payor_build", "gbuild"):
                    for line in _pre:
                        m = mod_pat.search(line) if "[INFO] Building" in line else None
                        if m:
                            st["current_module"], st["module_num"], st["total_modules"] = _mvn_artifact_id(m.group(1)), int(m.group(2)), int(m.group(3))
                        if "[INFO] BUILD SUCCESS" in line:
                            st["phase"], st["current_module"], st["module_num"] = "deploying", None, None
        for line in iter(proc.stdout.readline, ""):
            with lock:
                if st.get("status") == "aborted":
                    break
                st["output"] += line
                if kind in ("payor_build", "gbuild"):
                    m = mod_pat.search(line)
                    if m:
                        st["current_module"], st["module_num"], st["total_modules"] = _mvn_artifact_id(m.group(1)), int(m.group(2)), int(m.group(3))
                    if "[INFO] BUILD SUCCESS" in line:
                        st["phase"], st["current_module"], st["module_num"] = "deploying", None, None
                    elif st.get("phase") in ("deploying", "creating_schema") and boot.search(line):
                        st["phase"] = "bootstrapping"
                    elif st.get("phase") == "deploying" and schema.search(line):
                        st["phase"] = "creating_schema"
        proc.wait()
        with lock:
            st["proc"] = None
            if st.get("status") != "aborted":
                st["status"] = "success" if proc.returncode == 0 else "failed"
                if st["status"] == "failed" and kind in ("payor_build", "gbuild"):      # so Resume From still works after a restart
                    _h = _MVN_RF_HINT.findall(st.get("output") or "")
                    _fp = _r.findall(r"Failed to execute goal on project\s+(\S+?):", st.get("output") or "")
                    _out = st.get("output") or ""
                    _after = _out.rsplit("[INFO] BUILD SUCCESS", 1)[1] if "[INFO] BUILD SUCCESS" in _out else None
                    _failed_in_maven = _after is None or "[INFO] BUILD FAILURE" in _after
                    st["failed_module"] = ((_h[-1] if _h else (_fp[0] if _fp else None)) or st.get("current_module")) if _failed_in_maven else None
            if kind in ("payor_build", "gbuild"):
                st["phase"], st["current_module"] = None, None
        if kind == "payor_build":
            try:
                _restore_cfgviewer_pom(_payor_srcdir()[1])
            except Exception:
                pass

    _adopt_detached_jobs()
    _prune_detached_logs()

    def _run_generic_module_op(app_name, op, module, extra_args):
        import subprocess as _sub
        lock, mop = _get_generic_module_op_state(app_name)
        app_root = _generic_app_root(app_name)
        script_name = "build_module.js" if op == "build" else "deploy_jar.js"
        script_path = app_root / "scripts" / script_name
        cf = 0x08000000 if sys.platform == "win32" else 0
        if script_path.exists():
            args = [module] + extra_args if op == "build" else [module]
            cmd  = ["node", f"scripts/{script_name}"] + args
            cwd  = str(app_root)
        elif op == "build":
            srcdir = _get_generic_srcdir(app_name)
            if not srcdir or not Path(srcdir).exists():
                with lock:
                    mop["status"] = "failed"
                    mop["output"] += "\n[ERROR] Clone directory not found. Run env tool first.\n"
                return
            skip = "-st" in extra_args
            cmd  = ["mvn", "install", "-pl", module, "-am"] + (["-DskipTests"] if skip else [])
            cwd  = srcdir
        else:
            with lock:
                mop["status"] = "failed"
                mop["output"] += f"\n[ERROR] {script_path} not found.\n"
            return
        with lock:
            mop["output"] += f"$ {' '.join(cmd)}\n\n"
        try:
            proc = _detached_popen("gmodule_op", cmd, cwd=cwd, env=_tomcat_mgr_env(app_root), meta={"app": app_name, "op": op, "module": module})   # survives a Workbench restart
            with lock:
                mop["proc"] = proc
            for line in iter(proc.stdout.readline, ""):
                with lock:
                    mop["output"] += line
            proc.wait()
            with lock:
                mop["proc"] = None
                mop["status"] = "aborted" if mop["status"] == "aborted" else ("success" if proc.returncode == 0 else "failed")
        except Exception as e:
            with lock:
                mop["status"] = "failed"
                mop["output"] += f"\n[ERROR] {e}\n"

    def _generic_build_command(app_name):
        # devtool_config.xlsx build_tool takes highest precedence
        deps = _read_local_deps(app_name)
        cmd = deps.get("build_tool", "").strip()
        if cmd:
            return cmd
        # fall back to screen_config.xlsx settings build_command
        cached = _local_screen_cfg_cache.get(app_name, {})
        cmd = (cached.get("settings") or {}).get("build_command", "").strip()
        if cmd:
            return cmd
        xlsx_path = _generic_app_root(app_name) / "screen_config.xlsx"
        if xlsx_path.exists():
            try:
                import openpyxl as _xl
                wb = _xl.load_workbook(str(xlsx_path), data_only=True)
                ws = wb.active
                for row in ws.iter_rows(min_row=2, values_only=True):
                    if (row and len(row) > 2 and row[0] and
                            str(row[0]).strip().lower() == "settings" and
                            str(row[1]).strip().lower() == "build_command" and row[2]):
                        return str(row[2]).strip()
            except Exception:
                pass
        return f"refresh-{app_name}"

    @app.route("/api/local-app/<app_name>/build", methods=["POST"])
    def api_generic_local_build(app_name):
        import time as _time
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        body   = request.get_json() or {}
        flags  = [f for f in (body.get("flags") or []) if str(f).startswith("-")]
        _rf = (body.get("resume_from") or "").strip()
        _fl = []
        for f in flags:                      # keep -rf together with its module (-rf :artifactId)
            if f.strip() == "-rf":
                if _rf:
                    _fl.append("-rf")
                    _fl.append(_rf if _rf.startswith(":") else ":" + _rf)
                continue
            _fl.append(f)
        flags = _fl
        srcdir = _get_generic_srcdir(app_name)
        if not srcdir or not Path(srcdir).exists():
            return jsonify({"ok": False, "error": f"Clone directory not found: {srcdir or '(not configured — run env tool first)'}"})
        build_cmd  = _generic_build_command(app_name)
        params_key = " ".join(flags).strip() or "default"
        lock, build = _get_generic_build_state(app_name)
        _est = _get_generic_build_estimate(app_name, params_key)
        with lock:
            if build["status"] == "running":
                return jsonify({"ok": False, "error": "A build is already running"}), 409
            build.update({
                "status": "running", "output": "", "proc": None,
                "start_ms": int(_time.time() * 1000),
                "phase": None, "current_module": None, "module_num": None,
                "total_modules": None, "failed_module": None,
                "params_key": params_key,
                "estimate_ms": _est,
            })
        _threading.Thread(
            target=_run_generic_build, args=(app_name, srcdir, [build_cmd] + flags), daemon=True,
        ).start()
        return jsonify({"ok": True, "estimated_ms": _est})

    @app.route("/api/local-app/<app_name>/build-status", methods=["GET"])
    def api_generic_local_build_status(app_name):
        import time as _time
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        lock, build = _get_generic_build_state(app_name)
        with lock:
            status         = build["status"]
            output         = build["output"]
            start_ms       = build["start_ms"]
            phase          = build.get("phase")
            current_module = build.get("current_module")
            module_num     = build.get("module_num")
            total_modules  = build.get("total_modules")
            failed_module  = build.get("failed_module")
            estimate_ms    = build.get("estimate_ms")
        elapsed_ms = (int(_time.time() * 1000) - start_ms) if start_ms else 0
        if status == "running" and estimate_ms:
            progress = min(int(elapsed_ms / estimate_ms * 100), 95)
        elif status == "success":
            progress = 100
        else:
            progress = None
        return jsonify({
            "status": status, "output": output, "elapsed_ms": elapsed_ms,
            "estimated_ms": estimate_ms, "estimate_ms": estimate_ms,
            "progress": progress,
            "phase": phase, "current_module": current_module,
            "module_num": module_num, "total_modules": total_modules,
            "failed_module": failed_module,
        })

    @app.route("/api/local-app/<app_name>/abort-build", methods=["POST"])
    def api_generic_local_abort_build(app_name):
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        lock, build = _get_generic_build_state(app_name)
        with lock:
            if build["status"] != "running":
                return jsonify({"ok": False, "error": "No build running"}), 400
            build["status"] = "aborted"
            proc = build.get("proc")
        if proc:
            try:
                subprocess.run(["taskkill", "/F", "/T", "/PID", str(proc.pid)],
                               capture_output=True, creationflags=0x08000000)
            except Exception:
                pass
        return jsonify({"ok": True})

