    @app.route("/api/local-app/<app_name>/module-build", methods=["POST"])
    def api_generic_local_module_build(app_name):
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        body       = request.get_json() or {}
        module     = str(body.get("module", "")).strip()
        skip_tests = bool(body.get("skip_tests", False))
        with_dist  = bool(body.get("with_dist",  False))
        if not module:
            return jsonify({"ok": False, "error": "module is required"}), 400
        lock, mop = _get_generic_module_op_state(app_name)
        with lock:
            if mop["status"] == "running":
                return jsonify({"ok": False, "error": "An operation is already running"}), 409
            mop.update({"status": "running", "output": "", "op": "build", "module": module})
        extra = []
        if skip_tests: extra.append("-st")
        if with_dist:  extra.append("-dist")
        _threading.Thread(
            target=_run_generic_module_op, args=(app_name, "build", module, extra), daemon=True,
        ).start()
        return jsonify({"ok": True})

