    @app.route("/api/local-app/<app_name>/module-deploy-cfg", methods=["GET", "POST"])
    def api_generic_local_module_deploy_cfg(app_name):
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        app_root = _generic_app_root(app_name)
        if request.method == "POST":
            body   = request.get_json() or {}
            module = str(body.get("module", "")).strip()
            if not module:
                return jsonify({"ok": False, "error": "module is required"}), 400
            overrides = _read_module_overrides(app_root)
            entry = overrides.get(module, {})
            for field in ("suppress_warning", "disable_needs_build"):
                if field in body:
                    entry[field] = bool(body[field])
            if "target_artifact_name" in body:
                v = str(body["target_artifact_name"] or "").strip()
                if v: entry["target_artifact_name"] = v
                else: entry.pop("target_artifact_name", None)
            if "targets" in body:
                cleaned = [
                    {"deploy_dir": str(t.get("deploy_dir") or "").strip(),
                     "deployment_artifact_name": str(t.get("deployment_artifact_name") or "").strip()}
                    for t in (body["targets"] or [])
                    if str(t.get("deploy_dir") or "").strip() or str(t.get("deployment_artifact_name") or "").strip()
                ]
                entry["targets"] = cleaned
                entry.pop("jar_name", None)
                # Keep backward-compat keys = first target values (for deploy_jar.js)
                if cleaned:
                    entry["deploy_dir"] = cleaned[0]["deploy_dir"]
                    entry["deployment_artifact_name"] = cleaned[0]["deployment_artifact_name"]
                else:
                    entry.pop("deploy_dir", None)
                    entry.pop("deployment_artifact_name", None)
            else:
                # Legacy single-field update
                for field in ("deploy_dir", "deployment_artifact_name"):
                    val = body.get(field) if field in body else body.get("jar_name") if field == "deployment_artifact_name" else None
                    if val is not None:
                        v = str(val or "").strip()
                        entry.pop("jar_name", None)
                        if v:
                            entry[field] = v
                            targets = entry.get("targets", [])
                            if targets:
                                targets[0][field] = v
                            else:
                                entry["targets"] = [{"deploy_dir": entry.get("deploy_dir", ""), "deployment_artifact_name": entry.get("deployment_artifact_name", "")}]
                        else:
                            entry.pop(field, None)
            overrides[module] = entry
            _write_module_overrides(app_root, overrides)
            return jsonify({"ok": True})
        module_overrides = _read_module_overrides(app_root)
        script_path = app_root / "scripts" / "deploy_jar.js"
        if not script_path.exists():
            return jsonify({"ok": True, "configured": False, "reason": "deploy_jar.js not found",
                            "module_overrides": module_overrides})
        return jsonify({"ok": True, "configured": True, "module_overrides": module_overrides})

    @app.route("/api/local-app/<app_name>/open-ide", methods=["POST"])
    def api_generic_local_open_ide(app_name):
        import glob as _glob, shutil as _shutil
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        srcdir = _get_generic_srcdir(app_name)
        if not srcdir or not Path(srcdir).exists():
            return jsonify({"ok": False, "error": f"Clone directory not found: {srcdir or '(not configured — run env tool first)'}"})
        idea_exe = ""
        for pf in [r"C:\Program Files\JetBrains", r"C:\Program Files (x86)\JetBrains"]:
            matches = sorted(_glob.glob(pf + r"\IntelliJ IDEA*\bin\idea64.exe"))
            if matches:
                idea_exe = matches[-1]; break
        if not idea_exe:
            idea_exe = _shutil.which("idea64") or _shutil.which("idea") or ""
        if not idea_exe or not Path(idea_exe).exists():
            return jsonify({"ok": False, "error": "IntelliJ IDEA not found."})
        try:
            subprocess.Popen([idea_exe, srcdir], creationflags=0x08000000)
            return jsonify({"ok": True})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/local-app/<app_name>/open-terminal", methods=["POST"])
    def api_generic_local_open_terminal(app_name):
        if app_name not in _KNOWN_GENERIC_LOCAL_APPS:
            return jsonify({"ok": False, "error": f"Unknown app: {app_name}"}), 404
        deps          = _read_local_deps(app_name)
        terminal_init = deps.get("terminal_init", "").strip()
        try:
            if terminal_init:
                subprocess.Popen(
                    ["cmd.exe", "/c", "start", "powershell.exe", "-NoExit",
                     "-Command", terminal_init],
                    creationflags=0x08000000,
                )
            else:
                srcdir = _get_generic_srcdir(app_name)
                if not srcdir or not Path(srcdir).exists():
                    return jsonify({"ok": False, "error": f"Clone directory not found: {srcdir or '(not configured — run env tool first)'}"})
                subprocess.Popen(
                    ["cmd.exe", "/c", "start", "powershell.exe", "-NoExit",
                     "-Command", f"Set-Location '{srcdir}'"],
                    creationflags=0x08000000,
                )
            return jsonify({"ok": True})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    # ── Payor-specific server status + ops (native WebLogic, not Docker) ────────

    @app.route("/api/remote-app/payor/domain-status", methods=["GET"])
    def api_remote_payor_domain_status():
        """Check todomain reachability and get deployed payor version."""
        vm_ip = request.args.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
        force = request.args.get("force", "").lower() in ("1", "true", "yes")
        if not force:
            cached = _rcache_get(vm_ip, "domain_status")
            if cached is not None:
                # If cached domain_status predates branch_release_map field, merge it in.
                if not cached.get("branch_release_map"):
                    bmap = _rcache_get(vm_ip, "branch_release_map")
                    if bmap:
                        cached = {**cached, "branch_release_map": bmap}
                return jsonify({**cached, "cached": True})
        # todomain is a shell alias — must run inside bash -i -c.
        # We check success by comparing pwd before and after todomain.
        # Version is extracted from the domain directory name (healthedge_X.Y.Z).
        # The current branch (from ~/.default-branch) is included so results are
        # cached per-branch: domain_status_{branch}.
        cfg         = _read_remote_app_config("payor")
        git_pattern = cfg.get("git_pattern", "hrp.payer.core-*")
        git_prefix  = git_pattern.split('*')[0]   # e.g. "hrp.payer.core-"
        # Call 1: bash -i needed for todomain alias (domain check + alldomains list).
        inner = (
            "DEF=$(cat $HOME/.default-branch 2>/dev/null | tr -d '\\n\\r'); "
            "echo BRANCH:$DEF; "
            "BEFORE=$(pwd); "
            "todomain 2>/dev/null; "
            "AFTER=$(pwd); "
            "DNAME=$(basename $AFTER); "
            "if [ \"$BEFORE\" != \"$AFTER\" ] && echo $DNAME | grep -qi healthedge; then "
            "  echo DOMAIN_OK; "
            "  VER=$(echo $DNAME | sed 's/.*healthedge_//'); "
            "  echo VERSION:$VER; "
            "else "
            "  echo DOMAIN_NA; "
            "fi; "
            "echo ALLDOMAINS:$(ls -d /home/weblogic/domains/healthedge_* 2>/dev/null "
            "  | xargs -I{} basename {} | sed 's/healthedge_//' | tr '\\n' ',')"
        )
        cmd = f'bash -i -c "{inner}" 2>/dev/null'
        ok, out, err = _ssh_run(vm_ip, cmd, timeout=15)
        if not ok:
            result = {"ok": True, "domain_available": False, "version": None,
                      "branch": None, "all_domain_versions": [],
                      "error": err or "SSH failed"}
            return jsonify(result)
        lines = out.strip().splitlines()
        domain_available = any(l.strip() == "DOMAIN_OK" for l in lines)
        version = None; branch = None; all_domain_versions = []
        for l in lines:
            if l.startswith("BRANCH:"):
                branch = l[len("BRANCH:"):].strip() or None
            elif l.startswith("VERSION:"):
                v = l[len("VERSION:"):].strip()
                if v: version = v
            elif l.startswith("ALLDOMAINS:"):
                parts = l[len("ALLDOMAINS:"):].strip().rstrip(",").split(",")
                all_domain_versions = [p.strip() for p in parts if p.strip()]

        # Call 2: plain SSH (no bash -i -c wrapper) to scan all repo clones for release_ver.
        # Variables like $_REPO, $_BR, $_RV work correctly only outside the bash -i -c "..."
        # double-quote context — inside it the outer shell would expand them to empty.
        bmap_cmd = (
            "[ -f $HOME/.bash_profile ] && . $HOME/.bash_profile >/dev/null 2>&1; "
            "[ -f $HOME/.bashrc ] && . $HOME/.bashrc >/dev/null 2>&1; "
            f"for _REPO in ${{GIT_HOME:-$HOME}}/{git_prefix}* $HOME/{git_prefix}* /home/weblogic/{git_prefix}*; do "
            "  test -f \"$_REPO/metadata/release.txt\" || continue; "
            f"  _BR=$(basename \"$_REPO\" | sed 's|{git_prefix}||;s|^release-||'); "
            "  _RV=$(grep -m1 '^release_ver=' \"$_REPO/metadata/release.txt\" 2>/dev/null | cut -d= -f2 | tr -d '\\n'); "
            "  test -n \"$_BR\" && test -n \"$_RV\" && echo \"BMAP:$_BR=$_RV\"; "
            "done"
        )
        _, bmap_out, _ = _ssh_run(vm_ip, bmap_cmd, timeout=15)
        branch_release_map = {}
        for l in bmap_out.strip().splitlines():
            if l.startswith("BMAP:"):
                pair = l[len("BMAP:"):].strip()
                if "=" in pair:
                    b, _, rv = pair.partition("=")
                    b = b.strip(); rv = rv.strip()
                    if b and rv:
                        branch_release_map[b] = {
                            "branch_version": b,
                            "release_ver": rv,
                            "domain": rv if rv in all_domain_versions else None,
                        }
        result = {"ok": True, "domain_available": domain_available,
                  "version": version, "branch": branch,
                  "all_domain_versions": all_domain_versions,
                  "branch_release_map": branch_release_map}
        # Cache domain_status (includes branch_release_map) and branch_release_map separately.
        # Separate cache for branch_release_map means the filter mapping survives independent
        # of domain_status invalidation and gets its own TTL refresh cycle.
        _rcache_set(vm_ip, "domain_status", result)
        _rcache_set(vm_ip, "branch_release_map", branch_release_map)
        if branch:
            _rcache_set(vm_ip, f"domain_status_{branch}", result)
        return jsonify(result)

    @app.route("/api/remote-app/payor/server-status", methods=["GET"])
    def api_remote_payor_server_status():
        vm_ip = request.args.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
        cfg   = _read_remote_app_config("payor")
        port  = cfg.get("port", 7001)
        cmd   = (
            f"curl -s -o /dev/null -w '%{{http_code}}' "
            f"http://localhost:{port}/ --connect-timeout 3 2>/dev/null"
        )
        ok, out, _ = _ssh_run(vm_ip, cmd, timeout=10)
        running = ok and out.strip() not in ("", "000")
        dbg = False
        if running:
            okd, outd, _ = _ssh_run(vm_ip, _DEBUG_PS_CMD, timeout=10)
            dbg = okd and outd.strip() not in ("", "0")
        return jsonify({"ok": True, "running": running, "vm_ip": vm_ip, "port": port, "debug": dbg})

    @app.route("/api/remote-app/payor/server-op", methods=["POST"])
    def api_remote_payor_server_op():
        body      = request.get_json() or {}
        vm_ip     = body.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
        operation = body.get("operation", "start")
        if operation not in ("start", "stop", "restart"):
            return jsonify({"ok": False, "error": f"Unknown operation: {operation}"}), 400
        if operation == "start":
            cmd = 'bash -i -c "nohup startServer > /tmp/payor_start.log 2>&1 & disown; sleep 3; echo Started" 2>/dev/null'
        elif operation == "stop":
            cmd = 'bash -i -c "stopServer 2>&1" 2>/dev/null'
        else:
            cmd = (
                'bash -i -c "stopServer 2>&1; sleep 5; '
                'nohup startServer > /tmp/payor_start.log 2>&1 & disown; sleep 3; echo Restarted" 2>/dev/null'
            )
        ok, out, err = _ssh_run(vm_ip, cmd, timeout=120)
        if not ok:
            return jsonify({"ok": False, "error": err or out or "Operation failed", "output": out})
        _rcache_invalidate(vm_ip, "domain_status")
        return jsonify({"ok": True, "output": out.strip()})

    @app.route("/api/remote-app/payor/server-log", methods=["GET"])
    def api_remote_payor_server_log():
        vm_ip = request.args.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
        ok, out, _ = _ssh_run(vm_ip, "tail -n 300 /tmp/payor_start.log 2>/dev/null", timeout=10)
        return jsonify({"ok": True, "output": out or ""})

