    # ── Payor-specific runtime-properties via todomain ────────────────────────

    @app.route("/api/remote-app/payor/runtime-properties", methods=["GET"])
    def api_remote_payor_runtime_props_get():
        vm_ip = request.args.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
        cached = _rcache_get(vm_ip, "runtime_props")
        if cached is not None:
            return jsonify({"ok": True, "properties": cached, "cached": True})
        cmd = 'bash -i -c "todomain 2>/dev/null; cat runtime.properties 2>/dev/null" 2>/dev/null'
        ok, out, err = _ssh_run(vm_ip, cmd)
        if not ok or not out.strip():
            return jsonify({"ok": False, "error": err or "Could not read runtime.properties via todomain"})
        props = _parse_java_props(out)
        _rcache_set(vm_ip, "runtime_props", props)
        return jsonify({"ok": True, "properties": props})

    @app.route("/api/remote-app/payor/runtime-properties", methods=["POST"])
    def api_remote_payor_runtime_props_add():
        body  = request.get_json() or {}
        vm_ip = body.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
        key   = (body.get("key") or "").strip()
        value = str(body.get("value", ""))
        if not key:
            return jsonify({"ok": False, "error": "key is required"})
        escaped = value.replace("\\", "\\\\").replace("/", "\\/").replace("&", "\\&")
        inner = (
            f"todomain 2>/dev/null; "
            f"if grep -q '^{key}=' runtime.properties 2>/dev/null; then "
            f"sed -i 's|^{key}=.*|{key}={escaped}|' runtime.properties; "
            f"else printf '%s\\n' '{key}={value}' >> runtime.properties; fi; "
            f"cat runtime.properties 2>/dev/null"
        )
        cmd = f'bash -i -c "{inner}" 2>/dev/null'
        ok, out, err = _ssh_run(vm_ip, cmd)
        if not ok:
            return jsonify({"ok": False, "error": err or "Failed to add property"})
        props = _parse_java_props(out)
        _rcache_set(vm_ip, "runtime_props", props)
        return jsonify({"ok": True, "properties": props})

