        folder = _DB_QUERIES_BASE / "remote" / _remote_db_safe_vm(vm_ip)
        folder.mkdir(parents=True, exist_ok=True)
        path   = folder / f"QueryTab_{tab_num}.sql"
        sql    = path.read_text(encoding="utf-8") if path.exists() else ""
        return jsonify({"ok": True, "sql": sql, "version": f"remote-{_remote_db_safe_vm(vm_ip)}"})

