    # ── Remote Payor – UI Apps (Manager, Designer, Admin) ─────────────────────

    _RP_UI_INSTALLERS_DEFAULT = str(HE_UI_INSTALLERS_BASE / "Remote")
    _RP_UI_INSTALLED_DEFAULT  = str(HE_UI_INSTALLED_BASE  / "Remote")

    def _rp_ui_ensure_config(vm_ip):
        import openpyxl as _xl
        cfg_file = REMOTE_PAYOR_UI_APPS_CONFIG
        payor_cfg = _read_remote_app_config("payor")
        port      = payor_cfg.get("port", 7001)
        defaults  = {
            "base_url":        f"http://{vm_ip}:{port}/",
            "version":         "",
            "installers_base": _RP_UI_INSTALLERS_DEFAULT,
            "installed_base":  _RP_UI_INSTALLED_DEFAULT,
        }
        if not cfg_file.exists():
            wb = _xl.Workbook()
            ws_cfg = wb.active; ws_cfg.title = "Config"
            ws_cfg.append(["Setting", "Value"])
            for k, v in defaults.items():
                ws_cfg.append([k, v])
            ws_apps = wb.create_sheet("Apps")
            ws_apps.append(["app_id", "display_name", "folder", "app_file"])
            ws_apps.append(["manager",  "Manager",  "Manager",  "HealthEdge.Manager.application"])
            ws_apps.append(["admin",    "Admin",    "UASAdmin", "UASAdmin.application"])
            ws_apps.append(["designer", "Designer", "Designer", "HealthEdge.Designer.application"])
            wb.save(str(cfg_file))
            return
        wb = _xl.load_workbook(str(cfg_file))
        ws_cfg = wb["Config"] if "Config" in wb.sheetnames else wb.active
        existing_keys = set()
        for row in ws_cfg.iter_rows(min_row=2, values_only=True):
            if row[0]:
                existing_keys.add(str(row[0]).strip())
        changed = False
        for k, v in defaults.items():
            if k not in existing_keys:
                ws_cfg.append([k, v]); changed = True
        if changed:
            wb.save(str(cfg_file))

    def _rp_ui_read_config(vm_ip):
        import openpyxl as _xl
        _rp_ui_ensure_config(vm_ip)
        wb = _xl.load_workbook(str(REMOTE_PAYOR_UI_APPS_CONFIG))
        ws_cfg = wb["Config"]
        config = {}
        for row in ws_cfg.iter_rows(min_row=2, values_only=True):
            if row[0]:
                config[str(row[0]).strip()] = str(row[1] or "").strip()
        ws_apps = wb["Apps"]
        headers = [c.value for c in next(ws_apps.iter_rows(min_row=1, max_row=1))]
        apps = []
        for row in ws_apps.iter_rows(min_row=2, values_only=True):
            if row[0]:
                apps.append({h: (str(v).strip() if v is not None else "")
                              for h, v in zip(headers, row)})
        return config, apps

    def _rp_ui_write_config(updates):
        import openpyxl as _xl
        wb = _xl.load_workbook(str(REMOTE_PAYOR_UI_APPS_CONFIG))
        ws_cfg = wb["Config"]
        existing = {}
        for i, row in enumerate(ws_cfg.iter_rows(min_row=2), start=2):
            if row[0].value:
                existing[str(row[0].value).strip()] = i
        for k, v in updates.items():
            if k in existing:
                ws_cfg.cell(row=existing[k], column=2, value=v)
            else:
                ws_cfg.append([k, v])
        wb.save(str(REMOTE_PAYOR_UI_APPS_CONFIG))

    def _rp_ui_fetch_version(vm_ip):
        """
        Determine the deployed payor version on the remote VM.
        Uses the same approach as the remote app info endpoint:
          1. Read ~/.default-branch for the branch name
          2. Find the repo dir, then read metadata/release.txt for release_ver (e.g. 27.1)
          3. If branch is a release branch (release-X.Y.Z), extract the version from it
          4. Return as "release-X.Y" so it matches ClickOnce server directory names
        """
        cached = _rcache_get(vm_ip, "branch_info")
        if cached is not None:
            return cached.get("ui_version", "")
        import re as _rev
        try:
            cfg     = _read_remote_app_config("payor")
            pattern = cfg.get("git_pattern", "hrp.payer.core-*")
            prefix  = pattern.split('*')[0]
            cmd = (
                'DEFAULT_BRANCH=$(cat $HOME/.default-branch 2>/dev/null | tr -d \'\\n\\r\'); '
                'SRCDIR=""; '
                f'for _BASE in "${{GIT_HOME:-}}" "$HOME" /home/weblogic /opt; do '
                '  [ -z "$_BASE" ] && continue; '
                '  if [ -n "$DEFAULT_BRANCH" ]; then '
                f'    _F=$(ls -d "$_BASE"/{prefix}${{DEFAULT_BRANCH}} 2>/dev/null | head -1); '
                '    [ -n "$_F" ] && SRCDIR="$_F" && break; '
                '  fi; '
                f'  _F=$(ls -d "$_BASE"/{pattern} 2>/dev/null | head -1); '
                '  [ -n "$_F" ] && SRCDIR="$_F" && break; '
                'done; '
                'RELEASE_VER=$(grep -m1 \'^release_ver=\' "$SRCDIR/metadata/release.txt" 2>/dev/null | cut -d= -f2 | tr -d \'\\n\'); '
                'printf \'%s|%s\' "$DEFAULT_BRANCH" "$RELEASE_VER"'
            )
            ok, out, _ = _ssh_run(vm_ip, cmd, timeout=12)
            if ok and out.strip():
                parts       = out.strip().split("|")
                def_branch  = parts[0].strip() if len(parts) > 0 else ""
                release_ver = parts[1].strip() if len(parts) > 1 else ""
                ui_version = ""
                if def_branch.lower() == "master":
                    ui_version = "master"
                elif release_ver:
                    ui_version = f"release-{release_ver}"
                elif def_branch:
                    m = _rev.search(r'release-(\d+\.\d+)', def_branch, _rev.I)
                    ui_version = f"release-{m.group(1)}" if m else def_branch
                if ui_version:
                    _rcache_set(vm_ip, "branch_info", {"branch": def_branch, "release_ver": release_ver, "ui_version": ui_version})
                    return ui_version
        except Exception:
            pass
        return ""

    def _rp_ui_get_apps(vm_ip):
        config, app_defs = _rp_ui_read_config(vm_ip)
        base = config.get("base_url", "").rstrip("/")
        ver  = config.get("version", "").strip()
        # Auto-detect version from remote VM when not explicitly configured
        if not ver:
            ver = _rp_ui_fetch_version(vm_ip)
        # Get the numeric release version cached by _rp_ui_fetch_version (e.g. "27.1")
        _rp_release_ver = (_rcache_get(vm_ip, "branch_info") or {}).get("release_ver", "")
        available = _fetch_clickonce_versions(base) if base else []
        ui_ver    = _find_best_ui_version(ver, available) if available else ver
        ui_clean  = _clean_version(ui_ver) if ui_ver else ""
        # For master builds with a known release version, use the release version dir
        # for install checks (master IS that release); download URL still uses "master".
        _install_clean = (
            _clean_version(f"release-{_rp_release_ver}")
            if ver == "master" and _rp_release_ver
            else (ui_clean or "unknown")
        )
        config["version"]    = ver
        config["ui_version"] = ui_ver
        inst_base_str  = _expand_cfg_path(config.get("installers_base", ""))
        instd_base_str = _expand_cfg_path(config.get("installed_base",  ""))
        inst_base  = Path(inst_base_str)  if inst_base_str  else (HE_UI_INSTALLERS_BASE / "Remote")
        instd_base = Path(instd_base_str) if instd_base_str else (HE_UI_INSTALLED_BASE  / "Remote")
        result = []
        for app in app_defs:
            name         = app.get("display_name", "")
            if base and ui_ver:
                url = f"{base}/{ui_ver}/{app.get('folder','')}/{app.get('app_file','')}"
            elif base:
                url = f"{base}/{app.get('folder','')}/{app.get('app_file','')}"
            else:
                url = ""
            ver_for_dir  = _install_clean
            installers   = inst_base  / name / ver_for_dir
            installed_at = instd_base / name / ver_for_dir
            if ver_for_dir == "master":
                import re as _re_vd2
                _marker2 = inst_base / name / "master_version.txt"
                if _marker2.exists():
                    try:
                        _mv_str2 = _marker2.read_text(encoding="utf-8").strip()
                        if _re_vd2.match(r'\d+\.\d+', _mv_str2):
                            _redir_inst2 = inst_base / name / _mv_str2
                            if _redir_inst2.resolve() != installers.resolve():
                                ver_for_dir  = _mv_str2
                                installers   = _redir_inst2
                                installed_at = instd_base / name / ver_for_dir
                    except Exception:
                        pass
            downloaded = False
            if installers.exists():
                if (installers / ".download_complete").exists():
                    downloaded = True
                else:
                    for _ext in (".exe", ".msi"):
                        if list(installers.glob(f"*{_ext}")):
                            downloaded = True; break
            try:
                install_info = _get_ui_installation(f"remote_payor_{name}", ver_for_dir)
            except Exception:
                install_info = None
            if install_info:
                install_path = install_info.get("InstallPath", "")
                main_exe     = install_info.get("MainExe", "")
                installed    = bool(install_path and Path(install_path).exists())
            else:
                install_path = str(installed_at)
                main_exe     = ""
                installed    = installed_at.exists()
            result.append({**app, "url": url, "version": ver_for_dir,
                           "installers": str(installers), "installed_at": install_path,
                           "installed": installed, "downloaded": downloaded, "main_exe": main_exe})
        return config, result

    # Remote payor UI apps use namespaced app_ids (e.g. "rp_manager") to share
    # the existing _ui_downloads / _ui_install_ops tracking dicts safely.
    def _rp_aid(app_id):
        return f"rp_{app_id}"

    @app.route("/api/remote-app/payor/ui-apps", methods=["GET"])
    def api_rp_ui_apps_get():
        try:
            vm_ip = request.args.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
            config, apps = _rp_ui_get_apps(vm_ip)
            return jsonify({"ok": True, "config": config, "apps": apps})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/remote-app/payor/ui-apps/config", methods=["POST"])
    def api_rp_ui_apps_save_config():
        try:
            body = request.get_json() or {}
            vm_ip = body.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
            updates = {k: str(body[k]).strip() for k in ("base_url", "version", "installers_base", "installed_base") if k in body}
            if updates:
                _rp_ui_ensure_config(vm_ip)
                _rp_ui_write_config(updates)
            config, apps = _rp_ui_get_apps(vm_ip)
            return jsonify({"ok": True, "config": config, "apps": apps})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/remote-app/payor/ui-apps/<app_id>/download", methods=["POST"])
    def api_rp_ui_apps_download(app_id):
        try:
            import threading as _thr
            vm_ip = request.args.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
            _, apps = _rp_ui_get_apps(vm_ip)
            app_obj = next((a for a in apps if a["app_id"] == app_id), None)
            if not app_obj:
                return jsonify({"ok": False, "error": f"Unknown app: {app_id}"})
            url = app_obj.get("url", "")
            if not url:
                return jsonify({"ok": False, "error": "No URL configured — set the Base URL in config"})
            app_file = app_obj.get("app_file", url.split("/")[-1])
            dest_path = Path(app_obj["installers"]) / app_file
            nid = _rp_aid(app_id)
            with _ui_downloads_lock:
                _ui_downloads[nid] = {"status": "starting", "percent": 0, "source_url": url}
            _thr.Thread(
                target=_do_download,
                args=(nid, url, dest_path, app_obj["display_name"]),
                daemon=True,
            ).start()
            return jsonify({"ok": True, "url": url})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/remote-app/payor/ui-apps/<app_id>/download/progress", methods=["GET"])
    def api_rp_ui_apps_download_progress(app_id):
        with _ui_downloads_lock:
            state = dict(_ui_downloads.get(_rp_aid(app_id), {"status": "idle"}))
        return jsonify(state)

    @app.route("/api/remote-app/payor/ui-apps/<app_id>/run-installer", methods=["POST"])
    def api_rp_ui_apps_run_installer(app_id):
        try:
            import threading as _thr
            vm_ip = request.args.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
            _, apps = _rp_ui_get_apps(vm_ip)
            app_obj = next((a for a in apps if a["app_id"] == app_id), None)
            if not app_obj:
                return jsonify({"ok": False, "error": f"Unknown app: {app_id}"})
            inst_dir = Path(app_obj["installers"])
            target = None
            if inst_dir.exists():
                for ext in (".application", ".exe", ".msi"):
                    hits = list(inst_dir.glob(f"*{ext}"))
                    if hits:
                        target = hits[0]; break
            if not target:
                return jsonify({"ok": False, "error": f"No installer found in {inst_dir}"})
            install_dir = Path(app_obj["installed_at"]) if app_obj.get("installed_at") else (
                (HE_UI_INSTALLED_BASE / "Remote") / app_obj["display_name"] / app_obj["version"]
            )
            nid = _rp_aid(app_id)
            with _ui_install_ops_lock:
                _ui_install_ops[nid] = {"status": "installing", "percent": 0, "elapsed": 0,
                                        "phase_label": "Starting…", "error": None}
            _weblogic_url = f"http://{vm_ip}:7001/web-services/"
            _thr.Thread(
                target=_do_install_direct,
                args=(nid, target, app_obj["url"], install_dir,
                      f"remote_payor_{app_obj['display_name']}", app_obj["version"]),
                kwargs={"weblogic_url": _weblogic_url},
                daemon=True,
            ).start()
            return jsonify({"ok": True})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/remote-app/payor/ui-apps/<app_id>/install-progress", methods=["GET"])
    def api_rp_ui_apps_install_progress(app_id):
        with _ui_install_ops_lock:
            state = dict(_ui_install_ops.get(_rp_aid(app_id), {"status": "idle"}))
        return jsonify(state)

