    @app.route("/api/remote-app/payor/ui-apps/<app_id>/open", methods=["POST"])
    def api_rp_ui_apps_open(app_id):
        try:
            import subprocess as _subp, time as _t
            vm_ip = request.args.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
            _, apps = _rp_ui_get_apps(vm_ip)
            app_obj = next((a for a in apps if a["app_id"] == app_id), None)
            if not app_obj:
                return jsonify({"ok": False, "error": f"Unknown app: {app_id}"})

            def _launch(exe_path):
                exe = Path(exe_path)
                si = _subp.STARTUPINFO()
                si.dwFlags = _subp.STARTF_USESHOWWINDOW; si.wShowWindow = 1
                proc = _subp.Popen([str(exe)], cwd=str(exe.parent), startupinfo=si,
                                   creationflags=_subp.DETACHED_PROCESS | _subp.CREATE_NEW_PROCESS_GROUP)
                _t.sleep(1.5)
                if proc.poll() is not None:
                    raise RuntimeError(f"Process exited immediately (code {proc.returncode}). Exe: {exe}")
                return str(exe)

            _SKIP = {"7za.exe", "7z.exe", "7zfm.exe", "7zg.exe",
                     "setup.exe", "uninstall.exe", "updater.exe", "crashreporter.exe", "squirrel.exe"}

            main_exe = app_obj.get("main_exe", "")
            if main_exe and Path(main_exe).exists() and Path(main_exe).name.lower() not in _SKIP:
                return jsonify({"ok": True, "message": f"Opened: {_launch(main_exe)}"})
            install_dir = Path(app_obj.get("installed_at", ""))
            if not install_dir.exists():
                return jsonify({"ok": False, "error": "Application is not installed. Please download and install first."})
            all_exes = [e for e in install_dir.rglob("*.exe") if e.name.lower() not in _SKIP]
            app_name_lower = app_obj.get("display_name", "").lower()
            preferred = [e for e in all_exes if app_name_lower in e.name.lower()]
            hit = preferred[0] if preferred else (all_exes[0] if all_exes else None)
            if hit:
                return jsonify({"ok": True, "message": f"Opened: {_launch(hit)}"})
            return jsonify({"ok": False, "error": f"No launchable executable found in {install_dir}."})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/remote-app/payor/ui-apps/<app_id>/uninstall", methods=["POST"])
    def api_rp_ui_apps_uninstall(app_id):
        try:
            import shutil as _shutil
            vm_ip = request.args.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
            _, apps = _rp_ui_get_apps(vm_ip)
            app_obj = next((a for a in apps if a["app_id"] == app_id), None)
            if not app_obj:
                return jsonify({"ok": False, "error": f"Unknown app: {app_id}"})
            install_path = app_obj.get("installed_at", "")
            if install_path and Path(install_path).exists():
                _shutil.rmtree(install_path)
            try:
                _remove_ui_installation(f"remote_payor_{app_obj['display_name']}", app_obj["version"])
            except Exception:
                pass
            return jsonify({"ok": True, "message": f"Uninstalled {app_obj['display_name']}"})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

