    def _remote_payor_find_repo_cmd(pattern, dflt_branch_file="$HOME/.default-branch"):
        prefix = pattern.split('*')[0]   # e.g. "hrp.payer.core-"
        return (
            "[ -f $HOME/.bash_profile ] && . $HOME/.bash_profile >/dev/null 2>&1; "
            "[ -f $HOME/.bashrc ] && . $HOME/.bashrc >/dev/null 2>&1; "
            f"_DEF=$(cat {dflt_branch_file} 2>/dev/null | tr -d '\\n\\r'); "
            "SRCDIR=''; "
            f"for _BASE in \"${{GIT_HOME:-}}\" \"$HOME\" /home/weblogic /opt; do "
            "  [ -z \"$_BASE\" ] && continue; "
            "  if [ -n \"$_DEF\" ]; then "
            f"    _F=$(ls -d \"$_BASE\"/{prefix}${{_DEF}} 2>/dev/null | head -1); "
            "    [ -n \"$_F\" ] && SRCDIR=\"$_F\" && break; "
            "  fi; "
            f"  _F=$(ls -d \"$_BASE\"/{pattern} 2>/dev/null | head -1); "
            "  [ -n \"$_F\" ] && SRCDIR=\"$_F\" && break; "
            "done; "
            f"[ -z \"$SRCDIR\" ] && printf 'ERROR: repo {pattern} not found under $GIT_HOME / $HOME / /home/weblogic' && exit 1; "
        )

    @app.route("/api/remote-app/payor/git-local-branches", methods=["GET"])
    def api_remote_payor_git_local_branches():
        vm_ip   = request.args.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
        cfg     = _read_remote_app_config("payor")
        pattern = cfg.get("git_pattern", "hrp.payer.core-*")
        find    = _remote_payor_find_repo_cmd(pattern)
        cmd     = find + "git -C \"$SRCDIR\" branch 2>&1"
        ok, out, err = _ssh_run(vm_ip, cmd)
        if not ok:
            return jsonify({"ok": False, "error": err or out or "SSH failed"})
        branches = []
        current  = None
        for line in (out or "").strip().splitlines():
            line = line.strip()
            if line.startswith("* "):
                current = line[2:].strip()
                branches.append(current)
            elif line:
                branches.append(line)
        return jsonify({"ok": True, "branches": branches, "current": current})

    @app.route("/api/remote-app/payor/git-checkout", methods=["POST"])
    def api_remote_payor_git_checkout():
        body   = request.get_json() or {}
        vm_ip  = body.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
        branch = (body.get("branch") or "").strip()
        if not branch:
            return jsonify({"ok": False, "error": "branch is required"})
        cfg     = _read_remote_app_config("payor")
        pattern = cfg.get("git_pattern", "hrp.payer.core-*")
        find    = _remote_payor_find_repo_cmd(pattern)
        cmd     = (find +
                   f"git -C \"$SRCDIR\" checkout {branch} 2>&1 && "
                   f"echo '{branch}' > $HOME/.default-branch")
        ok, out, err = _ssh_run(vm_ip, cmd)
        if not ok:
            return jsonify({"ok": False, "error": err or out or "SSH failed"})
        # Branch changed — invalidate branch-related caches
        _rcache_invalidate(vm_ip, "branch_info")
        _rcache_invalidate(vm_ip, "branch_info_payor")
        return jsonify({"ok": True, "output": out})

    @app.route("/api/remote-app/payor/git-branch", methods=["DELETE"])
    def api_remote_payor_git_branch_delete():
        body   = request.get_json() or {}
        vm_ip  = body.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
        branch = (body.get("branch") or "").strip()
        if not branch:
            return jsonify({"ok": False, "error": "branch is required"})
        cfg     = _read_remote_app_config("payor")
        pattern = cfg.get("git_pattern", "hrp.payer.core-*")
        find    = _remote_payor_find_repo_cmd(pattern)
        cmd     = find + f"git -C \"$SRCDIR\" branch -d {branch} 2>&1"
        ok, out, err = _ssh_run(vm_ip, cmd)
        if not ok:
            return jsonify({"ok": False, "error": err or out or "SSH failed"})
        return jsonify({"ok": True, "output": out})

    @app.route("/api/remote-app/payor/git-pull", methods=["POST"])
    def api_remote_payor_git_pull():
        body    = request.get_json() or {}
        vm_ip   = body.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
        cfg     = _read_remote_app_config("payor")
        pattern = cfg.get("git_pattern", "hrp.payer.core-*")
        find    = _remote_payor_find_repo_cmd(pattern)
        cmd     = find + "git -C \"$SRCDIR\" pull 2>&1"
        ok, out, err = _ssh_run(vm_ip, cmd, timeout=60)
        if not ok:
            return jsonify({"ok": False, "error": err or out or "SSH failed"})
        # Pull may change metadata/release.txt — invalidate branch caches
        _rcache_invalidate(vm_ip, "branch_info")
        _rcache_invalidate(vm_ip, "branch_info_payor")
        return jsonify({"ok": True, "output": out.strip()})

    @app.route("/api/remote-app/payor/branches", methods=["GET"])
    def api_remote_payor_branches():
        vm_ip   = request.args.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
        cfg     = _read_remote_app_config("payor")
        pattern = cfg.get("git_pattern", "hrp.payer.core-*")
        find    = _remote_payor_find_repo_cmd(pattern)
        # List all remote branches that match release-*, strip the prefix, return sorted versions
        cmd = (
            find +
            "git -C \"$SRCDIR\" branch -a 2>/dev/null | "
            "grep -E 'remotes/.*/release-' | "
            "sed 's|.*release-||' | "
            "sed 's/[[:space:]]//g' | "
            "sort -u"
        )
        ok, out, err = _ssh_run(vm_ip, cmd, timeout=30)
        if not ok:
            return jsonify({"ok": False, "error": err or out or "SSH failed"})

        import re as _re

        def _sort_key(v):
            parts = _re.split(r"[.\-]", v)
            result = []
            for x in parts:
                result.append((0, int(x)) if x.isdigit() else (1, x))
            return result

        versions = sorted(
            [v.strip() for v in out.strip().splitlines() if v.strip()],
            key=_sort_key,
            reverse=True,
        )
        return jsonify({"ok": True, "branches": ["master"] + versions})

    @app.route("/api/remote-app/payor/open-terminal", methods=["POST"])
    def api_remote_payor_open_terminal():
        body     = request.get_json() or {}
        vm_ip    = body.get("vm_ip", _REMOTE_DEV_DEFAULT_VM)
        vm_user, vm_pass, vm_key = _lookup_vm_credentials(vm_ip)
        init_cmd = "source ~/.bash_profile 2>/dev/null; source ~/.bashrc 2>/dev/null; tosrc"

        # Write a self-contained paramiko terminal script so we can pass the
        # password without it appearing on the command line or in a shell history.
        script = (
            "import sys, time, threading, pathlib\n"
            "import paramiko\n"
            f"_vm_ip   = {repr(vm_ip)}\n"
            f"_user    = {repr(vm_user)}\n"
            f"_pass    = {repr(vm_pass)}\n"
            f"_key     = {repr(vm_key)}\n"
            f"_init    = {repr(init_cmd)}\n"
            "print(f'Connecting to {_user}@{_vm_ip} ...')\n"
            "sys.stdout.flush()\n"
            "c = paramiko.SSHClient()\n"
            "c.set_missing_host_key_policy(paramiko.AutoAddPolicy())\n"
            "kw = dict(hostname=_vm_ip, port=22, username=_user, timeout=15)\n"
            "if _key and pathlib.Path(_key).exists():\n"
            "    kw.update(key_filename=_key, look_for_keys=False, allow_agent=False)\n"
            "elif _pass:\n"
            "    kw.update(password=_pass, look_for_keys=False, allow_agent=False)\n"
            "try:\n"
            "    c.connect(**kw)\n"
            "except Exception as e:\n"
            "    print(f'Connection failed: {e}'); input('Press Enter to close...'); sys.exit(1)\n"
            "print('Connected.')\n"
            "sys.stdout.flush()\n"
            "import shutil as _sh\n"
            "cols, rows = _sh.get_terminal_size((200, 50))\n"
            "ch = c.invoke_shell(term='xterm-256color', width=cols, height=rows)\n"
            "time.sleep(0.8)\n"
            "while ch.recv_ready(): sys.stdout.buffer.write(ch.recv(4096))\n"
            "sys.stdout.buffer.flush()\n"
            "ch.send(_init + '\\n')\n"
            "import msvcrt\n"
            "_done = threading.Event()\n"
            "def _rx():\n"
            "    while not _done.is_set():\n"
            "        if ch.recv_ready():\n"
            "            data = ch.recv(4096)\n"
            "            if not data: _done.set(); break\n"
            "            sys.stdout.buffer.write(data); sys.stdout.buffer.flush()\n"
            "        elif ch.closed: _done.set(); break\n"
            "        else: time.sleep(0.01)\n"
            "threading.Thread(target=_rx, daemon=True).start()\n"
            "_SPECIAL = {'K':'\\x1b[D','M':'\\x1b[C','H':'\\x1b[A','P':'\\x1b[B',"
            "            'S':'\\x1b[3~','G':'\\x1b[H','O':'\\x1b[F'}\n"
            "try:\n"
            "    while not _done.is_set():\n"
            "        if msvcrt.kbhit():\n"
            "            k = msvcrt.getwch()\n"
            "            if k in ('\\x00','\\xe0'):\n"
            "                k2 = msvcrt.getwch()\n"
            "                seq = _SPECIAL.get(k2)\n"
            "                if seq: ch.send(seq.encode())\n"
            "            else:\n"
            "                ch.send(k if isinstance(k,bytes) else k.encode('utf-8','replace'))\n"
            "        else: time.sleep(0.01)\n"
            "except (KeyboardInterrupt, EOFError):\n"
            "    try: ch.send(b'\\x03')\n"
            "    except Exception: pass\n"
            "c.close()\n"
            "print('\\n[SSH session closed]')\n"
            "input('Press Enter to close...')\n"
        )

        import tempfile, base64 as _b64
        tmp = tempfile.NamedTemporaryFile(
            mode="w", suffix="_idp_payor_term.py", delete=False, encoding="utf-8"
        )
        tmp.write(script); tmp.flush(); tmp.close()

        ps_cmd = f'python "{tmp.name}"'
        try:
            encoded = _b64.b64encode(ps_cmd.encode("utf-16-le")).decode("ascii")
            subprocess.Popen(
                ["powershell.exe", "-EncodedCommand", encoded],
                creationflags=0x00000010,  # CREATE_NEW_CONSOLE
            )
            return jsonify({"ok": True})
        except Exception as exc:
            return jsonify({"ok": False, "error": str(exc)})

