    @app.route("/", defaults={"path": ""})
    @app.route("/<path:path>")
    def serve_react(path):
        if path.startswith("api"):
            return jsonify({"error": "not found"}), 404
        target = STATIC_DIR / path
        if path and target.is_file():
            return send_from_directory(str(STATIC_DIR), path)
        # index.html must never be cached — the hashed JS/CSS assets it references change
        # on every build, so a stale index.html would load an outdated bundle.
        from flask import make_response
        resp = make_response(send_from_directory(str(STATIC_DIR), "index.html"))
        resp.headers["Cache-Control"] = "no-cache, no-store, must-revalidate"
        resp.headers["Pragma"] = "no-cache"
        resp.headers["Expires"] = "0"
        return resp

    # ── WebSocket terminal ─────────────────────────────────────────────────────
    try:
        from flask_sock import Sock as _Sock
        _sock = _Sock(app)

        @_sock.route("/ws/vms/developer/<vm_name>/terminal")
        def vm_terminal_ws(ws, vm_name):
            import json as _json, threading as _thr, time as _tm, select as _sel
            try:
                import openpyxl as _xl
            except ImportError:
                ws.send("ERROR: openpyxl not installed.\r\n"); return
            try:
                import paramiko as _pm
            except ImportError:
                ws.send("ERROR: paramiko not installed. Run: pip install paramiko\r\n"); return

            # Look up VM credentials from vms.xlsx
            if not VMS_FILE.exists():
                ws.send("ERROR: vms.xlsx not found.\r\n"); return
            wb  = _xl.load_workbook(str(VMS_FILE))
            vm  = None
            for _sheet in wb.sheetnames:
                _wsh  = wb[_sheet]
                _hdrs = [str(_wsh.cell(1, c).value or "").strip().lower()
                         for c in range(1, _wsh.max_column + 1)]
                if "name" not in _hdrs or "ip" not in _hdrs:
                    continue
                for _row in _wsh.iter_rows(min_row=2, values_only=True):
                    _d = {k: ("" if v is None else str(v).strip())
                          for k, v in zip(_hdrs, _row)}
                    if _d.get("name", "").lower() == vm_name.lower():
                        vm = _d; break
                if vm:
                    break

            if not vm:
                ws.send(f"ERROR: VM '{vm_name}' not found.\r\n"); return

            ip       = vm.get("ip", "")
            # description column stores SSH username (per vms.xlsx convention)
            user     = vm.get("description", "") or "weblogic"
            password = vm.get("password", "")
            if not ip:
                ws.send("ERROR: VM has no IP address.\r\n"); return

            ssh = _pm.SSHClient()
            ssh.set_missing_host_key_policy(_pm.AutoAddPolicy())
            try:
                ssh.connect(hostname=ip, port=22, username=user, password=password,
                            timeout=15, allow_agent=False, look_for_keys=False)
            except Exception as e:
                ws.send(f"SSH connection failed: {e}\r\n"); return

            chan = ssh.invoke_shell(term="xterm-256color", width=220, height=50)
            chan.setblocking(False)
            stop = _thr.Event()

            def _read_ssh():
                try:
                    while not stop.is_set():
                        rd, _, _ = _sel.select([chan], [], [], 0.5)
                        if rd:
                            data = chan.recv(8192)
                            if not data:
                                break
                            ws.send(data.decode("utf-8", errors="replace"))
                except Exception:
                    pass
                finally:
                    # Only signal stop — do NOT call ws.close() from this thread.
                    # The main thread detects stop and exits cleanly, letting
                    # flask-sock send a proper close frame (code 1000).
                    stop.set()

            _thr.Thread(target=_read_ssh, daemon=True).start()

            try:
                while not stop.is_set():
                    try:
                        msg = ws.receive(timeout=2)
                    except Exception:
                        break
                    if msg is None:
                        continue
                    try:
                        obj = _json.loads(msg)
                        if obj.get("type") == "input":
                            chan.sendall(obj.get("data", "").encode("utf-8"))
                        elif obj.get("type") == "resize":
                            chan.resize_pty(
                                width  = max(1, int(obj.get("cols", 80))),
                                height = max(1, int(obj.get("rows", 24))),
                            )
                    except Exception:
                        pass
            finally:
                stop.set()
                try: chan.close()
                except: pass
                try: ssh.close()
                except: pass

    except ImportError:
        pass  # flask-sock not installed; terminal feature unavailable

    # ── JIRA helpers (sprint endpoints) ────────────────────────────────────────
    def _jira_creds():
        if not SECRETS_FILE.exists():
            return None, "secrets.xlsx not found"
        import openpyxl as _xl_j
        wb = _xl_j.load_workbook(str(SECRETS_FILE), data_only=True)
        sec = {}
        for sn in ("Atlassian", "atlassian"):
            if sn in wb.sheetnames:
                for r in wb[sn].iter_rows(min_row=2, values_only=True):
                    if r and r[0] and r[1]: sec[str(r[0]).strip()] = str(r[1]).strip()
                break
        wb.close()
        bu = sec.get("jira_base_url", "").rstrip("/")
        em = sec.get("jira_email", "")
        tk = sec.get("jira_api_token", "")
        if not bu or not em or not tk:
            return None, "jira_base_url/jira_email/jira_api_token missing in secrets.xlsx Atlassian tab"
        return {"base_url": bu, "email": em, "api_token": tk}, None

    def _fetch_board_issues(creds, sprint_url):
        import re as _re_b, urllib3 as _u3b
        import requests as _rq_b
        from requests.auth import HTTPBasicAuth as _BA_b
        _u3b.disable_warnings()
        m = _re_b.search(r'/boards/(\d+)', sprint_url)
        if not m: return None, "Could not parse board ID from URL"
        board_id = m.group(1)
        base = creds["base_url"]
        auth = _BA_b(creds["email"], creds["api_token"])
        # Use board/issue endpoint with openSprints() JQL — works for cross-project boards
        # and both Scrum and Kanban. The board's own saved filter is applied first,
        # then our JQL narrows to active sprint issues only (no backlog, no epics).
        jql = 'sprint in openSprints() AND issuetype not in (Epic, "Sub-task")'
        issues, start = [], 0
        while True:
            r = _rq_b.get(f"{base}/rest/agile/1.0/board/{board_id}/issue",
                          params={"startAt": start, "maxResults": 100, "jql": jql,
                                  "fields": "summary,status,assignee,issuetype,story_points,"
                                            "customfield_10045,customfield_10016,customfield_10028,"
                                            "customfield_10015,customfield_10032,customfield_10033,"
                                            "customfield_10014,customfield_10105,parent"},
                          auth=auth, headers={"Accept": "application/json"}, timeout=30, verify=False)
            if r.status_code != 200:
                return None, f"Board issues API: HTTP {r.status_code} — {r.text[:300]}"
            data = r.json()
            batch = data.get("issues", [])
            issues.extend(batch)
            if start + len(batch) >= data.get("total", 0): break
            start += len(batch)
        return issues, None

    def _fmt_sp(v):
        if v is None: return None
        if isinstance(v, (list, tuple)):
            v = v[0] if v else None
            if v is None: return None
        if isinstance(v, dict):
            v = v.get("value") if v.get("value") is not None else v.get("displayValue")
            if v is None: return None
        try:
            f = float(v)
            return int(f) if f == int(f) else f
        except (TypeError, ValueError):
            s = str(v).strip()
            return s if s else None

    def _sp_from_fields(fields):
        for k in ("story_points", "customfield_10045", "customfield_10016", "customfield_10028",
                  "customfield_10015", "customfield_10032", "customfield_10033", "customfield_10014",
                  "customfield_10105"):
            v = _fmt_sp(fields.get(k))
            if v is not None and isinstance(v, (int, float)):
                return v
        return None

    def _fetch_issue_prs(creds, issue_id, issue_key):
        import requests as _rq_pr, urllib3 as _u3p
        from requests.auth import HTTPBasicAuth as _BA_pr
        _u3p.disable_warnings()
        base = creds["base_url"]
        auth = _BA_pr(creds["email"], creds["api_token"])
        headers = {"Accept": "application/json"}
        pr_urls, pr_statuses = [], []
        for app_type in ("oAuth-com.github.integration.production", "GitHub",
                         "com.github.integration.production"):
            try:
                r = _rq_pr.get(
                    f"{base}/rest/dev-status/1.0/issue/detail",
                    params={"issueId": issue_id, "applicationType": app_type,
                            "dataType": "pullrequest"},
                    auth=auth, headers=headers, timeout=10, verify=False
                )
                if r.status_code != 200:
                    continue
                for d in r.json().get("detail", []):
                    for pr in d.get("pullRequests", []):
                        branch = str((pr.get("source") or {}).get("branch") or "")
                        if issue_key.upper() not in branch.upper():
                            continue
                        url = pr.get("url", "")
                        if url:
                            pr_urls.append(url)
                            pr_statuses.append(pr.get("status", ""))
                if pr_urls:
                    break
            except Exception:
                pass
        return pr_urls, pr_statuses

    def _business_days(start_str, end_date=None):
        from datetime import date, timedelta
        try:
            start = date.fromisoformat(str(start_str)[:10])
        except Exception:
            return 0
        end = end_date or date.today()
        if end < start:
            return 0
        count, cur = 0, start
        while cur <= end:
            if cur.weekday() < 5:
                count += 1
            cur += timedelta(days=1)
        return count

    def _ensure_issue_type_col(ws):
        """Make sure the sheet has an "Issue Type" column right after "Story" (backfilled from "Type"). True if it added one."""
        if ws is None:
            return False
        hdr = [c.value for c in next(ws.iter_rows(min_row=1, max_row=1))]
        if "Issue Type" in hdr or "Story" not in hdr:
            return False
        at = hdr.index("Story") + 2            # 1-based column right after Story
        ws.insert_cols(at)
        ws.cell(row=1, column=at).value = "Issue Type"
        if "Type" in hdr:
            tcol = hdr.index("Type") + 1 + (1 if hdr.index("Type") + 1 >= at else 0)
            for r in range(2, ws.max_row + 1):
                ws.cell(row=r, column=at).value = ws.cell(row=r, column=tcol).value
        return True

    _prev_idx_cache = {}

    def _prev_index(team, sprint_root):
        """{JIRA KEY: [(sprint_name, devdays, indevsince, qadays, inqasince, sprints), ...]} newest sprint first.
        Rebuilt only when the team's previous-sprint files change."""
        prev_dir = sprint_root / "PreviousSprints" / team
        if not prev_dir.exists():
            return {}
        files = sorted(prev_dir.glob("*.xlsx"), key=lambda f: f.stat().st_mtime, reverse=True)
        sig = tuple((f.name, f.stat().st_mtime) for f in files)
        ck = (team, str(prev_dir))
        if _prev_idx_cache.get(ck, (None,))[0] == sig:
            return _prev_idx_cache[ck][1]
        import openpyxl as _xl_pv
        idx = {}
        for sf in files:
            try:
                wb = _xl_pv.load_workbook(str(sf), read_only=True, data_only=True)
                seen = set()
                for sn in ("Sprint Board", "Adhoc Task"):
                    if sn not in wb.sheetnames: continue
                    w = wb[sn]
                    hdr = [c.value for c in next(w.iter_rows(min_row=1, max_row=1))]
                    ci = {h: i for i, h in enumerate(hdr) if h}
                    ji = ci.get("JIRA ID")
                    if ji is None: continue
                    def g(rp, name):
                        i = ci.get(name)
                        return rp[i] if i is not None and i < len(rp) else None
                    for rp in w.iter_rows(min_row=2, values_only=True):
                        v = rp[ji] if ji < len(rp) else None
                        k = str(v).strip().upper() if v else ""
                        if k and k not in seen:
                            seen.add(k)
                            idx.setdefault(k, []).append((sf.stem, g(rp, "DevDays"), g(rp, "InDevSince"),
                                                          g(rp, "QADays"), g(rp, "InQASince"), g(rp, "Sprints")))
                wb.close()
            except Exception:
                pass
        _prev_idx_cache[ck] = (sig, idx)
        return idx

    def _find_prev_dev_days(team, key, sprint_root):
        """Return (dev_days, in_dev_since, found, qa_days, in_qa_since, sprints_before, origin_sprint) for key.
        Dev/QA days come from the most recent previous sprint holding the story; sprints_before
        counts every previous sprint it appeared in; origin_sprint is the oldest one."""
        if not team or not sprint_root:
            return None, None, False, None, None, 0, ""
        try:
            hits = _prev_index(team, sprint_root).get(key) or []
        except Exception:
            hits = []
        if not hits:
            return None, None, False, None, None, 0, ""
        latest = hits[0]
        try: stored = int(latest[5])
        except Exception: stored = 0
        origin = hits[-1][0]
        pre = team + "_"
        if origin.startswith(pre): origin = origin[len(pre):]
        return latest[1], latest[2], True, latest[3], latest[4], max(len(hits), stored), origin

    def _apply_board_issues(ws, issues, base_url, creds=None, freeze_dev=True, team=None, sprint_root=None, adhoc_ws=None):
        from datetime import date as _date
        _today_str = _date.today().isoformat()
        _IN_DEV_STATUSES = {"in dev", "in development"}
        def _is_in_dev(s): return any(s.lower().strip() == x for x in _IN_DEV_STATUSES)
        def _is_testing(s): return s.lower().strip() in ("in testing", "testing")

        _ensure_issue_type_col(ws)
        _ensure_issue_type_col(adhoc_ws)
        header = [c.value for c in next(ws.iter_rows(min_row=1, max_row=1))]
        ci = {h: i for i, h in enumerate(header) if h}
        it_i      = ci.get("Issue Type")
        jira_i    = ci.get("JIRA ID");    story_i   = ci.get("Story")
        type_i    = ci.get("Type");       stat_i    = ci.get("Status")
        dev_i     = ci.get("Developer");  sp_i      = ci.get("Story Point")
        prs_i     = ci.get("PRs");        pr_stat_i = ci.get("PR Status")
        dd_i      = ci.get("DevDays");    ids_i     = ci.get("InDevSince")
        # Ensure DevDays and InDevSince columns exist
        if dd_i is None:
            ws.cell(row=1, column=len(header)+1).value = "DevDays"
            dd_i = len(header); header.append("DevDays"); ci["DevDays"] = dd_i
        if ids_i is None:
            ws.cell(row=1, column=len(header)+1).value = "InDevSince"
            ids_i = len(header); header.append("InDevSince"); ci["InDevSince"] = ids_i
        qa_i      = ci.get("QA")
        qd_i      = ci.get("QADays");     qs_i      = ci.get("InQASince")
        if qd_i is None:
            ws.cell(row=1, column=len(header)+1).value = "QADays"
            qd_i = len(header); header.append("QADays"); ci["QADays"] = qd_i
        if qs_i is None:
            ws.cell(row=1, column=len(header)+1).value = "InQASince"
            qs_i = len(header); header.append("InQASince"); ci["InQASince"] = qs_i
        co_i      = ci.get("Carried Over")
        if co_i is None:
            ws.cell(row=1, column=len(header)+1).value = "Carried Over"
            co_i = len(header); header.append("Carried Over"); ci["Carried Over"] = co_i
        sc_i      = ci.get("Sprints")
        if sc_i is None:
            ws.cell(row=1, column=len(header)+1).value = "Sprints"
            sc_i = len(header); header.append("Sprints"); ci["Sprints"] = sc_i
        og_i      = ci.get("Origin Sprint")
        if og_i is None:
            ws.cell(row=1, column=len(header)+1).value = "Origin Sprint"
            og_i = len(header); header.append("Origin Sprint"); ci["Origin Sprint"] = og_i
        if jira_i is None: return 0
        existing = {}
        for ri, row in enumerate(ws.iter_rows(min_row=2, values_only=True)):
            v = row[jira_i] if jira_i < len(row) else None
            if v: existing[str(v).strip().upper()] = ri + 2
        count = 0
        for issue in issues:
            key      = (issue.get("key") or "").upper()
            issue_id = issue.get("id")
            fields   = issue.get("fields") or {}
            summary   = fields.get("summary") or ""
            status    = (fields.get("status")   or {}).get("name") or ""
            assignee  = (fields.get("assignee") or {}).get("displayName") or ""
            issue_type = (fields.get("issuetype") or {}).get("name") or ""
            sp_val    = _sp_from_fields(fields)
            if not key: continue
            # Fallback: if board API gave no SP, fetch the issue directly
            if sp_val is None and creds:
                try:
                    import requests as _rq_sp_fb, urllib3 as _u3_sp_fb
                    from requests.auth import HTTPBasicAuth as _BA_sp_fb
                    _u3_sp_fb.disable_warnings()
                    _fb_r = _rq_sp_fb.get(
                        f"{creds['base_url']}/rest/api/2/issue/{key}",
                        params={"fields": "story_points,customfield_10045,customfield_10016,"
                                          "customfield_10028,customfield_10015,customfield_10032,"
                                          "customfield_10033,customfield_10014,customfield_10105"},
                        auth=_BA_sp_fb(creds["email"], creds["api_token"]),
                        headers={"Accept": "application/json"}, timeout=10, verify=False
                    )
                    if _fb_r.status_code == 200:
                        sp_val = _sp_from_fields(_fb_r.json().get("fields", {}))
                except Exception:
                    pass
            # Fetch PRs filtered by branch containing ticket key
            pr_urls_list, pr_stat_list = [], []
            if creds and issue_id:
                pr_urls_list, pr_stat_list = _fetch_issue_prs(creds, issue_id, key)
            prs_val    = "|".join(pr_urls_list) if pr_urls_list else None
            pr_stat_val = "|".join(pr_stat_list) if pr_stat_list else None
            if key in existing:
                er = existing[key]
                if story_i    is not None: ws.cell(row=er, column=story_i+1).value    = summary
                if type_i     is not None and issue_type: ws.cell(row=er, column=type_i+1).value = issue_type
                if it_i       is not None and issue_type: ws.cell(row=er, column=it_i+1).value   = issue_type
                if stat_i     is not None: ws.cell(row=er, column=stat_i+1).value     = status
                if sp_i       is not None: ws.cell(row=er, column=sp_i+1).value       = sp_val
                if prs_i      is not None and prs_val     is not None: ws.cell(row=er, column=prs_i+1).value     = prs_val
                if pr_stat_i  is not None and pr_stat_val is not None: ws.cell(row=er, column=pr_stat_i+1).value = pr_stat_val
                if not freeze_dev:
                    if dev_i is not None and assignee: ws.cell(row=er, column=dev_i+1).value = assignee
                # QA: when in Testing, always fill an empty QA; overwrite a filled one only when Dev Freeze is off
                if _is_testing(status) and qa_i is not None and assignee:
                    _cur_qa = ws.cell(row=er, column=qa_i+1).value
                    if not str(_cur_qa or "").strip() or not freeze_dev:
                        ws.cell(row=er, column=qa_i+1).value = assignee
                # QADays: business days spent in Testing (count is kept after leaving Testing)
                _cur_qs = ws.cell(row=er, column=qs_i+1).value
                if _is_testing(status):
                    if not _cur_qs:
                        ws.cell(row=er, column=qs_i+1).value = _today_str
                        _cur_qs = _today_str
                    ws.cell(row=er, column=qd_i+1).value = _business_days(_cur_qs)
                elif _cur_qs:
                    ws.cell(row=er, column=qs_i+1).value = None
                # DevDays logic for existing rows
                cur_ids = ws.cell(row=er, column=ids_i+1).value
                if _is_in_dev(status):
                    if not cur_ids:
                        ws.cell(row=er, column=ids_i+1).value = _today_str
                        cur_ids = _today_str
                    ws.cell(row=er, column=dd_i+1).value = _business_days(cur_ids)
                else:
                    if cur_ids:
                        ws.cell(row=er, column=ids_i+1).value = None
                # First sync after the Sprints column appeared (or row predates carry-over tracking):
                # look the story up in previous sprints once, flag it and carry dev/QA days
                if str(ws.cell(row=er, column=co_i+1).value or "").strip().lower() != "yes":
                    _pdd, _pids, _pfound, _pqd, _pqs, _pn, _porg = _find_prev_dev_days(team, key, sprint_root)
                    if _pfound:
                        ws.cell(row=er, column=co_i+1).value = "Yes"
                        ws.cell(row=er, column=sc_i+1).value = _pn + 1
                        ws.cell(row=er, column=og_i+1).value = _porg
                        if _is_in_dev(status):
                            _ids2 = _pids or ws.cell(row=er, column=ids_i+1).value or _today_str
                            ws.cell(row=er, column=ids_i+1).value = _ids2
                            ws.cell(row=er, column=dd_i+1).value = _business_days(_ids2)
                        elif _pdd is not None:
                            ws.cell(row=er, column=dd_i+1).value = _pdd
                        if _is_testing(status):
                            _qs2 = _pqs or ws.cell(row=er, column=qs_i+1).value or _today_str
                            ws.cell(row=er, column=qs_i+1).value = _qs2
                            ws.cell(row=er, column=qd_i+1).value = _business_days(_qs2)
                        elif _pqd is not None:
                            ws.cell(row=er, column=qd_i+1).value = _pqd
                    else:
                        ws.cell(row=er, column=sc_i+1).value = 1
            else:
                # New ticket: try to carry forward Dev/QA days from previous sprint
                prev_dd, prev_ids, prev_found, prev_qd, prev_qs, prev_n, prev_org = _find_prev_dev_days(team, key, sprint_root)
                if _is_in_dev(status):
                    carry_ids = prev_ids if prev_ids else _today_str
                    carry_dd  = _business_days(carry_ids)
                else:
                    carry_ids = None
                    carry_dd  = prev_dd  # preserve frozen count even if no longer In Dev

                if freeze_dev and adhoc_ws is not None:
                    # Dev is frozen — route new tickets to Adhoc Task sheet
                    _ah = adhoc_ws
                    _ah_hdr = [c.value for c in next(_ah.iter_rows(min_row=1, max_row=1))]
                    _ah_ci  = {h: i for i, h in enumerate(_ah_hdr) if h}
                    # Ensure "Date Added" column exists
                    if "Date Added" not in _ah_ci:
                        _ah.cell(row=1, column=len(_ah_hdr)+1).value = "Date Added"
                        _ah_ci["Date Added"] = len(_ah_hdr); _ah_hdr.append("Date Added")
                    if "Carried Over" not in _ah_ci:
                        _ah.cell(row=1, column=len(_ah_hdr)+1).value = "Carried Over"
                        _ah_ci["Carried Over"] = len(_ah_hdr); _ah_hdr.append("Carried Over")
                    for _nc in ("Sprints", "Origin Sprint", "DevDays", "InDevSince", "QADays", "InQASince"):
                        if _nc not in _ah_ci:
                            _ah.cell(row=1, column=len(_ah_hdr)+1).value = _nc
                            _ah_ci[_nc] = len(_ah_hdr); _ah_hdr.append(_nc)
                    # Skip if already in Adhoc Task
                    _ah_existing = set()
                    for _ahr in _ah.iter_rows(min_row=2, values_only=True):
                        _jc = _ah_ci.get("JIRA ID", 0)
                        if _ahr and _jc < len(_ahr) and _ahr[_jc]:
                            _ah_existing.add(str(_ahr[_jc]).strip().upper())
                    if key not in _ah_existing:
                        _ah_row = [None] * len(_ah_hdr)
                        for _col, _val in [
                            ("JIRA ID", key), ("Story", summary), ("Type", issue_type), ("Issue Type", issue_type),
                            ("Status", status), ("Developer", assignee), ("Story Point", sp_val),
                            ("PRs", prs_val), ("PR Status", pr_stat_val), ("Date Added", _today_str),
                            ("Carried Over", "Yes" if prev_found else None),
                            ("Sprints", (prev_n + 1) if prev_found else 1),
                            ("Origin Sprint", prev_org if prev_found else None),
                            ("QADays", prev_qd), ("InQASince", prev_qs if _is_testing(status) else None),
                            ("DevDays", carry_dd), ("InDevSince", carry_ids),
                        ]:
                            if _col in _ah_ci:
                                _ah_row[_ah_ci[_col]] = _val
                        _ah.append(_ah_row)
                        if base_url:
                            _jira_col = _ah_ci.get("JIRA ID")
                            if _jira_col is not None:
                                _ah.cell(row=_ah.max_row, column=_jira_col+1).hyperlink = f"{base_url}/browse/{key}"
                    else:
                        # Update live fields on existing Adhoc Task row (Story, SP, Status, PRs — NOT Developer/QA)
                        _jc = _ah_ci.get("JIRA ID", 0)
                        for _ahr in _ah.iter_rows(min_row=2):
                            if _ahr[_jc].value and str(_ahr[_jc].value).strip().upper() == key:
                                for _col, _val in [
                                    ("Story", summary), ("Issue Type", issue_type), ("Story Point", sp_val), ("Status", status),
                                    ("PRs", prs_val), ("PR Status", pr_stat_val),
                                ]:
                                    if _col in _ah_ci:
                                        _ahr[_ah_ci[_col]].value = _val
                                break
                else:
                    row_vals = [None] * len(header)
                    row_vals[jira_i] = key
                    if story_i   is not None: row_vals[story_i]   = summary
                    if type_i    is not None: row_vals[type_i]    = issue_type
                    if it_i      is not None: row_vals[it_i]      = issue_type
                    if stat_i    is not None: row_vals[stat_i]    = status
                    if dev_i     is not None: row_vals[dev_i]     = assignee
                    if sp_i      is not None: row_vals[sp_i]      = sp_val
                    if prs_i     is not None: row_vals[prs_i]     = prs_val
                    if pr_stat_i is not None: row_vals[pr_stat_i] = pr_stat_val
                    row_vals[dd_i]  = carry_dd
                    row_vals[co_i]  = "Yes" if prev_found else None
                    row_vals[ids_i] = carry_ids
                    row_vals[sc_i]  = (prev_n + 1) if prev_found else 1
                    row_vals[og_i]  = prev_org if prev_found else None
                    if prev_qd is not None: row_vals[qd_i] = prev_qd
                    if _is_testing(status):
                        if qa_i is not None: row_vals[qa_i] = assignee
                        _qs_new = prev_qs or _today_str
                        row_vals[qs_i] = _qs_new
                        row_vals[qd_i] = _business_days(_qs_new)
                    ws.append(row_vals)
                    if base_url:
                        ws.cell(row=ws.max_row, column=jira_i+1).hyperlink = f"{base_url}/browse/{key}"
            count += 1
        return count

