    @app.route("/api/project-management/sprint/rules-all", methods=["GET"])
    def api_tm_sprint_rules_all():
        import openpyxl as _xl_ra
        RULES_FILE = SPRINT_ROOT / "Rules.xlsx"
        _SHEET_COLS = {
            "Sprint":  ["Rule", "Condition", "Unit", "Notes"],
            "Project": ["JIRA Prefix", "Ticket Type", "Branch Prefix", "Branch Midfix", "Branch Postfix", "Application", "Default"],
        }
        result = {"Sprint": [], "Project": []}
        if RULES_FILE.exists():
            try:
                wb = _xl_ra.load_workbook(str(RULES_FILE), read_only=True, data_only=True)
                for _sn in ("Sprint", "Project"):
                    if _sn in wb.sheetnames:
                        _ws = wb[_sn]
                        _all_rows = list(_ws.iter_rows(min_row=1, values_only=True))
                        if not _all_rows:
                            continue
                        # Use first row as headers; fall back to expected cols
                        _hdr = [str(c).strip() if c is not None else "" for c in _all_rows[0]]
                        _expected = _SHEET_COLS.get(_sn, [])
                        _cols = _hdr if any(_hdr) else _expected
                        for _rr in _all_rows[1:]:
                            if not _rr or all(v is None or str(v).strip() == "" for v in _rr):
                                continue
                            _obj = {}
                            for _ci, _col in enumerate(_cols):
                                _obj[_col] = str(_rr[_ci]).strip() if _ci < len(_rr) and _rr[_ci] is not None else ""
                            result[_sn].append(_obj)
                wb.close()
            except Exception as e:
                return jsonify({"ok": False, "error": str(e)})
        return jsonify({"ok": True, "rules": result})

    @app.route("/api/project-management/sprint/rules-save", methods=["POST"])
    def api_tm_sprint_rules_save():
        import openpyxl as _xl_rs
        RULES_FILE = SPRINT_ROOT / "Rules.xlsx"
        _SHEET_COLS = {
            "Sprint":  ["Rule", "Condition", "Unit", "Notes"],
            "Project": ["JIRA Prefix", "Ticket Type", "Branch Prefix", "Branch Midfix", "Branch Postfix", "Application", "Default"],
        }
        body  = request.get_json() or {}
        rules = body.get("rules") or {}
        try:
            wb = _xl_rs.load_workbook(str(RULES_FILE)) if RULES_FILE.exists() else _xl_rs.Workbook()
            if "Sheet" in wb.sheetnames and len(wb.sheetnames) == 1:
                wb.active.title = "Sprint"
            for _sn, rows in rules.items():
                if _sn not in wb.sheetnames:
                    wb.create_sheet(_sn)
                ws = wb[_sn]
                # clear existing content
                for _row in ws.iter_rows():
                    for _c in _row: _c.value = None
                _cols = _SHEET_COLS.get(_sn, list(rows[0].keys()) if rows else ["Rule", "Value"])
                for _ci, _ch in enumerate(_cols, start=1):
                    ws.cell(row=1, column=_ci).value = _ch
                for _ri, _r in enumerate(rows, start=2):
                    for _ci, _col in enumerate(_cols, start=1):
                        ws.cell(row=_ri, column=_ci).value = str(_r.get(_col, ""))
            wb.save(str(RULES_FILE))
            wb.close()
            return jsonify({"ok": True})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/project-management/sprint/rules", methods=["GET"])
    def api_tm_sprint_rules():
        from datetime import date, timedelta
        import openpyxl as _xl_r
        RULES_FILE = SPRINT_ROOT / "Rules.xlsx"
        if not RULES_FILE.exists():
            return jsonify({"ok": True, "start_date": "", "end_date": ""})
        _DAY_NUM = {"monday": 0, "tuesday": 1, "wednesday": 2, "thursday": 3,
                    "friday": 4, "saturday": 5, "sunday": 6}
        rules = {}
        try:
            _wb_r = _xl_r.load_workbook(str(RULES_FILE), read_only=True, data_only=True)
            if "Sprint" in _wb_r.sheetnames:
                for _rr in _wb_r["Sprint"].iter_rows(min_row=2, values_only=True):
                    if _rr[0] and _rr[1] is not None:
                        rules[str(_rr[0]).strip()] = _rr[1]
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})
        start_day  = str(rules.get("Start Date", "")).strip().lower()
        end_day    = str(rules.get("End Date",   "")).strip().lower()
        try:
            sprint_len = int(rules.get("Sprint Length", 2))
        except Exception:
            sprint_len = 2
        today          = date.today()
        monday_of_week = today - timedelta(days=today.weekday())
        start_date = ""
        end_date   = ""
        if start_day in _DAY_NUM:
            start_date = (monday_of_week + timedelta(days=_DAY_NUM[start_day])).isoformat()
        if end_day in _DAY_NUM and sprint_len > 0:
            monday_end = monday_of_week + timedelta(weeks=sprint_len)
            end_date   = (monday_end + timedelta(days=_DAY_NUM[end_day])).isoformat()
        return jsonify({"ok": True, "start_date": start_date, "end_date": end_date})

    @app.route("/api/project-management/sprint/list", methods=["GET"])
    def api_tm_sprint_list():
        try:
            sprints = []
            if SPRINTS_DIR.exists():
                for f in sorted(SPRINTS_DIR.glob("**/*.xlsx"), reverse=True):
                    sprints.append({"name": f.stem, "file": f.name})
            prev_root = SPRINT_DATA / "PreviousSprints"
            if prev_root.exists():
                for f in sorted(prev_root.glob("**/*.xlsx"), reverse=True):
                    sprints.append({"name": f.stem, "file": f.name, "previous": True})
            return jsonify({"ok": True, "sprints": sprints})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/project-management/sprint/search", methods=["GET"])
    def api_tm_sprint_search():
        import openpyxl as _xl_srch
        q = (request.args.get("q") or "").strip().lower()
        if not q or len(q) < 2:
            return jsonify({"ok": True, "results": []})
        results = []
        _LIMIT = 60
        # Collect all sprint files: current Sprints/** + PreviousSprints/**
        _all_files = []
        for _glob_root in (SPRINTS_DIR, SPRINT_DATA / "PreviousSprints"):
            if _glob_root.exists():
                _all_files.extend(sorted(_glob_root.glob("**/*.xlsx"), reverse=True))
        try:
            for _sf in _all_files:
                if len(results) >= _LIMIT:
                    break
                try:
                    _wb = _xl_srch.load_workbook(str(_sf), read_only=True, data_only=True)
                    _sprint_label = _sf.stem
                    _is_prev = "PreviousSprints" in str(_sf)
                    for _sn in ("Sprint Board", "Adhoc Task"):
                        if _sn not in _wb.sheetnames:
                            continue
                        _ws = _wb[_sn]
                        _all_r = list(_ws.iter_rows(min_row=1, values_only=True))
                        if not _all_r:
                            continue
                        _hdrs = [str(h or "").strip() for h in _all_r[0]]
                        _ji = next((i for i, h in enumerate(_hdrs) if h == "JIRA ID"),   -1)
                        _si = next((i for i, h in enumerate(_hdrs) if h == "Story"),     -1)
                        _sti= next((i for i, h in enumerate(_hdrs) if h == "Status"),    -1)
                        _di = next((i for i, h in enumerate(_hdrs) if h == "Developer"), -1)
                        _spi= next((i for i, h in enumerate(_hdrs) if h == "Story Point"),-1)
                        for _row in _all_r[1:]:
                            if len(results) >= _LIMIT:
                                break
                            if not _row or all(v is None for v in _row):
                                continue
                            _jira = str(_row[_ji] if _ji >= 0 and _ji < len(_row) and _row[_ji] else "").strip()
                            _story= str(_row[_si] if _si >= 0 and _si < len(_row) and _row[_si] else "").strip()
                            if not _jira and not _story:
                                continue
                            if q in _jira.lower() or q in _story.lower():
                                results.append({
                                    "jira_id":  _jira,
                                    "story":    _story,
                                    "status":   str(_row[_sti] if _sti >= 0 and _sti < len(_row) and _row[_sti] else "").strip(),
                                    "developer":str(_row[_di]  if _di  >= 0 and _di  < len(_row) and _row[_di]  else "").strip(),
                                    "sp":       _row[_spi] if _spi >= 0 and _spi < len(_row) else None,
                                    "sprint":   _sprint_label,
                                    "file":     _sf.name,
                                    "sheet":    _sn,
                                    "previous": _is_prev,
                                })
                    _wb.close()
                except Exception:
                    pass
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})
        return jsonify({"ok": True, "results": results})

    @app.route("/api/project-management/sprint/create", methods=["POST"])
    def api_tm_sprint_create():
        import shutil, re as _re_s, json as _json_c
        import openpyxl as _xl_c
        body = request.get_json() or {}
        sprint_name       = str(body.get("sprint_name") or "").strip()
        sprint_start_date = str(body.get("sprint_start_date") or "").strip()
        sprint_end_date   = str(body.get("sprint_end_date") or "").strip()
        team_name         = str(body.get("team_name") or "").strip()
        if not sprint_name:
            return jsonify({"ok": False, "error": "sprint_name is required"})
        if not sprint_start_date:
            return jsonify({"ok": False, "error": "sprint_start_date is required"})
        if not sprint_end_date:
            return jsonify({"ok": False, "error": "sprint_end_date is required"})
        if not team_name:
            return jsonify({"ok": False, "error": "team_name is required"})
        if not SPRINT_TEMPLATE.exists():
            return jsonify({"ok": False, "error": f"Template not found: {SPRINT_TEMPLATE}"})
        # Look up team's board URL from Template.xlsx Teams tab (col A = name, col B = board_url)
        sprint_url = ""
        try:
            _wb_t = _xl_c.load_workbook(str(SPRINT_TEMPLATE), read_only=True, data_only=True)
            if "Teams" in _wb_t.sheetnames:
                for _tr in _wb_t["Teams"].iter_rows(min_row=1, values_only=True):
                    if _tr and _tr[0] and str(_tr[0]).strip() == team_name:
                        sprint_url = str(_tr[1]).strip() if len(_tr) > 1 and _tr[1] else ""
                        break
            _wb_t.close()
        except Exception:
            pass
        def _safe(s):
            return _re_s.sub(r'[\\/:*?"<>|]', '-', s)
        safe_end   = _safe(sprint_end_date)
        safe_team  = _safe(team_name)
        safe_name  = _safe(sprint_name)
        team_dir = SPRINT_DATA / "Sprints" / safe_team
        team_dir.mkdir(parents=True, exist_ok=True)
        dest = team_dir / f"{safe_team}_{safe_end}_{safe_name}.xlsx"
        if dest.exists():
            return jsonify({"ok": False, "error": f"Sprint already exists: {dest.name}"})
        try:
            shutil.copy2(str(SPRINT_TEMPLATE), str(dest))
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})
        # Save sidecar with sprint_url from template
        if sprint_url:
            (team_dir / f"{dest.stem}.json").write_text(_json_c.dumps({"sprint_url": sprint_url}))
        # Populate Sprint Board from JIRA board
        populate_msg = None
        if sprint_url:
            try:
                creds, cerr = _jira_creds()
                if cerr:
                    populate_msg = f"Board URL found but JIRA creds error: {cerr}"
                else:
                    issues, ferr = _fetch_board_issues(creds, sprint_url)
                    if ferr:
                        populate_msg = f"Board fetch failed: {ferr}"
                    elif issues:
                        wb_c = _xl_c.load_workbook(str(dest))
                        if "Sprint Board" in wb_c.sheetnames:
                            cnt = _apply_board_issues(wb_c["Sprint Board"], issues, creds["base_url"], creds)
                            wb_c.save(str(dest))
                            populate_msg = f"Populated {cnt} tickets from active sprint"
                        wb_c.close()
                    else:
                        populate_msg = "No active sprint found on board — sprint file created empty"
            except Exception as pe:
                populate_msg = f"Board populate error: {pe}"
        else:
            populate_msg = "Sprint created — no board URL in Template.xlsx Teams tab (column B)"
        return jsonify({"ok": True, "file": dest.name, "path": str(dest), "message": populate_msg})

    @app.route("/api/project-management/sprint/refresh-jira", methods=["POST"])
    def api_tm_sprint_refresh_jira():
        import re as _re2
        try:
            import requests as _req, urllib3 as _u3
            from requests.auth import HTTPBasicAuth as _BA
            _u3.disable_warnings(_u3.exceptions.InsecureRequestWarning)
        except ImportError:
            return jsonify({"ok": False, "error": "requests library not installed"})
        # Read JIRA credentials from secrets.xlsx Atlassian tab
        if not SECRETS_FILE.exists():
            return jsonify({"ok": False, "error": "secrets.xlsx not found"})
        import openpyxl as _xl_s
        _wb_s = _xl_s.load_workbook(str(SECRETS_FILE), data_only=True)
        _sec  = {}
        for _sname in ("Atlassian", "atlassian"):
            if _sname in _wb_s.sheetnames:
                for _row in _wb_s[_sname].iter_rows(min_row=2, values_only=True):
                    if _row and _row[0] and _row[1]:
                        _sec[str(_row[0]).strip()] = str(_row[1]).strip()
                break
        _wb_s.close()
        base_url  = _sec.get("jira_base_url", "").rstrip("/")
        email     = _sec.get("jira_email", "")
        api_token = _sec.get("jira_api_token", "")
        if not base_url or not email or not api_token:
            return jsonify({"ok": False, "error": "jira_base_url / jira_email / jira_api_token missing in secrets.xlsx Atlassian tab"})
        auth = _BA(email, api_token)
        body     = request.get_json() or {}
        filename = str(body.get("file") or "").strip()
        if not filename:
            return jsonify({"ok": False, "error": "file required"})
        target   = _sprint_team_path(filename)
        if not target.exists():
            return jsonify({"ok": False, "error": f"File not found: {filename}"})
        import openpyxl as _xl
        wb = _xl.load_workbook(str(target))
        _DATA_SHEETS = ["Sprint Board", "Adhoc Task", "PR Reviews"]
        updated, errors = 0, []
        for sname in _DATA_SHEETS:
            if sname not in wb.sheetnames: continue
            ws      = wb[sname]
            header  = [c.value for c in next(ws.iter_rows(min_row=1, max_row=1))]
            jira_ci    = next((i for i,h in enumerate(header) if h == "JIRA ID"),     None)
            story_ci   = next((i for i,h in enumerate(header) if h == "Story"),       None)
            type_ci    = next((i for i,h in enumerate(header) if h == "Type"),        None)
            stat_ci    = next((i for i,h in enumerate(header) if h == "Status"),      None)
            sp_ci      = next((i for i,h in enumerate(header) if h == "Story Point"), None)
            prs_ci     = next((i for i,h in enumerate(header) if h == "PRs"),         None)
            pr_stat_ci = next((i for i,h in enumerate(header) if h == "PR Status"),   None)
            if jira_ci is None: continue
            for row_idx, row in enumerate(ws.iter_rows(min_row=2, values_only=True)):
                raw = row[jira_ci] if jira_ci < len(row) else None
                if not raw or not str(raw).strip(): continue
                m = _re2.search(r'/browse/([A-Z]+-\d+)', str(raw), _re2.I) or _re2.match(r'^([A-Z]+-\d+)$', str(raw).strip(), _re2.I)
                if not m: continue
                ticket = m.group(1).upper()
                try:
                    resp = _req.get(f"{base_url}/rest/api/2/issue/{ticket}",
                                    params={"fields": "summary,status,issuetype,story_points,customfield_10045,customfield_10016,customfield_10028,customfield_10015"},
                                    auth=auth, headers={"Accept": "application/json"}, timeout=10, verify=False)
                    if resp.status_code == 200:
                        rj          = resp.json()
                        fields      = rj.get("fields", {})
                        summary     = fields.get("summary", "")
                        status      = fields.get("status", {}).get("name", "")
                        issue_type  = (fields.get("issuetype") or {}).get("name", "")
                        sp_val      = _sp_from_fields(fields)
                        er          = row_idx + 2  # excel row
                        if story_ci is not None and summary:
                            ws.cell(row=er, column=story_ci + 1).value = summary
                        if type_ci  is not None and issue_type:
                            ws.cell(row=er, column=type_ci  + 1).value = issue_type
                        if stat_ci  is not None and status:
                            ws.cell(row=er, column=stat_ci  + 1).value = status
                        if sp_ci    is not None:
                            ws.cell(row=er, column=sp_ci    + 1).value = sp_val
                        # Fetch PRs filtered by branch containing ticket key
                        issue_id_str = rj.get("id")
                        if issue_id_str and (prs_ci is not None or pr_stat_ci is not None):
                            pr_urls_list, pr_stat_list = _fetch_issue_prs(creds, issue_id_str, ticket)
                            if pr_urls_list:
                                if prs_ci     is not None: ws.cell(row=er, column=prs_ci+1).value     = "|".join(pr_urls_list)
                                if pr_stat_ci is not None: ws.cell(row=er, column=pr_stat_ci+1).value = "|".join(pr_stat_list)
                        updated += 1
                    else:
                        errors.append(f"{ticket}: HTTP {resp.status_code}")
                except Exception as ex:
                    errors.append(f"{ticket}: {ex}")
        wb.save(str(target))
        wb.close()
        return jsonify({"ok": True, "updated": updated, "errors": errors})

    @app.route("/api/project-management/sprint/rename", methods=["POST"])
    def api_tm_sprint_rename():
        import re as _re_r
        body = request.get_json() or {}
        filename = str(body.get("file") or "").strip()
        new_name = str(body.get("new_name") or "").strip()
        if not filename or not new_name:
            return jsonify({"ok": False, "error": "file and new_name required"})
        src = _sprint_team_path(filename)
        if not src.exists():
            return jsonify({"ok": False, "error": f"File not found: {filename}"})
        m = _re_r.match(r'^(.+)_(\d{4}-\d{2}-\d{2})_(.+)\.xlsx$', filename)
        if not m:
            return jsonify({"ok": False, "error": "Unexpected filename format"})
        team, date = m.group(1), m.group(2)
        safe = _re_r.sub(r'[\\/:*?"<>|]', '-', new_name)
        dest = src.parent / f"{team}_{date}_{safe}.xlsx"
        if dest.exists() and dest != src:
            return jsonify({"ok": False, "error": f"Name already exists: {dest.name}"})
        try:
            src.rename(dest)
            sc_src = src.parent / f"{src.stem}.json"
            if sc_src.exists():
                sc_src.rename(src.parent / f"{dest.stem}.json")
            return jsonify({"ok": True, "new_file": dest.name})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/project-management/sprint/row/add", methods=["POST"])
    def api_tm_sprint_row_add():
        import openpyxl as _xl
        body = request.get_json() or {}
        filename   = str(body.get("file") or "").strip()
        sheet      = str(body.get("sheet") or "").strip()
        values     = body.get("values") or []
        hyperlinks = body.get("hyperlinks") or {}
        if not filename or not sheet:
            return jsonify({"ok": False, "error": "file and sheet required"})
        target = _sprint_team_path(filename)
        if not target.exists():
            return jsonify({"ok": False, "error": f"File not found: {filename}"})
        try:
            wb = _xl.load_workbook(str(target))
            if sheet not in wb.sheetnames:
                return jsonify({"ok": False, "error": f"Sheet not found: {sheet}"})
            ws = wb[sheet]
            ws.append([str(v) if v else None for v in values])
            last_row = ws.max_row
            for col_str, url in hyperlinks.items():
                ws.cell(row=last_row, column=int(col_str) + 1).hyperlink = str(url)
            wb.save(str(target)); wb.close()
            return jsonify({"ok": True})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

