    @app.route("/api/project-management/sprint/data", methods=["GET"])
    def api_tm_sprint_data():
        import openpyxl as _xl, json as _json_d
        filename = request.args.get("file", "").strip()
        if not filename:
            return jsonify({"ok": False, "error": "file param required"})
        target = _sprint_team_path(filename)
        if not target.exists():
            return jsonify({"ok": False, "error": f"File not found: {filename}"})
        try:
            wb = _xl.load_workbook(str(target), read_only=True, data_only=True)
            DATA_SHEETS = ["Sprint Board", "Adhoc Task", "PR Reviews"]
            sheets = {}
            for sname in DATA_SHEETS:
                if sname not in wb.sheetnames:
                    sheets[sname] = {"columns": [], "rows": []}
                    continue
                ws = wb[sname]
                all_rows = list(ws.iter_rows(values_only=True))
                if not all_rows:
                    sheets[sname] = {"columns": [], "rows": []}
                    continue
                columns = [str(c) if c is not None else "" for c in all_rows[0]]
                rows = []
                for row in all_rows[1:]:
                    if any(c is not None and str(c).strip() for c in row):
                        rows.append([str(c) if c is not None else "" for c in row])
                sheets[sname] = {"columns": columns, "rows": rows}
            # Read QA names from the QA sheet (same open workbook)
            qa_names = []
            if "QA" in wb.sheetnames:
                for _qr in wb["QA"].iter_rows(values_only=True):
                    if _qr and _qr[0]:
                        _qn = str(_qr[0]).strip()
                        if _qn:
                            qa_names.append(_qn)
            # Read Sprint Log sheet
            LOG_SHEET = "Sprint Log"
            _LOG_COLS  = ["S.No", "Date", "Notes", "Status"]
            _needs_log_init    = LOG_SHEET not in wb.sheetnames
            _needs_log_migrate = False
            if not _needs_log_init:
                _ws_log = wb[LOG_SHEET]
                _all_log = list(_ws_log.iter_rows(values_only=True))
                if _all_log:
                    _log_cols = [str(c) if c is not None else "" for c in _all_log[0]]
                    _needs_log_migrate = "Status" not in _log_cols
                    _log_rows = []
                    for _lr in _all_log[1:]:
                        if any(c is not None for c in _lr):
                            _row = [str(c) if c is not None else "" for c in _lr]
                            if _needs_log_migrate:
                                _row.append("Pending")
                            _log_rows.append(_row)
                    if _needs_log_migrate:
                        _log_cols = _LOG_COLS
                else:
                    _log_cols, _log_rows = _LOG_COLS, []
                sheets[LOG_SHEET] = {"columns": _log_cols, "rows": _log_rows}
            else:
                sheets[LOG_SHEET] = {"columns": _LOG_COLS, "rows": []}
            wb.close()
            # Ensure "Issue Type" (after Story) exists on Sprint Board and Adhoc Task
            for _it_sheet in ("Sprint Board", "Adhoc Task"):
                _it_d = sheets.get(_it_sheet, {})
                _it_cols = _it_d.get("columns", [])
                if not _it_cols or "Issue Type" in _it_cols or "Story" not in _it_cols:
                    continue
                try:
                    _wb_it = _xl.load_workbook(str(target))
                    if _it_sheet in _wb_it.sheetnames and _ensure_issue_type_col(_wb_it[_it_sheet]):
                        _wb_it.save(str(target))
                    _wb_it.close()
                    _at = _it_cols.index("Story") + 1
                    _ti = _it_cols.index("Type") if "Type" in _it_cols else -1
                    for _rw_it in _it_d.get("rows", []):
                        _rw_it.insert(_at, _rw_it[_ti] if 0 <= _ti < len(_rw_it) else "")
                    _it_cols.insert(_at, "Issue Type")
                except Exception:
                    pass
            # Ensure the DevDays / QADays / carry-over helper columns exist on Sprint Board and Adhoc Task
            for _en_sheet, _en_need in (("Sprint Board", ["DevDays", "InDevSince", "QADays", "InQASince", "Carried Over", "Sprints", "Origin Sprint"]),
                                        ("Adhoc Task",   ["DevDays", "QADays", "InQASince", "Carried Over", "Sprints", "Origin Sprint"])):
                _en_cols = sheets.get(_en_sheet, {}).get("columns", [])
                if not _en_cols or all(c in _en_cols for c in _en_need):
                    continue
                try:
                    _wb_en = _xl.load_workbook(str(target))
                    if _en_sheet in _wb_en.sheetnames:
                        _ws_en  = _wb_en[_en_sheet]
                        _hdr_en = [c.value for c in next(_ws_en.iter_rows(min_row=1, max_row=1))]
                        _changed = False
                        for _nm in _en_need:
                            if _nm not in _hdr_en:
                                _ws_en.cell(row=1, column=len(_hdr_en) + 1).value = _nm
                                _hdr_en.append(_nm)
                                if _nm not in _en_cols:
                                    _en_cols.append(_nm)
                                _changed = True
                        if _changed:
                            _wb_en.save(str(target))
                    _wb_en.close()
                    sheets[_en_sheet]["columns"] = _en_cols
                except Exception:
                    pass
            # Create or migrate Sprint Log sheet as needed
            if _needs_log_init or _needs_log_migrate:
                try:
                    _wb2 = _xl.load_workbook(str(target))
                    if _needs_log_init:
                        _ws2 = _wb2.create_sheet(LOG_SHEET)
                        _ws2.append(_LOG_COLS)
                    else:
                        _ws2 = _wb2[LOG_SHEET]
                        _ws2.cell(row=1, column=4).value = "Status"
                        for _ri in range(2, _ws2.max_row + 1):
                            if _ws2.cell(_ri, 4).value is None:
                                _ws2.cell(_ri, 4).value = "Pending"
                    _wb2.save(str(target))
                    _wb2.close()
                except Exception:
                    pass
            # Resolve board URL: sidecar overrides, else look up team from Template.xlsx
            import re as _re_d
            sprint_url = ""
            sidecar = target.parent / f"{target.stem}.json"
            if sidecar.exists():
                try: sprint_url = _json_d.loads(sidecar.read_text()).get("sprint_url", "")
                except: pass
            if not sprint_url and SPRINT_TEMPLATE.exists():
                _m = _re_d.match(r'^(.+?)_\d{4}-\d{2}-\d{2}_', target.stem)
                _team = _m.group(1) if _m else ""
                if _team:
                    try:
                        _wbt = _xl.load_workbook(str(SPRINT_TEMPLATE), read_only=True, data_only=True)
                        if "Teams" in _wbt.sheetnames:
                            for _tr in _wbt["Teams"].iter_rows(min_row=1, values_only=True):
                                if _tr and _tr[0] and str(_tr[0]).strip() == _team:
                                    sprint_url = str(_tr[1]).strip() if len(_tr) > 1 and _tr[1] else ""
                                    break
                        _wbt.close()
                    except Exception:
                        pass
            return jsonify({"ok": True, "sheets": sheets, "sprint_url": sprint_url, "qa_names": qa_names})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/project-management/sprint/open", methods=["POST"])
    def api_tm_sprint_open():
        import subprocess as _sp
        body = request.get_json() or {}
        filename = str(body.get("file") or "").strip()
        if not filename:
            return jsonify({"ok": False, "error": "file is required"})
        target = _sprint_team_path(filename)
        if not target.exists():
            return jsonify({"ok": False, "error": f"File not found: {filename}"})
        try:
            _sp.Popen(["start", "", str(target)], shell=True)
            return jsonify({"ok": True})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/project-management/sprint/summary-data", methods=["GET"])
    def api_tm_sprint_summary_data():
        import openpyxl as _xl_sd
        import openpyxl.styles as _st_sd
        from openpyxl.chart import BarChart as _BC_sd, Reference as _Ref_sd
        from datetime import datetime as _dt_sd
        filename = request.args.get("file", "").strip()
        if not filename:
            return jsonify({"ok": False, "error": "file required"})
        src = _sprint_team_path(filename)
        if not src.exists():
            return jsonify({"ok": False, "error": f"File not found: {filename}"})
        try:
            DONE_STATUS = {"done", "closed", "released", "completed", "deployed", "merged", "bug filed"}
            wb = _xl_sd.load_workbook(str(src))
            # Count Adhoc Task rows
            adhoc_count = 0
            if "Adhoc Task" in wb.sheetnames:
                for _ar in wb["Adhoc Task"].iter_rows(min_row=2, values_only=True):
                    if _ar and any(v for v in _ar):
                        adhoc_count += 1
            all_rows_sd = []
            for _sh in ("Sprint Board", "Adhoc Task"):
                if _sh not in wb.sheetnames:
                    continue
                _data_ws = wb[_sh]
                _all = list(_data_ws.iter_rows(values_only=True))
                if not _all:
                    continue
                _hdrs   = [str(h or "").strip() for h in _all[0]]
                _sp_c   = next((i for i, h in enumerate(_hdrs) if h == "Story Point"), -1)
                _st_c   = next((i for i, h in enumerate(_hdrs) if h == "Status"),      -1)
                _dev_c  = next((i for i, h in enumerate(_hdrs) if h == "Developer"),   -1)
                _key_c  = next((i for i, h in enumerate(_hdrs) if h == "JIRA ID"),     -1)
                _sum_c  = next((i for i, h in enumerate(_hdrs) if h == "Summary"),     -1)
                _type_c = next((i for i, h in enumerate(_hdrs) if h == "Type"),        -1)
                for _r in _all[1:]:
                    if not any(v for v in _r):
                        continue
                    def _gv(ci, _r=_r):
                        return _r[ci] if 0 <= ci < len(_r) else None
                    _sp_raw = _gv(_sp_c)
                    try:
                        _sp_val = float(_sp_raw) if _sp_raw is not None and str(_sp_raw).strip() else 0.0
                    except Exception:
                        _sp_val = 0.0
                    all_rows_sd.append({
                        "sp":     _sp_val,
                        "status": str(_gv(_st_c)  or "").strip(),
                        "dev":    str(_gv(_dev_c) or "").strip(),
                        "key":    str(_gv(_key_c) or "").strip(),
                        "summary":str(_gv(_sum_c) or "").strip(),
                        "type":   str(_gv(_type_c)or "").strip(),
                        "source": _sh,
                    })

            total_s  = len(all_rows_sd)
            total_sp = sum(r["sp"] for r in all_rows_sd)
            done_rows= [r for r in all_rows_sd if r["status"].lower() in DONE_STATUS]
            done_s   = len(done_rows)
            done_sp  = sum(r["sp"] for r in done_rows)
            _pct     = lambda n, d: f"{n/d*100:.1f}%" if d else "0%"

            status_map = {}
            for _r in all_rows_sd:
                _k = _r["status"] or "(No Status)"
                if _k not in status_map:
                    status_map[_k] = {"count": 0, "sp": 0.0}
                status_map[_k]["count"] += 1
                status_map[_k]["sp"]    += _r["sp"]

            dev_map = {}
            for _r in all_rows_sd:
                _k = _r["dev"] or "(Unassigned)"
                if _k not in dev_map:
                    dev_map[_k] = {"total": 0, "done": 0, "sp_total": 0.0, "sp_done": 0.0}
                dev_map[_k]["total"]    += 1
                dev_map[_k]["sp_total"] += _r["sp"]
                if _r["status"].lower() in DONE_STATUS:
                    dev_map[_k]["done"]    += 1
                    dev_map[_k]["sp_done"] += _r["sp"]

            _n = lambda v: int(v) if v == int(v) else v
            adhoc_sp = sum(r["sp"] for r in all_rows_sd if r["source"] == "Adhoc Task")
            overview = [
                {"metric": "Total Stories",               "value": total_s},
                {"metric": "Total Story Points",          "value": _n(total_sp)},
                {"metric": "Completed Stories",           "value": done_s},
                {"metric": "Completed Story Points",      "value": _n(done_sp)},
                {"metric": "Adhoc Stories Added",         "value": adhoc_count},
                {"metric": "Adhoc Story Points Added",    "value": _n(adhoc_sp)},
            ]
            # Row groups for the Overview table; each carries every Sprint Board column (Adhoc rows mapped by name)
            _sbws = wb["Sprint Board"] if "Sprint Board" in wb.sheetnames else None
            _grp_head = [str(c.value).strip() for c in next(_sbws.iter_rows(min_row=1, max_row=1)) if c.value] if _sbws is not None else []
            _grp_all = []
            for _sh in ("Sprint Board", "Adhoc Task"):
                if _sh not in wb.sheetnames:
                    continue
                _all2 = list(wb[_sh].iter_rows(values_only=True))
                if not _all2:
                    continue
                _h2 = [str(h or "").strip() for h in _all2[0]]
                _st2 = _h2.index("Status") if "Status" in _h2 else -1
                for _r2 in _all2[1:]:
                    if not any(v for v in _r2):
                        continue
                    _row2 = [("" if (_h in _h2 and _h2.index(_h) < len(_r2) and _r2[_h2.index(_h)] is None) else
                              (str(_r2[_h2.index(_h)]) if _h in _h2 and _h2.index(_h) < len(_r2) else "")) for _h in _grp_head]
                    _done2 = _st2 >= 0 and _st2 < len(_r2) and str(_r2[_st2] or "").strip().lower() in DONE_STATUS
                    _grp_all.append((_row2, _done2, _sh == "Adhoc Task"))
            groups = {
                "total":     {"head": _grp_head, "rows": [r for r, d, a in _grp_all]},
                "completed": {"head": _grp_head, "rows": [r for r, d, a in _grp_all if d]},
                "adhoc":     {"head": _grp_head, "rows": [r for r, d, a in _grp_all if a]},
            }
            overview_rows = [
                {"key": "total",     "label": "Total",     "stories": total_s, "sp": _n(total_sp)},
                {"key": "completed", "label": "Completed", "stories": done_s,  "sp": _n(done_sp)},
                {"key": "adhoc",     "label": "Adhoc Added", "stories": adhoc_count, "sp": _n(adhoc_sp)},
            ]

            status_breakdown = [
                {"status": st, "count": v["count"],
                 "sp": int(v["sp"]) if v["sp"] == int(v["sp"]) else v["sp"]}
                for st, v in sorted(status_map.items())
            ]

            dev_breakdown = [
                {"dev": d, "total": v["total"], "done": v["done"],
                 "sp_total": int(v["sp_total"]) if v["sp_total"] == int(v["sp_total"]) else v["sp_total"],
                 "sp_done":  int(v["sp_done"])  if v["sp_done"]  == int(v["sp_done"])  else v["sp_done"]}
                for d, v in sorted(dev_map.items())
            ]

            # ── Write / refresh Summary sheet ──────────────────────────────────
            if "Summary" in wb.sheetnames:
                del wb["Summary"]
            ws_sum = wb.create_sheet("Summary", 0)
            T_FONT = _st_sd.Font(name="Calibri", size=14, bold=True, color="1A237E")
            H_FONT = _st_sd.Font(name="Calibri", size=10, bold=True, color="FFFFFF")
            H_FILL = _st_sd.PatternFill("solid", fgColor="1565C0")
            L_FONT = _st_sd.Font(name="Calibri", size=10, bold=True)
            V_FONT = _st_sd.Font(name="Calibri", size=10)
            A_FILL = _st_sd.PatternFill("solid", fgColor="E3F2FD")
            _bs    = _st_sd.Side(border_style="thin", color="BBDEFB")
            T_BRD  = _st_sd.Border(left=_bs, right=_bs, top=_bs, bottom=_bs)
            C_ALN  = _st_sd.Alignment(horizontal="center")
            ws_sum.column_dimensions["A"].width = 30
            ws_sum.column_dimensions["B"].width = 18
            ws_sum.column_dimensions["C"].width = 18
            _rw = 1
            def _sc(r, c, val, font=None, fill=None, border=None, align=None):
                cell = ws_sum.cell(row=r, column=c)
                cell.value = val
                if font:  cell.font  = font
                if fill:  cell.fill  = fill
                if border:cell.border= border
                if align: cell.alignment = align
            sprint_label = filename[:-5] if filename.endswith(".xlsx") else filename
            _sc(_rw, 1, "Sprint Summary", font=T_FONT); _rw += 1
            _sc(_rw, 1, f"Sprint: {sprint_label}",
                font=_st_sd.Font(name="Calibri", size=11, italic=True, color="555555")); _rw += 1
            _sc(_rw, 1, f"Generated: {_dt_sd.today().strftime('%Y-%m-%d')}",
                font=_st_sd.Font(name="Calibri", size=10, color="888888")); _rw += 2
            _sc(_rw, 1, "Overview",
                font=_st_sd.Font(name="Calibri", size=12, bold=True, color="1565C0")); _rw += 1
            for c, h in enumerate(["Metric", "Value"], 1):
                _sc(_rw, c, h, font=H_FONT, fill=H_FILL, border=T_BRD, align=C_ALN)
            _rw += 1
            for i, m in enumerate(overview):
                _f = A_FILL if i % 2 else None
                _sc(_rw, 1, m["metric"], font=L_FONT, fill=_f, border=T_BRD)
                _sc(_rw, 2, m["value"],  font=V_FONT, fill=_f, border=T_BRD, align=C_ALN)
                _rw += 1
            _rw += 1
            _sc(_rw, 1, "Status Breakdown",
                font=_st_sd.Font(name="Calibri", size=12, bold=True, color="1565C0")); _rw += 1
            for c, h in enumerate(["Status", "Stories", "Story Points"], 1):
                _sc(_rw, c, h, font=H_FONT, fill=H_FILL, border=T_BRD, align=C_ALN)
            _rw += 1
            _chart_hdr, _chart_start = _rw - 1, _rw
            for i, sb in enumerate(status_breakdown):
                _f = A_FILL if i % 2 else None
                _sc(_rw, 1, sb["status"], font=V_FONT, fill=_f, border=T_BRD)
                _sc(_rw, 2, sb["count"],  font=V_FONT, fill=_f, border=T_BRD, align=C_ALN)
                _sc(_rw, 3, sb["sp"],     font=V_FONT, fill=_f, border=T_BRD, align=C_ALN)
                _rw += 1
            _chart_end = _rw - 1
            if _chart_end >= _chart_start:
                _chart = _BC_sd(); _chart.type = "col"; _chart.title = "Stories by Status"
                _chart.y_axis.title = "Count"; _chart.x_axis.title = "Status"
                _chart.style = 10; _chart.width = 20; _chart.height = 14; _chart.grouping = "clustered"
                _d1 = _Ref_sd(ws_sum, min_col=2, max_col=2, min_row=_chart_hdr, max_row=_chart_end)
                _d2 = _Ref_sd(ws_sum, min_col=3, max_col=3, min_row=_chart_hdr, max_row=_chart_end)
                _cats = _Ref_sd(ws_sum, min_col=1, min_row=_chart_start, max_row=_chart_end)
                _chart.add_data(_d1, titles_from_data=True); _chart.add_data(_d2, titles_from_data=True)
                _chart.set_categories(_cats); ws_sum.add_chart(_chart, "E3")
            _rw += 2
            _sc(_rw, 1, "Developer Breakdown",
                font=_st_sd.Font(name="Calibri", size=12, bold=True, color="1565C0")); _rw += 1
            for c, h in enumerate(["Developer", "Total", "Done", "SP Total", "SP Done"], 1):
                _sc(_rw, c, h, font=H_FONT, fill=H_FILL, border=T_BRD, align=C_ALN)
            _rw += 1
            for i, db in enumerate(dev_breakdown):
                _f = A_FILL if i % 2 else None
                for ci, val in enumerate([db["dev"], db["total"], db["done"], db["sp_total"], db["sp_done"]], 1):
                    _sc(_rw, ci, val, font=V_FONT if ci > 1 else L_FONT, fill=_f, border=T_BRD,
                        align=C_ALN if ci > 1 else None)
                _rw += 1
            wb.save(str(src))
            wb.close()

            return jsonify({
                "ok": True,
                "overview": overview,
                "overview_rows": overview_rows,
                "groups": groups,
                "status_breakdown": status_breakdown,
                "sprint_label": sprint_label,
            })
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/project-management/sprint/export-xlsx", methods=["POST"])
    def api_tm_sprint_export_xlsx():
        import openpyxl as _xl_ex
        from openpyxl.styles import Font as _Fnt, PatternFill as _Fill
        from flask import send_file as _sf_ex
        body = request.get_json() or {}
        head = body.get("head") or []
        rows = body.get("rows") or []
        urls = body.get("urls") or []
        jp   = body.get("jp", -1)
        wb = _xl_ex.Workbook()
        ws = wb.active
        ws.title = str(body.get("sheet") or "Stories")[:31]
        ws.append(head)
        for c in ws[1]:
            c.font = _Fnt(bold=True, color="FFFFFF")
            c.fill = _Fill("solid", fgColor="4472C4")
        for ri, r in enumerate(rows):
            ws.append(r)
            u = urls[ri] if ri < len(urls) else ""
            if u and isinstance(jp, int) and 0 <= jp < len(r):
                cell = ws.cell(row=ri + 2, column=jp + 1)
                cell.hyperlink = u
                cell.font = _Fnt(color="0563C1", underline="single")
        for ci, h in enumerate(head, 1):
            width = max([len(str(h))] + [len(str(r[ci - 1])) for r in rows if ci - 1 < len(r)])
            ws.column_dimensions[ws.cell(row=1, column=ci).column_letter].width = min(max(width + 2, 10), 60)
        ws.freeze_panes = "A2"
        buf = io.BytesIO()
        wb.save(buf)
        buf.seek(0)
        return _sf_ex(buf, as_attachment=True, download_name=str(body.get("name") or "sprint") + ".xlsx",
                      mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")

    # ── Sprint > PR Reviews: GitHub PRs on which I am (or was) a reviewer, with the days I have been a reviewer ──
    _pr_rev_cache = {}

    def _rv_label(reviews, me):
        """Review status from the PR's reviews. A comment never cancels an approval; approvals are split into mine / others'."""
        eff = {}
        for x in sorted([x for x in reviews if isinstance(x, dict)], key=lambda x: x.get("submitted_at") or ""):
            u, s = (x.get("user") or {}).get("login", ""), (x.get("state") or "").upper()
            if not u or s == "PENDING": continue
            if s == "COMMENTED": eff.setdefault(u, s)
            else: eff[u] = s
        mine = eff.get(me, "")
        others = any(s == "APPROVED" for u, s in eff.items() if u != me)
        if mine == "APPROVED": return "Approved (By me and others)" if others else "Approved (By me)"
        base = {"CHANGES_REQUESTED": "Changes Requested", "COMMENTED": "Commented", "DISMISSED": "Dismissed"}.get(mine, "")
        if others: return (base + ", " if base else "") + "Approved (By others)"
        return base or "Review"

    @app.route("/api/project-management/sprint/pr-reviews", methods=["GET"])
    def api_sprint_pr_reviews():
        import requests as _rq, re as _r, datetime as _dt, urllib3 as _u3
        from concurrent.futures import ThreadPoolExecutor
        _u3.disable_warnings()
        tok = _scm_github_token()
        if not tok: return jsonify({"ok": False, "error": "github_token is missing in secrets.xlsx (GitHub sheet)"})
        H = {"Authorization": "Bearer " + tok, "Accept": "application/vnd.github+json"}
        since = request.args.get("since") or (_dt.date.today() - _dt.timedelta(days=30)).isoformat()
        if not _r.fullmatch(r"\d{4}-\d{2}-\d{2}", since): return jsonify({"ok": False, "error": "since must be YYYY-MM-DD"})
        def get(url, **kw): return _rq.get(url, headers=H, timeout=30, verify=False, **kw)
        try:
            u = get("https://api.github.com/user")
            if u.status_code != 200: return jsonify({"ok": False, "error": "GitHub rejected the token (HTTP %d)" % u.status_code})
            me = u.json().get("login", "")
            def search(q):
                out = []
                for page in range(1, 6):
                    r = get("https://api.github.com/search/issues", params={"q": q, "per_page": 100, "page": page})
                    if r.status_code != 200: raise RuntimeError("GitHub search failed (HTTP %d): %s" % (r.status_code, r.text[:160]))
                    items = r.json().get("items", [])
                    out += items
                    if len(items) < 100: break
                return out
            found = {}
            for q in ("is:pr is:open review-requested:%s" % me, "is:pr is:open reviewed-by:%s" % me,
                      "is:pr is:closed review-requested:%s closed:>=%s" % (me, since), "is:pr is:closed reviewed-by:%s closed:>=%s" % (me, since)):
                for it in search(q): found[it["html_url"]] = it
            pat = _r.compile(r"(?<![A-Za-z0-9])([A-Z][A-Z0-9]+-\d+)(?!\d)")
            def build(it):
                key = it["html_url"] + "|v3"                                    # v3: "Not Reviewed" renamed "Review"
                hit = _pr_rev_cache.get(key)
                repo_api = it["repository_url"]
                num = it["number"]
                def reviews_label():
                    rv_list = []
                    try:
                        url = "%s/pulls/%d/reviews" % (repo_api, num)
                        for _ in range(5):
                            r = get(url, params={"per_page": 100}) if "?" not in url else get(url)
                            if r.status_code != 200: break
                            rv_list += r.json()
                            url = r.links.get("next", {}).get("url")
                            if not url: break
                    except Exception:
                        pass
                    return _rv_label(rv_list, me)
                if hit and hit[0] == it.get("updated_at"):
                    # the rest of the row is cached, but the review status is always re-read (e.g. Changes Requested -> Approved)
                    return dict(hit[1], review_status=reviews_label())
                start = None
                try:
                    url = "%s/issues/%d/timeline" % (repo_api, num)
                    reviewed = None
                    for _ in range(5):
                        r = get(url, params={"per_page": 100}) if "?" not in url else get(url)
                        if r.status_code != 200: break
                        for ev in r.json():
                            if ev.get("event") == "review_requested" and (ev.get("requested_reviewer") or {}).get("login") == me:
                                t = ev.get("created_at")
                                if t and (start is None or t < start): start = t
                            if ev.get("event") == "reviewed" and (ev.get("user") or {}).get("login") == me:
                                t = ev.get("submitted_at")
                                if t and (reviewed is None or t < reviewed): reviewed = t
                        nxt = r.links.get("next", {}).get("url")
                        if not nxt: break
                        url = nxt
                    start = start or reviewed or it.get("created_at")
                except Exception:
                    start = it.get("created_at")
                rv_state = reviews_label()
                m = pat.search(it.get("title", ""))
                if not m:                                                       # no ticket in the title: look at the branch name
                    try:
                        br = (get((it.get("pull_request") or {}).get("url", "")).json().get("head") or {}).get("ref", "")
                        m = pat.search(br)
                    except Exception:
                        m = None
                pr = it.get("pull_request") or {}
                merged = pr.get("merged_at")
                info = {"jira_id": m.group(1) if m else "", "pr": it["html_url"], "pr_label": "%s#%d" % (repo_api.rsplit("/", 1)[-1], num),
                        "title": it.get("title", ""), "repository": "/".join(repo_api.split("/")[-2:]), "author": (it.get("user") or {}).get("login", ""),
                        "state": "open" if it.get("state") == "open" else ("merged" if merged else "closed"),
                        "review_status": rv_state,
                        "requested_at": start, "end_at": merged or it.get("closed_at") if it.get("state") != "open" else None}
                _pr_rev_cache[key] = (it.get("updated_at"), info)
                return info
            with ThreadPoolExecutor(max_workers=8) as ex:
                rows = list(ex.map(build, list(found.values())[:250]))
        except Exception as e:
            return jsonify({"ok": False, "error": "%s: %s" % (type(e).__name__, e)})
        now = _dt.datetime.now(_dt.timezone.utc)
        def day(t): return _dt.datetime.fromisoformat(t.replace("Z", "+00:00")) if t else None
        for r in rows:
            s, e = day(r["requested_at"]), (day(r["end_at"]) if r["end_at"] else now)
            r["review_days"] = max(0, (e.date() - s.date()).days) if s and e else 0
        opn = sorted([r for r in rows if r["state"] == "open"], key=lambda r: (-r["review_days"], r["pr"]))
        cls = sorted([r for r in rows if r["state"] != "open"], key=lambda r: r["end_at"] or "", reverse=True)
        return jsonify({"ok": True, "me": me, "since": since, "open": opn, "closed": cls})

    @app.route("/api/project-management/sprint/pr-reviews/adhoc", methods=["GET"])
    def api_sprint_pr_reviews_adhoc():
        import requests as _rq, re as _r, datetime as _dt, urllib3 as _u3
        _u3.disable_warnings()
        m = _r.match(r"^\s*https?://github\.com/([\w.-]+)/([\w.-]+)/pull/(\d+)", request.args.get("url") or "")
        if not m: return jsonify({"ok": False, "error": "Enter a GitHub PR URL like https://github.com/org/repo/pull/123"})
        tok = _scm_github_token()
        if not tok: return jsonify({"ok": False, "error": "github_token is missing in secrets.xlsx (GitHub sheet)"})
        H = {"Authorization": "Bearer " + tok, "Accept": "application/vnd.github+json"}
        owner, repo, num = m.group(1), m.group(2), int(m.group(3))
        try:
            r = _rq.get("https://api.github.com/repos/%s/%s/pulls/%d" % (owner, repo, num), headers=H, timeout=30, verify=False)
            if r.status_code != 200: return jsonify({"ok": False, "error": "GitHub returned HTTP %d for this PR" % r.status_code})
            p = r.json()
            me = (_rq.get("https://api.github.com/user", headers=H, timeout=30, verify=False).json() or {}).get("login", "")
            rvs = _rq.get("https://api.github.com/repos/%s/%s/pulls/%d/reviews" % (owner, repo, num), params={"per_page": 100},
                          headers=H, timeout=30, verify=False).json()
            rv_state = _rv_label(rvs if isinstance(rvs, list) else [], me)
        except Exception as e:
            return jsonify({"ok": False, "error": "%s: %s" % (type(e).__name__, e)})
        pat = _r.compile(r"(?<![A-Za-z0-9])([A-Z][A-Z0-9]+-\d+)(?!\d)")
        jm = pat.search(p.get("title", "")) or pat.search((p.get("head") or {}).get("ref", "")) or pat.search(p.get("body") or "")
        merged = p.get("merged_at")
        opened = p.get("state") == "open"
        start = p.get("created_at")
        end = None if opened else (merged or p.get("closed_at"))
        now = _dt.datetime.now(_dt.timezone.utc)
        def day(t): return _dt.datetime.fromisoformat(t.replace("Z", "+00:00")) if t else None
        s, e = day(start), (day(end) if end else now)
        return jsonify({"ok": True, "row": {
            "jira_id": jm.group(1) if jm else "", "pr": p.get("html_url", ""), "pr_label": "%s#%d" % (repo, num),
            "title": p.get("title", ""), "repository": "%s/%s" % (owner, repo), "author": (p.get("user") or {}).get("login", ""),
            "state": "open" if opened else ("merged" if merged else "closed"), "review_status": rv_state, "requested_at": start, "end_at": end,
            "review_days": max(0, (e.date() - s.date()).days) if s and e else 0}})

    @app.route("/api/project-management/sprint/pr-reviews/export", methods=["POST"])
    def api_sprint_pr_reviews_export():
        import openpyxl as _xl_ex
        from openpyxl.styles import Font as _Fnt, PatternFill as _Fill
        from flask import send_file as _sf_ex
        body = request.get_json() or {}
        wb = _xl_ex.Workbook()
        ws = wb.active
        ws.title = str(body.get("sheet") or "PR Reviews")[:31]
        widths = {}
        row = 1
        for sec in body.get("sections") or []:
            ws.cell(row=row, column=1, value="%s (%d)" % (sec.get("title", ""), len(sec.get("rows") or []))).font = _Fnt(bold=True, size=12)
            row += 1
            head = sec.get("head") or []
            for ci, h in enumerate(head, 1):
                c = ws.cell(row=row, column=ci, value=h)
                c.font = _Fnt(bold=True, color="FFFFFF")
                c.fill = _Fill("solid", fgColor="4472C4")
                widths[ci] = max(widths.get(ci, 8), len(str(h)))
            row += 1
            for ri, r in enumerate(sec.get("rows") or []):
                links = (sec.get("links") or [])[ri] if ri < len(sec.get("links") or []) else {}
                for ci, v in enumerate(r, 1):
                    c = ws.cell(row=row, column=ci, value=v)
                    widths[ci] = max(widths.get(ci, 8), min(len(str(v)), 60))
                    u = links.get(str(ci - 1)) if isinstance(links, dict) else None
                    if u:
                        c.hyperlink = u
                        c.font = _Fnt(color="0563C1", underline="single")
                row += 1
            row += 1
        for ci, w in widths.items():
            ws.column_dimensions[ws.cell(row=1, column=ci).column_letter].width = min(w + 2, 62)
        buf = io.BytesIO()
        wb.save(buf)
        buf.seek(0)
        return _sf_ex(buf, as_attachment=True, download_name=str(body.get("name") or "PR_Reviews") + ".xlsx",
                      mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")

    @app.route("/api/project-management/sprint/complete", methods=["POST"])
    def api_tm_sprint_complete():
        import shutil as _shutil_sc
        import openpyxl as _xl_sc
        import openpyxl.styles as _st_sc
        from openpyxl.chart import BarChart as _BarChart, Reference as _Ref
        from datetime import datetime as _dt_sc
        body = request.get_json() or {}
        filename = str(body.get("file") or "").strip()
        if not filename:
            return jsonify({"ok": False, "error": "file required"})
        src = _sprint_team_path(filename)
        if not src.exists():
            return jsonify({"ok": False, "error": f"File not found: {filename}"})
        try:
            # ── Generate Summary sheet ─────────────────────────────────────────
            DONE_STATUS = {"done", "closed", "released", "completed", "deployed", "merged", "bug filed"}
            wb = _xl_sc.load_workbook(str(src))
            if "Summary" in wb.sheetnames:
                del wb["Summary"]
            ws = wb.create_sheet("Summary", 0)

            # Count Adhoc Task rows
            adhoc_count = 0
            if "Adhoc Task" in wb.sheetnames:
                for _ar in wb["Adhoc Task"].iter_rows(min_row=2, values_only=True):
                    if _ar and any(v for v in _ar):
                        adhoc_count += 1

            # Collect data from Sprint Board + Adhoc Task
            all_rows_sc = []
            for _sh in ("Sprint Board", "Adhoc Task"):
                if _sh not in wb.sheetnames:
                    continue
                _data_ws = wb[_sh]
                _all = list(_data_ws.iter_rows(values_only=True))
                if not _all:
                    continue
                _hdrs = [str(h or "").strip() for h in _all[0]]
                _sp_c   = next((i for i, h in enumerate(_hdrs) if h == "Story Point"), -1)
                _st_c   = next((i for i, h in enumerate(_hdrs) if h == "Status"),      -1)
                _dev_c  = next((i for i, h in enumerate(_hdrs) if h == "Developer"),   -1)
                _type_c = next((i for i, h in enumerate(_hdrs) if h == "Type"),        -1)
                for _r in _all[1:]:
                    if not any(v for v in _r):
                        continue
                    def _gv(ci):
                        return _r[ci] if ci >= 0 and ci < len(_r) else None
                    _sp_raw = _gv(_sp_c)
                    try:
                        _sp_val = float(_sp_raw) if _sp_raw is not None and str(_sp_raw).strip() else 0.0
                    except Exception:
                        _sp_val = 0.0
                    all_rows_sc.append({
                        "sp":  _sp_val,
                        "status": str(_gv(_st_c) or "").strip(),
                        "dev":    str(_gv(_dev_c) or "").strip(),
                        "type":   str(_gv(_type_c) or "").strip(),
                    })

            total_s    = len(all_rows_sc)
            total_sp   = sum(r["sp"] for r in all_rows_sc)
            done_rows  = [r for r in all_rows_sc if r["status"].lower() in DONE_STATUS]
            done_s     = len(done_rows)
            done_sp    = sum(r["sp"] for r in done_rows)

            status_map = {}
            for _r in all_rows_sc:
                _k = _r["status"] or "(No Status)"
                if _k not in status_map:
                    status_map[_k] = {"count": 0, "sp": 0.0}
                status_map[_k]["count"] += 1
                status_map[_k]["sp"]    += _r["sp"]

            # ── Styles ──────────────────────────────────────────────────────
            T_FONT  = _st_sc.Font(name="Calibri", size=14, bold=True, color="1A237E")
            H_FONT  = _st_sc.Font(name="Calibri", size=10, bold=True, color="FFFFFF")
            H_FILL  = _st_sc.PatternFill("solid", fgColor="1565C0")
            L_FONT  = _st_sc.Font(name="Calibri", size=10, bold=True)
            V_FONT  = _st_sc.Font(name="Calibri", size=10)
            A_FILL  = _st_sc.PatternFill("solid", fgColor="E3F2FD")
            _bs     = _st_sc.Side(border_style="thin", color="BBDEFB")
            T_BRD   = _st_sc.Border(left=_bs, right=_bs, top=_bs, bottom=_bs)
            C_ALIGN = _st_sc.Alignment(horizontal="center")

            ws.column_dimensions["A"].width = 30
            ws.column_dimensions["B"].width = 20
            ws.column_dimensions["C"].width = 20
            ws.column_dimensions["D"].width = 2
            ws.column_dimensions["E"].width = 20

            _row = 1
            def _cell(r, c, val, font=None, fill=None, border=None, align=None):
                cell = ws.cell(row=r, column=c)
                cell.value = val
                if font:   cell.font   = font
                if fill:   cell.fill   = fill
                if border: cell.border = border
                if align:  cell.alignment = align
                return cell

            # Title
            _cell(_row, 1, "Sprint Summary", font=T_FONT); _row += 1
            sprint_label = filename[:-5] if filename.endswith(".xlsx") else filename
            _cell(_row, 1, f"Sprint: {sprint_label}",
                  font=_st_sc.Font(name="Calibri", size=11, italic=True, color="555555")); _row += 1
            _cell(_row, 1, f"Generated: {_dt_sc.today().strftime('%Y-%m-%d')}",
                  font=_st_sc.Font(name="Calibri", size=10, color="888888")); _row += 2

            # ── Overview ────────────────────────────────────────────────────
            _cell(_row, 1, "Overview",
                  font=_st_sc.Font(name="Calibri", size=12, bold=True, color="1565C0")); _row += 1
            for c, h in enumerate(["Metric", "Value"], 1):
                _cell(_row, c, h, font=H_FONT, fill=H_FILL, border=T_BRD, align=C_ALIGN)
            _row += 1
            _pct = lambda n, d: f"{n/d*100:.1f}%" if d else "0%"
            _metrics = [
                ("Total Stories",          total_s),
                ("Total Story Points",     int(total_sp) if total_sp == int(total_sp) else total_sp),
                ("Completed Stories",      done_s),
                ("Completed Story Points", int(done_sp)  if done_sp  == int(done_sp)  else done_sp),
                ("Adhoc Stories Added",    adhoc_count),
            ]
            for i, (lbl, val) in enumerate(_metrics):
                _fill = A_FILL if i % 2 else None
                _cell(_row, 1, lbl,  font=L_FONT, fill=_fill, border=T_BRD)
                _cell(_row, 2, val,  font=V_FONT, fill=_fill, border=T_BRD, align=C_ALIGN)
                _row += 1
            _row += 1

            # ── Status Breakdown ────────────────────────────────────────────
            _cell(_row, 1, "Status Breakdown",
                  font=_st_sc.Font(name="Calibri", size=12, bold=True, color="1565C0")); _row += 1
            _chart_hdr = _row
            for c, h in enumerate(["Status", "Stories", "Story Points"], 1):
                _cell(_row, c, h, font=H_FONT, fill=H_FILL, border=T_BRD, align=C_ALIGN)
            _row += 1
            _chart_start = _row
            for i, (st, v) in enumerate(sorted(status_map.items())):
                _fill = A_FILL if i % 2 else None
                _sp_disp = int(v["sp"]) if v["sp"] == int(v["sp"]) else v["sp"]
                _cell(_row, 1, st,         font=V_FONT, fill=_fill, border=T_BRD)
                _cell(_row, 2, v["count"], font=V_FONT, fill=_fill, border=T_BRD, align=C_ALIGN)
                _cell(_row, 3, _sp_disp,   font=V_FONT, fill=_fill, border=T_BRD, align=C_ALIGN)
                _row += 1
            _chart_end = _row - 1

            # ── Bar Chart ───────────────────────────────────────────────────
            if _chart_end >= _chart_start:
                _chart = _BarChart()
                _chart.type    = "col"
                _chart.title   = "Stories by Status"
                _chart.y_axis.title = "Count"
                _chart.x_axis.title = "Status"
                _chart.style   = 10
                _chart.width   = 20
                _chart.height  = 14
                _chart.grouping = "clustered"

                _d1 = _Ref(ws, min_col=2, max_col=2, min_row=_chart_hdr, max_row=_chart_end)
                _d2 = _Ref(ws, min_col=3, max_col=3, min_row=_chart_hdr, max_row=_chart_end)
                _cats = _Ref(ws, min_col=1, min_row=_chart_start, max_row=_chart_end)
                _chart.add_data(_d1, titles_from_data=True)
                _chart.add_data(_d2, titles_from_data=True)
                _chart.set_categories(_cats)
                ws.add_chart(_chart, "E3")

            wb.save(str(src))
            wb.close()
            try:
                _rs_capture(src, filename)       # Resource_And_Skill: completed tickets per developer
            except Exception:
                pass

            # Pin this sprint's untagged My Tasks to it so they don't leak into the next sprint
            try:
                _tp = _tasks_path(filename); _tl = _tasks_load(_tp); _ch = False
                for _t in _tl:
                    if not _t.get("sprint"): _t["sprint"] = filename; _ch = True
                if _ch: _tasks_save(_tp, _tl)
            except Exception:
                pass

            # ── Move to PreviousSprints/{team} ──────────────────────────────
            team = _team_from_sprint_filename(filename)
            prev_dir = SPRINT_DATA / "PreviousSprints" / team if team else SPRINT_DATA / "PreviousSprints"
            prev_dir.mkdir(parents=True, exist_ok=True)
            _shutil_sc.move(str(src), str(prev_dir / filename))
            sidecar = src.parent / f"{src.stem}.json"
            if sidecar.exists():
                _shutil_sc.move(str(sidecar), str(prev_dir / sidecar.name))
            return jsonify({"ok": True})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    # ── Resource And Skill ─────────────────────────────────────────────────────
    # Resource_And_Skill/Skill_Matrix.xlsx + Resource/<Developer>.xlsx (tabs: skill, JIRA)
    import re
    RS_ROOT     = TEAM_MGMT_ROOT / "Resource_And_Skill"
    RS_RESOURCE = RS_ROOT / "Resource"
    RS_MATRIX   = RS_ROOT / "Skill_Matrix.xlsx"
    _RS_JIRA_COLS = ["JIRA ID", "Story", "Story Point", "Days", "Module", "Quarter", "Sprint"]
    _rs_lock = _threading.Lock()

    def _rs_safe(name):
        n = re.sub(r'[\\/:*?"<>|]+', "_", str(name or "").strip())
        return n[:80]

    def _rs_file(name):
        return RS_RESOURCE / f"{_rs_safe(name)}.xlsx"

    def _rs_open(name):
        import openpyxl as _xl
        f = _rs_file(name)
        if f.exists():
            wb = _xl.load_workbook(str(f))
        else:
            wb = _xl.Workbook()
            wb.active.title = "skill"
        if "skill" not in wb.sheetnames:
            wb.create_sheet("skill", 0)
        if "JIRA" not in wb.sheetnames:
            wb.create_sheet("JIRA")
        if [c.value for c in wb["skill"][1]][:2] != ["Skill", "Proficiency"]:
            wb["skill"].cell(1, 1).value = "Skill"
            wb["skill"].cell(1, 2).value = "Proficiency"
        if [c.value for c in wb["JIRA"][1]][:len(_RS_JIRA_COLS)] != _RS_JIRA_COLS:
            for i, h in enumerate(_RS_JIRA_COLS, 1):
                wb["JIRA"].cell(1, i).value = h
        return wb, f

    def _rs_read_skills(wb):
        out = []
        for r in wb["skill"].iter_rows(min_row=2, values_only=True):
            if r and r[0] and str(r[0]).strip():
                try:
                    prof = float(r[1]) if r[1] not in (None, "") else 0
                except (TypeError, ValueError):
                    prof = 0
                out.append({"skill": str(r[0]).strip(), "proficiency": int(prof) if prof == int(prof) else prof})
        return out

    def _rs_rebuild_matrix():
        """Skill_Matrix.xlsx: one row per developer (Resource file), one column per skill, cell = proficiency."""
        import openpyxl as _xl
        from openpyxl.styles import Font as _F, PatternFill as _P
        RS_RESOURCE.mkdir(parents=True, exist_ok=True)
        people, skills = [], []
        for f in sorted(RS_RESOURCE.glob("*.xlsx"), key=lambda x: x.stem.lower()):
            if f.name.startswith("~$"):
                continue
            try:
                wb = _xl.load_workbook(str(f), read_only=True, data_only=True)
                rows = [r for r in wb["skill"].iter_rows(min_row=2, values_only=True)] if "skill" in wb.sheetnames else []
                wb.close()
            except Exception:
                continue
            sc = {}
            for r in rows:
                if r and r[0] and str(r[0]).strip():
                    sc[str(r[0]).strip()] = r[1]
                    if str(r[0]).strip() not in skills:
                        skills.append(str(r[0]).strip())
            people.append((f.stem, sc))
        wb = _xl.Workbook()
        ws = wb.active
        ws.title = "Skill Matrix"
        ws.append(["Developer"] + skills)
        for c in ws[1]:
            c.font = _F(bold=True, color="FFFFFF")
            c.fill = _P("solid", fgColor="4472C4")
        for name, sc in people:
            ws.append([name] + [sc.get(k) for k in skills])
        ws.freeze_panes = "B2"
        ws.column_dimensions["A"].width = 28
        RS_ROOT.mkdir(parents=True, exist_ok=True)
        wb.save(str(RS_MATRIX))

    def _rs_quarter(d):
        return f"Q{(d.month - 1) // 3 + 1} {d.year}"

    def _rs_capture(src, filename):
        """Sprint completed: record each developer's completed tickets (story points, days, quarter) in Resource/<dev>.xlsx."""
        import openpyxl as _xl
        from datetime import date as _d
        DONE = {"done", "closed", "released", "completed", "deployed", "merged"}
        m = re.search(r"_(\d{4})-(\d{2})-(\d{2})_", filename)
        quarter = _rs_quarter(_d(int(m.group(1)), int(m.group(2)), int(m.group(3)))) if m else _rs_quarter(_d.today())
        sprint = Path(filename).stem
        wb_s = _xl.load_workbook(str(src), data_only=True)
        per = {}
        for sh in ("Sprint Board", "Adhoc Task"):
            if sh not in wb_s.sheetnames:
                continue
            rows = list(wb_s[sh].iter_rows(values_only=True))
            if not rows:
                continue
            hd = [str(h or "").strip() for h in rows[0]]
            ix = {h: i for i, h in enumerate(hd) if h}
            for r in rows[1:]:
                g = lambda k: r[ix[k]] if k in ix and ix[k] < len(r) else None
                dev, key = str(g("Developer") or "").strip(), str(g("JIRA ID") or "").strip()
                if not dev or not key or str(g("Status") or "").strip().lower() not in DONE:
                    continue
                try:
                    sp = float(g("Story Point")) if g("Story Point") not in (None, "") else 0
                except (TypeError, ValueError):
                    sp = 0
                days = g("DevDays")
                per.setdefault(dev, []).append([key, g("Story") or "", sp, days if days not in (None, "") else "", g("Module") or "", quarter, sprint])
        wb_s.close()
        with _rs_lock:
            RS_RESOURCE.mkdir(parents=True, exist_ok=True)
            for dev, items in per.items():
                wb, f = _rs_open(dev)
                ws = wb["JIRA"]
                have = {(str(r[0].value), str(r[6].value)): r[0].row for r in ws.iter_rows(min_row=2) if r[0].value}
                for it in items:
                    k = (str(it[0]), str(it[6]))
                    if k in have:
                        for ci, v in enumerate(it, 1):
                            ws.cell(have[k], ci).value = v
                    else:
                        ws.append(it)
                wb.save(str(f))
            # developers with no completed tickets still get a file so they appear in the matrix
            _rs_rebuild_matrix()

    @app.route("/api/project-management/resource-skill/matrix", methods=["GET"])
    def api_rs_matrix():
        import openpyxl as _xl
        with _rs_lock:
            if not RS_MATRIX.exists():
                _rs_rebuild_matrix()
            wb = _xl.load_workbook(str(RS_MATRIX), read_only=True, data_only=True)
            rows = list(wb.active.iter_rows(values_only=True))
            wb.close()
        skills = [str(c) for c in (rows[0][1:] if rows else []) if c]
        res = [{"name": str(r[0]), "scores": {sk: r[i + 1] for i, sk in enumerate(skills) if i + 1 < len(r) and r[i + 1] not in (None, "")}}
               for r in rows[1:] if r and r[0]]
        return jsonify({"ok": True, "skills": skills, "resources": res, "path": str(RS_ROOT)})

    @app.route("/api/project-management/resource-skill/resource", methods=["POST"])
    def api_rs_add_resource():
        name = _rs_safe((request.get_json(silent=True) or {}).get("name"))
        if not name:
            return jsonify({"ok": False, "error": "Name is required"}), 400
        with _rs_lock:
            wb, f = _rs_open(name)
            RS_RESOURCE.mkdir(parents=True, exist_ok=True)
            try:
                wb.save(str(f))
                _rs_rebuild_matrix()
            except PermissionError:
                return jsonify({"ok": False, "error": "A resource file is open in Excel — close it and retry"}), 500
        return jsonify({"ok": True})

    @app.route("/api/project-management/resource-skill/resource/<name>", methods=["GET"])
    def api_rs_resource(name):
        if not _rs_file(name).exists():
            return jsonify({"ok": False, "error": "Resource not found"}), 404
        with _rs_lock:
            wb, _ = _rs_open(name)
            skills = _rs_read_skills(wb)
            jira = [dict(zip(_RS_JIRA_COLS, ["" if v is None else v for v in r]))
                    for r in wb["JIRA"].iter_rows(min_row=2, values_only=True) if r and r[0]]
            wb.close()
        return jsonify({"ok": True, "name": _rs_safe(name), "skills": skills, "jira": jira})

    @app.route("/api/project-management/resource-skill/resource/<name>/skills", methods=["PUT"])
    def api_rs_save_skills(name):
        items = (request.get_json(silent=True) or {}).get("skills") or []
        with _rs_lock:
            wb, f = _rs_open(name)
            ws = wb["skill"]
            ws.delete_rows(2, max(ws.max_row, 2))
            seen = set()
            for it in items:
                sk = str(it.get("skill", "")).strip()
                if not sk or sk.lower() in seen:
                    continue
                seen.add(sk.lower())
                try:
                    pr = float(it.get("proficiency") or 0)
                except (TypeError, ValueError):
                    pr = 0
                ws.append([sk, int(pr) if pr == int(pr) else pr])
            try:
                wb.save(str(f))
                _rs_rebuild_matrix()
            except PermissionError:
                return jsonify({"ok": False, "error": "A resource file is open in Excel — close it and retry"}), 500
        return jsonify({"ok": True})

    @app.route("/api/project-management/sprint/delete", methods=["POST"])
    def api_tm_sprint_delete():
        body = request.get_json() or {}
        filename = str(body.get("file") or "").strip()
        if not filename:
            return jsonify({"ok": False, "error": "file required"})
        target = _sprint_team_path(filename)
        if not target.exists():
            return jsonify({"ok": False, "error": f"File not found: {filename}"})
        try:
            target.unlink()
            sidecar = target.parent / f"{target.stem}.json"
            if sidecar.exists():
                sidecar.unlink()
            return jsonify({"ok": True})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/project-management/sprint/project-setup-branch", methods=["POST"])
    def api_tm_sprint_project_setup_branch():
        import subprocess as _sub_sb
        body        = request.get_json() or {}
        application = str(body.get("application") or "").strip()
        branch_name = str(body.get("branch_name") or "").strip()
        if not application or not branch_name:
            return jsonify({"ok": False, "error": "application and branch_name required"})

        _APP_SLUG_MAP_SB = {
            "PAYOR": "payor", "CLASSIC": "classic", "CONNECTOR": "connector",
            "ENROLLMENT": "enrollment", "PIK": "pik",
        }
        _DISPLAY_NAMES_SB = {
            "payor": "Payor", "classic": "Classic", "connector": "Connector",
            "enrollment": "Enrollment", "pik": "PIK",
        }
        app_slug     = _APP_SLUG_MAP_SB.get(application.upper(), application.lower())
        display_name = _DISPLAY_NAMES_SB.get(app_slug, application)
        _cf = 0x08000000 if sys.platform == "win32" else 0
        steps = []

        def _git(*args, cwd, timeout=120):
            r = _sub_sb.run(["git"] + list(args), cwd=cwd,
                            capture_output=True, text=True, encoding="utf-8",
                            errors="replace", creationflags=_cf, timeout=timeout)
            return r.returncode == 0, (r.stdout + r.stderr).strip()

        # 1. Build check
        build_running = False
        try:
            if app_slug == "payor":
                with _payor_build_lock:
                    build_running = _payor_build["status"] == "running"
            else:
                lock_sb, state_sb = _get_generic_build_state(app_slug)
                with lock_sb:
                    build_running = state_sb["status"] == "running"
        except Exception:
            pass

        if build_running:
            steps.append({"label": "Build check", "status": "error",
                          "detail": f"Build is running for {display_name}"})
            return jsonify({"ok": False, "steps": steps,
                            "error": f"Build is running for {display_name} — cannot switch branches"})
        steps.append({"label": "Build check", "status": "ok",
                      "detail": f"No build running for {display_name}"})

        # 2. Find clone dir
        clone_dir = _find_repo_dir(app_slug)
        if not clone_dir:
            steps.append({"label": "Find repository", "status": "error", "detail": "Local clone not found"})
            return jsonify({"ok": False, "steps": steps, "error": "Local clone not found"})
        steps.append({"label": "Repository", "status": "ok", "detail": clone_dir})

        # 3. Stale file check
        confirm_revert = bool(body.get("confirm_revert"))
        ok_st, out_st = _git("status", "--porcelain", cwd=clone_dir, timeout=15)
        changed_files = [l.strip() for l in out_st.splitlines() if l.strip()] if ok_st else []
        if changed_files and not confirm_revert:
            return jsonify({"ok": False, "stale_files": True, "changed_files": changed_files, "steps": steps})
        if changed_files and confirm_revert:
            ok_rv, out_rv = _git("checkout", ".", cwd=clone_dir, timeout=30)
            steps.append({"label": "Revert changes", "status": "ok" if ok_rv else "error",
                          "detail": "Reverted uncommitted changes" if ok_rv else out_rv})
            if not ok_rv:
                return jsonify({"ok": False, "steps": steps, "error": f"Could not revert: {out_rv}"})

        # 4. git checkout master/main
        checked_default = None
        for db in ("master", "main"):
            ok_co, out_co = _git("checkout", db, cwd=clone_dir, timeout=30)
            if ok_co:
                steps.append({"label": f"git checkout {db}", "status": "ok",
                              "detail": out_co or f"On branch {db}"})
                checked_default = db
                break
        if not checked_default:
            steps.append({"label": "git checkout master", "status": "error", "detail": out_co})
            return jsonify({"ok": False, "steps": steps,
                            "error": "Could not checkout master/main"})

        # 4. git pull
        ok_pull, out_pull = _git("pull", cwd=clone_dir, timeout=120)
        steps.append({"label": "git pull",
                      "status": "ok" if ok_pull else "warning",
                      "detail": out_pull or ("Already up to date." if ok_pull else "Pull had warnings")})

        # 5. Branch setup
        ok_list, out_list = _git("branch", "--list", branch_name, cwd=clone_dir, timeout=15)
        branch_exists_local = bool(out_list.strip())
        branch_action = None

        if branch_exists_local:
            ok_co2, out_co2 = _git("checkout", branch_name, cwd=clone_dir, timeout=30)
            steps.append({"label": f"Branch", "status": "ok" if ok_co2 else "error",
                          "detail": f"{branch_name} — found locally, checked out" if ok_co2 else out_co2})
            branch_action = "found_local"
        else:
            ok_co3, out_co3 = _git("checkout", branch_name, cwd=clone_dir, timeout=60)
            if ok_co3:
                steps.append({"label": "Branch", "status": "ok",
                              "detail": f"{branch_name} — checked out from remote"})
                branch_action = "checked_out_remote"
            else:
                ok_cb, out_cb = _git("checkout", "-b", branch_name, cwd=clone_dir, timeout=30)
                if ok_cb:
                    steps.append({"label": "Branch", "status": "ok",
                                  "detail": f"{branch_name} — created as new local branch"})
                    branch_action = "created_local"
                else:
                    steps.append({"label": "Branch", "status": "error", "detail": out_cb or "Failed"})
                    return jsonify({"ok": False, "steps": steps,
                                    "error": f"Could not set up branch: {out_cb}"})

        return jsonify({
            "ok": True, "steps": steps, "branch_action": branch_action,
            "local_app_path": f"/local-app/{app_slug}",
            "app_name": display_name,
        })

    @app.route("/api/project-management/sprint/project-preview", methods=["POST"])
    def api_tm_sprint_project_preview():
        import re as _re_pp
        body       = request.get_json() or {}
        jira_id    = str(body.get("jira_id")    or "").strip()
        story      = str(body.get("story")      or "").strip()
        issue_type = str(body.get("issue_type") or "").strip()
        if not jira_id:
            return jsonify({"ok": False, "error": "jira_id required"})
        RULES_FILE = SPRINT_ROOT / "Rules.xlsx"
        if not RULES_FILE.exists():
            return jsonify({"ok": False, "error": "Rules.xlsx not found"})
        try:
            import openpyxl as _xl_pp
            wb = _xl_pp.load_workbook(str(RULES_FILE), read_only=True, data_only=True)
            if "Project" not in wb.sheetnames:
                return jsonify({"ok": False, "error": "Project tab not found in Rules.xlsx"})
            ws   = wb["Project"]
            hdrs = [str(c.value or "").strip().lower().replace(" ", "_") for c in ws[1]]
            rules = []
            for row in ws.iter_rows(min_row=2, values_only=True):
                if not any(v for v in row):
                    continue
                rules.append({k: (str(v).strip() if v is not None else "") for k, v in zip(hdrs, row)})
            wb.close()
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})
        rule, is_default = None, False
        for r in rules:
            if jira_id.upper().startswith(r.get("jira_prefix", "").upper()) and \
               r.get("ticket_type", "").lower() == issue_type.lower():
                rule = r; break
        if rule is None:
            for r in rules:
                if jira_id.upper().startswith(r.get("jira_prefix", "").upper()) and \
                   r.get("default", "").lower() == "yes":
                    rule = r; is_default = True; break
        if rule is None:
            return jsonify({"ok": False, "error": f"No matching rule for {jira_id} / {issue_type}"})
        # strip leading ticket prefix from story title, convert to snake_case
        title = _re_pp.sub(r'^\s*\[[A-Z]+-\d+\]\s*', '', story)
        title = _re_pp.sub(r'^\s*[A-Z]+-\d+[:\s]+', '', title, flags=_re_pp.I)
        title = _re_pp.sub(r'[^\w\s]', ' ', title)
        title = _re_pp.sub(r'\s+', '_', title.strip())
        snake = title.lower()[:60].strip('_')
        branch = (
            (rule.get("branch_prefix") or "") +
            jira_id +
            (rule.get("branch_midfix") or "") +
            snake +
            (rule.get("branch_postfix") or "")
        )
        proj_file = f"{jira_id}.xlsx"
        proj_path = _find_project_path(jira_id)
        proj_exists = proj_path.exists()
        project_info, next_branch_suggestion = {}, None
        if proj_exists:
            try:
                _wb_ex = _xl_pp.load_workbook(str(proj_path), read_only=True, data_only=True)
                _ws_ex = _wb_ex.active
                for _row in _ws_ex.iter_rows(min_row=1, values_only=True):
                    if _row and _row[0]:
                        project_info[str(_row[0]).strip()] = str(_row[1] or "").strip() if len(_row) > 1 else ""
                _wb_ex.close()
            except Exception: pass
            existing_branches = [v for k, v in project_info.items()
                                 if k == "Branch" or _re_pp.match(r"^Branch \d+$", k)]
            next_ver = len(existing_branches) + 1
            next_branch_suggestion = branch + f"_V{next_ver}"
        # Fetch fix versions, code freeze date, and release date from Jira
        fix_versions     = []
        code_freeze_date = None
        release_date     = None
        try:
            _creds_fv, _cerr_fv = _jira_creds()
            if _creds_fv:
                import requests as _rq_fv, urllib3 as _u3_fv
                from requests.auth import HTTPBasicAuth as _ba_fv
                _u3_fv.disable_warnings()
                _r_fv = _rq_fv.get(
                    f"{_creds_fv['base_url']}/rest/api/2/issue/{jira_id}",
                    params={"fields": "*navigable", "expand": "names"},
                    auth=_ba_fv(_creds_fv["email"], _creds_fv["api_token"]),
                    headers={"Accept": "application/json"},
                    timeout=10, verify=False,
                )
                if _r_fv.status_code == 200:
                    _fv_data    = _r_fv.json()
                    _fv_fields  = _fv_data.get("fields", {})
                    _fvs        = _fv_fields.get("fixVersions", [])
                    fix_versions = [fv.get("name", "") for fv in _fvs if fv.get("name")]
                    # Reverse-map display names → field IDs for custom fields
                    _n2id = {str(v).lower(): k for k, v in _fv_data.get("names", {}).items()}
                    _cf_id = _n2id.get("code freeze date")
                    _rd_id = _n2id.get("release date")
                    code_freeze_date = _fv_fields.get(_cf_id) or None if _cf_id else None
                    release_date     = _fv_fields.get(_rd_id) or None if _rd_id else None
        except Exception:
            pass
        return jsonify({
            "ok": True,
            "branch_name": branch,
            "is_default": is_default,
            "project_exists": proj_exists,
            "project_file": proj_file if proj_exists else None,
            "project_info": project_info if proj_exists else None,
            "next_branch_suggestion": next_branch_suggestion,
            "fix_versions": fix_versions,
            "code_freeze_date": code_freeze_date,
            "release_date": release_date,
            "rule": {
                "jira_prefix":    rule.get("jira_prefix"),
                "ticket_type":    rule.get("ticket_type"),
                "branch_prefix":  rule.get("branch_prefix"),
                "branch_midfix":  rule.get("branch_midfix"),
                "branch_postfix": rule.get("branch_postfix"),
                "application":    rule.get("application"),
            },
        })

    @app.route("/api/project-management/sprint/resolve-release-branch", methods=["POST"])
    def api_sprint_resolve_release_branch():
        import re as _re_rb, requests as _rq_rb, urllib3 as _u3_rb
        import urllib.parse as _up_rb
        _u3_rb.disable_warnings()
        body        = request.get_json() or {}
        app_name    = str(body.get("app")         or "").strip().lower()
        fix_version = str(body.get("fix_version") or "").strip()
        if not app_name or not fix_version:
            return jsonify({"ok": False, "error": "app and fix_version required"})

        repos    = _scm_read_git_config()
        repo_url = next((r["repo_url"] for r in repos if r["app"] == app_name), None)
        if not repo_url:
            return jsonify({"ok": True, "release_branch": None, "note": f"No repo configured for '{app_name}'"})

        m = _re_rb.search(r"github\.com/([^/]+)/([^/]+?)(?:\.git)?/?$", repo_url)
        if not m:
            return jsonify({"ok": True, "release_branch": None, "note": "Invalid repo URL"})
        owner, repo_gh = m.group(1), m.group(2)

        token   = _scm_github_token()
        headers = ({"Authorization": f"token {token}", "Accept": "application/vnd.github+json"}
                   if token else {"Accept": "application/vnd.github+json"})

        # Extract numeric version (handles "Payor 26.2.1.0.4" prefixes)
        v_match = _re_rb.search(r"(\d+(?:\.\d+){2,})", fix_version)
        if not v_match:
            return jsonify({"ok": True, "release_branch": None})
        v_num = v_match.group(1)
        parts = v_num.split(".")
        try:
            last = int(parts[-1])
        except ValueError:
            last = 0

        # Candidates: full version descending from N to 1
        candidates = [".".join(parts[:-1] + [str(i)]) for i in range(last, 0, -1)]
        # 4-segment only: also try 3-segment fallback (e.g., 26.2.4)
        if len(parts) == 4:
            candidates.append(".".join(parts[:-1]))

        for ver in candidates:
            branch_name = f"release-{ver}"
            try:
                resp = _rq_rb.get(
                    f"https://api.github.com/repos/{owner}/{repo_gh}/branches/{_up_rb.quote(branch_name, safe='')}",
                    headers=headers, timeout=5, verify=False,
                )
                if resp.status_code == 200:
                    return jsonify({"ok": True, "release_branch": branch_name})
            except Exception:
                pass

        return jsonify({"ok": True, "release_branch": None})

    @app.route("/api/project-management/sprint/project-add-branch", methods=["POST"])
    def api_tm_sprint_project_add_branch():
        import re as _re_ab
        body        = request.get_json() or {}
        jira_id     = str(body.get("jira_id")     or "").strip()
        branch_name = str(body.get("branch_name") or "").strip()
        team        = str(body.get("team")        or "").strip()
        if not jira_id or not branch_name:
            return jsonify({"ok": False, "error": "jira_id and branch_name required"})
        dest = _find_project_path(jira_id, team or None)
        if not dest.exists():
            return jsonify({"ok": False, "error": f"Project {jira_id}.xlsx not found"})
        try:
            import openpyxl as _xl_ab
            wb = _xl_ab.load_workbook(str(dest))
            ws = wb.active
            existing = [str(c.value or "").strip() for c in ws["A"] if c.value]
            branch_count = sum(1 for k in existing if k == "Branch" or _re_ab.match(r"^Branch \d+$", k))
            label = f"Branch {branch_count + 1}"
            ws.append((label, branch_name))
            wb.save(str(dest))
            wb.close()
            return jsonify({"ok": True, "label": label})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/project-management/sprint/project-delete-branch", methods=["POST"])
    def api_tm_sprint_project_delete_branch():
        import subprocess as _sub_db
        body         = request.get_json() or {}
        jira_id      = str(body.get("jira_id")      or "").strip()
        branch_name  = str(body.get("branch_name")  or "").strip()
        branch_label = str(body.get("branch_label") or "").strip()
        application  = str(body.get("application")  or "").strip()
        if not jira_id or not branch_name:
            return jsonify({"ok": False, "error": "jira_id and branch_name required"})

        _APP_SLUG_MAP_DB = {
            "PAYOR": "payor", "CLASSIC": "classic", "CONNECTOR": "connector",
            "ENROLLMENT": "enrollment", "PIK": "pik",
        }
        _DISPLAY_NAMES_DB = {
            "payor": "Payor", "classic": "Classic", "connector": "Connector",
            "enrollment": "Enrollment", "pik": "PIK",
        }
        app_slug     = _APP_SLUG_MAP_DB.get(application.upper(), application.lower())
        display_name = _DISPLAY_NAMES_DB.get(app_slug, application)
        _cf = 0x08000000 if sys.platform == "win32" else 0

        # Find clone dir
        clone_dir = _find_repo_dir(app_slug)
        if not clone_dir:
            return jsonify({"ok": False, "error": "Local clone not found"})

        # Check build status
        build_running = False
        try:
            if app_slug == "payor":
                with _payor_build_lock:
                    build_running = _payor_build["status"] == "running"
            else:
                lock_db, state_db = _get_generic_build_state(app_slug)
                with lock_db:
                    build_running = state_db["status"] == "running"
        except Exception:
            pass

        # Check currently checked-out branch
        r_head = _sub_db.run(
            ["git", "rev-parse", "--abbrev-ref", "HEAD"],
            cwd=clone_dir, capture_output=True, text=True,
            encoding="utf-8", errors="replace", creationflags=_cf, timeout=10,
        )
        current_branch = r_head.stdout.strip() if r_head.returncode == 0 else ""

        if build_running and current_branch == branch_name:
            return jsonify({
                "ok": False, "blocked": True,
                "error": f"Cannot delete: {display_name} is currently building on branch '{branch_name}'",
            })

        # Delete local git branch
        r_del = _sub_db.run(
            ["git", "branch", "-D", branch_name],
            cwd=clone_dir, capture_output=True, text=True,
            encoding="utf-8", errors="replace", creationflags=_cf, timeout=30,
        )
        git_out = (r_del.stdout + r_del.stderr).strip()
        if r_del.returncode != 0:
            return jsonify({"ok": False, "error": git_out or "git branch -D failed"})

        # Remove matching row from project Excel
        dest = _find_project_path(jira_id)
        if dest.exists():
            try:
                import openpyxl as _xl_db
                wb = _xl_db.load_workbook(str(dest))
                ws = wb.active
                for row in ws.iter_rows():
                    col_a = str(row[0].value or "").strip()
                    col_b = str(row[1].value or "").strip() if len(row) > 1 else ""
                    if col_b == branch_name and (col_a == "Branch" or col_a == branch_label or col_a.startswith("Branch")):
                        ws.delete_rows(row[0].row)
                        break
                wb.save(str(dest))
                wb.close()
            except Exception as e:
                return jsonify({"ok": True, "warning": f"Branch deleted from git but Excel update failed: {e}", "git_output": git_out})

        return jsonify({"ok": True, "git_output": git_out})

    @app.route("/api/project-management/sprint/project-create", methods=["POST"])
    def api_tm_sprint_project_create():
        from datetime import datetime as _dt_pc
        body        = request.get_json() or {}
        jira_id     = str(body.get("jira_id")     or "").strip()
        story       = str(body.get("story")       or "").strip()
        issue_type  = str(body.get("issue_type")  or "").strip()
        developer   = str(body.get("developer")   or "").strip()
        application = str(body.get("application") or "").strip()
        team        = str(body.get("team")        or "").strip()
        branches         = [str(b).strip() for b in (body.get("branches")     or []) if str(b).strip()]
        sprints          = [str(s).strip() for s in (body.get("sprints")      or []) if str(s).strip()]
        code_freeze_date = str(body.get("code_freeze_date") or "").strip()
        release_date     = str(body.get("release_date")     or "").strip()
        if not jira_id or not branches:
            return jsonify({"ok": False, "error": "jira_id and at least one branch required"})
        proj_team_dir = SPRINT_DATA / "Projects" / team if team else SPRINT_DATA / "Projects"
        proj_team_dir.mkdir(parents=True, exist_ok=True)
        dest = proj_team_dir / f"{jira_id}.xlsx"
        if dest.exists():
            return jsonify({"ok": False, "error": f"Project {jira_id}.xlsx already exists"})
        try:
            import openpyxl as _xl_pc
            from openpyxl.styles import Font as _Font_pc
            wb = _xl_pc.Workbook()
            ws = wb.active
            ws.title = "Project Info"
            ws.column_dimensions["A"].width = 20
            ws.column_dimensions["B"].width = 70
            # fixed fields
            fixed_rows = [("JIRA ID", jira_id), ("Story", story), ("Type", issue_type),
                          ("Application", application), ("Team", team), ("Developer", developer),
                          ("Created", _dt_pc.today().strftime("%Y-%m-%d"))]
            if code_freeze_date:
                fixed_rows.append(("Code Freeze Date", code_freeze_date))
            if release_date:
                fixed_rows.append(("Release Date", release_date))
            for r in fixed_rows:
                ws.append(r)
            # numbered sprints
            for idx, s in enumerate(sprints, 1):
                label = "Sprint" if len(sprints) == 1 else f"Sprint {idx}"
                ws.append((label, s))
            # numbered branches
            for idx, b in enumerate(branches, 1):
                label = "Branch" if len(branches) == 1 else f"Branch {idx}"
                ws.append((label, b))
            # JIRA ID hyperlink
            creds, _ = _jira_creds()
            base_url  = (creds or {}).get("base_url", "").rstrip("/")
            if base_url and jira_id:
                ws["B1"].hyperlink = f"{base_url}/browse/{jira_id}"
                ws["B1"].font = _Font_pc(color="1565C0", underline="single")
            wb.save(str(dest))
            wb.close()
            return jsonify({"ok": True, "file": dest.name})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/project-management/sprint/refresh-board", methods=["POST"])
    def api_tm_sprint_refresh_board():
        import json as _json_rb, re as _re_rb
        try:
            import requests as _rq_rb, urllib3 as _u3_rb
            _u3_rb.disable_warnings()
        except ImportError:
            return jsonify({"ok": False, "error": "requests library not installed"})
        body = request.get_json() or {}
        filename = str(body.get("file") or "").strip()
        freeze_dev = bool(body.get("freeze_dev", True))
        if not filename:
            return jsonify({"ok": False, "error": "file required"})
        target = _sprint_team_path(filename)
        if not target.exists():
            return jsonify({"ok": False, "error": f"File not found: {filename}"})
        # Resolve board URL: sidecar → Template.xlsx Teams tab (col B)
        sprint_url = ""
        sidecar = target.parent / f"{target.stem}.json"
        if sidecar.exists():
            try: sprint_url = _json_rb.loads(sidecar.read_text()).get("sprint_url", "")
            except: pass
        if not sprint_url and SPRINT_TEMPLATE.exists():
            _m = _re_rb.match(r'^(.+?)_\d{4}-\d{2}-\d{2}_', target.stem)
            _team = _m.group(1) if _m else ""
            if _team:
                try:
                    import openpyxl as _xl_rb_t
                    _wbt = _xl_rb_t.load_workbook(str(SPRINT_TEMPLATE), read_only=True, data_only=True)
                    if "Teams" in _wbt.sheetnames:
                        for _tr in _wbt["Teams"].iter_rows(min_row=1, values_only=True):
                            if _tr and _tr[0] and str(_tr[0]).strip() == _team:
                                sprint_url = str(_tr[1]).strip() if len(_tr) > 1 and _tr[1] else ""
                                break
                    _wbt.close()
                except Exception:
                    pass
        if not sprint_url:
            return jsonify({"ok": False, "error": "No board URL found — add it to Template.xlsx Teams tab (column B)"})
        creds, cerr = _jira_creds()
        if cerr:
            return jsonify({"ok": False, "error": cerr})
        issues, ferr = _fetch_board_issues(creds, sprint_url)
        if ferr:
            return jsonify({"ok": False, "error": ferr})
        if issues is None:
            return jsonify({"ok": False, "error": "Failed to fetch issues from board"})
        if not issues:
            return jsonify({"ok": True, "count": 0, "total_board": 0, "message": "No active sprint found on board"})
        try:
            import openpyxl as _xl_rb
            wb = _xl_rb.load_workbook(str(target))
            count = 0
            if "Sprint Board" in wb.sheetnames:
                _m_rb = _re_rb.match(r'^(.+?)_\d{4}-\d{2}-\d{2}_', target.stem)
                _team_rb = _m_rb.group(1) if _m_rb else ""
                # Ensure Adhoc Task sheet exists with correct headers (incl. Date Added)
                _ADHOC_HEADERS = ["JIRA ID", "Story", "Issue Type", "Type", "Status", "Developer",
                                   "Story Point", "PRs", "PR Status", "Date Added"]
                if "Adhoc Task" not in wb.sheetnames:
                    _aws = wb.create_sheet("Adhoc Task")
                    for _ci, _ch in enumerate(_ADHOC_HEADERS, 1):
                        _aws.cell(row=1, column=_ci).value = _ch
                else:
                    _aws = wb["Adhoc Task"]
                    _ah_hdr = [c.value for c in next(_aws.iter_rows(min_row=1, max_row=1))]
                    if "Date Added" not in _ah_hdr:
                        _aws.cell(row=1, column=len(_ah_hdr)+1).value = "Date Added"
                adhoc_ws_arg = _aws if freeze_dev else None
                count = _apply_board_issues(wb["Sprint Board"], issues, creds["base_url"], creds,
                                            freeze_dev=freeze_dev, team=_team_rb, sprint_root=SPRINT_DATA,
                                            adhoc_ws=adhoc_ws_arg)
            wb.save(str(target))
            wb.close()
            return jsonify({"ok": True, "count": count, "total_board": len(issues)})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    # ── Project Summary (Epic roll-up) ─────────────────────────────────────────
    _PS_SHEET    = "Project Summary"
    _PS_COLS     = ["S.No", "HINIT", "HINIT Due Date", "Epic-JIRA", "HINIT/Epic goal",
                    "Current Sprint Target", "Next Sprint Target", "Status", "Risk and Mitigation",
                    "Comments1", "Comments2",
                    "Qtr SP Done", "Qtr SP Committed", "Qtr Tickets Done", "Qtr Tickets Committed", "Qtr Velocity",
                    "Team Progress", "Status Override", "Epic Created", "Source"]
    _PS_WIDTHS   = (6, 12, 14, 14, 40, 55, 40, 13, 40, 30, 30, 12, 12, 12, 12, 12, 22, 15, 14, 10)
    _PS_STATUSES = ["Not Started", "In Progress", "At Risk", "Completed", "Overdue"]
    _PS_EDITABLE = {"HINIT Due Date", "HINIT/Epic goal", "Next Sprint Target", "Risk and Mitigation",
                    "Comments1", "Comments2", "Status Override"}
    _EPIC_COLS   = ["JIRA ID", "Story", "Type", "Status", "Story Point", "Assignee", "Team Story",
                    "In Current Sprint", "Resolved", "Qtr Committed"]
    _PS_DONE     = {"closed", "done", "released", "completed", "deployed", "merged", "bug filed", "resolved", "cancelled", "complete"}
    _PS_NOT_STARTED = {"", "to do", "backlog", "open", "new", "ready for dev", "reopened", "refinement", "ready for refinement"}
    _PS_KEY_RE   = _re_team.compile(r"^([A-Z][A-Z0-9]+-\d+)(.*)$")
    _PS_KEY_ANY  = _re_team.compile(r"[A-Z][A-Z0-9]+-\d+")

    def _ps_epic_sheet(key):
        return f"Epic {key}"[:31]

    def _ps_date(v):
        from datetime import date as _d
        try: return _d.fromisoformat(str(v).strip()[:10])
        except Exception: return None

    def _ps_num(v):
        try: return float(v)
        except (TypeError, ValueError): return None

    def _ps_fmt(x):
        return int(x) if float(x) == int(x) else round(x, 1)

    def _ps_quarter():
        """Current calendar quarter -> (quarter number, year, first day of the quarter)."""
        from datetime import date as _d
        t = _d.today(); q = (t.month - 1) // 3 + 1
        return q, t.year, _d(t.year, 3 * (q - 1) + 1, 1)

    def _ps_workdays(start, end):
        """Weekdays (Mon-Fri) from start to end, both inclusive."""
        from datetime import timedelta
        n, d = 0, start
        while d <= end:
            if d.weekday() < 5: n += 1
            d += timedelta(days=1)
        return n

    def _ps_quarter_end():
        from datetime import date as _d, timedelta
        q, y, _ = _ps_quarter()
        return _d(y + (q == 4), 1 if q == 4 else 3 * q + 1, 1) - timedelta(days=1)

    def _ps_forecast(prog, m):
        """Velocity (per 2 working weeks) from this quarter's completed work, and whether the remaining work fits before quarter end."""
        from datetime import date as _d, timedelta
        today, qe = _d.today(), _ps_quarter_end()
        elapsed = max(1, _ps_workdays(_ps_quarter()[2], today))
        left = _ps_workdays(today + timedelta(days=1), qe) if today < qe else 0
        done_q = m["sp_done"] if prog["unit"] == "SP" else m["tickets_done"]
        per_day = done_q / elapsed
        remaining = prog["total"] - prog["done"]
        capacity = per_day * left
        return {"velocity": round(per_day * 10, 1), "unit": prog["unit"], "remaining": _ps_fmt(remaining),
                "days_left": left, "capacity": round(capacity, 1), "on_track": remaining <= capacity + 1e-9,
                "quarter_end": qe.isoformat()}

    def _ps_rows_as_dicts(ws):
        rows = list(ws.iter_rows(values_only=True))
        if not rows: return []
        hdr = [str(c) if c is not None else "" for c in rows[0]]
        out = []
        for r in rows[1:]:
            if not any(c is not None and str(c).strip() for c in r): continue
            out.append({h: ("" if i >= len(r) or r[i] is None else str(r[i])) for i, h in enumerate(hdr)})
        return out

    def _ps_read_epic(wb, key):
        sn = _ps_epic_sheet(key)
        return _ps_rows_as_dicts(wb[sn]) if sn in wb.sheetnames else []

    def _ps_read_sheet(wb):
        return _ps_rows_as_dicts(wb[_PS_SHEET]) if _PS_SHEET in wb.sheetnames else []

    def _ps_progress(stories):
        """Progress counts only stories flagged Team Story = Yes (story points if any, else story count)."""
        team = [s for s in stories if s.get("Team Story", "").strip().lower() == "yes"]
        use_sp = any((_ps_num(s.get("Story Point")) or 0) > 0 for s in team)
        def w(s): return (_ps_num(s.get("Story Point")) or 0) if use_sp else 1
        total = sum(w(s) for s in team)
        done  = sum(w(s) for s in team if s.get("Status", "").strip().lower() in _PS_DONE)
        started = any(s.get("Status", "").strip().lower() not in _PS_NOT_STARTED for s in team)
        return {"pct": round(done / total * 100) if total else 0, "done": _ps_fmt(done), "total": _ps_fmt(total),
                "unit": "SP" if use_sp else "stories", "started": started, "team_count": len(team)}

    def _ps_qtr_metrics(stories):
        """Team stories committed in the current quarter, and how many of them are done."""
        qs = _ps_quarter()[2].isoformat()
        yes = lambda s, k: s.get(k, "").strip().lower() == "yes"
        # committed = every team-ticked story except those already finished before this quarter began
        is_done = lambda s: s.get("Status", "").strip().lower() in _PS_DONE
        comm = [s for s in stories if yes(s, "Team Story")
                and not (is_done(s) and s.get("Resolved", "")[:10] and s.get("Resolved", "")[:10] < qs)]
        done = [s for s in comm if is_done(s)]
        sp = lambda L: sum(_ps_num(s.get("Story Point")) or 0 for s in L)
        return {"sp_done": _ps_fmt(sp(done)), "sp_committed": _ps_fmt(sp(comm)),
                "tickets_done": len(done), "tickets_committed": len(comm)}

    def _ps_auto_status(prog, due, created, fc=None):
        from datetime import date as _d
        today = _d.today()
        if prog["total"] == 0: return "Not Started"
        if prog["pct"] >= 100: return "Completed"
        if due and today > due: return "Overdue"
        if prog["pct"] == 0 and not prog["started"]: return "Not Started"
        # remaining work vs. what the current velocity can deliver in the working days left in the quarter
        if fc and prog["total"] - prog["done"] > 0 and not fc["on_track"]: return "At Risk"
        return "In Progress"

    def _ps_row_view(wb, rec):
        stories = _ps_read_epic(wb, rec.get("Epic-JIRA", ""))
        prog = _ps_progress(stories)
        fc = _ps_forecast(prog, _ps_qtr_metrics(stories))
        auto = _ps_auto_status(prog, _ps_date(rec.get("HINIT Due Date")), _ps_date(rec.get("Epic Created")), fc)
        ov = rec.get("Status Override", "")
        return stories, prog, auto, (ov if ov in _PS_STATUSES else auto)

    def _ps_bulletize(text):
        out = []
        for l in str(text or "").split("\n"):
            l = l.strip()
            if l: out.append(l if l.startswith("•") else "• " + l)
        return "\n".join(out)

    def _ps_style_link(cell, url):
        from openpyxl.styles import Font
        cell.hyperlink = url
        cell.font = Font(color="0563C1", underline="single")

    def _ps_target_cell(cell, text, base_url):
        """Bulleted lines; the cell is styled as a link and opens all of its tickets in a Jira search."""
        if not text or not base_url: return
        keys = []
        for line in text.split("\n"):
            m = _PS_KEY_RE.match(line[1:].strip() if line.startswith("•") else line)
            if m: keys.append(m.group(1))
        if keys:
            url = f"{base_url}/issues/?jql=key%20in%20({','.join(keys)})"
            if len(url) < 2000: _ps_style_link(cell, url)

    def _ps_link_epic_sheet(wb, key, base_url):
        sn = _ps_epic_sheet(key)
        if not base_url or sn not in wb.sheetnames: return
        for row in wb[sn].iter_rows(min_row=2, max_col=1):
            c = row[0]
            if c.value: _ps_style_link(c, f"{base_url}/browse/{str(c.value).strip()}")

    def _ps_status_colors(ws, rng):
        from openpyxl.formatting.rule import CellIsRule
        from openpyxl.styles import PatternFill, Font
        for name, bg, fg in (("Not Started", "CFD8DC", "37474F"), ("In Progress", "BBDEFB", "0D47A1"),
                             ("At Risk", "FFE0B2", "E65100"), ("Completed", "C8E6C9", "1B5E20"),
                             ("Overdue", "FFCDD2", "B71C1C")):
            ws.conditional_formatting.add(rng, CellIsRule(operator="equal", formula=[f'"{name}"'],
                                          fill=PatternFill("solid", start_color=bg, end_color=bg), font=Font(bold=True, color=fg)))

    def _ps_write_sheet(wb, recs, base_url=""):
        from openpyxl.worksheet.datavalidation import DataValidation
        from openpyxl.styles import Font, PatternFill, Alignment
        from openpyxl.utils import get_column_letter
        if _PS_SHEET in wb.sheetnames: del wb[_PS_SHEET]
        ws = wb.create_sheet(_PS_SHEET, 1 if len(wb.sheetnames) > 1 else 0)
        ws.append(_PS_COLS)
        for c in ws[1]:
            c.font = Font(bold=True, color="FFFFFF"); c.fill = PatternFill("solid", fgColor="1565C0")
        for i, rec in enumerate(recs, 1):
            stories, prog, auto, status = _ps_row_view(wb, rec)
            m = _ps_qtr_metrics(stories)
            rec["Qtr Velocity"] = _ps_forecast(prog, m)["velocity"]
            rec["S.No"] = str(i); rec["Status"] = status
            rec["Team Progress"] = f"{prog['pct']}% ({prog['done']}/{prog['total']} {prog['unit']})"
            rec["Qtr SP Done"] = m["sp_done"]; rec["Qtr SP Committed"] = m["sp_committed"]
            rec["Qtr Tickets Done"] = m["tickets_done"]; rec["Qtr Tickets Committed"] = m["tickets_committed"]
            for _f in ("Current Sprint Target", "Next Sprint Target"):
                rec[_f] = _ps_bulletize(rec.get(_f))
            ws.append([rec.get(h) if rec.get(h) not in ("", None) else None for h in _PS_COLS])
            r = ws.max_row
            if base_url:
                _ps_style_link(ws.cell(r, 4), f"{base_url}/browse/{rec.get('Epic-JIRA', '')}")
                if rec.get("HINIT"): _ps_style_link(ws.cell(r, 2), f"{base_url}/browse/{rec['HINIT']}")
                _ps_target_cell(ws.cell(r, 6), rec.get("Current Sprint Target"), base_url)
                _ps_target_cell(ws.cell(r, 7), rec.get("Next Sprint Target"), base_url)
                _ps_link_epic_sheet(wb, rec.get("Epic-JIRA", ""), base_url)
            for col in (5, 6, 7, 9, 10, 11):
                ws.cell(r, col).alignment = Alignment(wrap_text=True, vertical="top")
        n = max(ws.max_row, 200)
        ov = get_column_letter(_PS_COLS.index("Status Override") + 1)
        _ps_status_colors(ws, f"H2:H{n}")
        for rng in (f"H2:H{n}", f"{ov}2:{ov}{n}"):
            dv = DataValidation(type="list", formula1='"' + ",".join(_PS_STATUSES) + '"', allow_blank=True)
            ws.add_data_validation(dv); dv.add(rng)
        for i, wd in enumerate(_PS_WIDTHS, 1):
            ws.column_dimensions[get_column_letter(i)].width = wd

    def _ps_write_epic_sheet(wb, key, stories):
        from openpyxl.worksheet.datavalidation import DataValidation
        from openpyxl.styles import Font, PatternFill
        from openpyxl.utils import get_column_letter
        sn = _ps_epic_sheet(key)
        if sn in wb.sheetnames: del wb[sn]
        ws = wb.create_sheet(sn)
        ws.append(_EPIC_COLS)
        for c in ws[1]:
            c.font = Font(bold=True, color="FFFFFF"); c.fill = PatternFill("solid", fgColor="455A64")
        for s in stories: ws.append([s.get(h) or None for h in _EPIC_COLS])
        dv = DataValidation(type="list", formula1='"Yes,No"', allow_blank=True)
        ws.add_data_validation(dv); dv.add(f"G2:G{max(ws.max_row, 200)}")
        for i, wd in enumerate((14, 60, 14, 16, 12, 22, 12, 16, 12, 14), 1):
            ws.column_dimensions[get_column_letter(i)].width = wd

    def _ps_board_url(target):
        import json as _j, re as _r, openpyxl as _x
        sidecar = target.parent / f"{target.stem}.json"
        if sidecar.exists():
            try:
                u = _j.loads(sidecar.read_text()).get("sprint_url", "")
                if u: return u
            except Exception: pass
        m = _r.match(r'^(.+?)_\d{4}-\d{2}-\d{2}_', target.stem)
        if m and SPRINT_TEMPLATE.exists():
            try:
                wbt = _x.load_workbook(str(SPRINT_TEMPLATE), read_only=True, data_only=True)
                if "Teams" in wbt.sheetnames:
                    for tr in wbt["Teams"].iter_rows(values_only=True):
                        if tr and tr[0] and str(tr[0]).strip() == m.group(1):
                            return str(tr[1]).strip() if len(tr) > 1 and tr[1] else ""
            except Exception: pass
        return ""

    def _ps_quarter_label():
        q, y, _ = _ps_quarter()
        return f"Q{q} {y}"

    def _ps_view_payload(wb):
        out = []
        for rec in _ps_read_sheet(wb):
            stories, prog, auto, status = _ps_row_view(wb, rec)
            qm = _ps_qtr_metrics(stories)
            out.append({**rec, "Status": status, "auto_status": auto, "progress": prog,
                        "qtr": qm, "forecast": _ps_forecast(prog, qm), "stories": stories})
        return out

    def _ps_base_url():
        creds, _ = _jira_creds()
        return (creds or {}).get("base_url", "")

    def _ps_order_recs(recs, old):
        """Keep the user's HINIT/Epic order; unseen HINITs and Epics go after the known ones."""
        gpos, epos = {}, {}
        for i, (k, r) in enumerate(old.items()):
            gpos.setdefault(r.get("HINIT", ""), i); epos[k] = i
        big = 10 ** 6
        return sorted(recs, key=lambda r: (gpos.get(r.get("HINIT", ""), big), r.get("HINIT", ""),
                                           epos.get(r.get("Epic-JIRA"), big), r.get("Epic-JIRA", "")))

    def _ps_jira_getter(creds):
        import requests as _rq, urllib3 as _u3
        from requests.auth import HTTPBasicAuth as _BA
        _u3.disable_warnings()
        auth = _BA(creds["email"], creds["api_token"])
        def _get(path, params=None):
            r = _rq.get(f"{creds['base_url']}{path}", params=params, auth=auth,
                        headers={"Accept": "application/json"}, timeout=30, verify=False)
            if r.status_code != 200:
                raise RuntimeError(f"Jira {path}: HTTP {r.status_code} — {r.text[:200]}")
            return r.json()
        return _get

    def _ps_fetch_epic(_get, wb, ek, sprint_keys, old, hcache, targets=None):
        """Pull one Epic (+ its HINIT and every story) from Jira, write its detail sheet, return its summary record."""
        ep = _get(f"/rest/api/2/issue/{ek}", {"fields": "summary,duedate,created,parent,issuetype"}).get("fields", {})
        if (ep.get("issuetype") or {}).get("name") != "Epic":
            raise ValueError(f"{ek} is not an Epic")
        par = ep.get("parent") or {}
        hk = par.get("key", "") if str(par.get("key", "")).startswith("HINIT") else ""
        hsum, hdue = "", ""
        if hk:
            if hk not in hcache:
                hf = _get(f"/rest/api/2/issue/{hk}", {"fields": "summary,duedate"}).get("fields", {})
                hcache[hk] = (hf.get("summary") or "", hf.get("duedate") or "")
            hsum, hdue = hcache[hk]
        q, y, qstart = _ps_quarter()
        qs = qstart.isoformat()
        SPF = ("summary,status,issuetype,assignee,resolutiondate,customfield_10020,story_points,customfield_10045,"
               "customfield_10016,customfield_10028,customfield_10015,customfield_10032,customfield_10033,customfield_10105")
        prev = {s["JIRA ID"]: s for s in _ps_read_epic(wb, ek)}
        stories, token = [], None
        while True:
            p = {"jql": f"parent = {ek} ORDER BY key", "fields": SPF, "maxResults": 100}
            if token: p["nextPageToken"] = token
            d = _get("/rest/api/3/search/jql", p)
            for it in d.get("issues", []):
                f = it.get("fields") or {}; k = it.get("key")
                sp = _sp_from_fields(f)
                rd = (f.get("resolutiondate") or "")[:10]
                # committed this quarter = in an active sprint, in a sprint that started this quarter, or finished this quarter
                in_q = k in sprint_keys or any(
                    isinstance(x, dict) and (x.get("state") == "active" or str(x.get("startDate") or "")[:10] >= qs)
                    for x in (f.get("customfield_10020") or []))
                stories.append({
                    "JIRA ID": k, "Story": f.get("summary") or "",
                    "Type": (f.get("issuetype") or {}).get("name") or "",
                    "Status": (f.get("status") or {}).get("name") or "",
                    "Story Point": "" if sp is None else str(sp),
                    "Assignee": (f.get("assignee") or {}).get("displayName") or "",
                    "Team Story": (prev.get(k) or {}).get("Team Story") or ("Yes" if k in sprint_keys else "No"),
                    "In Current Sprint": "Yes" if k in sprint_keys else "No",
                    "Resolved": rd,
                    "Qtr Committed": "Yes" if (in_q or (rd and rd >= qs)) else "No"})
            token = d.get("nextPageToken")
            if d.get("isLast", True) or not token: break
        _ps_write_epic_sheet(wb, ek, stories)
        if targets is None:
            targets = [f"• {s['JIRA ID']} - {s['Story']} [{s['Status']}]" for s in stories if s["JIRA ID"] in sprint_keys]
        return {
            "HINIT": hk, "HINIT Due Date": hdue or ep.get("duedate") or old.get("HINIT Due Date", ""),
            "Epic-JIRA": ek,
            "HINIT/Epic goal": old.get("HINIT/Epic goal") or (f"{hsum} / {ep.get('summary') or ''}" if hsum else (ep.get("summary") or "")),
            "Current Sprint Target": "\n".join(targets),
            "Next Sprint Target": old.get("Next Sprint Target", ""),
            "Risk and Mitigation": old.get("Risk and Mitigation", ""),
            "Comments1": old.get("Comments1", ""), "Comments2": old.get("Comments2", ""),
            "Status Override": old.get("Status Override", ""),
            "Epic Created": (ep.get("created") or "")[:10], "Source": old.get("Source", "")}

    def _ps_presentation_sheet(wb, base_url):
        """Export/copy layout (in memory only): one row per current-sprint ticket so just the ticket id is a link."""
        from openpyxl.worksheet.datavalidation import DataValidation
        from openpyxl.styles import Font, PatternFill, Alignment
        from openpyxl.utils import get_column_letter
        ql = _ps_quarter_label()
        cols = ["S.No", "HINIT", "HINIT Due Date", "Epic-JIRA", "HINIT/Epic goal", "Current Sprint Target",
                "Ticket Details", "Next Sprint Target", "Status", "Risk and Mitigation", "Comments1", "Comments2",
                f"Story Points Done ({ql})", f"Story Points Committed ({ql})",
                f"Tickets Done ({ql})", f"Tickets Committed ({ql})", "Velocity (per 2 weeks)"]
        recs = _ps_read_sheet(wb)
        for rec in recs: _ps_link_epic_sheet(wb, rec.get("Epic-JIRA", ""), base_url)
        views = [(rec,) + _ps_row_view(wb, rec) for rec in recs]
        if _PS_SHEET in wb.sheetnames: del wb[_PS_SHEET]
        ws = wb.create_sheet(_PS_SHEET, 0)
        ws.append(cols)
        for c in ws[1]:
            c.font = Font(bold=True, color="FFFFFF"); c.fill = PatternFill("solid", fgColor="1565C0")
            c.alignment = Alignment(wrap_text=True, vertical="center")
        top = Alignment(wrap_text=True, vertical="top")
        for i, (rec, stories, prog, auto, status) in enumerate(views, 1):
            tickets = [l.strip() for l in str(rec.get("Current Sprint Target") or "").split("\n") if l.strip()]
            n = max(1, len(tickets))
            start = ws.max_row + 1
            for _ in range(n): ws.append([None] * len(cols))
            qm = _ps_qtr_metrics(stories)
            vals = {1: i, 2: rec.get("HINIT"), 3: rec.get("HINIT Due Date"), 4: rec.get("Epic-JIRA"),
                    5: rec.get("HINIT/Epic goal"), 8: _ps_bulletize(rec.get("Next Sprint Target")), 9: status,
                    10: rec.get("Risk and Mitigation"), 11: rec.get("Comments1"), 12: rec.get("Comments2"),
                    13: qm["sp_done"], 14: qm["sp_committed"], 15: qm["tickets_done"], 16: qm["tickets_committed"],
                    17: _ps_forecast(prog, qm)["velocity"]}
            for c, v in vals.items():
                cell = ws.cell(start, c); cell.value = v if v not in ("", None) else None; cell.alignment = top
                if n > 1: ws.merge_cells(start_row=start, start_column=c, end_row=start + n - 1, end_column=c)
            if base_url:
                _ps_style_link(ws.cell(start, 4), f"{base_url}/browse/{rec.get('Epic-JIRA', '')}")
                if rec.get("HINIT"): _ps_style_link(ws.cell(start, 2), f"{base_url}/browse/{rec['HINIT']}")
                _ps_target_cell(ws.cell(start, 8), vals[8], base_url)
            for t, line in enumerate(tickets):
                body = line[1:].strip() if line.startswith("•") else line
                m = _PS_KEY_RE.match(body)
                a, b = ws.cell(start + t, 6), ws.cell(start + t, 7)
                a.alignment = top; b.alignment = top
                if m:
                    a.value = "• " + m.group(1)
                    b.value = m.group(2).lstrip(" -").strip() or None
                    if base_url: _ps_style_link(a, f"{base_url}/browse/{m.group(1)}")
                else:
                    a.value = "• " + body
        last = max(ws.max_row, 2)
        dv = DataValidation(type="list", formula1='"' + ",".join(_PS_STATUSES) + '"', allow_blank=True)
        ws.add_data_validation(dv); dv.add(f"I2:I{last}")
        _ps_status_colors(ws, f"I2:I{last}")
        if views:
            tr = last + 1
            ws.cell(tr, 12, "Total")
            tfill = PatternFill("solid", fgColor="455A64")
            for c in range(1, 18):
                ws.cell(tr, c).font = Font(bold=True, color="FFFFFF"); ws.cell(tr, c).fill = tfill
            ws.cell(tr, 12).alignment = Alignment(horizontal="right")
            for c in (13, 14, 15, 16):
                col = get_column_letter(c)
                # merged cells keep their value in the first row only, so a plain SUM over the column is correct
                ws.cell(tr, c, f"=SUM({col}2:{col}{last})").alignment = Alignment(horizontal="center")
            ws.cell(tr, 17, f"=SUM(Q2:Q{last})").alignment = Alignment(horizontal="center")
        for i, wd in enumerate((6, 12, 14, 14, 40, 18, 55, 40, 13, 40, 30, 30, 14, 14, 14, 14, 14), 1):
            ws.column_dimensions[get_column_letter(i)].width = wd
        ws.row_dimensions[1].height = 45

