    @app.route("/api/project-management/sprint/project-summary/refresh", methods=["POST"])
    def api_tm_project_summary_refresh():
        import openpyxl as _xl
        try:
            import requests as _rq_chk  # noqa: F401
        except ImportError:
            return jsonify({"ok": False, "error": "requests library not installed"})
        filename = str((request.get_json() or {}).get("file") or "").strip()
        target = _sprint_team_path(filename) if filename else None
        if not target or not target.exists():
            return jsonify({"ok": False, "error": f"File not found: {filename}"})
        url = _ps_board_url(target)
        if not url:
            return jsonify({"ok": False, "error": "No board URL found — add it to Template.xlsx Teams tab (column B)"})
        creds, cerr = _jira_creds()
        if cerr: return jsonify({"ok": False, "error": cerr})
        issues, ferr = _fetch_board_issues(creds, url)
        if ferr: return jsonify({"ok": False, "error": ferr})
        _get = _ps_jira_getter(creds)
        try:
            sprint_by_epic, no_epic, sprint_keys = {}, 0, set()
            for it in issues or []:
                f = it.get("fields") or {}
                key = it.get("key", "")
                sprint_keys.add(key)
                par = f.get("parent") or {}
                if ((par.get("fields") or {}).get("issuetype") or {}).get("name") == "Epic":
                    ek = par.get("key")
                else:
                    ek = f.get("customfield_10014") if isinstance(f.get("customfield_10014"), str) else None
                if not ek:
                    no_epic += 1; continue
                sprint_by_epic.setdefault(ek, []).append(
                    f"• {key} - {f.get('summary') or ''} [{(f.get('status') or {}).get('name') or ''}]")
            wb = _xl.load_workbook(str(target))
            old = {r.get("Epic-JIRA"): r for r in _ps_read_sheet(wb)}
            manual = [k for k, r in old.items() if r.get("Source") == "Manual" and k not in sprint_by_epic]
            hcache, recs = {}, []
            for ek in list(sprint_by_epic) + manual:
                rec = _ps_fetch_epic(_get, wb, ek, sprint_keys, old.get(ek, {}), hcache, sprint_by_epic.get(ek))
                rec["Source"] = "Manual" if ek in manual else ""
                recs.append(rec)
            recs = _ps_order_recs(recs, old)
            _ps_write_sheet(wb, recs, creds["base_url"])
            wb.save(str(target)); wb.close()
            return jsonify({"ok": True, "epics": len(recs), "no_epic": no_epic})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/project-management/sprint/project-summary/add-epic", methods=["POST"])
    def api_tm_project_summary_add_epic():
        import openpyxl as _xl
        body = request.get_json() or {}
        filename = str(body.get("file") or "").strip()
        m = _PS_KEY_ANY.search(str(body.get("epic") or "").upper())
        target = _sprint_team_path(filename) if filename else None
        if not target or not target.exists() or not m:
            return jsonify({"ok": False, "error": "file and a valid Epic key (e.g. PAYOR-12345) required"})
        ek = m.group(0)
        creds, cerr = _jira_creds()
        if cerr: return jsonify({"ok": False, "error": cerr})
        try:
            wb = _xl.load_workbook(str(target))
            old = {r.get("Epic-JIRA"): r for r in _ps_read_sheet(wb)}
            if ek in old:
                return jsonify({"ok": False, "error": f"{ek} is already in the Project Summary"})
            sprint_keys = set()
            url = _ps_board_url(target)
            if url:
                issues, ferr = _fetch_board_issues(creds, url)
                if not ferr: sprint_keys = {i.get("key") for i in issues or []}
            rec = _ps_fetch_epic(_ps_jira_getter(creds), wb, ek, sprint_keys, {}, {})
            rec["Source"] = "Manual"
            recs = list(old.values()) + [rec]
            recs = _ps_order_recs(recs, old)
            _ps_write_sheet(wb, recs, creds["base_url"])
            wb.save(str(target))
            payload = _ps_view_payload(wb); wb.close()
            return jsonify({"ok": True, "rows": payload})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/project-management/sprint/project-summary/move-hinit", methods=["POST"])
    def api_tm_project_summary_move_hinit():
        import openpyxl as _xl
        body = request.get_json() or {}
        filename = str(body.get("file") or "").strip()
        hinit = str(body.get("hinit") or "")
        step = -1 if body.get("direction") == "up" else 1
        target = _sprint_team_path(filename) if filename else None
        if not target or not target.exists():
            return jsonify({"ok": False, "error": f"File not found: {filename}"})
        try:
            wb = _xl.load_workbook(str(target))
            recs = _ps_read_sheet(wb)
            groups = []
            for r in recs:
                if r.get("HINIT", "") not in groups: groups.append(r.get("HINIT", ""))
            if hinit not in groups:
                return jsonify({"ok": False, "error": f"HINIT not found: {hinit}"})
            i = groups.index(hinit); j = i + step
            if 0 <= j < len(groups):
                groups[i], groups[j] = groups[j], groups[i]
            recs.sort(key=lambda r: groups.index(r.get("HINIT", "")))
            _ps_write_sheet(wb, recs, _ps_base_url())
            wb.save(str(target))
            payload = _ps_view_payload(wb); wb.close()
            return jsonify({"ok": True, "rows": payload})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/project-management/sprint/project-summary/move-epic", methods=["POST"])
    def api_tm_project_summary_move_epic():
        """Move an Epic up/down, but only past other Epics of the same HINIT."""
        import openpyxl as _xl
        body = request.get_json() or {}
        filename = str(body.get("file") or "").strip()
        epic = str(body.get("epic") or "").strip()
        step = -1 if body.get("direction") == "up" else 1
        target = _sprint_team_path(filename) if filename else None
        if not target or not target.exists() or not epic:
            return jsonify({"ok": False, "error": "file and epic required"})
        try:
            wb = _xl.load_workbook(str(target))
            recs = _ps_read_sheet(wb)
            idx = next((i for i, r in enumerate(recs) if r.get("Epic-JIRA") == epic), None)
            if idx is None:
                return jsonify({"ok": False, "error": f"Epic not found: {epic}"})
            j = idx + step
            if 0 <= j < len(recs) and recs[j].get("HINIT", "") == recs[idx].get("HINIT", ""):
                recs[idx], recs[j] = recs[j], recs[idx]
                _ps_write_sheet(wb, recs, _ps_base_url())
                wb.save(str(target))
            payload = _ps_view_payload(wb); wb.close()
            return jsonify({"ok": True, "rows": payload})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

