    @app.route("/api/project-management/sonar-report/ai-job/<job_id>", methods=["GET"])
    def api_sonar_ai_job_status(job_id):
        job = _job_refresh(job_id)
        if not job:
            return jsonify({"ok": False, "error": "Job not found"}), 404
        return jsonify({"ok": True, **_job_view(job)})

    @app.route("/api/project-management/sonar-report/ai-job-latest/<path:filepath>", methods=["GET"])
    def api_sonar_ai_job_latest(filepath):
        best = None
        if _AI_JOBS_DIR.exists():
            for jf in _AI_JOBS_DIR.glob("*.json"):
                j = _job_load(jf.stem)
                if j and j.get("filepath") == filepath and not j.get("dismissed"):
                    if best is None or j.get("created", 0) > best.get("created", 0):
                        best = j
        if not best:
            return jsonify({"ok": True, "job": None})
        best = _job_refresh(best["id"])
        return jsonify({"ok": True, "job": _job_view(best)})

    @app.route("/api/project-management/sonar-report/ai-job-dismiss/<job_id>", methods=["POST"])
    def api_sonar_ai_job_dismiss(job_id):
        with _job_io_lock:
            j = _job_load(job_id)
            if j:
                j["dismissed"] = True
                _job_save(j)
        return jsonify({"ok": True})

    @app.route("/api/project-management/sonar-report/ai-abort/<job_id>", methods=["POST"])
    def api_sonar_ai_abort(job_id):
        import subprocess as _sp
        with _job_io_lock:
            job = _job_load(job_id)
            if not job:
                return jsonify({"ok": False, "error": "Job not found"}), 404
            if job.get("status") != "running":
                return jsonify({"ok": True})
            job["status"] = "aborted"
            job["note"] = "━━ Aborted by user ━━"
            _job_save(job)
        if job.get("pid"):
            _sp.run(["taskkill", "/PID", str(job["pid"]), "/T", "/F"], capture_output=True,
                    creationflags=getattr(_sp, "CREATE_NO_WINDOW", 0))
        return jsonify({"ok": True})

    @app.route("/api/project-management/sonar-report/ai-build/<job_id>", methods=["POST"])
    def api_sonar_ai_build(job_id):
        parent = _job_load(job_id)
        follow = _live_follow(parent) if parent else None
        if not parent or not follow:
            return jsonify({"ok": False, "error": "No change set for this job"}), 404
        mod = str((request.get_json() or {}).get("path") or "")
        if mod not in {m["path"] for m in follow["modules"]}:
            return jsonify({"ok": False, "error": "Unknown module"}), 400
        mdir = (Path(follow["root"]) / mod).resolve()
        ps_cmd = f"Set-Location '{mdir}'; mvn -B clean install"
        jid = _spawn_job("build", ps_cmd, f"$ cd {mdir}\n$ mvn -B clean install\n\n", parent["filepath"], parent["app"],
                         f"building & testing {mod}", [], parent.get("project", ""), follow)
        return jsonify({"ok": True, "job_id": jid})

    @app.route("/api/project-management/sonar-report/ai-git-status/<job_id>", methods=["POST"])
    def api_sonar_ai_git_status(job_id):
        parent = _job_load(job_id)
        follow = (parent or {}).get("follow")
        if not parent or not follow:
            return jsonify({"ok": False, "error": "No change set for this job"}), 404
        rc, out = _git(follow["root"], "status")
        return jsonify({"ok": rc == 0, "output": f"$ git status\n{out}", "root": follow["root"]})

    @app.route("/api/project-management/sonar-report/ai-push/<job_id>", methods=["POST"])
    def api_sonar_ai_push(job_id):
        parent = _job_load(job_id)
        follow = (parent or {}).get("follow")
        if not parent or not follow:
            return jsonify({"ok": False, "error": "No change set for this job"}), 404
        root, branch = follow["root"], follow["branch"]
        if branch in ("", "HEAD", "master", "main", "develop") or branch.startswith("release"):
            return jsonify({"ok": False, "error": f"Refusing to push: '{branch}' is not a feature branch. Check out the PR's feature branch in {root} first."})
        ticket = str((request.get_json() or {}).get("ticket") or follow.get("ticket") or "").strip()
        if not ticket:
            return jsonify({"ok": False, "error": "Ticket ID not found in the branch name"})
        what = "Increased Unit Test Coverage" if follow["kind"] == "coverage" else "Fixed Sonar Issues"
        msg = f"{ticket}: {what}"
        log = []
        for args in (["add", "-A"], ["commit", "-m", msg], ["push"]):
            rc, out = _git(root, *args, timeout=300)
            if rc != 0 and args[0] == "push" and "no upstream" in out.lower():
                log.append(f"$ git push\n{out}")
                args = ["push", "--set-upstream", "origin", branch]
                rc, out = _git(root, *args, timeout=300)
            log.append(f"$ git {' '.join(args)}\n{out}")
            if rc != 0:
                return jsonify({"ok": False, "error": f"git {args[0]} failed", "output": "\n".join(log)})
        # Link to the PR this report belongs to (<repo web url>/pull/<number from the report file name>)
        pr_url = ""
        _, remote = _git(root, "remote", "get-url", "origin")
        _m = _jre.match(r"(?:https://(?:[^@/]+@)?github\.com/|git@github\.com:)([^/]+/[^/]+?)(?:\.git)?/?$", remote.strip())
        _pr = Path(parent["filepath"]).name.split("_")[0]
        if _m and _pr.isdigit():
            pr_url = f"https://github.com/{_m.group(1)}/pull/{_pr}"
        with _job_io_lock:
            for _jf in _AI_JOBS_DIR.glob("*.json"):       # the fix/coverage job and its build jobs share the change set
                _j = _job_load(_jf.stem)
                if _j and _j.get("filepath") == parent["filepath"] and _j.get("follow"):
                    _j["follow"]["pushed"] = True
                    _j["pr_url"] = pr_url
                    _job_save(_j)
        return jsonify({"ok": True, "output": "\n".join(log), "message": msg, "branch": branch, "pr_url": pr_url})

    @app.route("/api/project-management/sonar-report/resolve/<path:filepath>", methods=["POST"])
    def api_sonar_report_resolve(filepath):
        path = _resolve_report_path(filepath)
        if path is None or not path.exists():
            return jsonify({"ok": False, "error": "File not found"}), 404
        body = request.get_json() or {}
        # issues: list of issue # values (1-based), or absent/empty means all
        resolve_all  = bool(body.get("all"))
        issue_nums   = set(str(n) for n in (body.get("issues") or []))
        try:
            import openpyxl as _xl
            wb = _xl.load_workbook(str(path))
            if "Issues" not in wb.sheetnames:
                return jsonify({"ok": False, "error": "Issues sheet not found"})
            ws = wb["Issues"]
            # Find header row (row 1) and locate # col and Resolved col
            headers = [str(ws.cell(1, c).value or '').strip() for c in range(1, ws.max_column + 1)]
            num_col = next((i + 1 for i, h in enumerate(headers) if h == '#'), None)
            res_col = next((i + 1 for i, h in enumerate(headers) if h.lower() == 'resolved'), None)
            if res_col is None:
                res_col = ws.max_column + 1
                ws.cell(1, res_col, 'Resolved')
            for row in range(2, ws.max_row + 1):
                num_val = str(ws.cell(row, num_col).value or '') if num_col else ''
                if resolve_all or num_val in issue_nums:
                    ws.cell(row, res_col, 'Yes')
            wb.save(str(path))
            return jsonify({"ok": True})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    _SONAR_CONFIG_PATH = Path(__file__).parent.parent.parent / "Tools" / "Sonar_Report_Generator" / "sonar_config.xlsx"

    @app.route("/api/project-management/sonar-report/config", methods=["GET"])
    def api_sonar_config_get():
        import openpyxl as _xl
        if not _SONAR_CONFIG_PATH.exists():
            return jsonify({"ok": True, "apps": []})
        try:
            _wb = _xl.load_workbook(str(_SONAR_CONFIG_PATH), read_only=True, data_only=True)
            apps = []
            for _sname in _wb.sheetnames:
                rows = []
                for _row in _wb[_sname].iter_rows(values_only=True):
                    if any(v is not None for v in _row):
                        rows.append([str(_row[0] or ''), str(_row[1] if len(_row) > 1 and _row[1] is not None else '')])
                apps.append({"name": _sname, "rows": rows})
            _wb.close()
            return jsonify({"ok": True, "apps": apps})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/project-management/sonar-report/config", methods=["POST"])
    def api_sonar_config_save():
        import openpyxl as _xl, shutil as _shutil
        body = request.get_json() or {}
        apps = body.get("apps", [])
        try:
            # Collect existing app names before overwriting
            _existing_names = set()
            if _SONAR_CONFIG_PATH.exists():
                try:
                    _tmp = _xl.load_workbook(str(_SONAR_CONFIG_PATH), read_only=True, data_only=True)
                    _existing_names = {s.lower() for s in _tmp.sheetnames}
                    _tmp.close()
                except Exception:
                    pass
            _new_names = {str(a.get("name") or "").strip().lower() for a in apps if str(a.get("name") or "").strip()}
            _removed   = _existing_names - _new_names

            # Write updated config
            _wb = _xl.Workbook()
            _wb.remove(_wb.active)
            for _app in apps:
                _name = str(_app.get("name") or "").strip()
                if not _name:
                    continue
                _ws = _wb.create_sheet(_name)
                for _row in (_app.get("rows") or []):
                    if _row and len(_row) >= 2:
                        _ws.append([str(_row[0]), str(_row[1])])
            _SONAR_CONFIG_PATH.parent.mkdir(parents=True, exist_ok=True)
            _wb.save(str(_SONAR_CONFIG_PATH))

            # Delete report folders for removed apps
            for _rname in _removed:
                _rdir = _SONAR_REPORT_DIR / _rname
                if _rdir.exists() and _rdir.is_dir():
                    try:
                        _shutil.rmtree(str(_rdir))
                    except Exception:
                        pass

            return jsonify({"ok": True})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    # ── IT tab: integration tests (Local/Remote App) ─────────────────────────────────────
    # Config: <Applications>/<App>/it_config.xlsx  → sheet `test_modules` (col A = module dirs),
    # sheet `settings` (key | value, e.g. test_properties). Runs reuse the detached, log-file based
    # job runner so a Workbench restart never kills a test run; only Abort does.
    _IT_NAME_RE = _jre.compile(r"^[A-Za-z0-9_.$-]+$")
    _it_index_cache = {}

    def _it_cfg_path(scope, app_name):
        root = _remote_app_root(app_name) if scope == "remote" else _generic_app_root(app_name)
        return Path(root) / "it_config.xlsx"

    def _it_load(scope, app_name):
        import openpyxl as _xl
        p = _it_cfg_path(scope, app_name)
        modules, props = [], "~/test.properties"
        if p.exists():
            try:
                wb = _xl.load_workbook(str(p), read_only=True, data_only=True)
                if "test_modules" in wb.sheetnames:
                    for r in wb["test_modules"].iter_rows(values_only=True):
                        v = str(r[0] or "").strip() if r else ""
                        if v and v.lower() != "module":
                            modules.append(v)
                if "settings" in wb.sheetnames:
                    for r in wb["settings"].iter_rows(values_only=True):
                        if r and str(r[0] or "").strip().lower() == "test_properties" and len(r) > 1 and r[1]:
                            props = str(r[1]).strip()
                wb.close()
            except Exception:
                pass
        return modules, props

    def _it_srcdir(app_name):
        try:
            if app_name.lower() == "payor":
                return _payor_srcdir()[1]
            return _get_generic_srcdir(app_name) or ""
        except Exception:
            return ""

    # ── Remote apps: the IT tab works on the VM (source clone + ~/test.properties there), over SSH ──────────
    _it_remote_cache = {}

    def _it_vm():
        return str(request.args.get("vm_ip") or "").strip()

    def _it_rexec(app_name, vm_ip, body, timeout=180):
        """Run `body` on the VM after the app's source dir is resolved into $SRCDIR; returns (ok, text-after-marker | error)."""
        cmd = _remote_app_find_repo_cmd(app_name) + "echo __DWB_BEGIN__; " + body
        ok, out, err = _ssh_run(vm_ip, cmd, timeout=timeout)
        if not ok:
            return False, err or out or "SSH failed"
        if "__DWB_BEGIN__" not in out:
            return False, (out or err or "Could not locate the project source on the VM")[:600]
        return True, out.split("__DWB_BEGIN__", 1)[1].lstrip("\r\n")

    def _it_shpath(path):
        """Shell-safe path on the VM; a leading ~ becomes $HOME."""
        import shlex as _shl
        path = (path or "~/test.properties").strip()
        if path == "~":
            return '"$HOME"'
        if path.startswith("~/"):
            return '"$HOME"/' + _shl.quote(path[2:])
        return _shl.quote(path)

    def _it_remote_classes(app_name, modules):
        import time as _tm, shlex as _shl
        vm_ip = _it_vm()
        if not vm_ip:
            return jsonify({"ok": False, "error": "Enter the VM IP at the top of the page first."})
        if not modules:
            return jsonify({"ok": True, "total": 0, "classes": [], "base": "", "changed_total": 0})
        key = (vm_ip, app_name, tuple(modules))
        hit = _it_remote_cache.get(key)
        if not hit or _tm.time() - hit[0] > 900:
            pat = _shl.quote(r"@Test|void test[A-Za-z0-9_]*[[:space:]]*\(")
            body = "for m in " + " ".join(_shl.quote(m) for m in modules) + "; do d=\"$SRCDIR/$m/src/test/java\"; [ -d \"$d\" ] && " \
                   "grep -rlE --include=*.java " + pat + " \"$d\" 2>/dev/null | xargs -r grep -LE 'abstract[[:space:]]+class' 2>/dev/null | " \
                   "sed \"s|^$SRCDIR/||\"; done; true"
            ok, out = _it_rexec(app_name, vm_ip, body, timeout=300)
            if not ok:
                return jsonify({"ok": False, "error": out})
            items = []
            for ln in out.splitlines():
                rel = ln.strip()
                if not rel.endswith(".java"):
                    continue
                mod = next((m for m in modules if rel.startswith(m.rstrip("/") + "/")), "")
                tail = rel.split("/src/test/java/", 1)[-1]
                stem = tail.rsplit("/", 1)[-1][:-5]
                items.append({"cls": stem, "fqcn": tail[:-5].replace("/", "."), "module": mod, "path": rel})
            items.sort(key=lambda c: c["cls"].lower())
            hit = _it_remote_cache[key] = (_tm.time(), items)
        changes, base = {}, ""
        recent = request.args.get("recent") in ("1", "true")
        if recent:
            body = ('cd "$SRCDIR"; B=origin/master; git rev-parse -q --verify $B >/dev/null || B=origin/main; '
                    'MB=$(git merge-base HEAD $B 2>/dev/null); echo "B:$B"; '
                    'git diff --relative --name-status $MB -- ":(glob)**/src/test/**/*.java" 2>/dev/null; '
                    'git ls-files --others --exclude-standard -- ":(glob)**/src/test/**/*.java" 2>/dev/null | sed "s/^/?\\t/"; true')
            ok, out = _it_rexec(app_name, vm_ip, body, timeout=180)
            if not ok:
                return jsonify({"ok": False, "error": out})
            for ln in out.splitlines():
                if ln.startswith("B:"):
                    base = ln[2:].strip()
                elif "\t" in ln:
                    st, pth = ln.split("\t", 1)
                    if st[:1] in ("A", "?"):
                        changes[pth.strip()] = "new"
                    elif st[:1] in ("M", "R", "C"):
                        changes[pth.strip().split("\t")[-1]] = "modified"
        toks = str(request.args.get("q") or "").lower().split()
        out_items = []
        for c in hit[1]:
            name, fq = c["cls"].lower(), c["fqcn"].lower()
            if toks and not all(t in fq for t in toks):
                continue
            ch = changes.get(c["path"], "")
            if recent and not ch:
                continue
            rank = 3 if not toks else (0 if name.startswith(toks[0]) else 1 if all(t in name for t in toks) else 2)
            out_items.append({**c, "changed": ch, "_r": rank})
        out_items.sort(key=lambda c: (c["_r"], c["cls"].lower()))
        for c in out_items:
            c.pop("_r", None)
        return jsonify({"ok": True, "total": len(out_items), "classes": out_items[:200], "base": base,
                        "changed_total": sum(1 for c in out_items if c["changed"])})

    # ── AI Analyzer (Tools/AIAnalyzer): JIRA ticket -> working folder -> agent analysis / RCA ─────────
    _AIA_DIR = WORKFLOWS_ROOT / "Tools" / "AIAnalyzer"

    def _aia():
        import importlib
        if str(_AIA_DIR) not in sys.path:
            sys.path.insert(0, str(_AIA_DIR))
        mod = importlib.import_module("ai_analyzer")
        mod.ensure_files()
        return mod

    def _aia_project_view(mod, p):
        out = dict(p)
        out["folder_exists"] = Path(p["folder_path"]).exists()
        out["has_analysis"] = (Path(p["folder_path"]) / "ANALYSIS.md").exists()
        out["has_rca"] = bool(p.get("rca_file")) and Path(str(p["rca_file"])).exists()
        out["supporting_count"] = len(mod.supporting_files(p)) if Path(p["folder_path"]).exists() else 0
        for kind in ("analyze", "rca"):
            j = mod.read_job(p["id"], kind)
            out[f"{kind}_status"] = j["status"] if j else ""
        return out

    @app.route("/api/ai-analyzer/config", methods=["GET", "POST"])
    def api_aia_config():
        mod = _aia()
        if request.method == "POST":
            body = request.get_json() or {}
            wd = str(body.get("workspace_dir") or "").strip()
            if wd:
                try:
                    Path(wd).mkdir(parents=True, exist_ok=True)
                except OSError as e:
                    return jsonify({"ok": False, "error": f"Cannot use workspace directory: {e}"})
            return jsonify({"ok": True, "config": mod.save_config(body)})
        return jsonify({"ok": True, "config": mod.load_config(), "path": str(mod.CONFIG_FILE)})

    @app.route("/api/ai-analyzer/lookup", methods=["POST"])
    def api_aia_lookup():
        mod = _aia()
        key = mod.extract_key((request.get_json() or {}).get("jira_id", ""))
        if not key:
            return jsonify({"ok": False, "error": "Enter a JIRA ID (e.g. PAYOR-209520) or a ticket URL."})
        creds, err = _jira_creds()
        if err:
            return jsonify({"ok": False, "error": err})
        t, err = mod.fetch_ticket(creds, key)
        if err:
            return jsonify({"ok": False, "error": err})
        return jsonify({"ok": True, "jira_id": key, "title": t["title"], "url": t["url"], "status": t["status"],
                        "folder_name": mod.make_folder_name(key, t["title"])})

    @app.route("/api/ai-analyzer/projects", methods=["GET", "POST"])
    def api_aia_projects():
        mod = _aia()
        if request.method == "GET":
            return jsonify({"ok": True, "projects": [_aia_project_view(mod, p) for p in reversed(mod.list_projects())]})
        body = request.get_json() or {}
        key = mod.extract_key(body.get("jira_id", ""))
        if not key:
            return jsonify({"ok": False, "error": "JIRA ID is required."})
        title = str(body.get("title") or "")
        row, err = mod.create_project(key, title, body.get("folder_name") or mod.make_folder_name(key, title), body.get("url", ""))
        if err:
            return jsonify({"ok": False, "error": err})
        return jsonify({"ok": True, "project": _aia_project_view(mod, row)})

    def _aia_get(mod, pid):
        p = mod.get_project(pid)
        if not p:
            return None, (jsonify({"ok": False, "error": "Unknown project"}), 404)
        if not Path(p["ai_workspace"]).exists():
            Path(p["ai_workspace"]).mkdir(parents=True, exist_ok=True)
        (Path(p["folder_path"]) / "supporting_data").mkdir(parents=True, exist_ok=True)   # also for projects created before this folder existed
        return p, None

    @app.route("/api/ai-analyzer/projects/<int:pid>/<kind>", methods=["POST"])
    def api_aia_run(pid, kind):
        """kind: analyze | rca - starts the agent as a detached job."""
        mod = _aia()
        if kind not in ("analyze", "rca"):
            return jsonify({"ok": False, "error": "Unknown action"}), 400
        p, bad = _aia_get(mod, pid)
        if bad:
            return bad
        cur = mod.read_job(pid, kind)
        if cur and cur["status"] == "running":
            return jsonify({"ok": True, "started": False})
        if kind == "analyze":
            creds, err = _jira_creds()
            if err:
                return jsonify({"ok": False, "error": err})
            t, err = mod.fetch_ticket(creds, p["jira_id"], full=True)
            if err:
                return jsonify({"ok": False, "error": err})
            mod.write_ticket_file(p, t)
            prompt = mod.analyze_prompt(p)
        else:
            if not (Path(p["folder_path"]) / "ticket.md").exists():
                return jsonify({"ok": False, "error": "Run Analyze first - the ticket has not been downloaded yet."})
            mod.rca_path(p).parent.mkdir(parents=True, exist_ok=True)
            prompt = mod.rca_prompt(p)
            mod.update_project(pid, rca_file=str(mod.rca_path(p)))
        ok, err = mod.start_job(p, kind, prompt)
        if err:
            return jsonify({"ok": False, "error": err})
        mod.update_project(pid, status="analyzing" if kind == "analyze" else "rca")
        return jsonify({"ok": True, "started": True})

    @app.route("/api/ai-analyzer/projects/<int:pid>/<kind>/job", methods=["GET"])
    def api_aia_job(pid, kind):
        mod = _aia()
        j = mod.read_job(pid, kind)
        if not j:
            return jsonify({"ok": True, "job": None})
        raw = j.pop("raw", "")
        text = "\n".join(x for x in (_fmt_agent_event(l.rstrip()) for l in raw.splitlines() if l.strip()) if x)
        if j["status"] in ("done", "failed", "aborted"):
            p = mod.get_project(pid)
            if p and p.get("status") in ("analyzing", "rca"):
                mod.update_project(pid, status={"done": "analyzed" if kind == "analyze" else "rca done"}.get(j["status"], j["status"]))
        return jsonify({"ok": True, "job": {**j, "output": text}})

    @app.route("/api/ai-analyzer/projects/<int:pid>/<kind>/abort", methods=["POST"])
    def api_aia_abort(pid, kind):
        return jsonify({"ok": _aia().abort_job(pid, kind)})

    @app.route("/api/ai-analyzer/projects/<int:pid>/open-folder", methods=["POST"])
    def api_aia_open_folder(pid):
        mod = _aia()
        p, bad = _aia_get(mod, pid)
        if bad:
            return bad
        target = (request.get_json() or {}).get("target", "folder")
        path = Path(p["folder_path"])
        if target == "supporting":
            path = path / "supporting_data"
            path.mkdir(parents=True, exist_ok=True)
        if target == "rca" and p.get("rca_file") and Path(str(p["rca_file"])).exists():
            subprocess.Popen(["explorer", "/select,", str(Path(p["rca_file"]))])   # explorer exit code is always 1; ignore
        else:
            subprocess.Popen(["explorer", str(path)])
        return jsonify({"ok": True})

    @app.route("/api/ai-analyzer/projects/<int:pid>/file", methods=["GET"])
    def api_aia_file(pid):
        """Read ANALYSIS.md / RCA / ticket.md to show in the page."""
        mod = _aia()
        p, bad = _aia_get(mod, pid)
        if bad:
            return bad
        which = request.args.get("which", "analysis")
        f = {"analysis": Path(p["folder_path"]) / "ANALYSIS.md", "ticket": Path(p["folder_path"]) / "ticket.md",
             "rca": Path(str(p.get("rca_file") or ""))}.get(which)
        if not f or not f.is_file():
            return jsonify({"ok": True, "exists": False, "text": ""})
        return jsonify({"ok": True, "exists": True, "text": f.read_text(encoding="utf-8", errors="replace")[:300000], "path": str(f)})

    # ── Merge release branch into the checked-out feature branch (local clones) ──────────────────────
    def _mr_release_branch(app_name):
        """Release branch the clone was set up for (payor: ~/.default-branch, others: their branch file)."""
        if app_name.lower() == "payor":
            return _payor_srcdir()[0]
        bf = _LOCAL_APP_DEFAULTS.get(app_name, {}).get("branch_file", "")
        if not bf:
            bf = _read_local_deps(app_name).get("default_branch_file", "").strip()
        if bf:
            p = Path(bf.replace("~", str(Path.home())))
            if p.exists():
                return p.read_text(errors="replace").strip()
        return ""

    def _mr_git(src, *args, timeout=120):
        import subprocess as _sp
        env = dict(os.environ, GIT_TERMINAL_PROMPT="0", GIT_EDITOR="true")
        r = _sp.run(["git", "-C", src, *args], capture_output=True, text=True, timeout=timeout, env=env,
                    encoding="utf-8", errors="replace", creationflags=getattr(_sp, "CREATE_NO_WINDOW", 0))
        return r.returncode, ((r.stdout or "") + (r.stderr or "")).strip()

    def _mr_state(app_name):
        src = _it_srcdir(app_name)
        if not src or not Path(src).exists():
            return None, {"ok": False, "error": "Project source folder not found - set the branch / clone the project first."}
        rc, cur = _mr_git(src, "rev-parse", "--abbrev-ref", "HEAD", timeout=15)
        cur = cur.strip() if rc == 0 else ""
        release = _mr_release_branch(app_name)
        rc, git_dir = _mr_git(src, "rev-parse", "--git-dir", timeout=15)
        gd = Path(git_dir.strip()) if rc == 0 else Path(src) / ".git"
        if not gd.is_absolute():
            gd = Path(src) / gd
        _, unmerged = _mr_git(src, "diff", "--name-only", "--diff-filter=U", timeout=30)
        is_feature = bool(cur) and cur != "HEAD" and cur != release and not _re_team.match(r"(?i)^(master|main|develop|release[-/_.].*|release)$", cur)
        return src, {"ok": True, "current": cur, "release": release, "is_feature": is_feature,
                     "merging": (gd / "MERGE_HEAD").exists(),
                     "conflicts": [f for f in unmerged.splitlines() if f.strip()]}

    @app.route("/api/local-app/<app_name>/merge-release/status", methods=["GET"])
    def api_merge_release_status(app_name):
        _, st = _mr_state(app_name)
        return jsonify(st)

    _MR_JOBS_DIR = TOOL_ROOT / "merge_jobs"

    def _mr_state_file(app_name):
        _MR_JOBS_DIR.mkdir(parents=True, exist_ok=True)
        return _MR_JOBS_DIR / f"{app_name}.json"

    def _mr_pid_alive(pid):
        try:
            r = subprocess.run(["tasklist", "/FI", f"PID eq {int(pid)}", "/NH"], capture_output=True, text=True, timeout=10,
                               creationflags=0x08000000) if sys.platform == "win32" else None
            if r is None:
                os.kill(int(pid), 0)
                return True
            return str(int(pid)) in r.stdout
        except Exception:
            return False

    def _mr_read_job(app_name):
        import json as _jm
        f = _mr_state_file(app_name)
        if not f.exists():
            return None
        try:
            j = _jm.loads(f.read_text(encoding="utf-8"))
        except Exception:
            return None
        if j.get("status") == "running" and not _mr_pid_alive(j.get("pid")):
            j.update(status="error", phase="done", message="The merge process was interrupted (it is no longer running).")
        return j

    def _mr_start_job(app_name, mode, src, release, cur):
        import json as _jm
        f = _mr_state_file(app_name)
        f.write_text(_jm.dumps({"status": "running", "phase": "starting", "mode": mode, "current": cur, "release": release,
                                "output": "", "message": "", "conflicts": [], "started": time.time(), "pid": 0}), encoding="utf-8")
        # detached: survives a Workbench restart; progress is written to the state file by the worker
        flags = (0x00000008 | 0x00000200 | 0x08000000) if sys.platform == "win32" else 0   # DETACHED | NEW_PROCESS_GROUP | NO_WINDOW
        p = subprocess.Popen([sys.executable, str(SCRIPT_DIR / "merge_release_job.py"), mode, src, release, cur, str(f)],
                             stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                             creationflags=flags, close_fds=True)
        j = _jm.loads(f.read_text(encoding="utf-8"))
        if j.get("status") == "running" and not j.get("pid"):
            j["pid"] = p.pid
            f.write_text(_jm.dumps(j), encoding="utf-8")

    @app.route("/api/local-app/<app_name>/merge-release", methods=["POST"])
    def api_merge_release(app_name):
        """Start 'git pull origin <release>' + 'git push origin <feature>' as a detached job."""
        src, st = _mr_state(app_name)
        if not st.get("ok"):
            return jsonify(st)
        cur, release = st["current"], st["release"]
        job = _mr_read_job(app_name)
        if job and job.get("status") == "running":
            return jsonify({"ok": True, "started": False, "job": job})
        if not st["is_feature"]:
            return jsonify({"ok": False, "code": "not_feature", "error": f"'{cur}' is not a feature branch - check out a feature branch first."})
        if not release:
            return jsonify({"ok": False, "error": "Release branch is not set for this project."})
        if st["merging"] or st["conflicts"]:
            return jsonify({"ok": False, "code": "conflict", "conflicts": st["conflicts"], "current": cur, "release": release,
                            "error": "A merge is already in progress with unresolved conflicts."})
        # any local change (modified, staged, deleted or untracked) must be reverted/stashed first
        _, dirty = _mr_git(src, "status", "--porcelain", "--untracked-files=all", timeout=60)
        if dirty.strip():
            return jsonify({"ok": False, "code": "dirty", "files": [l for l in dirty.splitlines() if l.strip()][:50],
                            "error": "You have local changes or untracked files. Revert (or stash/remove) them before merging the release branch."})
        _mr_start_job(app_name, "merge", src, release, cur)
        return jsonify({"ok": True, "started": True, "job": _mr_read_job(app_name)})

    @app.route("/api/local-app/<app_name>/merge-release/job", methods=["GET"])
    def api_merge_release_job(app_name):
        return jsonify({"ok": True, "job": _mr_read_job(app_name)})

    @app.route("/api/local-app/<app_name>/merge-release/job/dismiss", methods=["POST"])
    def api_merge_release_job_dismiss(app_name):
        job = _mr_read_job(app_name)
        if job and job.get("status") != "running":
            try:
                _mr_state_file(app_name).unlink()
            except OSError:
                pass
        return jsonify({"ok": True})

    @app.route("/api/local-app/<app_name>/merge-release/abort", methods=["POST"])
    def api_merge_release_abort(app_name):
        src, st = _mr_state(app_name)
        if not st.get("ok"):
            return jsonify(st)
        rc, out = _mr_git(src, "merge", "--abort", timeout=60)
        if rc == 0:
            try:
                _mr_state_file(app_name).unlink()
            except OSError:
                pass
        return jsonify({"ok": rc == 0, "output": out, "error": "" if rc == 0 else (out or "git merge --abort failed")})

    @app.route("/api/local-app/<app_name>/merge-release/finish", methods=["POST"])
    def api_merge_release_finish(app_name):
        """After the conflicts were resolved in the IDE: complete the merge commit (if needed) and push, as a detached job."""
        src, st = _mr_state(app_name)
        if not st.get("ok"):
            return jsonify(st)
        if st["conflicts"]:
            return jsonify({"ok": False, "code": "conflict", "conflicts": st["conflicts"],
                            "error": "Conflicts are still unresolved in: " + ", ".join(st["conflicts"][:10])})
        _mr_start_job(app_name, "finish", src, st["release"], st["current"])
        return jsonify({"ok": True, "started": True, "job": _mr_read_job(app_name)})

    @app.route("/api/local-app/<app_name>/merge-release/open-ide", methods=["POST"])
    def api_merge_release_open_ide(app_name):
        import glob as _glob, shutil as _shutil
        src, st = _mr_state(app_name)
        if not st.get("ok"):
            return jsonify(st)
        exe = _read_local_tool("intellij_exe")
        if not exe or not Path(exe).exists():
            exe = _shutil.which("idea64") or _shutil.which("idea") or ""
        if not exe or not Path(exe).exists():
            for pf in (r"C:\Program Files (x86)\JetBrains", r"C:\Program Files\JetBrains"):
                m = sorted(_glob.glob(pf + r"\IntelliJ IDEA*\bin\idea64.exe"))
                if m:
                    exe = m[-1]
                    break
        if not exe or not Path(exe).exists():
            return jsonify({"ok": False, "error": "IntelliJ IDEA not found. Add intellij_exe to the 'Local Tools' sheet of app_config.xlsx."})
        args = [exe, src]
        if st["conflicts"]:
            args.append(str(Path(src) / st["conflicts"][0]))   # open the first conflicted file; Git > Resolve Conflicts lists the rest
        try:
            subprocess.Popen(args, creationflags=0x08000000 if sys.platform == "win32" else 0)
            return jsonify({"ok": True})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/it/<scope>/<app_name>/config", methods=["GET"])
    def api_it_config_get(scope, app_name):
        modules, props = _it_load(scope, app_name)
        if scope == "remote":
            return jsonify({"ok": True, "modules": modules, "test_properties": props, "srcdir": "on the VM",
                            "config_path": str(_it_cfg_path(scope, app_name)), "remote": True})
        src = _it_srcdir(app_name)
        if src and Path(src).exists():      # build the class index in the background while the tab opens
            _threading.Thread(target=lambda: _it_index(app_name, modules), daemon=True).start()
        return jsonify({"ok": True, "modules": modules, "test_properties": props, "srcdir": src,
                        "config_path": str(_it_cfg_path(scope, app_name))})

    @app.route("/api/it/<scope>/<app_name>/config", methods=["POST"])
    def api_it_config_save(scope, app_name):
        import openpyxl as _xl
        body = request.get_json() or {}
        modules = [str(m).strip() for m in (body.get("modules") or []) if str(m).strip()]
        props = str(body.get("test_properties") or "~/test.properties").strip()
        p = _it_cfg_path(scope, app_name)
        try:
            p.parent.mkdir(parents=True, exist_ok=True)
            wb = _xl.Workbook()
            ws = wb.active
            ws.title = "test_modules"
            for m in modules:
                ws.append([m])
            st = wb.create_sheet("settings")
            st.append(["test_properties", props])
            wb.save(str(p))
            _it_index_cache.clear()
            _it_remote_cache.clear()
            return jsonify({"ok": True})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    def _it_props_path(scope, app_name):
        _, props = _it_load(scope, app_name)
        return Path(props.replace("~", str(Path.home()), 1)) if props.startswith("~") else Path(props)

    _IT_PROP_RE = _jre.compile(r"^\s*([^#!=:\s][^=:]*?)\s*[=:]\s*(.*?)\s*$")

    def _it_props_apply(lines, new):
        out, seen = [], set()
        for line in lines:
            m = _IT_PROP_RE.match(line)
            if not m:
                out.append(line)
                continue
            k = m.group(1)
            if k not in new or k in seen:      # removed in the UI (or a duplicate definition)
                continue
            seen.add(k)
            out.append(line if m.group(2) == new[k] else f"{k}={new[k]}")
        for k, v in new.items():
            if k not in seen:
                out.append(f"{k}={v}")
        return out

    def _it_remote_props_read(vm_ip, props):
        ok, out, err = _ssh_run(vm_ip, f'P={_it_shpath(props)}; if [ -f "$P" ]; then echo __DWB_EXISTS__; cat "$P"; else echo __DWB_MISSING__; fi', timeout=60)
        if not ok:
            return None, err or out or "SSH failed"
        if "__DWB_EXISTS__" in out:
            return out.split("__DWB_EXISTS__", 1)[1].lstrip("\r\n").splitlines(), ""
        if "__DWB_MISSING__" in out:
            return [], "missing"
        return None, (out or err or "Unexpected reply from the VM")[:400]

    @app.route("/api/it/<scope>/<app_name>/properties", methods=["GET"])
    def api_it_props_get(scope, app_name):
        if scope == "remote":
            vm_ip = _it_vm()
            if not vm_ip:
                return jsonify({"ok": False, "error": "Enter the VM IP first."})
            _, props_loc = _it_load(scope, app_name)
            lines, err = _it_remote_props_read(vm_ip, props_loc)
            if lines is None:
                return jsonify({"ok": False, "error": err})
            props = []
            for line in lines:
                m = _IT_PROP_RE.match(line)
                if m:
                    props.append({"key": m.group(1), "value": m.group(2)})
            return jsonify({"ok": True, "path": f"{vm_ip}:{props_loc}", "exists": err != "missing", "props": props})
        p = _it_props_path(scope, app_name)
        if not p.exists():
            return jsonify({"ok": True, "path": str(p), "exists": False, "props": []})
        props = []
        for line in p.read_text(encoding="utf-8", errors="replace").splitlines():
            m = _IT_PROP_RE.match(line)
            if m:
                props.append({"key": m.group(1), "value": m.group(2)})
        return jsonify({"ok": True, "path": str(p), "exists": True, "props": props})

    @app.route("/api/it/<scope>/<app_name>/properties", methods=["POST"])
    def api_it_props_save(scope, app_name):
        """Apply key/value edits to test.properties in place: comments, blank lines and commented-out
        entries are preserved; changed values are rewritten, removed keys dropped, new keys appended."""
        body = request.get_json() or {}
        new = {}
        for it in body.get("props") or []:
            k = str(it.get("key") or "").strip()
            if k:
                if _jre.search(r"[=:#!\s]", k):
                    return jsonify({"ok": False, "error": f"Invalid key: {k}"})
                new[k] = str(it.get("value") if it.get("value") is not None else "").replace("\r", "").replace("\n", " ")
        if scope == "remote":
            import base64 as _b64
            vm_ip = _it_vm()
            if not vm_ip:
                return jsonify({"ok": False, "error": "Enter the VM IP first."})
            _, props_loc = _it_load(scope, app_name)
            lines, err = _it_remote_props_read(vm_ip, props_loc)
            if lines is None:
                return jsonify({"ok": False, "error": err})
            data = ("\n".join(_it_props_apply(lines, new)) + "\n").encode("utf-8")
            cmd = (f'P={_it_shpath(props_loc)}; [ -f "$P" ] && cp "$P" "$P.bak"; mkdir -p "$(dirname "$P")"; '
                   f'echo {_b64.b64encode(data).decode()} | base64 -d > "$P" && echo __DWB_OK__')
            ok, out, e2 = _ssh_run(vm_ip, cmd, timeout=60)
            if not ok or "__DWB_OK__" not in out:
                return jsonify({"ok": False, "error": e2 or out or "Could not write the file on the VM"})
            return jsonify({"ok": True, "count": len(new)})
        p = _it_props_path(scope, app_name)
        try:
            lines = p.read_text(encoding="utf-8", errors="replace").splitlines() if p.exists() else []
            out = _it_props_apply(lines, new)
            if p.exists():
                import shutil as _sh
                _sh.copyfile(str(p), str(p) + ".bak")
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text("\n".join(out) + "\n", encoding="utf-8")
            return jsonify({"ok": True, "count": len(new)})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    _it_index_lock = _threading.Lock()

    def _it_index(app_name, modules):
        with _it_index_lock:
            return _it_index_locked(app_name, modules)

    def _it_index_locked(app_name, modules):
        """All test classes under <srcdir>/<module>/src/test/java for the configured modules.
        Thousands of files: they are read in parallel and the result is kept for 15 minutes (Rescan refreshes it)."""
        import time as _tm
        from concurrent.futures import ThreadPoolExecutor as _TPE
        src = _it_srcdir(app_name)
        key = (src, tuple(modules))
        hit = _it_index_cache.get(key)
        if hit and _tm.time() - hit[0] < 900:
            return hit[1]
        files = []
        for mod in modules:
            troot = Path(src) / mod / "src" / "test" / "java"
            if troot.is_dir():
                files.extend((mod, f) for f in troot.rglob("*.java"))

        def _one(mf):
            mod, f = mf
            try:
                raw = f.read_bytes()
            except Exception:
                return None
            # cheap byte searches first: the regexes below are slow over ~140 MB of test sources
            if b"@Test" not in raw and b"void test" not in raw:
                return None
            stem = f.stem
            if (b"class " + stem.encode()) not in raw:
                return None
            txt = raw.decode("utf-8", errors="replace")
            if "@Test" not in txt and not _jre.search(r"void\s+test\w*\s*\(", txt):
                return None
            if not _jre.search(r"\bclass\s+" + _jre.escape(stem) + r"\b", txt):
                return None
            if "abstract" in txt and _jre.search(r"\babstract\s+class\s+" + _jre.escape(stem) + r"\b", txt):
                return None
            pm = _jre.search(r"^\s*package\s+([\w.]+)\s*;", txt[:8192], _jre.M)
            return {"cls": stem, "fqcn": (pm.group(1) + "." if pm else "") + stem,
                    "module": mod, "path": str(f.relative_to(src)).replace("\\", "/")}

        with _TPE(max_workers=16) as ex:
            out = [r for r in ex.map(_one, files) if r]
        out.sort(key=lambda c: c["cls"].lower())
        _it_index_cache[key] = (_tm.time(), out)
        return out

    _it_changes_cache = {}

    def _it_changes(app_name):
        """Test files added/modified on the current feature branch (vs its merge-base with master/main,
        or `base_branch` from it_config settings) plus uncommitted work.
        Returns ({repo-relative path: {"whole": bool, "ranges": [(start, end)]}}, base label).
        git is slow on this repo (seconds per command), so the commands run in parallel, the diff is limited to
        test sources, and the result is cached for a short time (Rescan clears it)."""
        import time as _tm
        from concurrent.futures import ThreadPoolExecutor as _TPE
        src = _it_srcdir(app_name)
        if not src or not Path(src).exists():
            return {}, ""
        hit = _it_changes_cache.get(src)
        if hit and _tm.time() - hit[0] < 90:
            return hit[1]
        rc, root = _git(src, "rev-parse", "--show-toplevel")
        if rc != 0:
            return {}, ""
        root = root.strip()
        prefix = ""
        try:
            prefix = str(Path(src).resolve().relative_to(Path(root).resolve())).replace("\\", "/")
            prefix = "" if prefix == "." else prefix + "/"
        except ValueError:
            pass
        spec = ":(glob)**/src/test/**/*.java"

        def _cand(c):
            rc1, mb = _git(root, "merge-base", "HEAD", c)
            if rc1 != 0:
                return None
            rc2, names = _git(root, "diff", "--name-only", mb.strip(), "--", spec)
            return (len(names.splitlines()) if rc2 == 0 else 10**9, mb.strip(), c)

        with _TPE(max_workers=3) as ex:
            f_cands = [ex.submit(_cand, c) for c in ("origin/master", "origin/main")]
            f_untr = ex.submit(_git, root, "ls-files", "--others", "--exclude-standard", "--", spec)
            cands = [x for x in (f.result() for f in f_cands) if x]
            _, untracked = f_untr.result()
        if not cands:
            return {}, ""
        best = min(cands, key=lambda x: x[0])
        rc, diff = _git(root, "diff", "-U0", "--no-color", best[1], "--", spec, timeout=120)
        out, cur, whole = {}, None, False

        def _rel(p):
            return p[len(prefix):] if prefix and p.startswith(prefix) else p
        for ln in diff.splitlines():
            if ln.startswith("diff --git "):
                cur, whole = None, False
            elif ln.startswith("+++ b/"):
                p = _rel(ln[6:].strip())
                if p.endswith(".java") and "/src/test/" in p:
                    cur = out.setdefault(p, {"whole": False, "ranges": []})
                    cur["whole"] = whole
            elif ln.startswith("new file mode") or ln.startswith("--- /dev/null"):
                whole = True
            elif ln.startswith("@@") and cur is not None:
                m = _jre.match(r"@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@", ln)
                if m:
                    s0 = int(m.group(1))
                    c0 = int(m.group(2)) if m.group(2) is not None else 1
                    cur["ranges"].append((s0, s0 + max(c0, 1) - 1))
        # `--- /dev/null` precedes `+++ b/...`, so whole is already set when the file entry is created
        for p in untracked.splitlines():
            p = _rel(p.strip())
            if p.endswith(".java") and "/src/test/" in p:
                out[p] = {"whole": True, "ranges": []}
        res = (out, best[2])
        _it_changes_cache[src] = (_tm.time(), res)
        return res

    @app.route("/api/it/<scope>/<app_name>/classes", methods=["GET"])
    def api_it_classes(scope, app_name):
        modules, _ = _it_load(scope, app_name)
        if request.args.get("refresh"):
            _it_index_cache.clear()
            _it_changes_cache.clear()
            _it_remote_cache.clear()
        if scope == "remote":
            return _it_remote_classes(app_name, modules)
        if not _it_srcdir(app_name) or not Path(_it_srcdir(app_name)).exists():
            return jsonify({"ok": False, "error": "Project source folder not found - set the branch / clone the project first."})
        toks = str(request.args.get("q") or "").lower().split()
        recent = request.args.get("recent") in ("1", "true")
        # git diff only runs for "Recent IT"; plain search stays a fast in-memory filter
        changes, base = _it_changes(app_name) if recent else ({}, "")
        items = []
        for c in _it_index(app_name, modules):
            name, fq = c["cls"].lower(), c["fqcn"].lower()
            if toks and not all(t in fq for t in toks):
                continue
            ch = changes.get(c["path"])
            if recent and not ch:
                continue
            # rank: class name starts with the query, then class name contains it, then package-only matches
            rank = 3 if not toks else (0 if name.startswith(toks[0]) else 1 if all(t in name for t in toks) else 2)
            items.append({**c, "changed": ("new" if ch["whole"] else "modified") if ch else "", "_r": rank})
        items.sort(key=lambda c: (c["_r"], c["cls"].lower()))
        for c in items:
            c.pop("_r", None)
        return jsonify({"ok": True, "total": len(items), "classes": items[:200], "base": base,
                        "changed_total": sum(1 for c in items if c["changed"])})

    @app.route("/api/it/<scope>/<app_name>/methods", methods=["GET"])
    def api_it_methods(scope, app_name):
        rel = str(request.args.get("path") or "")
        if scope == "remote":
            vm_ip = _it_vm()
            if not vm_ip or not _jre.match(r"^[\w./$-]+\.java$", rel) or ".." in rel:
                return jsonify({"ok": False, "error": "Invalid path or VM"}), 400
            ok, txt = _it_rexec(app_name, vm_ip, f'cat "$SRCDIR/{rel}"', timeout=60)
            if not ok:
                return jsonify({"ok": False, "error": txt})
        else:
            src = _it_srcdir(app_name)
            f = (Path(src) / rel).resolve()
            try:
                f.relative_to(Path(src).resolve())
            except ValueError:
                return jsonify({"ok": False, "error": "Invalid path"}), 400
            if not f.is_file() or f.suffix != ".java":
                return jsonify({"ok": False, "error": "File not found"}), 404
            txt = f.read_text(encoding="utf-8", errors="replace")
        found = []   # (start offset, name)
        for m in _jre.finditer(r"@(?:Test|ParameterizedTest|RepeatedTest)\b[^\n]*(?:\n\s*@[^\n]*)*\n\s*(?:public\s+|protected\s+)?(?:static\s+)?void\s+(\w+)\s*\(", txt):
            found.append((m.start(), m.group(1)))
        for m in _jre.finditer(r"\bpublic\s+void\s+(test\w*)\s*\(", txt):
            found.append((m.start(), m.group(1)))
        found.sort()
        seen, uniq, spans = set(), [], {}
        for i, (off, n) in enumerate(found):
            if n in seen:
                continue
            seen.add(n)
            uniq.append(n)
            end = found[i + 1][0] if i + 1 < len(found) else len(txt)
            spans[n] = (txt.count("\n", 0, off) + 1, txt.count("\n", 0, end) + 1)
        ch = None if scope == "remote" else _it_changes(app_name)[0].get(rel)
        changed = []
        if ch:
            for n, (s, e) in spans.items():
                if ch["whole"] or any(a <= e and b >= s for a, b in ch["ranges"]):
                    changed.append(n)
        return jsonify({"ok": True, "methods": uniq, "changed_methods": changed,
                        "class_changed": ("new" if ch["whole"] else "modified") if ch else ""})

    @app.route("/api/it/<scope>/<app_name>/run", methods=["POST"])
    def api_it_run(scope, app_name):
        body   = request.get_json() or {}
        module = str(body.get("module") or "").strip()
        cls    = str(body.get("cls") or "").strip()
        method = str(body.get("method") or "").strip()
        modules, props = _it_load(scope, app_name)
        if module not in modules:
            return jsonify({"ok": False, "error": "Module is not configured as a test module"})
        if not _IT_NAME_RE.match(cls) or (method and not _IT_NAME_RE.match(method)):
            return jsonify({"ok": False, "error": "Invalid test class / method name"})
        if scope == "remote":
            import shlex as _shl
            vm_ip = _it_vm()
            if not vm_ip:
                return jsonify({"ok": False, "error": "Enter the VM IP first."})
            if _jre.search(r'["`$\\\n]', props.lstrip("~")):
                return jsonify({"ok": False, "error": "Invalid test.properties location"})
            target = f"{cls}#{method}" if method else cls
            pfile = _it_shpath(props)
            rcmd = (_remote_app_find_repo_cmd(app_name) +
                    f'cd "$SRCDIR"/{_shl.quote(module)} || exit 1; '
                    f'[ -f {pfile} ] || {{ echo "test.properties not found on the VM: {props}"; exit 1; }}; '
                    f'echo "$ cd $PWD"; echo "$ mvn -B test -Dtest={target} -Dtest.prop.file={props}"; echo; '
                    f'mvn -B test "-Dtest={target}" "-Dtest.prop.file="{pfile} "-DfailIfNoTests=false" "-Dsurefire.failIfNoSpecifiedTests=false"')
            vm_user, vm_pass, vm_key = _lookup_vm_credentials(vm_ip)
            _AI_JOBS_DIR.mkdir(parents=True, exist_ok=True)
            sf = _AI_JOBS_DIR / f"itrun_{_uuid_mod.uuid4().hex}.py"
            sf.write_text(
                "import sys, os, time, pathlib\n"
                "import paramiko\n"
                f"_ip, _user, _pass, _key, _cmd = {vm_ip!r}, {vm_user!r}, {vm_pass!r}, {vm_key!r}, {rcmd!r}\n"
                "try: os.remove(__file__)\n"
                "except Exception: pass\n"
                "c = paramiko.SSHClient(); c.set_missing_host_key_policy(paramiko.AutoAddPolicy())\n"
                "kw = dict(hostname=_ip, port=22, username=_user, timeout=30, allow_agent=False)\n"
                "if _key and pathlib.Path(_key).exists():\n"
                "    kw.update(key_filename=_key, look_for_keys=False)\n"
                "else:\n"
                "    kw['look_for_keys'] = True\n"
                "    if _pass: kw['password'] = _pass\n"
                "c.connect(**kw)\n"
                "ch = c.get_transport().open_session()\n"
                "ch.get_pty(width=220, height=50)\n"
                "ch.exec_command(_cmd)\n"
                "out = sys.stdout.buffer\n"
                "while True:\n"
                "    if ch.recv_ready():\n"
                "        out.write(ch.recv(65536).replace(b'\\r\\n', b'\\n')); out.flush()\n"
                "    elif ch.exit_status_ready():\n"
                "        break\n"
                "    else:\n"
                "        time.sleep(0.05)\n"
                "while ch.recv_ready():\n"
                "    out.write(ch.recv(65536).replace(b'\\r\\n', b'\\n')); out.flush()\n"
                "sys.exit(ch.recv_exit_status())\n", encoding="utf-8")
            jid = _spawn_job("it", f"& '{sys.executable}' -I '{sf}'", f"$ ssh {vm_user}@{vm_ip}\n",
                             f"it/{scope}/{app_name}", app_name, f"running {target} on {vm_ip}", [], "")
            return jsonify({"ok": True, "job_id": jid})
        mdir = Path(_it_srcdir(app_name)) / module
        if not mdir.is_dir():
            return jsonify({"ok": False, "error": f"Module folder not found: {mdir}"})
        props_path = Path(props.replace("~", str(Path.home()), 1)) if props.startswith("~") else Path(props)
        if not props_path.exists():
            return jsonify({"ok": False, "error": f"test.properties not found: {props_path}"})
        target = f"{cls}#{method}" if method else cls
        # mvn is a .cmd batch: cmd.exe splits unquoted args at '=' / '.', so each -D arg gets literal double quotes
        ps_cmd = (f"Set-Location '{mdir}'; mvn -B test '\"-Dtest={target}\"' '\"-Dtest.prop.file={props_path}\"' "
                  "'\"-DfailIfNoTests=false\"' '\"-Dsurefire.failIfNoSpecifiedTests=false\"'")
        header = (f"$ cd {mdir}\n$ mvn -B test -Dtest={target} -Dtest.prop.file={props_path}\n\n")
        # AppMap recording: the pom dependency alone records nothing, the JVM needs the agent + appmap.yml
        try:
            _sd = _it_srcdir(app_name)
            _pm = Path(_sd) / "pom.xml" if _sd else None
            _ptxt = _pm.read_text(encoding="utf-8", errors="replace") if _pm and _pm.exists() else ""
            _amset = _appmap_settings(app_name)
            if _amset["enabled"]:
                import re as _re_am, urllib.request as _ur_am
                _mv = _re_am.search(r"appmap-agent</artifactId>\s*<version>([^<]+)</version>", _ptxt)
                _ver = _mv.group(1).strip() if _mv else _APPMAP_FALLBACK_VERSION
                _have = sorted((_appmap_lib()).glob("appmap-agent-*.jar"), key=lambda q: q.stat().st_mtime) if (_appmap_lib()).is_dir() else []
                _jar = _have[-1] if _have else _appmap_lib() / f"appmap-agent-{_ver}.jar"
                if not _jar.exists() or _jar.stat().st_size < 100000:
                    _jar.parent.mkdir(parents=True, exist_ok=True)
                    _ur_am.urlretrieve(f"https://repo1.maven.org/maven2/com/appland/appmap-agent/{_ver}/appmap-agent-{_ver}.jar", str(_jar))
                _cfg = _appmap_yml_path(app_name)
                _out = _appmap_home(app_name) / "tmp" / "appmap"
                _out.mkdir(parents=True, exist_ok=True)
                _opts = f"-javaagent:{_jar} -Dappmap.config.file={_cfg} -Dappmap.output.directory={_out}" + ("" if _amset["record_values"] else " -Dappmap.event.disableValue=true")
                # JaCoCo (pom argLine) and AppMap both rewrite bytecode; JaCoCo fails on the AppMap-instrumented classes
                ps_cmd = f"$env:JAVA_TOOL_OPTIONS='{_opts}'; " + ps_cmd + " '\"-Djacoco.skip=true\"'"
                header += f"AppMap recording on -> {_out} (JaCoCo skipped for this run)\n\n"
        except Exception as _e_am:
            header += f"AppMap agent not attached: {_e_am}\n\n"
        jid = _spawn_job("it", ps_cmd, header, f"it/{scope}/{app_name}", app_name,
                         f"running {target}", [], str(mdir))
        return jsonify({"ok": True, "job_id": jid})

    # ── CoPilot Review ────────────────────────────────────────────────────────

    _COPILOT_REVIEW_SCRIPT = Path(__file__).parent.parent.parent / "Tools" / "CoPilotReview" / "copilot_review.py"

    # ── AI PR Review: files changed (diffs) + review actions (comment / approve / request changes) + review time ──
    def _gh_pr_call(method, path, **kw):
        import requests as _rq, urllib3 as _u3
        _u3.disable_warnings()
        tok = _scm_github_token()
        if not tok: return None, "github_token is missing in secrets.xlsx (GitHub sheet)"
        H = {"Authorization": "Bearer " + tok, "Accept": "application/vnd.github+json"}
        try:
            return _rq.request(method, "https://api.github.com" + path, headers=H, timeout=60, verify=False, **kw), ""
        except Exception as e:
            return None, "%s: %s" % (type(e).__name__, e)

    def _gh_pr_args(body):
        import re as _r
        o, rp, n = (str(body.get(k) or "").strip() for k in ("owner", "repo", "pr"))
        if not (_r.fullmatch(r"[\w.-]+", o) and _r.fullmatch(r"[\w.-]+", rp) and _r.fullmatch(r"\d+", n)): return None
        return o, rp, n

    @app.route("/api/tools/copilot-review/files", methods=["POST"])
    def api_copilot_review_files():
        a = _gh_pr_args(request.get_json() or {})
        if not a: return jsonify({"ok": False, "error": "owner, repo and pr are required"})
        o, rp, n = a
        pr, err = _gh_pr_call("GET", "/repos/%s/%s/pulls/%s" % (o, rp, n))
        if pr is None or pr.status_code != 200: return jsonify({"ok": False, "error": err or "GitHub returned HTTP %d" % pr.status_code})
        files = []
        for page in range(1, 11):
            r, err = _gh_pr_call("GET", "/repos/%s/%s/pulls/%s/files" % (o, rp, n), params={"per_page": 100, "page": page})
            if r is None or r.status_code != 200: return jsonify({"ok": False, "error": err or "GitHub returned HTTP %d" % r.status_code})
            chunk = r.json()
            files += [{"path": f.get("filename", ""), "status": f.get("status", ""), "additions": f.get("additions", 0),
                       "deletions": f.get("deletions", 0), "patch": f.get("patch", ""), "previous": f.get("previous_filename", "")} for f in chunk]
            if len(chunk) < 100: break
        comments = []
        for page in range(1, 6):
            r, err = _gh_pr_call("GET", "/repos/%s/%s/pulls/%s/comments" % (o, rp, n), params={"per_page": 100, "page": page})
            if r is None or r.status_code != 200: break
            chunk = r.json()
            comments += [{"id": c["id"], "path": c.get("path", ""), "line": c.get("line") or c.get("original_line"),
                          "side": c.get("side") or "RIGHT", "author": (c.get("user") or {}).get("login", ""), "body": c.get("body", ""),
                          "url": c.get("html_url", "")} for c in chunk]
            if len(chunk) < 100: break
        u, _e = _gh_pr_call("GET", "/user")
        me = (u.json().get("login", "") if u is not None and u.status_code == 200 else "")
        my_state = ""                                   # my latest approve / request-changes (a plain comment does not change it)
        rv, _e = _gh_pr_call("GET", "/repos/%s/%s/pulls/%s/reviews" % (o, rp, n), params={"per_page": 100})
        if rv is not None and rv.status_code == 200:
            for x in sorted(rv.json(), key=lambda x: x.get("submitted_at") or ""):
                if (x.get("user") or {}).get("login") == me and x.get("state") in ("APPROVED", "CHANGES_REQUESTED", "DISMISSED"):
                    my_state = "" if x["state"] == "DISMISSED" else x["state"]
        return jsonify({"ok": True, "head_sha": (pr.json().get("head") or {}).get("sha", ""), "files": files, "comments": comments, "me": me, "my_state": my_state,
                        "pr_title": pr.json().get("title", ""), "pr_body": pr.json().get("body") or "", "pr_author": (pr.json().get("user") or {}).get("login", "")})

    @app.route("/api/tools/copilot-review/comment/delete", methods=["POST"])
    def api_copilot_review_comment_delete():
        body = request.get_json() or {}
        a = _gh_pr_args(body)
        if not a: return jsonify({"ok": False, "error": "owner, repo and pr are required"})
        o, rp, _n = a
        try: cid = int(body.get("id"))
        except Exception: return jsonify({"ok": False, "error": "comment id required"})
        c, err = _gh_pr_call("GET", "/repos/%s/%s/pulls/comments/%d" % (o, rp, cid))
        u, _e = _gh_pr_call("GET", "/user")
        if c is None or c.status_code != 200 or u is None or u.status_code != 200:
            return jsonify({"ok": False, "error": err or "Could not read the comment from GitHub"})
        if (c.json().get("user") or {}).get("login") != u.json().get("login"):
            return jsonify({"ok": False, "error": "You can delete only your own comments"})
        r, err = _gh_pr_call("DELETE", "/repos/%s/%s/pulls/comments/%d" % (o, rp, cid))
        if r is None or r.status_code != 204: return jsonify({"ok": False, "error": err or "GitHub returned HTTP %d" % r.status_code})
        return jsonify({"ok": True})

    # Security analyzer: pattern scan of the lines a PR adds (secrets, injection, weak crypto, unsafe exec / deserialization, disabled TLS checks)
    _SEC_RULES = [
        ("Hard-coded secret", "High", r"""(?i)\b(pass(word|wd)?|secret|token|api[_-]?key|private[_-]?key|client[_-]?secret)\b\s*[:=]\s*["'][^"'\s]{6,}["']"""),
        ("Cloud / GitHub credential", "Critical", r"AKIA[0-9A-Z]{16}|gh[pousr]_[A-Za-z0-9]{30,}|xox[baprs]-[A-Za-z0-9-]{10,}"),
        ("Private key material", "Critical", r"-----BEGIN (RSA |EC |DSA |OPENSSH )?PRIVATE KEY-----"),
        ("SQL built by string concatenation", "High", r"""(?i)\b(select|insert\s+into|update|delete\s+from)\b[^;\n]*["']\s*\+|["']\s*\+[^;\n]*\b(where|values)\b"""),
        ("Weak hash / cipher", "Medium", r"""(?i)\b(MD5|SHA-?1|DES|RC4)\b|MessageDigest\.getInstance\(\s*["'](MD5|SHA-?1)["']"""),
        ("OS command execution", "High", r"Runtime\.getRuntime\(\)\.exec|new\s+ProcessBuilder|os\.system\(|subprocess\.\w+\([^)]*shell\s*=\s*True"),
        ("Unsafe deserialization", "High", r"ObjectInputStream|pickle\.loads?\(|yaml\.load\((?!.*SafeLoader)|readObject\("),
        ("TLS / certificate checks disabled", "High", r"verify\s*=\s*False|TrustAll|ALLOW_ALL_HOSTNAME_VERIFIER|setHostnameVerifier|checkServerTrusted\s*\([^)]*\)\s*\{\s*\}"),
        ("XML parser without XXE hardening", "Medium", r"DocumentBuilderFactory\.newInstance|SAXParserFactory\.newInstance|XMLInputFactory\.newInstance"),
        ("Stack trace / debug output", "Low", r"printStackTrace\(\)|System\.(out|err)\.print"),
    ]

    @app.route("/api/tools/copilot-review/security", methods=["POST"])
    def api_copilot_review_security():
        import re as _r
        a = _gh_pr_args(request.get_json() or {})
        if not a: return jsonify({"ok": False, "error": "owner, repo and pr are required"})
        o, rp, n = a
        rules = [(t, s, _r.compile(p)) for t, s, p in _SEC_RULES]
        findings, scanned = [], 0
        for page in range(1, 11):
            r, err = _gh_pr_call("GET", "/repos/%s/%s/pulls/%s/files" % (o, rp, n), params={"per_page": 100, "page": page})
            if r is None or r.status_code != 200: return jsonify({"ok": False, "error": err or "GitHub returned HTTP %d" % r.status_code})
            chunk = r.json()
            for f in chunk:
                path, scanned = f.get("filename", ""), scanned + 1
                if _r.search(r"\.(pem|p12|pfx|jks|keystore)$|(^|/)\.env(\.|$)|id_rsa$", path) and f.get("status") != "removed":
                    findings.append({"path": path, "line": 0, "rule": "Sensitive file added", "severity": "High", "code": path})
                line = 0
                for text in (f.get("patch") or "").split("\n"):
                    h = _r.match(r"^@@ -\d+(?:,\d+)? \+(\d+)", text)
                    if h: line = int(h.group(1)); continue
                    if text.startswith("-") or text.startswith("\\"): continue
                    if text.startswith("+"):
                        code = text[1:]
                        for title, sev, rx in rules:
                            if rx.search(code):
                                findings.append({"path": path, "line": line, "rule": title, "severity": sev, "code": code.strip()[:200]})
                    line += 1
            if len(chunk) < 100: break
        order = {"Critical": 0, "High": 1, "Medium": 2, "Low": 3}
        findings.sort(key=lambda x: (order.get(x["severity"], 9), x["path"], x["line"]))
        return jsonify({"ok": True, "scanned": scanned, "findings": findings})

    @app.route("/api/tools/copilot-review/submit", methods=["POST"])
    def api_copilot_review_submit():
        body = request.get_json() or {}
        a = _gh_pr_args(body)
        if not a: return jsonify({"ok": False, "error": "owner, repo and pr are required"})
        o, rp, n = a
        ev = str(body.get("event") or "").upper()
        if ev not in ("COMMENT", "APPROVE", "REQUEST_CHANGES"): return jsonify({"ok": False, "error": "event must be COMMENT, APPROVE or REQUEST_CHANGES"})
        text = str(body.get("body") or "").strip()
        if ev != "APPROVE" and not text: return jsonify({"ok": False, "error": "A comment is required for this review type"})
        r, err = _gh_pr_call("POST", "/repos/%s/%s/pulls/%s/reviews" % (o, rp, n), json={"event": ev, "body": text})
        if r is None or r.status_code not in (200, 201):
            return jsonify({"ok": False, "error": err or "GitHub returned HTTP %d: %s" % (r.status_code, r.text[:200])})
        return jsonify({"ok": True, "state": r.json().get("state", "")})

    @app.route("/api/tools/copilot-review/comment", methods=["POST"])
    def api_copilot_review_comment():
        body = request.get_json() or {}
        a = _gh_pr_args(body)
        if not a: return jsonify({"ok": False, "error": "owner, repo and pr are required"})
        o, rp, n = a
        text, path, sha = str(body.get("body") or "").strip(), str(body.get("path") or ""), str(body.get("commit_id") or "")
        try: line = int(body.get("line"))
        except Exception: line = 0
        if not (text and path and sha and line > 0): return jsonify({"ok": False, "error": "comment text, file, line and commit are required"})
        side = "LEFT" if str(body.get("side")).upper() == "LEFT" else "RIGHT"
        r, err = _gh_pr_call("POST", "/repos/%s/%s/pulls/%s/comments" % (o, rp, n),
                             json={"body": text, "commit_id": sha, "path": path, "line": line, "side": side})
        if r is None or r.status_code not in (200, 201):
            return jsonify({"ok": False, "error": err or "GitHub returned HTTP %d: %s" % (r.status_code, r.text[:200])})
        return jsonify({"ok": True, "url": r.json().get("html_url", ""), "comment": {
            "id": r.json().get("id"), "path": path, "line": line, "side": side,
            "author": (r.json().get("user") or {}).get("login", ""), "body": text, "url": r.json().get("html_url", "")}})

    # Review time lives in the sprint workbook, sheet "PR Reviews" (columns JIRA ID, PR, Review Time as h:mm)
    import threading as _rt_th
    _rt_lock = _rt_th.Lock()

    def _rt_parse(v):
        try:
            h, m = str(v or "0:00").split(":")[:2]
            return int(h) * 60 + int(m)
        except Exception:
            return 0

    def row_secs(ws, row, si, ti):
        """Seconds recorded for a PR row (exact seconds column when present, else the h:mm text)."""
        try:
            if si >= 0: return int(float(ws.cell(row=row, column=si + 1).value))
        except Exception:
            pass
        return _rt_parse(ws.cell(row=row, column=ti + 1).value) * 60

    @app.route("/api/project-management/sprint/pr-review-time", methods=["GET", "POST"])
    def api_sprint_pr_review_time():
        import openpyxl as _xl
        body = request.get_json(silent=True) or {}
        filename = str(request.args.get("file") or body.get("file") or "").strip()
        if not filename: return jsonify({"ok": False, "error": "file required"})
        target = _sprint_team_path(filename)
        if not target.exists(): return jsonify({"ok": False, "error": "File not found: %s" % filename})
        try:
          with _rt_lock:
            wb = _xl.load_workbook(str(target))
            ws = wb["PR Reviews"] if "PR Reviews" in wb.sheetnames else wb.create_sheet("PR Reviews")
            if ws.max_row < 1 or not any(c.value for c in ws[1]): ws.append(["JIRA ID", "PR", "Review Time"])
            head = [str(c.value or "") for c in ws[1]]
            for h in ("JIRA ID", "PR", "Review Time", "Review Seconds"):
                if h not in head:
                    head.append(h)
                    ws.cell(row=1, column=len(head), value=h)
            ji, pi, ti, si = head.index("JIRA ID"), head.index("PR"), head.index("Review Time"), head.index("Review Seconds")
            rows = {str(ws.cell(row=r, column=pi + 1).value or "").strip(): r for r in range(2, ws.max_row + 1)}
            if request.method == "GET":
                import re as _r
                def lab(s): return "%d:%02d" % (s // 60 // 60, s // 60 % 60)
                def secs(row): return row_secs(ws, row, si, ti)
                mine = {u: secs(r) for u, r in rows.items() if u}
                # earlier sprints of the same team: time already spent on the same PRs (spill-over)
                prev, cur_date = {}, (_r.search(r"(\d{4}-\d{2}-\d{2})", filename) or [None, ""])[1]
                team = _team_from_sprint_filename(filename)
                for root in (SPRINT_DATA / "Sprints" / team, SPRINT_DATA / "PreviousSprints" / team) if team else ():
                    for p in (root.glob("*.xlsx") if root.exists() else []):
                        pd = (_r.search(r"(\d{4}-\d{2}-\d{2})", p.name) or [None, ""])[1]
                        if p.name == filename or not pd or not cur_date or pd >= cur_date: continue
                        try:
                            wb2 = _xl.load_workbook(str(p), read_only=False, data_only=True)
                            if "PR Reviews" not in wb2.sheetnames: continue
                            w2 = wb2["PR Reviews"]
                            h2 = [str(c.value or "") for c in w2[1]]
                            if "PR" not in h2 or "Review Time" not in h2: continue
                            p2, t2 = h2.index("PR"), h2.index("Review Time")
                            s2 = h2.index("Review Seconds") if "Review Seconds" in h2 else -1
                            for rr in range(2, w2.max_row + 1):
                                u = str(w2.cell(row=rr, column=p2 + 1).value or "").strip()
                                if u: prev[u] = prev.get(u, 0) + row_secs(w2, rr, s2, t2)
                        except Exception:
                            continue
                return jsonify({"ok": True, "times": {u: lab(s) for u, s in mine.items()}, "seconds": mine,
                                "previous": {u: lab(s) for u, s in prev.items() if s}, "total": lab(sum(mine.values())),
                                "count": sum(1 for s in mine.values() if s > 0),
                                "average": lab(sum(mine.values()) // max(1, sum(1 for s in mine.values() if s > 0)))})
            pr = str(body.get("pr") or "").strip()
            if not pr: return jsonify({"ok": False, "error": "pr required"})
            try: add = max(0, int(float(body.get("seconds") or 0)))
            except Exception: add = 0
            r = rows.get(pr)
            if r is None:
                r = ws.max_row + 1
                ws.cell(row=r, column=pi + 1, value=pr)
            if body.get("jira_id"): ws.cell(row=r, column=ji + 1, value=str(body["jira_id"]).upper())
            try: prev = int(float(ws.cell(row=r, column=si + 1).value))
            except Exception: prev = _rt_parse(ws.cell(row=r, column=ti + 1).value) * 60
            tot = (prev + add) // 60                                 # seconds are kept so small autosaves add up exactly
            label = "%d:%02d" % (tot // 60, tot % 60)
            ws.cell(row=r, column=si + 1, value=prev + add)
            ws.cell(row=r, column=ti + 1, value=label)
            wb.save(str(target))
            return jsonify({"ok": True, "time": label})
        except PermissionError:
            return jsonify({"ok": False, "error": "The sprint file is open in another program - close it and try again"})
        except Exception as e:
            return jsonify({"ok": False, "error": "%s: %s" % (type(e).__name__, e)})

    @app.route("/api/tools/copilot-review/fetch", methods=["POST"])
    def api_copilot_review_fetch():
        import subprocess as _sp, sys as _sys, json as _json
        body  = request.get_json() or {}
        owner = str(body.get("owner") or "").strip()
        repo  = str(body.get("repo")  or "").strip()
        pr    = str(body.get("pr")    or "").strip()
        if not owner or not repo or not pr:
            return jsonify({"ok": False, "error": "owner, repo and pr are required"})
        if not _COPILOT_REVIEW_SCRIPT.exists():
            return jsonify({"ok": False, "error": f"Script not found: {_COPILOT_REVIEW_SCRIPT}"})
        pr_url = f"https://github.com/{owner}/{repo}/pull/{pr}"
        try:
            result = _sp.run(
                [_sys.executable, str(_COPILOT_REVIEW_SCRIPT), "--url", pr_url],
                capture_output=True, text=True, timeout=60,
                creationflags=0x08000000,
            )
        except _sp.TimeoutExpired:
            return jsonify({"ok": False, "error": "Request timed out after 60 seconds"})
        except Exception as e:
            return jsonify({"ok": False, "error": f"Failed to run script: {e}"})
        if result.returncode != 0:
            err = (result.stderr or result.stdout or "Unknown error").strip()
            return jsonify({"ok": False, "error": err})
        try:
            data = _json.loads(result.stdout)
            return jsonify({"ok": True, **data})
        except Exception as e:
            return jsonify({"ok": False, "error": f"Failed to parse output: {e}\n{result.stdout[:300]}"})

    # Tools\AI_PR_Review_Tool\config.xlsx: baseline project (a jQAssistant code base) + dependency analyzer on/off
    _PRR_XLSX = Path(__file__).parent.parent.parent / "Tools" / "AI_PR_Review_Tool" / "config.xlsx"
    _PRR_DEFAULTS = [("baseline_project", "payor", "jQAssistant application whose analyzed dependencies are the baseline"),
                     ("dependency_analyzer", "on", "on / off - dependency report in AI PR Review"),
                     ("test_case_analyzer", "on", "on / off - test case report in AI PR Review")]

    def _prr_cfg(updates=None):
        import openpyxl as _xl
        if _PRR_XLSX.exists():
            wb = _xl.load_workbook(str(_PRR_XLSX))
        else:
            wb = _xl.Workbook()
            wb.active.title = "config"
            wb.active.append(["key", "value", "description"])
            for k, v, d in _PRR_DEFAULTS:
                wb.active.append([k, v, d])
            _PRR_XLSX.parent.mkdir(parents=True, exist_ok=True)
            wb.save(str(_PRR_XLSX))
        ws = wb["config"] if "config" in wb.sheetnames else wb.active
        cfg = {str(r[0].value): ("" if r[1].value is None else str(r[1].value)) for r in ws.iter_rows(min_row=2) if r[0].value}
        if updates:
            for k, v in updates.items():
                row = next((r for r in ws.iter_rows(min_row=2) if r[0].value == k), None)
                if row:
                    row[1].value = v
                else:
                    ws.append([k, v])
                cfg[k] = v
            wb.save(str(_PRR_XLSX))
        for k, v, _d in _PRR_DEFAULTS:
            cfg.setdefault(k, v)
        return cfg

    try:
        _prr_cfg()          # create Tools\AI_PR_Review_Tool\config.xlsx up front
    except Exception:
        pass

    @app.route("/api/tools/ai-pr-review/config", methods=["GET", "POST"])
    def api_prr_config():
        if request.method == "POST":
            b = request.get_json(silent=True) or {}
            upd = {}
            if "baseline_project" in b:
                upd["baseline_project"] = str(b["baseline_project"]).strip()
            if "dependency_analyzer" in b:
                upd["dependency_analyzer"] = "on" if str(b["dependency_analyzer"]).lower() in ("on", "true", "1", "yes") else "off"
            if "test_case_analyzer" in b:
                upd["test_case_analyzer"] = "on" if str(b["test_case_analyzer"]).lower() in ("on", "true", "1", "yes") else "off"
            if upd:
                try:
                    _prr_cfg(upd)
                except PermissionError:
                    return jsonify({"ok": False, "error": "config.xlsx is open - close it and retry"}), 500
        cfg = _prr_cfg()
        try:
            apps = [a["name"] for a in _jqa_cfg()["apps"]]
        except Exception:
            apps = []
        return jsonify({"ok": True, "baseline_project": cfg["baseline_project"], "dependency_analyzer": cfg["dependency_analyzer"].lower() != "off",
                        "test_case_analyzer": cfg["test_case_analyzer"].lower() != "off",
                        "jqassistant_apps": apps, "config_file": str(_PRR_XLSX)})

    def _prr_baseline(name):
        """{ 'group:artifact': {versions} } from the analyzed jQAssistant baseline project, or None if not analyzed."""
        import json as _j
        try:
            r = _j.loads((_JQA_HOME / "results" / (_jqa_safe(name) + ".json")).read_text(encoding="utf-8"))
        except Exception:
            return None
        out = {}
        for m in r.get("modules", []):
            for d in m.get("deps", []):
                out.setdefault("%s:%s" % (d["group"], d["artifact"]), set()).add(d["version"])
        return out or None

    @app.route("/api/tools/copilot-review/dependencies", methods=["POST"])
    def api_copilot_review_dependencies():
        """Dependency report of a PR (added / removed / updated / duplicates), compared with the baseline project."""
        import subprocess as _sp, sys as _sys, json as _json
        cfgd = _prr_cfg()
        if cfgd["dependency_analyzer"].lower() == "off":
            return jsonify({"ok": True, "disabled": True})
        body = request.get_json() or {}
        owner, repo, pr = (str(body.get(k) or "").strip() for k in ("owner", "repo", "pr"))
        if not owner or not repo or not pr:
            return jsonify({"ok": False, "error": "owner, repo and pr are required"})
        if not _COPILOT_REVIEW_SCRIPT.exists():
            return jsonify({"ok": False, "error": f"Script not found: {_COPILOT_REVIEW_SCRIPT}"})
        try:
            r = _sp.run([_sys.executable, str(_COPILOT_REVIEW_SCRIPT), "--deps", "--url", f"https://github.com/{owner}/{repo}/pull/{pr}"],
                        capture_output=True, text=True, timeout=180, creationflags=0x08000000)
        except _sp.TimeoutExpired:
            return jsonify({"ok": False, "error": "Request timed out"})
        if r.returncode != 0:
            return jsonify({"ok": False, "error": (r.stderr or r.stdout or "Unknown error").strip()[-600:]})
        try:
            rep = _json.loads(r.stdout)
        except Exception as e:
            return jsonify({"ok": False, "error": f"Failed to parse output: {e}"})
        # compare the PR's new / updated versions with the baseline project's versions
        bname = cfgd["baseline_project"].strip()
        bl = _prr_baseline(bname) if bname else None
        rep["baseline"] = {"project": bname, "available": bl is not None}
        if bl is None:
            rep["note"] = ((rep.get("note") or "") + " Baseline project '%s' has no analysis results - analyze it in jQAssistant to enable the baseline comparison." % bname).strip()
        mism = 0
        for sec, vkey in (("added", "version"), ("updated", "to_version")):
            for e in rep.get(sec, []):
                if bl is None:
                    e["baseline_status"], e["baseline_versions"] = "", ""
                    continue
                bv = sorted(bl.get("%s:%s" % (e.get("group"), e.get("artifact")), []))
                if not bv:
                    e["baseline_status"], e["baseline_versions"] = "not in baseline", ""
                elif e.get(vkey) in bv:
                    e["baseline_status"], e["baseline_versions"] = "match", ", ".join(bv)
                else:
                    e["baseline_status"], e["baseline_versions"] = "MISMATCH", ", ".join(bv)
                    mism += 1
        rep["totals"]["baseline_mismatch"] = mism
        return jsonify({"ok": True, **rep})

    @app.route("/api/tools/copilot-review/dependencies/export", methods=["POST"])
    def api_copilot_review_dependencies_export():
        """Export the dependency report (sent back by the page) as json / csv / html."""
        import json as _j, csv as _csv, io as _io, html as _h, datetime as _dt
        body = request.get_json() or {}
        fmt, rep = str(body.get("format", "json")).lower(), body.get("report") or {}
        pr = rep.get("pr") or {}
        fname = "dependency-report-%s-pr%s" % (str(pr.get("repo", "repo")).replace("/", "_"), pr.get("number", ""))
        SECTIONS = [("added", "New Dependencies Added"), ("removed", "Dependencies Removed"), ("updated", "Dependencies Updated"),
                    ("dup_module", "Duplicate Dependencies - same module"), ("dup_repo", "Duplicate Dependencies - version mismatch in repository")]
        cols = ["Section", "Module", "File", "Group", "Artifact", "Version / From", "To", "Scope / From", "To Scope", "Line",
                "Placeholder", "Baseline Version(s)", "Baseline Status", "Caused by PR"]
        PH_COLS = ["Placeholder", "Used By", "Value", "Base Value", "Mismatch", "Defined In", "Line", "Caused by PR"]
        scope = str(body.get("scope", "all")).lower()      # all = overall issues, pr = issues caused by the PR only
        yn = lambda e: "yes" if e.get("pr") else "no"

        def row(sec, e):
            if sec == "updated":
                return [sec, e.get("module"), e.get("file"), e.get("group"), e.get("artifact"), e.get("from_version"), e.get("to_version"),
                        e.get("from_scope"), e.get("to_scope"), e.get("line"), e.get("placeholder", ""),
                        e.get("baseline_versions", ""), e.get("baseline_status", ""), yn(e)]
            return [sec, e.get("module"), e.get("file"), e.get("group"), e.get("artifact"), e.get("version"), "", e.get("scope"), "", e.get("line"),
                    e.get("placeholder", ""), e.get("baseline_versions", ""), e.get("baseline_status", ""), yn(e)]

        def pick(sec, only_pr):
            return [e for e in rep.get(sec, []) if not only_pr or e.get("pr") or sec in ("added", "removed", "updated")]

        def ph_rows(only_pr):
            return [[p.get("key"), p.get("used_by"), p.get("value"), p.get("base_value", ""), "MISMATCH" if p.get("mismatch") else "", p.get("file"), p.get("line"), yn(p)]
                    for p in rep.get("placeholders", []) if not only_pr or p.get("pr")]
        if fmt == "json":
            # json: the report as is, plus an "issues" block that splits overall issues from the ones caused by the PR
            def view(only_pr):
                v = {sec: pick(sec, only_pr) for sec, _t in SECTIONS}
                v["placeholders"] = [p for p in rep.get("placeholders", []) if not only_pr or p.get("pr")]
                v["counts"] = {k: len(x) for k, x in v.items()}
                return v
            data, mime, ext = _j.dumps({**rep, "issues": {"overall": view(False), "pr_only": view(True)}}, indent=2), "application/json", "json"
        elif fmt == "xlsx":
            import openpyxl as _xl
            from openpyxl.styles import Font as _F, PatternFill as _P
            wb = _xl.Workbook()
            wb.remove(wb.active)
            for sheet, only_pr in (("Overall", False), ("PR Only", True)):
                ws2 = wb.create_sheet("Placeholders" if not only_pr else "Placeholders (PR)", 0 if not only_pr else 1)
                ws2.append(PH_COLS)
                for r_ in ph_rows(only_pr):
                    ws2.append(r_)
                    if r_[4] == "MISMATCH":
                        for c in ws2[ws2.max_row]:
                            c.font = _F(color="B71C1C", bold=True)
                            c.fill = _P("solid", fgColor="FFEBEE")
                for c in ws2[1]:
                    c.font = _F(bold=True, color="FFFFFF")
                    c.fill = _P("solid", fgColor="1565C0")
                ws = wb.create_sheet(sheet)
                ws.append(cols)
                for sec, _t in SECTIONS:
                    for e in pick(sec, only_pr):
                        ws.append(row(sec, e))
                        if e.get("baseline_status") == "MISMATCH":
                            for c in ws[ws.max_row]:
                                c.font = _F(color="B71C1C", bold=True)
                                c.fill = _P("solid", fgColor="FFEBEE")
                ws.freeze_panes = "A2"
                hdr = ws[1]
                for c in hdr:
                    c.font = _F(bold=True, color="FFFFFF")
                    c.fill = _P("solid", fgColor="1565C0")
            for w_ in wb.worksheets:
                for col in w_.columns:
                    w_.column_dimensions[col[0].column_letter].width = min(60, max(10, max(len(str(c.value or "")) for c in col) + 2))
            buf = _io.BytesIO()
            wb.save(buf)
            data, mime, ext = buf.getvalue(), "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", "xlsx"
        elif fmt == "csv":
            buf = _io.StringIO()
            w = _csv.writer(buf)
            only_pr = scope == "pr"
            w.writerow(["Placeholders"])
            w.writerow(PH_COLS)
            for r_ in ph_rows(only_pr):
                w.writerow(r_)
            w.writerow([])
            w.writerow(cols)
            for sec, _t in SECTIONS:
                for e in pick(sec, only_pr):
                    w.writerow(row(sec, e))
            data, mime, ext = "\ufeff" + buf.getvalue(), "text/csv", "csv"
            if only_pr:
                fname += "-pr-only"
        elif fmt == "html":
            out = ["<html><head><meta charset='utf-8'><title>Dependency report</title><style>body{font-family:Segoe UI,Arial;margin:24px}"
                   "table{border-collapse:collapse;font-size:13px;margin-bottom:22px}td,th{border:1px solid #ccc;padding:4px 8px}"
                   "th{background:#1565c0;color:#fff}h3{margin-bottom:6px}</style></head><body>",
                   "<h2>Dependency report - %s PR #%s</h2><p>%s &middot; generated %s</p>" % (
                       _h.escape(str(pr.get("repo", ""))), _h.escape(str(pr.get("number", ""))), _h.escape(str(pr.get("title", ""))),
                       _dt.datetime.now().strftime("%Y-%m-%d %H:%M")),
                   "<p>Baseline project: <b>%s</b> &middot; %s &middot; <span style='color:#b71c1c'><b>%s</b> version mismatch(es) with the baseline</span></p>" % (
                       _h.escape(str((rep.get("baseline") or {}).get("project", ""))),
                       "analysis available" if (rep.get("baseline") or {}).get("available") else "baseline not analyzed",
                       (rep.get("totals") or {}).get("baseline_mismatch", 0))]
            out[0] = out[0].replace("</style>", ".tab{display:none}.tab.on{display:block}.tb{padding:6px 14px;border:1px solid #1565c0;"
                                    "background:#fff;color:#1565c0;cursor:pointer;font-weight:600}.tb.on{background:#1565c0;color:#fff}</style>", 1)
            out.append("<div style='margin:12px 0'><button class='tb on' onclick=\"sw(0)\">Overall issues</button>"
                          "<button class='tb' onclick=\"sw(1)\">Issues caused by this PR</button></div>"
                          "<script>function sw(i){document.querySelectorAll('.tab').forEach(function(t,n){t.classList.toggle('on',n==i)});"
                          "document.querySelectorAll('.tb').forEach(function(t,n){t.classList.toggle('on',n==i)})}</script>")
            for ti, only_pr in enumerate((False, True)):
                out.append("<div class='tab%s'>" % (" on" if ti == 0 else ""))
                prs = ph_rows(only_pr)
                out.append("<h3>Placeholders (%d)</h3>" % len(prs))
                if prs:
                    out.append("<table><tr>" + "".join("<th>%s</th>" % x for x in PH_COLS) + "</tr>" +
                               "".join("<tr%s>" % (" style='background:#ffebee;color:#b71c1c;font-weight:600'" if r_[4] == "MISMATCH" else "") + "".join("<td>%s</td>" % _h.escape(str(c if c is not None else "")) for c in r_) + "</tr>" for r_ in prs) + "</table>")
                else:
                    out.append("<p>None</p>")
                for sec, title in SECTIONS:
                    items = pick(sec, only_pr)
                    out.append("<h3>%s (%d)</h3>" % (title, len(items)))
                    if not items:
                        out.append("<p>None</p>")
                        continue
                    out.append("<table><tr>" + "".join("<th>%s</th>" % x for x in cols[1:]) + "</tr>")
                    for e in items:
                        mm = e.get("baseline_status") == "MISMATCH"
                        out.append("<tr%s>" % (" style='background:#ffebee;color:#b71c1c;font-weight:600'" if mm else "") +
                                   "".join("<td>%s</td>" % _h.escape(str(c if c is not None else "")) for c in row(sec, e)[1:]) + "</tr>")
                    out.append("</table>")
                out.append("</div>")
            if rep.get("note"):
                out.append("<p><i>%s</i></p>" % _h.escape(rep["note"]))
            out.append("</body></html>")
            data, mime, ext = "\n".join(out), "text/html", "html"
        else:
            return jsonify({"ok": False, "error": "Unknown format"}), 400
        from flask import Response as _Resp
        return _Resp(data, mimetype=mime + ("" if ext == "xlsx" else "; charset=utf-8"), headers={"Content-Disposition": 'attachment; filename="%s.%s"' % (fname, ext)})

