    # ── Regression Parity Checker (Tools) ────────────────────────────────────
    def _rpc_fetch(job_url, auth):
        """{test id: {class, name, state}} from a Jenkins build's test report. state: passed / failed / disabled."""
        import requests as _rq, re as _re, urllib3 as _u3
        _u3.disable_warnings()
        u = job_url.strip().split("?")[0].rstrip("/")
        if "/testReport" in u:
            u = u.split("/testReport")[0]
        if not _re.search(r"/(\d+|last\w*Build)$", u):
            u += "/lastCompletedBuild"
        r = _rq.get(u + "/testReport/api/json", auth=auth, timeout=120, verify=False,
                    params={"tree": "suites[cases[className,name,status,skipped]],childReports[result[suites[cases[className,name,status,skipped]]]]"})
        if r.status_code == 404:
            raise ValueError("No test report found at %s (is it a build with a published test report?)" % u)
        if r.status_code in (401, 403):
            raise ValueError("Jenkins rejected the credentials (HTTP %s) for %s" % (r.status_code, u))
        r.raise_for_status()
        d = r.json()
        suites = list(d.get("suites") or [])
        for ch in d.get("childReports") or []:
            suites += (ch.get("result") or {}).get("suites") or []
        out = {}
        for su in suites:
            for c in su.get("cases") or []:
                st = str(c.get("status") or "").upper()
                state = "disabled" if (c.get("skipped") or st == "SKIPPED") else ("failed" if st in ("FAILED", "REGRESSION") else "passed")
                cls, nm = c.get("className") or "", c.get("name") or ""
                tid = (cls + "." + nm) if cls else nm
                prev = out.get(tid)
                # a duplicate id keeps the worst outcome
                if prev is None or (state == "failed") or (state == "disabled" and prev["state"] == "passed"):
                    out[tid] = {"id": tid, "class": cls, "name": nm, "state": state}
        return out

    @app.route("/api/tools/regression-parity/check", methods=["POST"])
    def api_regression_parity_check():
        import openpyxl as _xl, datetime as _dt
        b = request.get_json() or {}
        bl_url, rg_url = str(b.get("baseline_url") or "").strip(), str(b.get("regression_url") or "").strip()
        if not bl_url or not rg_url:
            return jsonify({"ok": False, "error": "Baseline job URL and regression job URL are required"})
        sec = {}
        try:
            if SECRETS_FILE.exists():
                wb = _xl.load_workbook(str(SECRETS_FILE), read_only=True)
                if "Jenkins" in wb.sheetnames:
                    for r in wb["Jenkins"].iter_rows(min_row=2, values_only=True):
                        if r[0] and r[1] is not None:
                            sec[str(r[0]).strip()] = str(r[1]).strip()
        except Exception:
            pass
        auth = (sec.get("jenkins_username"), sec.get("jenkins_api_token") or sec.get("jenkins_password") or "") if sec.get("jenkins_username") else None
        try:
            bl, rg = _rpc_fetch(bl_url, auth), _rpc_fetch(rg_url, auth)
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)[:500]})
        cnt = lambda m: {"total": len(m), "passed": sum(1 for t in m.values() if t["state"] == "passed"),
                         "failed": sum(1 for t in m.values() if t["state"] == "failed"),
                         "disabled": sum(1 for t in m.values() if t["state"] == "disabled")}
        row = lambda t, bs, rs: {"id": t["id"], "class": t["class"], "name": t["name"], "baseline": bs, "regression": rs}
        failing = [row(rg[i], bl[i]["state"], "failed") for i in sorted(rg) if i in bl and rg[i]["state"] == "failed" and bl[i]["state"] == "passed"]
        missing = [row(bl[i], bl[i]["state"], "missing") for i in sorted(bl) if i not in rg]
        disabled = [row(rg[i], bl[i]["state"], "disabled") for i in sorted(rg) if i in bl and rg[i]["state"] == "disabled" and bl[i]["state"] != "disabled"]
        added = [row(rg[i], "", rg[i]["state"]) for i in sorted(rg) if i not in bl]
        return jsonify({"ok": True, "baseline_url": bl_url, "regression_url": rg_url,
                        "generated": _dt.datetime.now().strftime("%Y-%m-%d %H:%M"),
                        "baseline": cnt(bl), "regression": cnt(rg),
                        "failing": failing, "missing": missing, "disabled": disabled, "added": added,
                        "totals": {"failing": len(failing), "missing": len(missing), "disabled": len(disabled), "added": len(added)}})

    @app.route("/api/tools/regression-parity/export", methods=["POST"])
    def api_regression_parity_export():
        import json as _j, csv as _csv, io as _io, html as _h
        body = request.get_json() or {}
        fmt, rep = str(body.get("format", "json")).lower(), body.get("report") or {}
        SEG = [("failing", "Failing in regression, passing in baseline"), ("missing", "Missing in regression, present in baseline"),
               ("disabled", "Disabled in regression, enabled in baseline"), ("added", "Newly added in regression")]
        cols = ["Category", "Test Case", "Class", "Name", "Baseline", "Regression"]
        row = lambda k, e: [k, e.get("id"), e.get("class"), e.get("name"), e.get("baseline"), e.get("regression")]
        summ = [("Baseline total", rep.get("baseline", {}).get("total")), ("Regression total", rep.get("regression", {}).get("total")),
                ("Failing in regression but passing in baseline", (rep.get("totals") or {}).get("failing")),
                ("Missing in regression but present in baseline", (rep.get("totals") or {}).get("missing")),
                ("Disabled in regression but enabled in baseline", (rep.get("totals") or {}).get("disabled")),
                ("Newly added in regression", (rep.get("totals") or {}).get("added"))]
        fname = "regression-parity-report"
        if fmt == "json":
            data, mime, ext = _j.dumps(rep, indent=2), "application/json", "json"
        elif fmt == "csv":
            buf = _io.StringIO()
            w = _csv.writer(buf)
            w.writerow(["Summary", "Count"])
            for k, v in summ:
                w.writerow([k, v])
            w.writerow([])
            w.writerow(cols)
            for k, _t in SEG:
                for e in rep.get(k, []):
                    w.writerow(row(k, e))
            data, mime, ext = "\ufeff" + buf.getvalue(), "text/csv", "csv"
        elif fmt == "xlsx":
            import openpyxl as _xl
            from openpyxl.styles import Font as _F, PatternFill as _P
            wb = _xl.Workbook()
            ws = wb.active
            ws.title = "Summary"
            ws.append(["Summary", "Count"])
            for k, v in summ:
                ws.append([k, v])
            ws.append(["Baseline job", rep.get("baseline_url", "")])
            ws.append(["Regression job", rep.get("regression_url", "")])
            sheets = [ws]
            for k, t in SEG:
                w2 = wb.create_sheet(k.capitalize())
                w2.append(cols[1:])
                for e in rep.get(k, []):
                    w2.append(row(k, e)[1:])
                sheets.append(w2)
            for w_ in sheets:
                for c in w_[1]:
                    c.font = _F(bold=True, color="FFFFFF")
                    c.fill = _P("solid", fgColor="1565C0")
                for col in w_.columns:
                    w_.column_dimensions[col[0].column_letter].width = min(80, max(10, max(len(str(c.value or "")) for c in col) + 2))
            buf = _io.BytesIO()
            wb.save(buf)
            data, mime, ext = buf.getvalue(), "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", "xlsx"
        elif fmt == "html":
            e_ = _h.escape
            colors = {"failing": "#C62828", "missing": "#6A1B9A", "disabled": "#E65100", "added": "#2E7D32"}
            tot, bl, rg = rep.get("totals") or {}, rep.get("baseline") or {}, rep.get("regression") or {}
            out = ["<html><head><meta charset='utf-8'><title>Regression parity report</title><style>"
                   "body{font-family:'Segoe UI',Arial,sans-serif;margin:0;padding:24px 28px;background:#f5f6f8;color:#1f2937}"
                   "h1{font-size:22px;margin:0}.sub{font-size:13px;color:#6b7280;margin:4px 0 16px}"
                   ".card{background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:14px 16px}"
                   ".tiles{display:flex;flex-wrap:wrap;gap:12px;margin-bottom:16px}.tile{flex:1 1 170px;min-width:170px}"
                   ".tile.click{cursor:pointer}.tile.on .card{outline:2px solid var(--c)}"
                   ".lbl{font-size:11px;color:#6b7280}.val{font-size:24px;font-weight:700}"
                   ".seg{display:none}.seg.on{display:block}"
                   ".sh{font-weight:700;font-size:13px;padding-bottom:3px;margin-bottom:6px;border-bottom:2px solid}"
                   "table{width:100%;border-collapse:collapse}th{text-align:left;padding:4px 8px;font-size:11px;background:#f3f4f6;border-bottom:1px solid #e5e7eb;white-space:nowrap}"
                   "td{padding:4px 8px;font-size:12px;border-bottom:1px solid #e5e7eb;word-break:break-all}"
                   ".foot{font-size:11px;color:#6b7280;margin-top:10px}.none{font-size:12px;color:#6b7280}</style></head><body>",
                   "<h1>Regression Parity Checker</h1>",
                   "<div class='sub'>Baseline: %s<br>Regression: %s<br>Generated %s</div>" % (
                       e_(str(rep.get("baseline_url", ""))), e_(str(rep.get("regression_url", ""))), e_(str(rep.get("generated", "")))),
                   "<div class='tiles'>",
                   "<div class='tile'><div class='card'><div class='lbl'>Total tests - baseline</div><div class='val'>%s</div></div></div>" % e_(str(bl.get("total", ""))),
                   "<div class='tile'><div class='card'><div class='lbl'>Total tests - regression</div><div class='val'>%s</div></div></div>" % e_(str(rg.get("total", "")))]
            for i, (k, t) in enumerate(SEG):
                out.append("<div class='tile click%s' id='t-%s' style='--c:%s' onclick=\"sw('%s')\"><div class='card'><div class='lbl'>%s</div>"
                           "<div class='val' style='color:%s'>%s</div></div></div>" % (" on" if i == 0 else "", k, colors[k], k, e_(t), colors[k], e_(str(tot.get(k, 0)))))
            out.append("</div>")
            for i, (k, t) in enumerate(SEG):
                items = rep.get(k, [])
                out.append("<div class='seg card%s' id='s-%s'><div class='sh' style='color:%s;border-color:%s'>%s (%d)</div>" % (" on" if i == 0 else "", k, colors[k], colors[k], e_(t), len(items)))
                if not items:
                    out.append("<div class='none'>None</div>")
                else:
                    out.append("<table><tr><th>Class</th><th>Test case</th><th>Baseline</th><th>Regression</th></tr>" +
                               "".join("<tr><td>%s</td><td>%s</td><td>%s</td><td>%s</td></tr>" % (
                                   e_(str(x.get("class") or "")), e_(str(x.get("name") or "")), e_(str(x.get("baseline") or "—")), e_(str(x.get("regression") or ""))) for x in items) + "</table>")
                out.append("</div>")
            out.append("<div class='foot'>Baseline: passed %s · failed %s · disabled %s &nbsp;|&nbsp; Regression: passed %s · failed %s · disabled %s</div>" % (
                bl.get("passed"), bl.get("failed"), bl.get("disabled"), rg.get("passed"), rg.get("failed"), rg.get("disabled")))
            out.append("<script>function sw(k){['failing','missing','disabled','added'].forEach(function(x){"
                       "document.getElementById('s-'+x).classList.toggle('on',x==k);document.getElementById('t-'+x).classList.toggle('on',x==k)})}</script></body></html>")
            data, mime, ext = "\n".join(out), "text/html", "html"
        else:
            return jsonify({"ok": False, "error": "Unknown format"}), 400
        from flask import Response as _Resp
        return _Resp(data, mimetype=mime + ("" if ext == "xlsx" else "; charset=utf-8"), headers={"Content-Disposition": 'attachment; filename="%s.%s"' % (fname, ext)})

    # ── M2 Repo Cleaner ──────────────────────────────────────────────────────
    _M2_BASE_DIR   = WORKFLOWS_ROOT / "Tools" / "M2RepoCleaner"
    _M2_CFG_FILE   = _M2_BASE_DIR / "config.xlsx"
    _M2_STATS_DIR  = _M2_BASE_DIR / "stats"
    _M2_STATS_FILE = _M2_STATS_DIR / "stats.xlsx"
    _M2_CACHE_FILE = _M2_BASE_DIR / "scan_cache.json"
    _M2_REPO_DEFAULT = str(Path.home() / ".m2" / "repository")

    def _m2_ensure_dirs():
        _M2_BASE_DIR.mkdir(parents=True, exist_ok=True)
        _M2_STATS_DIR.mkdir(parents=True, exist_ok=True)

    def _m2_load_path():
        import openpyxl as _xl
        if _M2_CFG_FILE.exists():
            try:
                wb = _xl.load_workbook(str(_M2_CFG_FILE))
                ws = wb["config"] if "config" in wb.sheetnames else wb.active
                for row in ws.iter_rows(min_row=1, values_only=True):
                    if row and len(row) >= 2 and str(row[0] or "").strip().lower() == "path":
                        val = str(row[1] or "").strip()
                        return val or _M2_REPO_DEFAULT
            except Exception:
                pass
        return _M2_REPO_DEFAULT

    def _m2_save_path(path_str):
        import openpyxl as _xl
        _m2_ensure_dirs()
        if _M2_CFG_FILE.exists():
            try:
                wb = _xl.load_workbook(str(_M2_CFG_FILE))
            except Exception:
                wb = _xl.Workbook()
        else:
            wb = _xl.Workbook()
        if "config" in wb.sheetnames:
            ws = wb["config"]
        else:
            ws = wb.active
            ws.title = "config"
        updated = False
        for row in ws.iter_rows(min_row=1):
            if str(row[0].value or "").strip().lower() == "path":
                row[1].value = path_str
                updated = True
                break
        if not updated:
            ws.append(["path", path_str])
        wb.save(str(_M2_CFG_FILE))

    def _m2_load_stats():
        import openpyxl as _xl
        if not _M2_STATS_FILE.exists():
            return []
        try:
            wb = _xl.load_workbook(str(_M2_STATS_FILE))
            ws = wb.active
            records = []
            for row in ws.iter_rows(min_row=2, values_only=True):
                if row and row[0] is not None and row[1] is not None:
                    records.append({"timestamp": str(row[0]), "size_bytes": int(row[1] or 0)})
            return records
        except Exception:
            return []

    def _m2_append_stat(size_bytes):
        import openpyxl as _xl
        from datetime import datetime as _dt
        _m2_ensure_dirs()
        records = _m2_load_stats()
        records.append({"timestamp": _dt.now().strftime("%Y-%m-%d %H:%M:%S"), "size_bytes": size_bytes})
        records = records[-10:]  # keep only last 10
        wb = _xl.Workbook()
        ws = wb.active
        ws.append(["Timestamp", "Size Bytes"])
        for rec in records:
            ws.append([rec["timestamp"], rec["size_bytes"]])
        wb.save(str(_M2_STATS_FILE))

    def _m2_compute_threshold(current_bytes, stats):
        if len(stats) < 10:
            return None, None
        sizes = sorted([s["size_bytes"] for s in stats])
        n = len(sizes)
        median = (sizes[n // 2 - 1] + sizes[n // 2]) / 2.0 if n % 2 == 0 else float(sizes[n // 2])
        if median == 0:
            return None, None
        pct = (current_bytes / median) * 100
        if pct >= 100:
            level = "alert_100"
        elif pct >= 90:
            level = "alert_90"
        elif pct >= 80:
            level = "warn_80"
        elif pct >= 70:
            level = "warn_70"
        else:
            level = None
        return level, round(pct, 1)

    def _m2_maybe_popup(level, current_gb, median_gb):
        if level not in ("alert_90", "alert_100"):
            return
        try:
            import ctypes as _ct, threading as _thr2
            pct_label = "≥90%" if level == "alert_90" else "≥100%"
            msg = (
                f"M2 repository is {current_gb:.2f} GB "
                f"({pct_label} of median clean size {median_gb:.2f} GB).\n\n"
                "Please open M2 Repo Cleaner and clean the repository to free disk space."
            )
            _thr2.Thread(
                target=lambda: _ct.windll.user32.MessageBoxW(0, msg, "M2 Repo Cleaner — Action Required", 0x30),
                daemon=True,
            ).start()
        except Exception:
            pass

    def _m2_save_cache(size_bytes):
        import json as _json
        from datetime import datetime as _dt
        try:
            _m2_ensure_dirs()
            _M2_CACHE_FILE.write_text(_json.dumps({
                "size_bytes": size_bytes,
                "scanned_at": _dt.now().strftime("%Y-%m-%d %H:%M:%S"),
            }))
        except Exception:
            pass

    def _m2_load_cache():
        import json as _json
        if _M2_CACHE_FILE.exists():
            try:
                return _json.loads(_M2_CACHE_FILE.read_text())
            except Exception:
                pass
        return None

    @app.route("/api/tools/m2-repo/config", methods=["GET"])
    def api_m2_repo_config_get():
        return jsonify({"ok": True, "path": _m2_load_path()})

    @app.route("/api/tools/m2-repo/config", methods=["POST"])
    def api_m2_repo_config_save():
        body = request.get_json() or {}
        path_str = str(body.get("path") or "").strip()
        if not path_str:
            return jsonify({"ok": False, "error": "Path is required"})
        _m2_save_path(path_str)
        return jsonify({"ok": True})

    @app.route("/api/tools/m2-repo/stats", methods=["GET"])
    def api_m2_repo_stats():
        stats = _m2_load_stats()
        cache = _m2_load_cache()
        cur_bytes = cache["size_bytes"] if cache else None
        level, pct = _m2_compute_threshold(cur_bytes or 0, stats) if cur_bytes is not None else (None, None)
        sizes = sorted([s["size_bytes"] for s in stats]) if len(stats) >= 10 else []
        n = len(sizes)
        median_bytes = None
        if n >= 10:
            median_bytes = int((sizes[n // 2 - 1] + sizes[n // 2]) / 2) if n % 2 == 0 else sizes[n // 2]
        return jsonify({
            "ok": True,
            "history": stats,
            "last_scan": cache,
            "warning_level": level,
            "pct_of_median": pct,
            "median_bytes": median_bytes,
        })

    @app.route("/api/tools/m2-repo/scan", methods=["GET"])
    def api_m2_repo_scan():
        import os as _os
        repo = Path(_m2_load_path())
        if not repo.exists():
            return jsonify({"ok": False, "error": f"Path does not exist: {repo}"})
        if not repo.is_dir():
            return jsonify({"ok": False, "error": f"Not a directory: {repo}"})
        total_files = 0
        total_bytes = 0
        top_level   = []
        try:
            for entry in sorted(repo.iterdir(), key=lambda e: e.name.lower()):
                entry_bytes = 0
                entry_files = 0
                if entry.is_dir():
                    for root, _dirs, files in _os.walk(str(entry)):
                        for f in files:
                            try:
                                entry_bytes += _os.path.getsize(_os.path.join(root, f))
                                entry_files += 1
                            except OSError:
                                pass
                    top_level.append({"name": entry.name, "type": "dir",
                                      "size_bytes": entry_bytes, "files": entry_files})
                else:
                    try:
                        entry_bytes = _os.path.getsize(str(entry))
                    except OSError:
                        pass
                    entry_files = 1
                    top_level.append({"name": entry.name, "type": "file",
                                      "size_bytes": entry_bytes, "files": 1})
                total_bytes += entry_bytes
                total_files += entry_files
            top_level.sort(key=lambda x: x["size_bytes"], reverse=True)
            _m2_save_cache(total_bytes)
            stats = _m2_load_stats()
            level, pct = _m2_compute_threshold(total_bytes, stats)
            sizes = sorted([s["size_bytes"] for s in stats]) if len(stats) >= 10 else []
            n = len(sizes)
            median_bytes = None
            if n >= 10:
                median_bytes = int((sizes[n // 2 - 1] + sizes[n // 2]) / 2) if n % 2 == 0 else sizes[n // 2]
            if level in ("alert_90", "alert_100") and median_bytes:
                _m2_maybe_popup(level, total_bytes / 1e9, median_bytes / 1e9)
            return jsonify({
                "ok": True,
                "path": str(repo),
                "total_size_bytes": total_bytes,
                "total_files": total_files,
                "top_level": top_level,
                "warning_level": level,
                "pct_of_median": pct,
                "median_bytes": median_bytes,
            })
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/tools/m2-repo/clean", methods=["POST"])
    def api_m2_repo_clean():
        import shutil as _sh
        body = request.get_json() or {}
        size_before = body.get("size_bytes")
        repo = Path(_m2_load_path())
        if not repo.exists():
            return jsonify({"ok": False, "error": f"Path does not exist: {repo}"})
        if not repo.is_dir():
            return jsonify({"ok": False, "error": f"Not a directory: {repo}"})
        if size_before is None:
            import os as _os2
            size_before = 0
            for root, _dirs, files in _os2.walk(str(repo)):
                for f in files:
                    try:
                        size_before += _os2.path.getsize(_os2.path.join(root, f))
                    except OSError:
                        pass
        deleted = 0
        errors  = []
        for entry in list(repo.iterdir()):
            try:
                if entry.is_dir():
                    _sh.rmtree(str(entry))
                else:
                    entry.unlink()
                deleted += 1
            except Exception as exc:
                errors.append(f"{entry.name}: {exc}")
        ok = deleted > 0 or (deleted == 0 and not errors)
        if ok:
            _m2_append_stat(int(size_before))
            _m2_save_cache(0)
        return jsonify({"ok": ok, "deleted": deleted, "errors": errors, "size_before_bytes": int(size_before)})

    @app.route("/api/tools/m2-repo/settings-xml", methods=["GET"])
    def api_m2_repo_settings_xml():
        settings_path = Path.home() / ".m2" / "settings.xml"
        if not settings_path.exists():
            return jsonify({"ok": False, "error": f"settings.xml not found at {settings_path}"})
        try:
            content = settings_path.read_text(encoding="utf-8", errors="replace")
            return jsonify({"ok": True, "path": str(settings_path), "content": content})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/tools/m2-repo/healthedge-scan", methods=["GET"])
    def api_m2_repo_healthedge_scan():
        import os as _os, re as _re
        repo = Path(_m2_load_path())
        he_path = repo / "com" / "healthedge"
        if not he_path.exists():
            return jsonify({"ok": False, "error": f"Path does not exist: {he_path}"})

        def _is_version(name):
            # Version dirs look like "26.2-SNAPSHOT", "27.1-SNAPSHOT", "21.6-SNAPSHOT"
            return bool(_re.match(r'^\d+\.\d+', name))

        def _dir_size(path_str):
            total = 0
            for root, _d, files in _os.walk(path_str):
                for f in files:
                    try:
                        total += _os.path.getsize(_os.path.join(root, f))
                    except OSError:
                        pass
            return total

        def _safe_listdirs(p):
            try:
                return [e for e in p.iterdir() if e.is_dir()]
            except (PermissionError, OSError):
                return []

        def _base_ver(name):
            # "27.1-SNAPSHOT" → "27.1", "27.1-202610171600-9ac845e" → "27.1"
            # "27.1_288_6" → "27.1", "4.4.11.1.1-SNAPSHOT" → "4.4"
            base = _re.split(r'[-_]', name)[0]
            parts = base.split(".")
            return f"{parts[0]}.{parts[1]}" if len(parts) >= 2 else base

        version_map = {}

        def _accumulate(ver_dir):
            label = _base_ver(ver_dir.name)
            size  = _dir_size(str(ver_dir))
            if label not in version_map:
                version_map[label] = {"label": label, "total_size_bytes": 0, "artifact_count": 0}
            version_map[label]["total_size_bytes"] += size
            version_map[label]["artifact_count"]   += 1

        def _walk(directory, depth):
            if depth == 0:
                return
            children = _safe_listdirs(directory)
            version_children = [c for c in children if _is_version(c.name)]
            if version_children:
                for c in version_children:
                    _accumulate(c)
            else:
                for c in children:
                    _walk(c, depth - 1)

        try:
            try:
                max_depth = max(1, min(10, int(request.args.get("max_depth", 3))))
            except (TypeError, ValueError):
                max_depth = 3
            _walk(he_path, max_depth)

            def _ver_tuple(label):
                return tuple(int(p) if p.isdigit() else 0 for p in label.split("."))

            versions = sorted(
                version_map.values(),
                key=lambda v: (_ver_tuple(v["label"]), v["total_size_bytes"]),
                reverse=True,
            )
            return jsonify({
                "ok": True,
                "base_path": str(he_path),
                "total_size_bytes": sum(v["total_size_bytes"] for v in versions),
                "versions": versions,
            })
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/tools/m2-repo/clean-versions", methods=["POST"])
    def api_m2_repo_clean_versions():
        import shutil as _sh, re as _re2
        body = request.get_json() or {}
        labels = set(body.get("version_labels") or [])
        if not labels:
            return jsonify({"ok": False, "error": "No version labels provided"})
        repo = Path(_m2_load_path())
        he_path = repo / "com" / "healthedge"
        if not he_path.exists():
            return jsonify({"ok": False, "error": f"Path does not exist: {he_path}"})

        def _is_version(name):
            return bool(_re2.match(r'^\d+\.\d+', name))

        def _safe_listdirs(p):
            try:
                return [e for e in p.iterdir() if e.is_dir()]
            except (PermissionError, OSError):
                return []

        deleted = 0
        errors  = []

        def _base_ver2(name):
            base = _re2.split(r'[-_]', name)[0]
            parts = base.split(".")
            return f"{parts[0]}.{parts[1]}" if len(parts) >= 2 else base

        def _walk_delete(directory, depth):
            nonlocal deleted
            if depth == 0:
                return
            children = _safe_listdirs(directory)
            version_children = [c for c in children if _is_version(c.name)]
            if version_children:
                for c in version_children:
                    if _base_ver2(c.name) in labels:
                        try:
                            _sh.rmtree(str(c))
                            deleted += 1
                        except Exception as exc:
                            errors.append(f"{c}: {exc}")
            else:
                for c in children:
                    _walk_delete(c, depth - 1)

        try:
            max_depth = max(1, min(10, int(body.get("max_depth", 3))))
        except (TypeError, ValueError):
            max_depth = 3
        _walk_delete(he_path, max_depth)

        return jsonify({"ok": True, "deleted": deleted, "errors": errors})

    # ── Project Cleaner ──────────────────────────────────────────────────────
    _PC_BASE_DIR     = WORKFLOWS_ROOT / "Tools" / "ProjectCleaner"
    _PC_CFG_FILE     = _PC_BASE_DIR / "config.xlsx"
    _PC_DEFAULT_PATH = (os.environ.get("GIT_HOME") or str(Path.home() / "hebb")).replace("\\", "/")

    def _pc_ensure_dirs():
        _PC_BASE_DIR.mkdir(parents=True, exist_ok=True)

    def _pc_load_path():
        import openpyxl as _xl
        if _PC_CFG_FILE.exists():
            try:
                wb = _xl.load_workbook(str(_PC_CFG_FILE))
                ws = wb["config"] if "config" in wb.sheetnames else wb.active
                for row in ws.iter_rows(min_row=1, values_only=True):
                    if row and len(row) >= 2 and str(row[0] or "").strip().lower() == "path":
                        val = str(row[1] or "").strip()
                        return val or _PC_DEFAULT_PATH
            except Exception:
                pass
        return _PC_DEFAULT_PATH

    def _pc_save_path(path_str):
        import openpyxl as _xl
        _pc_ensure_dirs()
        if _PC_CFG_FILE.exists():
            try:
                wb = _xl.load_workbook(str(_PC_CFG_FILE))
            except Exception:
                wb = _xl.Workbook()
        else:
            wb = _xl.Workbook()
        if "config" in wb.sheetnames:
            ws = wb["config"]
        else:
            ws = wb.active
            ws.title = "config"
        updated = False
        for row in ws.iter_rows(min_row=1):
            if str(row[0].value or "").strip().lower() == "path":
                row[1].value = path_str
                updated = True
                break
        if not updated:
            ws.append(["path", path_str])
        wb.save(str(_PC_CFG_FILE))

    @app.route("/api/tools/project-cleaner/config", methods=["GET"])
    def api_pc_config_get():
        return jsonify({"ok": True, "path": _pc_load_path()})

    @app.route("/api/tools/project-cleaner/config", methods=["POST"])
    def api_pc_config_save():
        body = request.get_json() or {}
        path_str = str(body.get("path") or "").strip()
        if not path_str:
            return jsonify({"ok": False, "error": "Path is required"})
        _pc_save_path(path_str)
        return jsonify({"ok": True})

    _PC_EXCLUDED = {"hrp-docker-win-devenv", "hrp.dev.tools", "hrp.payer.datauniv"}

    _PC_CATEGORY_ORDER = ["Payor", "Classic", "Connector", "Enrollment", "PIK", "Rest Adaptor", "UI", "Other"]

    def _pc_categorize(name):
        n = name.lower().replace("-", ".").replace("_", ".")
        # More-specific checks first to avoid early Payor/Payer match consuming sub-categories
        if "rest" in n and "adapt" in n:
            return "Rest Adaptor"
        if ("payor" in n or "payer" in n) and "utils" in n:
            return "Payer Utils"
        parts = n.split(".")
        if ".ui." in ("." + n + ".") or parts[-1] == "ui" or parts[-1] == "web" or n.endswith(".ui"):
            return "UI"
        if "payor" in n or "payer" in n:
            return "Payor"
        if "classic" in n:
            return "Classic"
        if "connector" in n:
            return "Connector"
        if "enrollment" in n or "enroll" in n:
            return "Enrollment"
        if "pik" in n or ("portal" in n and "integration" in n):
            return "PIK"
        return "Other"

    @app.route("/api/tools/project-cleaner/scan", methods=["GET"])
    def api_pc_scan():
        from datetime import datetime as _dt
        base = Path(_pc_load_path())
        if not base.exists():
            return jsonify({"ok": False, "error": f"Path does not exist: {base}"})
        if not base.is_dir():
            return jsonify({"ok": False, "error": f"Not a directory: {base}"})
        projects = []
        try:
            for entry in base.iterdir():
                if not entry.is_dir():
                    continue
                if entry.name in _PC_EXCLUDED:
                    continue
                try:
                    st = entry.stat()
                    mtime = st.st_mtime
                    modified = _dt.fromtimestamp(mtime).strftime("%Y-%m-%d %H:%M")
                except Exception:
                    mtime = 0
                    modified = ""
                projects.append({
                    "name": entry.name,
                    "modified": modified,
                    "mtime": mtime,
                    "category": _pc_categorize(entry.name),
                })
            # Least recently used first
            projects.sort(key=lambda x: x["mtime"])
            return jsonify({
                "ok": True,
                "base_path": str(base),
                "projects": projects,
            })
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/api/tools/project-cleaner/clean", methods=["POST"])
    def api_pc_clean():
        import shutil as _sh
        body = request.get_json() or {}
        names = body.get("names") or []
        if not names:
            return jsonify({"ok": False, "error": "No project names provided"})
        base = Path(_pc_load_path())
        if not base.exists():
            return jsonify({"ok": False, "error": f"Path does not exist: {base}"})
        deleted = []
        errors  = []
        for name in names:
            target = base / name
            if not target.exists():
                errors.append(f"{name}: not found")
                continue
            if not target.is_dir():
                errors.append(f"{name}: not a directory")
                continue
            if not str(target.resolve()).startswith(str(base.resolve())):
                errors.append(f"{name}: path traversal blocked")
                continue
            try:
                _sh.rmtree(str(target))
                deleted.append(name)
            except Exception as exc:
                errors.append(f"{name}: {exc}")
        return jsonify({"ok": True, "deleted": deleted, "errors": errors})

    def _jreg_startup_recovery():
        """Read persisted poll interval and restart job poller for any in-progress JReg run."""
        import openpyxl as _xl
        _FINAL = {
            "success", "passed", "failure", "failed", "unstable", "aborted",
            "trigger failed", "error", "conn_err", "auth_error", "no_builds", "no_url",
        }
        # Ensure scheduler_config.xlsx exists with a default
        _cfg = JR_ROOT / "scheduler_config.xlsx"
        _poll      = 60
        _stale_hrs = 48
        if _cfg.exists():
            try:
                _wb = _xl.load_workbook(str(_cfg))
                for _r in _wb.active.iter_rows(min_row=2, values_only=True):
                    if not _r[0]:
                        continue
                    _key = str(_r[0]).strip().lower()
                    if _key == "poll_interval_s" and _r[1]:
                        _poll = max(30, int(_r[1]))
                    elif _key == "stale_threshold_hours" and _r[1]:
                        _stale_hrs = max(1, int(_r[1]))
            except Exception:
                pass
        else:
            _jr_write_poll_interval(_poll)
        with _jreg_op_lock:
            _jreg_op["poll_interval_s"] = _poll

        _proj_root = JR_DATA / "projects"
        if not _proj_root.exists():
            return
        for _app_dir in _proj_root.iterdir():
            if not _app_dir.is_dir():
                continue
            _files = sorted(
                _app_dir.glob("*.xlsx"),
                key=lambda p: int(p.stem.split("_")[0]) if p.stem.split("_")[0].isdigit() else 0,
                reverse=True)
            if not _files:
                continue
            try:
                with _jr_per_file_lock(_files[0]):
                    _wb2 = _xl.load_workbook(str(_files[0]))
                if "jobs" not in _wb2.sheetnames:
                    continue
                _ws  = _wb2["jobs"]
                _hdr = [str(c.value or "").strip().lower() for c in _ws[1]]
                if "completed" not in _hdr:
                    continue
                _ci  = _hdr.index("completed")
                _sts = [str(r[_ci] or "").strip().lower()
                        for r in _ws.iter_rows(min_row=2, values_only=True) if any(r)]
                if not _sts or all(s in _FINAL for s in _sts):
                    continue
                # Check staleness
                import time as _time_rec
                _file_age = _time_rec.time() - _files[0].stat().st_mtime
                if _file_age > _stale_hrs * 3600:
                    try:
                        with _jr_per_file_lock(_files[0]):
                            _wb_st = _xl.load_workbook(str(_files[0]))
                            _st_sts = []
                            if "jobs" in _wb_st.sheetnames:
                                _ws_st = _wb_st["jobs"]
                                _hd_st = [str(c.value or "").strip().lower()
                                          for c in _ws_st[1]]
                                _ci_st = (_hd_st.index("completed")
                                          if "completed" in _hd_st else None)
                                if _ci_st is not None:
                                    for _rw_st in _ws_st.iter_rows(min_row=2):
                                        if any(c.value is not None for c in _rw_st):
                                            _v_st = str(_rw_st[_ci_st].value or "").strip().lower()
                                            if _v_st not in _FINAL:
                                                _rw_st[_ci_st].value = "conn_err"
                                            _st_sts.append(
                                                str(_rw_st[_ci_st].value or "conn_err"))
                            _wb_st.save(str(_files[0]))
                        if _st_sts:
                            try:
                                _run_id_st = int(_files[0].stem.split("_")[0])
                                _jr_scripts = str(JR_ROOT / "scripts")
                                import sys as _sys_jr_st
                                if _jr_scripts not in _sys_jr_st.path:
                                    _sys_jr_st.path.insert(0, _jr_scripts)
                                from jreg_tool import update_run_status as _urs_jr
                                with _jreg_projects_lock, _jr_projects_filelock():
                                    _urs_jr(_run_id_st, "conn_err", _app_dir.name)
                            except Exception:
                                pass
                    except Exception:
                        pass
                    continue  # stale — do not start a poller
                # Ensure the row exists in projects.xlsx (may be missing after a crash).
                try:
                    _run_id = int(_files[0].stem.split("_")[0])
                    _proj_xlsx = JR_DATA / "projects.xlsx"
                    _row_found = False
                    if _proj_xlsx.exists():
                        with _jreg_projects_lock, _jr_projects_filelock():
                            _wb3 = _xl.load_workbook(str(_proj_xlsx))
                            _ws3 = (_wb3[_app_dir.name]
                                    if _app_dir.name in _wb3.sheetnames else _wb3.active)
                            _row_found = any(
                                _ws3.cell(r, 1).value == _run_id
                                for r in range(2, _ws3.max_row + 1)
                            )
                    if not _row_found:
                        _jr_scripts = str(JR_ROOT / "scripts")
                        import sys as _sys_jr2
                        if _jr_scripts not in _sys_jr2.path:
                            _sys_jr2.path.insert(0, _jr_scripts)
                        from jreg_tool import append_run as _append_run_jr
                        _ver = ""
                        if "info" in _wb2.sheetnames:
                            for _ir in _wb2["info"].iter_rows(min_row=2, values_only=True):
                                if _ir and str(_ir[0] or "").strip() == "release_version":
                                    _ver = str(_ir[1] or "").strip(); break
                        _trig = ""
                        if "info" in _wb2.sheetnames:
                            for _ir in _wb2["info"].iter_rows(min_row=2, values_only=True):
                                if _ir and str(_ir[0] or "").strip() == "triggered_at":
                                    _trig = str(_ir[1] or "").strip(); break
                        if not _trig:
                            from datetime import datetime as _dt2
                            _trig = _dt2.fromtimestamp(_files[0].stat().st_mtime).strftime(
                                "%Y-%m-%d %H:%M:%S")
                        _append_run_jr(_run_id, _ver, 1, "running", _trig, _app_dir.name)
                except Exception:
                    pass
                with _jreg_op_lock:
                    _jreg_op.update({"status": "running", "app": _app_dir.name,
                                     "output": "", "pid": None})
                _threading.Thread(
                    target=_jreg_job_poller, args=(_app_dir.name,), daemon=True
                ).start()
                break  # only one jreg run at a time
            except Exception:
                pass

    def _jbaseline_startup_recovery():
        """Read persisted poll interval and restart job poller for any in-progress run."""
        import openpyxl as _xl
        _FINAL = {
            "success", "passed", "failure", "failed", "unstable", "aborted",
            "trigger failed", "error", "conn_err", "auth_error", "no_builds", "no_url",
        }
        # Read persisted poll interval and stale threshold from scheduler_config.xlsx
        _cfg        = JB_ROOT / "scheduler_config.xlsx"
        _poll       = 60
        _stale_hrs  = 48
        if _cfg.exists():
            try:
                _wb = _xl.load_workbook(str(_cfg))
                for _r in _wb.active.iter_rows(min_row=2, values_only=True):
                    if not _r[0]:
                        continue
                    _key = str(_r[0]).strip().lower()
                    if _key == "poll_interval_s" and _r[1]:
                        _poll = max(30, int(_r[1]))
                    elif _key == "stale_threshold_hours" and _r[1]:
                        _stale_hrs = max(1, int(_r[1]))
            except Exception:
                pass
        with _jbaseline_op_lock:
            _jbaseline_op["poll_interval_s"] = _poll

        # Scan per-project xlsx files for any run with non-final job statuses
        _proj_root = JB_DATA / "projects"
        if not _proj_root.exists():
            return
        for _app_dir in _proj_root.iterdir():
            if not _app_dir.is_dir():
                continue
            _files = sorted(
                _app_dir.glob("*.xlsx"),
                key=lambda p: int(p.stem.split("_")[0]) if p.stem.split("_")[0].isdigit() else 0,
                reverse=True)
            if not _files:
                continue
            try:
                with _jb_per_file_lock(_files[0]):
                    _wb2 = _xl.load_workbook(str(_files[0]))
                if "jobs" not in _wb2.sheetnames:
                    continue
                _ws  = _wb2["jobs"]
                _hdr = [str(c.value or "").strip().lower() for c in _ws[1]]
                if "completed" not in _hdr:
                    continue
                _ci  = _hdr.index("completed")
                _sts = [str(r[_ci] or "").strip().lower()
                        for r in _ws.iter_rows(min_row=2, values_only=True) if any(r)]
                if _sts and not all(s in _FINAL for s in _sts):
                    # If the file is older than 4 hours the run is considered stale.
                    # Force all non-final jobs to conn_err and skip starting a poller.
                    import time as _time_rec
                    _file_age = _time_rec.time() - _files[0].stat().st_mtime
                    if _file_age > _stale_hrs * 3600:
                        try:
                            with _jb_per_file_lock(_files[0]):
                                _wb_st = _xl.load_workbook(str(_files[0]))
                                _st_sts = []
                                if "jobs" in _wb_st.sheetnames:
                                    _ws_st = _wb_st["jobs"]
                                    _hd_st = [str(c.value or "").strip().lower()
                                              for c in _ws_st[1]]
                                    _ci_st = (_hd_st.index("completed")
                                              if "completed" in _hd_st else None)
                                    if _ci_st is not None:
                                        for _rw_st in _ws_st.iter_rows(min_row=2):
                                            if any(c.value is not None for c in _rw_st):
                                                _v_st = str(_rw_st[_ci_st].value or "").strip().lower()
                                                if _v_st not in _FINAL:
                                                    _rw_st[_ci_st].value = "conn_err"
                                                _st_sts.append(
                                                    str(_rw_st[_ci_st].value or "conn_err"))
                                _wb_st.save(str(_files[0]))
                            if _st_sts:
                                try:
                                    _run_id_st = int(_files[0].stem.split("_")[0])
                                    with _jbaseline_projects_lock:
                                        _jb_scripts = str(JB_ROOT / "scripts")
                                        import sys as _sys_st
                                        if _jb_scripts not in _sys_st.path:
                                            _sys_st.path.insert(0, _jb_scripts)
                                        from jbaseline_tool import update_run_status as _urs_st
                                        _urs_st(_run_id_st, "conn_err")
                                except Exception:
                                    pass
                        except Exception:
                            pass
                        continue  # stale — do not start a poller
                    # Ensure the row exists in projects.xlsx (may be missing after a crash).
                    # _append_run acquires _jb_projects_filelock internally, so it must be
                    # called OUTSIDE the with-block to avoid deadlock (FileLock is non-reentrant).
                    try:
                        _run_id = int(_files[0].stem.split("_")[0])
                        _proj_xlsx = JB_DATA / "projects.xlsx"
                        _row_found = False
                        if _proj_xlsx.exists():
                            with _jb_projects_filelock():
                                _wb3 = _xl.load_workbook(str(_proj_xlsx))
                                _ws3 = _wb3["Payor"] if "Payor" in _wb3.sheetnames else _wb3.active
                                _row_found = any(
                                    _ws3.cell(r, 1).value == _run_id
                                    for r in range(2, _ws3.max_row + 1)
                                )
                        if not _row_found:
                            _jb_scripts = str(JB_ROOT / "scripts")
                            import sys as _sys2
                            if _jb_scripts not in _sys2.path:
                                _sys2.path.insert(0, _jb_scripts)
                            from jbaseline_tool import append_run as _append_run
                            _ver = ""
                            if "info" in _wb2.sheetnames:
                                for _ir in _wb2["info"].iter_rows(min_row=2, values_only=True):
                                    if _ir and str(_ir[0] or "").strip() == "release_version":
                                        _ver = str(_ir[1] or "").strip(); break
                            from datetime import datetime as _dt2
                            # Use triggered_at from info sheet (authoritative) rather than file mtime.
                            _trig = ""
                            if "info" in _wb2.sheetnames:
                                for _ir in _wb2["info"].iter_rows(min_row=2, values_only=True):
                                    if _ir and str(_ir[0] or "").strip() == "triggered_at":
                                        _trig = str(_ir[1] or "").strip(); break
                            if not _trig:
                                _trig = _dt2.fromtimestamp(_files[0].stat().st_mtime).strftime("%Y-%m-%d %H:%M:%S")
                            _append_run(_run_id, _ver, 1, "running", _trig)
                    except Exception:
                        pass
                    with _jbaseline_op_lock:
                        _jbaseline_op.update({"status": "running", "app": _app_dir.name,
                                              "output": "", "pid": None})
                    _threading.Thread(
                        target=_jbaseline_job_poller, args=(_app_dir.name,), daemon=True
                    ).start()
                    break  # only one baseline run at a time
            except Exception:
                pass

    def _cw_startup_recovery():
        """Restart workflow engines for any in-progress clone workflow projects."""
        import openpyxl as _xl, json as _json_cw
        import threading as _thr_cw

        # Ensure scheduler_config.xlsx exists with a default
        if not CW_SCHEDULER_CFG.exists():
            _cw_write_poll_interval(600)

        _poll_s = _cw_read_poll_interval()

        # Read stale threshold from scheduler_config
        _cw_stale_hrs = 48
        if CW_SCHEDULER_CFG.exists():
            try:
                _wb_cw_sc = _xl.load_workbook(str(CW_SCHEDULER_CFG), data_only=True)
                for _r_cw_sc in _wb_cw_sc.active.iter_rows(min_row=2, values_only=True):
                    if _r_cw_sc[0] and str(_r_cw_sc[0]).strip().lower() == "stale_threshold_hours" and _r_cw_sc[1]:
                        _cw_stale_hrs = max(1, int(_r_cw_sc[1]))
            except Exception:
                pass

        if not PROJECTS.exists():
            return

        # Load all in-progress projects
        try:
            _wb2 = _xl.load_workbook(str(PROJECTS), read_only=True, data_only=True)
            _ws2 = _wb2.active
            _hdrs = [str(c.value or "").strip().lower() for c in _ws2[1]]
            _proj_rows = []
            for _r2 in _ws2.iter_rows(min_row=2, values_only=True):
                if any(v is not None for v in _r2):
                    _proj_rows.append({_hdrs[i]: (str(_r2[i]) if _r2[i] is not None else "")
                                       for i in range(len(_hdrs))})
            _wb2.close()
        except Exception:
            return

        # Load dependency graph once
        _deps = {}
        _dep_path = CW_ROOT / "workflow_dependencies.xlsx"
        if _dep_path.exists():
            try:
                _wb3 = _xl.load_workbook(str(_dep_path), read_only=True, data_only=True)
                for _r3 in _wb3.active.iter_rows(min_row=2, values_only=True):
                    _sid = str(_r3[0] or "").strip(); _dep = str(_r3[1] or "").strip()
                    if _sid and _dep:
                        _deps.setdefault(_sid, [])
                        if _dep not in _deps[_sid]:
                            _deps[_sid].append(_dep)
                _wb3.close()
            except Exception:
                pass

        for _proj in _proj_rows:
            _pid     = str(_proj.get("pid", "")).strip()
            _pstatus = str(_proj.get("status", "")).strip()
            if not _pid or _pstatus not in ("In Progress", "Paused"):
                continue
            if _pid in _WF_THREADS and _WF_THREADS[_pid].is_alive():
                continue

            # Only resume if at least one stage is still non-final
            _stages = load_stages(_pid)
            if not any(s.get("status", "Pending") not in ("Completed", "Skipped", "Failed", "Aborted")
                       for s in _stages):
                continue

            # Build proj_params
            _extra = {}
            try:
                _extra = _json_cw.loads(_proj.get("extra_params") or "{}")
            except Exception:
                pass
            _proj_params = {
                **_extra,
                "payor_version":                  _proj.get("payor_version", ""),
                "bluecard_config_version_prefix": _proj.get("bluecard_config_version_prefix", ""),
                "datauniverse_version_prefix":    _proj.get("datauniverse_version_prefix", ""),
                "app":                            _extra.get("app", "Payor"),
            }

            # Skip if project is older than stale threshold
            _created_cw = str(_proj.get("created_at", "")).strip()
            if _created_cw:
                try:
                    import time as _time_cw_sr
                    import openpyxl as _xl_cw_sr
                    from datetime import datetime as _dt_cw
                    _age_cw = _time_cw_sr.time() - _dt_cw.strptime(_created_cw, "%Y-%m-%d %H:%M:%S").timestamp()
                    if _age_cw > _cw_stale_hrs * 3600:
                        _cw_nonfinal = {"Pending", "Waiting", "In Progress", "Stage Paused"}
                        for _st_cw in load_stages(_pid):
                            if str(_st_cw.get("status", "")) in _cw_nonfinal:
                                update_stage(_pid, _st_cw["stage_id"],
                                             {"status": "Failed", "notes": "Timed out (stale recovery)"})
                        try:
                            with _cw_projects_lock, _cw_projects_filelock():
                                _wb_stale = _xl_cw_sr.load_workbook(str(PROJECTS))
                                _ws_stale = _wb_stale.active
                                _h_stale = [str(_ws_stale.cell(1, c).value or "").strip().lower()
                                            for c in range(1, _ws_stale.max_column + 1)]
                                _sc_stale = (_h_stale.index("status") + 1) if "status" in _h_stale else None
                                for _rw_stale in _ws_stale.iter_rows(min_row=2):
                                    if str(_rw_stale[0].value or "").strip() == str(_pid):
                                        if _sc_stale:
                                            _rw_stale[_sc_stale - 1].value = "Stale"
                                        break
                                _save(_wb_stale, PROJECTS)
                        except Exception:
                            pass
                        continue  # don't restart engine for stale project
                except Exception:
                    pass

            # For paused projects, hold the pause gate so the engine monitors
            # in-progress stages but doesn't trigger new downstream ones
            if _pstatus == "Paused":
                _pev = _thr_cw.Event()
                _pev.set()
                _WF_PAUSE_EVENTS[_pid] = _pev

            _trigger_fn, _check_fn = _build_wf_fns(_pid, _proj_params)
            _abort_ev = _thr_cw.Event()
            _WF_ABORT_EVENTS[_pid] = _abort_ev
            _t = _thr_cw.Thread(
                target=_wf_run_engine,
                args=(_pid, _poll_s, _deps, _trigger_fn, _check_fn,
                      {"baseline", "jreg", "jcj", "jcj_baseline", "remote_setup", "melissa_update", "clone_pr_gp",
                       "melissa_gp_payor", "melissa_gp_classic", "rpb", "puc_baseline", "puc"}, _proj_params),
                daemon=True,
            )
            _t.start()
            _WF_THREADS[_pid] = _t

    def _jcj_startup_recovery():
        """At server restart, mark JCJ per-project jobs as conn_err if the file is stale."""
        import openpyxl as _xl, time as _time_jcj
        _FINAL = {
            "success", "passed", "failure", "failed", "unstable", "aborted",
            "trigger failed", "error", "conn_err", "auth_error", "no_builds", "no_url",
        }
        _stale_hrs = 48
        _cfg = JCJ_ROOT / "scheduler_config.xlsx"
        if _cfg.exists():
            try:
                _wb_cfg = _xl.load_workbook(str(_cfg), data_only=True)
                for _r in _wb_cfg.active.iter_rows(min_row=2, values_only=True):
                    if _r[0] and str(_r[0]).strip().lower() == "stale_threshold_hours" and _r[1]:
                        _stale_hrs = max(1, int(_r[1]))
            except Exception:
                pass
        _proj_root = JCJ_DATA / "projects"
        if not _proj_root.exists():
            return
        for _app_dir in _proj_root.iterdir():
            if not _app_dir.is_dir():
                continue
            _files = sorted(
                _app_dir.glob("*.xlsx"),
                key=lambda p: int(p.stem.split("_")[0]) if p.stem.split("_")[0].isdigit() else 0,
                reverse=True)
            if not _files:
                continue
            try:
                _wb2 = _xl.load_workbook(str(_files[0]))
                if "jobs" not in _wb2.sheetnames:
                    continue
                _ws = _wb2["jobs"]
                _hdr = [str(c.value or "").strip().lower() for c in _ws[1]]
                if "completed" not in _hdr:
                    continue
                _ci = _hdr.index("completed")
                _sts = [str(r[_ci] or "").strip().lower()
                        for r in _ws.iter_rows(min_row=2, values_only=True) if any(r)]
                if not _sts or all(s in _FINAL for s in _sts):
                    continue
                _age = _time_jcj.time() - _files[0].stat().st_mtime
                if _age > _stale_hrs * 3600:
                    for _rw in _ws.iter_rows(min_row=2):
                        if any(c.value is not None for c in _rw):
                            _v = str(_rw[_ci].value or "").strip().lower()
                            if _v not in _FINAL:
                                _rw[_ci].value = "conn_err"
                    _wb2.save(str(_files[0]))
            except Exception:
                pass

    def _rs_startup_recovery():
        """Read saved RS poll interval and restart poller if active projects exist."""
        import sys as _sys, time as _time_rs
        import openpyxl as _xl_rs
        _poll_s = _rs_read_poll_interval()
        with _rs_poller_state_lock:
            _rs_poller_state["poll_interval_s"] = _poll_s
        # Read stale threshold
        _stale_hrs_rs = 48
        _cfg_rs = RS_ROOT / "scheduler_config.xlsx"
        if _cfg_rs.exists():
            try:
                _wb_rs = _xl_rs.load_workbook(str(_cfg_rs), data_only=True)
                for _r_rs in _wb_rs.active.iter_rows(min_row=2, values_only=True):
                    if _r_rs[0] and str(_r_rs[0]).strip().lower() == "stale_threshold_hours" and _r_rs[1]:
                        _stale_hrs_rs = max(1, int(_r_rs[1]))
            except Exception:
                pass
        _rs_scr = str(RS_ROOT / "scripts")
        if _rs_scr not in _sys.path:
            _sys.path.insert(0, _rs_scr)
        try:
            import rvmsetupstatus as _rvm
            _projects = _rvm._load_projects()
            _active = [_p for _p in _projects
                       if str(_p.get("status", "") or "").lower() in _rvm._ACTIVE_STATUSES]
            if _active:
                # Check if projects.xlsx is older than stale threshold
                _proj_path_rs = RS_DATA / "projects.xlsx"
                _stale_pids = []
                if _proj_path_rs.exists():
                    try:
                        _age_rs = _time_rs.time() - _proj_path_rs.stat().st_mtime
                        if _age_rs > _stale_hrs_rs * 3600:
                            _stale_pids = [str(_p.get("pid", "")) for _p in _active]
                    except Exception:
                        pass
                if _stale_pids:
                    try:
                        _wb_upd = _xl_rs.load_workbook(str(_proj_path_rs))
                        _ws_upd = _wb_upd.active
                        _hdrs_upd = [str(_ws_upd.cell(1, c).value or "").strip().lower()
                                     for c in range(1, _ws_upd.max_column + 1)]
                        _st_col = (_hdrs_upd.index("status") + 1) if "status" in _hdrs_upd else None
                        _pid_col = (_hdrs_upd.index("pid") + 1) if "pid" in _hdrs_upd else 1
                        if _st_col:
                            for _rw_upd in _ws_upd.iter_rows(min_row=2):
                                if str(_rw_upd[_pid_col - 1].value or "") in _stale_pids:
                                    _cur = str(_rw_upd[_st_col - 1].value or "").lower()
                                    if _cur in _rvm._ACTIVE_STATUSES:
                                        _rw_upd[_st_col - 1].value = "Stale"
                            _wb_upd.save(str(_proj_path_rs))
                    except Exception:
                        pass
                else:
                    _rs_ensure_poller()
        except Exception:
            pass

    def _mdl_scheduler_tick():
        """Check _mdl_run_procs for completed runs and sync status to projects.xlsx."""
        import openpyxl as _xl_mds
        try:
            _path = MDL_DATA / "projects.xlsx"
            if not _path.exists():
                return
            with _mdl_run_lock:
                _finished = {run_id: st for run_id, st in _mdl_run_procs.items()
                             if st["status"] in ("done", "failed")}
            if not _finished:
                return
            wb = _xl_mds.load_workbook(str(_path))
            ws = wb.active
            hdrs = [str(ws.cell(1, c).value or "").strip().lower()
                    for c in range(1, ws.max_column + 1)]
            if "status" not in hdrs:
                return
            status_idx = hdrs.index("status")
            # We don't store run_id per row yet, so update any row still stuck at Running
            # whose process has clearly finished.
            _any_running = any(
                str(row[status_idx].value or "").strip().lower() == "running"
                for row in ws.iter_rows(min_row=2)
            )
            if not _any_running:
                return
            # If all tracked processes finished and some rows are still Running,
            # leave them — the script updates its own row on completion.
            # This tick's job is only cleanup for processes that ended silently.
            all_done = all(st["status"] in ("done", "failed")
                           for st in _mdl_run_procs.values()) if _mdl_run_procs else False
            if all_done and _mdl_run_procs:
                for row in ws.iter_rows(min_row=2):
                    if str(row[status_idx].value or "").strip().lower() == "running":
                        row[status_idx].value = "Stale"
                try:
                    wb.save(str(_path))
                except Exception:
                    pass
        except Exception:
            pass

    def _mdl_scheduler_loop():
        import time as _t_mds
        while True:
            with _mdl_sched_lock:
                interval = _mdl_sched_state.get("interval_s", 60)
            _t_mds.sleep(max(interval, 30))
            try:
                _mdl_scheduler_tick()
            except Exception:
                pass

    def _mdl_startup_recovery():
        """Read saved interval, ensure scheduler_config.xlsx exists, start scheduler."""
        interval_m = _mdl_read_interval()
        with _mdl_sched_lock:
            _mdl_sched_state["interval_s"] = interval_m * 60
        if not _MDL_SCHED_CFG.exists():
            _mdl_write_interval(interval_m)
        _threading.Thread(target=_mdl_scheduler_loop, daemon=True).start()

    def _rpb_startup_recovery():
        """On IDP restart: re-attach orphaned RPB runs using scheduler_config.xlsx settings."""
        import openpyxl as _xl_rpbs, json as _json_rpbs, time as _time_rpbs
        import threading as _thr_rpbs

        _rpb_sched_cfg = RPB_ROOT / "scheduler_config.xlsx"
        _poll_s    = 300
        _stale_hrs = 48
        _max_hrs   = 48
        if _rpb_sched_cfg.exists():
            try:
                _wb_rpbs = _xl_rpbs.load_workbook(str(_rpb_sched_cfg), data_only=True)
                for _r in _wb_rpbs.active.iter_rows(min_row=2, values_only=True):
                    _k = str(_r[0] or "").strip().lower()
                    _v = str(_r[1] or "").strip()
                    if _v:
                        if   _k == "poll_interval_s":        _poll_s    = max(30, int(_v))
                        elif _k == "stale_threshold_hours":  _stale_hrs = max(1,  int(_v))
                        elif _k == "max_poll_hours":         _max_hrs   = max(1,  int(_v))
                _wb_rpbs.close()
            except Exception:
                pass

        _rpb_proj_xlsx = RPB_DATA / "projects.xlsx"
        if not _rpb_proj_xlsx.exists():
            return

        # Collect in-progress rows from all app sheets
        _candidates = []   # (pid_int, app_name, payor_version, gp_enabled, created_at_str)
        try:
            _wb_p = _xl_rpbs.load_workbook(str(_rpb_proj_xlsx), read_only=True, data_only=True)
            for _sheet_name in _wb_p.sheetnames:
                _ws_p = _wb_p[_sheet_name]
                _h_p  = [str(c.value or "").strip().lower() for c in _ws_p[1]]
                for _r_p in _ws_p.iter_rows(min_row=2, values_only=True):
                    if not any(v is not None for v in _r_p):
                        continue
                    _rd = {_h_p[i]: (str(_r_p[i]) if _r_p[i] is not None else "")
                           for i in range(min(len(_h_p), len(_r_p)))}
                    if (_rd.get("status", "") == "In Progress"
                            and _rd.get("regression_status", "") == "In Progress"):
                        _pid_s = _rd.get("pid", "").strip()
                        if _pid_s.isdigit():
                            _candidates.append((
                                int(_pid_s),
                                _sheet_name,
                                _rd.get("payor_version", ""),
                                False,   # gp_enabled read from project xlsx below
                                _rd.get("created_at", ""),
                            ))
            _wb_p.close()
        except Exception:
            return

        def _rpb_recovery_thread_fn(pid, app, payor_version, gp_enabled):
            import subprocess as _sub_rec, os as _os_rec, sys as _sys_rec
            log_dir     = RPB_DATA / app / "logs"
            log_dir.mkdir(parents=True, exist_ok=True)
            log_path    = log_dir / f"{pid}_run.log"
            scripts_dir = RPB_ROOT / "projects" / app / "scripts"
            cwd         = str(RPB_ROOT / "projects" / app)
            env         = _os_rec.environ.copy()
            env["RPB_PID"] = str(pid)
            abort_event = _rpb_abort_events.get(pid)

            def _run(script, extra_args=None):
                if abort_event and abort_event.is_set():
                    return False
                cmd = ["node", str(scripts_dir / script)] + (extra_args or [])
                with open(str(log_path), "a", encoding="utf-8", errors="replace") as lf:
                    lf.write(f"\n{'='*60}\n Running: {script} {' '.join(extra_args or [])}\n{'='*60}\n")
                    lf.flush()
                    extra_cf = {"creationflags": 0x08000000} if _sys_rec.platform == "win32" else {}
                    proc = _sub_rec.Popen(cmd, cwd=cwd, env=env,
                                          stdout=lf, stderr=_sub_rec.STDOUT, **extra_cf)
                    with _rpb_threads_lock:
                        _rpb_cur_procs[pid] = proc
                    proc.wait()
                    with _rpb_threads_lock:
                        _rpb_cur_procs.pop(pid, None)
                if abort_event and abort_event.is_set():
                    return False
                return proc.returncode == 0

            try:
                with open(str(log_path), "a", encoding="utf-8", errors="replace") as lf:
                    lf.write(f"\n[RECOVERY] Re-attaching to remote run for project #{pid}...\n")
                ok4 = _run("step2_run_remote_its.js", ["--recover"])
                _run("step3_update_excel.js")
                _run("step4_generate_email.js")
                _rpb_update_status_in_xlsx(pid, app, regression_status="Completed" if ok4 else "Failed")
                if gp_enabled:
                    _rpb_update_status_in_xlsx(pid, app, gp_status="In Progress")
                    ok_gp = _run("gp_regression.js")
                    _rpb_update_status_in_xlsx(pid, app, gp_status="Completed" if ok_gp else "Failed")
                if abort_event and abort_event.is_set():
                    _rpb_update_status_in_xlsx(pid, app, status="Aborted")
                else:
                    _rpb_update_status_in_xlsx(pid, app, status="Completed" if ok4 else "Failed")
            except Exception as _e_rec:
                _rpb_update_status_in_xlsx(pid, app, status="Failed")
                with open(str(log_path), "a", encoding="utf-8", errors="replace") as lf:
                    lf.write(f"\n[RECOVERY ERROR] {_e_rec}\n")
            finally:
                with _rpb_threads_lock:
                    _rpb_abort_events.pop(pid, None)
                    _rpb_cur_procs.pop(pid, None)

        _now_rpbs = _time_rpbs.time()
        for _pid_i, _app_i, _ver_i, _, _created_i in _candidates:
            with _rpb_threads_lock:
                if _pid_i in _rpb_threads and _rpb_threads[_pid_i].is_alive():
                    continue

            # Stale check
            if _created_i:
                try:
                    from datetime import datetime as _dt_rpbs
                    _age = _now_rpbs - _dt_rpbs.strptime(_created_i, "%Y-%m-%d %H:%M:%S").timestamp()
                    if _age > _stale_hrs * 3600:
                        _rpb_update_status_in_xlsx(_pid_i, _app_i, status="Stale",
                                                   regression_status="Failed")
                        continue
                except Exception:
                    pass

            # Recovery file check
            _rec_file = RPB_DATA / _app_i / "logs" / f"{_pid_i}_recovery.json"
            if not _rec_file.exists():
                # step2 hadn't started or already completed — can't safely resume
                _rpb_update_status_in_xlsx(_pid_i, _app_i, status="Failed",
                                           regression_status="Failed")
                continue

            # Read gp_enabled from per-project xlsx
            _gp_i = False
            try:
                _urls_i = _rpb_read_urls(_pid_i, _app_i)
                _gp_i   = bool(_urls_i.get("gp_enabled", False))
            except Exception:
                pass

            _abort_ev_i = _thr_rpbs.Event()
            with _rpb_threads_lock:
                _rpb_abort_events[_pid_i] = _abort_ev_i
            _t_rec = _thr_rpbs.Thread(
                target=_rpb_recovery_thread_fn,
                args=(_pid_i, _app_i, _ver_i, _gp_i),
                daemon=True,
            )
            _t_rec.start()
            with _rpb_threads_lock:
                _rpb_threads[_pid_i]     = _t_rec
                _rpb_thread_apps[_pid_i] = _app_i

        # Periodic stale-check loop (marks runs stuck beyond max_poll_hours as Failed)
        def _rpb_stale_loop():
            while True:
                _time_rpbs.sleep(_poll_s)
                if not _rpb_proj_xlsx.exists():
                    continue
                try:
                    _wb_sl = _xl_rpbs.load_workbook(str(_rpb_proj_xlsx), read_only=True, data_only=True)
                    for _sn_sl in _wb_sl.sheetnames:
                        _ws_sl = _wb_sl[_sn_sl]
                        _h_sl  = [str(c.value or "").strip().lower() for c in _ws_sl[1]]
                        for _r_sl in _ws_sl.iter_rows(min_row=2, values_only=True):
                            _rd_sl = {_h_sl[i]: (str(_r_sl[i]) if _r_sl[i] is not None else "")
                                      for i in range(min(len(_h_sl), len(_r_sl)))}
                            if _rd_sl.get("status", "") != "In Progress":
                                continue
                            _p_sl = _rd_sl.get("pid", "").strip()
                            if not _p_sl.isdigit():
                                continue
                            _pid_sl = int(_p_sl)
                            with _rpb_threads_lock:
                                if _pid_sl in _rpb_threads and _rpb_threads[_pid_sl].is_alive():
                                    continue
                            _cr_sl = _rd_sl.get("created_at", "").strip()
                            if _cr_sl:
                                try:
                                    from datetime import datetime as _dt_sl
                                    _age_sl = _time_rpbs.time() - _dt_sl.strptime(
                                        _cr_sl, "%Y-%m-%d %H:%M:%S").timestamp()
                                    if _age_sl > _max_hrs * 3600:
                                        _rpb_update_status_in_xlsx(_pid_sl, _sn_sl,
                                                                   status="Stale",
                                                                   regression_status="Failed")
                                except Exception:
                                    pass
                    _wb_sl.close()
                except Exception:
                    pass

        _thr_rpbs.Thread(target=_rpb_stale_loop, daemon=True).start()

    _cw_startup_recovery()
    _jreg_startup_recovery()
    _jbaseline_startup_recovery()
    _jcj_startup_recovery()
    _rs_startup_recovery()
    _mdl_startup_recovery()
    _rpb_startup_recovery()

    # ── Setup endpoints ───────────────────────────────────────────────────────

    @app.route("/api/setup/version-managers")
    def api_setup_version_managers():
        """Detect SDKMAN (Java), pyenv (Python), NVM (JavaScript) and their installed versions."""
        home = Path.home()

        # Detection only READS files: opening this page must never start nvm / node / pyenv / go.
        def _subdirs(p):
            try:
                return sorted(d.name for d in p.iterdir() if d.is_dir() and d.name != "current") if p.is_dir() else []
            except OSError:
                return []

        def _target_name(p):
            """Name of the folder a link / junction points to (e.g. ...\\nodejs -> ...\\nvm\\v24.13.0 gives v24.13.0)."""
            try:
                return Path(os.path.realpath(str(p))).name if Path(p).exists() else ""
            except OSError:
                return ""

        def _ver_key(v):
            return [int(x) if x.isdigit() else 0 for x in _re_team.split(r"[.\D]+", v)]

        out = {}

        # SDKMAN is a bash tool: detect via its install dir (works with Git Bash / WSL-shared home)
        sd = Path(os.environ.get("SDKMAN_DIR") or (INSTALLED_SOFTWARES / "sdkman" if (INSTALLED_SOFTWARES / "sdkman").is_dir() else home / ".sdkman"))
        cur = sd / "candidates" / "java" / "current"
        out["sdkman"] = {
            "installed": sd.is_dir(), "path": str(sd) if sd.is_dir() else "",
            "version": (sd / "var" / "version").read_text().strip() if (sd / "var" / "version").is_file() else "",
            "versions": _subdirs(sd / "candidates" / "java"),
            "active": cur.resolve().name if cur.exists() else "",
        }

        # pyenv-win: ~/.pyenv/pyenv-win/{bin/pyenv.bat, version (global), versions/<x.y.z>}
        pw = (INSTALLED_SOFTWARES / "pyenv" / "pyenv-win") if (INSTALLED_SOFTWARES / "pyenv" / "pyenv-win").is_dir() else (home / ".pyenv" / "pyenv-win")
        pe = next((p for p in (str(pw / "bin" / "pyenv.bat"), shutil.which("pyenv")) if p and Path(p).exists()), "")
        gv = pw / "version"
        out["pyenv"] = {
            "installed": bool(pe), "path": pe, "version": "",
            "versions": sorted(_subdirs(pw / "versions"), key=_ver_key),
            "active": gv.read_text(errors="replace").strip().splitlines()[0] if gv.is_file() and gv.read_text(errors="replace").strip() else "",
        }

        # nvm-windows: %NVM_HOME%\{nvm.exe, v<x.y.z>\}; the active version is where the %NVM_SYMLINK% link (nodejs) points
        nvm_home = Path((INSTALLED_SOFTWARES / "nvm") if (INSTALLED_SOFTWARES / "nvm").is_dir() else (os.environ.get("NVM_HOME") or (home / "AppData" / "Roaming" / "nvm")))
        nvm_exe = nvm_home / "nvm.exe"
        nvv = sorted((d.name for d in nvm_home.glob("v*") if d.is_dir()), key=_ver_key) if nvm_home.is_dir() else []
        link = (INSTALLED_SOFTWARES / "nodejs") if (INSTALLED_SOFTWARES / "nvm").is_dir() else Path(os.environ.get("NVM_SYMLINK") or r"C:\Program Files\nodejs")
        out["nvm"] = {
            "installed": nvm_exe.is_file() or bool(nvv), "path": str(nvm_home) if (nvm_exe.is_file() or nvv) else "",
            "version": "", "versions": nvv, "active": _target_name(link) if link.exists() else "",
        }

        # Go: official golang.org/dl wrappers. Active version = the VERSION file of the Go that is on PATH (read, not executed)
        gobin = shutil.which("go")
        gact = ""
        if gobin:
            vf = Path(gobin).resolve().parent.parent / "VERSION"
            if vf.is_file():
                gact = vf.read_text(errors="replace").splitlines()[0].replace("go", "", 1).strip()
        out["go"] = {
            "installed": bool(gobin), "path": gobin or "", "version": gact,
            "versions": sorted((d.name[2:] for d in (home / "sdk").glob("go*") if d.is_dir()), key=_ver_key) if (home / "sdk").is_dir() else [],
            "active": gact,
        }
        return jsonify({"ok": True, "managers": out})

    _vm_jobs = {}

    def _vm_env():
        """Environment for version-manager commands: managers living in Installed_Softwares get their home variables."""
        e = dict(os.environ)
        if (INSTALLED_SOFTWARES / "sdkman").is_dir():
            e["SDKMAN_DIR"] = str(INSTALLED_SOFTWARES / "sdkman")
        if (INSTALLED_SOFTWARES / "pyenv").is_dir():
            e["PYENV"] = e["PYENV_ROOT"] = e["PYENV_HOME"] = str(INSTALLED_SOFTWARES / "pyenv" / "pyenv-win")
        if (INSTALLED_SOFTWARES / "nvm").is_dir():
            e["NVM_HOME"] = str(INSTALLED_SOFTWARES / "nvm")
            e["NVM_SYMLINK"] = str(INSTALLED_SOFTWARES / "nodejs")
        return e

    def _vm_command(mgr, action, ver):
        """Build the argv for a version-manager action, or (None, error)."""
        home = Path.home()
        if mgr == "sdkman":
            sd = Path(os.environ.get("SDKMAN_DIR") or (INSTALLED_SOFTWARES / "sdkman" if (INSTALLED_SOFTWARES / "sdkman").is_dir() else home / ".sdkman"))
            bash = shutil.which("bash") or r"C:\Program Files\Git\bin\bash.exe"
            if not Path(bash).exists():
                return None, "bash not found (install Git for Windows or WSL)"
            if not (sd / "bin" / "sdkman-init.sh").is_file():
                return None, "SDKMAN is not installed"
            verb = {"install": "install", "use": "default", "uninstall": "uninstall"}[action]
            script = 'source "$1/bin/sdkman-init.sh" && sdk %s java "$2" < /dev/null' % verb
            if action == "install":
                script = 'source "$1/bin/sdkman-init.sh" && yes n | sdk install java "$2"'
            return [bash, "-c", script, "_", sd.as_posix(), ver], None
        if mgr == "pyenv":
            pe = next((p for p in (shutil.which("pyenv"), str(INSTALLED_SOFTWARES / "pyenv" / "pyenv-win" / "bin" / "pyenv.bat"), str(home / ".pyenv" / "pyenv-win" / "bin" / "pyenv.bat")) if p and Path(p).exists()), "")
            if not pe:
                return None, "pyenv is not installed"
            return [pe] + {"install": ["install", ver], "use": ["global", ver], "uninstall": ["uninstall", "-f", ver]}[action], None
        if mgr == "nvm":
            nv = str(INSTALLED_SOFTWARES / "nvm" / "nvm.exe") if (INSTALLED_SOFTWARES / "nvm" / "nvm.exe").is_file() else shutil.which("nvm")
            if not nv:
                return None, "nvm is not installed"
            return [nv, action, ver], None
        if mgr == "go":
            if not shutil.which("go"):
                return None, "Go is not installed"
            return ["go", action, ver], None  # steps are expanded by _vm_go_steps
        return None, "Unknown manager"

    @app.route("/api/setup/version-managers/action", methods=["POST"])
    def api_setup_vm_action():
        import threading as _th, uuid as _uuid
        b = request.get_json(silent=True) or {}
        mgr, action, ver = b.get("manager", ""), b.get("action", ""), str(b.get("version", "")).strip()
        if action not in ("install", "use", "uninstall"):
            return jsonify({"ok": False, "error": "Invalid action"}), 400
        if not _re_team.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._+\-]*", ver):
            return jsonify({"ok": False, "error": "Invalid version"}), 400
        if mgr == "go" and not _re_team.fullmatch(r"\d+\.\d+(\.\d+)?((rc|beta)\d+)?", ver):
            return jsonify({"ok": False, "error": "Use a Go version like 1.22.0"}), 400
        cmd, err = _vm_command(mgr, action, ver)
        if err:
            return jsonify({"ok": False, "error": err}), 400
        key = _uuid.uuid4().hex[:10]
        job = _vm_jobs[key] = {"status": "running", "output": ""}

        def _stream(argv):
            job["output"] += "$ " + " ".join(argv) + "\n"
            p = subprocess.Popen(argv, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, errors="replace", env=_vm_env(), creationflags=0x08000000)
            for line in p.stdout:
                job["output"] += line
            p.wait()
            return p.returncode

        def _go_steps():
            home = Path.home()
            gv = "go" + ver
            gopath = (_run_go_env("GOPATH") or str(home / "go"))
            wrapper = str(Path(gopath) / "bin" / gv)
            if action == "install":
                return (_stream(["go", "install", "golang.org/dl/%s@latest" % gv]) == 0
                        and _stream([wrapper, "download"]) == 0)
            if action == "use":
                # Go has no global switch: show where this SDK lives and how to run it
                ok = _stream([wrapper, "version"]) == 0 and _stream([wrapper, "env", "GOROOT"]) == 0
                job["output"] += "\nRun `%s <cmd>` instead of `go <cmd>`, or point GOROOT/PATH at the path above.\n" % gv
                return ok
            sdk = home / "sdk" / gv
            if sdk.is_dir():
                shutil.rmtree(sdk, ignore_errors=True)
            for w in (Path(wrapper), Path(wrapper + ".exe")):
                if w.exists():
                    w.unlink()
            job["output"] += "Removed %s\n" % sdk
            return not sdk.exists()

        def _run_go_env(k):
            try:
                return subprocess.run(["go", "env", k], capture_output=True, text=True, timeout=15, creationflags=0x08000000).stdout.strip()
            except Exception:
                return ""

        def _go():
            try:
                if mgr == "go":
                    job["status"] = "success" if _go_steps() else "failed"
                    return
                job["output"] += "$ " + " ".join(cmd) + "\n"
                p = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, errors="replace", env=_vm_env(), creationflags=0x08000000)
                for line in p.stdout:
                    job["output"] += line
                p.wait()
                job["status"] = "success" if p.returncode == 0 else "failed"
            except Exception as e:
                job["output"] += str(e)
                job["status"] = "failed"
        _th.Thread(target=_go, daemon=True).start()
        return jsonify({"ok": True, "key": key})

