    _oracle_dl_state: dict = {}
    _oracle_dl_lock = _threading.Lock()

    @app.route("/api/setup/oracle-download", methods=["POST"])
    def api_setup_oracle_download():
        import subprocess as _sp, os as _os, shutil as _shutil, webbrowser as _wb
        from pathlib import Path as _Path
        data       = request.get_json() or {}
        dest_path  = str(data.get("dest_path", "")).strip()
        if not dest_path:
            return jsonify({"ok": False, "error": "dest_path required"})
        # Read download URL
        dl_url = ""
        try:
            _dl_file = SETUP_ROOT / "oracle_download.txt"
            if _dl_file.exists():
                for _ln in _dl_file.read_text(encoding="utf-8").splitlines():
                    if "=" in _ln:
                        dl_url = _ln.split("=", 1)[1].strip()
                        break
        except Exception:
            pass
        if not dl_url:
            return jsonify({"ok": False, "error": "No download URL configured"})
        key = "oracle_dl"
        with _oracle_dl_lock:
            if _oracle_dl_state.get(key, {}).get("status") == "running":
                return jsonify({"ok": False, "error": "Download already in progress"})
            _oracle_dl_state[key] = {"status": "running", "output": "Starting download…\n"}

        # Also delete any corrupt file from a previous attempt
        try:
            _corrupt = _Path(dest_path)
            if _corrupt.exists():
                _corrupt.unlink()
        except Exception:
            pass

        def _do_download():
            out = []
            def _upd(msg):
                out.append(msg)
                with _oracle_dl_lock:
                    _oracle_dl_state[key]["output"] = "".join(out)
            dest = _Path(dest_path)
            dest.parent.mkdir(parents=True, exist_ok=True)
            # SharePoint personal URLs require browser-based auth; open browser + watch Downloads
            _upd("Opening browser to download oracle tar (SharePoint requires your browser login).\n")
            _upd(f"Watching ~/Downloads for oraclearchve.tar.gz — the app will auto-move it once complete.\n\n")
            try:
                _wb.open(dl_url)
            except Exception:
                pass
            downloads = _Path(_os.path.expanduser("~")) / "Downloads"
            src_file  = downloads / "oraclearchve.tar.gz"
            import time as _time
            for _ in range(600):   # wait up to 10 min
                _time.sleep(1)
                if src_file.exists() and src_file.stat().st_size > 0:
                    _upd(f"Found {src_file}, moving to {dest_path}…\n")
                    try:
                        _shutil.move(str(src_file), dest_path)
                        _upd("Done.\n")
                        with _oracle_dl_lock:
                            _oracle_dl_state[key]["status"] = "success"
                    except Exception as mv_ex:
                        _upd(f"Move failed: {mv_ex}\n")
                        with _oracle_dl_lock:
                            _oracle_dl_state[key]["status"] = "failed"
                    return
            _upd("Timed out waiting for download.\n")
            with _oracle_dl_lock:
                _oracle_dl_state[key]["status"] = "failed"

        _threading.Thread(target=_do_download, daemon=True).start()
        return jsonify({"ok": True, "key": key})

